class FinalizeResponsePersistenceError(RuntimeError):
    """Provider returned, but the protected finalize artifact was not committed."""

    def __init__(self, message: str, *, response_content_hash: str = "") -> None:
        super().__init__(message)
        self.response_content_hash = str(response_content_hash or "")


def _finalize_endpoint_identity(endpoint: str) -> Tuple[str, str]:
    """Return an exact parsed hostname and a credential-free endpoint digest."""
    raw = str(endpoint or "").strip()
    parsed = urlsplit(raw)
    hostname = str(parsed.hostname or "").lower().rstrip(".")
    if not hostname:
        raise ValueError("Finalize provider endpoint requires a valid hostname")
    scheme = str(parsed.scheme or "https").lower()
    port = f":{parsed.port}" if parsed.port is not None else ""
    path = "/" + str(parsed.path or "").lstrip("/")
    normalized = f"{scheme}://{hostname}{port}{path.rstrip('/') or '/'}"
    return hostname, "sha256:" + hashlib.sha256(
        normalized.encode("utf-8")
    ).hexdigest()


def _finalize_provider_http_status(exc: BaseException) -> Optional[int]:
    """Read typed SDK/HTTP status fields without inspecting exception prose."""
    candidates = [
        getattr(exc, "status_code", None),
        getattr(exc, "http_status", None),
        getattr(getattr(exc, "response", None), "status_code", None),
    ]
    for value in candidates:
        if isinstance(value, bool):
            continue
        try:
            status = int(value)
        except (TypeError, ValueError):
            continue
        if 100 <= status <= 599:
            return status
    return None


def _classify_finalize_provider_exception(
    exc: BaseException,
    *,
    idempotency_supported: bool,
) -> Dict[str, Any]:
    """Classify provider delivery from typed exception/status evidence only."""
    if isinstance(exc, (TimeoutError, asyncio.TimeoutError)):
        return {
            "provider_status": "outcome_unknown",
            "error_code": "FINALIZE_PROVIDER_OUTCOME_UNKNOWN",
            "error_owner": "controller_provider",
            "retry_safe": False,
        }
    if isinstance(exc, (PermissionError, TypeError, ValueError)):
        return {
            "provider_status": "fatal_failed",
            "error_code": "FINALIZE_PROVIDER_FATAL",
            "error_owner": "provider",
            "retry_safe": False,
        }

    status = _finalize_provider_http_status(exc)
    definite_retryable_rejections = {408, 409, 425, 429}
    if status in definite_retryable_rejections:
        if not idempotency_supported:
            return {
                "provider_status": "outcome_unknown",
                "error_code": "FINALIZE_PROVIDER_OUTCOME_UNKNOWN",
                "error_owner": "controller_provider",
                "retry_safe": False,
            }
        return {
            "provider_status": "transient_failed",
            "error_code": "FINALIZE_PROVIDER_TRANSIENT",
            "error_owner": "provider",
            "retry_safe": True,
        }
    if status is not None:
        if status >= 500 and idempotency_supported:
            return {
                "provider_status": "transient_failed",
                "error_code": "FINALIZE_PROVIDER_TRANSIENT",
                "error_owner": "provider",
                "retry_safe": True,
            }
        if status >= 500:
            return {
                "provider_status": "outcome_unknown",
                "error_code": "FINALIZE_PROVIDER_OUTCOME_UNKNOWN",
                "error_owner": "controller_provider",
                "retry_safe": False,
            }
        return {
            "provider_status": "fatal_failed",
            "error_code": "FINALIZE_PROVIDER_FATAL",
            "error_owner": "provider",
            "retry_safe": False,
        }

    if isinstance(exc, ConnectionRefusedError):
        return {
            "provider_status": "transient_failed",
            "error_code": "FINALIZE_PROVIDER_TRANSIENT",
            "error_owner": "provider",
            "retry_safe": True,
        }
    if isinstance(exc, (ConnectionError, OSError)):
        if idempotency_supported:
            return {
                "provider_status": "transient_failed",
                "error_code": "FINALIZE_PROVIDER_TRANSIENT",
                "error_owner": "provider",
                "retry_safe": True,
            }
        return {
            "provider_status": "outcome_unknown",
            "error_code": "FINALIZE_PROVIDER_OUTCOME_UNKNOWN",
            "error_owner": "controller_provider",
            "retry_safe": False,
        }
    return {
        "provider_status": "outcome_unknown",
        "error_code": "FINALIZE_PROVIDER_OUTCOME_UNKNOWN",
        "error_owner": "controller_provider",
        "retry_safe": False,
    }


def _finalize_message_wire_rows(messages: Sequence[BaseMessage]) -> List[Dict[str, str]]:
    """Convert the isolated FINALIZE request to exact Chat Completions rows."""
    rows: List[Dict[str, str]] = []
    for message in messages:
        role = str(getattr(message, "type", "") or "").lower()
        if role == "human":
            role = "user"
        elif role == "ai":
            role = "assistant"
        if role not in {"system", "user", "assistant"}:
            raise ValueError(f"Unsupported FINALIZE wire role: {role or type(message).__name__}")
        content = getattr(message, "content", "")
        if not isinstance(content, str):
            raise TypeError("FINALIZE wire messages require exact string content")
        rows.append({"role": role, "content": content})
    if [row["role"] for row in rows] != ["system", "user"]:
        raise ValueError("New FINALIZE requests require exactly system,user roles")
    return rows


def _build_finalize_wire_payload(
    messages: Sequence[BaseMessage],
    settings: Mapping[str, Any],
) -> Dict[str, Any]:
    """Build the provider body without allowing a generic max-token rewrite."""
    provider_id = str(settings.get("provider_id") or "").lower()
    output_tokens = int(settings.get("max_output_tokens") or 0)
    if output_tokens <= 0:
        raise ValueError("FINALIZE output token cap must be a positive integer")
    token_parameter = str(settings.get("output_token_parameter") or "")
    if provider_id == "deepseek":
        token_parameter = token_parameter or "max_tokens"
        if token_parameter != "max_tokens":
            raise ValueError(
                "FINALIZE_PROVIDER_PARAMETER_UNSUPPORTED: DeepSeek requires max_tokens"
            )
    else:
        token_parameter = token_parameter or "max_tokens"
    body: Dict[str, Any] = {
        "model": str(settings.get("model") or ""),
        "messages": _finalize_message_wire_rows(messages),
        "temperature": float(settings.get("temperature") or 0.0),
        "top_p": float(settings.get("top_p") or 1.0),
        token_parameter: output_tokens,
        "stream": False,
    }
    response_format = settings.get("response_format")
    if isinstance(response_format, Mapping):
        body["response_format"] = deepcopy(dict(response_format))
    extra_body = settings.get("extra_body_allowlist")
    if isinstance(extra_body, Mapping) and extra_body:
        # ``openai`` merges extra_body into the serialized JSON. Keep it
        # separate in the SDK call but bind its keys into the wire digest below.
        body["extra_body"] = deepcopy(dict(extra_body))
    if not body["model"]:
        raise ValueError("FINALIZE provider model is required")
    if provider_id == "deepseek" and (
        "max_tokens" not in body or "max_completion_tokens" in body
    ):
        raise ValueError(
            "FINALIZE_PROVIDER_PARAMETER_UNSUPPORTED: effective DeepSeek payload is miswired"
        )
    return body


def _finalize_effective_wire_projection(
    payload: Mapping[str, Any],
    settings: Mapping[str, Any],
) -> Dict[str, Any]:
    """Return a credential-free projection of the exact SDK call arguments."""
    provider_id = str(settings.get("provider_id") or "").lower()
    token_key = "max_tokens" if "max_tokens" in payload else (
        "max_completion_tokens" if "max_completion_tokens" in payload else ""
    )
    semantic_body = deepcopy(dict(payload))
    body_hash = hashlib.sha256(
        json.dumps(
            semantic_body,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")
    ).hexdigest()
    return {
        "record_type": "finalize_effective_wire_settings",
        "api_surface": "chat_completions",
        "provider_id": provider_id,
        "model": str(payload.get("model") or ""),
        "stream": bool(payload.get("stream")),
        "response_format": deepcopy(payload.get("response_format")),
        "thinking": str(settings.get("thinking") or "disabled"),
        "output_token_parameter": token_key,
        "output_token_value": int(payload.get(token_key) or 0) if token_key else 0,
        "payload_key_set": sorted(str(key) for key in payload),
        "payload_digest": body_hash,
        "max_completion_tokens_present": "max_completion_tokens" in payload,
        "max_tokens_present": "max_tokens" in payload,
    }


def _finalize_completion_projection(completion: Any) -> Dict[str, Any]:
    """Extract raw content, finish reason, IDs and usage from an SDK object."""
    choices = list(getattr(completion, "choices", None) or [])
    first = choices[0] if choices else None
    message = getattr(first, "message", None)
    content = getattr(message, "content", "") if message is not None else ""
    raw_response = content if isinstance(content, str) else ""
    finish_reason = str(getattr(first, "finish_reason", "") or "")
    usage_obj = getattr(completion, "usage", None)
    usage: Dict[str, Any] = {}
    if usage_obj is not None:
        for source, target in (
            ("prompt_tokens", "prompt_tokens"),
            ("completion_tokens", "completion_tokens"),
            ("total_tokens", "total_tokens"),
        ):
            value = getattr(usage_obj, source, None)
            if value is not None:
                usage[target] = int(value)
    return {
        "raw_response": raw_response,
        "finish_reason": finish_reason,
        "usage": usage,
        "provider_metadata": {
            "response_id": str(getattr(completion, "id", "") or ""),
            "model": str(getattr(completion, "model", "") or ""),
            "finish_reason": finish_reason,
            "usage": usage,
        },
    }


def _finalize_exception_completion(exc: BaseException) -> Optional[Any]:
    """Return an SDK-delivered completion carried by a typed exception."""
    completion = getattr(exc, "completion", None)
    if completion is not None:
        return completion
    return None

SUPERVISOR_RETRY_FIELDS = (
    "retry_reason",
    "failed_step_id",
    "failure_fingerprint",
    "failure_owner",
    "required_next_action",
    "recovery_scope",
    "evidence_status",
)


def missing_supervisor_retry_fields(state: Dict[str, Any]) -> List[str]:
    """Return missing fields from the Supervisor -> Recovery contract."""
    if str((state or {}).get("supervisor_verdict") or "").upper() != "RETRY":
        return []
    return [key for key in SUPERVISOR_RETRY_FIELDS if not str((state or {}).get(key) or "").strip()]


@dataclass(frozen=True)
class InteractiveRunResult:
    """Structured terminal projection rendered before the next prompt."""

    task_id: str
    status: str
    stage: str = ""
    failure_code: str = ""
    reason: str = ""
    result_path: str = ""
    trace_path: str = ""


# ════════════════════════════════════════════════════════════════
#  1.  统一输出路由器（消除重复打印）
# ════════════════════════════════════════════════════════════════

class OutputRouter:
    """
    所有终端打印通过此类，通过 _seen 集合去重，
    避免同一内容在 streaming 和事件循环中被打印两次。
    """
    def __init__(self):
        self._seen: set = set()
        self._last_node: str = ""
        self._console_lock = threading.RLock()
        self.pager_line_threshold = int(os.getenv("BIOMIND_PAGER_LINES", "35"))
        self.preview_lines = int(os.getenv("BIOMIND_PREVIEW_LINES", "20"))
        self.viewer_height = int(os.getenv("BIOMIND_VIEWER_HEIGHT", "15"))
        self.viewer_mode = os.getenv("BIOMIND_VIEWER_MODE", "inline").lower()

    def _pager_enabled(self) -> bool:
        if os.getenv("BIOMIND_PAGER", "1").lower() in {"0", "false", "no", "off"}:
            return False
        return bool(sys.stdin.isatty() and sys.stdout.isatty())

    def _inline_window_viewer(self, title: str, text: str) -> bool:
        """Show a fixed-height scroll window directly in the current terminal page."""
        if not sys.stdin.isatty() or not sys.stdout.isatty():
            return False

        lines = text.splitlines() or [""]
        height = max(5, self.viewer_height)
        width = shutil.get_terminal_size((100, 24)).columns
        width = max(40, width)
        top = 0
        previous_block_lines = 0

        def visible_width_slice(s: str, limit: int) -> str:
            # Good enough for terminal logs: keep ANSI-less content stable.
            return s[:limit]

        def render() -> int:
            nonlocal top
            content_h = height
            max_top = max(0, len(lines) - content_h)
            top = min(max(top, 0), max_top)
            body_width = width - 2
            header = f" {title} " if title else " Scroll View "
            status = (
                f" {top + 1}-{min(top + content_h, len(lines))}/{len(lines)}  "
                "VIEW ONLY: n/j next  p/k prev  q/Enter return (approval follows) "
            )

            block = []
            block.append("┌" + "─" * body_width + "┐")
            block.append("│" + visible_width_slice(header, body_width).ljust(body_width) + "│")
            block.append("├" + "─" * body_width + "┤")
            for idx in range(content_h):
                line = lines[top + idx] if top + idx < len(lines) else ""
                block.append("│" + visible_width_slice(line, body_width).ljust(body_width) + "│")
            block.append("├" + "─" * body_width + "┤")
            block.append("│" + visible_width_slice(status, body_width).ljust(body_width) + "│")
            block.append("└" + "─" * body_width + "┘")
            print("\n".join(block))
            return len(block)

        try:
            while True:
                if previous_block_lines:
                    # Move cursor back above the previous block + prompt, then clear.
                    print(f"\x1b[{previous_block_lines + 1}A\x1b[J", end="")
                previous_block_lines = render()
                # A previous subprocess or terminal UI can leave ISIG/ICANON
                # disabled. Restore normal TTY semantics before waiting so
                # Ctrl-C/Ctrl-Z are signals instead of literal ``^C``/``^Z``.
                restore_terminal_state()
                cmd = safe_input(
                    "Scroll only (Enter/q/y=continue to approval) > ",
                    timeout_seconds=resolve_input_timeout(300),
                    history=False,
                ).strip().lower()
                if cmd in {"", "q", "quit", "exit", "y", "yes"}:
                    break
                if cmd in {"n", "next", "j", "down", "d", " "}: 
                    top += height
                elif cmd in {"p", "prev", "previous", "k", "up", "u"}:
                    top -= height
                elif cmd in {"g", "home"}:
                    top = 0
                elif cmd in {"end", "bottom"}:
                    top = max(0, len(lines) - height)
                else:
                    try:
                        top = int(cmd) - 1
                    except ValueError:
                        pass
            return True
        except KeyboardInterrupt:
            restore_terminal_state()
            raise
        except (EOFError, HumanInputUnavailable):
            restore_terminal_state()
            return True

    def _preview_text(self, title: str, text: str, color: str = ""):
        lines = text.splitlines()
        shown = "\n".join(lines[:self.preview_lines])
        suffix = ""
        if len(lines) > self.preview_lines:
            suffix = f"\n... [{len(lines) - self.preview_lines} more lines; set BIOMIND_PAGER=1 in a TTY to scroll]"
        header = f"\n{title}\n" if title else ""
        body = f"{header}{shown}{suffix}"
        print(f"{color}{body}{Style.RESET_ALL}" if color else body)

    def page_text(self, title: str, text: str, color: str = "", force: bool = False):
        """Display long text in a scrollable terminal pager when available."""
        text = text.rstrip("\n")
        line_count = len(text.splitlines())
        if not text:
            return
        if not force and line_count <= self.pager_line_threshold:
            header = f"\n{title}\n" if title else ""
            body = header + text
            print(f"{color}{body}{Style.RESET_ALL}" if color else body)
            return
        if not self._pager_enabled():
            self._preview_text(title, text, color)
            return

        if self.viewer_mode == "inline" and self._inline_window_viewer(title, text):
            return

        if not shutil.which("less"):
            self._preview_text(title, text, color)
            return

        fd, path = tempfile.mkstemp(prefix="biomind_view_", suffix=".txt")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                if title:
                    f.write(title.rstrip() + "\n")
                    f.write("=" * min(80, max(20, len(title))) + "\n\n")
                f.write(text)
                f.write("\n")
            print(f"{Fore.CYAN}↕ Opening scroll view ({line_count} lines). Use ↑/↓/PgUp/PgDn, q to return.{Style.RESET_ALL}")
            subprocess.run(["less", "-R", "-S", path])
        finally:
            try:
                os.remove(path)
            except OSError:
                pass

    def print_node_header(self, node: str):
        with self._console_lock:
            if node != self._last_node:
                self._last_node = node
                icons = {
                    "triage": "🔀", "direct_chat": "💬",
                    "consultant": "🧠", "planner": "📋", "plan_review": "👁️",
                    "generate": "⚙️ ", "execute": "▶️ ", "supervisor": "🔬",
                    "install_subagent": "🔧", "finish": "🏁",
                }
                icon = icons.get(node, "•")
                print(f"\n{Fore.CYAN}{'─'*55}")
                print(f"  {icon}  NODE: {node.upper()}")
                print(f"{'─'*55}{Style.RESET_ALL}")

    def print_once(self, key: str, text: str, color: str = ""):
        """相同 key 只打印一次"""
        with self._console_lock:
            if key in self._seen:
                return
            self._seen.add(key)
            print(f"{color}{text}{Style.RESET_ALL}" if color else text)

    def render_terminal_result(self, result: InteractiveRunResult) -> bool:
        """Render one atomic terminal block; return whether it was emitted."""
        if str(result.status or "") == "waiting_user":
            return False
        key = f"terminal_result:{result.task_id}:{result.status}:{result.failure_code}"
        with self._console_lock:
            if key in self._seen:
                return False
            self._seen.add(key)
            color = (
                Fore.GREEN
                if result.status == "completed"
                else Fore.YELLOW
                if result.status in {"cancelled", "interrupted"}
                else Fore.RED
            )
            lines = [
                "Terminal result",
                f"  Status: {result.status or 'unknown'}",
                f"  Stage: {result.stage or '-'}",
                f"  Failure code: {result.failure_code or '-'}",
                f"  Reason: {result.reason or '-'}",
                f"  Result path: {result.result_path or '-'}",
                f"  Trace path: {result.trace_path or '-'}",
            ]
            print(f"\n{color}" + "\n".join(lines) + Style.RESET_ALL, flush=True)
            return True

    def print_ai(self, content: str):
        """打印 AI 消息（过滤代码块和标签）"""
        # 不打印纯代码块（由 execute 节点负责展示）
        if any(
            tag in str(content or "").lower()
            for tag in ("<execute>", "<install_tool", "<shell>", "<python>", "<r>")
        ):
            return
        clean = str(content or "")
        # Drop known machine-only payloads, but preserve the text enclosed by
        # status wrappers such as <llm_retryable_pause>.  Removing every
        # generic tagged block made real timeout/failure messages invisible.
        for tag in ("observation", "validation_result", "runtime_status"):
            clean = re.sub(
                rf"<{tag}\b[^>]*>.*?</{tag}>",
                "",
                clean,
                flags=re.IGNORECASE | re.DOTALL,
            )
        clean = re.sub(r"</?[^>]+>", "", clean).strip()
        clean = re.sub(r"```.*?```", "[code block]", clean, flags=re.DOTALL)
        if clean:
            key = clean[:80]
            if key not in self._seen:
                self._seen.add(key)
                self.page_text("🤖 AI Message", clean, Fore.WHITE)

    def print_observation(self, content: str):
        """打印执行结果（只打印一次）"""
        clean = content.replace("<observation>", "").replace("</observation>", "").strip()
        key = f"obs:{clean[:60]}"
        if key not in self._seen:
            self._seen.add(key)
            color = Fore.GREEN if "✅" in clean else Fore.RED
            print(f"\n{color}{'─'*50}")
            self.page_text("Execution Output", clean, color)
            print(f"{'─'*50}{Style.RESET_ALL}")

    def reset_for_task(self):
        with self._console_lock:
            self._seen.clear()
            self._last_node = ""


output = OutputRouter()
atexit.register(shutdown_observation_writers)


# ════════════════════════════════════════════════════════════════
#  2.  思考流式处理器
# ════════════════════════════════════════════════════════════════

class VibeThinkingHandler(BaseCallbackHandler):
    def __init__(self):
        self.is_thinking = False

    def on_llm_new_token(self, token: str, **kwargs) -> None:
        chunk = kwargs.get("chunk")
        reasoning = ""
        if chunk and hasattr(chunk, "additional_kwargs"):
            reasoning = chunk.additional_kwargs.get("reasoning_content", "")

        if reasoning:
            if not self.is_thinking:
                print(f"\n{Fore.LIGHTBLACK_EX}🧠 [Thinking...]{Style.RESET_ALL}", end="")
                self.is_thinking = True
            print(f"{Fore.LIGHTBLACK_EX}{reasoning}{Style.RESET_ALL}", end="", flush=True)
        elif token:
            if self.is_thinking:
                print(f"\n{Fore.GREEN}💡 [Done thinking]{Style.RESET_ALL}\n", end="")
                self.is_thinking = False
            # 不在这里打印，由 OutputRouter 统一处理


