@dataclass(frozen=True)
class StructuredActionParseResult:
    """Successful action plus bounded machine diagnostics for failed parsing."""

    action: Dict[str, Any] = field(default_factory=dict)
    error: Dict[str, Any] = field(default_factory=dict)
    candidate: Any = None
    raw_candidate: str = ""

    @property
    def succeeded(self) -> bool:
        return bool(self.action)


class BioAnalystAgent:
    @staticmethod
    def _resolve_runtime_memory_dir(data_path: str) -> Path:
        configured = Path(BIOMIND_MEMORY_DIR).expanduser() if BIOMIND_MEMORY_DIR else None
        if configured:
            if not configured.is_absolute():
                configured = PathManager.SYSTEM_ROOT / configured
            return configured.resolve()
        return (PathManager.SYSTEM_ROOT / ".biomind" / "memory").resolve()

    @staticmethod
    def _copy_runtime_memory_if_missing(source_dir: str | Path, target_dir: str | Path) -> int:
        source = Path(source_dir).resolve()
        target = Path(target_dir).resolve()
        if source == target or not source.exists() or not source.is_dir():
            return 0
        copied = 0
        for source_file in source.rglob("*"):
            if not source_file.is_file():
                continue
            dest = target / source_file.relative_to(source)
            if dest.exists():
                continue
            dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(source_file, dest)
            copied += 1
        return copied

    def __init__(
        self,
        data_path: str = str(PathManager.WORK_DIR),
        llm_model: str = LLM_DEFAULT_MODEL,
        model_provider: str = "openai",
        enable_persistence: bool = True,
        max_memory_tokens: int = 200_000,
        use_llm_supervisor: bool = True,
    ):
        self.data_path = data_path
        self.profiler = RunProfiler(output_root=Path(data_path) / "task_outputs")
        self.input_timeout_seconds = resolve_input_timeout()
        self.llm_timeout_seconds = LLM_TIMEOUT_SECONDS
        self.llm_readonly_timeout_seconds = min(
            LLM_READONLY_TIMEOUT_SECONDS,
            self.llm_timeout_seconds,
        )
        self.llm_max_retries = LLM_MAX_RETRIES
        self.llm_total_timeout_seconds = LLM_TOTAL_TIMEOUT_SECONDS
        self.llm_first_chunk_timeout_seconds = LLM_FIRST_CHUNK_TIMEOUT_SECONDS
        self.llm_stream_idle_timeout_seconds = LLM_STREAM_IDLE_TIMEOUT_SECONDS
        self.llm_cancel_cleanup_timeout_seconds = LLM_CANCEL_CLEANUP_TIMEOUT_SECONDS
        self.generate_provider_max_attempts = GENERATE_PROVIDER_MAX_ATTEMPTS
        self.generate_provider_retry_base_seconds = GENERATE_PROVIDER_RETRY_BASE_SECONDS
        self.generate_provider_retry_cap_seconds = GENERATE_PROVIDER_RETRY_CAP_SECONDS
        self.generate_llm_sdk_max_retries = 0
        self.generate_completion_cache_enabled = False
        self.llm_context_limit_tokens = max(1, int(max_memory_tokens))
        self._provider_attempt_history: Dict[str, List[Dict[str, Any]]] = {}

        # ── PackageManager ────────────────────────────────────
        try:
            self.pm = PackageManager(work_dir=data_path)
        except ImportError:
            logger.warning("PackageManager not found.")
            self.pm = None

        # ── LLM ──────────────────────────────────────────────
        self.llm_provider_is_deepseek = _is_deepseek_target(
            llm_model, LLM_BASE_URL
        )
        llm_kwargs: dict[str, Any] = {
            "model": llm_model,
            "model_provider": model_provider,
            "base_url": LLM_BASE_URL,
            "streaming": True,
            "api_key": LLM_API_KEY,
            "callbacks": [VibeThinkingHandler(), ProfilingCallbackHandler(self.profiler)],
            "timeout": self.llm_timeout_seconds,
            "max_retries": self.llm_max_retries,
        }
        llm_kwargs["temperature"] = (
            float(DEEPSEEK_TEMPERATURE)
            if self.llm_provider_is_deepseek
            else 0.7
        )
        extra_body = _llm_extra_body(llm_model, LLM_BASE_URL)
        if extra_body:
            llm_kwargs["extra_body"] = extra_body
        # Persist the effective, credential-free response settings separately
        # from the provider client.  Consultant FINALIZE hashes this allowlist
        # so checkpoint replay cannot confuse materially different requests.
        self.llm_model_id = str(llm_model)
        self.llm_provider_id = str(model_provider)
        self.llm_endpoint_id = str(LLM_BASE_URL)
        self.llm_response_extra_body = deepcopy(extra_body)
        self.llm = init_chat_model(**llm_kwargs)
        if self.llm_provider_is_deepseek:
            self.llm = enable_deepseek_reasoning_stream(self.llm)
        self.llm_reasoning_stream_adapter_active = (
            deepseek_reasoning_stream_enabled(self.llm)
        )
        generate_transport_llm = init_chat_model(
            **generate_client_kwargs(llm_kwargs)
        )
        if self.llm_provider_is_deepseek:
            generate_transport_llm = enable_deepseek_reasoning_stream(
                generate_transport_llm
            )
        self.generate_llm, self.generate_llm_policy = bind_generate_llm(
            generate_transport_llm,
            model=llm_model,
            base_url=LLM_BASE_URL,
        )
        self.generate_llm_policy = {
            **dict(self.generate_llm_policy or {}),
            "sdk_max_retries": self.generate_llm_sdk_max_retries,
            "completion_cache_enabled": self.generate_completion_cache_enabled,
            "application_max_attempts": self.generate_provider_max_attempts,
        }
        self.recovery_llm, self.recovery_llm_policy = bind_recovery_llm(
            self.llm,
            model=llm_model,
            base_url=LLM_BASE_URL,
        )
        (
            self.consultant_reasoning_llm,
            self.consultant_reasoning_llm_policy,
        ) = bind_consultant_reasoning_llm(
            self.llm,
            model=llm_model,
            base_url=LLM_BASE_URL,
        )
        (
            self.planner_correction_llm,
            self.planner_correction_llm_policy,
        ) = bind_planner_correction_llm(
            self.llm,
            model=llm_model,
            base_url=LLM_BASE_URL,
        )
        logger.info(
            "LLM request policy: timeout=%ss readonly_timeout=%ss max_retries=%s",
            self.llm_timeout_seconds,
            self.llm_readonly_timeout_seconds,
            self.llm_max_retries,
        )
        if self.llm_provider_is_deepseek:
            logger.info(
                "DeepSeek reasoning stream adapter: enabled=%s",
                self.llm_reasoning_stream_adapter_active,
            )

        # ── 验证 & 确认 ───────────────────────────────────────
        self.validator = ResultValidator()
        self.confirmation_manager = ConfirmationManager(
            ConfirmationConfig(
                auto_approve_safe=True,
                show_code_preview=True,
                timeout_seconds=self.input_timeout_seconds,
            )
        )
        self.middleware = HITLMiddleware(auto_approve_safe=True)

        # ── 持久化 ────────────────────────────────────────────
        self.state_manager = None
        if enable_persistence:
            self.state_manager = PersistentStateManager(
                db_path=str(PathManager.SYSTEM_DB_PATH),
                output_dir=str(PathManager.DEFAULT_OUTPUT_DIR),
            )
        self.artifact_index = ArtifactIndex(PathManager.SYSTEM_DB_PATH) if enable_persistence else None

        # ── RAG ───────────────────────────────────────────────
        self.retriever = None
        if RAGFLOW_API_KEY:
            try:
                self.retriever = RAGFlowRetriever(
                    api_key=RAGFLOW_API_KEY,
                    base_url=RAGFLOW_ADDRESS,
                    dataset_ids=[],
                    rerank_id=RERANK_MODEL_ID,
                )
            except Exception as e:
                logger.warning(f"RAG init failed: {e}")

        # ── MemoryManager（新）────────────────────────────────
        self.runtime_memory_dir = self._resolve_runtime_memory_dir(data_path)
        self.runtime_root = self.runtime_memory_dir.parent
        migrated = WikiMemoryManager.migrate_legacy_runtime_memory(
            Path(data_path) / "memory",
            self.runtime_memory_dir,
        )
        if migrated:
            logger.info("Migrated legacy runtime memory files into %s", self.runtime_memory_dir)
        migrated_current_memory = self._copy_runtime_memory_if_missing(
            Path(data_path) / ".biomind" / "memory",
            self.runtime_memory_dir,
        )
        if migrated_current_memory:
            logger.info(
                "Copied %s runtime memory file(s) from working directory into fixed memory dir %s",
                migrated_current_memory,
                self.runtime_memory_dir,
            )
        self.wiki_enabled = bool(BIOMIND_WIKI_ENABLED)
        self.configured_wiki_dir: Optional[Path] = None
        if self.wiki_enabled and BIOMIND_WIKI_DIR:
            configured = Path(BIOMIND_WIKI_DIR).expanduser()
            if not configured.is_absolute():
                configured = self.runtime_memory_dir / configured
            self.configured_wiki_dir = configured.resolve()
            migrated_wiki = WikiMemoryManager.migrate_wiki_pages(
                self.runtime_memory_dir / "wiki",
                self.configured_wiki_dir,
            )
            if migrated_wiki:
                logger.info(
                    "Migrated %s wiki file(s) into configured wiki dir %s",
                    len(migrated_wiki),
                    self.configured_wiki_dir,
                )

        archive_dir = self.runtime_root / "memory_archives"
        self.memory_manager = MemoryManager(
            llm=self.llm,
            archive_dir=str(archive_dir),
            max_tokens=max_memory_tokens,
        )
        self.default_project_id = DEFAULT_PROJECT_ID
        self.core_memory_store = CoreMemoryStore(
            memory_dir=self.runtime_memory_dir,
            default_project_id=self.default_project_id,
        )
        self.session_archive = SessionArchive(
            db_path=self.runtime_memory_dir / "session_archive.sqlite3",
        )
        self.session_archive_writer = acquire_observation_writer(
            self.session_archive.db_path,
            capacity=SESSION_ARCHIVE_OBSERVATION_QUEUE_SIZE,
            busy_timeout_seconds=SESSION_ARCHIVE_WRITER_BUSY_TIMEOUT_SECONDS,
            max_write_attempts=SESSION_ARCHIVE_WRITER_MAX_ATTEMPTS,
            backoff_seconds=SESSION_ARCHIVE_WRITER_BACKOFF_SECONDS,
            shutdown_drain_seconds=SESSION_ARCHIVE_SHUTDOWN_DRAIN_SECONDS,
        )
        self._session_archive_writer_released = False
        self._stable_prompt_cache: Dict[str, Dict[str, str]] = {}
        self._stable_prompt_dir = self.runtime_memory_dir / "session_prompts"
        self._latest_llm_call_refs: Dict[str, List[Dict[str, Any]]] = {}
        self._node_invocations = InvocationRegistry(
            max_entries=512,
            max_stale_signatures=512,
        )
        if self.wiki_enabled:
            self.wiki_memory_manager = WikiMemoryManager(
                llm=self.llm,
                memory_dir=self.runtime_memory_dir,
                default_project_id=self.default_project_id,
                wiki_dir=self.configured_wiki_dir,
                embedding_config={
                    "enabled": WIKI_EMBEDDING_ENABLED,
                    "base_url": WIKI_EMBEDDING_BASE_URL,
                    "api_key": WIKI_EMBEDDING_API_KEY,
                    "model": WIKI_EMBEDDING_MODEL,
                    "dimensions": WIKI_EMBEDDING_DIMENSIONS,
                },
            )
        else:
            self.wiki_memory_manager = NullWikiMemoryManager(default_project_id=self.default_project_id)
        self.task_summary_renderer = TaskSummaryRenderer(
            memory_dir=self.runtime_memory_dir,
            session_archive=self.session_archive,
            wiki_memory_manager=self.wiki_memory_manager,
        )
        self._wiki_digest_cache: Dict[str, Tuple[float, str]] = {}
        self.wiki_ingest_mode = BIOMIND_WIKI_INGEST_MODE if self.wiki_enabled else "disabled"
        self._wiki_ingest_offer_done: set[str] = set()
        self._wiki_auto_ingest_done: set[str] = set()

        # ── SupervisorNode（新）───────────────────────────────
        self.supervisor_node = SupervisorNode(
            llm=self.llm,
            output_dir=os.path.join(data_path, "task_outputs"),
            max_retries=2,
            use_llm_review=use_llm_supervisor,
        )
        self._install_env_choices: Dict[str, str] = {}
        self._install_attempt_counts: Dict[str, int] = {}
        self._install_scope_attempt_counts: Dict[str, int] = {}
        self.runtime_status: Dict[str, Dict[str, Dict[str, Any]]] = {}

        # ── 子智能体 ──────────────────────────────────────────
        _installer = InstallerAgent(self.llm, work_dir=data_path, package_manager=self.pm)
        self.installer_app = _installer.get_graph()

        # ── SkillManager ──────────────────────────────────────
        try:
            from config.config import SKILLS_DIR
            self.skill_manager = SkillManager(SKILLS_DIR)
        except Exception:
            self.skill_manager = None
        self.skill_access_service = (
            SkillAccessService(self.skill_manager)
            if self.skill_manager is not None
            else None
        )
        self._sync_runtime_registries_at_startup()
        self.workflow_manager = WorkflowManager(str(Path(__file__).resolve().parent / "workflows"))

        # ── 图 ────────────────────────────────────────────────
        self.checkpointer = MemorySaver()
        self.app = self._build_graph()

    # ────────────────────────────────────────────────────────────
    #  工具方法
    # ────────────────────────────────────────────────────────────

    def _auto_save_results(self, task_id, step_index, code, stdout):
        if not self.state_manager:
            return
        patterns = [r'-O\s+([^\s]+)', r'-o\s+([^\s]+)', r'>\s+([^\s]+)', r"to_csv\(['\"](.*?)['\"]"]
        detected = []
        for p in patterns:
            detected.extend(re.findall(p, code))
        for fpath in detected:
            fpath = fpath.strip()
            if os.path.exists(fpath):
                self.state_manager.save_artifact(
                    task_id, step_index, 'file',
                    os.path.basename(fpath), str(fpath), str(fpath),
                )

    def _auto_task_id_for_prompt(self, prompt: Any, fallback_prefix: str = "task") -> str:
        if isinstance(prompt, Command):
            return ""
        text = str(prompt or "").strip()
        if not text:
            return ""
        try:
            semantics = infer_task_semantics(
                task_id="",
                stage="start",
                messages=[HumanMessage(content=text)],
                payload={"user_query": text},
            )
        except Exception as exc:
            logger.debug("Automatic task id inference failed: %s", exc)
            semantics = {}
        task_type = str(semantics.get("task_type") or "general")
        analysis_type = str(semantics.get("analysis_type") or "general_analysis")
        if task_type == "general" and analysis_type == "general_analysis":
            return ""
        title = str(semantics.get("task_title") or analysis_type or fallback_prefix).strip()
        slug = re.sub(r"[^A-Za-z0-9_.-]+", "_", title).strip("._-").lower()
        if not slug:
            slug = f"{fallback_prefix}_{datetime.now().strftime('%Y%m%d')}"
        slug = slug[:90].strip("._-") or fallback_prefix
        return f"{slug}_{datetime.now().strftime('%H%M%S')}"

    def _record_initial_profiler_metadata(self, task_id: str, input_data: Any) -> None:
        if isinstance(input_data, Command):
            return
        prompt = str(input_data or "").strip()
        generic_meta = generic_metadata_for_prompt(task_id, prompt, repo_root=current_dir)
        benchmark_meta = benchmark_metadata_for_task(task_id, repo_root=current_dir)
        metadata = {**generic_meta, **benchmark_meta} if benchmark_meta else generic_meta
        try:
            self.profiler.record_task_metadata(
                task_id,
                test_content=metadata.get("test_content", ""),
                test_prompt=metadata.get("test_prompt", ""),
                test_data=metadata.get("test_data", []),
                data_size_bytes=metadata.get("data_size_bytes", 0),
                benchmark=metadata.get("benchmark", {}),
                extra={"semantics": metadata.get("semantics", {})},
            )
        except Exception as exc:
            logger.debug("Profiler initial metadata recording failed: %s", exc)

    def _should_auto_rename_session(
        self,
        task_id: str,
        *,
        authoritative_new_task: bool = False,
    ) -> bool:
        if not re.fullmatch(r"session_\d+", str(task_id or "")):
            return False
        if authoritative_new_task:
            return True
        try:
            return not self.task_summary_renderer.task_exists(task_id)
        except Exception:
            return True

    async def _observe_session_memory(
        self,
        task_id: str,
        stage: str,
        messages: Optional[List[BaseMessage]] = None,
        payload: Optional[Dict[str, Any]] = None,
    ) -> None:
        messages = messages or []
        payload = dict(payload or {})
        event_type = str(payload.get("event_type") or f"{stage}_event")
        project_id = str(payload.get("project_id") or self.default_project_id)
        try:
            inferred = infer_task_semantics(
                task_id=task_id,
                stage=stage,
                messages=messages,
                payload=payload,
            )
            task_semantics = merge_task_semantics(inferred, payload.get("task_semantics"))
            if task_semantics:
                payload["task_semantics"] = task_semantics
            recent = messages[-4:] if messages else []
            content_parts = [
                f"{type(msg).__name__}: {str(getattr(msg, 'content', msg))[:2000]}"
                for msg in recent
            ]
            if payload:
                content_parts.append("payload: " + json.dumps(payload, ensure_ascii=False, default=str)[:4000])
            content = "\n\n".join(content_parts) or stage
            summary = str(payload.get("summary") or content[:1200])
            returncode = payload.get("returncode")
            # The writer owns the former self.session_archive.append_event
            # operation; this node only performs a bounded enqueue_nowait.
            enqueue_result = self.session_archive_writer.enqueue_nowait(
                task_id=task_id,
                session_id=task_id,
                project_id=project_id,
                stage=stage,
                event_type=event_type,
                content=content,
                summary=summary,
                metadata=payload,
                paths=self._archive_paths_from_payload(payload, task_semantics),
                tags=[str(payload.get("task_mode") or ""), str(payload.get("workflow_id") or "")],
                returncode=returncode if isinstance(returncode, int) else None,
                task_semantics=task_semantics,
                source_refs=[f"task:{task_id}"],
            )
            if enqueue_result != "enqueued":
                logger.warning(
                    "Optional SessionArchive observation %s: task=%s stage=%s",
                    enqueue_result,
                    task_id,
                    stage,
                )
        except Exception as e:
            logger.warning(f"SessionArchive observe failed at {stage}: {e}")

    async def aclose(self, timeout_seconds: Optional[float] = None) -> Dict[str, Any]:
        """Bounded explicit shutdown for optional process-local archive writes."""

        if getattr(self, "_session_archive_writer_released", False):
            writer = getattr(self, "session_archive_writer", None)
            return writer.snapshot() if writer is not None else {}
        archive = getattr(self, "session_archive", None)
        if archive is None:
            return {}
        self._session_archive_writer_released = True
        return await asyncio.to_thread(
            release_observation_writer,
            archive.db_path,
            timeout_seconds=(
                SESSION_ARCHIVE_SHUTDOWN_DRAIN_SECONDS
                if timeout_seconds is None
                else timeout_seconds
            ),
        )

    async def _finalize_task_memory(
        self,
        task_id: str,
        status: str,
        messages: Optional[List[BaseMessage]] = None,
        payload: Optional[Dict[str, Any]] = None,
    ) -> None:
        payload = dict(payload or {})
        payload["status"] = status
        payload["event_type"] = "task_finalized"
        output_result = (
            payload.get("solution")
            or payload.get("result")
            or payload.get("final_result")
            or payload.get("reason")
            or payload.get("decision")
            or ""
        )
        try:
            output_artifacts = self._structured_final_artifacts(task_id, payload)
        except Exception:
            output_artifacts = []
        self.profiler.record_final_result(
            task_id,
            status=status,
            output_result=str(output_result or ""),
            output_artifacts=output_artifacts,
            node="finalize",
        )
        try:
            await self._observe_session_memory(
                task_id=task_id,
                stage="finalize",
                messages=messages or [],
                payload=payload,
            )
            self.task_summary_renderer.write_task_summary(task_id, fallback_status=status)
            await self._maybe_auto_wiki_ingest_after_finalize(task_id, status)
        except Exception as e:
            logger.warning(f"Task memory finalize failed for {task_id}: {e}")

    @staticmethod
    def _finalize_semantic_identity(
        constraint: Mapping[str, Any],
    ) -> Tuple[str, str, str, str]:
        return (
            str(constraint.get("semantic_key") or "").strip().casefold(),
            str(constraint.get("operator") or "").strip().casefold(),
            json.dumps(
                constraint.get("value"),
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
                default=str,
            ),
            json.dumps(
                constraint.get("condition"),
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
                allow_nan=False,
                default=str,
            ),
        )

    def _load_verified_finalize_v4_contract(
        self,
        *,
        task_id: str,
        protocol: Mapping[str, Any],
        task_spec: Mapping[str, Any],
        selected_skill_ids: Sequence[Any],
        enforce_task_spec_binding_hash: bool = True,
    ) -> Dict[str, Any]:
        """Reload and bind a compiled v4 contract to current business state."""
        owner = deepcopy(dict(protocol or {}))
        if (
            int(owner.get("schema_version") or 0) != 4
            or int(owner.get("wire_schema_version") or 0) != 3
        ):
            raise SnapshotConflictError(
                "FINALIZE_PROTOCOL_VERSION_UNSUPPORTED"
            )
        validate_finalize_protocol_v4(owner)
        outcome = dict(owner.get("compile_outcome") or {})
        if (
            str(owner.get("finalize_status") or "") != "compiled"
            or str(owner.get("protocol_status") or "") != "valid"
            or str(outcome.get("status") or "") != "compiled"
            or str(outcome.get("protocol_status") or "") != "valid"
        ):
            raise SnapshotConflictError(
                "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
            )
        store = ContextLineageStore(self.data_path, task_id)
        context_artifact = dict(
            store.lookup_finalize_context_artifact(
                finalize_context_id=str(
                    owner.get("finalize_context_id") or ""
                ),
                base_contract_hash=str(
                    owner.get("base_contract_hash") or ""
                ),
            )
            or {}
        )
        frozen_context = dict(
            context_artifact.get("finalize_context") or {}
        )
        selected = list(dict.fromkeys(
            str(item).strip()
            for item in selected_skill_ids or []
            if str(item).strip()
        ))
        current_task_binding_hash = (
            finalize_task_spec_binding_hash(
                task_spec,
                selected_skill_ids=selected,
            )
            if enforce_task_spec_binding_hash
            else ""
        )
        if (
            not context_artifact
            or not frozen_context
            or (
                enforce_task_spec_binding_hash
                and str(frozen_context.get("task_spec_binding_hash") or "")
                != current_task_binding_hash
            )
            or list(frozen_context.get("resolved_selected_skill_ids") or [])
            != selected
        ):
            raise SnapshotConflictError(
                "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
            )
        compiled = dict(
            store.lookup_finalize_compiled_contract(
                compiled_contract_hash=str(
                    outcome.get("compiled_contract_hash") or ""
                ),
                finalize_context_id=str(
                    owner.get("finalize_context_id") or ""
                ),
            )
            or {}
        )
        aggregate = dict(owner.get("aggregate") or {})
        expected_resolution_ids = sorted(
            str(item)
            for item in aggregate.get("expected_resolution_ids") or []
        )
        resolved_resolution_ids = sorted(
            str(item)
            for item in aggregate.get("resolved_resolution_ids") or []
        )
        protocol_leaves = sorted(
            (
                str(item.get("batch_id") or ""),
                str(item.get("batch_hash") or ""),
                str(item.get("decision_artifact_ref") or ""),
                str(item.get("decision_artifact_hash") or ""),
            )
            for item in owner.get("batches") or []
            if isinstance(item, Mapping)
            and str(item.get("status") or "") == "resolved"
        )
        compiled_leaves = sorted(
            (
                str(item.get("batch_id") or ""),
                str(item.get("batch_hash") or ""),
                str(item.get("decision_artifact_ref") or ""),
                str(item.get("decision_artifact_hash") or ""),
            )
            for item in compiled.get("active_leaf_decisions") or []
            if isinstance(item, Mapping)
        )
        compile_mode = str(compiled.get("compile_mode") or "")
        if (
            not compiled
            or str(compiled.get("compiled_contract_ref") or "")
            != str(outcome.get("compiled_contract_ref") or "")
            or str(compiled.get("compiled_contract_hash") or "")
            != str(outcome.get("compiled_contract_hash") or "")
            or str(compiled.get("coverage_artifact_ref") or "")
            != str(outcome.get("coverage_artifact_ref") or "")
            or str(compiled.get("coverage_artifact_hash") or "")
            != str(outcome.get("coverage_artifact_hash") or "")
            or str(owner.get("coverage_artifact_ref") or "")
            != str(outcome.get("coverage_artifact_ref") or "")
            or str(owner.get("coverage_artifact_hash") or "")
            != str(outcome.get("coverage_artifact_hash") or "")
            or str(compiled.get("finalize_context_id") or "")
            != str(owner.get("finalize_context_id") or "")
            or str(compiled.get("base_contract_hash") or "")
            != str(owner.get("base_contract_hash") or "")
            or str(compiled.get("finalize_context_artifact_ref") or "")
            != str(context_artifact.get("finalize_context_artifact_ref") or "")
            or str(compiled.get("finalize_context_artifact_hash") or "")
            != str(context_artifact.get("finalize_context_artifact_hash") or "")
            or int(compiled.get("protocol_schema_version") or 0) != 4
            or int(compiled.get("wire_schema_version") or 0) != 3
            or compile_mode != str(owner.get("compile_mode") or "")
            or compile_mode != str(outcome.get("mode") or "")
            or list(compiled.get("selected_skills") or []) != selected
            or int(compiled.get("task_spec_revision") or -1)
            != task_spec_revision(task_spec)
            or expected_resolution_ids != resolved_resolution_ids
            or len(expected_resolution_ids) != len(set(expected_resolution_ids))
            or (
                compile_mode == "model_batched"
                and (not protocol_leaves or protocol_leaves != compiled_leaves)
            )
            or (
                compile_mode == "controller_deterministic"
                and (protocol_leaves or compiled_leaves)
            )
        ):
            raise SnapshotConflictError(
                "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
            )

        return compiled

    def _wiki_terminal_snapshot(
        self,
        task_id: str,
        *,
        terminal_status: str = "",
        values: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Build one fail-closed snapshot for both Wiki offer and ingestion."""
        try:
            durable_plan = load_plan_state(self.data_path, task_id)
        except Exception:
            durable_plan = {}
        value_map = dict(values or {})
        task_state = dict(durable_plan.get("task_state") or {})
        consultation = value_map.get("consultation_state")
        if not isinstance(consultation, Mapping):
            consultation = task_state.get("consultation_state") or {}
        waiting = bool(
            value_map.get("pending_human_question")
            or task_state.get("pending_question")
            or self._business_waiting_state(
                load_waiting_state(self.data_path, task_id)
            )
        )
        durable_status = str(task_status(durable_plan) or "").lower()
        observed_terminal = str(terminal_status or durable_status or "").lower()
        managed_task = bool(
            durable_plan.get("plan_schema_version")
            or durable_plan.get("plan_id")
            or str(value_map.get("task_mode") or "managed") == "managed"
        )
        compiled_contract_verified = False
        consultation_map = dict(consultation or {})
        wiki_protocol = dict(
            consultation_map.get("finalize_protocol") or {}
        )
        # Terminal decisions are verified only against durable canonical
        # state.  Corruption disables Wiki eligibility instead of falling back
        # to a checkpoint alias.
        try:
            wiki_task_spec = canonical_task_spec_for_state(durable_plan)
        except CanonicalTaskStateError:
            wiki_task_spec = {}
        wiki_selected_skills = (
            value_map.get("selected_skills")
            or consultation_map.get("resolved_selected_skill_ids")
            or task_state.get("selected_skills")
            or []
        )
        if (
            int(wiki_protocol.get("schema_version") or 0) == 4
            and int(wiki_protocol.get("wire_schema_version") or 0) == 3
            and str(wiki_protocol.get("finalize_status") or "") == "compiled"
            and isinstance(wiki_task_spec, Mapping)
        ):
            try:
                durable_compiled = self._load_verified_finalize_v4_contract(
                    task_id=task_id,
                    protocol=wiki_protocol,
                    task_spec=wiki_task_spec,
                    selected_skill_ids=wiki_selected_skills,
                )
                compiled_contract_verified = bool(durable_compiled)
            except (OSError, ValueError, SnapshotConflictError):
                compiled_contract_verified = False
        return terminal_snapshot_projection(
            task_id=task_id,
            terminal_status=observed_terminal,
            task_status=durable_status,
            plan_state=durable_plan,
            consultation_state=consultation_map,
            waiting_business_question=waiting,
            managed_task=managed_task,
            compiled_contract_verified=compiled_contract_verified,
        )

    def _persist_wiki_eligibility_decision(
        self,
        task_id: str,
        *,
        decision_kind: str,
        terminal_status: str = "",
        values: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        snapshot = self._wiki_terminal_snapshot(
            task_id,
            terminal_status=terminal_status,
            values=values,
        )
        decision = evaluate_wiki_eligibility(
            snapshot,
            decision_kind=decision_kind,
        )
        # Persistence is part of the eligibility gate.  Any exception is
        # intentionally allowed to fail closed at the caller boundary.
        return WikiLifecycleStore(self.data_path, task_id).persist_decision(decision)

    async def _ingest_wiki_task_with_gate(
        self,
        task_id: str,
        *,
        project_id: str,
        expected_snapshot_hash: str = "",
        limit: Optional[int] = None,
    ) -> Tuple[bool, Any]:
        """Re-evaluate eligibility, journal the side effect, then ingest once."""
        decision = self._persist_wiki_eligibility_decision(
            task_id,
            decision_kind="ingest",
            terminal_status="completed",
        )
        if not bool(decision.get("eligible")):
            return False, f"Wiki ingest denied: {decision.get('reason') or 'ineligible'}"
        if expected_snapshot_hash and str(decision.get("terminal_snapshot_hash") or "") != str(
            expected_snapshot_hash
        ):
            return False, "Wiki ingest denied: terminal_snapshot_changed"
        pending_count = self.session_archive.pending_for_wiki_count(
            project_id=project_id,
            task_id=task_id,
        )
        if pending_count <= 0:
            return False, "Wiki ingest skipped: no pending events"
        content_identity = {
            "task_id": task_id,
            "project_id": project_id,
            "pending_count": int(pending_count),
            "terminal_snapshot_hash": decision.get("terminal_snapshot_hash"),
            "compiled_contract_hash": decision.get("compiled_contract_hash"),
        }
        content_hash = hashlib.sha256(
            json.dumps(
                content_identity,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
        lifecycle = WikiLifecycleStore(self.data_path, task_id)
        outbox = lifecycle.prepare_outbox(
            eligibility_decision=decision,
            project_id=project_id,
            operation="archive_ingest",
            content_hash=content_hash,
        )
        outbox_status = str(outbox.get("status") or "")
        if outbox_status == "succeeded":
            return True, dict(outbox.get("destination_result") or {})
        if outbox_status in {"dispatched", "outcome_unknown"}:
            return False, "Wiki ingest outcome requires reconciliation; duplicate dispatch blocked"
        lifecycle.transition_outbox(outbox["outbox_id"], status="dispatched")
        try:
            result = await self.wiki_memory_manager.ingest_from_archive(
                self.session_archive,
                project_id=project_id,
                task_id=task_id,
                limit=max(1, int(limit or pending_count)),
            )
        except BaseException as exc:
            lifecycle.transition_outbox(
                outbox["outbox_id"],
                status="outcome_unknown",
                destination_result={
                    "error_type": type(exc).__name__,
                    "message": str(exc)[:2000],
                },
            )
            raise
        lifecycle.transition_outbox(
            outbox["outbox_id"],
            status="succeeded",
            destination_result={"acknowledged": True, "result": str(result)},
        )
        return True, result

    async def _maybe_auto_wiki_ingest_after_finalize(self, task_id: str, status: str) -> None:
        if not self.wiki_enabled or self.wiki_ingest_mode != "auto":
            return
        project_id = self.default_project_id
        key = f"{project_id}:{task_id}"
        if key in self._wiki_auto_ingest_done:
            return
        try:
            decision = self._persist_wiki_eligibility_decision(
                task_id,
                decision_kind="ingest",
                terminal_status=status,
            )
            if not bool(decision.get("eligible")):
                return
            succeeded, result = await self._ingest_wiki_task_with_gate(
                task_id,
                project_id=project_id,
                expected_snapshot_hash=str(decision.get("terminal_snapshot_hash") or ""),
            )
            if succeeded:
                self._wiki_auto_ingest_done.add(key)
                logger.info("Auto wiki ingest after %s: %s", task_id, result)
        except Exception as e:
            logger.warning(f"Auto wiki ingest failed for {task_id}: {e}")

    async def _maybe_offer_wiki_ingest(self, task_id: str, project_id: Optional[str] = None) -> None:
        if not self.wiki_enabled or self.wiki_ingest_mode != "ask":
            return
        project_id = project_id or self.default_project_id
        key = f"{project_id}:{task_id}"
        if key in self._wiki_ingest_offer_done:
            return
        try:
            offer_decision = self._persist_wiki_eligibility_decision(
                task_id,
                decision_kind="offer",
                terminal_status="completed",
            )
        except Exception as exc:
            logger.warning("Wiki offer decision persistence failed closed for %s: %s", task_id, exc)
            return
        if not bool(offer_decision.get("eligible")):
            return
        try:
            task_pending = self.session_archive.pending_for_wiki_count(
                project_id=project_id,
                task_id=task_id,
            )
            if task_pending <= 0:
                return
            project_pending = self.session_archive.pending_for_wiki_count(project_id=project_id)
        except Exception as e:
            logger.warning(f"Wiki ingest pending check failed for {task_id}: {e}")
            return
        self._wiki_ingest_offer_done.add(key)

        prompt = (
            f"\n{Fore.CYAN}Wiki memory: {task_pending} pending event(s) from this task "
            f"({project_pending} pending in project). Ingest this task into Wiki now? [y/N] > "
            f"{Style.RESET_ALL}"
        )
        payload = {
            "type": "wiki_ingest_offer",
            "task_id": task_id,
            "project_id": project_id,
            "task_pending": task_pending,
            "project_pending": project_pending,
            "mode": self.wiki_ingest_mode,
        }
        wait_started = time.perf_counter()
        wait_started_at = timestamp_now()
        try:
            response = await self._aprompt_user(
                task_id,
                "wiki_ingest_offer",
                prompt,
                payload=payload,
                started_at=wait_started_at,
            )
        except HumanInputUnavailable as exc:
            self._record_human_wait(
                task_id,
                "wiki_ingest_offer",
                wait_started,
                f"<waiting_user:{type(exc).__name__}>",
                payload,
                started_at=wait_started_at,
            )
            return
        self._record_human_wait(
            task_id,
            "wiki_ingest_offer",
            wait_started,
            response,
            payload,
            started_at=wait_started_at,
        )
        if response.strip().lower() not in {"y", "yes"}:
            print(f"{Fore.CYAN}Wiki ingest skipped. Run /wiki ingest later, or set BIOMIND_WIKI_INGEST_MODE=manual/auto.{Style.RESET_ALL}")
            return
        succeeded, result = await self._ingest_wiki_task_with_gate(
            task_id,
            project_id=project_id,
            expected_snapshot_hash=str(offer_decision.get("terminal_snapshot_hash") or ""),
            limit=max(1, task_pending),
        )
        output.page_text("Wiki Ingest", result, Fore.CYAN if succeeded else Fore.YELLOW)

    async def _task_summary_prompt_context(self, task_id: str, query: str) -> Dict[str, str]:
        try:
            return await self.task_summary_renderer.build_prompt_context_async(task_id, query)
        except Exception as e:
            logger.warning(f"Task summary retrieval failed for {task_id}: {e}")
            return {"long_term_memory": "", "task_memory": "", "related_memory": ""}

    def _task_summary_resume_context(self, task_id: str) -> str:
        try:
            task_memory = self.task_summary_renderer.read_task_summary(task_id)
        except Exception as e:
            logger.warning(f"Task summary resume read failed for {task_id}: {e}")
            return ""
        if not task_memory.strip():
            return ""
        return (
            "**Task Summary (derived resume context):**\n"
            f"{task_memory}\n\n"
            "Use this task summary first, then use execution records below as supporting evidence.\n"
        )

    @staticmethod
    def _archive_paths_from_payload(payload: Dict[str, Any], task_semantics: Dict[str, Any]) -> List[str]:
        paths: List[str] = []
        for key in ("paths", "path", "output_path", "output_paths", "output_file", "artifact", "artifacts", "plan_file", "script_file"):
            value = payload.get(key)
            if isinstance(value, (list, tuple, set)):
                paths.extend(str(item) for item in value if str(item).strip())
            elif str(value or "").strip():
                paths.append(str(value))
        paths.extend(str(item) for item in task_semantics.get("output_artifacts", []) if str(item).strip())
        seen: set[str] = set()
        ordered: List[str] = []
        for path in paths:
            if path in seen:
                continue
            seen.add(path)
            ordered.append(path)
        return ordered

    def _structured_final_artifacts(self, task_id: str, payload: Dict[str, Any]) -> List[Dict[str, Any]]:
        """Project final artifacts only from TaskSpec and Plan ownership."""
        plan = load_plan_state(self.data_path, task_id)
        task_spec = ensure_task_spec(
            canonical_task_spec_for_state(plan),
            task_id=task_id,
        )
        contracts = effective_output_contracts(task_spec)
        output_dir = next(
            (
                str(item.get("canonical_path") or "")
                for item in contracts
                if str(item.get("role") or "") == "output_dir"
            ),
            "",
        )
        steps = [item for item in plan.get("steps", []) or [] if isinstance(item, dict)]
        records: List[Dict[str, Any]] = []
        for contract in contracts:
            if str(contract.get("role") or "") == "output_dir":
                continue
            requested = str(contract.get("canonical_path") or "")
            if not requested:
                continue
            path = Path(requested).expanduser()
            if not path.is_absolute() and output_dir:
                path = Path(output_dir).expanduser() / path
            identity = path.name.lower()
            producers = [
                step for step in steps
                if identity in {
                    Path(str(value)).name.lower()
                    for value in step.get("outputs", []) or []
                    if str(value)
                }
            ]
            producer = producers[0] if len(producers) == 1 else {}
            artifacts = [
                item for item in producer.get("artifacts", []) or []
                if isinstance(item, dict)
                and Path(str(item.get("path") or "")).name.lower() == identity
            ]
            artifact = artifacts[0] if artifacts else {}
            producer_id = str(producer.get("step_id") or "")
            records.append({
                "artifact_ref": str(artifact.get("artifact_id") or contract.get("artifact_id") or identity),
                "output_id": str(contract.get("artifact_id") or contract.get("output_id") or identity),
                "path": str(path),
                "producer_id": producer_id,
                "producer_type": "renderer" if producer.get("renderer_composite") else ("plan_step" if producer_id else "unresolved"),
                "required": bool(contract.get("required", True)),
                "exists": path.is_file() and path.stat().st_size > 0,
                "validation_ref": str(artifact.get("validator") or contract.get("validation_contract_id") or ""),
                "source_contract_ref": str(contract.get("source_ref") or contract.get("artifact_id") or ""),
            })
        return records

    def _load_agents_md(self, work_dir: str) -> str:
        try:
            start = Path(work_dir).expanduser().resolve()
        except Exception:
            start = Path(work_dir).expanduser()
        if start.is_file():
            start = start.parent

        candidates: List[Path] = []
        for folder in [start, *start.parents]:
            path = folder / "AGENTS.md"
            if path.exists() and path.is_file():
                candidates.append(path)

        if not candidates:
            return ""

        blocks = []
        for path in reversed(candidates):
            try:
                content = path.read_text(encoding="utf-8")
            except UnicodeDecodeError:
                content = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            blocks.append(f"### {path}\n{content.strip()}")
        return self._clip_prompt_text("\n\n".join(blocks), 20_000)

    def _user_preferences_path(self) -> Path:
        configured = os.getenv("BIOMIND_USER_PREFERENCES", "").strip()
        if configured:
            path = Path(configured).expanduser()
            if not path.is_absolute():
                path = current_dir / path
            return path.resolve()
        return (current_dir / "user_preferences.md").resolve()

    def _load_user_preferences(self) -> str:
        path = self._user_preferences_path()
        if not path.exists() or not path.is_file():
            return ""
        try:
            content = path.read_text(encoding="utf-8")
        except UnicodeDecodeError:
            content = path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            return ""
        content = content.strip()
        if not content:
            return ""
        return self._clip_prompt_text(f"### {path}\n{content}", 12_000)

    def _get_or_create_stable_prompt(self, session_id: str, project_id: Optional[str] = None) -> Dict[str, str]:
        project_id = project_id or self.default_project_id
        cache_key = f"{session_id}::{project_id}"
        cached = self._stable_prompt_cache.get(cache_key)
        if cached:
            return cached

        prompt_path, meta_path = self._stable_prompt_paths(session_id, project_id)
        if prompt_path.exists():
            prompt = prompt_path.read_text(encoding="utf-8")
            meta = self._read_json_file(meta_path)
            record = {
                "prompt": prompt,
                "session_id": session_id,
                "project_id": str(meta.get("project_id") or project_id),
                "core_memory_loaded_at": str(meta.get("core_memory_loaded_at") or "unknown"),
                "prompt_path": str(prompt_path),
            }
            self._stable_prompt_cache[cache_key] = record
            return record

        work_dir = str(self.pm.work_dir if self.pm else self.data_path)
        snapshot = self.core_memory_store.load_snapshot(project_id, snapshot_id=session_id)
        core_memory = snapshot.prompt_text()
        agents_md = self._load_agents_md(work_dir)
        user_preferences = self._load_user_preferences()
        prompt = PromptManager.build_stable_system_prompt(
            package_manager=self.pm,
            work_dir=work_dir,
            core_memory=core_memory,
            agents_md_context=agents_md,
            user_preferences_context=user_preferences,
        )
        prompt_path.parent.mkdir(parents=True, exist_ok=True)
        prompt_path.write_text(prompt, encoding="utf-8")
        meta = {
            "session_id": session_id,
            "project_id": project_id,
            "core_memory_loaded_at": snapshot.loaded_at,
            "work_dir": work_dir,
            "user_preferences_path": str(self._user_preferences_path()),
            "user_preferences_loaded": bool(user_preferences),
            "prompt_path": str(prompt_path),
            "created_at": datetime.now().isoformat(timespec="seconds"),
        }
        meta_path.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")
        record = {
            "prompt": prompt,
            "session_id": session_id,
            "project_id": project_id,
            "core_memory_loaded_at": snapshot.loaded_at,
            "prompt_path": str(prompt_path),
        }
        self._stable_prompt_cache[cache_key] = record
        return record

    def _archive_prompt_context(
        self,
        task_id: Optional[str],
        query: str,
        project_id: Optional[str] = None,
        limit: int = 4,
        exclude_task_id: Optional[str] = None,
    ) -> str:
        if not query.strip():
            return ""
        try:
            hits = self.session_archive.search(
                query,
                task_id=task_id or None,
                project_id=project_id,
                limit=limit * 3 if exclude_task_id else limit,
            )
            if exclude_task_id:
                excluded = str(exclude_task_id).strip()
                hits = [hit for hit in hits if str(hit.task_id).strip() != excluded][:limit]
            if not hits:
                return ""
            return self.session_archive.format_hits(hits, title="Retrieved Session Archive")
        except Exception as e:
            logger.warning(f"Session archive retrieval failed for {task_id or 'project'}: {e}")
            return ""

    def _pending_archive_buffer_context(
        self,
        task_id: Optional[str],
        query: str,
        project_id: Optional[str] = None,
        limit: int = 4,
    ) -> str:
        if not self.wiki_enabled or not query.strip():
            return ""
        project_id = project_id or self.default_project_id
        try:
            hits = self.session_archive.search_pending_for_wiki(
                query,
                task_id=task_id or None,
                project_id=project_id,
                limit=limit,
            )
            if len(hits) < limit:
                seen_ids = {hit.id for hit in hits}
                for hit in self.session_archive.search_pending_for_wiki(
                    query,
                    project_id=project_id,
                    limit=limit * 2,
                ):
                    if hit.id in seen_ids:
                        continue
                    hits.append(hit)
                    seen_ids.add(hit.id)
                    if len(hits) >= limit:
                        break
            if not hits:
                return ""
            context = self.session_archive.format_hits(
                hits,
                title="Pending SessionArchive Buffer (not yet Wiki-ingested)",
            )
            return (
                "<session_archive_buffer_policy>\n"
                "- This buffer is only for the current task or recent events waiting for Wiki curation.\n"
                "- Prefer Wiki claims for durable facts; use these raw events only to avoid losing just-finished context.\n"
                "- Do not treat TaskSummary reports as factual sources.\n"
                "</session_archive_buffer_policy>\n\n"
                f"{self._clip_prompt_text(context, 2400)}"
            )
        except Exception as e:
            logger.warning(f"Pending SessionArchive buffer retrieval failed for {task_id or 'project'}: {e}")
            return ""

    def _artifact_index_context(self, task_id: Optional[str], query: str, limit: int = 6) -> str:
        if not self.artifact_index or not query.strip():
            return ""
        try:
            hits = self.artifact_index.search_artifacts(query, task_id=task_id or None, limit=limit)
            if len(hits) < limit:
                seen_ids = {hit.id for hit in hits}
                for hit in self.artifact_index.search_artifacts(query, limit=limit * 2):
                    if hit.id in seen_ids:
                        continue
                    hits.append(hit)
                    seen_ids.add(hit.id)
                    if len(hits) >= limit:
                        break
            if not hits:
                return ""
            return (
                "<artifact_index_policy>\n"
                "- This artifact index is retrieved only when Generate appears to be missing an input or output path.\n"
                "- Verify paths on disk before reusing them; artifact records may be stale.\n"
                "</artifact_index_policy>\n\n"
                f"{self._clip_prompt_text(self.artifact_index.format_hits(hits, title='Retrieved Artifact Index'), 2400)}"
            )
        except Exception as e:
            logger.warning(f"Artifact index retrieval failed for {task_id or 'project'}: {e}")
            return ""

    @staticmethod
    def _empty_task_summary_context() -> Dict[str, str]:
        return {"long_term_memory": "", "task_memory": "", "related_memory": ""}

    @staticmethod
    def _recent_observation_text(messages: List[BaseMessage], max_chars: int = 2400) -> str:
        parts: List[str] = []
        for msg in reversed(messages[-10:]):
            content = str(getattr(msg, "content", msg) or "")
            if (
                "<observation>" in content
                or "<supervisor_feedback" in content
                or "supervisor" in content.lower()
                or "❌" in content
            ):
                parts.append(content)
            if len(parts) >= 3:
                break
        return "\n\n".join(reversed(parts))[-max_chars:]

    @staticmethod
    def _latest_human_text(messages: List[BaseMessage], max_chars: int = 1600) -> str:
        for msg in reversed(messages):
            if isinstance(msg, HumanMessage):
                return str(getattr(msg, "content", "") or "")[-max_chars:]
        return ""

    @staticmethod
    def _looks_like_failed_or_retry_context(text: str) -> bool:
        lower = str(text or "").lower()
        return "❌" in str(text or "") or any(
            term in lower
            for term in (
                "failed",
                "failure",
                "traceback",
                "exception",
                "error:",
                "returncode",
                "failed validation",
                "retry",
                "warn",
                "报错",
                "失败",
                "错误",
            )
        )

    @staticmethod
    def _supervisor_warn_requires_followup(messages: List[BaseMessage]) -> bool:
        """Detect WARN reviews that are actually unfinished-step instructions."""
        text = "\n".join(str(getattr(msg, "content", msg) or "") for msg in messages)
        lower = text.lower()
        if "verdict" not in lower or "warn" not in lower:
            return False
        followup_action = re.search(
            r"\baction\s*:\s*(?:execute|run|rerun|re-run|inspect|verify|check|proceed|continue|repair)\b",
            lower,
        )
        unfinished_signal = any(
            phrase in lower
            for phrase in (
                "only created",
                "without running",
                "no actual",
                "not performed",
                "not generated",
                "incomplete",
                "truncated",
                "before accepting",
                "before treating",
                "proceed to the next planned analysis step",
                "execute the generated",
                "run the preprocess",
                "inspect the output",
                "validate its scientific outputs",
                "未真正执行",
                "没有真正执行",
                "尚未执行",
                "继续执行",
                "执行生成的",
            )
        )
        return bool(followup_action and unfinished_signal)

    @staticmethod
    def _supervisor_warn_is_acceptably_artifact_bounded(
        messages: List[BaseMessage],
        plan_state: Dict[str, Any],
        step_gate: Any,
    ) -> bool:
        """Allow artifact-bounded WARNs when deterministic gates already passed.

        Some LLM reviews ask for another inspection because a terminal preview
        was visually truncated or a compact TSV is small. If the active step is
        the final/status/report artifact step and CompletionGate already verified
        the step contract, do not convert that advisory WARN into an endless
        RETRY loop.
        """
        if not getattr(step_gate, "passed", False):
            return False
        step = BioAnalystAgent._running_plan_step(plan_state)
        title = str(step.get("title") or "").lower()
        if not re.search(r"report|reproduce|stage_status|status|summary|final|artifact|output|报告|状态|可复现|总结", title):
            return False
        text = "\n".join(str(getattr(msg, "content", msg) or "") for msg in messages).lower()
        advisory_terms = ("inspect", "verify", "check", "before accepting", "truncated", "incomplete", "empty")
        hard_terms = ("exit code", "traceback", "no such file", "does not exist", "command not found", "a user error")
        return any(term in text for term in advisory_terms) and not any(term in text for term in hard_terms)

    @staticmethod
    def _looks_like_missing_input_context(text: str) -> bool:
        lower = str(text or "").lower()
        missing_terms = (
            "no such file",
            "does not exist",
            "cannot find",
            "cannot access",
            "not found",
            "missing input",
            "missing path",
            "找不到",
            "不存在",
            "缺少输入",
            "路径缺失",
        )
        path_terms = (
            "path",
            "file",
            "input",
            "artifact",
            "output",
            "rds",
            "fastq",
            "bam",
            "vcf",
            "csv",
            "tsv",
            "路径",
            "文件",
            "输入",
            "产物",
        )
        return any(term in lower for term in missing_terms) and any(term in lower for term in path_terms)

    @staticmethod
    def _looks_like_evidence_query(text: str) -> bool:
        lower = str(text or "").lower()
        return any(
            term in lower
            for term in (
                "evidence",
                "source",
                "citation",
                "claim",
                "why",
                "basis",
                "依据",
                "证据",
                "来源",
                "引用",
                "为什么",
                "解释",
            )
        )

    async def _generate_on_demand_memory_contexts(
        self,
        state: AgentState,
        messages: List[BaseMessage],
        task_id: str,
        project_id: str,
        query: str,
        memory_packet_context: str,
        supervisor_verdict: str,
    ) -> Dict[str, Any]:
        """Return only memory contexts required by the current Generate turn."""
        contexts: Dict[str, Any] = {
            "task_summary_context": self._empty_task_summary_context(),
            "archive_context": "",
            "wiki_context": "",
            "wiki_digest": "",
        }
        recent_observation = self._recent_observation_text(messages)
        latest_human = self._latest_human_text(messages)
        trigger_text = "\n\n".join(
            part for part in [query, recent_observation, latest_human] if str(part).strip()
        )

        recovery_trigger = (
            supervisor_verdict in {"RETRY", "WARN"}
            or self._looks_like_failed_or_retry_context(recent_observation)
        )
        missing_input = self._looks_like_missing_input_context(trigger_text)
        evidence_query = self._looks_like_evidence_query(latest_human)

        archive_parts: List[str] = []
        if recovery_trigger:
            recovery_query = "\n".join(
                part
                for part in [
                    "similar error history recovery fix",
                    supervisor_verdict,
                    trigger_text,
                ]
                if str(part).strip()
            )
            archive_context = self._archive_prompt_context(
                None,
                recovery_query,
                project_id=project_id,
                limit=4,
            )
            if archive_context.strip():
                archive_parts.append(
                    "<error_recovery_memory>\n"
                    f"{self._clip_prompt_text(archive_context, 2600)}\n"
                    "</error_recovery_memory>"
                )

        if missing_input:
            artifact_context = self._artifact_index_context(task_id, trigger_text, limit=6)
            if artifact_context.strip():
                archive_parts.append(f"<artifact_lookup>\n{artifact_context}\n</artifact_lookup>")
            pending_context = self._pending_archive_buffer_context(
                task_id=task_id,
                project_id=project_id,
                query=trigger_text,
                limit=4,
            )
            if pending_context.strip():
                archive_parts.append(
                    "<missing_input_archive_lookup>\n"
                    f"{self._clip_prompt_text(pending_context, 2400)}\n"
                    "</missing_input_archive_lookup>"
                )

        if archive_parts:
            contexts["archive_context"] = (
                "<on_demand_runtime_memory_policy>\n"
                "- Generate normally receives only step-local context.\n"
                "- The sections below were retrieved because this turn matched an error-recovery or missing-input trigger.\n"
                "- Use them only to repair the current step; do not treat raw events as durable facts without verification.\n"
                "</on_demand_runtime_memory_policy>\n\n"
                + "\n\n".join(archive_parts)
            )

        if self.wiki_enabled and evidence_query:
            wiki_context = self._wiki_prompt_context(task_id, project_id, trigger_text)
            if wiki_context.strip():
                contexts["wiki_context"] = wiki_context
            contexts["wiki_digest"] = self._wiki_digest_prompt_context(project_id, max_chars=2000)
        elif self.wiki_enabled and not memory_packet_context.strip() and state.get("wiki_memory_context"):
            contexts["wiki_context"] = str(state.get("wiki_memory_context") or "")

        return contexts

    def _archive_resume_context(self, task_id: str) -> str:
        try:
            hits = self.session_archive.resume_events(task_id=task_id, limit=8)
            if not hits:
                return ""
            return self.session_archive.format_hits(hits, title="Retrieved Session Archive for Resume")
        except Exception as e:
            logger.warning(f"Session archive resume retrieval failed for {task_id}: {e}")
            return ""

    def _build_resume_prompt(self, task_id: str, user_prompt: Any = "") -> str:
        parts = []
        task_resume = self._task_summary_resume_context(task_id)
        if task_resume.strip():
            parts.append(task_resume.strip())
        if self.state_manager:
            state_resume = self.state_manager.resume_task(task_id)
            if str(state_resume).strip():
                parts.append(str(state_resume).strip())
        archive_resume = self._archive_resume_context(task_id)
        if archive_resume.strip():
            parts.append(archive_resume.strip())
        if str(user_prompt).strip():
            parts.append(str(user_prompt).strip())
        return "\n\n".join(parts)

    def _persistent_task_record(self, task_id: str) -> Dict[str, Any]:
        if not self.state_manager:
            return {}
        try:
            context = self.state_manager.get_task_context(task_id)
        except Exception:
            return {}
        task_info = context.get("task_info") if isinstance(context, dict) else {}
        return dict(task_info) if isinstance(task_info, dict) else {}

    @staticmethod
    def _business_waiting_state(waiting: Dict[str, Any]) -> bool:
        # Wiki ingestion is optional post-processing after a task has already
        # reached a terminal state.  A stale/timeout Wiki offer must never
        # resurrect that task as business-level ``waiting_user``.
        return bool(
            waiting
            and str(waiting.get("stage") or "")
            not in {"", "interactive_prompt", "wiki_ingest_offer"}
        )

    @staticmethod
    def _recovery_state_is_resolved(recovery_state: Dict[str, Any]) -> bool:
        """Return whether durable recovery state supersedes stale checkpoint retry data."""
        phase = str((recovery_state or {}).get("phase") or "").strip().lower()
        status = str((recovery_state or {}).get("status") or "").strip().lower()
        return phase in {
            "resolved", "success", "completed", "cleared",
            "consumed", "superseded", "expired",
        } or status in {
            "resolved", "success", "completed", "cleared",
            "consumed", "superseded", "expired",
        }

    @staticmethod
    def _merge_recovery_phase_evidence(
        durable_recovery: Mapping[str, Any],
        external_phase: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Keep schema-v4 lifecycle authoritative over the legacy side store."""
        durable = dict(durable_recovery or {})
        external = dict(external_phase or {})
        try:
            schema_version = int(durable.get("schema_version") or 0)
        except (TypeError, ValueError):
            schema_version = 0
        if schema_version >= 4:
            if external:
                durable["external_phase_evidence"] = external
            return durable
        return {**durable, **external}

    def _consume_pending_recovery_on_resume(
        self,
        task_id: str,
        plan_state: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Crash-resume one durable pending transition through the sole resolver."""
        task_state = dict(plan_state.get("task_state") or {})
        recovery_state = dict(task_state.get("recovery_state") or {})
        active = dict(recovery_state.get("active_transition") or {})
        if str(active.get("status") or "").strip().lower() != "pending":
            return {}
        decision_id = str(
            active.get("decision_id") or active.get("idempotency_key") or ""
        )
        trigger_node = str(
            active.get("trigger_node") or active.get("source_node") or ""
        ).strip().lower()
        trigger_event_id = str(
            active.get("trigger_event_id") or active.get("attempt_id") or ""
        )
        step_id = str(active.get("step_id") or plan_state.get("current_step_id") or "")
        if not decision_id or not trigger_node:
            return {}

        provenance = dict(plan_state.get("provenance_state") or {})
        attempt = dict((provenance.get("attempts") or {}).get(trigger_event_id) or {})
        execution_evidence: Dict[str, Any] = {}
        if trigger_node == "execute" and attempt:
            execution_evidence = {
                "attempt_id": trigger_event_id,
                "execution_id": str(
                    attempt.get("execution_id")
                    or attempt.get("execution_record_id")
                    or trigger_event_id
                ),
                "action_id": str(attempt.get("action_id") or active.get("action_id") or ""),
                "step_id": str(attempt.get("step_id") or step_id),
                "returncode": attempt.get("returncode"),
                "execution_status": str(attempt.get("status") or ""),
                "command_role": str(attempt.get("command_role") or "primary"),
                "validation": dict(attempt.get("validation") or {}),
            }

        final_step_completion = bool(
            str(active.get("kind") or "") == RecoveryDecisionKind.COMPLETE_STEP.value
            and plan_state.get("steps")
            and all(
                str(step.get("status") or "") in {"done", "passed", "skipped"}
                for step in plan_state.get("steps", []) or []
                if isinstance(step, Mapping)
            )
        )
        safe_proposal = (
            "supervisor_final_audit" if final_step_completion else "supervisor"
        )
        update: Dict[str, Any] = {
            "proposed_route": safe_proposal,
            "next_step": safe_proposal,
            "current_step_id": step_id,
            "recovery_decision": active,
            "recovery_application": {
                "applied": True,
                "decision_id": decision_id,
                "transition_status": "pending",
            },
            "transition_guard": "resume_pending_recovery_transition",
        }
        if execution_evidence:
            update["execution_evidence"] = execution_evidence
        if final_step_completion:
            update.update({
                "final_audit_requested": True,
                "transition_guard": "complete_step_requires_final_audit",
            })
        return self._resolve_and_commit_effective_transition(
            trigger_node,
            {"task_id": task_id, "current_step_id": step_id},
            update,
            task_id,
        )

    def _resolve_resume_node(
        self,
        task_id: str,
        values: Optional[Dict[str, Any]] = None,
        *,
        consume_pending_recovery: bool = True,
        preview_pending_recovery: bool = False,
    ) -> Tuple[str, Dict[str, Any]]:
        """Resolve recovery from durable business state, never from failure_stage alone."""
        values = dict(values or {})
        plan_state = load_plan_state(self.data_path, task_id)
        task_state = dict(plan_state.get("task_state") or {})
        recovery_store = RecoveryStateStore(self.data_path, task_id)
        persisted_recovery = recovery_store.load_phase()
        recovery_state = self._merge_recovery_phase_evidence(
            task_state.get("recovery_state") or {},
            persisted_recovery,
        )
        durable_task_spec = canonical_task_spec_for_state(plan_state)
        # Resume must not promote a parser/fallback projection to canonical
        # truth.  An uninitialized or legacy semantic-empty task returns to
        # Consultant with its durable conversation evidence.
        task_spec = (
            ensure_task_spec(durable_task_spec, "", task_id=task_id)
            if task_spec_is_initialized(durable_task_spec)
            else {}
        )
        task_revision = task_spec_revision(task_spec)
        selected_skills = list(
            values.get("selected_skills")
            or plan_state.get("selected_skill_ids")
            or [
                skill_id
                for step in plan_state.get("steps", []) or []
                if isinstance(step, dict)
                for skill_id in step.get("skill_ids", []) or []
                if str(skill_id).strip()
            ]
        )
        selected_skills = list(dict.fromkeys(str(item) for item in selected_skills if str(item).strip()))
        waiting = load_waiting_state(self.data_path, task_id)
        pending_question = values.get("pending_human_question") or task_state.get("pending_question") or {}
        pending_action = values.get("pending_action") or task_state.get("pending_action") or {}
        recovery_resolved = self._recovery_state_is_resolved(recovery_state)
        pending_recovery_action = (
            {}
            if recovery_resolved
            else values.get("pending_recovery_action") or recovery_state.get("pending_action") or {}
        )
        validation = validate_plan_for_generate(plan_state, task_revision)
        steps = [step for step in plan_state.get("steps", []) or [] if isinstance(step, dict)]
        statuses = {str(step.get("status") or "").lower() for step in steps}
        durable_task_status = task_status(plan_state)
        recovery_phase = str(recovery_state.get("phase") or "").lower()
        recovery_action_type = str(pending_recovery_action.get("type") or "").lower() if isinstance(pending_recovery_action, dict) else ""
        active_or_pending = bool(statuses & {
            "pending", "ready", "running", "diagnosing", "repairing",
            "retry_pending", "verification_pending",
        })
        pending_action_id = str((pending_action or {}).get("action_id") or "")
        attempt_resume = (
            classify_attempt_resume(
                plan_state,
                step_id=str((pending_action or {}).get("step_id") or ""),
                action_id=pending_action_id,
                plan_id=str(
                    (pending_action or {}).get("plan_id")
                    or plan_state.get("plan_id")
                    or ""
                ),
                plan_version=str(
                    (pending_action or {}).get("plan_version")
                    or plan_state.get("plan_version")
                    or ""
                ),
                execution_epoch=(pending_action or {}).get("execution_epoch", ""),
            )
            if pending_action_id
            else {
                "route": "none",
                "attempt": {},
                "create_new_attempt": True,
                "reason": "current_action_identity_missing",
            }
        )
        consultation_owner = dict(
            values.get("consultation_state")
            or task_state.get("consultation_state")
            or {}
        )
        resume_finalize_protocol = dict(
            consultation_owner.get("finalize_protocol") or {}
        )
        resume_protocol_schema = int(
            resume_finalize_protocol.get("schema_version") or 0
        )
        resume_compile_outcome = dict(
            resume_finalize_protocol.get("compile_outcome") or {}
        )
        finalize_compiled_for_planner = bool(
            resume_protocol_schema == 4
            and str(
                resume_finalize_protocol.get("finalize_status") or ""
            ) == "compiled"
            and str(resume_compile_outcome.get("status") or "")
            == "compiled"
        )
        resume_finalize_status = str(
            resume_finalize_protocol.get("finalize_status")
            or resume_finalize_protocol.get("status")
            or ""
        ).strip().lower()
        finalize_owner_present = bool(
            resume_finalize_protocol
            or str(consultation_owner.get("phase") or "").strip().lower()
            == "finalize"
        )
        finalize_owner_blocked = bool(
            resume_finalize_status
            in {
                "blocked", "blocked_internal_contract",
                "blocked_internal_provider",
            }
            or str(consultation_owner.get("phase") or "").strip().lower()
            == "blocked"
        )
        # A stale plan/task projection must never outrank an in-flight FINALIZE
        # owner.  Frozen legacy compiled state also returns through Consultant
        # once so its protected artifact chain can be verified before Planner.
        finalize_owner_requires_consultant = bool(
            finalize_owner_present
            and not finalize_owner_blocked
            and not finalize_compiled_for_planner
        )
        legacy_bootstrap_recovery = bool(
            not task_spec_is_initialized(task_spec)
            and str((plan_state.get("audit_index") or {}).get("raw_submission_ref") or "")
        )

        active_transition = dict(recovery_state.get("active_transition") or {})
        active_transition_pending = bool(
            str(active_transition.get("status") or "").strip().lower() == "pending"
        )
        if preview_pending_recovery and active_transition_pending:
            preview_route = str(
                active_transition.get("target_route")
                or active_transition.get("next_route")
                or "supervisor"
            ).strip().lower()
            # Plain-continue classification must resume even when the pending
            # transition will ultimately block.  Only the real resume path may
            # consume and dispatch the one-shot transition.
            node = preview_route if preview_route in {
                "consultant", "planner", "ask_user", "execute", "install_subagent",
                "supervisor", "supervisor_final_audit", "generate",
            } else "supervisor"
            return node, {
                "task_id": task_id,
                "resume_mode": "pending_recovery_transition_preview",
                "resolved_resume_node": node,
                "resume_reason": "pending_recovery_transition_preview",
                "override_decision_id": str(
                    active_transition.get("decision_id")
                    or active_transition.get("idempotency_key")
                    or ""
                ),
                "plan_validation": validation,
                "attempt_resume": attempt_resume,
            }

        resumed_transition = (
            self._consume_pending_recovery_on_resume(task_id, plan_state)
            if consume_pending_recovery and active_transition_pending
            else {}
        )
        if resumed_transition.get("recovery_transition_consumed") is True:
            resumed_plan = load_plan_state(self.data_path, task_id)
            resumed_index, resumed_step = current_plan_step_with_index(resumed_plan)
            dispatch_route = str(
                resumed_transition.get("dispatch_route")
                or resumed_transition.get("next_step")
                or "finish"
            )
            node = dispatch_route if dispatch_route in {
                "consultant", "planner", "ask_user", "execute", "install_subagent",
                "supervisor", "supervisor_final_audit", "generate",
            } else "finish"
            resumed_recovery = dict(
                (resumed_plan.get("task_state") or {}).get("recovery_state") or {}
            )
            return node, {
                "task_id": task_id,
                "resume_mode": "pending_recovery_transition",
                "task_status": task_status(resumed_plan),
                "task_revision": task_revision,
                "plan_revision": int(resumed_plan.get("plan_revision") or 0),
                "plan_status": str(resumed_plan.get("plan_status") or ""),
                "approved_plan_hash": str(resumed_plan.get("approved_plan_hash") or ""),
                "current_step_id": str(resumed_step.get("step_id") or ""),
                "current_step_index": resumed_index,
                "selected_skill_ids": selected_skills,
                "resolved_resume_node": node,
                "resume_reason": "consumed_pending_recovery_transition",
                "recovery_phase": str(resumed_recovery.get("phase") or ""),
                "recovery_status": str(resumed_recovery.get("status") or ""),
                "route_event_id": str(resumed_transition.get("route_event_id") or ""),
                "override_decision_id": str(
                    resumed_transition.get("override_decision_id") or ""
                ),
                "resume_execution_evidence": deepcopy(dict(
                    resumed_transition.get("execution_evidence") or {}
                )),
                "resume_reconciliation_evidence": deepcopy(dict(
                    resumed_transition.get("reconciliation_evidence") or {}
                )),
                "plan_validation": validation,
                "attempt_resume": attempt_resume,
            }
        if consume_pending_recovery and active_transition_pending:
            # The attempted transition was stale, malformed, or otherwise not
            # consumed.  Re-resolve from the now-current durable Plan without
            # previewing (and therefore without dispatching) its old target.
            return self._resolve_resume_node(
                task_id,
                values,
                consume_pending_recovery=False,
                preview_pending_recovery=False,
            )

        if durable_task_status == TASK_STATUS_CANCELLED:
            node = "finish"
            reason = "task_cancelled"
        elif legacy_bootstrap_recovery:
            node = "consultant"
            reason = "legacy_uninitialized_taskspec_recovery"
        elif durable_task_status in {TASK_STATUS_BLOCKED, TASK_STATUS_FAILED}:
            node = "finish"
            reason = "legacy_terminal_state" if active_or_pending else f"task_{durable_task_status}"
        elif recovery_phase in {"blocked", "exhausted"} or recovery_action_type == "blocked":
            node = "finish"
            reason = "legacy_terminal_recovery_with_active_steps" if active_or_pending else "recovery_terminal_without_new_evidence"
        elif finalize_owner_blocked:
            node = "finish"
            reason = "finalize_owner_terminal_block"
        elif finalize_owner_requires_consultant:
            node = "consultant"
            reason = "versioned_finalize_required_before_planner"
        elif durable_task_status == TASK_STATUS_COMPLETED:
            node = "finish"
            reason = "task_already_terminal"
        elif "verification_pending" in statuses or str(task_state.get("resume_route_hint") or "") == "supervisor":
            node = "supervisor"
            reason = "successful_execution_requires_supervisor_verification"
        elif attempt_resume.get("route") in {
            "monitor_running_attempt", "reconcile_attempt", "supervisor", "transition_guard",
        }:
            node = "execute"
            reason = str(attempt_resume.get("reason") or "resume_durable_attempt")
        elif pending_action and not self._validate_pending_action_contract(
            pending_action,
            {**values, "task_spec": task_spec, "task_revision": task_revision},
            task_id,
        ):
            node = "execute"
            reason = "fresh_pending_action"
        elif pending_question:
            node = "ask_user"
            reason = "pending_user_question"
        elif self._business_waiting_state(waiting):
            node = "waiting_user"
            reason = "saved_human_input_required"
        elif str(recovery_state.get("status") or "") == "PROMPT_ASSEMBLY_FAILURE":
            node = "finish"
            reason = "prompt_assembly_failure_blocked"
        elif recovery_phase in {
            "capture", "unwrap", "diagnose", "probe", "plan_repair", "apply_repair", "rerun", "verify", "rollback"
        } or pending_recovery_action:
            node = "generate"
            reason = "resume_persisted_local_recovery"
        elif steps and statuses and statuses <= {"done", "passed", "skipped", "skipped_upstream_blocked", "cancelled"}:
            node = "finish"
            reason = "task_already_terminal"
        elif validation.get("valid"):
            node = "generate"
            reason = "approved_valid_plan"
        elif steps and validation.get("reason_code") == "plan_not_approved":
            node = "plan_review"
            reason = "plan_requires_approval"
        elif str(task_spec.get("goal") or "").strip() and selected_skills:
            if finalize_compiled_for_planner:
                node = "planner"
                reason = "compiled_task_spec_and_skills_without_valid_plan"
            else:
                node = "consultant"
                reason = "versioned_finalize_required_before_planner"
        else:
            node = "consultant"
            reason = "task_requires_consultation"

        failure = plan_state.get("failure") if isinstance(plan_state.get("failure"), dict) else {}
        current_step_index, current_step = current_plan_step_with_index(plan_state)
        audit = {
            "task_id": task_id,
            "resume_mode": "business_state",
            "task_status": (
                TASK_STATUS_BLOCKED
                if recovery_phase in {"blocked", "exhausted"} or recovery_action_type == "blocked"
                else durable_task_status
            ),
            "task_revision": task_revision,
            "plan_revision": int(plan_state.get("plan_revision") or 0),
            "plan_status": str(plan_state.get("plan_status") or ""),
            "approved_plan_hash": str(plan_state.get("approved_plan_hash") or ""),
            "current_step_id": str(current_step.get("step_id") or ""),
            "current_step_index": current_step_index,
            "selected_skill_ids": selected_skills,
            "finalize_protocol_schema": resume_protocol_schema,
            "finalize_compiled_for_planner": finalize_compiled_for_planner,
            "finalize_owner_requires_consultant": (
                finalize_owner_requires_consultant
            ),
            "resolved_input_count": len(task_spec.get("inputs", []) or []),
            "failure_stage": str(failure.get("failure_stage") or values.get("failure_stage") or ""),
            "recovery_phase": str(recovery_state.get("phase") or ""),
            "recovery_status": str(recovery_state.get("status") or ""),
            "resolved_resume_node": node,
            "resume_reason": reason,
            "plan_validation": validation,
            "attempt_resume": attempt_resume,
        }
        return node, audit

    async def _resume_durable_attempt_update(
        self,
        task_id: str,
        state: AgentState,
    ) -> Optional[Dict[str, Any]]:
        """Reconcile one persisted active attempt without allocating a replacement."""
        plan_state = load_plan_state(self.data_path, task_id)
        task_state = dict(plan_state.get("task_state") or {})
        pending_action = dict(
            state.get("pending_action")
            or task_state.get("pending_action")
            or {}
        )
        resume_identity = {
            "step_id": str(pending_action.get("step_id") or ""),
            "action_id": str(pending_action.get("action_id") or ""),
            "plan_id": str(pending_action.get("plan_id") or plan_state.get("plan_id") or ""),
            "plan_version": str(
                pending_action.get("plan_version") or plan_state.get("plan_version") or ""
            ),
            "execution_epoch": pending_action.get("execution_epoch", ""),
        }
        if not resume_identity["action_id"]:
            # Resume is legal only for the exact current action.  An orphaned
            # attempt without a durable current-action identity is not
            # permission to execute or resume it.
            return None
        resume = classify_attempt_resume(plan_state, **resume_identity)
        if resume.get("create_new_attempt") or not resume.get("attempt"):
            return None

        while resume.get("route") == "monitor_running_attempt":
            await asyncio.sleep(1.0)
            plan_state = load_plan_state(self.data_path, task_id)
            resume = classify_attempt_resume(plan_state, **resume_identity)

        attempt = dict(resume.get("attempt") or {})
        attempt_id = str(attempt.get("attempt_id") or "")
        action_id = str(attempt.get("action_id") or "")
        provenance = dict(plan_state.get("provenance_state") or {})
        action = dict((provenance.get("actions") or {}).get(action_id) or {})
        if resume.get("route") == "transition_guard":
            evidence_ref = str(
                attempt.get("validation_evidence_ref")
                or attempt.get("execution_record_id")
                or f"attempt:{attempt_id}"
            )
            return {
                "messages": [SystemMessage(content=(
                    "Recovered a validated attempt whose plan transition was not committed. "
                    f"attempt_id={attempt_id}."
                ))],
                "pending_action": {},
                "step_completion_candidate": {
                    "type": "step_completion_candidate",
                    "step_id": str(attempt.get("step_id") or action.get("step_id") or ""),
                    "reason": "Persisted ValidationEvidence satisfies the interrupted step transition.",
                    "evidence_ids": [evidence_ref],
                    "attempt_id": attempt_id,
                },
                "next_step": "generate",
            }
        exit_status_path = Path(str(attempt.get("exit_status_path") or ""))
        exit_record: Dict[str, Any] = {}
        if exit_status_path.is_file():
            try:
                exit_record = json.loads(exit_status_path.read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError):
                exit_record = {}
        returncode = exit_record.get("returncode", attempt.get("returncode"))
        try:
            returncode = int(returncode) if returncode is not None else None
        except (TypeError, ValueError):
            returncode = None

        def read_tail(path_value: Any, limit: int = 16_000) -> str:
            path = Path(str(path_value or ""))
            try:
                payload = path.read_bytes()
            except OSError:
                return ""
            return payload[-limit:].decode("utf-8", errors="replace")

        stdout = read_tail(attempt.get("stdout_path"))
        stderr = read_tail(attempt.get("stderr_path"))
        recovery_store = RecoveryStateStore(self.data_path, task_id)
        immutable_failure = recovery_store.load_attempt_failure_evidence(attempt_id)
        if immutable_failure:
            if returncode is None and immutable_failure.get("exit_code") is not None:
                try:
                    returncode = int(immutable_failure["exit_code"])
                except (TypeError, ValueError):
                    returncode = None
            stdout = stdout or str(immutable_failure.get("bounded_stdout_excerpt") or "")
            stderr = stderr or str(immutable_failure.get("bounded_stderr_excerpt") or "")
        attempt_status = str(attempt.get("status") or "").upper()
        if returncode is None and attempt_status != ATTEMPT_UNKNOWN_AFTER_CRASH:
            record_provenance_event(plan_state, "attempt_state_changed", {
                "attempt_id": attempt_id,
                "status": ATTEMPT_UNKNOWN_AFTER_CRASH,
                "finished_at": datetime.now().isoformat(timespec="seconds"),
            })
        elif returncode is not None and attempt_status in {ATTEMPT_STARTING, ATTEMPT_RUNNING, ATTEMPT_UNKNOWN_AFTER_CRASH}:
            record_provenance_event(plan_state, "attempt_state_changed", {
                "attempt_id": attempt_id,
                "status": ATTEMPT_PROCESS_EXITED,
                "returncode": returncode,
                "finished_at": str(exit_record.get("finished_at") or datetime.now().isoformat(timespec="seconds")),
            })
        evidence = {
            "execution_id": f"exec-{attempt_id}",
            "attempt_id": attempt_id,
            "action_id": action_id,
            "plan_id": str(plan_state.get("plan_id") or ""),
            "plan_version": str(attempt.get("plan_version") or plan_state.get("plan_version") or ""),
            "step_id": str(attempt.get("step_id") or action.get("step_id") or ""),
            "stage_id": str(attempt.get("stage_id") or action.get("stage_id") or ""),
            "command_role": str(attempt.get("command_role") or action.get("command_role") or "primary"),
            "action_source": str(action.get("source") or "resume"),
            "execution_status": "succeeded" if returncode == 0 else "failed" if returncode is not None else "unknown",
            "returncode": returncode,
            "stdout_summary": self._clip_observation_text(stdout, 2000),
            "stderr_summary": self._clip_observation_text(stderr, 2000),
            "stdout_log": str(attempt.get("stdout_path") or ""),
            "stderr_log": str(attempt.get("stderr_path") or ""),
            "exit_status_path": str(exit_status_path) if str(exit_status_path) != "." else "",
            "generated_script": dict(attempt.get("generated_script") or action.get("generated_script") or {}),
            "approved_script": dict(attempt.get("approved_script") or {}),
            "executed_script": dict(attempt.get("executed_script") or {}),
            "script_file": str(attempt.get("executed_script_path") or ""),
            "finished_at": str(exit_record.get("finished_at") or attempt.get("finished_at") or ""),
            "resumed_after_crash": True,
        }
        if returncode not in {None, 0} and not immutable_failure:
            # A controller crash may happen after the process writes its exit
            # status but before Execute commits the immutable snapshot.  Resume
            # closes that exact durability gap without re-running the action.
            recovered_failure = AttemptFailureEvidence.from_mapping({
                **evidence,
                "session_id": str(state.get("session_id") or task_id),
                "task_id": task_id,
                "failed_command": str(
                    attempt.get("command")
                    or action.get("command")
                    or action.get("code")
                    or ""
                ),
                "expected_runtime": dict(
                    attempt.get("runtime_snapshot")
                    or action.get("runtime_snapshot")
                    or {}
                ),
                "actual_runtime": dict(attempt.get("actual_environment") or {}),
                "diagnostic_code": "RECOVERED_PROCESS_FAILURE",
                "diagnostic_summary": (
                    "The persisted process exit was non-zero; Resume captured "
                    "the available per-attempt evidence without rerunning it."
                ),
            })
            failure_path = recovery_store.save_attempt_failure_evidence(
                recovered_failure
            )
            immutable_failure = recovered_failure.to_dict()
            evidence["failure_evidence_path"] = str(failure_path)
        for key, value in immutable_failure.items():
            if key not in evidence or evidence.get(key) in (None, "", [], {}):
                evidence[key] = deepcopy(value)
        if immutable_failure:
            snapshot_aliases = {
                "command": immutable_failure.get("failed_command"),
                "failed_command": immutable_failure.get("failed_command"),
                "stdout_log": immutable_failure.get("stdout_ref"),
                "stderr_log": immutable_failure.get("stderr_ref"),
                "trace_file": immutable_failure.get("trace_ref"),
                "stdout_summary": immutable_failure.get("bounded_stdout_excerpt"),
                "stderr_summary": immutable_failure.get("bounded_stderr_excerpt"),
                "expected_runtime_contract": immutable_failure.get("expected_runtime"),
                "actual_environment": immutable_failure.get("actual_runtime"),
            }
            for key, value in snapshot_aliases.items():
                if evidence.get(key) in (None, "", [], {}) and value not in (
                    None, "", [], {},
                ):
                    evidence[key] = deepcopy(value)
            evidence["failure_evidence_path"] = str(
                recovery_store.root.parent
                / "attempts"
                / re.sub(r"[^A-Za-z0-9_.-]+", "_", attempt_id)
                / "failure_evidence.json"
            )
        if returncode is not None and attempt_status != ATTEMPT_EVIDENCE_COMMITTED:
            record = ExecutionRecord.from_mapping(evidence)
            execution_record_path = recovery_store.save_execution_record(record)
            evidence["execution_record_path"] = str(execution_record_path)
            record_provenance_event(plan_state, "execution_finished", {
                "attempt_id": attempt_id,
                "execution_record": {**evidence, **record.summary()},
            })
            task_state = dict(plan_state.get("task_state") or {})
            task_state["pending_action"] = {}
            plan_state["task_state"] = task_state
        save_plan_state(self.data_path, task_id, plan_state)
        return {
            "messages": [SystemMessage(content=(
                "Recovered a persisted execution attempt without rerunning it. "
                f"attempt_id={attempt_id} returncode={returncode!r}."
            ))],
            "execution_evidence": evidence,
            "pending_action": {},
            "pending_recovery_action": ({
                "type": "revalidate",
                "reason": "The process ended without a trustworthy external exit record.",
                "failure_owner": RecoveryFailureOwner.VERIFICATION.value,
                "requires_user_input": False,
            } if returncode is None else {}),
            "required_next_action": "REVALIDATE" if returncode is None else "",
            "next_step": "supervisor",
        }

    def _build_resume_runner_state(
        self,
        task_id: str,
        user_prompt: Any = "",
        checkpoint_values: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        values = dict(checkpoint_values or {})
        plan_state = load_plan_state(self.data_path, task_id)
        task_state = dict(plan_state.get("task_state") or {})
        recovery_store = RecoveryStateStore(self.data_path, task_id)
        persisted_recovery = recovery_store.load_phase()
        recovery_state = self._merge_recovery_phase_evidence(
            task_state.get("recovery_state") or {},
            persisted_recovery,
        )
        recovery_resolved = self._recovery_state_is_resolved(recovery_state)
        task_record = self._persistent_task_record(task_id)
        original_query = str(task_record.get("user_query") or "")
        durable_task_spec = canonical_task_spec_for_state(plan_state)
        task_spec = (
            ensure_task_spec(durable_task_spec, "", task_id=task_id)
            if task_spec_is_initialized(durable_task_spec)
            else {}
        )
        task_revision = task_spec_revision(task_spec)
        selected_skills = list(values.get("selected_skills") or task_state.get("selected_skills") or plan_state.get("selected_skill_ids") or [])
        consultation_state = deepcopy(dict(
            values.get("consultation_state")
            or task_state.get("consultation_state")
            or {}
        ))
        if not selected_skills:
            selected_skills = list(dict.fromkeys(
                str(skill_id)
                for step in plan_state.get("steps", []) or []
                if isinstance(step, dict)
                for skill_id in step.get("skill_ids", []) or []
                if str(skill_id).strip()
            ))
        plan_file = Path(str(plan_state.get("plan_file") or default_plan_file(self.data_path, task_id)))
        try:
            current_plan = plan_file.read_text(encoding="utf-8")
        except OSError:
            current_plan = str(values.get("current_plan") or "")
        node, audit = self._resolve_resume_node(
            task_id,
            {
                **values,
                "task_spec": task_spec,
                "task_revision": task_revision,
                "selected_skills": selected_skills,
                "consultation_state": consultation_state,
            },
        )
        # The resume resolver may atomically consume a one-shot transition.
        # Re-read its durable lifecycle before projecting runner state; using
        # the pre-consume snapshot would resurrect pending route authority.
        plan_state = load_plan_state(self.data_path, task_id)
        task_state = dict(plan_state.get("task_state") or {})
        persisted_recovery = recovery_store.load_phase()
        recovery_state = self._merge_recovery_phase_evidence(
            task_state.get("recovery_state") or {},
            persisted_recovery,
        )
        recovery_resolved = self._recovery_state_is_resolved(recovery_state)
        consumed_transition = dict(
            recovery_state.get("last_consumed_transition") or {}
        )
        reconciliation_evidence = (
            {
                "decision_id": str(
                    consumed_transition.get("decision_id")
                    or consumed_transition.get("idempotency_key")
                    or ""
                ),
                "attempt_id": str(
                    consumed_transition.get("attempt_id")
                    or consumed_transition.get("trigger_event_id")
                    or ""
                ),
                "step_id": str(consumed_transition.get("step_id") or ""),
                "status": str(consumed_transition.get("status") or "consumed"),
                "evidence": list(consumed_transition.get("evidence") or []),
                "reason": str(consumed_transition.get("reason") or ""),
            }
            if str(consumed_transition.get("kind") or "")
            == RecoveryDecisionKind.ACCEPT_EXECUTION_FOR_VERIFICATION.value
            else {}
        )
        project_id = str(values.get("project_id") or self.default_project_id)
        stable_record = self._get_or_create_stable_prompt(task_id, project_id)
        resume_message = str(user_prompt or "").strip()
        messages = list(values.get("messages") or [])
        if not messages:
            if not values.get("messages"):
                messages = [HumanMessage(content=str(task_spec.get("goal") or original_query or resume_message))]
        messages.append(SystemMessage(content=f"<resume_audit>\n{json.dumps(audit, ensure_ascii=False)}\n</resume_audit>"))
        logger.info("Resume state resolved: %s", json.dumps(audit, ensure_ascii=False, sort_keys=True))
        runner_state = {
            **values,
            "messages": messages,
            "task_id": task_id,
            "session_id": task_id,
            "project_id": project_id,
            "stable_system_prompt": stable_record["prompt"],
            "core_memory_loaded_at": stable_record["core_memory_loaded_at"],
            "task_mode": str(values.get("task_mode") or "managed"),
            "task_spec": task_spec,
            "task_revision": task_revision,
            "current_plan": current_plan,
            "plan_progress": render_plan_progress(plan_state),
            "selected_skills": selected_skills,
            "selected_skills_raw": list(values.get("selected_skills_raw") or selected_skills),
            "active_skills": list(values.get("active_skills") or []),
            "consultation_state": consultation_state,
            "conversation_evidence": deepcopy(dict(plan_state.get("conversation_evidence") or {})),
            "resolved_bindings": deepcopy(dict(
                values.get("resolved_bindings")
                or task_state.get("resolved_bindings")
                or {}
            )),
            "planner_feedback": deepcopy(dict(
                values.get("planner_feedback")
                or task_state.get("planner_feedback")
                or {}
            )),
            "consultant_contract_repair": deepcopy(dict(
                values.get("consultant_contract_repair")
                or task_state.get("consultant_contract_repair")
                or {}
            )),
            "contract_status": str(
                values.get("contract_status")
                or task_state.get("contract_status")
                or ""
            ),
            "runtime_status": values.get("runtime_status") or self._runtime_status_for_task(task_id),
            "runtime_audit": values.get("runtime_audit") or task_state.get("runtime_audit") or [],
            "input_audit": values.get("input_audit") or task_state.get("input_audit") or {},
            "pending_action": values.get("pending_action") or task_state.get("pending_action") or {},
            "pending_human_question": values.get("pending_human_question") or task_state.get("pending_question") or {},
            "execution_evidence": (
                audit.get("resume_execution_evidence")
                or values.get("execution_evidence")
                or {}
            ),
            "pending_recovery_action": (
                {}
                if recovery_resolved
                else values.get("pending_recovery_action") or recovery_state.get("pending_action") or {}
            ),
            "recovery_phase": (
                None if recovery_resolved else recovery_state.get("phase") or values.get("recovery_phase")
            ),
            "recovery_context": (
                {}
                if recovery_resolved
                else values.get("recovery_context")
                or {
                    "context_ref": str(recovery_store.root / "recovery_context.json"),
                    "context_id": str(recovery_state.get("context_id") or ""),
                    "error_fingerprint": str(recovery_state.get("error_fingerprint") or ""),
                }
            ),
            "diagnostic_summary": (
                {} if recovery_resolved else values.get("diagnostic_summary") or recovery_store.load_diagnostic_summary()
            ),
            "reconciliation_evidence": (
                audit.get("resume_reconciliation_evidence")
                or values.get("reconciliation_evidence")
                or reconciliation_evidence
            ),
            "resume_mode": "business_state",
            "resolved_resume_node": node,
            "resume_audit": audit,
            "recovery_status": recovery_state.get("status") or "resuming",
            "recovery_decision": (
                {}
                if recovery_resolved
                else values.get("recovery_decision") or {}
            ),
            "next_step": node,
        }
        if recovery_resolved and audit.get("resume_reason") == "approved_valid_plan":
            runner_state.update({
                "supervisor_verdict": "",
                "last_supervisor_feedback": {},
                "retry_count": 0,
                "recovery_decision": {},
                "forbidden_recovery_actions": [],
                "observation": "",
                "execution_evidence": {},
                "failure_stage": "",
                "failure_owner": "",
                "error_analysis": "",
            })
            for field in SUPERVISOR_RETRY_FIELDS:
                runner_state[field] = ""
        return runner_state

    def _continue_control_state(self, task_id: str) -> Dict[str, Any]:
        """Classify plain 'continue' without turning it into task content."""
        task_record = self._persistent_task_record(task_id)
        has_plan = plan_state_path(self.data_path, task_id).exists()
        if not task_record and not has_plan:
            return {"action": "new_task"}
        waiting = load_waiting_state(self.data_path, task_id)
        if self._business_waiting_state(waiting):
            return {"action": "waiting_user", "waiting": waiting}
        resume_node, audit = self._resolve_resume_node(
            task_id,
            consume_pending_recovery=False,
            preview_pending_recovery=True,
        )
        if resume_node == "finish":
            return {"action": "completed", "resume_audit": audit}
        return {"action": "resume", "resume_audit": audit}

    def _wiki_disabled_message(self) -> str:
        return (
            "Wiki memory is disabled (BIOMIND_WIKI_ENABLED=false). "
            "BioMind will use SessionArchive, TaskSummary, Core memory, and verified filesystem evidence instead."
        )

    def _wiki_prompt_context(self, task_id: str, project_id: str, query: str) -> str:
        if not self.wiki_enabled or not query.strip():
            return ""
        try:
            return self.wiki_memory_manager.build_prompt_context(
                task_id=task_id,
                project_id=project_id,
                query=query,
            )
        except Exception as e:
            logger.warning(f"Wiki memory retrieval failed for {task_id}: {e}")
            return ""

    def _wiki_memory_stage_context(
        self,
        task_id: str,
        project_id: str,
        query: str,
        digest_chars: int = 2_000,
        context_chars: int = 4_000,
    ) -> str:
        if not self.wiki_enabled:
            return ""
        parts = []
        digest = self._wiki_digest_prompt_context(project_id, max_chars=digest_chars)
        if digest:
            parts.append(f"<wiki_digest>\n{digest}\n</wiki_digest>")
        wiki_context = self._wiki_prompt_context(task_id, project_id, query)
        if wiki_context:
            parts.append(f"<wiki_context>\n{self._clip_prompt_text(wiki_context, context_chars)}\n</wiki_context>")
        if not parts:
            return ""
        policy = (
            "<wiki_memory_policy>\n"
            "- wiki_purpose is direction-setting context, not factual evidence.\n"
            "- Wiki claims with evidence are preferred for project facts, dataset paths, methods, parameters, and conclusions.\n"
            "- If Wiki and Core memory conflict, verify filesystem/evidence and prefer current input/latest observations over stale memory.\n"
            "- This context is read-only; do not compile or write wiki pages during consultant/planner/generate.\n"
            "</wiki_memory_policy>"
        )
        return policy + "\n\n" + "\n\n".join(parts)

    @staticmethod
    def _dedupe_current_query_from_retrieval(text: str, query: str) -> str:
        """Replace an exact current-request replay with an authority pointer."""
        value = str(text or "")
        current = str(query or "").strip()
        if len(current) < 120 or current not in value:
            return value
        return value.replace(
            current,
            "[current request omitted here; use the lossless Human message and canonical TaskSpec above]",
        )

    async def _consultant_memory_retrieval_context(
        self,
        task_id: str,
        project_id: str,
        query: str,
        wiki_context: str,
        *,
        archive_context: Optional[str] = None,
    ) -> str:
        """Build the full retrieval bundle shown only to Consultant."""
        sections: List[str] = [
            "<memory_broker_policy>\n"
            "- Consultant is the only broad automatic memory retrieval stage for managed tasks.\n"
            "- Curate relevant facts into the FINISH handoff; do not copy all retrieved text forward.\n"
            "- Planner and Generate should consume the curated handoff packet and request targeted retrieval only when information is missing.\n"
            "</memory_broker_policy>"
        ]
        if wiki_context.strip():
            wiki_context = self._dedupe_current_query_from_retrieval(wiki_context, query)
            sections.append(f"<wiki_memory_retrieval>\n{wiki_context}\n</wiki_memory_retrieval>")

        # TaskSummary and generic archive renderers contain old prompts, commands,
        # and transcripts. Consultant receives only typed durable projections.
        if archive_context is None:
            archive_context = self._consultant_archive_facts_context(
                query=query,
                project_id=project_id,
                exclude_task_id=task_id,
                limit=4,
            )
        if archive_context.strip():
            archive_context = self._dedupe_current_query_from_retrieval(archive_context, query)
            sections.append(
                "<project_session_archive_retrieval>\n"
                f"{archive_context}\n"
                "</project_session_archive_retrieval>"
            )

        return "\n\n".join(sections)

    def _consultant_archive_facts_context(
        self,
        *,
        query: str,
        project_id: str,
        exclude_task_id: str,
        limit: int = 4,
        raise_errors: bool = False,
    ) -> str:
        """Project archive hits to durable facts; never forward raw transcripts."""
        if not str(query or "").strip():
            return ""
        allowed_event_types = {
            "artifact_created",
            "error_detected",
            "supervisor_verdict",
            "task_finalized",
            "knowledge_conflict_resolved",
            "root_cause_analysis",
        }
        try:
            hits = self.session_archive.search(
                query,
                project_id=project_id,
                limit=max(limit * 4, limit),
            )
        except Exception as exc:
            logger.warning("Consultant structured archive retrieval failed for %s: %s", exclude_task_id, exc)
            if raise_errors:
                raise
            return ""
        rows: List[Dict[str, Any]] = []
        durable_keys = {
            "status", "root_cause", "root_cause_analysis", "failure_conclusion",
            "lesson", "lessons", "artifact_ref", "artifacts", "selected_skills",
            "constraint_summary", "conclusion", "verdict",
        }
        for hit in hits:
            if str(getattr(hit, "task_id", "")) == str(exclude_task_id):
                continue
            event_type = str(getattr(hit, "event_type", ""))
            if event_type not in allowed_event_types:
                continue
            metadata = dict(getattr(hit, "metadata", {}) or {})
            facts = {key: metadata[key] for key in durable_keys if key in metadata}
            summary = str(getattr(hit, "summary", "") or "").strip()
            row = {
                "evidence_ref": str(getattr(hit, "evidence_ref", "")),
                "task_id": str(getattr(hit, "task_id", "")),
                "event_type": event_type,
                "status": facts.pop("status", ""),
                "durable_facts": facts,
                "summary": self._clip_prompt_text(summary, 600) if summary else "",
                "paths": list(getattr(hit, "paths", []) or [])[:8],
            }
            rows.append(row)
            if len(rows) >= limit:
                break
        if not rows:
            return ""
        return json.dumps({"schema_version": 1, "durable_archive_facts": rows}, ensure_ascii=False, sort_keys=True, indent=2, default=str)

    def _record_consultant_progress(
        self,
        task_id: str,
        *,
        code: str,
        message: str,
        detail: Optional[Mapping[str, Any]] = None,
    ) -> None:
        """Emit observation-only progress without changing semantic authority."""

        safe_message = redact_lineage_text(message)[:500]
        safe_detail = {
            str(key): value
            for key, value in dict(detail or {}).items()
            if isinstance(value, (str, int, float, bool)) or value is None
        }
        try:
            self.profiler.record_consultant_progress(
                task_id,
                code=code,
                message=safe_message,
                detail=safe_detail,
            )
            ContextLineageStore(self.data_path, task_id).record_event(
                "consultant_progress",
                {
                    "code": str(code or "consultant_progress"),
                    "message": safe_message,
                    "detail": safe_detail,
                    "semantic_effect": "none",
                },
            )
        except Exception as exc:
            logger.warning(
                "Consultant progress telemetry failed open for %s: %s",
                task_id,
                type(exc).__name__,
            )

    def _finalize_consultant_commit_events(
        self,
        task_id: str,
        update: Mapping[str, Any],
        *,
        source: str,
        selected_skill_ids: Sequence[str] = (),
    ) -> Dict[str, Any]:
        """Resolve Consultant dispatch before emitting commit-success events."""
        resolved = dict(update or {})
        effective_route = str(
            resolved.get("effective_route")
            or resolved.get("next_step")
            or ""
        )
        dispatch_route = str(
            resolved.get("dispatch_route")
            or effective_route
        )
        resolved.setdefault(
            "proposed_route", str(resolved.get("next_step") or effective_route)
        )
        resolved["effective_route"] = effective_route
        resolved["dispatch_route"] = dispatch_route
        committed = dict(resolved.get("canonical_commit") or {})
        if committed.get("succeeded") is not True:
            return resolved

        selected = list(dict.fromkeys(
            str(value) for value in selected_skill_ids or [] if str(value)
        ))
        if selected:
            self._record_consultant_progress(
                task_id,
                code="CONSULTANT_SKILL_SELECTED",
                message=(
                    "Consultant committed documented compatible Skill capability."
                ),
                detail={
                    "selected_skill_count": len(selected),
                    "source": str(source or ""),
                },
            )
        if effective_route == "planner" and dispatch_route == "planner":
            self._record_consultant_progress(
                task_id,
                code="CONSULTANT_PLANNER_HANDOFF",
                message=(
                    "Canonical Consultant commit succeeded; handing the task "
                    "to Planner."
                ),
                detail={
                    "source": str(source or ""),
                    "task_revision": int(committed.get("task_revision") or 0),
                },
            )
        return resolved

    def _flush_consultant_preprocess_trace(
        self,
        task_id: str,
        recorder: ConsultantPreprocessRecorder,
    ) -> Dict[str, Any]:
        """Persist one secret-free measured preprocessing breakdown."""

        store = ContextLineageStore(self.data_path, task_id)
        initial_events = recorder.event_rows(
            include_phases=[
                row["phase"]
                for row in recorder.phase_rows()
                if row["phase"] != "context_trace_write"
            ]
        )
        started = time.perf_counter()
        try:
            store.record_events(initial_events)
            for row in recorder.phase_rows():
                if row["phase"] != "context_trace_write":
                    self.profiler.record_consultant_preprocess(task_id, {
                        "episode_id": recorder.episode_id,
                        "invocation": recorder.invocation,
                        **row,
                    })
            self.profiler.flush(task_id)
            elapsed_ms = (time.perf_counter() - started) * 1000
            recorder.mark(
                "context_trace_write",
                elapsed_ms=elapsed_ms,
                call_count=1,
                event_count=len(initial_events),
            )
            total = recorder.total_payload()
            store.record_events([
                *recorder.event_rows(include_phases=["context_trace_write"]),
                {"event_kind": "consultant_preprocess_total", "payload": total},
            ])
            self.profiler.record_consultant_preprocess(
                task_id,
                {
                    "episode_id": recorder.episode_id,
                    "invocation": recorder.invocation,
                    **next(
                        row for row in recorder.phase_rows()
                        if row["phase"] == "context_trace_write"
                    ),
                },
            )
            self.profiler.record_consultant_preprocess(task_id, total)
            self.profiler.flush(task_id)
            return total
        except Exception as exc:
            logger.warning(
                "Consultant preprocessing trace failed open for %s: %s",
                task_id,
                type(exc).__name__,
            )
            return recorder.total_payload()

    def _consultant_handoff_memory_packet(
        self,
        consultant_summary: str,
        retrieval_context: str,
    ) -> str:
        """Create the compact cross-stage memory packet after Consultant curates retrieval."""
        source_refs = self._memory_source_refs(retrieval_context)
        ref_lines = "\n".join(f"- {ref}" for ref in source_refs) if source_refs else "- none"
        return (
            "<consultant_memory_packet>\n"
            "<memory_packet_policy>\n"
            "- This packet is the primary memory handoff from Consultant to Planner and Generate.\n"
            "- It is curated primarily from Wiki and source SessionArchive evidence; TaskSummary is report/cache only.\n"
            "- If details are missing, request targeted retrieval instead of repeating broad automatic recall.\n"
            "</memory_packet_policy>\n\n"
            "<consultant_curated_handoff>\n"
            f"{self._clip_prompt_text(consultant_summary, 5000)}\n"
            "</consultant_curated_handoff>\n\n"
            "<memory_source_refs>\n"
            f"{ref_lines}\n"
            "</memory_source_refs>\n"
            "</consultant_memory_packet>"
        )

    @staticmethod
    def _planner_consultant_contract_projection(
        contract: Mapping[str, Any] | None,
    ) -> Dict[str, Any]:
        """Keep FINALIZE proof metadata without duplicating TaskSpec in Planner."""
        raw = dict(contract or {})
        if not raw:
            return {}
        constraints = [
            dict(item) for item in raw.get("constraints") or []
            if isinstance(item, Mapping)
        ]
        scope_counts = {"plan": 0, "runtime_global": 0, "context_only": 0}
        for item in constraints:
            scope_counts[semantic_constraint_enforcement_scope(item)] += 1
        keep = (
            "record_type", "schema_version", "artifact_schema_version",
            "protocol_schema_version", "wire_schema_version", "finalize_context_id",
            "base_contract_hash", "coverage_artifact_hash", "candidate_catalog_hash",
            "compile_mode", "compiled_contract_id", "compiled_contract_hash",
            "selected_skills",
        )
        projection = {
            key: deepcopy(raw.get(key))
            for key in keep
            if raw.get(key) not in (None, "", [], {})
        }
        projection["constraint_counts_by_scope"] = scope_counts
        projection["constraint_count"] = len(constraints)
        projection["contract_authority"] = (
            "Constraint details are projected once through the canonical TaskSpec context."
        )
        summary = str(raw.get("summary") or raw.get("requirements_summary") or "").strip()
        if summary:
            projection["summary"] = summary[:1500]
        return projection

    @staticmethod
    def _accepted_consultant_handoff_projection(
        source: Mapping[str, Any] | None,
    ) -> Dict[str, Any]:
        """Keep only the accepted semantic cross-node handoff."""
        raw = dict(source or {})
        task_spec = (
            dict(raw.get("task_spec") or {})
            if isinstance(raw.get("task_spec"), Mapping)
            else {}
        )
        summary = str(
            raw.get("summary") or raw.get("requirements_summary") or ""
        ).strip()
        projection: Dict[str, Any] = {}
        if summary:
            projection["summary"] = summary
        for key in (
            "goal_interpretation", "input_files", "required_outputs",
            "selected_skills", "capability_decisions",
            "runtime_requirements", "resolved_ambiguities",
            "unresolved_questions", "database_strategy",
        ):
            value = raw.get(key)
            if value not in (None, "", [], {}):
                projection[key] = deepcopy(value)

        # The accepted commit already contains the canonical interpretation.
        # Project only semantic fields, never candidate/provider/audit records.
        if task_spec and not projection.get("goal_interpretation"):
            goal = str(task_spec.get("goal") or "").strip()
            if goal:
                projection["goal_interpretation"] = goal
        if task_spec and not projection.get("input_files"):
            inputs = [
                {
                    key: deepcopy(item[key])
                    for key in ("role", "path", "format", "required")
                    if item.get(key) not in (None, "", [], {})
                }
                for item in task_spec.get("inputs", []) or []
                if isinstance(item, Mapping)
            ]
            if inputs:
                projection["input_files"] = inputs
        if task_spec and not projection.get("required_outputs"):
            outputs = [
                {
                    key: deepcopy(item[key])
                    for key in (
                        "role", "path", "format", "required", "path_policy",
                    )
                    if item.get(key) not in (None, "", [], {})
                }
                for item in (
                    task_spec.get("output_contracts")
                    or task_spec.get("outputs")
                    or []
                )
                if isinstance(item, Mapping)
            ]
            if outputs:
                projection["required_outputs"] = outputs
        if task_spec and not projection.get("unresolved_questions"):
            unresolved = deepcopy(list(task_spec.get("unresolved_questions") or []))
            if unresolved:
                projection["unresolved_questions"] = unresolved
        return projection

    @staticmethod
    def _memory_source_refs(text: str, limit: int = 24) -> List[str]:
        patterns = [
            r"\b(?:session_archive|task|artifact|raw):[A-Za-z0-9_.:/\\-]+",
            r"\[([A-Za-z0-9_.:/\\-]+\.md)\]",
        ]
        refs: List[str] = []
        seen: set[str] = set()
        for pattern in patterns:
            for match in re.finditer(pattern, str(text or "")):
                ref = match.group(1) if match.groups() else match.group(0)
                ref = ref.strip()
                if not ref or ref in seen:
                    continue
                seen.add(ref)
                refs.append(ref)
                if len(refs) >= limit:
                    return refs
        return refs

    def _wiki_digest_prompt_context(self, project_id: str, max_chars: int = 4_000) -> str:
        if not self.wiki_enabled:
            return ""
        try:
            digest_path = self.wiki_memory_manager.digest_path(project_id)
            if not digest_path.exists():
                return ""
            mtime = digest_path.stat().st_mtime
            cache_key = str(digest_path)
            cached = self._wiki_digest_cache.get(cache_key)
            if cached and cached[0] == mtime:
                return cached[1]

            data = json.loads(digest_path.read_text(encoding="utf-8"))
            text = self._format_wiki_digest(data)
            clipped = self._clip_prompt_text(text, max_chars)
            self._wiki_digest_cache[cache_key] = (mtime, clipped)
            return clipped
        except Exception as e:
            logger.warning(f"Wiki digest load failed for project {project_id}: {e}")
            return ""

    @staticmethod
    def _format_wiki_digest(data: Dict[str, Any]) -> str:
        page_types = data.get("page_types") if isinstance(data.get("page_types"), dict) else {}
        claims = data.get("high_confidence_claims")
        if not isinstance(claims, list):
            claims = []
        lines = [
            f"Project: {data.get('project_id', 'unknown')}",
            f"Updated: {data.get('updated_at', 'unknown')}",
            f"Pages: {data.get('page_count', 0)} | Claims: {data.get('claim_count', 0)} | Review items: {data.get('review_count', 0)}",
            f"Entities: {data.get('entity_count', 0)} | Concepts: {data.get('concept_count', 0)} | Research queries: {data.get('research_query_count', 0)}",
            "Page types: " + (", ".join(f"{key}={value}" for key, value in sorted(page_types.items())) or "none"),
        ]
        knowledge_pages = data.get("knowledge_pages")
        if isinstance(knowledge_pages, list) and knowledge_pages:
            lines.append("Entity/concept pages:")
            for page in knowledge_pages[:6]:
                if not isinstance(page, dict):
                    continue
                lines.append(f"- {page.get('path', '')}: {page.get('title', '')} ({page.get('type', '')})")
        lines.append("High-confidence claims:")
        if claims:
            for claim in claims[:8]:
                evidence = claim.get("evidence") if isinstance(claim, dict) else []
                if not isinstance(evidence, list):
                    evidence = []
                evidence_text = ", ".join(str(item) for item in evidence[:3]) or "none"
                lines.append(
                    f"- {claim.get('id', 'claim')}: {claim.get('text', '')} "
                    f"(page: {claim.get('page', 'unknown')}; evidence: {evidence_text})"
                )
        else:
            lines.append("- None compiled yet.")
        lines.append("Use wiki search/page retrieval for evidence; this digest is only a compact index.")
        return "\n".join(lines)

    def _ephemeral_prompt_context(
        self,
        state: AgentState,
        messages: List[BaseMessage],
        current_plan: str,
        loaded_skills: str,
        task_summary_context: Dict[str, str],
        memory_packet_context: str,
        wiki_context: str,
        wiki_digest: str,
        archive_context: str,
        supervisor_context: str,
        recovery_context: str = "",
        plan_progress: str = "",
    ) -> str:
        text, _ = self._ephemeral_prompt_context_result(
            state=state,
            messages=messages,
            current_plan=current_plan,
            loaded_skills=loaded_skills,
            task_summary_context=task_summary_context,
            memory_packet_context=memory_packet_context,
            wiki_context=wiki_context,
            wiki_digest=wiki_digest,
            archive_context=archive_context,
            supervisor_context=supervisor_context,
            recovery_context=recovery_context,
            plan_progress=plan_progress,
        )
        return text

    def _ephemeral_prompt_context_result(
        self,
        state: AgentState,
        messages: List[BaseMessage],
        current_plan: str,
        loaded_skills: str,
        task_summary_context: Dict[str, str],
        memory_packet_context: str,
        wiki_context: str,
        wiki_digest: str,
        archive_context: str,
        supervisor_context: str,
        recovery_context: str = "",
        plan_progress: str = "",
    ) -> Tuple[str, Dict[str, Any]]:
        rag_history_list = state.get("rag_history", []) or []
        inherited_rag = str(rag_history_list[-1]) if rag_history_list else ""
        work_dir = str(self.pm.work_dir if self.pm else self.data_path)
        runtime_audit_context = self._format_runtime_audit(
            list(state.get("runtime_audit", []) or [])
        )
        dynamic_tool_context = PromptManager.build_scoped_runtime_context(
            self._clip_prompt_text(runtime_audit_context, 3000),
            self.pm,
            work_dir,
        )
        return PromptManager.build_ephemeral_context_result(
            task_spec_context=self._generate_task_spec_projection(state, messages),
            rag_context=inherited_rag,
            history=messages,
            dynamic_tool_context=dynamic_tool_context,
            loaded_skills_instructions=loaded_skills,
            long_term_memory=task_summary_context.get("long_term_memory", ""),
            task_memory=task_summary_context.get("task_memory", ""),
            related_memory=task_summary_context.get("related_memory", ""),
            memory_packet_context=memory_packet_context,
            wiki_context=wiki_context,
            wiki_digest=wiki_digest,
            archive_context=archive_context,
            supervisor_context=supervisor_context,
            recovery_context=recovery_context,
            current_plan=current_plan,
            plan_progress=plan_progress,
            current_action_context=self._current_action_contract(state, str(state.get("task_id") or "default")),
            max_chars=LLM_STEP_EPHEMERAL_CHARS,
        )

    def _compact_generate_context_result(
        self,
        *,
        state: AgentState,
        messages: List[BaseMessage],
        current_plan: str,
        loaded_skills: str,
        supervisor_context: str,
        recovery_context: str = "",
    ) -> Tuple[str, Dict[str, Any]]:
        """Rebuild Generate from required business state after packing failure."""
        runtime_context = self._format_runtime_audit(list(state.get("runtime_audit", []) or []))
        text, report = PromptManager.build_ephemeral_context_result(
            task_spec_context=self._generate_task_spec_projection(state, messages),
            history=[],
            dynamic_tool_context=runtime_context or "No selected-skill runtime audit is available.",
            loaded_skills_instructions=loaded_skills,
            supervisor_context=supervisor_context,
            recovery_context=recovery_context,
            current_plan=current_plan,
            plan_progress="PlanTracker owns status; use the canonical CurrentStepContext above.",
            current_action_context=self._current_action_contract(state, str(state.get("task_id") or "default")),
            max_chars=LLM_STEP_EPHEMERAL_CHARS,
        )
        report = dict(report)
        report["projection_mode"] = "compact_required_state_retry"
        return text, report

    def _generate_task_spec_projection(
        self,
        state: AgentState,
        messages: List[BaseMessage],
    ) -> str:
        """Compatibility entrypoint backed by the V2 deterministic LLMPayload."""
        spec = self._task_spec_for_state(dict(state), messages)
        task_id = str(state.get("task_id") or "default")
        plan_state = load_plan_state(self.data_path, task_id)
        input_audit = state.get("input_audit") or (plan_state.get("task_state") or {}).get("input_audit") or {}
        if isinstance(input_audit, dict) and input_audit:
            spec = merge_task_spec_input_audit(spec, input_audit)
        _, current_step = current_plan_step_with_index(plan_state)
        protocol = self._renderer_action_protocol(state, task_id)
        context = build_node_context(
            node_type="generate",
            task_spec=spec,
            plan_state=plan_state,
            state_generation=int(plan_state.get("state_generation") or 0),
            current_step_id=str((current_step or {}).get("step_id") or ""),
            runtime={
                "progress": {
                    "current_step_status": str((current_step or {}).get("status") or "pending"),
                    "remaining_step_count": sum(
                        1
                        for step in plan_state.get("steps", []) or []
                        if isinstance(step, Mapping)
                        and str(step.get("status") or "").lower()
                        not in {"done", "completed", "skipped"}
                    ),
                },
                "renderer_status": str(protocol.get("manifest_status") or ""),
            },
            feedback=dict(state.get("last_supervisor_feedback") or {}),
            allowed_operations=list(protocol.get("allowed_actions") or []),
            trace_enabled=False,
            max_payload_chars=max(
                1,
                int(getattr(self, "llm_context_limit_tokens", 200_000)) * 4,
            ),
        )
        # This method is a legacy local projection API, not a provider call.
        # Preserve its flat read shape while PromptManager serialises only the
        # two provider-facing V2 sections.
        return json.dumps(
            context.llm_payload.to_dict(),
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )

    @staticmethod
    def _bounded_message_history(
        messages: List[BaseMessage],
        *,
        max_messages: int = LLM_MAX_HISTORY_MESSAGES,
        max_chars: int = LLM_MAX_HISTORY_CHARS,
    ) -> List[BaseMessage]:
        """Keep the initial request and recent evidence within a fixed budget."""
        if not messages:
            return []
        selected = messages[-max_messages:]
        if messages[0] not in selected and max_messages > 1:
            selected = [messages[0]] + selected[-(max_messages - 1):]

        per_message_limit = max(1200, max_chars // max(1, len(selected)))
        bounded: List[BaseMessage] = []
        for message in selected:
            content = str(getattr(message, "content", message) or "")
            if len(content) <= per_message_limit:
                bounded.append(message)
                continue
            clipped = compress_tagged_text(content, per_message_limit)
            try:
                bounded.append(message.model_copy(update={"content": clipped}))
            except AttributeError:
                if isinstance(message, HumanMessage):
                    bounded.append(HumanMessage(content=clipped))
                elif isinstance(message, AIMessage):
                    bounded.append(AIMessage(content=clipped))
                elif isinstance(message, SystemMessage):
                    bounded.append(SystemMessage(content=clipped))
                else:
                    bounded.append(HumanMessage(content=clipped))
        return bounded

    @staticmethod
    def _user_goal_messages(messages: List[BaseMessage]) -> List[BaseMessage]:
        """Keep the original goal and explicit later user answers only."""
        if not messages:
            return []
        selected: List[BaseMessage] = []
        first_human = next(
            (message for message in messages if isinstance(message, HumanMessage)),
            None,
        )
        if first_human is not None:
            selected.append(first_human)
        later_humans = [
            message
            for message in messages
            if isinstance(message, HumanMessage)
            and message is not first_human
            and "<observation>" not in str(getattr(message, "content", ""))
        ]
        if later_humans:
            selected.append(later_humans[-1])
        return selected

    def _task_spec_for_state(
        self,
        state: Optional[Dict[str, Any]],
        messages: Optional[List[BaseMessage]] = None,
    ) -> Dict[str, Any]:
        mapping = state if isinstance(state, dict) else {}
        task_id = str(mapping.get("task_id") or mapping.get("session_id") or "")
        if not task_id:
            return {}
        durable = load_plan_state(self.data_path, task_id)
        if durable.get("canonical_state_error"):
            raise CanonicalTaskStateError(
                str((durable.get("canonical_state_error") or {}).get("detail") or "")
            )
        authoritative = canonical_task_spec_for_state(durable)
        return (
            ensure_task_spec(authoritative, "", task_id=task_id)
            if task_spec_is_initialized(authoritative)
            else {}
        )

    def _task_revision_for_state(self, state: Optional[Dict[str, Any]]) -> int:
        mapping = state if isinstance(state, dict) else {}
        return task_spec_revision(self._task_spec_for_state(mapping))

    @staticmethod
    def _authoritative_user_turn_revision(
        plan_state: Mapping[str, Any],
    ) -> int:
        conversation = dict(plan_state.get("conversation_evidence") or {})
        return max(0, int(
            conversation.get("user_turn_count")
            if conversation.get("user_turn_count") is not None
            else conversation.get("turn_count")
            or 0
        ))

    @staticmethod
    def _active_skill_ids_from_refs(
        refs: Sequence[Mapping[str, Any]],
    ) -> List[str]:
        return list(dict.fromkeys(
            str(item.get("skill_id") or "")
            for item in refs or []
            if isinstance(item, Mapping)
            and str(item.get("status") or "") == "active"
            and str(item.get("scope") or "task") == "task"
            and str(item.get("skill_id") or "")
        ))

    @staticmethod
    def _authorised_task_skill_selection(
        access_state: Mapping[str, Any],
        proposal: Mapping[str, Any],
    ) -> List[str]:
        """Return the only task Skill set authorised by one reviewed proposal."""
        access = normalize_skill_access_state(access_state)
        candidate_id = str(proposal.get("candidate_skill_id") or "")
        candidate_snapshot_id = str(
            proposal.get("candidate_snapshot_id") or ""
        )
        candidate_ref_scope = str(
            proposal.get("candidate_ref_scope") or "task"
        ).lower()
        candidate_ref_target = str(
            proposal.get("candidate_ref_target_step_id") or ""
        )
        scope = str(proposal.get("requested_scope") or "").lower()
        relation = str(proposal.get("relation") or "").lower()
        if scope != "task" or relation not in {"supplement", "replace"}:
            raise SkillAccessError(
                "SKILL_BINDING_TASK_SELECTION_INVALID",
                f"scope={scope or '<missing>'}; relation={relation or '<missing>'}",
            )
        candidate_refs = [
            item for item in access.get("selected_skill_refs") or []
            if isinstance(item, Mapping)
            and str(item.get("skill_id") or "") == candidate_id
            and str(item.get("snapshot_id") or "") == candidate_snapshot_id
            and str(item.get("status") or "") == "candidate"
            and str(item.get("scope") or "task") == candidate_ref_scope
            and (
                candidate_ref_scope == "task"
                or str(item.get("target_step_id") or "")
                == candidate_ref_target
            )
            and not str(item.get("candidate_disposition") or "")
        ]
        if len(candidate_refs) != 1:
            raise SkillAccessError(
                "SKILL_BINDING_CANDIDATE_UNAVAILABLE",
                f"candidate_refs={len(candidate_refs)}",
            )
        active_refs = [
            item for item in access.get("selected_skill_refs") or []
            if isinstance(item, Mapping)
            and str(item.get("status") or "") == "active"
            and str(item.get("scope") or "task") == "task"
        ]
        active_ids = list(dict.fromkeys(
            str(item.get("skill_id") or "")
            for item in active_refs
            if str(item.get("skill_id") or "")
        ))
        if relation == "replace":
            if len(active_refs) != 1:
                raise SkillAccessError(
                    "SKILL_REPLACEMENT_TARGET_AMBIGUOUS",
                    f"active_targets={len(active_refs)}",
                )
            replaced_id = str(active_refs[0].get("skill_id") or "")
            active_ids = [item for item in active_ids if item != replaced_id]
        if candidate_id not in active_ids:
            active_ids.append(candidate_id)
        return active_ids

    def _prepare_durable_skill_access(
        self,
        plan_state: Mapping[str, Any],
        *,
        selected_skill_ids: Sequence[Any] = (),
        task_revision: int = 0,
    ) -> Dict[str, Any]:
        """Migrate legacy IDs to immutable refs and close stale continuations."""
        task_state = dict(plan_state.get("task_state") or {})
        access = normalize_skill_access_state(
            task_state.get("skill_access_state")
            or plan_state.get("skill_access_state")
            or {"selected_skill_refs": plan_state.get("selected_skill_refs") or []}
        )
        service = getattr(self, "skill_access_service", None)
        selected = list(dict.fromkeys(
            str(item) for item in (
                selected_skill_ids
                or task_state.get("selected_skills")
                or plan_state.get("selected_skill_ids")
                or []
            ) if str(item)
        ))
        if service is not None and selected:
            access = service.ensure_selected_skill_refs(
                access,
                selected,
                task_revision=max(0, int(task_revision or 0)),
                scope="task",
            )
        _, current_step = current_plan_step_with_index(dict(plan_state or {}))
        access = close_stale_continuations(
            access,
            task_revision=max(0, int(task_revision or 0)),
            plan_revision=max(0, int(plan_state.get("plan_revision") or 0)),
            current_step_id=str((current_step or {}).get("step_id") or ""),
            authoritative_user_turn_revision=(
                self._authoritative_user_turn_revision(plan_state)
            ),
        )
        return access

    def _persist_durable_skill_access(
        self,
        task_id: str,
        access_state: Mapping[str, Any],
        *,
        continuation_id: str = "",
        pending_proposal: Optional[Mapping[str, Any]] = None,
        pending_plan_impact: Optional[Mapping[str, Any]] = None,
        expected_state_generation: Optional[int] = None,
        expected_proposal_id: str = "",
        expected_proposal_status: str = "",
        expected_proposal_snapshot_id: str = "",
    ) -> Dict[str, Any]:
        """Persist canonical Skill state; ID lists are compatibility projections."""
        durable = load_plan_state(self.data_path, task_id)
        if (
            expected_state_generation is not None
            and int(durable.get("state_generation") or 0)
            != int(expected_state_generation)
        ):
            raise StateCASConflict(
                "SKILL_ACCESS_TRANSACTION_STALE: state_generation="
                f"{expected_state_generation}/{durable.get('state_generation')}"
            )
        if expected_proposal_id:
            current_task_state = dict(durable.get("task_state") or {})
            current_pointer = dict(
                current_task_state.get("pending_skill_binding_proposal") or {}
            )
            current_access = normalize_skill_access_state(
                current_task_state.get("skill_access_state")
                or durable.get("skill_access_state")
            )
            current_proposal = dict(
                (current_access.get("binding_proposals") or {}).get(
                    expected_proposal_id
                )
                or {}
            )
            observed = {
                "pointer_proposal_id": str(
                    current_pointer.get("proposal_id") or ""
                ),
                "record_proposal_id": str(
                    current_proposal.get("proposal_id") or ""
                ),
                "status": str(
                    current_proposal.get("status")
                    or current_pointer.get("status")
                    or ""
                ),
                "candidate_snapshot_id": str(
                    current_proposal.get("candidate_snapshot_id")
                    or current_pointer.get("candidate_snapshot_id")
                    or ""
                ),
            }
            expected = {
                "pointer_proposal_id": str(expected_proposal_id),
                "record_proposal_id": str(expected_proposal_id),
                "status": str(expected_proposal_status or ""),
                "candidate_snapshot_id": str(
                    expected_proposal_snapshot_id or ""
                ),
            }
            mismatches = {
                key: {"expected": value, "observed": observed[key]}
                for key, value in expected.items()
                if value and value != observed[key]
            }
            if mismatches:
                raise StateCASConflict(
                    "SKILL_ACCESS_TRANSACTION_STALE: "
                    + json.dumps(mismatches, sort_keys=True)
                )
        access = normalize_skill_access_state(access_state)
        refs = deepcopy(list(access.get("selected_skill_refs") or []))
        selected = self._active_skill_ids_from_refs(refs)
        task_state = dict(durable.get("task_state") or {})
        task_state["skill_access_state"] = deepcopy(access)
        task_state["selected_skill_refs"] = deepcopy(refs)
        task_state["selected_skills"] = list(selected)
        if continuation_id:
            task_state["skill_continuation_id"] = str(continuation_id)
        else:
            task_state.pop("skill_continuation_id", None)
        if pending_proposal is not None:
            if pending_proposal:
                task_state["pending_skill_binding_proposal"] = deepcopy(
                    dict(pending_proposal)
                )
            else:
                task_state.pop("pending_skill_binding_proposal", None)
        if pending_plan_impact is not None:
            if pending_plan_impact:
                task_state["pending_plan_impact_review"] = deepcopy(
                    dict(pending_plan_impact)
                )
            else:
                task_state.pop("pending_plan_impact_review", None)
        durable["task_state"] = task_state
        durable["skill_access_state"] = deepcopy(access)
        durable["selected_skill_refs"] = deepcopy(refs)
        durable["selected_skill_ids"] = list(selected)
        save_plan_state(self.data_path, task_id, durable)
        return {
            "skill_access_state": deepcopy(access),
            "selected_skill_refs": deepcopy(refs),
            "selected_skills": list(selected),
            "selected_skill_ids": list(selected),
            "skill_continuation_id": str(continuation_id or ""),
            "pending_skill_binding_proposal": deepcopy(
                dict(pending_proposal or {})
            ) if pending_proposal is not None else deepcopy(dict(
                task_state.get("pending_skill_binding_proposal") or {}
            )),
            "pending_plan_impact_review": deepcopy(
                dict(pending_plan_impact or {})
            ) if pending_plan_impact is not None else deepcopy(dict(
                task_state.get("pending_plan_impact_review") or {}
            )),
        }

    def _skill_context_projection(
        self,
        plan_state: Mapping[str, Any],
        *,
        caller_node: str,
        current_step_id: str,
        continuation_id: str = "",
    ) -> Dict[str, Any]:
        task_state = dict(plan_state.get("task_state") or {})
        return project_skill_context(
            task_state.get("skill_access_state")
            or plan_state.get("skill_access_state"),
            caller_node=caller_node,
            current_step_id=current_step_id,
            continuation_id=(
                continuation_id
                or str(task_state.get("skill_continuation_id") or "")
            ),
        )

    def _complete_durable_skill_continuation(
        self,
        task_id: str,
        *,
        caller_node: str,
    ) -> Dict[str, Any]:
        target_continuation_id = ""
        last_conflict: Optional[StateCASConflict] = None
        for _ in range(3):
            durable = load_plan_state(self.data_path, task_id)
            task_state = dict(durable.get("task_state") or {})
            continuation_id = str(
                task_state.get("skill_continuation_id") or ""
            )
            if not target_continuation_id:
                target_continuation_id = continuation_id
            if not continuation_id:
                return {}
            if continuation_id != target_continuation_id:
                raise StateCASConflict(
                    "SKILL_CONTINUATION_TRANSACTION_STALE: continuation="
                    f"{target_continuation_id}/{continuation_id}"
                )
            access = complete_skill_continuation(
                task_state.get("skill_access_state")
                or durable.get("skill_access_state"),
                continuation_id,
                caller_node=caller_node,
            )
            try:
                return self._persist_durable_skill_access(
                    task_id,
                    access,
                    continuation_id="",
                    expected_state_generation=int(
                        durable.get("state_generation") or 0
                    ),
                )
            except StateCASConflict as exc:
                last_conflict = exc
        raise last_conflict or StateCASConflict(
            "SKILL_CONTINUATION_TRANSACTION_STALE"
        )

    @staticmethod
    def _skill_access_cas_stale_update(
        *,
        caller_node: str,
        next_step: str,
        detail: str,
    ) -> Dict[str, Any]:
        stale = {
            "decision_result": "STALE_NODE_RESULT",
            "caller_node": str(caller_node),
            "changed_preconditions": ["skill_access_transaction"],
            "detail": str(detail),
            "counts_as_failure": False,
            "consumes_execution_retry": False,
            "consumes_recovery_retry": False,
        }
        return {
            "messages": [SystemMessage(content=json.dumps(
                stale, ensure_ascii=False, sort_keys=True,
            ))],
            "stale_node_result": deepcopy(stale),
            "skill_decision_result": deepcopy(stale),
            "pending_action": {},
            "next_step": str(next_step),
        }

    def _record_durable_skill_event(
        self,
        task_id: str,
        event: str,
        payload: Mapping[str, Any],
    ) -> None:
        for _ in range(3):
            durable = load_plan_state(self.data_path, task_id)
            task_state = dict(durable.get("task_state") or {})
            access = record_skill_access_event(
                task_state.get("skill_access_state")
                or durable.get("skill_access_state"),
                event,
                payload,
            )
            task_state["skill_access_state"] = access
            durable["task_state"] = task_state
            durable["skill_access_state"] = deepcopy(access)
            try:
                save_plan_state(self.data_path, task_id, durable)
                return
            except StateCASConflict:
                continue
            except OSError:
                logger.exception(
                    "Skill event persistence failed: task=%s event=%s",
                    task_id,
                    event,
                )
                return

    def _refund_planner_call_for_skill_continuation(
        self,
        task_id: str,
        planning_epoch_id: str,
    ) -> None:
        """Keep Skill acquisition outside the normal plan-candidate budget."""
        for _ in range(3):
            durable = load_plan_state(self.data_path, task_id)
            task_state = dict(durable.get("task_state") or {})
            epoch = dict(task_state.get("planning_epoch") or {})
            if (
                not epoch
                or str(epoch.get("planning_epoch_id") or "")
                != str(planning_epoch_id or "")
            ):
                return
            epoch["planner_calls_total"] = max(
                0, int(epoch.get("planner_calls_total") or 0) - 1
            )
            task_state["planning_epoch"] = epoch
            durable["task_state"] = task_state
            try:
                save_plan_state(self.data_path, task_id, durable)
                return
            except StateCASConflict:
                continue

    async def _handle_skill_node_decision(
        self,
        *,
        task_id: str,
        caller_node: str,
        graph_node: str,
        decision: Mapping[str, Any],
        node_context: NodeContext,
        response: BaseMessage,
        selected_skill_ids: Sequence[Any] = (),
    ) -> Dict[str, Any]:
        """Serve a typed Skill decision before any action/plan parser runs."""
        service = getattr(self, "skill_access_service", None)
        if service is None:
            raise SkillAccessError(
                "SKILL_CONTEXT_UNAVAILABLE", "SkillManager is not configured"
            )
        durable = load_plan_state(self.data_path, task_id)
        task_spec = canonical_task_spec_for_state(durable)
        task_revision = task_spec_revision(task_spec)
        _, durable_step = current_plan_step_with_index(dict(durable))
        fresh_authority = {
            "task_revision": task_revision,
            "plan_revision": int(durable.get("plan_revision") or 0),
            "authoritative_user_turn_revision": (
                self._authoritative_user_turn_revision(durable)
            ),
            "step_id": str((durable_step or {}).get("step_id") or ""),
        }
        bound_authority = {
            "task_revision": int(node_context.binding.task_revision or 0),
            "plan_revision": int(node_context.binding.plan_revision or 0),
            "authoritative_user_turn_revision": int(
                node_context.binding.authoritative_user_turn_revision or 0
            ),
            "step_id": str(node_context.binding.step_id or ""),
        }
        authority_changes = sorted(
            key for key, value in fresh_authority.items()
            if value != bound_authority[key]
        )
        if authority_changes:
            return {
                "messages": [response, SystemMessage(content=json.dumps({
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": caller_node,
                    "caller_invocation_id": (
                        node_context.binding.invocation_id
                    ),
                    "changed_preconditions": authority_changes,
                    "counts_as_failure": False,
                }, ensure_ascii=False, sort_keys=True))],
                "stale_node_result": {
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": caller_node,
                    "changed_preconditions": authority_changes,
                },
                "pending_action": {},
                "next_step": graph_node,
            }
        expected_state_generation = int(
            durable.get("state_generation") or 0
        )
        access = self._prepare_durable_skill_access(
            durable,
            selected_skill_ids=selected_skill_ids,
            task_revision=task_revision,
        )
        prior_continuation_id = str(
            (durable.get("task_state") or {}).get("skill_continuation_id") or ""
        )
        prior_continuation = dict(
            (access.get("continuations") or {}).get(prior_continuation_id) or {}
        )
        logical_invocation_id = str(node_context.binding.invocation_id)
        if (
            prior_continuation
            and str(prior_continuation.get("caller_node") or "") == caller_node
            and int(prior_continuation.get("task_revision") or 0) == task_revision
            and int(prior_continuation.get("plan_revision") or 0)
            == int(durable.get("plan_revision") or 0)
            and int(
                prior_continuation.get(
                    "authoritative_user_turn_revision"
                )
                or 0
            ) == self._authoritative_user_turn_revision(durable)
            and str(prior_continuation.get("current_step_id") or "")
            == str(node_context.binding.step_id or "")
        ):
            logical_invocation_id = str(
                prior_continuation.get("caller_invocation_id")
                or logical_invocation_id
            )
            access = complete_skill_continuation(
                access,
                prior_continuation_id,
                caller_node=caller_node,
            )
        envelope = {
            "caller_node": caller_node,
            "caller_invocation_id": logical_invocation_id,
            "task_revision": task_revision,
            "plan_revision": int(durable.get("plan_revision") or 0),
            "authoritative_user_turn_revision": (
                self._authoritative_user_turn_revision(durable)
            ),
            "current_step_id": str(node_context.binding.step_id or ""),
            "attempt_id": str(node_context.binding.attempt_id or ""),
        }
        kind = str(decision.get("decision") or "").upper()
        if kind == REQUEST_SKILL_CONTEXT:
            access, result = service.serve_context_request(
                access, decision, runtime_envelope=envelope,
            )
            proposal = None
        elif kind == SEARCH_SKILLS:
            input_roles = [
                str(item.get("role") or item.get("name") or "")
                for item in task_spec.get("inputs") or []
                if isinstance(item, Mapping)
            ]
            access, result = service.search_skills(
                access,
                decision,
                runtime_envelope=envelope,
                input_roles=input_roles,
            )
            proposal = None
        elif kind == PROPOSE_SKILL_BINDING:
            access, proposal = service.propose_binding(
                access, decision, runtime_envelope=envelope,
            )
            direct_plan_impact = (
                str(proposal.get("review_route") or "")
                == "planner_plan_impact_review"
            )
            result = {
                "decision_result": "SKILL_BINDING_PROPOSAL_RECORDED",
                "proposal_id": proposal["proposal_id"],
                "status": (
                    "pending_plan_impact_review"
                    if direct_plan_impact
                    else "pending_consultant_review"
                ),
                "review_route": str(proposal.get("review_route") or ""),
            }
        else:  # validate_skill_decision owns this boundary.
            raise SkillAccessError("SKILL_DECISION_SCHEMA_INVALID", kind)

        continuation_id = str(result.get("continuation_id") or "")
        no_progress = str(result.get("status") or "") in {
            "SKILL_CONTEXT_NO_PROGRESS", "SKILL_SEARCH_NO_PROGRESS",
        }
        if no_progress and continuation_id:
            access = complete_skill_continuation(
                access,
                continuation_id,
                caller_node=caller_node,
            )
            continuation_id = ""
        pending_plan_impact = None
        if proposal is not None and direct_plan_impact:
            pending_plan_impact = {
                "mode": "plan_impact_review",
                "proposal_id": str(proposal.get("proposal_id") or ""),
                "base_task_revision": task_revision,
                "new_task_revision": task_revision,
                "base_plan_revision": int(durable.get("plan_revision") or 0),
                "base_user_turn_revision": (
                    self._authoritative_user_turn_revision(durable)
                ),
                "skill_change": {
                    "proposal": deepcopy(dict(proposal)),
                    "candidate_skill_refs": [
                        deepcopy(dict(item))
                        for item in access.get("selected_skill_refs") or []
                        if str(item.get("snapshot_id") or "")
                        == str(proposal.get("candidate_snapshot_id") or "")
                    ],
                },
                "status": "pending",
            }
        try:
            projection = self._persist_durable_skill_access(
                task_id,
                access,
                continuation_id=continuation_id,
                pending_proposal=(proposal if proposal is not None else None),
                pending_plan_impact=pending_plan_impact,
                expected_state_generation=expected_state_generation,
            )
        except StateCASConflict as exc:
            return {
                "messages": [response, SystemMessage(content=json.dumps({
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": caller_node,
                    "caller_invocation_id": (
                        node_context.binding.invocation_id
                    ),
                    "changed_preconditions": ["skill_access_transaction"],
                    "detail": str(exc),
                    "counts_as_failure": False,
                }, ensure_ascii=False, sort_keys=True))],
                "stale_node_result": {
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": caller_node,
                    "changed_preconditions": ["skill_access_transaction"],
                },
                "pending_action": {},
                "next_step": graph_node,
            }
        next_step = (
            "planner"
            if proposal is not None and direct_plan_impact
            else "consultant"
            if proposal is not None or no_progress
            else graph_node
        )
        update: Dict[str, Any] = {
            "messages": [
                response,
                SystemMessage(content=json.dumps(
                    result, ensure_ascii=False, sort_keys=True, default=str,
                )),
            ],
            "pending_action": {},
            "next_step": next_step,
            "skill_decision_result": deepcopy(result),
            "transition_guard": (
                "skill_binding_requires_plan_impact_review"
                if proposal is not None and direct_plan_impact
                else "skill_binding_requires_consultant_review"
                if proposal is not None
                else "skill_no_progress_requires_consultant"
                if no_progress
                else "skill_same_node_continuation"
            ),
            **projection,
        }
        if graph_node == "generate":
            update.update({
                "generate_result": (
                    "SKILL_BINDING_PROPOSED"
                    if proposal is not None
                    else "SKILL_NO_PROGRESS"
                    if no_progress
                    else "SKILL_CONTINUATION"
                ),
                "generate_exit_reason": (
                    "skill_binding_proposed"
                    if proposal is not None
                    else "skill_no_progress"
                    if no_progress
                    else "skill_context_served"
                ),
            })
        return update

    async def _run_consultant_skill_resolution(
        self,
        state: AgentState,
        *,
        task_id: str,
        durable: Mapping[str, Any],
        proposal: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Run the bounded Consultant-owned applicability review."""
        task_spec = canonical_task_spec_for_state(durable)
        task_revision = task_spec_revision(task_spec)
        task_state = dict(durable.get("task_state") or {})
        access = self._prepare_durable_skill_access(
            durable,
            selected_skill_ids=task_state.get("selected_skills") or [],
            task_revision=task_revision,
        )
        proposal_id = str(proposal.get("proposal_id") or "")
        durable_proposal = deepcopy(dict(
            (access.get("binding_proposals") or {}).get(proposal_id) or {}
        ))
        pending_pointer = deepcopy(dict(
            task_state.get("pending_skill_binding_proposal") or {}
        ))
        if (
            not proposal_id
            or str(durable_proposal.get("proposal_id") or "") != proposal_id
            or str(pending_pointer.get("proposal_id") or "") != proposal_id
            or str(durable_proposal.get("candidate_snapshot_id") or "")
            != str(proposal.get("candidate_snapshot_id") or "")
        ):
            raise SkillAccessError(
                "SKILL_BINDING_PROPOSAL_MISMATCH", proposal_id
            )
        snapshot_id = str(durable_proposal.get("candidate_snapshot_id") or "")
        try:
            snapshot = deepcopy(dict(
                SkillAccessService._verified_snapshot(access, snapshot_id)
            ))
        except SkillAccessError:
            raise SkillAccessError(
                "SKILL_BINDING_CANDIDATE_UNAVAILABLE", snapshot_id
            )
        verified_excerpt_refs = [
            str(item)
            for item in durable_proposal.get("verified_excerpt_refs") or []
            if str(item)
        ]
        if not verified_excerpt_refs:
            raise SkillAccessError(
                "SKILL_BINDING_EVIDENCE_REQUIRED", proposal_id
            )
        relevant_excerpts: List[Dict[str, Any]] = []
        for excerpt_id in verified_excerpt_refs:
            excerpt = deepcopy(dict(
                SkillAccessService._verified_excerpt(access, excerpt_id)
            ))
            if str(excerpt.get("snapshot_id") or "") != snapshot_id:
                raise SkillAccessError(
                    "SKILL_EXCERPT_LINKAGE_INVALID", excerpt_id
                )
            relevant_excerpts.append(excerpt)
        latest_skill_tool_result = {}
        for result_id in sorted(
            (access.get("skill_tool_results") or {}).keys(), reverse=True
        ):
            candidate_result = dict(
                (access.get("skill_tool_results") or {}).get(result_id) or {}
            )
            result_excerpt_ids = {
                str(item.get("excerpt_id") or "")
                for item in candidate_result.get("results") or []
                if isinstance(item, Mapping)
            }
            if result_excerpt_ids.intersection(verified_excerpt_refs):
                latest_skill_tool_result = deepcopy(candidate_result)
                break
        transaction_material = {
            "pointer": pending_pointer,
            "proposal": durable_proposal,
            "candidate_ref": [
                deepcopy(dict(item))
                for item in access.get("selected_skill_refs") or []
                if isinstance(item, Mapping)
                and str(item.get("snapshot_id") or "") == snapshot_id
            ],
            "snapshot": snapshot,
            "excerpts": relevant_excerpts,
        }
        proposal_transaction_hash = hashlib.sha256(json.dumps(
            transaction_material,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")).hexdigest()
        expected_state_generation = int(
            durable.get("state_generation") or 0
        )
        expected_proposal_status = str(
            durable_proposal.get("status") or ""
        )
        _, resolution_step = current_plan_step_with_index(dict(durable))
        resolution_step_id = str(
            (resolution_step or {}).get("step_id") or ""
        )
        conversation_index = dict(durable.get("conversation_evidence") or {})
        bounded_user_evidence: List[Dict[str, Any]] = []
        if conversation_index.get("head_ref"):
            turns = StateContractStore(
                self.data_path, task_id
            ).read_conversation_evidence(conversation_index)
            proposal_refs = {
                str(item)
                for item in (
                    list(durable_proposal.get("evidence_refs") or [])
                    + list(durable_proposal.get("user_answer_refs") or [])
                )
                if str(item)
            }
            matching_turns = [
                deepcopy(dict(item))
                for item in turns
                if str(item.get("role") or "") == "user"
                and {
                    str(item.get("turn_id") or ""),
                    str(item.get("turn_ref") or ""),
                    str(item.get("content_ref") or ""),
                }
                & proposal_refs
            ]
            if not matching_turns:
                matching_turns = [
                    deepcopy(dict(item))
                    for item in turns
                    if str(item.get("role") or "") == "user"
                ][-1:]
            bounded_user_evidence = matching_turns[-3:]
        resolution_payload = build_skill_resolution_payload(
            task_snapshot=task_spec,
            current_plan=durable,
            active_skill_refs=access.get("selected_skill_refs") or [],
            candidate={
                **snapshot,
                "relevant_excerpt_refs": verified_excerpt_refs,
                "relevant_skill_excerpts": relevant_excerpts,
                "latest_skill_tool_result": latest_skill_tool_result,
            },
            proposal=durable_proposal,
            user_evidence=bounded_user_evidence,
        )
        consultant_context = build_node_context(
            node_type="consultant",
            task_spec=task_spec,
            plan_state=durable,
            state_generation=int(durable.get("state_generation") or 0),
            current_step_id=resolution_step_id,
            authoritative_user_turn_revision=(
                self._authoritative_user_turn_revision(durable)
            ),
        )
        prompt = PromptManager.get_consultant_skill_resolution_prompt(
            resolution_payload
        )
        response = await self._ainvoke_node_llm(
            [HumanMessage(content=prompt)],
            node_context=consultant_context,
            stage="consultant_skill_resolution",
            task_id=task_id,
            task_mode=str(state.get("task_mode") or "managed"),
            temperature=0.0,
            trace_metadata={
                "call_kind": "consultant_skill_resolution",
                "proposal_id": proposal_id,
                "task_spec_revision": task_revision,
            },
        )
        latest = load_plan_state(self.data_path, task_id)
        _, latest_resolution_step = current_plan_step_with_index(latest)
        latest_context = build_node_context(
            node_type="consultant",
            task_spec=canonical_task_spec_for_state(latest),
            plan_state=latest,
            state_generation=int(latest.get("state_generation") or 0),
            current_step_id=str(
                (latest_resolution_step or {}).get("step_id") or ""
            ),
            authoritative_user_turn_revision=(
                self._authoritative_user_turn_revision(latest)
            ),
        )
        staleness = evaluate_node_staleness(
            consultant_context.binding,
            latest_context.binding.to_dict(),
        )
        latest_task_state = dict(latest.get("task_state") or {})
        latest_access = normalize_skill_access_state(
            latest_task_state.get("skill_access_state")
            or latest.get("skill_access_state")
        )
        latest_pointer = deepcopy(dict(
            latest_task_state.get("pending_skill_binding_proposal") or {}
        ))
        latest_proposal = deepcopy(dict(
            (latest_access.get("binding_proposals") or {}).get(proposal_id)
            or {}
        ))
        try:
            latest_snapshot = deepcopy(dict(
                SkillAccessService._verified_snapshot(
                    latest_access,
                    str(latest_proposal.get("candidate_snapshot_id") or ""),
                )
            ))
        except SkillAccessError:
            latest_snapshot = {}
        latest_verified_excerpt_refs = [
            str(item)
            for item in latest_proposal.get("verified_excerpt_refs") or []
            if str(item)
        ]
        latest_excerpts: List[Dict[str, Any]] = []
        try:
            latest_excerpts = [
                deepcopy(dict(SkillAccessService._verified_excerpt(
                    latest_access, excerpt_id,
                )))
                for excerpt_id in latest_verified_excerpt_refs
            ]
        except SkillAccessError:
            latest_excerpts = []
        latest_transaction_material = {
            "pointer": latest_pointer,
            "proposal": latest_proposal,
            "candidate_ref": [
                deepcopy(dict(item))
                for item in latest_access.get("selected_skill_refs") or []
                if isinstance(item, Mapping)
                and str(item.get("snapshot_id") or "")
                == str(latest_snapshot.get("snapshot_id") or "")
            ],
            "snapshot": latest_snapshot,
            "excerpts": latest_excerpts,
        }
        latest_transaction_hash = hashlib.sha256(json.dumps(
            latest_transaction_material,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")).hexdigest()
        transaction_changed = (
            latest_transaction_hash != proposal_transaction_hash
        )
        changed_preconditions = list(staleness.changed_preconditions)
        if transaction_changed:
            changed_preconditions.append("skill_resolution_transaction")
        if not staleness.usable or transaction_changed:
            self._record_durable_skill_event(
                task_id,
                "stale_node_result_discarded",
                {
                    "caller_node": "consultant",
                    "caller_invocation_id": consultant_context.binding.invocation_id,
                    "changed_preconditions": changed_preconditions,
                },
            )
            return {
                "messages": [response, SystemMessage(content=json.dumps({
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": "consultant",
                    "caller_invocation_id": consultant_context.binding.invocation_id,
                    "changed_preconditions": changed_preconditions,
                    "counts_as_failure": False,
                }, ensure_ascii=False, sort_keys=True))],
                "stale_node_result": {
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": "consultant",
                    "changed_preconditions": changed_preconditions,
                },
                "next_step": "consultant",
            }
        # Review and persist the latest byte-identical transaction so unrelated
        # record-only writes cannot be clobbered. A subsequent race is caught
        # by the generation/proposal CAS in _persist_durable_skill_access.
        access = latest_access
        durable_proposal = latest_proposal
        expected_state_generation = int(
            latest.get("state_generation") or 0
        )
        expected_proposal_status = str(
            latest_proposal.get("status") or ""
        )
        persistence_cas = {
            "expected_state_generation": expected_state_generation,
            "expected_proposal_id": proposal_id,
            "expected_proposal_status": expected_proposal_status,
            "expected_proposal_snapshot_id": snapshot_id,
        }
        review = validate_skill_resolution_decision(
            parse_strict_json_object(
                str(response.content or ""),
                error_code="SKILL_RESOLUTION_SCHEMA_INVALID",
            )
        )
        access, reviewed = review_binding_proposal(
            access,
            proposal_id,
            review,
        )
        review_kind = str(review["decision"])
        caller = str(durable_proposal.get("caller_node") or "")
        resume_node = (
            "planner"
            if caller.startswith("planner")
            else "supervisor"
            if caller == "recovery"
            else "consultant"
            if caller == "consultant"
            else "generate"
        )

        if review_kind == "SEARCH_MORE":
            search_decision = {
                "decision": SEARCH_SKILLS,
                "query": str(review.get("query") or ""),
                "capability_gap": str(review.get("reason") or "more evidence required"),
                "desired_outcome": "resolve the pending Skill binding proposal",
                "requested_scope": (
                    "current_step"
                    if str(durable_proposal.get("requested_scope") or "") == "step"
                    else "task"
                ),
                "relation_hint": str(
                    durable_proposal.get("relation") or "unknown"
                ),
            }
            access, search_result = self.skill_access_service.search_skills(
                access,
                search_decision,
                runtime_envelope={
                    "caller_node": caller,
                    "caller_invocation_id": str(
                        durable_proposal.get("caller_invocation_id") or ""
                    ),
                    "task_revision": int(
                        durable_proposal.get("base_task_revision") or 0
                    ),
                    "plan_revision": int(
                        durable_proposal.get("base_plan_revision") or 0
                    ),
                    "authoritative_user_turn_revision": int(
                        durable_proposal.get("base_user_turn_revision") or 0
                    ),
                    "current_step_id": str(
                        durable_proposal.get("base_step_id") or ""
                    ),
                    "attempt_id": "",
                },
            )
            continuation_id = str(
                search_result.get("continuation_id") or ""
            )
            projection = self._persist_durable_skill_access(
                task_id,
                access,
                continuation_id=continuation_id,
                pending_proposal={},
                **persistence_cas,
            )
            return {
                "messages": [
                    response,
                    SystemMessage(content=json.dumps(
                        search_result,
                        ensure_ascii=False,
                        sort_keys=True,
                        default=str,
                    )),
                ],
                "skill_resolution": deepcopy(review),
                "skill_decision_result": deepcopy(search_result),
                "pending_action": {},
                "next_step": resume_node,
                **projection,
            }

        if review_kind == "NEED_USER_INPUT":
            projection = self._persist_durable_skill_access(
                task_id,
                access,
                pending_proposal=reviewed,
                **persistence_cas,
            )
            return {
                "messages": [response],
                "pending_human_question": {
                    "type": "skill_resolution",
                    "stage": "consultant",
                    "question": str(review.get("question") or ""),
                    "requested_slots": list(review.get("requested_slots") or []),
                    "resume_step": "consultant",
                    "proposal_id": proposal_id,
                    "owner": "user",
                },
                "next_step": "ask_user",
                **projection,
            }

        if review_kind == "REJECT_SKILL_PROPOSAL":
            projection = self._persist_durable_skill_access(
                task_id,
                access,
                pending_proposal={},
                **persistence_cas,
            )
            return {
                "messages": [response],
                "skill_resolution": deepcopy(review),
                "pending_action": {},
                "next_step": resume_node,
                **projection,
            }

        active_ids = self._active_skill_ids_from_refs(
            access.get("selected_skill_refs") or []
        )
        if review_kind == "ROUTE_TASK_LEVEL_CHANGE":
            # skill_resolution is advisory.  It may classify scope/relation,
            # but it cannot mutate TaskSpec or activate a task binding.  The
            # reviewed candidate now enters the ordinary main Consultant
            # candidate/commit transaction with full user authority.
            access = record_skill_access_event(
                access,
                "task_skill_change_routed_to_main_consultant",
                {
                    "proposal_id": proposal_id,
                    "base_task_revision": task_revision,
                    "base_plan_revision": int(durable.get("plan_revision") or 0),
                    "candidate_skill_id": str(
                        durable_proposal.get("candidate_skill_id") or ""
                    ),
                },
            )
            projection = self._persist_durable_skill_access(
                task_id,
                access,
                pending_proposal=reviewed,
                pending_plan_impact={},
                **persistence_cas,
            )
            return {
                "messages": [response, SystemMessage(content=json.dumps({
                    "decision_result": "TASK_SKILL_CHANGE_REQUIRES_MAIN_CONSULTANT",
                    "proposal_id": proposal_id,
                    "status": "approved_for_task_commit",
                    "counts_as_failure": False,
                }, ensure_ascii=False, sort_keys=True))],
                "skill_resolution": deepcopy(review),
                "pending_action": {},
                "next_step": "consultant",
                **projection,
            }
        pending_impact = {
            "mode": "plan_impact_review",
            "proposal_id": proposal_id,
            "base_task_revision": task_revision,
            "new_task_revision": task_revision,
            "base_plan_revision": int(durable.get("plan_revision") or 0),
            "base_user_turn_revision": (
                self._authoritative_user_turn_revision(durable)
            ),
            "skill_change": {
                "proposal": deepcopy(dict(durable_proposal)),
                "consultant_review": deepcopy(review),
                "active_skill_refs": [
                    deepcopy(dict(item))
                    for item in access.get("selected_skill_refs") or []
                    if str(item.get("status") or "") == "active"
                ],
                "candidate_skill_refs": [
                    deepcopy(dict(item))
                    for item in access.get("selected_skill_refs") or []
                    if str(item.get("snapshot_id") or "")
                    == snapshot_id
                ],
            },
            "status": "pending",
        }
        projection = self._persist_durable_skill_access(
            task_id,
            access,
            pending_proposal={},
            pending_plan_impact=pending_impact,
            **persistence_cas,
        )
        return {
            "messages": [response],
            "skill_resolution": deepcopy(review),
            "pending_action": {},
            "next_step": "planner",
            **projection,
        }

    async def _run_planner_plan_impact_review(
        self,
        state: AgentState,
        *,
        task_id: str,
        durable: Mapping[str, Any],
        pending: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Run and transactionally apply the restricted Planner impact mode."""
        task_spec = canonical_task_spec_for_state(durable)
        task_revision = task_spec_revision(task_spec)
        plan_revision = int(durable.get("plan_revision") or 0)
        expected_task_revision = int(
            pending.get("new_task_revision")
            or pending.get("base_task_revision")
            or 0
        )
        expected_plan_revision = int(pending.get("base_plan_revision") or 0)
        current_user_turn_revision = (
            self._authoritative_user_turn_revision(durable)
        )
        expected_user_turn_revision = int(
            pending.get("base_user_turn_revision")
            if pending.get("base_user_turn_revision") is not None
            else current_user_turn_revision
        )
        pending_proposal_hint = dict(
            (pending.get("skill_change") or {}).get("proposal") or {}
        )
        hinted_scope = str(
            pending_proposal_hint.get("requested_scope") or ""
        ).lower()
        if hinted_scope == "current_step":
            hinted_scope = "step"
        hinted_step_id = str(
            pending_proposal_hint.get("target_step_id")
            or pending_proposal_hint.get("base_step_id")
            or ""
        )
        durable_step_id = str(
            (current_plan_step_with_index(dict(durable))[1] or {}).get(
                "step_id"
            )
            or ""
        )
        step_target_changed = bool(
            hinted_scope == "step"
            and hinted_step_id
            and hinted_step_id != durable_step_id
        )
        if (
            expected_task_revision == task_revision
            and expected_user_turn_revision == current_user_turn_revision
            and expected_plan_revision != plan_revision
            and not step_target_changed
        ):
            rebased_pending = {
                **deepcopy(dict(pending)),
                "base_plan_revision": plan_revision,
                "status": "pending",
                "rebased_from_plan_revision": expected_plan_revision,
            }
            rebased = deepcopy(dict(durable))
            rebased_task_state = dict(rebased.get("task_state") or {})
            rebased_task_state["pending_plan_impact_review"] = (
                rebased_pending
            )
            rebased["task_state"] = rebased_task_state
            save_plan_state(self.data_path, task_id, rebased)
            return await self._run_planner_plan_impact_review(
                state,
                task_id=task_id,
                durable=load_plan_state(self.data_path, task_id),
                pending=rebased_pending,
            )
        if (
            expected_task_revision != task_revision
            or expected_user_turn_revision != current_user_turn_revision
            or step_target_changed
        ):
            proposal_id = str(pending.get("proposal_id") or "")
            stale_durable = deepcopy(dict(durable))
            stale_task_state = dict(stale_durable.get("task_state") or {})
            stale_access = normalize_skill_access_state(
                stale_task_state.get("skill_access_state")
                or stale_durable.get("skill_access_state")
            )
            stale_proposal = (
                stale_access.get("binding_proposals") or {}
            ).get(proposal_id)
            if isinstance(stale_proposal, MutableMapping):
                stale_proposal["status"] = "stale"
                stale_proposal["stale_reason"] = (
                    "authoritative_revision_changed"
                )
            stale_snapshot_id = str(
                (stale_proposal or {}).get("candidate_snapshot_id") or ""
            )
            for ref in stale_access.get("selected_skill_refs") or []:
                if (
                    isinstance(ref, MutableMapping)
                    and stale_snapshot_id
                    and str(ref.get("snapshot_id") or "")
                    == stale_snapshot_id
                    and str(ref.get("status") or "") == "candidate"
                ):
                    ref["candidate_disposition"] = "stale"
                    ref["stale_reason"] = (
                        "authoritative_revision_changed"
                    )
            stale_access = record_skill_access_event(
                stale_access,
                "stale_plan_impact_review_discarded",
                {
                    "proposal_id": proposal_id,
                    "expected_task_revision": expected_task_revision,
                    "current_task_revision": task_revision,
                    "expected_user_turn_revision": (
                        expected_user_turn_revision
                    ),
                    "current_user_turn_revision": (
                        current_user_turn_revision
                    ),
                    "expected_step_id": hinted_step_id,
                    "current_step_id": durable_step_id,
                },
            )
            stale_access = invalidate_skill_continuations(
                stale_access,
                reason="stale_plan_impact_review",
            )
            stale_task_state.pop("pending_plan_impact_review", None)
            pointed_proposal = dict(
                stale_task_state.get("pending_skill_binding_proposal") or {}
            )
            if str(pointed_proposal.get("proposal_id") or "") == proposal_id:
                stale_task_state.pop(
                    "pending_skill_binding_proposal", None
                )
            stale_task_state["skill_access_state"] = stale_access
            stale_task_state["stale_plan_impact_review"] = deepcopy(
                dict(pending)
            )
            stale_durable["task_state"] = stale_task_state
            stale_durable["skill_access_state"] = deepcopy(stale_access)
            stale_durable["selected_skill_refs"] = deepcopy(list(
                stale_access.get("selected_skill_refs") or []
            ))
            stale_durable["selected_skill_ids"] = (
                self._active_skill_ids_from_refs(
                    stale_access.get("selected_skill_refs") or []
                )
            )
            save_plan_state(self.data_path, task_id, stale_durable)
            self._record_durable_skill_event(
                task_id,
                "stale_node_result_discarded",
                {
                    "caller_node": "planner",
                    "expected_task_revision": expected_task_revision,
                    "current_task_revision": task_revision,
                    "expected_plan_revision": expected_plan_revision,
                    "current_plan_revision": plan_revision,
                    "expected_user_turn_revision": (
                        expected_user_turn_revision
                    ),
                    "current_user_turn_revision": (
                        current_user_turn_revision
                    ),
                },
            )
            return {
                "messages": [SystemMessage(content=json.dumps({
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": "planner",
                    "changed_preconditions": [
                        *(["task_revision"] if expected_task_revision != task_revision else []),
                        *(["plan_revision"] if expected_plan_revision != plan_revision else []),
                        *(
                            ["authoritative_user_turn_revision"]
                            if expected_user_turn_revision
                            != current_user_turn_revision
                            else []
                        ),
                        *(["step_id"] if step_target_changed else []),
                    ],
                    "counts_as_failure": False,
                }, ensure_ascii=False, sort_keys=True))],
                "stale_node_result": {
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": "planner",
                    "expected_task_revision": expected_task_revision,
                    "current_task_revision": task_revision,
                    "expected_plan_revision": expected_plan_revision,
                    "current_plan_revision": plan_revision,
                    "expected_user_turn_revision": (
                        expected_user_turn_revision
                    ),
                    "current_user_turn_revision": (
                        current_user_turn_revision
                    ),
                    "expected_step_id": hinted_step_id,
                    "current_step_id": durable_step_id,
                },
                "next_step": (
                    "planner" if step_target_changed else "consultant"
                ),
            }
        task_state = dict(durable.get("task_state") or {})
        access = normalize_skill_access_state(
            task_state.get("skill_access_state")
            or durable.get("skill_access_state")
        )
        impact_skill_change = deepcopy(dict(
            pending.get("skill_change") or {}
        ))
        pending_proposal_id = str(pending.get("proposal_id") or "")
        impact_proposal = deepcopy(dict(
            (access.get("binding_proposals") or {}).get(
                pending_proposal_id
            )
            or impact_skill_change.get("proposal")
            or {}
        ))
        candidate_snapshot_ids = {
            str(item.get("snapshot_id") or "")
            for item in impact_skill_change.get("candidate_skill_refs") or []
            if isinstance(item, Mapping)
            and str(item.get("snapshot_id") or "")
        }
        proposal_snapshot_id = str(
            impact_proposal.get("candidate_snapshot_id") or ""
        )
        if proposal_snapshot_id:
            candidate_snapshot_ids.add(proposal_snapshot_id)
        verified_candidate_excerpt_ids = {
            str(item)
            for item in impact_proposal.get("verified_excerpt_refs") or []
            if str(item)
        }
        _, current_step = current_plan_step_with_index(dict(durable))
        completed_steps = [
            deepcopy(dict(item))
            for item in durable.get("steps") or []
            if isinstance(item, Mapping)
            and str(item.get("status") or "").lower()
            in {"done", "passed", "completed", "skipped"}
        ]
        skill_projection = project_skill_context(
            access,
            caller_node="planner",
            current_step_id=str((current_step or {}).get("step_id") or ""),
            continuation_id="",
            include_candidate_snapshot_ids=candidate_snapshot_ids,
            include_excerpt_ids=verified_candidate_excerpt_ids,
        )
        impact_user_evidence: List[Dict[str, Any]] = []
        conversation_index = dict(
            durable.get("conversation_evidence") or {}
        )
        if conversation_index.get("head_ref"):
            turns = StateContractStore(
                self.data_path, task_id
            ).read_conversation_evidence(conversation_index)
            answer_ref = str(pending.get("answer_turn_ref") or "")
            if answer_ref:
                impact_user_evidence = [
                    deepcopy(dict(item))
                    for item in turns
                    if str(item.get("role") or "") == "user"
                    and answer_ref in {
                        str(item.get("turn_id") or ""),
                        str(item.get("turn_ref") or ""),
                        str(item.get("content_ref") or ""),
                    }
                ][-1:]
            if not impact_user_evidence:
                impact_user_evidence = [
                    deepcopy(dict(item))
                    for item in turns
                    if str(item.get("role") or "") == "user"
                ][-3:]
        impact_payload = {
            "impact_kind": str(
                pending.get("impact_kind") or "skill_binding_change"
            ),
            "binding_decision_allowed": bool(impact_proposal),
            "base_task_revision": int(
                pending.get("base_task_revision") or task_revision
            ),
            "new_task_revision": task_revision,
            "base_plan_revision": plan_revision,
            "current_plan": {
                "plan_id": str(durable.get("plan_id") or ""),
                "plan_version": str(durable.get("plan_version") or ""),
                "steps": deepcopy(list(durable.get("steps") or [])),
            },
            "skill_change": impact_skill_change,
            "completed_steps": completed_steps,
            "current_step": deepcopy(dict(current_step or {})),
            "user_evidence": impact_user_evidence,
            "relevant_skill_excerpts": deepcopy(list(
                skill_projection.get("relevant_skill_excerpts") or []
            )),
        }
        planner_context = build_node_context(
            node_type="planner",
            task_spec=task_spec,
            plan_state=durable,
            state_generation=int(durable.get("state_generation") or 0),
            current_step_id=str((current_step or {}).get("step_id") or ""),
            feedback={"planning": {
                "mode": "plan_impact_review",
                "proposal_id": str(pending.get("proposal_id") or ""),
            }},
            skill_context=skill_projection,
            authoritative_user_turn_revision=(
                self._authoritative_user_turn_revision(durable)
            ),
            continuation_id=str(task_state.get("skill_continuation_id") or ""),
        )
        impact_transaction_hash = hashlib.sha256(json.dumps(
            dict(pending),
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")).hexdigest()
        response = await self._ainvoke_node_llm(
            [HumanMessage(content=PromptManager.get_plan_impact_review_prompt(
                impact_payload
            ))],
            node_context=planner_context,
            stage="planner_plan_impact_review",
            task_id=task_id,
            task_mode=str(state.get("task_mode") or "managed"),
            temperature=0.0,
            trace_metadata={
                "call_kind": "planner_plan_impact_review",
                "proposal_id": str(pending.get("proposal_id") or ""),
                "task_spec_revision": task_revision,
                "plan_revision": plan_revision,
            },
        )
        latest = load_plan_state(self.data_path, task_id)
        latest_context = build_node_context(
            node_type="planner",
            task_spec=canonical_task_spec_for_state(latest),
            plan_state=latest,
            current_step_id=str((current_plan_step_with_index(latest)[1] or {}).get(
                "step_id"
            ) or ""),
            authoritative_user_turn_revision=(
                self._authoritative_user_turn_revision(latest)
            ),
            continuation_id=str(
                (latest.get("task_state") or {}).get("skill_continuation_id")
                or ""
            ),
        )
        staleness = evaluate_node_staleness(
            planner_context.binding,
            latest_context.binding.to_dict(),
        )
        latest_pending = dict(
            (latest.get("task_state") or {}).get(
                "pending_plan_impact_review"
            ) or {}
        )
        latest_transaction_hash = hashlib.sha256(json.dumps(
            latest_pending,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        ).encode("utf-8")).hexdigest()
        transaction_changed = (
            latest_transaction_hash != impact_transaction_hash
        )
        changed_preconditions = list(staleness.changed_preconditions)
        if transaction_changed:
            changed_preconditions.append("plan_impact_transaction")
        if not staleness.usable or transaction_changed:
            self._record_durable_skill_event(
                task_id,
                "stale_node_result_discarded",
                {
                    "caller_node": "planner",
                    "caller_invocation_id": planner_context.binding.invocation_id,
                    "changed_preconditions": changed_preconditions,
                },
            )
            return {
                "messages": [response, SystemMessage(content=json.dumps({
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": "planner",
                    "caller_invocation_id": planner_context.binding.invocation_id,
                    "changed_preconditions": changed_preconditions,
                    "counts_as_failure": False,
                }, ensure_ascii=False, sort_keys=True))],
                "stale_node_result": {
                    "decision_result": "STALE_NODE_RESULT",
                    "caller_node": "planner",
                    "changed_preconditions": changed_preconditions,
                },
                "next_step": (
                    "consultant" if transaction_changed else "planner"
                ),
            }
        decision = validate_plan_impact_decision(
            parse_strict_json_object(
                str(response.content or ""),
                error_code="PLAN_IMPACT_SCHEMA_INVALID",
            ),
            base_task_revision=int(
                pending.get("base_task_revision") or task_revision
            ),
            new_task_revision=task_revision,
            base_plan_revision=plan_revision,
        )
        kind = str(decision["decision"])
        latest_task_state = dict(latest.get("task_state") or {})
        access = normalize_skill_access_state(
            latest_task_state.get("skill_access_state")
            or latest.get("skill_access_state")
        )
        proposal_for_impact = deepcopy(dict(
            (access.get("binding_proposals") or {}).get(
                str(pending.get("proposal_id") or "")
            )
            or (pending.get("skill_change") or {}).get("proposal")
            or {}
        ))
        if proposal_for_impact:
            validate_plan_impact_proposal_compatibility(
                decision,
                proposal_for_impact,
                current_step_id=str(
                    (current_plan_step_with_index(latest)[1] or {}).get(
                        "step_id"
                    )
                    or ""
                ),
            )
        elif kind == "BIND_AND_RESUME":
            raise SkillAccessError(
                "PLAN_IMPACT_BIND_SCOPE_INVALID",
                "BIND_AND_RESUME requires a reviewed step Skill supplement",
            )
        access = record_skill_access_event(
            access,
            "plan_impact_reviewed",
            {
                "proposal_id": str(pending.get("proposal_id") or ""),
                "decision": kind,
                "base_task_revision": task_revision,
                "base_plan_revision": plan_revision,
            },
        )
        if kind == "NEED_USER_INPUT":
            latest = deepcopy(dict(latest))
            latest_task_state = dict(latest.get("task_state") or {})
            latest_task_state["pending_plan_impact_review"] = {
                **deepcopy(dict(pending)),
                "status": "waiting_user",
                "question": str(decision.get("question") or ""),
                "requested_slots": list(decision.get("requested_slots") or []),
            }
            latest_task_state["skill_access_state"] = deepcopy(access)
            latest["task_state"] = latest_task_state
            latest["skill_access_state"] = deepcopy(access)
            save_plan_state(self.data_path, task_id, latest)
            return {
                "messages": [response],
                "pending_human_question": {
                    "type": "plan_impact_review",
                    "stage": "consultant",
                    "question": str(decision.get("question") or ""),
                    "requested_slots": list(decision.get("requested_slots") or []),
                    "resume_step": "planner",
                    "owner": "user",
                },
                "next_step": "consultant",
            }
        if kind == "REJECT_PROPOSAL":
            proposal_id = str(pending.get("proposal_id") or "")
            proposal = (
                access.get("binding_proposals") or {}
            ).get(proposal_id)
            candidate_snapshot_id = str(
                (proposal or {}).get("candidate_snapshot_id")
                or ((pending.get("skill_change") or {}).get("proposal") or {}).get(
                    "candidate_snapshot_id"
                )
                or ""
            )
            if isinstance(proposal, MutableMapping):
                proposal["status"] = "rejected_by_plan_impact"
                proposal["plan_impact_review"] = deepcopy(decision)
            old_active_refs = [
                deepcopy(dict(item))
                for item in (
                    (pending.get("skill_change") or {}).get(
                        "old_active_skill_refs"
                    )
                    or []
                )
                if isinstance(item, Mapping)
            ]
            old_ref_keys = {
                tuple(str(item.get(field) or "") for field in (
                    "skill_id", "snapshot_id", "source_path", "content_hash",
                    "scope", "target_step_id",
                ))
                for item in old_active_refs
            }
            for ref in access.get("selected_skill_refs") or []:
                if not isinstance(ref, MutableMapping):
                    continue
                ref_key = tuple(str(ref.get(field) or "") for field in (
                    "skill_id", "snapshot_id", "source_path", "content_hash",
                    "scope", "target_step_id",
                ))
                if (
                    candidate_snapshot_id
                    and str(ref.get("snapshot_id") or "")
                    == candidate_snapshot_id
                ):
                    ref["status"] = "candidate"
                    ref["candidate_disposition"] = "rejected"
                    ref["rejection_reason"] = str(
                        decision.get("reason") or ""
                    )
                elif ref_key in old_ref_keys:
                    ref["status"] = "active"
                    ref.pop("superseded_by", None)
                    ref.pop("superseded_at_task_revision", None)
            access = invalidate_skill_continuations(
                access,
                reason="plan_impact_proposal_rejected",
            )
            access = record_skill_access_event(
                access,
                "skill_binding_rejected_by_plan_impact",
                {
                    "proposal_id": proposal_id,
                    "candidate_snapshot_id": candidate_snapshot_id,
                    "reason": str(decision.get("reason") or ""),
                },
            )
            active_ids = self._active_skill_ids_from_refs(
                access.get("selected_skill_refs") or []
            )
            base_task_revision = int(
                pending.get("base_task_revision") or task_revision
            )
            old_task_spec = deepcopy(dict(
                (pending.get("skill_change") or {}).get("old_task_spec")
                or {}
            ))
            if (
                base_task_revision != task_revision
                and task_spec_is_initialized(old_task_spec)
            ):
                rollback_task = canonical_current_task_spec(old_task_spec)
                rollback_task["revision"] = task_revision + 1
                rollback_task.setdefault("change_log", []).append({
                    "revision": task_revision + 1,
                    "source": "planner_plan_impact_rejection",
                    "reason": str(decision.get("reason") or ""),
                    "proposal_id": proposal_id,
                    "recorded_at": datetime.now().isoformat(),
                })
                try:
                    rollback_update = self._commit_consultant_update(
                        task_id,
                        {
                            "messages": [response],
                            "task_spec": rollback_task,
                            "selected_skills": list(active_ids),
                            "selected_skill_ids": list(active_ids),
                            "skill_access_state": deepcopy(access),
                            "selected_skill_refs": deepcopy(list(
                                access.get("selected_skill_refs") or []
                            )),
                            "pending_skill_binding_proposal": {},
                            "pending_plan_impact_review": {},
                            "_plan_impact_rejection_rollback": True,
                            "expected_state_generation": int(
                                latest.get("state_generation") or 0
                            ),
                            "expected_plan_revision": plan_revision,
                            "expected_user_turn_revision": (
                                self._authoritative_user_turn_revision(latest)
                            ),
                            "next_step": "planner",
                        },
                    )
                except StateCASConflict as exc:
                    return {
                        "messages": [response, SystemMessage(content=json.dumps({
                            "decision_result": "STALE_NODE_RESULT",
                            "caller_node": "planner",
                            "changed_preconditions": [
                                "plan_impact_transaction"
                            ],
                            "detail": str(exc),
                            "counts_as_failure": False,
                        }, ensure_ascii=False, sort_keys=True))],
                        "next_step": "consultant",
                    }
                rollback_update.update({
                    "plan_impact_review": deepcopy(decision),
                    "pending_plan_impact_review": {},
                    "pending_skill_binding_proposal": {},
                    "skill_continuation_id": "",
                    "next_step": "planner",
                })
                return rollback_update

            latest = deepcopy(dict(latest))
            latest_task_state = dict(latest.get("task_state") or {})
            latest_task_state.pop("pending_plan_impact_review", None)
            latest_task_state.pop("pending_skill_binding_proposal", None)
            latest_task_state.pop("skill_continuation_id", None)
            latest_task_state["skill_access_state"] = deepcopy(access)
            latest_task_state["selected_skill_refs"] = deepcopy(list(
                access.get("selected_skill_refs") or []
            ))
            latest_task_state["selected_skills"] = list(active_ids)
            latest["task_state"] = latest_task_state
            latest["skill_access_state"] = deepcopy(access)
            latest["selected_skill_refs"] = deepcopy(list(
                access.get("selected_skill_refs") or []
            ))
            latest["selected_skill_ids"] = list(active_ids)
            save_plan_state(self.data_path, task_id, latest)
            caller = str((proposal or {}).get("caller_node") or "")
            resume_node = (
                "planner" if caller.startswith("planner")
                else "supervisor" if caller == "recovery"
                else "consultant" if caller == "consultant"
                else "generate"
            )
            return {
                "messages": [response],
                "plan_impact_review": deepcopy(decision),
                "pending_plan_impact_review": {},
                "pending_skill_binding_proposal": {},
                "skill_access_state": deepcopy(access),
                "selected_skill_refs": deepcopy(list(
                    access.get("selected_skill_refs") or []
                )),
                "selected_skills": list(active_ids),
                "selected_skill_ids": list(active_ids),
                "skill_continuation_id": "",
                "next_step": resume_node,
            }

        pending_proposal_id = str(pending.get("proposal_id") or "")
        pending_proposal = dict(
            (access.get("binding_proposals") or {}).get(pending_proposal_id)
            or {}
        )
        if (
            str(pending_proposal.get("status") or "")
            == "approved_for_plan_impact"
        ):
            access, activated_ids = activate_reviewed_binding(
                access,
                pending_proposal_id,
                task_revision=task_revision,
            )
            access = record_skill_access_event(
                access,
                "task_skill_binding_changed",
                {
                    "proposal_id": pending_proposal_id,
                    "old_task_revision": int(
                        pending.get("base_task_revision") or task_revision
                    ),
                    "new_task_revision": task_revision,
                    "active_skill_ids": list(activated_ids),
                    "plan_impact_decision": kind,
                },
            )
        candidate_snapshot_id = str(
            pending_proposal.get("candidate_snapshot_id")
            or ((pending.get("skill_change") or {}).get("proposal") or {}).get(
                "candidate_snapshot_id"
            )
            or ""
        )
        candidate_active_refs = [
            deepcopy(dict(item))
            for item in access.get("selected_skill_refs") or []
            if isinstance(item, Mapping)
            and str(item.get("snapshot_id") or "") == candidate_snapshot_id
            and str(item.get("status") or "") == "active"
        ]
        if candidate_snapshot_id and len(candidate_active_refs) != 1:
            raise SkillAccessError(
                "PLAN_IMPACT_PROPOSED_SKILL_NOT_BOUND",
                f"candidate_active_refs={len(candidate_active_refs)}",
            )
        candidate_ref = candidate_active_refs[0] if candidate_active_refs else {}
        current_step_id = str(
            (current_plan_step_with_index(latest)[1] or {}).get("step_id")
            or ""
        )
        canonical_active_refs = [
            deepcopy(dict(item))
            for item in access.get("selected_skill_refs") or []
            if isinstance(item, Mapping)
            and str(item.get("status") or "") == "active"
        ]
        canonical_by_identity = {
            tuple(str(item.get(field) or "") for field in (
                "skill_id", "snapshot_id", "source_path", "content_hash",
            )): item
            for item in canonical_active_refs
        }

        def canonicalize_step_skill_refs(
            value: Mapping[str, Any],
        ) -> Dict[str, Any]:
            step_row = deepcopy(dict(value or {}))
            raw_refs = step_row.get("skill_refs")
            if raw_refs is None:
                return step_row
            if not isinstance(raw_refs, list):
                raise SkillAccessError(
                    "PLAN_IMPACT_SKILL_REFERENCE_INVALID",
                    str(step_row.get("step_id") or current_step_id),
                )
            projected_refs: List[Dict[str, Any]] = []
            for raw_ref in raw_refs:
                if not isinstance(raw_ref, Mapping):
                    raise SkillAccessError(
                        "PLAN_IMPACT_SKILL_REFERENCE_INVALID",
                        str(step_row.get("step_id") or current_step_id),
                    )
                raw = deepcopy(dict(raw_ref))
                identity = tuple(str(raw.get(field) or "") for field in (
                    "skill_id", "snapshot_id", "source_path", "content_hash",
                ))
                projected_refs.append(deepcopy(dict(
                    canonical_by_identity.get(identity) or raw
                )))
            step_row["skill_refs"] = projected_refs
            step_row["skill_ids"] = list(dict.fromkeys(
                str(item.get("skill_id") or "")
                for item in projected_refs
                if str(item.get("skill_id") or "")
            ))
            return step_row

        decision_steps: List[Mapping[str, Any]] = []
        if kind == "BIND_AND_RESUME":
            bind_step = canonicalize_step_skill_refs({
                "step_id": current_step_id,
                "skill_refs": decision.get("skill_refs") or [],
            })
            decision["skill_refs"] = deepcopy(list(
                bind_step.get("skill_refs") or []
            ))
            decision_steps = [bind_step]
        elif kind == "PATCH_CURRENT_STEP":
            patched = canonicalize_step_skill_refs(
                dict(decision.get("replacement_step") or {})
            )
            decision["replacement_step"] = deepcopy(patched)
            decision_steps = [patched]
        elif kind == "REPLAN_SUFFIX":
            decision_steps = [
                canonicalize_step_skill_refs(item)
                for item in decision.get("replacement_suffix") or []
                if isinstance(item, Mapping)
            ]
            decision["replacement_suffix"] = deepcopy(decision_steps)
        elif kind == "FULL_REPLAN":
            decision_steps = [
                canonicalize_step_skill_refs(item)
                for item in decision.get("replacement_steps") or []
                if isinstance(item, Mapping)
            ]
            decision["replacement_steps"] = deepcopy(decision_steps)
        identity_fields = (
            "skill_id", "snapshot_id", "source_path", "content_hash",
        )
        candidate_bound = False
        for step_row in decision_steps:
            step_id = str(step_row.get("step_id") or current_step_id)
            for raw_ref in step_row.get("skill_refs") or []:
                if not isinstance(raw_ref, Mapping):
                    continue
                if (
                    all(
                        str(raw_ref.get(field) or "")
                        == str(candidate_ref.get(field) or "")
                        for field in identity_fields
                    )
                    and (
                        str(candidate_ref.get("scope") or "task") == "task"
                        or str(candidate_ref.get("target_step_id") or "")
                        == step_id
                    )
                ):
                    candidate_bound = True
                    break
            if candidate_bound:
                break
        if candidate_snapshot_id and not candidate_bound:
            raise SkillAccessError(
                "PLAN_IMPACT_PROPOSED_SKILL_NOT_BOUND",
                candidate_snapshot_id,
            )
        valid_snapshot_ids = list((access.get("snapshots") or {}).keys())
        updated = apply_plan_impact_review(
            latest,
            decision,
            base_task_revision=int(
                pending.get("base_task_revision") or task_revision
            ),
            new_task_revision=task_revision,
            valid_skill_snapshot_ids=valid_snapshot_ids,
            valid_skill_refs=[
                deepcopy(dict(item))
                for item in access.get("selected_skill_refs") or []
                if isinstance(item, Mapping)
                and str(item.get("status") or "") == "active"
            ],
        )
        updated_task_state = dict(updated.get("task_state") or {})
        updated_task_state.pop("pending_plan_impact_review", None)
        updated_task_state.pop("pending_skill_binding_proposal", None)
        updated_task_state.pop("skill_continuation_id", None)
        updated_access = close_stale_continuations(
            access,
            task_revision=task_revision,
            plan_revision=int(updated.get("plan_revision") or 0),
            current_step_id=str(updated.get("current_step_id") or ""),
            reason="plan_impact_applied",
        )
        updated_task_state["skill_access_state"] = updated_access
        updated_refs = deepcopy(list(
            updated_access.get("selected_skill_refs") or []
        ))
        updated_ids = self._active_skill_ids_from_refs(updated_refs)
        updated_task_state["selected_skill_refs"] = deepcopy(updated_refs)
        updated_task_state["selected_skills"] = list(updated_ids)
        updated["task_state"] = updated_task_state
        updated["skill_access_state"] = deepcopy(updated_access)
        updated["selected_skill_refs"] = deepcopy(updated_refs)
        updated["selected_skill_ids"] = list(updated_ids)
        save_plan_state(self.data_path, task_id, updated)
        plan_text = render_structured_plan(updated)
        plan_file = str(
            updated.get("plan_file")
            or Path(self.data_path) / "task_outputs" / task_id / "plan.md"
        )
        try:
            Path(plan_file).write_text(plan_text, encoding="utf-8")
            update_plan_markdown_status(plan_file, updated)
        except OSError:
            logger.exception(
                "Plan impact Markdown projection failed: task=%s", task_id
            )
        return {
            "messages": [response],
            "current_plan": plan_text,
            "plan_progress": render_plan_progress(updated),
            "plan_revision": int(updated.get("plan_revision") or 0),
            "plan_impact_review": deepcopy(decision),
            "pending_plan_impact_review": {},
            "skill_access_state": deepcopy(updated_access),
            "selected_skill_refs": deepcopy(updated_refs),
            "selected_skills": list(updated_ids),
            "selected_skill_ids": list(updated_ids),
            "skill_continuation_id": "",
            "pending_action": {},
            "next_step": "plan_review",
        }

    def _commit_consultant_update(
        self,
        task_id: str,
        update: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Commit a validated Consultant proposal before it leaves the node."""
        projected = dict(update or {})
        proposed_task = projected.get("task_spec")
        if not task_spec_is_initialized(proposed_task):
            return projected
        durable_before = load_plan_state(self.data_path, task_id)
        task_state_before = dict(durable_before.get("task_state") or {})
        prior_task = canonical_task_spec_for_state(durable_before)
        if "pending_human_question" in projected:
            pending_question = projected.get("pending_human_question") or {}
        else:
            pending_question = task_state_before.get("pending_question") or {}
        candidate = {
            "task_spec": proposed_task,
            "selected_skills": list(
                projected.get("selected_skills")
                or task_state_before.get("selected_skills")
                or durable_before.get("selected_skill_ids")
                or []
            ),
            "resolved_bindings": dict(
                projected.get("resolved_bindings")
                or task_state_before.get("resolved_bindings")
                or {}
            ),
            "consultation_state": dict(
                projected.get("consultation_state")
                or task_state_before.get("consultation_state")
                or {}
            ),
            "pending_question": dict(pending_question),
        }
        skill_selection_changed = False
        for skill_transaction_field in (
            "pending_skill_binding_proposal",
            "pending_plan_impact_review",
        ):
            if skill_transaction_field in projected:
                value = projected.get(skill_transaction_field)
                if value not in (None, {}) and not isinstance(value, Mapping):
                    raise ValueError(
                        f"{skill_transaction_field.upper()}_INVALID"
                    )
                candidate[skill_transaction_field] = deepcopy(
                    dict(value or {})
                )
        for precondition_field in (
            "expected_state_generation",
            "expected_plan_revision",
            "expected_user_turn_revision",
            "expected_pending_skill_proposal_id",
            "expected_pending_skill_proposal_status",
            "expected_pending_skill_snapshot_id",
        ):
            if precondition_field in projected:
                candidate[precondition_field] = deepcopy(
                    projected.get(precondition_field)
                )
        prior_selected_ids = list(
            task_state_before.get("selected_skills")
            or durable_before.get("selected_skill_ids")
            or []
        )
        prior_access = normalize_skill_access_state(
            task_state_before.get("skill_access_state")
            or durable_before.get("skill_access_state")
            or {"selected_skill_refs": durable_before.get("selected_skill_refs") or []}
        )
        if getattr(self, "skill_access_service", None) is not None:
            prior_access = self._prepare_durable_skill_access(
                durable_before,
                selected_skill_ids=prior_selected_ids,
                task_revision=task_spec_revision(prior_task),
            )
        binding_phase = classify_consultant_binding_phase(
            durable_before,
            access_state=prior_access,
        )
        candidate["binding_phase"] = deepcopy(binding_phase)
        projected["binding_phase"] = deepcopy(binding_phase)
        if binding_phase["phase"] == (
            ConsultantBindingPhase.INCONSISTENT_CANONICAL_STATE.value
        ):
            failure = {
                "classification": "INTERNAL_PROTOCOL",
                "code": "CONSULTANT_CANONICAL_STATE_INCONSISTENT",
                "detail": (
                    "Canonical TaskSpec, active Skill binding, and materialized "
                    "Plan partitions do not form a coherent binding phase."
                ),
                "binding_phase": deepcopy(binding_phase),
            }
            failed = dict(projected)
            failed.pop("task_spec", None)
            failed.update({
                "messages": [
                    *list(projected.get("messages") or []),
                    SystemMessage(content=json.dumps(
                        failure, ensure_ascii=False, sort_keys=True,
                    )),
                ],
                "skill_decision_result": failure,
                "consultant_commit_rejection": deepcopy(failure),
                "canonical_commit": {
                    "succeeded": False,
                    "error_code": "CONSULTANT_CANONICAL_STATE_INCONSISTENT",
                },
                "task_status": TASK_STATUS_FAILED,
                "failure_owner": "controller",
                "contract_status": "internal_protocol",
                "pending_action": {},
                "next_step": "finish",
            })
            return failed

        if (
            not task_spec_is_initialized(prior_task)
            and not managed_execution_admitted(
                task_state_before.get("intent_admission")
            )
        ):
            blocked = dict(projected)
            blocked.pop("task_spec", None)
            blocked.update({
                "task_status": TASK_STATUS_BLOCKED,
                "next_step": "finish",
                "canonical_commit": {
                    "succeeded": False,
                    "error_code": "MANAGED_INTENT_ADMISSION_REQUIRED",
                    "reason": (
                        "A new executable TaskSpec requires a current typed "
                        "managed-execution admission from the LLM router."
                    ),
                },
                "messages": [SystemMessage(content=(
                    "MANAGED_INTENT_ADMISSION_REQUIRED: the request was not "
                    "admitted as an explicit managed execution request; no "
                    "executable TaskSpec was committed."
                ))],
            })
            return blocked

        prior_active_ids = self._active_skill_ids_from_refs(
            prior_access.get("selected_skill_refs") or []
        )
        if getattr(self, "skill_access_service", None) is not None:
            requested_selected_ids = list(dict.fromkeys(
                str(item)
                for item in candidate.get("selected_skills") or []
                if str(item)
            ))
            prior_task_skill_ids = list(dict.fromkeys(
                str(item)
                for item in (
                    (prior_task.get("capability_intent") or {}).get(
                        "selected_skill_ids"
                    )
                    if isinstance(prior_task, Mapping)
                    else []
                )
                or []
                if str(item)
            ))
            proposed_task_skill_ids = list(dict.fromkeys(
                str(item)
                for item in (
                    (proposed_task.get("capability_intent") or {}).get(
                        "selected_skill_ids"
                    )
                    if isinstance(proposed_task, Mapping)
                    else []
                )
                or []
                if str(item)
            ))
            skill_selection_changed = (
                requested_selected_ids != prior_active_ids
                or proposed_task_skill_ids != prior_task_skill_ids
            )
            initial_binding = binding_phase["phase"] in {
                ConsultantBindingPhase.INITIAL_TASK_AND_SKILL_BOOTSTRAP.value,
                ConsultantBindingPhase.PREPLAN_INITIAL_SKILL_BIND.value,
            }
            existing_binding_change = bool(
                skill_selection_changed
                and binding_phase["phase"]
                == ConsultantBindingPhase.EXISTING_BINDING_CHANGE.value
            )
            projected_pending_impact = dict(
                projected.get("pending_plan_impact_review") or {}
            )
            projected_proposal_id = str(
                projected_pending_impact.get("proposal_id") or ""
            )
            durable_proposal = (
                prior_access.get("binding_proposals") or {}
            ).get(projected_proposal_id)
            projected_skill_change = dict(
                projected_pending_impact.get("skill_change") or {}
            )
            projected_candidate_refs = [
                dict(item)
                for item in projected_skill_change.get(
                    "candidate_skill_refs"
                )
                or []
                if isinstance(item, Mapping)
            ]
            projected_candidate_snapshot_id = str(
                (projected_skill_change.get("proposal") or {}).get(
                    "candidate_snapshot_id"
                )
                or (
                    projected_candidate_refs[0].get("snapshot_id")
                    if projected_candidate_refs
                    else ""
                )
                or ""
            )
            authorised_selected_ids: List[str] = []
            if isinstance(durable_proposal, Mapping):
                try:
                    authorised_selected_ids = (
                        self._authorised_task_skill_selection(
                            prior_access,
                            durable_proposal,
                        )
                    )
                except SkillAccessError:
                    authorised_selected_ids = []
            projected_candidate_matches = bool(
                isinstance(durable_proposal, Mapping)
                and len(projected_candidate_refs) == 1
                and str(projected_candidate_refs[0].get("skill_id") or "")
                == str(durable_proposal.get("candidate_skill_id") or "")
                and str(projected_candidate_refs[0].get("snapshot_id") or "")
                == str(durable_proposal.get("candidate_snapshot_id") or "")
                and str(projected_candidate_refs[0].get("status") or "")
                == "candidate"
            )
            authorised_transaction = bool(
                isinstance(projected.get("skill_access_state"), Mapping)
                and projected_proposal_id
                and isinstance(durable_proposal, Mapping)
                and str(durable_proposal.get("status") or "")
                == "approved_for_task_commit"
                and str(durable_proposal.get("candidate_snapshot_id") or "")
                == projected_candidate_snapshot_id
                and projected_candidate_matches
                and set(proposed_task_skill_ids)
                == set(authorised_selected_ids)
                and len(proposed_task_skill_ids)
                == len(authorised_selected_ids)
                # The reviewed candidate stays inactive until Planner accepts
                # PlanImpact; the compatibility projection must therefore
                # still expose exactly the prior active set at this commit.
                and set(requested_selected_ids) == set(prior_active_ids)
                and len(requested_selected_ids) == len(prior_active_ids)
            )
            if (
                existing_binding_change
                and not initial_binding
                and not authorised_transaction
            ):
                rejected = {
                    "decision_result": "SKILL_BINDING_PROPOSAL_REQUIRED",
                    "classification": "INTERNAL_PROTOCOL",
                    "detail": (
                        "A canonical Skill selection may change only through "
                        "PROPOSE_SKILL_BINDING, Consultant review, and the "
                        "pending Planner plan-impact transaction."
                    ),
                    "counts_as_failure": False,
                    "required_next_action": "PROPOSE_SKILL_BINDING",
                    "binding_phase": deepcopy(binding_phase),
                }
                rejected_consultation = deepcopy(dict(
                    candidate.get("consultation_state") or {}
                ))
                feedback_item = {
                    "code": "SKILL_BINDING_PROPOSAL_REQUIRED",
                    "instruction": rejected["detail"],
                    "required_next_action": "PROPOSE_SKILL_BINDING",
                }
                rejected_consultation.update({
                    "phase": "consulting",
                    "consultation_status": "active",
                    "completion_decision": "needs_evidence",
                    "completion_reason": "SKILL_BINDING_PROPOSAL_REQUIRED",
                    "last_feedback": [
                        *list(rejected_consultation.get("last_feedback") or [])[-7:],
                        feedback_item,
                    ],
                })
                prior_guard = dict(
                    rejected_consultation.get("last_invocation_guard") or {}
                )
                prior_guard["retry_pending"] = False
                rejected_consultation["last_invocation_guard"] = prior_guard
                candidate["consultation_state"] = rejected_consultation
                transition = consultant_commit_no_progress_fingerprint(
                    durable_before,
                    candidate=candidate,
                    active_skill_refs=binding_phase["active_skill_refs"],
                    effective_route="consultant",
                    rejection_reason=rejected,
                )
                ledger = advance_consultant_commit_no_progress(
                    task_state_before.get("consultant_no_progress_ledger"),
                    transition,
                    limit=MAX_CONSULTANT_IDENTICAL_NO_PROGRESS_TRANSITIONS,
                )
                rejection_record = {
                    **deepcopy(rejected),
                    "candidate_hash": transition["candidate_hash"],
                    "fingerprint": transition["fingerprint"],
                    "requested_selected_skill_ids": requested_selected_ids,
                    "prior_active_skill_ids": prior_active_ids,
                }
                blocked = dict(projected)
                blocked.pop("task_spec", None)
                blocked.update({
                    "messages": [
                        *list(projected.get("messages") or []),
                        SystemMessage(content=json.dumps(
                            rejected,
                            ensure_ascii=False,
                            sort_keys=True,
                        )),
                    ],
                    "selected_skills": list(prior_active_ids),
                    "selected_skill_ids": list(prior_active_ids),
                    "selected_skill_refs": deepcopy(list(
                        prior_access.get("selected_skill_refs") or []
                    )),
                    "skill_access_state": deepcopy(prior_access),
                    "skill_decision_result": rejected,
                    "consultation_state": rejected_consultation,
                    "consultant_commit_rejection": rejection_record,
                    "consultant_no_progress_ledger": ledger,
                    "pending_action": {},
                    "canonical_commit": {
                        "succeeded": False,
                        "error_code": "SKILL_BINDING_PROPOSAL_REQUIRED",
                    },
                    "next_step": "consultant",
                })
                if ledger.get("terminal"):
                    terminal = {
                        "classification": "INTERNAL_PROTOCOL",
                        "code": "CONSULTANT_COMMIT_NO_PROGRESS",
                        "detail": (
                            "The same Consultant candidate, commit rejection, "
                            "and self-route repeated without durable progress."
                        ),
                        "rejection": rejection_record,
                    }
                    blocked.update({
                        "messages": [
                            *list(blocked.get("messages") or []),
                            SystemMessage(content=json.dumps(
                                terminal, ensure_ascii=False, sort_keys=True,
                            )),
                        ],
                        "skill_decision_result": terminal,
                        "canonical_commit": {
                            "succeeded": False,
                            "error_code": "CONSULTANT_COMMIT_NO_PROGRESS",
                        },
                        "task_status": TASK_STATUS_FAILED,
                        "failure_owner": "controller",
                        "contract_status": "internal_protocol",
                        "next_step": "finish",
                    })
                return blocked
        accepted_statuses = {
            "semantic_contract_compiled",
            "canonical_task_ready",
        }
        accepted_handoff = dict(
            task_state_before.get("accepted_consultant_handoff") or {}
        )
        if (
            str(projected.get("contract_status") or "") in accepted_statuses
            or (
                str(projected.get("next_step") or "") == "planner"
                and str(projected.get("requirements_summary") or "").strip()
            )
        ):
            accepted_handoff = self._accepted_consultant_handoff_projection({
                **projected,
                "selected_skills": list(candidate["selected_skills"]),
            })
        if accepted_handoff:
            candidate["accepted_consultant_handoff"] = accepted_handoff
        if "planner_feedback" in projected:
            incoming_feedback = dict(projected.get("planner_feedback") or {})
            prior_feedback = dict(task_state_before.get("planner_feedback") or {})
            incoming_semantics = {
                "instructions": list(incoming_feedback.get("instructions") or []),
                "source_refs": list(incoming_feedback.get("source_refs") or []),
            }
            prior_semantics = {
                "instructions": list(prior_feedback.get("instructions") or []),
                "source_refs": list(prior_feedback.get("source_refs") or []),
            }
            incoming_feedback["revision"] = (
                int(prior_feedback.get("revision") or 0)
                + (1 if incoming_semantics != prior_semantics else 0)
            )
            candidate["planner_feedback"] = incoming_feedback
        semantic_changed = bool(
            not task_spec_is_initialized(prior_task)
            or task_semantic_hash(prior_task) != task_semantic_hash(proposed_task)
        )
        candidate_rejection = dict(
            projected.get("consultant_commit_rejection") or {}
        )
        rejected_self_route = bool(
            candidate_rejection
            and str(projected.get("next_step") or "") == "consultant"
        )
        semantic_commit_progress = bool(
            semantic_changed or skill_selection_changed
        )
        if rejected_self_route and not semantic_commit_progress:
            transition = consultant_commit_no_progress_fingerprint(
                durable_before,
                candidate=candidate,
                active_skill_refs=binding_phase["active_skill_refs"],
                effective_route="consultant",
                rejection_reason=candidate_rejection,
            )
            ledger = advance_consultant_commit_no_progress(
                task_state_before.get("consultant_no_progress_ledger"),
                transition,
                limit=MAX_CONSULTANT_IDENTICAL_NO_PROGRESS_TRANSITIONS,
            )
            rejection_record = {
                **deepcopy(candidate_rejection),
                "candidate_hash": transition["candidate_hash"],
                "fingerprint": transition["fingerprint"],
            }
            if ledger.get("terminal"):
                terminal = {
                    "classification": "INTERNAL_PROTOCOL",
                    "code": "CONSULTANT_COMMIT_NO_PROGRESS",
                    "detail": (
                        "The same Consultant candidate, commit rejection, "
                        "and self-route repeated without durable progress."
                    ),
                    "rejection": rejection_record,
                }
                failed = dict(projected)
                failed.pop("task_spec", None)
                failed.update({
                    "messages": [
                        *list(projected.get("messages") or []),
                        SystemMessage(content=json.dumps(
                            terminal, ensure_ascii=False, sort_keys=True,
                        )),
                    ],
                    "skill_decision_result": terminal,
                    "consultant_commit_rejection": rejection_record,
                    "consultant_no_progress_ledger": ledger,
                    "canonical_commit": {
                        "succeeded": False,
                        "error_code": "CONSULTANT_COMMIT_NO_PROGRESS",
                    },
                    "task_status": TASK_STATUS_FAILED,
                    "failure_owner": "controller",
                    "contract_status": "internal_protocol",
                    "pending_action": {},
                    "next_step": "finish",
                })
                return failed
            candidate["consultant_no_progress_ledger"] = ledger
            candidate["consultant_commit_rejection"] = rejection_record
            projected["consultant_no_progress_ledger"] = deepcopy(ledger)
            projected["consultant_commit_rejection"] = deepcopy(
                rejection_record
            )
        post_bootstrap_plan_impact_required = bool(
            semantic_changed
            and task_spec_is_initialized(prior_task)
            and has_materialized_plan(durable_before)
            and str(projected.get("next_step") or "") == "planner"
            and not dict(candidate.get("pending_plan_impact_review") or {})
            and not bool(projected.get("_plan_impact_rejection_rollback"))
        )
        if post_bootstrap_plan_impact_required:
            old_task_revision = task_spec_revision(prior_task)
            new_task_revision = task_spec_revision(proposed_task)
            impact_id = "taskspec-impact-" + hashlib.sha256(json.dumps({
                "old_task_hash": task_semantic_hash(prior_task),
                "new_task_hash": task_semantic_hash(proposed_task),
                "old_task_revision": old_task_revision,
                "new_task_revision": new_task_revision,
                "base_plan_revision": int(
                    durable_before.get("plan_revision") or 0
                ),
            }, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()[:20]
            durable_access = normalize_skill_access_state(
                task_state_before.get("skill_access_state")
                or durable_before.get("skill_access_state")
            )
            old_active_refs = [
                deepcopy(dict(item))
                for item in durable_access.get("selected_skill_refs") or []
                if isinstance(item, Mapping)
                and str(item.get("status") or "") == "active"
            ]
            generic_impact = {
                "mode": "plan_impact_review",
                "impact_kind": "taskspec_semantic_change",
                "proposal_id": impact_id,
                "base_task_revision": old_task_revision,
                "new_task_revision": new_task_revision,
                "base_plan_revision": int(
                    durable_before.get("plan_revision") or 0
                ),
                "base_user_turn_revision": (
                    self._authoritative_user_turn_revision(durable_before)
                ),
                "skill_change": {
                    "change_kind": "taskspec_semantic_change",
                    "old_task_spec": deepcopy(prior_task),
                    "new_task_spec": deepcopy(proposed_task),
                    "old_active_skill_refs": old_active_refs,
                    "candidate_skill_refs": [],
                },
                "status": "pending",
            }
            candidate["pending_plan_impact_review"] = deepcopy(
                generic_impact
            )
            projected["pending_plan_impact_review"] = deepcopy(
                generic_impact
            )
        pending_review_classification = dict(
            task_state_before.get("pending_review_classification") or {}
        )
        planner_reconciliation = dict(
            task_state_before.get("planner_reconciliation") or {}
        )
        planner_feedback_present = bool(
            isinstance(projected.get("planner_feedback"), Mapping)
            and projected.get("planner_feedback")
        )
        genuine_user_owned_ambiguity = bool(
            str(projected.get("next_step") or "") == "ask_user"
            and isinstance(pending_question, Mapping)
            and str(pending_question.get("owner") or "") == "user"
            and list(pending_question.get("requested_slots") or [])
        )
        reconciliation_completed = bool(
            planner_reconciliation
            and str(projected.get("next_step") or "") in {"planner", "ask_user", "finish"}
        )
        reconciliation_ledger: Dict[str, Any] = dict(
            task_state_before.get("reconciliation_ledger") or {}
        )
        if reconciliation_completed:
            if genuine_user_owned_ambiguity:
                consultant_outcome = "genuine_user_owned_ambiguity"
            elif semantic_changed:
                consultant_outcome = "taskspec_semantic_mutation"
            elif planner_feedback_present:
                consultant_outcome = "planner_feedback_only"
            else:
                consultant_outcome = "no_semantic_progress"
            reconciliation_ledger = record_reconciliation_outcome(
                reconciliation_ledger,
                fingerprint=str(planner_reconciliation.get("fingerprint") or ""),
                task_semantic_revision=task_spec_revision(proposed_task),
                task_semantic_identity=str(
                    planner_reconciliation.get("task_semantic_identity") or ""
                ),
                relevant_evidence_revision=int(
                    planner_reconciliation.get("relevant_evidence_revision") or 0
                ),
                consultant_outcome=consultant_outcome,
                semantic_changed=semantic_changed,
                genuine_user_owned_ambiguity=genuine_user_owned_ambiguity,
            )
            candidate["reconciliation_ledger"] = reconciliation_ledger
            candidate["planner_reconciliation"] = {}
            candidate["planning_epoch"] = {
                **dict(task_state_before.get("planning_epoch") or {}),
                "status": (
                    "reconciliation_user_owned"
                    if genuine_user_owned_ambiguity
                    else "reconciliation_completed"
                ),
            }
        if pending_review_classification:
            # A Consultant invocation consumes exactly one pending review
            # classification. Whether it invalidates approval is determined
            # solely by the typed semantic result below; the Controller never
            # inspects the user's review prose.
            candidate["pending_review_classification"] = {}
            if (
                str(projected.get("next_step") or "")
                in {"planner", "ask_user", "finish"}
                and not genuine_user_owned_ambiguity
                and (semantic_changed or planner_feedback_present)
            ):
                candidate["approval_transition"] = {
                    "status": (
                        "superseded" if semantic_changed else "changes_requested"
                    ),
                    "decision_source": "consultant_typed_review_classification",
                    "review_event_id": str(
                        pending_review_classification.get("review_event_id") or ""
                    ),
                }
        if getattr(self, "skill_access_service", None) is not None:
            projected_skill_access = projected.get("skill_access_state")
            prepared_skill_access = (
                normalize_skill_access_state(projected_skill_access)
                if isinstance(projected_skill_access, Mapping)
                else self._prepare_durable_skill_access(
                    durable_before,
                    selected_skill_ids=candidate["selected_skills"],
                    task_revision=task_spec_revision(proposed_task),
                )
            )
            candidate["skill_access_state"] = prepared_skill_access
            candidate["selected_skill_refs"] = deepcopy(list(
                prepared_skill_access.get("selected_skill_refs") or []
            ))
        # A semantic Task/Skill commit or a non-rejected handoff is durable
        # progress. Clear the rejection ledger in that same CAS boundary.
        # An identical rejected self-route instead carries the ledger written
        # above, even though its compatibility projection is also refreshed.
        if semantic_commit_progress or not rejected_self_route:
            candidate["consultant_no_progress_ledger"] = {}
            candidate["consultant_commit_rejection"] = {}
        committed = commit_consultant_candidate_state(
            self.data_path,
            task_id,
            candidate,
        )
        committed_task = canonical_task_spec_for_state(committed)
        committed_state = dict(committed.get("task_state") or {})
        projected.update({
            "task_spec": deepcopy(committed_task),
            "task_revision": task_spec_revision(committed_task),
            "selected_skills": list(committed_state.get("selected_skills") or []),
            "selected_skill_refs": deepcopy(list(
                committed_state.get("selected_skill_refs")
                or committed.get("selected_skill_refs")
                or []
            )),
            "skill_access_state": deepcopy(dict(
                committed_state.get("skill_access_state")
                or committed.get("skill_access_state")
                or {}
            )),
            "resolved_bindings": deepcopy(dict(
                committed_state.get("resolved_bindings") or {}
            )),
            "consultation_state": deepcopy(dict(
                committed_state.get("consultation_state") or {}
            )),
            "pending_human_question": deepcopy(dict(
                committed_state.get("pending_question") or {}
            )),
            "accepted_consultant_handoff": deepcopy(dict(
                committed_state.get("accepted_consultant_handoff") or {}
            )),
            "conversation_evidence": deepcopy(dict(
                committed.get("conversation_evidence") or {}
            )),
            "canonical_commit": {
                "succeeded": True,
                "task_revision": task_spec_revision(committed_task),
                "state_generation": int(committed.get("state_generation") or 0),
                "binding_phase": str(binding_phase.get("phase") or ""),
            },
            "binding_phase": deepcopy(binding_phase),
            "consultant_no_progress_ledger": deepcopy(dict(
                committed_state.get("consultant_no_progress_ledger") or {}
            )),
            "consultant_commit_rejection": deepcopy(dict(
                committed_state.get("consultant_commit_rejection") or {}
            )),
        })
        for skill_transaction_field in (
            "pending_skill_binding_proposal",
            "pending_plan_impact_review",
        ):
            if skill_transaction_field in projected:
                projected[skill_transaction_field] = deepcopy(dict(
                    committed_state.get(skill_transaction_field) or {}
                ))
        planner_feedback = committed_state.get("planner_feedback")
        if isinstance(planner_feedback, Mapping):
            projected["planner_feedback"] = deepcopy(dict(planner_feedback))
        if reconciliation_completed:
            terminal_status = str(reconciliation_ledger.get("terminal_status") or "")
            if terminal_status:
                projected.update({
                    "task_status": TASK_STATUS_BLOCKED,
                    "next_step": "finish",
                    "messages": [SystemMessage(content=(
                        "TASKSPEC_RECONCILIATION_NONPROGRESS: Planner and Consultant "
                        "repeated the same typed reconciliation without TaskSpec or "
                        "relevant-evidence progress."
                    ))],
                })
            elif not genuine_user_owned_ambiguity:
                projected["next_step"] = "planner"
        if (
            pending_review_classification
            and not semantic_changed
            and not planner_feedback_present
            and not genuine_user_owned_ambiguity
            and not reconciliation_completed
        ):
            # The Consultant's typed result was "neither": preserve the
            # reviewed Plan/approval and return to Human Review.  The
            # Controller does not inspect the user's free text.
            projected["next_step"] = "plan_review"
            projected["review_classification"] = "explanation_only"
        projected.pop("_plan_impact_rejection_rollback", None)
        return projected

    def _stale_plan_task_revision_reason(self, state: AgentState, task_id: str) -> str:
        plan_state = load_plan_state(self.data_path, task_id)
        if not plan_state.get("steps"):
            return ""
        task_revision = self._task_revision_for_state({
            **dict(state),
            "task_id": task_id,
        })
        try:
            plan_revision = int(plan_state.get("generated_from_task_revision") or 0)
        except (TypeError, ValueError):
            plan_revision = 0
        if task_revision <= 0 or task_revision == plan_revision:
            return ""
        return (
            f"The effective task is revision {task_revision}, but the approved plan was generated from "
            f"task revision {plan_revision}. Re-plan before generating or executing another action."
        )

    def _supervisor_feedback_snapshot(
        self,
        update: Dict[str, Any],
        state: AgentState,
        task_id: str,
    ) -> Dict[str, Any]:
        relevant = [
            str(getattr(message, "content", message) or "")
            for message in list(update.get("messages", []) or [])
            if any(
                marker in str(getattr(message, "content", message) or "")
                for marker in (
                    "<supervisor_feedback",
                    "Step completion validation failed",
                    "Final completion validation failed",
                    "Knowledge conflict",
                )
            )
        ]
        plan_state = load_plan_state(self.data_path, task_id)
        structured = update.get("supervisor_feedback") or {}
        evidence = update.get("execution_evidence") or state.get("execution_evidence") or {}
        return {
            "verdict": str(structured.get("verdict") or update.get("supervisor_verdict") or ""),
            "text": self._clip_observation_text("\n\n".join(relevant[-4:]), 4000),
            "step_id": str(
                evidence.get("step_id")
                or (self._running_plan_step(plan_state) or {}).get("step_id")
                or ""
            ),
            "plan_version": str(plan_state.get("plan_version") or "plan_v1"),
            "task_revision": self._task_revision_for_state(dict(state)),
            "execution_id": str(evidence.get("execution_id") or evidence.get("action_id") or ""),
            "failed_checks": [
                {
                    "rule": str(item.get("rule") or "")[:160],
                    "severity": str(item.get("severity") or "")[:40],
                    "message": self._clip_observation_text(item.get("message"), 700),
                }
                for item in list(structured.get("failed_checks") or [])[-8:]
                if isinstance(item, dict)
            ],
            "required_fix": [
                self._clip_observation_text(item, 700)
                for item in list(structured.get("required_fix") or [])[-8:]
            ],
            "retryable": bool(structured.get("retryable")),
            "retry_reason": self._clip_observation_text(update.get("retry_reason"), 1200),
            "failed_step_id": str(update.get("failed_step_id") or ""),
            "failure_fingerprint": str(update.get("failure_fingerprint") or ""),
            "required_next_action": str(update.get("required_next_action") or ""),
            "recovery_scope": str(update.get("recovery_scope") or ""),
            "evidence_status": str(update.get("evidence_status") or ""),
        }

    async def _adjudicate_post_review_recovery(
        self,
        state: AgentState,
        update: Dict[str, Any],
        task_id: str,
    ) -> Dict[str, Any]:
        """Use the shared trigger/context schema for Supervisor/Gate conflicts."""
        merged = {**dict(state), **dict(update or {})}
        evidence = merged.get("execution_evidence") or state.get("execution_evidence") or {}
        if not isinstance(evidence, dict) or not evidence:
            return update
        store = RecoveryStateStore(self.data_path, task_id)
        history = store.load_attempts()
        current_execution_id = str(evidence.get("execution_id") or "")
        history.extend(
            item for item in store.load_execution_records()
            if str(item.get("execution_id") or "") != current_execution_id
        )
        trigger = evaluate_recovery_trigger(merged, evidence, recovery_history=history)
        update["recovery_trigger"] = trigger.to_dict()
        if not trigger.required:
            return update

        plan_state = load_plan_state(self.data_path, task_id)
        active_skills = [str(item) for item in merged.get("active_skills") or [] if str(item).strip()]
        skill_continuation_id = str(
            (plan_state.get("task_state") or {}).get("skill_continuation_id")
            or ""
        )
        if getattr(self, "skill_access_service", None) is not None:
            prior_skill_access = normalize_skill_access_state(
                (plan_state.get("task_state") or {}).get("skill_access_state")
                or plan_state.get("skill_access_state")
            )
            prepared_skill_access = self._prepare_durable_skill_access(
                plan_state,
                selected_skill_ids=active_skills,
                task_revision=task_spec_revision(
                    canonical_task_spec_for_state(plan_state)
                ),
            )
            if prepared_skill_access != prior_skill_access:
                try:
                    self._persist_durable_skill_access(
                        task_id,
                        prepared_skill_access,
                        continuation_id=skill_continuation_id,
                        expected_state_generation=int(
                            plan_state.get("state_generation") or 0
                        ),
                    )
                except StateCASConflict as exc:
                    stale_update = self._skill_access_cas_stale_update(
                        caller_node="recovery",
                        next_step="supervisor",
                        detail=str(exc),
                    )
                    stale_update["messages"] = [
                        *list(update.get("messages") or []),
                        *list(stale_update.get("messages") or []),
                    ]
                    return {**update, **stale_update}
                plan_state = load_plan_state(self.data_path, task_id)
        skill_context = ""
        if active_skills:
            try:
                skill_context = self.skill_manager.get_execution_cards(active_skills)
            except Exception as exc:  # noqa: BLE001 - diagnostic context is best effort.
                skill_context = f"active skill policy unavailable: {exc}"
        context = build_recovery_context(
            merged,
            evidence,
            plan_state=plan_state,
            task_root=Path(self.data_path) / "task_outputs" / task_id,
            skill_policy={
                "skill_ids": active_skills,
                "relevant_context": self._clip_observation_text(skill_context, 3000),
            },
            recovery_history=history,
        )
        # RecoveryContext remains the durable evidence record.  The model does
        # not receive its control IDs/refs or the legacy load-all/compact view.
        diagnosis = dict(context.diagnosis or {})
        recovery_task_spec = canonical_task_spec_for_state(plan_state)
        recovery_evidence: List[Dict[str, Any]] = []
        if context.bounded_log_excerpt:
            recovery_evidence.append({
                "evidence_id": context.context_id + ":log",
                "kind": "execution_log",
                "excerpt": context.bounded_log_excerpt,
                "truncated": True,
            })
        for index, item in enumerate(diagnosis.get("evidence") or [], start=1):
            recovery_evidence.append({
                "evidence_id": context.context_id + f":diagnosis:{index}",
                "kind": "diagnostic_fact",
                "excerpt": str(item),
                "truncated": False,
            })
        recovery_context_kwargs = {
            "node_type": "recovery",
            "task_spec": recovery_task_spec,
            "plan_state": plan_state,
            "state_generation": int(plan_state.get("state_generation") or 0),
            "current_step_id": str(context.step_id or evidence.get("step_id") or ""),
            "runtime": {
                "recovery_focus": {
                    "current_step": dict(context.current_step or {}),
                    "success_criteria": list(
                        (context.current_step or {}).get("success_criteria") or []
                    ),
                    "previous_action": dict(context.action_contract or {}),
                    "previous_script": str((context.execution or {}).get("code") or ""),
                    "previous_generated_script_ref": dict(
                        evidence.get("generated_script") or {}
                    ),
                    "previous_approved_script_ref": dict(
                        evidence.get("approved_script") or {}
                    ),
                    "failed_command": str(
                        (context.execution or {}).get("failed_command") or ""
                    ),
                    "exit_code": (context.execution or {}).get("returncode"),
                    "bounded_stdout": str(
                        (context.execution or {}).get("stdout_tail") or ""
                    ),
                    "bounded_stderr": str(
                        (context.execution or {}).get("stderr_tail") or ""
                    ),
                    "expected_runtime": dict(
                        (context.execution or {}).get("expected_runtime_contract") or {}
                    ),
                    "actual_runtime": dict(
                        (context.execution or {}).get("actual_environment") or {}
                    ),
                    "controller_machine_audit_findings": list(
                        context.machine_audit_findings or []
                    ),
                    "available_evidence": list(context.available_evidence or []),
                },
                "action_contract": dict(context.action_contract or {}),
                "execution": dict(context.execution or {}),
                "validation": dict(context.validation or {}),
                "completion": dict(context.completion or {}),
                "progress": dict(context.progress or {}),
                "recent_attempts": list(context.recent_attempts or []),
                "already_tried_strategies": list(context.already_tried_strategies or []),
                "skill_policy": dict(context.skill_policy or {}),
            },
            "feedback": {
                "diagnosis": {
                    key: value for key, value in diagnosis.items()
                    if key != "evidence"
                },
                "conflicts": list(context.conflicts or []),
            },
            "evidence": recovery_evidence,
            "allowed_operations": [item.value for item in RecoveryAction],
            "attempt_id": str(context.attempt_id or evidence.get("attempt_id") or ""),
            "failure_fingerprint": str(context.error_fingerprint or ""),
            "evidence_identity": str(context.context_id or ""),
            "trace_enabled": bool(os.getenv("NODE_CONTEXT_V2_TRACE", "")),
            "max_payload_chars": RECOVERY_PROVIDER_MAX_PAYLOAD_CHARS,
            "authoritative_user_turn_revision": (
                self._authoritative_user_turn_revision(plan_state)
            ),
            "skill_context": self._skill_context_projection(
                plan_state,
                caller_node="recovery",
                current_step_id=str(
                    context.step_id or evidence.get("step_id") or ""
                ),
                continuation_id=skill_continuation_id,
            ),
            "continuation_id": skill_continuation_id,
        }
        try:
            evidence_returncode = int(
                evidence.get("returncode")
                if evidence.get("returncode") is not None
                else evidence.get("exit_code")
            )
        except (TypeError, ValueError):
            evidence_returncode = None
        structured_execution_failed = (
            evidence_returncode not in {None, 0}
            or str(evidence.get("execution_status") or "").lower() == "failed"
        )
        judge_needed = diagnosis_required(trigger, evidence, merged)
        post_review_judge_invoked = False
        cached_judge_valid = False
        if not judge_needed and trigger.deterministic_action:
            decision = deterministic_recovery_decision(trigger, evidence)
        elif diagnosis.get("collection_complete") and not judge_needed and (
            structured_execution_failed or diagnosis.get("evidence_sufficient")
        ):
            decision = recovery_decision_from_diagnosis(diagnosis)
        elif judge_needed:
            recovery_cache_identity = {
                "task_revision": task_spec_revision(
                    canonical_task_spec_for_state(plan_state)
                ),
                "plan_revision": int(plan_state.get("plan_revision") or 0),
                "authoritative_user_turn_revision": (
                    self._authoritative_user_turn_revision(plan_state)
                ),
                "step_id": str(context.step_id or evidence.get("step_id") or ""),
                "attempt_id": str(
                    context.attempt_id or evidence.get("attempt_id") or ""
                ),
                "evidence_identity": str(context.context_id or ""),
                "continuation_id": skill_continuation_id,
            }
            cached_judge = store.load_llm_result(
                context.context_id,
                "recovery_judge",
                cache_identity=recovery_cache_identity,
            )
            cached_judge_valid = False
            if cached_judge.get("parsed_result"):
                try:
                    decision = RecoveryDecision.from_mapping(cached_judge["parsed_result"])
                    cached_judge_valid = True
                except (TypeError, ValueError):
                    cached_judge_valid = False
            if not cached_judge:
                try:
                    post_review_judge_invoked = True
                    recovery_judge_budget_charged = False
                    recovery_round_plan = plan_state
                    skill_context_rounds = 0
                    skill_search_rounds = 0
                    recovery_skill_round_limit = max(
                        1,
                        int(MAX_SKILL_CONTEXT_ROUNDS_PER_INVOCATION)
                        + int(MAX_SKILL_SEARCH_ROUNDS_PER_STEP),
                    )
                    for skill_round in range(recovery_skill_round_limit + 1):
                        recovery_approved_snapshot = load_approved_plan_snapshot(
                            self.data_path,
                            task_id,
                            state=recovery_round_plan,
                        )
                        recovery_semantic_inputs = self._node_context_semantic_inputs(
                            task_id,
                            recovery_round_plan,
                            messages=list(state.get("messages") or []),
                        )
                        round_task_spec = canonical_task_spec_for_state(
                            recovery_round_plan
                        )
                        round_step_id = str(
                            context.step_id or evidence.get("step_id") or ""
                        )
                        round_skill_context = self._skill_context_projection(
                            recovery_round_plan,
                            caller_node="recovery",
                            current_step_id=round_step_id,
                            continuation_id=skill_continuation_id,
                        )
                        recovery_node_context = build_node_context(
                            **{
                                **recovery_context_kwargs,
                                "task_spec": round_task_spec,
                                "plan_state": recovery_round_plan,
                                "state_generation": int(
                                    recovery_round_plan.get("state_generation") or 0
                                ),
                                "skill_context": round_skill_context,
                                "continuation_id": skill_continuation_id,
                            },
                            approved_plan_snapshot=recovery_approved_snapshot,
                            **recovery_semantic_inputs,
                        )
                        if (
                            getattr(self, "skill_access_service", None) is not None
                            and skill_continuation_id
                        ):
                            round_access = normalize_skill_access_state(
                                (recovery_round_plan.get("task_state") or {}).get(
                                    "skill_access_state"
                                )
                                or recovery_round_plan.get("skill_access_state")
                            )
                            round_continuation = dict(
                                (round_access.get("continuations") or {}).get(
                                    skill_continuation_id
                                )
                                or {}
                            )
                            if str(round_continuation.get("status") or "") in {
                                "served", "rejected",
                            }:
                                round_access = mark_continuation_resumed(
                                    round_access,
                                    skill_continuation_id,
                                    resumed_invocation_id=(
                                        recovery_node_context.binding.invocation_id
                                    ),
                                )
                                try:
                                    self._persist_durable_skill_access(
                                        task_id,
                                        round_access,
                                        continuation_id=skill_continuation_id,
                                        expected_state_generation=int(
                                            recovery_round_plan.get(
                                                "state_generation"
                                            )
                                            or 0
                                        ),
                                    )
                                except StateCASConflict as exc:
                                    stale_update = (
                                        self._skill_access_cas_stale_update(
                                            caller_node="recovery",
                                            next_step="supervisor",
                                            detail=str(exc),
                                        )
                                    )
                                    stale_update["messages"] = [
                                        *list(update.get("messages") or []),
                                        *list(stale_update.get("messages") or []),
                                    ]
                                    return {**update, **stale_update}
                                recovery_round_plan = load_plan_state(
                                    self.data_path, task_id
                                )
                        prompt = PromptManager.get_recovery_v2_prompt(
                            recovery_node_context.llm_payload.to_provider_dict()
                        )
                        response = await self._ainvoke_node_llm(
                            [HumanMessage(content=prompt)],
                            node_context=recovery_node_context,
                            stage="recovery_judge",
                            task_id=task_id,
                            task_mode=str(state.get("task_mode") or "managed"),
                            trace_metadata={
                                "call_kind": "recovery_judge",
                                "attempt_id": str(evidence.get("attempt_id") or ""),
                                "action_id": str(evidence.get("action_id") or ""),
                                "step_id": str(evidence.get("step_id") or ""),
                                "recovery_context_ref": str(
                                    store.root / "recovery_context.json"
                                ),
                                "provider_context_manifest": provider_context_manifest(
                                    recovery_node_context.llm_payload
                                ),
                                "recovery_llm_policy": dict(self.recovery_llm_policy),
                            },
                            llm_override=self.recovery_llm,
                            llm_policy=self.recovery_llm_policy,
                        )
                        raw_response = str(
                            getattr(response, "content", response) or ""
                        )
                        current_plan_state = load_plan_state(self.data_path, task_id)
                        current_task_spec = canonical_task_spec_for_state(
                            current_plan_state
                        )
                        current_approved_snapshot = load_approved_plan_snapshot(
                            self.data_path,
                            task_id,
                            state=current_plan_state,
                        )
                        current_task_state = dict(
                            current_plan_state.get("task_state") or {}
                        )
                        current_continuation_id = str(
                            current_task_state.get("skill_continuation_id")
                            or ""
                        )
                        current_binding = build_node_context(
                            node_type="recovery",
                            task_spec=current_task_spec,
                            plan_state=current_plan_state,
                            state_generation=int(
                                current_plan_state.get("state_generation") or 0
                            ),
                            current_step_id=round_step_id,
                            attempt_id=str(
                                context.attempt_id or evidence.get("attempt_id") or ""
                            ),
                            failure_fingerprint=str(context.error_fingerprint or ""),
                            evidence_identity=str(context.context_id or ""),
                            authoritative_user_turn_revision=(
                                self._authoritative_user_turn_revision(
                                    current_plan_state
                                )
                            ),
                            approved_plan_snapshot=current_approved_snapshot,
                            skill_context=self._skill_context_projection(
                                current_plan_state,
                                caller_node="recovery",
                                current_step_id=round_step_id,
                                continuation_id=current_continuation_id,
                            ),
                            continuation_id=current_continuation_id,
                        ).binding
                        staleness = evaluate_node_staleness(
                            recovery_node_context.binding,
                            current_binding.to_dict(),
                        )
                        if not staleness.usable:
                            self._node_invocations.mark_stale_signature_handled(
                                staleness.stale_signature
                            )
                            changed = list(staleness.changed_preconditions)
                            resume_route = (
                                "consultant"
                                if any(
                                    item in {
                                        "authoritative_user_turn_revision",
                                        "task_revision",
                                        "task_semantic_hash",
                                    }
                                    for item in changed
                                )
                                else "planner"
                                if any(
                                    item in {
                                        "plan_revision", "plan_version",
                                        "step_id", "step_revision",
                                    }
                                    for item in changed
                                )
                                else "supervisor"
                            )
                            stale_result = {
                                "decision_result": "STALE_NODE_RESULT",
                                "status": "discarded",
                                "code": str(
                                    staleness.code
                                    or "STALE_RECOVERY_CONTEXT"
                                ),
                                "caller_node": "recovery",
                                "caller_invocation_id": str(
                                    recovery_node_context.binding.invocation_id
                                    or ""
                                ),
                                "changed_preconditions": changed,
                                "request_task_revision": int(
                                    recovery_node_context.binding.task_revision
                                    or 0
                                ),
                                "request_plan_revision": int(
                                    recovery_node_context.binding.plan_revision
                                    or 0
                                ),
                                "request_user_turn_revision": int(
                                    recovery_node_context.binding
                                    .authoritative_user_turn_revision
                                    or 0
                                ),
                                "current_task_revision": int(
                                    current_binding.task_revision or 0
                                ),
                                "current_plan_revision": int(
                                    current_binding.plan_revision or 0
                                ),
                                "current_user_turn_revision": int(
                                    current_binding
                                    .authoritative_user_turn_revision
                                    or 0
                                ),
                                "resume_route": resume_route,
                                "counts_as_failure": False,
                                "consumes_execution_retry": False,
                                "consumes_recovery_retry": False,
                                "execute": False,
                            }
                            self._record_durable_skill_event(
                                task_id,
                                "stale_node_result_discarded",
                                stale_result,
                            )
                            update.update({
                                "messages": [
                                    *list(update.get("messages") or []),
                                    response,
                                    SystemMessage(content=json.dumps(
                                        stale_result,
                                        ensure_ascii=False,
                                        sort_keys=True,
                                    )),
                                ],
                                "stale_node_result": deepcopy(stale_result),
                                "decision_result": "STALE_NODE_RESULT",
                                "counts_as_failure": False,
                                "consumes_execution_retry": False,
                                "consumes_recovery_retry": False,
                                "next_step": resume_route,
                                "proposed_route": resume_route,
                            })
                            return update

                        if not recovery_judge_budget_charged:
                            accepted_plan = load_plan_state(
                                self.data_path, task_id
                            )
                            increment_plan_budget(
                                accepted_plan, "recovery_judge_count"
                            )
                            save_plan_state(
                                self.data_path, task_id, accepted_plan
                            )
                            recovery_judge_budget_charged = True

                        try:
                            typed_skill_decision = parse_typed_skill_decision(
                                raw_response
                            )
                        except SkillAccessError as skill_exc:
                            rejected_projection: Dict[str, Any] = {}
                            if skill_continuation_id:
                                rejected_projection = (
                                    self._complete_durable_skill_continuation(
                                        task_id,
                                        caller_node="recovery",
                                    )
                                )
                                skill_continuation_id = ""
                            rejected = {
                                "decision_result": "SKILL_DECISION_REJECTED",
                                **skill_exc.to_dict(),
                                "review_route": "consultant_skill_resolution",
                            }
                            update.update({
                                **rejected_projection,
                                "messages": [
                                    *list(update.get("messages") or []),
                                    response,
                                    SystemMessage(content=json.dumps(
                                        rejected,
                                        ensure_ascii=False,
                                        sort_keys=True,
                                    )),
                                ],
                                "skill_decision_result": rejected,
                                "pending_action": {},
                                "pending_recovery_action": {},
                                "required_next_action": "",
                                "recovery_scope": "",
                                "recovery_phase": "skill_review",
                                "transition_guard": (
                                    "recovery_skill_review_required"
                                ),
                                "next_step": "consultant",
                                "proposed_route": "consultant",
                            })
                            return update
                        if typed_skill_decision is None:
                            decision = parse_recovery_judge_decision(raw_response)
                            if skill_continuation_id:
                                update.update(
                                    self._complete_durable_skill_continuation(
                                        task_id,
                                        caller_node="recovery",
                                    )
                                )
                                skill_continuation_id = ""
                            store.save_llm_result(
                                context.context_id,
                                "recovery_judge",
                                raw_response=raw_response,
                                parsed_result=decision.to_dict(),
                                cache_identity=recovery_cache_identity,
                            )
                            break

                        typed_skill_kind = str(
                            typed_skill_decision.get("decision") or ""
                        ).upper()
                        request_budget_exhausted = (
                            typed_skill_kind == REQUEST_SKILL_CONTEXT
                            and skill_context_rounds
                            >= int(MAX_SKILL_CONTEXT_ROUNDS_PER_INVOCATION)
                        ) or (
                            typed_skill_kind == SEARCH_SKILLS
                            and skill_search_rounds
                            >= int(MAX_SKILL_SEARCH_ROUNDS_PER_STEP)
                        )
                        if request_budget_exhausted:
                            completed_projection: Dict[str, Any] = {}
                            if skill_continuation_id:
                                completed_projection = (
                                    self._complete_durable_skill_continuation(
                                        task_id,
                                        caller_node="recovery",
                                    )
                                )
                                skill_continuation_id = ""
                            limit_status = (
                                "SKILL_CONTEXT_NO_PROGRESS"
                                if typed_skill_kind == REQUEST_SKILL_CONTEXT
                                else "SKILL_SEARCH_NO_PROGRESS"
                            )
                            limit_result = {
                                "decision_result": (
                                    "SKILL_CONTINUATION_LIMIT_REACHED"
                                ),
                                "status": limit_status,
                                "detail": (
                                    "Recovery exhausted the configured Skill "
                                    "request rounds."
                                ),
                                "review_route": (
                                    "consultant_skill_resolution"
                                ),
                            }
                            update.update({
                                **completed_projection,
                                "messages": [
                                    *list(update.get("messages") or []),
                                    response,
                                    SystemMessage(content=json.dumps(
                                        limit_result,
                                        ensure_ascii=False,
                                        sort_keys=True,
                                    )),
                                ],
                                "skill_decision_result": limit_result,
                                "pending_action": {},
                                "pending_recovery_action": {},
                                "required_next_action": "",
                                "recovery_scope": "",
                                "recovery_phase": "skill_review",
                                "transition_guard": (
                                    "recovery_skill_review_required"
                                ),
                                "next_step": "consultant",
                                "proposed_route": "consultant",
                            })
                            return update

                        completed_projection: Dict[str, Any] = {}
                        if skill_continuation_id:
                            completed_projection = self._complete_durable_skill_continuation(
                                task_id,
                                caller_node="recovery",
                            )
                            skill_continuation_id = ""
                        try:
                            skill_update = await self._handle_skill_node_decision(
                                task_id=task_id,
                                caller_node="recovery",
                                graph_node="supervisor",
                                decision=typed_skill_decision,
                                node_context=recovery_node_context,
                                response=response,
                                selected_skill_ids=active_skills,
                            )
                        except SkillAccessError as skill_exc:
                            rejected = {
                                "decision_result": "SKILL_DECISION_REJECTED",
                                **skill_exc.to_dict(),
                                "review_route": "consultant_skill_resolution",
                            }
                            update.update({
                                **completed_projection,
                                "messages": [
                                    *list(update.get("messages") or []),
                                    response,
                                    SystemMessage(content=json.dumps(
                                        rejected,
                                        ensure_ascii=False,
                                        sort_keys=True,
                                    )),
                                ],
                                "skill_decision_result": rejected,
                                "pending_action": {},
                                "pending_recovery_action": {},
                                "required_next_action": "",
                                "recovery_scope": "",
                                "recovery_phase": "skill_review",
                                "transition_guard": (
                                    "recovery_skill_review_required"
                                ),
                                "next_step": "consultant",
                                "proposed_route": "consultant",
                            })
                            return update
                        skill_result = dict(
                            skill_update.get("skill_decision_result") or {}
                        )
                        pending_proposal = dict(
                            skill_update.get("pending_skill_binding_proposal") or {}
                        )
                        no_progress = str(skill_result.get("status") or "") in {
                            "SKILL_CONTEXT_NO_PROGRESS",
                            "SKILL_SEARCH_NO_PROGRESS",
                        }
                        proposal_pending = (
                            typed_skill_kind == PROPOSE_SKILL_BINDING
                        )
                        if proposal_pending or no_progress:
                            review_route = str(
                                pending_proposal.get("review_route")
                                or skill_result.get("review_route")
                                or "consultant_skill_resolution"
                            )
                            typed_next_step = (
                                "planner"
                                if review_route == "planner_plan_impact_review"
                                else "consultant"
                            )
                            skill_update["next_step"] = typed_next_step
                            skill_update["proposed_route"] = typed_next_step
                            skill_update["recovery_trigger"] = trigger.to_dict()
                            skill_update["recovery_phase"] = "skill_review"
                            skill_update["pending_recovery_action"] = {}
                            skill_update["required_next_action"] = ""
                            skill_update["recovery_scope"] = ""
                            skill_update["transition_guard"] = (
                                "recovery_skill_review_required"
                            )
                            skill_update["messages"] = [
                                *list(update.get("messages") or []),
                                *list(skill_update.get("messages") or []),
                            ]
                            update.update(skill_update)
                            return update

                        if typed_skill_kind == REQUEST_SKILL_CONTEXT:
                            skill_context_rounds += 1
                        elif typed_skill_kind == SEARCH_SKILLS:
                            skill_search_rounds += 1
                        skill_continuation_id = str(
                            skill_update.get("skill_continuation_id") or ""
                        )
                        recovery_round_plan = load_plan_state(
                            self.data_path, task_id
                        )
                    else:  # pragma: no cover - guarded by the explicit limit.
                        raise SkillAccessError(
                            "SKILL_CONTINUATION_LIMIT_REACHED",
                            "Recovery exceeded its same-node Skill continuation limit",
                        )
                except Exception as exc:
                    store.save_llm_result(
                        context.context_id,
                        "recovery_judge",
                        raw_response=str(getattr(locals().get("response"), "content", "") or ""),
                        parsed_result={},
                        cache_identity=recovery_cache_identity,
                    )
                    logger.warning(
                        "RecoveryJudge unavailable after review; preserving an internal protocol error: %s",
                        exc,
                    )
                    decision = recovery_decision_from_diagnosis({
                        "root_cause": "RecoveryJudge was unavailable after review; preserved evidence requires internal escalation.",
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "failure_type": "recovery_judge_unavailable",
                        "evidence": [*trigger.reasons, self._clip_observation_text(exc, 300)],
                        "confidence": 1.0,
                        "missing_evidence": [],
                        "repair_strategy": "Repair or resume the internal recovery protocol without asking for a scientific decision.",
                        "next_action": RecoveryAction.ESCALATE.value,
                        "requires_user_input": False,
                        "evidence_sufficient": True,
                    })
            elif not cached_judge_valid:
                decision = recovery_decision_from_diagnosis({
                    "root_cause": "The cached RecoveryJudge result is invalid for this unchanged recovery context.",
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    "failure_type": "recovery_judge_schema_error",
                    "evidence": [*trigger.reasons, f"recovery_context_id:{context.context_id}"],
                    "confidence": 1.0,
                    "missing_evidence": [],
                    "repair_strategy": "Repair the internal decision protocol without another LLM call.",
                    "next_action": RecoveryAction.ESCALATE.value,
                    "requires_user_input": False,
                    "evidence_sufficient": True,
                })
        else:
            decision = deterministic_recovery_decision(trigger, evidence)

        decision = constrain_recovery_decision(
            decision,
            diagnosis,
            user_decision_supported=structured_user_decision_required(merged),
        )
        decision = contextualize_recovery_decision(
            decision,
            action_id=str(evidence.get("action_id") or evidence.get("execution_id") or ""),
            step_id=str(evidence.get("step_id") or state.get("current_step_id") or ""),
            attempt_id=str(evidence.get("attempt_id") or evidence.get("execution_id") or ""),
            source_node="supervisor",
        )
        semantic_decision = decision
        decision, policy_outcome = RecoveryPolicy().apply_with_outcome(
            semantic_decision,
            dict(merged.get("recovery_progress") or {}),
            dict((plan_state.get("task_state") or {}).get("budgets") or {}),
        )
        decision = contextualize_recovery_decision(decision, source_node="supervisor")
        store.save_diagnostic_context(context)
        store.save_recovery_decision(decision)
        store.append_trace(
            "RECOVERY_JUDGE" if post_review_judge_invoked else "RECOVERY_POLICY",
            {
            "trigger": trigger.to_dict(),
            "decision": decision.to_dict(),
            "source": "post_review",
            "judge_invoked": post_review_judge_invoked,
            },
        )
        route = recovery_action_route(
            decision.recommended_action,
            interaction_allowed=not bool(state.get("non_interactive") or state.get("disable_user_questions")),
            failure_owner=decision.failure_owner,
            requires_user_input=decision.requires_user_input,
        )
        execution_envelope: Dict[str, Any] = {}
        if route.get("next_step") == "generate":
            decision_source = (
                RecoveryDecisionSource.FALLBACK.value
                if str(decision.failure_type or "").startswith("recovery_judge_")
                else RecoveryDecisionSource.LIVE_LLM.value
                if post_review_judge_invoked
                else RecoveryDecisionSource.CACHE.value
                if cached_judge_valid
                else RecoveryDecisionSource.DETERMINISTIC.value
            )
            active_step = self._running_plan_step(plan_state) or {}
            formal_outputs = [
                str(item)
                for item in active_step.get("outputs") or []
                if str(item or "")
            ]
            envelope = build_recovery_execution_envelope(
                decision,
                recovery_context_id=context.context_id,
                step_id=str(
                    evidence.get("step_id")
                    or state.get("current_step_id")
                    or active_step.get("step_id")
                    or ""
                ),
                task_root=store.root.parent,
                created_from=decision_source,
                allowed_input_roots=[str(store.root.parent)],
                forbidden_formal_output_paths=formal_outputs,
                policy_version=policy_outcome.policy_version,
            )
            execution_envelope = envelope.to_dict()
            store.save_recovery_execution_contract(
                semantic_decision=semantic_decision,
                final_decision=decision,
                policy_outcome=policy_outcome,
                execution_envelope=envelope,
            )
            store.update_llm_result_contract(
                context.context_id,
                "recovery_judge",
                semantic_decision=semantic_decision,
                policy_outcome=policy_outcome,
                execution_envelope=envelope,
                decision_source=decision_source,
                budget_snapshot=dict(
                    (plan_state.get("task_state") or {}).get("budgets") or {}
                ),
            )
            store.append_trace(
                "RECOVERY_EXECUTION_ENVELOPE_CREATED",
                execution_envelope,
            )
            if envelope.probe_id:
                store.save_probe_lifecycle(ProbeLifecycleRecord(
                    recovery_decision_id=envelope.recovery_decision_id,
                    diagnosis=str(
                        semantic_decision.root_cause
                        or semantic_decision.reason
                    ),
                    missing_evidence=tuple(
                        semantic_decision.missing_evidence or []
                    ),
                    probe_id=envelope.probe_id,
                    probe_objective=str(
                        semantic_decision.probe_objective
                        or semantic_decision.probe_reason
                        or semantic_decision.repair_strategy
                    ),
                    status=ProbeLifecycleStatus.PROPOSED.value,
                    action_id=envelope.action_id,
                ))
        pending = {
            "type": route["pending_type"],
            "reason": decision.reason or decision.root_cause,
            "step_id": str(evidence.get("step_id") or state.get("current_step_id") or ""),
            "failure_class": decision.failure_class,
            "failure_owner": decision.failure_owner,
            "recommended_action": decision.recommended_action,
            "evidence": list(decision.evidence),
            "failure_type": decision.failure_type,
            "missing_evidence": list(decision.missing_evidence),
            "repair_strategy": decision.repair_strategy,
            "root_cause": decision.root_cause,
            "repair_target": decision.repair_target,
            "repair_instruction": decision.repair_instruction,
            "machine_audit_findings": list(context.machine_audit_findings or []),
            "requires_user_input": decision.requires_user_input,
            "diagnostic_context_path": str(store.root / "recovery_context.json"),
            "execution_envelope": execution_envelope,
        }
        recovery_context_ref = str(store.root / "recovery_context.json")
        compact_recovery_binding = {
            "context_ref": recovery_context_ref,
            "context_id": context.context_id,
            "error_fingerprint": context.error_fingerprint,
            "failure_owner": decision.failure_owner,
            "evidence_handles": list(decision.evidence),
        }
        update.update({
            "diagnostic_context": compact_recovery_binding,
            "recovery_context": compact_recovery_binding,
            "recovery_context_digest": context.context_id,
            "recovery_decision": decision.to_dict(),
            "recovery_semantic_decision": semantic_decision.to_dict(),
            "recovery_policy_outcome": policy_outcome.to_dict(),
            "recovery_execution_envelope": execution_envelope,
            "diagnostic_summary": diagnosis,
            "structured_diagnosis": diagnosis,
            "failure_owner": decision.failure_owner,
            "recovery_history": history[-3:],
            "pending_recovery_action": pending,
            "required_next_action": route["required_next_action"],
            "recovery_scope": route["recovery_scope"],
            "evidence_status": "sufficient" if decision.evidence_sufficient else "insufficient",
            "retry_reason": decision.reason or decision.root_cause,
            "recovery_phase": "diagnose",
            "recovery_status": decision.recommended_action,
            "recovery_application": {},
        })
        if decision.next_route == "ask_user":
            question = "BioMind needs your decision before recovery can continue: " + (decision.reason or decision.root_cause)
            pending["question"] = question
            update["pending_human_question"] = {
                "type": "recovery_user_decision",
                "stage": "recovery",
                "question": question,
                "resume_step": "generate",
            }
        return update

    def _commit_legacy_recovery_projection(
        self,
        state: AgentState,
        update: Dict[str, Any],
        task_id: str,
        *,
        source_node: str,
    ) -> Dict[str, Any]:
        """Translate compatibility verdict fields into one committed policy decision."""
        if not isinstance(update, dict):
            return update
        existing = update.get("recovery_decision")
        if isinstance(existing, dict) and existing:
            try:
                decision = RecoveryDecision.from_mapping(existing)
            except ValueError:
                decision = None
            if decision is not None and str(decision.source_node or "") == source_node:
                return update

        merged = {**dict(state or {}), **update}
        verdict = str(update.get("supervisor_verdict") or "").strip().upper()
        required = str(update.get("required_next_action") or "").strip().upper()
        pending = update.get("pending_recovery_action")
        pending = dict(pending) if isinstance(pending, dict) else {}
        pending_type = str(pending.get("type") or "").strip().lower()
        if verdict not in {"RETRY", "ESCALATE"} and required not in {
            "ACTION_FORMAT_REPAIR", "FORMAT_REPAIR", "PROBE", "DIAGNOSTIC_PROBE",
            "PLAN_PATCH", "PATCH_PLAN", "BLOCKED",
        } and pending_type not in {"blocked", "action_format_repair", "diagnostic_probe", "plan_patch"}:
            return update

        plan_state = load_plan_state(self.data_path, task_id)
        _, step = current_plan_step_with_index(plan_state)
        step_id = str((step or {}).get("step_id") or state.get("current_step_id") or "task")
        evidence = dict(merged.get("execution_evidence") or {})
        action_id = str(evidence.get("action_id") or evidence.get("execution_id") or f"{source_node}:{step_id}")
        attempt_id = str(evidence.get("attempt_id") or evidence.get("execution_id") or "")
        if not attempt_id:
            attempt_id = hashlib.sha256(json.dumps({
                "verdict": verdict,
                "required": required,
                "pending_type": pending_type,
                "step_id": step_id,
                "feedback": update.get("completion_gate_result") or update.get("retry_reason") or "",
            }, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")).hexdigest()[:20]
        budgets = dict((plan_state.get("task_state") or {}).get("budgets") or {})
        policy = RecoveryPolicy()

        if required in {"ACTION_FORMAT_REPAIR", "FORMAT_REPAIR"} or pending_type == "action_format_repair":
            decision = policy.decide(
                pre_action_evidence={
                    "valid": False,
                    "repairable": True,
                    "repair_domain": PreActionRepairDomain.REPRESENTATION.value,
                    "violations": [str(pending.get("reason") or update.get("retry_reason") or required)],
                },
                action_id=action_id,
                step_id=step_id,
                attempt_id=attempt_id,
                budgets=budgets,
            )
        elif required in {"PLAN_PATCH", "PATCH_PLAN"} or pending_type == "plan_patch":
            decision = policy.decide(
                validation_evidence={
                    "status": "failed",
                    "failure_owner": RecoveryFailureOwner.PLAN.value,
                    "contract_violations": [str(pending.get("reason") or update.get("retry_reason") or "plan structural error")],
                },
                action_id=action_id,
                step_id=step_id,
                attempt_id=attempt_id,
                budgets=budgets,
            )
        elif required in {"PROBE", "DIAGNOSTIC_PROBE"} or pending_type == "diagnostic_probe":
            decision = policy.decide(
                validation_evidence={"status": "unknown", "recoverability_hints": ["probe"]},
                progress_snapshot=dict(merged.get("recovery_progress") or {}),
                action_id=action_id,
                step_id=step_id,
                attempt_id=attempt_id,
                budgets=budgets,
            )
        elif required == "BLOCKED" or pending_type == "blocked":
            reason = str(pending.get("reason") or update.get("retry_reason") or "structured blocked state")
            decision = policy.decide(
                pre_action_evidence={
                    "valid": False,
                    "repairable": False,
                    "missing_bindings": ["required_recovery_dependency"],
                    "blocked_evidence": [reason],
                },
                action_id=action_id,
                step_id=step_id,
                attempt_id=attempt_id,
                budgets=budgets,
            )
        else:
            gate = dict(update.get("completion_gate_result") or {})
            validation_errors = []
            if gate.get("passed") is False:
                validation_errors = [
                    str(gate.get("message") or gate.get("feedback") or "completion contract failed")
                ]
            if not evidence:
                evidence = {"returncode": 0, "command_role": "primary"}
            decision = policy.decide(
                execution_evidence=evidence,
                validation_evidence={
                    "status": "failed" if verdict == "RETRY" else "escalate",
                    "errors": validation_errors,
                    "warnings": [str(update.get("retry_reason") or "")] if verdict == "ESCALATE" else [],
                },
                action_id=action_id,
                step_id=step_id,
                attempt_id=attempt_id,
                budgets=budgets,
            )
        decision = contextualize_recovery_decision(decision, source_node=source_node)
        update["recovery_decision"] = decision.to_dict()
        update["recovery_application"] = {}
        update["next_step"] = decision.next_route
        update["recovery_status"] = decision.kind
        update["retry_count"] = int(
            (((plan_state.get("task_state") or {}).get("budgets") or {}).get("execution_retry_count"))
            or 0
        )
        return update

    def _fresh_supervisor_feedback(self, state: AgentState, task_id: str) -> Dict[str, Any]:
        """Return feedback only when it belongs to the current execution and plan step."""
        feedback = state.get("last_supervisor_feedback") or {}
        if not isinstance(feedback, dict) or not feedback:
            return {}
        plan_state = load_plan_state(self.data_path, task_id)
        current_step = self._running_plan_step(plan_state) or {}
        evidence = state.get("execution_evidence") or {}
        expected = {
            "step_id": str(current_step.get("step_id") or ""),
            "plan_version": str(plan_state.get("plan_version") or "plan_v1"),
            "task_revision": str(self._task_revision_for_state(dict(state))),
            "execution_id": str(evidence.get("execution_id") or evidence.get("action_id") or ""),
        }
        for key, value in expected.items():
            recorded = str(feedback.get(key) or "")
            if recorded and value and recorded != value:
                return {}
        return dict(feedback)

    def _renderer_action_protocol(
        self,
        state: AgentState,
        task_id: str,
    ) -> Dict[str, Any]:
        """Return the controller-owned Renderer contract for the current step."""
        plan_state = load_plan_state(self.data_path, task_id)
        task_state = dict(plan_state.get("task_state") or {})
        if not (
            task_state.get("legacy_renderer_mode") is True
            or str(task_state.get("execution_contract") or "") == "legacy_renderer_v1"
        ):
            return {
                "renderer_composite": False,
                "renderer": {},
                "renderer_id": "",
                "argument_schema": {},
                "argument_projection": {},
                "manifest_path": "",
                "manifest_status": "retired_v2",
                "resolved_inputs": [],
                "missing_roles": [],
                "ambiguous_roles": [],
                "allowed_actions": ["EXECUTE", "STEP_COMPLETION_CANDIDATE", "PLAN_PATCH", "BLOCKED"],
            }
        step = self._running_plan_step(plan_state) or {}
        renderer_execution = dict(step.get("renderer_execution") or {})
        manifest_path = str(renderer_execution.get("manifest_path") or "").strip()
        manifest_status = "absent"
        if manifest_path:
            try:
                manifest_status = "registered" if Path(manifest_path).is_file() and Path(manifest_path).stat().st_size > 0 else "registered_missing"
            except OSError:
                manifest_status = "registered_missing"

        skill_ids = self._selected_skill_ids(step.get("skill_ids") or state.get("active_skills") or [])
        skill_manager = getattr(self, "skill_manager", None)
        records = [
            skill_manager.get_renderer_record(skill_id)
            for skill_id in skill_ids
        ] if skill_manager else []
        declared = [record for record in records if record.get("status") == "declared"]
        requested_id = str(step.get("renderer_id") or "").strip().lower()
        if requested_id:
            declared = [
                record for record in declared
                if requested_id in {
                    str(alias).strip().lower()
                    for alias in record.get("renderer_aliases") or []
                    if str(alias).strip()
                }
            ]
        renderer = declared[0] if len(declared) == 1 else {}
        renderer_composite = bool(
            step.get("renderer_composite")
            or str(step.get("step_type") or "").strip().lower() == "renderer_composite"
            or (
                renderer
                and (
                    str(step.get("tool") or "").strip().lower() == "renderer"
                    or "renderer-backed" in str(step.get("title") or "").strip().lower()
                )
            )
        )
        input_audit = state.get("input_audit") or (plan_state.get("task_state") or {}).get("input_audit") or {}
        input_audit = input_audit if isinstance(input_audit, dict) else {}
        resolved_inputs = [
            item for item in input_audit.get("resolved_inputs", []) or []
            if isinstance(item, dict)
        ][:24]
        missing_roles = [str(item) for item in input_audit.get("missing_roles", []) or [] if str(item).strip()]
        ambiguous = input_audit.get("ambiguous_roles", []) or []
        ambiguous_roles = [
            str(item.get("role") or item) if isinstance(item, dict) else str(item)
            for item in ambiguous
            if str(item).strip()
        ]
        argument_schema = dict((renderer.get("invocation") or {}).get("arguments") or {})
        task_spec = merge_task_spec_input_audit(
            self._task_spec_for_state(dict(state), list(state.get("messages", []) or [])),
            input_audit,
        )
        approved_invocation = dict(step.get("renderer_invocation_contract") or {})
        if renderer and approved_invocation.get("arguments") is not None and approved_invocation.get("outdir"):
            argument_projection = {
                "arguments": deepcopy(dict(approved_invocation.get("arguments") or {})),
                "outdir": str(approved_invocation.get("outdir") or ""),
                "outputs": list(approved_invocation.get("outputs") or []),
                "bound_outputs": deepcopy(list(approved_invocation.get("bound_outputs") or [])),
                "missing_bindings": [],
                "conflicts": [],
                "unverified_bindings": [],
                "complete": True,
                "source": "approved_renderer_invocation_contract",
                "invocation_id": str(approved_invocation.get("invocation_id") or ""),
            }
        elif renderer:
            argument_projection = project_task_spec_to_renderer(
                task_spec,
                renderer.get("invocation") or {},
                task_id=task_id,
            )
        else:
            argument_projection = {
            "arguments": {},
            "outdir": "",
            "missing_bindings": [],
            "conflicts": [],
            "unverified_bindings": [],
            "complete": False,
            }
        if renderer_composite and manifest_status != "registered":
            allowed_actions = ["RENDERER_INVOCATION", "BLOCKED_WITH_DETERMINISTIC_MISSING_EVIDENCE"]
        elif renderer_composite:
            allowed_actions = ["MANIFEST_RUNNER"]
        else:
            allowed_actions = ["EXECUTE", "STEP_COMPLETION_CANDIDATE", "PLAN_PATCH", "BLOCKED"]
        return {
            "renderer_composite": renderer_composite,
            "renderer": renderer,
            "renderer_id": str(renderer.get("renderer_id") or step.get("renderer_id") or ""),
            "argument_schema": argument_schema,
            "argument_projection": argument_projection,
            "manifest_path": manifest_path,
            "manifest_status": manifest_status,
            "resolved_inputs": resolved_inputs,
            "missing_roles": missing_roles,
            "ambiguous_roles": ambiguous_roles,
            "allowed_actions": allowed_actions,
        }

    @staticmethod
    def _is_readonly_capability_probe(code: str) -> bool:
        """Classify source/help inspection without inferring a business action."""
        text = str(code or "").strip()
        if not text:
            return False
        if re.search(r"(?:^|\s)(?:--help|-h)(?:\s|$)", text, re.IGNORECASE):
            return True
        if re.search(r"(?:^|[;&|]\s*)(?:head|grep|rg|sed|cat|tail|awk|less|more)\b", text, re.IGNORECASE):
            writes_file = bool(
                re.search(r"(?:^|\s)(?:>>?|tee\s+|cp\s+|mv\s+)", text)
                and not re.search(r"\d?>&\d", text)
            )
            return not writes_file
        return False

    def _match_legacy_renderer_invocation(self, code: str, renderer: Dict[str, Any]) -> Dict[str, str]:
        """Accept only one complete, exact legacy Renderer launch command."""
        if self._is_readonly_capability_probe(code):
            return {}
        text = str(code or "").strip()
        if not text or any(token in text for token in ("\n", "|", ";", "&&", "||", ">", "<")):
            return {}
        try:
            argv = shlex.split(text)
        except ValueError:
            return {}
        if len(argv) < 3:
            return {}
        entrypoint = str(renderer.get("resolved_entrypoint") or "")
        if not entrypoint:
            return {}
        runner = Path(argv[0]).name.lower()
        if runner not in {"python", "python3", Path(sys.executable).name.lower()}:
            return {}
        try:
            invoked_entrypoint = str(Path(argv[1]).expanduser().resolve())
        except OSError:
            return {}
        if invoked_entrypoint != str(Path(entrypoint).expanduser().resolve()):
            return {}

        invocation = dict(renderer.get("invocation") or {})
        argument_specs = invocation.get("arguments") or {}
        flags = argv[2:]

        def has_value(flag: str) -> bool:
            for index, item in enumerate(flags):
                if item.startswith(flag + "=") and item.split("=", 1)[1]:
                    return True
                if item == flag and index + 1 < len(flags) and not flags[index + 1].startswith("-"):
                    return True
            return False

        for name, raw_spec in argument_specs.items():
            spec = dict(raw_spec or {}) if isinstance(raw_spec, dict) else {}
            if not spec.get("required"):
                continue
            accepted = [str(spec.get("flag") or "--" + str(name).replace("_", "-"))]
            accepted.extend(
                str(alias) if str(alias).startswith("-") else "--" + str(alias).replace("_", "-")
                for alias in spec.get("aliases") or []
            )
            if not any(has_value(flag) for flag in accepted):
                return {}
        outdir = ""
        for index, item in enumerate(flags):
            if item == "--outdir" and index + 1 < len(flags):
                outdir = flags[index + 1]
                break
            if item.startswith("--outdir="):
                outdir = item.split("=", 1)[1]
                break
        if not outdir:
            return {}
        return {"outdir": outdir}

    @staticmethod
    def _renderer_blocked_has_deterministic_evidence(
        action: Dict[str, Any],
        protocol: Dict[str, Any],
    ) -> bool:
        known = {
            str(item).strip().lower()
            for item in [
                *(protocol.get("missing_roles") or []),
                *(protocol.get("ambiguous_roles") or []),
            ]
            if str(item).strip()
        }
        provided = {
            str(item).strip().lower()
            for item in action.get("missing_evidence", []) or []
            if str(item).strip()
        }
        reason = str(action.get("reason") or "").lower()
        return bool(known and (known & provided or any(item in reason for item in known)))

    @staticmethod
    def _corrective_action_repair_instruction() -> str:
        return (
            "Repair the previous generated action instead of regenerating the step from scratch. "
            "Fix only the reported violation. Preserve all unrelated already-valid content. "
            "Do not introduce unrelated inputs, outputs, managed artifact handles, checks, "
            "working directories, or workflow logic. Do not re-plan the step."
        )

    @classmethod
    def _action_repair_projection(
        cls,
        state: Mapping[str, Any],
        recovery_action: Mapping[str, Any],
        recovery_decision: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Project only the current machine failure into Generate V2 repair context."""
        repair_type = str(recovery_action.get("type") or "").strip().lower()
        decision_kind = str(recovery_decision.get("kind") or "").strip().upper()
        recommended = str(recovery_decision.get("recommended_action") or "").strip().upper()
        if repair_type in {
            "controller_audit_repair", "script_repair", "repair_previous_action",
        } or recommended == RecoveryAction.PATCH_SCRIPT.value:
            execution = (
                dict(state.get("execution_evidence") or {})
                if isinstance(state.get("execution_evidence"), Mapping)
                else {}
            )
            previous_script = str(
                recovery_action.get("previous_script")
                or execution.get("generated_code")
                or execution.get("code_summary")
                or ""
            )
            machine_findings = list(
                recovery_action.get("machine_audit_findings")
                or state.get("controller_machine_audit_findings")
                or (execution.get("runtime_drift") or {}).get("machine_audit_findings")
                or []
            )
            return {
                "repair_mode": "corrective_script",
                "repair_stage": (
                    "controller_script_audit"
                    if repair_type == "controller_audit_repair"
                    else "post_execution_recovery"
                ),
                "previous_script": previous_script or "<previous script unavailable>",
                "previous_script_ref": deepcopy(
                    recovery_action.get("previous_script_ref")
                    or execution.get("generated_script")
                    or {}
                ),
                "controller_machine_audit_findings": deepcopy(machine_findings),
                "recovery_root_cause": str(
                    recovery_decision.get("root_cause")
                    or recovery_action.get("root_cause")
                    or recovery_action.get("reason")
                    or ""
                ),
                "repair_target": str(
                    recovery_decision.get("repair_target")
                    or recovery_action.get("repair_target")
                    or "previous_generated_script"
                ),
                "repair_instruction": str(
                    recovery_decision.get("repair_instruction")
                    or recovery_action.get("repair_instruction")
                    or recovery_decision.get("repair_strategy")
                    or cls._corrective_action_repair_instruction()
                ),
                "preservation_rule": cls._corrective_action_repair_instruction(),
            }
        if (
            repair_type not in {"action_format_repair", "format_repair"}
            and decision_kind != RecoveryDecisionKind.FORMAT_REPAIR.value
            and recommended != RecoveryAction.FORMAT_REPAIR.value
        ):
            return {}

        format_state = (
            dict(state.get("action_format_repair") or {})
            if isinstance(state.get("action_format_repair"), Mapping)
            else {}
        )
        protocol_error = recovery_action.get("protocol_error") or format_state.get("protocol_error") or {}
        if not isinstance(protocol_error, Mapping):
            protocol_error = {}
        previous_candidate: Any = recovery_action.get("previous_candidate")
        if previous_candidate in (None, "", [], {}):
            previous_candidate = format_state.get("previous_candidate")

        exact_violations: List[Dict[str, Any]] = []
        repair_stage = str(protocol_error.get("stage") or "")
        recovery_context = state.get("recovery_context")
        if isinstance(recovery_context, Mapping):
            validation = recovery_context.get("validation")
            raw_violations = (
                validation.get("violations")
                if isinstance(validation, Mapping)
                else []
            ) or []
            exact_violations = [
                deepcopy(dict(item))
                for item in raw_violations
                if isinstance(item, Mapping)
            ]
            if exact_violations:
                repair_stage = "managed_artifact"
                action_contract = recovery_context.get("action_contract")
                structured_candidate = (
                    action_contract.get("structured_candidate")
                    if isinstance(action_contract, Mapping)
                    else None
                )
                if structured_candidate not in (None, "", [], {}):
                    previous_candidate = deepcopy(structured_candidate)

        if (
            isinstance(previous_candidate, Mapping)
            and str(previous_candidate.get("script_adapter") or "")
            == "script_block_v1"
        ):
            script_candidate = dict(previous_candidate)
            script_language = str(script_candidate.get("language") or "bash")
            artifact_environment = list(
                script_candidate.get("controller_artifact_environment") or []
            )
            previous_candidate = project_script_repair_candidate(script_candidate)
            exact_violations = project_script_artifact_repair_violations(
                exact_violations,
                artifact_environment,
                language=script_language,
            )

        if not repair_stage:
            repair_stage = "action_schema"
        if isinstance(previous_candidate, str):
            position = protocol_error.get("position")
            previous_candidate = cls._bounded_protocol_excerpt(
                previous_candidate,
                position=int(position) if isinstance(position, int) else None,
            )
        elif isinstance(previous_candidate, Mapping):
            previous_candidate = deepcopy(dict(previous_candidate))

        projection: Dict[str, Any] = {
            "repair_mode": "corrective",
            "repair_stage": repair_stage,
            "previous_candidate": previous_candidate or "<previous candidate unavailable>",
            "repair_instruction": cls._corrective_action_repair_instruction(),
        }
        if protocol_error:
            projection["exact_error"] = deepcopy(dict(protocol_error))
        if exact_violations:
            projection["exact_violations"] = exact_violations
        return projection

    def _action_format_repair_feedback(
        self,
        state: AgentState,
        task_id: str,
        *,
        invalid_hash: str,
        invalid_excerpt: str,
        contract_error: Dict[str, Any] | None = None,
    ) -> str:
        protocol = self._renderer_action_protocol(state, task_id)
        plan_state = load_plan_state(self.data_path, task_id)
        _, step = current_plan_step_with_index(plan_state)
        lines = [
            "<action_format_repair>",
            "Your previous response did not satisfy the current action contract.",
            f"Current step: {str((step or {}).get('step_id') or 'unknown')}",
            f"Invalid response hash: {invalid_hash}",
            f"Invalid response excerpt: {str(invalid_excerpt or '').strip()[:500]}",
        ]
        if contract_error:
            lines.append("Contract error: " + json.dumps(contract_error, ensure_ascii=False, sort_keys=True))
        if protocol.get("renderer_composite"):
            lines.extend([
                f"canonical_renderer_id: {protocol.get('renderer_id') or '<missing>'}",
                "renderer_argument_schema: " + json.dumps(protocol.get("argument_schema") or {}, ensure_ascii=False, sort_keys=True),
                "formal_verified_inputs: " + json.dumps(protocol.get("resolved_inputs") or [], ensure_ascii=False, sort_keys=True),
                "projected_renderer_arguments: " + json.dumps(protocol.get("argument_projection") or {}, ensure_ascii=False, sort_keys=True),
                f"manifest_status: {protocol.get('manifest_status')}",
            ])
        lines.append("Allowed actions:")
        lines.extend(f"- {item}" for item in protocol.get("allowed_actions") or [])
        if str((contract_error or {}).get("stage") or "") == "script_block":
            lines.extend([
                self._corrective_action_repair_instruction(),
                "Return exactly one non-empty <shell>, <python>, or <r> block.",
                "Do not provide prose, Markdown fences, JSON, or multiple blocks.",
                "</action_format_repair>",
            ])
        else:
            lines.extend([
                self._corrective_action_repair_instruction(),
                "Return exactly one <action_json> block with one structured action.",
                "Do not provide a narrative summary or ask whether to continue.",
                "</action_format_repair>",
            ])
        return "\n".join(lines)

    def _persist_script_version(
        self,
        task_id: str,
        plan_state: Dict[str, Any],
        step_id: str,
        action_id: str,
        version: str,
        content: str,
        *,
        extension: str,
        parent_script_ref: Optional[Dict[str, Any]] = None,
        mutation_reason: str = "",
        producer: str = "controller",
        root: Optional[Path] = None,
    ) -> Dict[str, Any]:
        """Atomically persist one immutable script version and return its lineage ref."""
        script_root = root or (
            Path(self.data_path)
            / "task_outputs"
            / str(task_id or "default")
            / "scripts"
            / str(plan_state.get("plan_id") or "plan")
            / str(plan_state.get("plan_version") or "plan_v1")
            / str(step_id or "step")
            / str(action_id or "action")
        )
        script_root.mkdir(parents=True, exist_ok=True)
        path = script_root / f"{version}{extension}"
        payload = str(content or "").encode("utf-8")
        digest = hashlib.sha256(payload).hexdigest()
        if path.exists():
            existing_digest = hashlib.sha256(path.read_bytes()).hexdigest()
            if existing_digest != digest:
                raise ValueError(f"Immutable script version already exists with different content: {path}")
        else:
            fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=str(path.parent))
            try:
                with os.fdopen(fd, "wb") as handle:
                    handle.write(payload)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.chmod(tmp_name, 0o700)
                os.replace(tmp_name, path)
            finally:
                if os.path.exists(tmp_name):
                    os.unlink(tmp_name)
        return {
            "version": version,
            "path": str(path.resolve()),
            "sha256": digest,
            "producer": str(producer or "controller"),
            "parent_script_ref": dict(parent_script_ref or {}),
            "mutation_reason": str(mutation_reason or ""),
            "created_at": datetime.now().isoformat(timespec="seconds"),
        }

    def _bind_pending_action(
        self,
        action: Dict[str, Any],
        state: AgentState,
        task_id: str,
        *,
        plan_state: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Bind one generated action to the exact task revision and plan step."""
        if not isinstance(action, dict) or not action:
            return {}
        raw_action = dict(action)
        bound = dict(action)
        # Controller callers that already own a freshly loaded PlanState pass it
        # through so binding and their runtime mutation share one CAS commit.
        # Loading and saving a second copy here would advance the generation and
        # make the caller's otherwise valid snapshot stale.
        plan_state = plan_state if plan_state is not None else load_plan_state(self.data_path, task_id)
        step = self._running_plan_step(plan_state) or {}
        task_revision = task_spec_revision(
            canonical_task_spec_for_state(plan_state)
        )
        plan_version = str(plan_state.get("plan_version") or "plan_v1")
        plan_revision = max(0, int(plan_state.get("plan_revision") or 0))
        authoritative_user_turn_revision = (
            self._authoritative_user_turn_revision(plan_state)
        )
        plan_id = str(plan_state.get("plan_id") or "")
        step_id = str(step.get("step_id") or "")
        recovery_envelope: Optional[RecoveryExecutionEnvelope] = None
        if bound.get("recovery_execution_envelope") is not None:
            recovery_envelope = RecoveryExecutionEnvelope.from_mapping(
                bound.get("recovery_execution_envelope")
            )
        elif bool(bound.get("recovery_generated")):
            raise RecoveryExecutionContractError(
                "RECOVERY_EXECUTION_ENVELOPE_MISSING",
                "Recovery-generated action reached binding without Controller authority",
            )
        if recovery_envelope and recovery_envelope.step_id != step_id:
            raise RecoveryExecutionContractError(
                "RECOVERY_EXECUTION_ENVELOPE_STEP_MISMATCH",
                "Recovery action is not bound to the current plan step",
            )
        execution_epoch = str(
            step.get("execution_epoch")
            or (plan_state.get("runtime_state") or {}).get("execution_epoch")
            or "0"
        )
        action_type = str(bound.get("type") or "").lower()
        execution_capability_id = str(
            bound.get("execution_capability_id")
            or step.get("execution_capability_id")
            or ""
        ).strip()
        if (
            action_type == "execute"
            and str(bound.get("execution_capability_id") or "").strip()
            not in {"", str(step.get("execution_capability_id") or "").strip()}
        ):
            raise ActionRuntimeContractError(
                "UNKNOWN_EXECUTION_CAPABILITY",
                json_pointer="$.execution_capability_id",
                received_id=str(bound.get("execution_capability_id") or ""),
                approved_id=str(step.get("execution_capability_id") or ""),
                selected_skill_id=str(bound.get("selected_skill_id") or ""),
            )
        step_skill_ids = self._selected_skill_ids(
            step.get("skill_ids") or state.get("active_skills") or []
        )
        skill_manager = getattr(self, "skill_manager", None)
        capability_registry = (
            skill_manager.get_execution_capability_registry(step_skill_ids)
            if skill_manager and action_type == "execute"
            else {}
        )
        capability_contract = dict(
            capability_registry.get(execution_capability_id) or {}
        )
        selected_skill_id = str(
            capability_contract.get("selected_skill_id")
            or bound.get("selected_skill_id")
            or ""
        )
        purpose = (
            recovery_envelope.execution_purpose.lower()
            if recovery_envelope is not None
            else self._pending_action_purpose(bound, step)
        )
        protocol = self._renderer_action_protocol(state, task_id)
        if (
            str(bound.get("type") or "").lower() == "execute"
            and skill_manager
            and protocol.get("renderer_composite")
            and purpose not in {"probe", "diagnostic", "validation"}
        ):
            renderer_records = [
                skill_manager.get_renderer_record(skill_id)
                for skill_id in self._selected_skill_ids(step.get("skill_ids") or state.get("active_skills") or [])
            ]
            renderer_records = [record for record in renderer_records if record.get("status") == "declared"]
            code = str(bound.get("code") or "")
            matches = [
                (record, self._match_legacy_renderer_invocation(code, record))
                for record in renderer_records
            ]
            matched = [(record, details) for record, details in matches if details]
            if len(matched) == 1:
                renderer, details = matched[0]
                outdir = details["outdir"]
                bound.update({
                    "command_role": "renderer_invocation",
                    "action_source": "renderer_compat_adapter",
                    "renderer_id": str(renderer.get("renderer_id") or ""),
                    "manifest_path": str(
                        (Path(outdir).expanduser() / str(renderer.get("manifest_filename") or "manifest.json")).resolve()
                    ) if outdir else "",
                })
        generated_script_sha256 = (
            hashlib.sha256(str(bound.get("code") or "").encode("utf-8")).hexdigest()
            if action_type == "execute"
            else ""
        )
        preliminary_resolution: Dict[str, Any] = {}
        if action_type == "execute":
            preliminary_resolution = resolve_action_runtime_bindings(
                selected_skill_id=selected_skill_id,
                execution_capability_id=execution_capability_id,
                approved_capability_contract_hash=str(
                    step.get("capability_contract_hash") or ""
                ),
                capability_registry=capability_registry,
                ready_runtime_binding_registry=build_runtime_binding_registry(state),
                current_action_identity={
                    "plan_id": plan_id,
                    "step_id": step_id,
                },
            )
        fingerprint_input = json.dumps(
            {
                "type": bound.get("type"),
                "code": bound.get("code"),
                "tool": bound.get("tool"),
                "question": bound.get("question"),
                "step_id": step_id,
                "task_revision": task_revision,
                "plan_version": plan_version,
                "plan_revision": plan_revision,
                "authoritative_user_turn_revision": (
                    authoritative_user_turn_revision
                ),
                "plan_id": plan_id,
                "execution_epoch": execution_epoch,
                "execution_capability_id": execution_capability_id,
                "capability_contract_hash": str(
                    preliminary_resolution.get("capability_contract_hash") or ""
                ),
                "runtime_binding_value_digests": [
                    str(item.get("value_digest") or "")
                    for item in preliminary_resolution.get(
                        "runtime_binding_records", []
                    ) or []
                ],
                "generated_script_sha256": generated_script_sha256,
            },
            ensure_ascii=False,
            sort_keys=True,
            default=str,
        )
        explicit_role = str(bound.get("command_role") or "").strip().lower()
        if explicit_role not in {
            "primary", "diagnostic", "required_validation", "optional_probe", "fallback", "recovery",
            "renderer_invocation",
        }:
            explicit_role = ""
        command_role = (
            "diagnostic"
            if recovery_envelope is not None
            and recovery_envelope.execution_purpose == "DIAGNOSTIC"
            else "required_validation"
            if recovery_envelope is not None
            and recovery_envelope.execution_purpose == "VALIDATION"
            else "primary"
            if recovery_envelope is not None
            else explicit_role or {
                "probe": "diagnostic",
                "validation": "required_validation",
                "fallback": "fallback",
            }.get(purpose, "primary")
        )
        action_id = (
            recovery_envelope.action_id
            if recovery_envelope is not None
            else "action_" + hashlib.sha256(
                fingerprint_input.encode("utf-8")
            ).hexdigest()[:16]
        )
        expected_outputs = (
            list(bound.get("expected_outputs") or step.get("outputs") or [])
            if recovery_envelope is None
            or recovery_envelope.result_contract
            == RecoveryResultContract.FORMAL_OUTPUTS.value
            else []
        )
        bound.update(
            {
                "action_id": action_id,
                "step_id": step_id,
                "task_revision": task_revision,
                "plan_id": plan_id,
                "plan_version": plan_version,
                "plan_revision": plan_revision,
                "authoritative_user_turn_revision": (
                    authoritative_user_turn_revision
                ),
                "execution_epoch": execution_epoch,
                "purpose": purpose,
                "command_role": command_role,
                "expected_outputs": expected_outputs,
                "expected_evidence": list(bound.get("success_checks") or step.get("success_criteria") or []),
            }
        )
        if recovery_envelope is not None:
            bound.update({
                "recovery_generated": True,
                "recovery_execution_envelope": recovery_envelope.to_dict(),
                "recovery_decision_id": recovery_envelope.recovery_decision_id,
                "recovery_context_id": recovery_envelope.recovery_context_id,
                "recovery_strategy": recovery_envelope.recovery_strategy,
                "execution_mode": recovery_envelope.execution_mode,
                "result_contract": recovery_envelope.result_contract,
                "probe_id": recovery_envelope.probe_id,
                "scratch_capability": (
                    recovery_envelope.scratch_capability.to_dict()
                    if recovery_envelope.scratch_capability is not None
                    else None
                ),
                "completion_eligible": recovery_envelope.to_dict()[
                    "completion_eligible"
                ],
            })
        if action_type == "execute":
            runtime_resolution = resolve_action_runtime_bindings(
                selected_skill_id=selected_skill_id,
                execution_capability_id=execution_capability_id,
                approved_capability_contract_hash=str(
                    step.get("capability_contract_hash") or ""
                ),
                capability_registry=capability_registry,
                ready_runtime_binding_registry=build_runtime_binding_registry(state),
                current_action_identity={
                    "action_id": action_id,
                    "plan_id": plan_id,
                    "step_id": step_id,
                },
            )
            declared_language = str(bound.get("language") or "").strip().lower()
            action_language = {
                "bash": "Bash", "shell": "Bash", "sh": "Bash",
                "python": "Python", "py": "Python",
                "r": "R", "rscript": "R",
            }.get(
                declared_language,
                detect_script_language(str(bound.get("code") or "")),
            )
            action_identity = {
                "action_id": action_id,
                "plan_id": plan_id,
                "step_id": step_id,
            }
            artifact_manifest = build_artifact_env_manifest(
                list(bound.get("controller_artifact_environment") or []),
                action_identity=action_identity,
                selected_skill_id=selected_skill_id,
                execution_capability_id=execution_capability_id,
                capability_contract_hash_value=str(
                    runtime_resolution.get("capability_contract_hash") or ""
                ),
            )
            policy_manifest = build_execution_policy_manifest(
                action_identity=action_identity,
                working_directory=os.getcwd(),
                language=action_language,
            )
            approval_identity = build_action_approval_identity(
                generated_script_sha256=generated_script_sha256,
                capability_contract_hash_value=str(
                    runtime_resolution.get("capability_contract_hash") or ""
                ),
                runtime_env_manifest_hash=str(
                    runtime_resolution.get("runtime_binding_manifest_hash") or ""
                ),
                artifact_env_manifest_hash=str(artifact_manifest["manifest_hash"]),
                execution_policy_manifest_hash=str(policy_manifest["manifest_hash"]),
                working_directory=os.getcwd(),
            )
            bound.update({
                "selected_skill_id": selected_skill_id,
                "execution_capability_id": execution_capability_id,
                "capability_contract": deepcopy(
                    runtime_resolution.get("capability_contract") or {}
                ),
                "capability_contract_hash": str(
                    runtime_resolution.get("capability_contract_hash") or ""
                ),
                "runtime_bindings": dict(
                    runtime_resolution.get("effective_runtime_bindings") or {}
                ),
                "runtime_binding_records": deepcopy(
                    runtime_resolution.get("runtime_binding_records") or []
                ),
                "runtime_binding_manifest": deepcopy(
                    runtime_resolution.get("runtime_binding_manifest") or {}
                ),
                "runtime_binding_manifest_hash": str(
                    runtime_resolution.get("runtime_binding_manifest_hash") or ""
                ),
                "artifact_env_manifest": artifact_manifest,
                "artifact_env_manifest_hash": str(artifact_manifest["manifest_hash"]),
                "execution_policy_manifest": policy_manifest,
                "execution_policy_manifest_hash": str(policy_manifest["manifest_hash"]),
                "action_approval_identity": approval_identity,
                "generated_script_sha256": generated_script_sha256,
                "working_directory": str(Path(os.getcwd()).resolve()),
            })
        approval_scope = build_approval_scope(plan_state)
        bound["generated_from_plan_hash"] = approval_scope["plan_hash"]
        bound["generated_from_approval_scope_hash"] = approval_scope["approval_scope_hash"]
        bound["action_hash"] = hashlib.sha256(
            json.dumps(
                {
                    key: value for key, value in bound.items()
                    if key not in {"raw_response", "messages", "action_hash"}
                },
                ensure_ascii=False,
                sort_keys=True,
                default=str,
            ).encode("utf-8")
        ).hexdigest()
        invocation_contract = dict(bound.get("renderer_invocation_contract") or {})
        if invocation_contract and step_id:
            approved_invocation = dict(step.get("renderer_invocation_contract") or {})
            if approved_invocation:
                invocation_contract = approved_invocation
            else:
                invocation_contract.setdefault("invocation_id", str(bound["action_id"]))
            bound["renderer_invocation_contract"] = deepcopy(invocation_contract)
            for plan_step in plan_state.get("steps", []) or []:
                if isinstance(plan_step, dict) and str(plan_step.get("step_id") or "") == step_id:
                    if not plan_step.get("renderer_invocation_contract"):
                        plan_step["renderer_invocation_contract"] = deepcopy(invocation_contract)
                    break
        if str(bound.get("type") or "").lower() == "execute" and str(bound.get("code") or "").strip():
            declared_language = str(bound.get("language") or "").strip().lower()
            language = {
                "bash": "Bash", "shell": "Bash", "sh": "Bash",
                "python": "Python", "py": "Python",
                "r": "R", "rscript": "R",
            }.get(declared_language, detect_script_language(str(bound.get("code") or "")))
            generated_ref = self._persist_script_version(
                task_id,
                plan_state,
                step_id,
                str(bound["action_id"]),
                "generated",
                str(bound.get("code") or ""),
                extension={"Python": ".py", "R": ".R"}.get(language, ".sh"),
                mutation_reason="model_generation",
                producer="generate",
            )
            bound["generated_script"] = generated_ref
            bound["generated_script_path"] = generated_ref["path"]
            bound["generated_script_hash"] = generated_ref["sha256"]
            if generated_ref["sha256"] != generated_script_sha256:
                raise ActionRuntimeContractError(
                    "ACTION_APPROVAL_IDENTITY_DRIFT",
                    drift_field="generated_script_sha256",
                    expected=generated_script_sha256,
                    observed=generated_ref["sha256"],
                )
        action_record = record_provenance_event(plan_state, "action_bound", {
            "task_id": task_id,
            "action": bound,
            "raw_action": raw_action,
        })
        if action_record.get("manifest_id"):
            bound["manifest_id"] = str(action_record["manifest_id"])
        if action_record.get("stage_id"):
            bound["stage_id"] = str(action_record["stage_id"])
        task_state = dict(plan_state.get("task_state") or {})
        task_state["pending_action"] = {
            key: value for key, value in bound.items()
            if key not in {"code", "messages", "raw_response"}
        }
        plan_state["task_state"] = task_state
        save_plan_state(self.data_path, task_id, plan_state)
        return bound

    @staticmethod
    def _renderer_cli_arguments(arguments: Any) -> List[str]:
        """Build renderer argv without letting leading-dash values become options."""
        if isinstance(arguments, list):
            return [str(item) for item in arguments]
        if not isinstance(arguments, dict):
            return []
        argv: List[str] = []
        for raw_key, raw_value in arguments.items():
            key = str(raw_key or "").strip()
            if not key:
                continue
            flag = key if key.startswith("-") else "--" + key.replace("_", "-")
            values = raw_value if isinstance(raw_value, list) else [raw_value]
            for value in values:
                if value is False or value is None:
                    continue
                if value is True:
                    argv.append(flag)
                    continue
                text = str(value)
                if text.startswith("-") and flag.startswith("--"):
                    argv.append(f"{flag}={text}")
                else:
                    argv.extend([flag, text])
        return argv

    @staticmethod
    def _renderer_argument_key(value: Any) -> str:
        """Normalize one renderer argument name without guessing its meaning."""
        return str(value or "").strip().lstrip("-").replace("-", "_").lower()

    def _normalize_renderer_invocation_arguments(
        self,
        action: Dict[str, Any],
        renderer: Dict[str, Any],
        state: Dict[str, Any],
    ) -> Tuple[List[str], str, Dict[str, Any]]:
        """Validate and normalize an invocation from renderer-owned metadata.

        The controller understands the protocol shape, while each renderer owns
        its argument names, aliases, routed arguments, and runtime bindings.
        """
        raw_arguments = action.get("arguments") or {}
        outdir = str(action.get("outdir") or "").strip()
        if isinstance(raw_arguments, list):
            return self._renderer_cli_arguments(raw_arguments), outdir, {}
        if not isinstance(raw_arguments, dict):
            return [], outdir, {
                "error_type": "RENDERER_INVOCATION_SCHEMA_ERROR",
                "reason": "renderer arguments must be an object or argv list",
            }

        invocation = dict(renderer.get("invocation") or {})
        argument_specs = invocation.get("arguments") or {}
        if not isinstance(argument_specs, dict) or not argument_specs:
            return self._renderer_cli_arguments(raw_arguments), outdir, {}

        specs: Dict[str, Dict[str, Any]] = {}
        aliases: Dict[str, str] = {}
        for raw_name, raw_spec in argument_specs.items():
            canonical = self._renderer_argument_key(raw_name)
            spec = dict(raw_spec or {}) if isinstance(raw_spec, dict) else {"flag": str(raw_spec or "")}
            specs[canonical] = spec
            names = [raw_name, spec.get("flag"), *(spec.get("aliases") or [])]
            for name in names:
                normalized = self._renderer_argument_key(name)
                if normalized:
                    aliases[normalized] = canonical

        values: Dict[str, Any] = {}
        duplicate_fields: List[str] = []
        for raw_name, value in raw_arguments.items():
            normalized = self._renderer_argument_key(raw_name)
            if normalized in values:
                duplicate_fields.append(str(raw_name))
            values[normalized] = value

        route_errors: List[Dict[str, Any]] = []
        routed_arguments = invocation.get("routed_arguments") or {}
        if isinstance(routed_arguments, dict):
            for raw_source, raw_route in routed_arguments.items():
                source = self._renderer_argument_key(raw_source)
                if source not in values:
                    continue
                route = dict(raw_route or {})
                selector = self._renderer_argument_key(route.get("selector"))
                selector_value = str(values.get(selector) or "").strip()
                routes = {str(key): value for key, value in (route.get("routes") or {}).items()}
                target = self._renderer_argument_key(routes.get(selector_value))
                if not target:
                    route_errors.append({
                        "field": raw_source,
                        "selector": route.get("selector"),
                        "value": selector_value,
                        "allowed_values": sorted(routes),
                    })
                    continue
                if target in values and values[target] != values[source]:
                    duplicate_fields.append(str(raw_source))
                else:
                    values[target] = values[source]
                values.pop(source, None)
                values.pop(selector, None)

        ignored_fields: List[str] = []
        for raw_name in [
            *(invocation.get("runtime_only_arguments") or []),
            *(invocation.get("controller_owned_arguments") or []),
        ]:
            key = self._renderer_argument_key(raw_name)
            if key in values:
                ignored_fields.append(key)
                values.pop(key, None)

        runtime_bindings = self._runtime_bindings_from_state(state)
        for canonical, spec in specs.items():
            binding = str(spec.get("runtime_binding") or "").strip()
            if binding and runtime_bindings.get(binding):
                values[canonical] = runtime_bindings[binding]

        normalized_values: Dict[str, Any] = {}
        unknown_fields: List[str] = []
        for raw_name, value in values.items():
            canonical = aliases.get(raw_name)
            if not canonical:
                unknown_fields.append(raw_name)
                continue
            if canonical in normalized_values and normalized_values[canonical] != value:
                duplicate_fields.append(raw_name)
                continue
            normalized_values[canonical] = value

        argv: List[str] = []
        seen: set = set()
        for canonical, value in normalized_values.items():
            spec = specs[canonical]
            seen.add(canonical)
            if bool(spec.get("top_level")):
                candidate = str(value or "").strip()
                if outdir and candidate and Path(outdir).expanduser() != Path(candidate).expanduser():
                    duplicate_fields.append(canonical)
                elif candidate:
                    outdir = candidate
                continue
            flag = str(spec.get("flag") or "--" + canonical.replace("_", "-")).strip()
            argv.extend(self._renderer_cli_arguments({flag: value}))

        missing_fields = [
            canonical
            for canonical, spec in specs.items()
            if bool(spec.get("required"))
            and canonical not in seen
            and not (bool(spec.get("top_level")) and outdir)
        ]
        if unknown_fields or missing_fields or duplicate_fields or route_errors:
            return [], outdir, {
                "error_type": "RENDERER_INVOCATION_SCHEMA_ERROR",
                "renderer_id": str(renderer.get("renderer_id") or ""),
                "unknown_fields": sorted(set(unknown_fields)),
                "missing_fields": sorted(set(missing_fields)),
                "conflicting_fields": sorted(set(duplicate_fields)),
                "route_errors": route_errors,
                "ignored_runtime_or_controller_fields": sorted(set(ignored_fields)),
                "allowed_fields": sorted(specs),
            }
        return argv, outdir, {}

    def _materialize_renderer_invocation(
        self,
        action: Dict[str, Any],
        state: AgentState,
        task_id: str,
    ) -> Dict[str, Any]:
        plan_state = load_plan_state(self.data_path, task_id)
        step = self._running_plan_step(plan_state) or {}
        skill_ids = self._selected_skill_ids(step.get("skill_ids") or state.get("active_skills") or [])
        records = [self.skill_manager.get_renderer_record(skill_id) for skill_id in skill_ids] if self.skill_manager else []
        requested_id = str(action.get("renderer_id") or "").strip()
        candidates = [
            record for record in records
            if record.get("status") == "declared"
            and (
                not requested_id
                or requested_id.lower() in {
                    str(alias).strip().lower()
                    for alias in (record.get("renderer_aliases") or [])
                    if str(alias).strip()
                }
            )
        ]
        if len(candidates) != 1:
            declared = [record for record in records if record.get("status") == "declared"]
            return {
                "type": "renderer_contract_error",
                "source": "controller",
                "contract_error": {
                    "error_type": "RENDERER_INVOCATION_SCHEMA_ERROR",
                    "reason": "unknown_renderer_id" if requested_id else "ambiguous_renderer_id",
                    "requested_renderer_id": requested_id,
                    "allowed_renderer_ids": [str(record.get("renderer_id") or "") for record in declared],
                    "accepted_aliases": {
                        str(record.get("renderer_id") or ""): list(record.get("renderer_aliases") or [])
                        for record in declared
                    },
                },
            }
        renderer = candidates[0]
        approved_invocation = dict(step.get("renderer_invocation_contract") or {})
        if approved_invocation:
            requested_contract = {
                "renderer_id": str(renderer.get("renderer_id") or ""),
                "arguments": dict(action.get("arguments") or {}) if isinstance(action.get("arguments"), dict) else action.get("arguments"),
                "outdir": str(action.get("outdir") or ""),
            }
            approved_contract = {
                "renderer_id": str(approved_invocation.get("renderer_id") or ""),
                "arguments": dict(approved_invocation.get("arguments") or {}),
                "outdir": str(approved_invocation.get("outdir") or ""),
            }
            if requested_contract != approved_contract:
                return {
                    "type": "renderer_contract_error",
                    "source": "controller",
                    "contract_error": {
                        "error_type": "RENDERER_INVOCATION_APPROVAL_MISMATCH",
                        "reason": "renderer arguments or output directory differ from the approved binding",
                        "approved_invocation_id": str(approved_invocation.get("invocation_id") or ""),
                    },
                }
        argv, outdir, contract_error = self._normalize_renderer_invocation_arguments(action, renderer, state)
        if contract_error:
            return {
                "type": "renderer_contract_error",
                "source": "controller",
                "contract_error": contract_error,
            }
        step_id = str(step.get("step_id") or "")
        if "--producer-step-id" not in argv and not any(item.startswith("--producer-step-id=") for item in argv):
            argv.extend(["--producer-step-id", step_id])
        has_outdir_arg = "--outdir" in argv or any(item.startswith("--outdir=") for item in argv)
        if outdir and not has_outdir_arg:
            argv.extend(["--outdir", outdir])
        if not outdir:
            for index, item in enumerate(argv):
                if item == "--outdir" and index + 1 < len(argv):
                    outdir = argv[index + 1]
                    break
                if item.startswith("--outdir="):
                    outdir = item.split("=", 1)[1]
                    break
        if not outdir:
            return {
                "type": "renderer_contract_error",
                "source": "controller",
                "contract_error": {
                    "error_type": "RENDERER_INVOCATION_SCHEMA_ERROR",
                    "renderer_id": str(renderer.get("renderer_id") or ""),
                    "missing_fields": ["outdir"],
                },
            }
        entrypoint = str(renderer.get("resolved_entrypoint") or "")
        if not entrypoint:
            return {
                "type": "renderer_contract_error",
                "source": "controller",
                "contract_error": {
                    "error_type": "RENDERER_REGISTRY_ERROR",
                    "renderer_id": str(renderer.get("renderer_id") or ""),
                    "reason": "declared renderer entrypoint could not be resolved",
                },
            }
        command_argv = [sys.executable, entrypoint, *argv]
        manifest_path = str((Path(outdir).expanduser() / str(renderer.get("manifest_filename") or "manifest.json")).resolve())
        if approved_invocation and str(approved_invocation.get("manifest_path") or "") not in {"", manifest_path}:
            return {
                "type": "renderer_contract_error",
                "source": "controller",
                "contract_error": {
                    "error_type": "RENDERER_INVOCATION_APPROVAL_MISMATCH",
                    "reason": "renderer manifest path differs from the approved binding",
                    "approved_invocation_id": str(approved_invocation.get("invocation_id") or ""),
                },
            }
        invocation_contract = deepcopy(approved_invocation) if approved_invocation else {
            "schema_version": 2,
            "renderer_id": str(renderer.get("renderer_id") or ""),
            "producer_step_id": step_id,
            "arguments": deepcopy(dict(action.get("arguments") or {})) if isinstance(action.get("arguments"), dict) else {},
            "outdir": outdir,
            "outputs": list(action.get("outputs") or []),
            "bound_outputs": deepcopy(list(action.get("bound_outputs") or [])),
        }
        invocation_contract["manifest_path"] = manifest_path
        invocation_contract.setdefault("arguments_hash", hashlib.sha256(
            json.dumps(argv, ensure_ascii=False, sort_keys=True).encode("utf-8")
        ).hexdigest())
        return {
            "type": "execute",
            "language": "bash",
            "code": shlex.join(command_argv),
            "purpose": "analysis",
            "command_role": "renderer_invocation",
            "action_source": "renderer",
            "renderer_id": str(renderer.get("renderer_id") or ""),
            "manifest_path": manifest_path,
            "expected_outputs": [manifest_path],
            "success_checks": ["renderer_exit_zero", "manifest_v3_valid", "manifest_provenance_matches"],
            "renderer_invocation_contract": invocation_contract,
        }

    def _projected_renderer_action_update(
        self,
        state: AgentState,
        task_id: str,
    ) -> Dict[str, Any]:
        """Materialize a complete TaskSpec projection through the existing renderer path."""
        protocol = self._renderer_action_protocol(state, task_id)
        projection = dict(protocol.get("argument_projection") or {})
        if (
            not protocol.get("renderer_composite")
            or protocol.get("manifest_status") != "absent"
            or not protocol.get("renderer_id")
            or not projection.get("complete")
            or projection.get("unverified_bindings")
        ):
            return {}
        structured_action = {
            "type": "renderer_invocation",
            "renderer_id": protocol["renderer_id"],
            "arguments": dict(projection.get("arguments") or {}),
            "outdir": str(projection.get("outdir") or ""),
            "argument_projection": projection,
            "action_source": "task_spec_projection",
        }
        action = self._materialize_renderer_invocation(structured_action, state, task_id)
        if action.get("type") != "execute":
            return {
                "messages": [SystemMessage(content=(
                    "TaskSpec renderer argument projection could not be materialized. "
                    + json.dumps(action.get("contract_error") or {}, ensure_ascii=False, default=str)
                ))],
                "pending_action": {},
                "renderer_argument_projection": projection,
                "generate_result": "NEEDS_RECOVERY",
                "generate_exit_reason": "renderer_projection_contract_error",
                "next_step": "generate",
            }
        bound = self._bind_pending_action(action, state, task_id)
        return {
            "messages": [SystemMessage(content=(
                "Renderer invocation was projected from verified TaskSpec bindings and the declared renderer schema."
            ))],
            "pending_action": bound,
            "renderer_argument_projection": projection,
            "generate_result": "GENERATED_ACTION",
            "generate_exit_reason": "renderer_invocation_projected",
            "next_step": "execute",
        }

    def _registered_renderer_action_update(
        self,
        state: AgentState,
        task_id: str,
    ) -> Dict[str, Any]:
        plan_state = load_plan_state(self.data_path, task_id)
        _, step = current_plan_step_with_index(plan_state)
        step = step or {}
        execution = dict(step.get("renderer_execution") or {})
        manifest_path = str(execution.get("manifest_path") or "")
        if not manifest_path:
            return {}
        try:
            manifest = json.loads(Path(manifest_path).read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {
                "messages": [SystemMessage(content=f"Registered renderer manifest is unreadable: {manifest_path}")],
                "pending_action": {},
                "failure_owner": RecoveryFailureOwner.ARTIFACT_CONTRACT.value,
                "required_next_action": "RECONCILE_ARTIFACTS",
                "next_step": "supervisor",
                "generate_result": "NEEDS_RECOVERY",
                "generate_exit_reason": "renderer_manifest_unreadable",
            }
        normalized = normalize_renderer_manifest(manifest, manifest_path)
        if renderer_manifest_complete(normalized, execution):
            evidence_ids = [
                str(item.get("execution_id") or item.get("action_id") or "")
                for item in execution.get("action_evidence", []) or []
                if str(item.get("execution_id") or item.get("action_id") or "")
            ]
            return {
                "messages": [SystemMessage(content="All required renderer manifest actions have completed; requesting step-level validation.")],
                "pending_action": {},
                "step_completion_candidate": {
                    "type": "step_completion_candidate",
                    "step_id": str(step.get("step_id") or ""),
                    "reason": "All required actions in the registered renderer manifest completed.",
                    "evidence_ids": evidence_ids or [str(execution.get("producer_action_id") or "renderer_manifest")],
                },
                "generate_result": "GENERATED_ACTION",
                "generate_exit_reason": "renderer_step_completion_candidate",
                "next_step": "generate",
            }
        action = next_renderer_manifest_action(normalized, execution)
        if not action:
            return {
                "messages": [SystemMessage(content="Renderer manifest has no runnable action; dependency or contract reconciliation is required.")],
                "pending_action": {},
                "failure_owner": RecoveryFailureOwner.ARTIFACT_CONTRACT.value,
                "required_next_action": "RECONCILE_ARTIFACTS",
                "next_step": "supervisor",
                "generate_result": "NEEDS_RECOVERY",
                "generate_exit_reason": "renderer_manifest_stalled",
            }
        try:
            script_path = resolve_renderer_action_script(normalized, action)
            manifest_script_hash = hashlib.sha256(script_path.read_bytes()).hexdigest()
        except (OSError, ValueError) as exc:
            return {
                "messages": [SystemMessage(content=str(exc))],
                "pending_action": {},
                "failure_owner": RecoveryFailureOwner.ARTIFACT_CONTRACT.value,
                "required_next_action": "RECONCILE_ARTIFACTS",
                "next_step": "supervisor",
                "generate_result": "NEEDS_RECOVERY",
                "generate_exit_reason": "renderer_script_contract_error",
            }
        artifact_by_id = {
            str(item.get("artifact_id") or ""): item
            for item in normalized.get("artifacts", []) or []
        }
        expected_outputs = [
            str(artifact_by_id[item].get("path") or "")
            for item in action.get("expected_artifact_ids", []) or []
            if item in artifact_by_id
        ]
        execution["current_action_id"] = str(action.get("id") or "")
        step["renderer_execution"] = execution
        pending = self._bind_pending_action({
            "type": "execute",
            "language": "bash",
            "code": shlex.join(["bash", str(script_path)]),
            "purpose": "validation" if action.get("kind") == "verification" else "analysis",
            "command_role": "required_validation" if action.get("kind") == "verification" else "primary",
            "action_source": "manifest_runner",
            "renderer_id": str(execution.get("renderer_id") or ""),
            "manifest_path": manifest_path,
            "manifest_fingerprint": str(execution.get("manifest_fingerprint") or ""),
            "manifest_action_id": str(action.get("id") or ""),
            "manifest_script_hash": manifest_script_hash,
            "expected_outputs": expected_outputs,
            "success_checks": list(action.get("success_checks") or []),
        }, state, task_id, plan_state=plan_state)
        return {
            "messages": [SystemMessage(content=f"Manifest Runner selected action {action.get('id')}: {script_path.name}")],
            "pending_action": pending,
            "generate_result": "GENERATED_ACTION",
            "generate_exit_reason": "manifest_action_selected",
            "next_step": "execute",
        }

    @staticmethod
    def _runtime_bindings_from_state(state: Dict[str, Any]) -> Dict[str, str]:
        """Return verified runtime paths as safe environment bindings.

        Runtime audit remains the sole path resolver. Execute only transports
        bindings that already passed the audit's existing-path validation.
        """
        return {
            str(key): str(value)
            for key, value in dict(
                build_resolved_runtime_snapshot(state).get("bindings") or {}
            ).items()
        }

    @staticmethod
    def _pending_action_purpose(action: Dict[str, Any], step: Dict[str, Any]) -> str:
        """Classify action intent so helper success cannot complete analysis work."""
        explicit = str(action.get("purpose") or "").strip().lower()
        action_type = str(action.get("type") or "").strip().lower()
        if action_type == "install_tool":
            return "install"
        if action_type == "ask_user":
            return "user_input"
        code = str(action.get("code") or "")
        lower = code.lower()
        read_only = bool(
            BioAnalystAgent._is_readonly_capability_probe(code)
            or re.search(
                r"\b(?:ls|find|grep|rg|head|tail|cat|sed|awk|less|more|stat|file|test|command\s+-v|which|type)\b",
                lower,
            )
        )
        writes_output = bool(re.search(r"(?:^|\s)(?:>|>>|tee\s|cp\s|mv\s)|\s-o\s+\S+", lower))
        if read_only and not writes_output:
            step_purpose = str(step.get("purpose") or "").strip().lower()
            return "validation" if explicit == "validation" or step_purpose == "validation" else "probe"
        if explicit in {"analysis", "probe", "validation", "record_failure", "install", "user_input"}:
            return explicit
        step_purpose = str(step.get("purpose") or "").strip().lower()
        if step_purpose in {"analysis", "probe", "validation", "record_failure", "install", "user_input"}:
            return step_purpose
        return "analysis"

    def _validate_pending_action_contract(
        self,
        action: Dict[str, Any],
        state: AgentState,
        task_id: str,
        *,
        expected_type: str = "execute",
    ) -> str:
        """Validate one durable action before a router may enter Execute."""
        plan_state = load_plan_state(self.data_path, task_id)
        if task_status(plan_state) in TASK_TERMINAL_STATUSES:
            return f"Task is terminal ({task_status(plan_state)}); no further action may execute."
        if not isinstance(action, dict) or not action:
            return "No structured pending action is available."
        if str(action.get("type") or "").strip().lower() != expected_type:
            return f"Pending action type is not {expected_type}."
        if not str(action.get("action_id") or "").strip():
            return "Pending action has no action_id."
        if expected_type == "execute":
            try:
                assert_current_action_runtime_scope(action)
            except ActionRuntimeContractError as exc:
                return json.dumps(
                    exc.to_diagnostic(), ensure_ascii=False, sort_keys=True,
                )
        stale = self._pending_action_stale_reason(action, state, task_id)
        if stale:
            return stale
        task_spec = self._task_spec_for_state(dict(state), list(state.get("messages", []) or []))
        approved_snapshot = load_approved_plan_snapshot(
            self.data_path,
            task_id,
            state=plan_state,
        )
        _, current_step = current_plan_step_with_index(plan_state)
        managed_bindings = build_managed_artifact_bindings(
            task_spec,
            plan_state=plan_state,
            approved_plan_snapshot=approved_snapshot,
            current_step_id=str((current_step or {}).get("step_id") or ""),
        )
        if action.get("managed_artifact_handles") or action.get("materialized_artifacts"):
            managed_violations = validate_materialized_artifacts(action, managed_bindings)
            if managed_violations:
                return json.dumps(
                    managed_violations[0].to_dict(),
                    ensure_ascii=False,
                    sort_keys=True,
                )
        if expected_type == "execute":
            code = str(action.get("code") or "").strip()
            if not code:
                generated_ref = dict(action.get("generated_script") or {})
                generated_path = str(generated_ref.get("path") or action.get("generated_script_path") or "")
                generated_hash = str(generated_ref.get("sha256") or action.get("generated_script_hash") or "")
                try:
                    payload = Path(generated_path).read_bytes() if generated_path else b""
                except OSError:
                    payload = b""
                if payload and (not generated_hash or hashlib.sha256(payload).hexdigest() == generated_hash):
                    code = payload.decode("utf-8", errors="replace").strip()
            if not code:
                return "Pending execute action has no verified generated script source."
            executable_lines = [
                line.strip() for line in code.splitlines()
                if line.strip() and not line.lstrip().startswith("#")
            ]
            if not executable_lines:
                return "Pending execute action contains comments only."
            protocol = self._renderer_action_protocol(state, task_id)
            if protocol.get("renderer_composite") and protocol.get("manifest_status") != "registered":
                source = str(action.get("action_source") or "")
                role = str(action.get("command_role") or "")
                if source not in {"renderer", "renderer_compat_adapter"} or role != "renderer_invocation":
                    return (
                        "The current Renderer-backed composite step has no registered manifest. "
                        "Only a structured RENDERER_INVOCATION may execute; ordinary EXECUTE, probes, "
                        "and STEP_COMPLETION_CANDIDATE are rejected before execution."
                    )
            if str(action.get("action_source") or "") == "manifest_runner":
                _, step = current_plan_step_with_index(plan_state)
                step = step or {}
                renderer_execution = dict(step.get("renderer_execution") or {})
                if str(action.get("manifest_fingerprint") or "") != str(renderer_execution.get("manifest_fingerprint") or ""):
                    return "Pending manifest action does not match the registered manifest fingerprint."
                manifest_path = str(renderer_execution.get("manifest_path") or "")
                try:
                    manifest = normalize_renderer_manifest(
                        json.loads(Path(manifest_path).read_text(encoding="utf-8")),
                        manifest_path,
                    )
                    manifest_action = next(
                        item for item in manifest.get("actions", [])
                        if str(item.get("id") or "") == str(action.get("manifest_action_id") or "")
                    )
                    declared_script = resolve_renderer_action_script(manifest, manifest_action)
                    declared_script_hash = hashlib.sha256(declared_script.read_bytes()).hexdigest()
                except (OSError, json.JSONDecodeError, StopIteration, ValueError) as exc:
                    return f"Manifest action contract is invalid: {exc}"
                if str(declared_script) not in code:
                    return (
                        f"Pending command does not execute the manifest-declared script {declared_script}; "
                        f"requested action={action.get('manifest_action_id') or '<missing>'}."
                    )
                if str(action.get("manifest_script_hash") or "") != declared_script_hash:
                    return "Pending manifest action script changed after it was selected; reschedule it from the manifest."
            else:
                _, step = current_plan_step_with_index(plan_state)
                renderer_execution = dict((step or {}).get("renderer_execution") or {})
                if renderer_execution.get("manifest_path") and str(action.get("command_role") or "") not in {
                    "diagnostic", "recovery",
                }:
                    return (
                        "A renderer manifest is already registered for the current composite step. "
                        "Only the controller-selected manifest action may execute; free-form Generate commands are rejected."
                    )
        records = RecoveryStateStore(self.data_path, task_id).load_execution_records()
        same = [row for row in records if str(row.get("action_id") or row.get("execution_id") or "") == str(action.get("action_id"))]
        script_hash = str(action.get("manifest_script_hash") or "")
        if script_hash:
            same = [row for row in same if str(row.get("manifest_script_hash") or "") == script_hash]
        if any(str(row.get("execution_status") or "").lower() == "succeeded" or row.get("exit_code") == 0 for row in same):
            return "Pending action was already executed successfully."
        if len(same) >= 2:
            return "Pending action exhausted its duplicate execution budget."
        return ""

    def _increment_durable_budget(
        self,
        task_id: str,
        bucket: str,
        key: str,
        *,
        limit: int,
    ) -> Tuple[int, int]:
        """Increment an existing checkpoint budget so /resume keeps the count."""
        plan_state = load_plan_state(self.data_path, task_id)
        task_state = dict(plan_state.get("task_state") or {})
        budgets = dict(task_state.get("budgets") or {})
        counters = dict(budgets.get(bucket) or {})
        counter_key = str(key or "task")
        count = int(counters.get(counter_key) or 0) + 1
        counters[counter_key] = count
        budgets[bucket] = counters
        budgets[f"remaining_{bucket}"] = max(0, int(limit) - count)
        task_state["budgets"] = budgets
        plan_state["task_state"] = task_state
        save_plan_state(self.data_path, task_id, plan_state)
        return count, max(0, int(limit) - count)

    def _pending_action_revision_mismatches(
        self,
        action: Mapping[str, Any],
        plan_state: Mapping[str, Any],
    ) -> Dict[str, Dict[str, str]]:
        """Compare an action with current durable execution authority.

        Revision equality is necessary but not sufficient: a successor action
        can be installed (or the pending pointer can be cleared) without
        changing those revisions.  Once an action has an identity, Execute may
        use or commit its result only while the durable pending pointer still
        names that exact action.
        """
        step = self._running_plan_step(dict(plan_state)) or {}
        expected = {
            "step_id": str(step.get("step_id") or ""),
            "task_revision": str(task_spec_revision(
                canonical_task_spec_for_state(plan_state)
            )),
            "plan_version": str(plan_state.get("plan_version") or "plan_v1"),
            "plan_revision": str(int(plan_state.get("plan_revision") or 0)),
            "authoritative_user_turn_revision": str(
                self._authoritative_user_turn_revision(plan_state)
            ),
            "plan_id": str(plan_state.get("plan_id") or ""),
            "execution_epoch": str(
                step.get("execution_epoch")
                or (plan_state.get("runtime_state") or {}).get(
                    "execution_epoch"
                )
                or "0"
            ),
        }
        mismatches = {
            key: {
                "bound": (
                    "" if key not in action or action.get(key) is None
                    else str(action.get(key))
                ),
                "current": value,
            }
            for key, value in expected.items()
            if (
                "" if key not in action or action.get(key) is None
                else str(action.get(key))
            ) != value
        }
        bound_action_id = str(action.get("action_id") or "")
        if bound_action_id:
            durable_pending = dict(
                (plan_state.get("task_state") or {}).get("pending_action")
                or {}
            )
            durable_action_id = str(durable_pending.get("action_id") or "")
            if durable_action_id != bound_action_id:
                mismatches["pending_action_identity"] = {
                    "bound": bound_action_id,
                    "current": durable_action_id,
                }
        return mismatches

    def _pending_action_stale_reason(self, action: Dict[str, Any], state: AgentState, task_id: str) -> str:
        if not isinstance(action, dict) or not action:
            return "No structured pending action is available."
        plan_state = load_plan_state(self.data_path, task_id)
        compared_fields = (
            "step_id",
            "task_revision",
            "plan_version",
            "plan_revision",
            "authoritative_user_turn_revision",
            "plan_id",
            "execution_epoch",
        )
        required_fields = tuple(
            key for key in compared_fields
            if key != "plan_id" or str(plan_state.get("plan_id") or "")
        )
        missing = [
            key for key in required_fields
            if key not in action or action.get(key) is None
            or str(action.get(key)) == ""
        ]
        if missing:
            return "Pending action is missing revision metadata: " + ", ".join(missing)
        mismatch_map = self._pending_action_revision_mismatches(action, plan_state)
        mismatches = [
            f"{key}={item['bound']!r} (expected {item['current']!r})"
            for key, item in mismatch_map.items()
        ]
        if mismatches:
            return "Pending action is stale: " + "; ".join(mismatches)
        approval_record = dict(plan_state.get("approval_record") or {})
        if approval_record.get("approval_scope_hash"):
            return validate_action_approval_lineage(
                plan_state,
                action,
                task_spec_revision(canonical_task_spec_for_state(plan_state)),
            )
        return ""

    def _validate_generate_context(self, state: AgentState, task_id: str) -> Dict[str, Any]:
        """Use the canonical Plan validator for every managed Generate entry."""
        if str(state.get("task_mode") or "managed").lower() != "managed":
            return {"valid": True, "reason_code": "lightweight_task", "missing_fields": []}
        plan_state = load_plan_state(self.data_path, task_id)
        validation = validate_plan_for_generate(
            plan_state,
            self._task_revision_for_state(dict(state)),
        )
        task_spec = canonical_task_spec_for_state(plan_state)
        if validation.get("valid") and (
            not isinstance(task_spec, dict) or not str(task_spec.get("goal") or "").strip()
        ):
            validation = {
                **validation,
                "valid": False,
                "reason_code": "missing_task_spec_goal",
                "missing_fields": ["task_spec.goal"],
            }
        return validation

    def _generate_plan_redirect(
        self,
        state: AgentState,
        task_id: str,
        validation: Dict[str, Any],
        *,
        message: str = "",
    ) -> Dict[str, Any]:
        """Persist and log one observable, issue-owner-driven Generate redirect."""
        plan_state = load_plan_state(self.data_path, task_id)
        steps = [step for step in plan_state.get("steps", []) or [] if isinstance(step, dict)]
        current_index = int(validation.get("current_step_index", -1))
        if current_index < 0:
            current_index, _ = current_plan_step_with_index(plan_state)
        current_step = steps[current_index] if 0 <= current_index < len(steps) else {}
        audit = {
            "redirect_reason": str(validation.get("reason_code") or "invalid_plan"),
            "validation_function": str(validation.get("validation_function") or "validate_plan_for_generate"),
            "task_id": task_id,
            "task_revision": self._task_revision_for_state(dict(state)),
            "plan_revision": int(plan_state.get("plan_revision") or 0),
            "plan_status": str(plan_state.get("plan_status") or ""),
            "current_step_id": str(validation.get("current_step_id") or current_step.get("step_id") or ""),
            "current_step_index": current_index,
            "missing_fields": list(validation.get("missing_fields") or []),
            "plan_source": "plan_state.json" if plan_state.get("steps") else "none",
            "plan_state_path": str(plan_state_path(self.data_path, task_id)),
            "migration_applied": list(plan_state.get("migrations_applied") or []),
        }
        approval_reason = audit["redirect_reason"] in {
            "plan_not_approved", "stale_task_revision", "plan_approval_stale",
        }
        repair_owner = str(validation.get("repair_owner") or "planner")
        if approval_reason:
            target_node = "plan_review"
        elif repair_owner == "planner":
            target_node = "planner"
        elif repair_owner in {"task_spec", "external_input"}:
            target_node = "consultant"
        else:
            target_node = "finish"
        logger.warning(
            "Generate redirected to %s: %s",
            target_node,
            json.dumps(audit, ensure_ascii=False, sort_keys=True),
        )
        detail = json.dumps(audit, ensure_ascii=False, sort_keys=True)
        plan_progress = self._record_plan_current_evidence(task_id, "generate_plan_redirect", detail)
        repair_instruction = {
            "planner": "Planner must repair the canonical current-step contract.",
            "consultant": (
                "Consultant must repair the affected TaskSpec field, or request the exact "
                "missing external value when it is not inferable."
            ),
            "finish": (
                "Automatic LLM repair is not authorized for this internal contract failure; "
                "the task is blocked with structured diagnostics."
            ),
        }.get(target_node, "Controller validation must be completed before execution.")
        user_message = message or (
            f"Generate cannot continue ({audit['redirect_reason']}). "
            f"Missing fields: {', '.join(audit['missing_fields']) or 'none'}. "
            + repair_instruction
        )
        required_next_action = (
            "PLAN_APPROVAL_REQUIRED"
            if approval_reason
            else "PLAN_PATCH"
            if target_node == "planner"
            else "TASKSPEC_REPAIR"
            if target_node == "consultant"
            else "INTERNAL_CONTRACT_BLOCKED"
        )
        update = {
            "messages": [SystemMessage(content=user_message)],
            "plan_progress": plan_progress,
            "pending_action": {},
            "resume_audit": audit,
            "required_next_action": required_next_action,
            "failure_owner": "" if approval_reason else repair_owner,
            "recovery_scope": "" if approval_reason else "CURRENT_STEP",
            "recovery_phase": "" if approval_reason else "plan_repair",
            "next_step": target_node,
        }
        if approval_reason:
            update["plan_approval_status"] = (
                "PLAN_APPROVAL_REQUIRED"
                if audit["redirect_reason"] == "plan_not_approved"
                else "PLAN_APPROVAL_STALE"
            )
        return update

    def _pause_retryable_llm_failure(
        self,
        state: AgentState,
        task_id: str,
        stage: str,
        exc: Exception,
    ) -> Dict[str, Any]:
        """Persist transient LLM failure metadata without invalidating valid business state."""
        summary = llm_failure_summary(exc, stage, task_id)
        logger.error(summary)
        failure_id = "failure_" + hashlib.sha256(
            f"{task_id}|{stage}|{type(exc).__name__}|{summary}".encode("utf-8")
        ).hexdigest()[:16]
        plan_state = load_plan_state(self.data_path, task_id)
        prior_failure = plan_state.get("failure") if isinstance(plan_state.get("failure"), dict) else {}
        retry_count = int(prior_failure.get("retry_count") or 0) + 1
        plan_state["failure"] = {
            "failure_type": type(exc).__name__,
            "failure_stage": stage,
            "failure_id": failure_id,
            "retry_count": retry_count,
            "recorded_at": datetime.now().isoformat(timespec="seconds"),
            "task_revision": self._task_revision_for_state(dict(state)),
            "plan_revision": int(plan_state.get("plan_revision") or 0),
            "plan_status": str(plan_state.get("plan_status") or ""),
            "current_step_id": str((self._running_plan_step(plan_state) or {}).get("step_id") or ""),
            "summary": summary,
        }
        save_plan_state(self.data_path, task_id, plan_state)
        if self.state_manager:
            try:
                self.state_manager.update_task_status(task_id, "paused_retryable")
            except Exception:
                pass
        return {
            "messages": [
                SystemMessage(
                    content=(
                        "<llm_retryable_pause>\n"
                        f"{summary}\n"
                        "The task is paused_retryable. Existing plan, approval, current step, skills and inputs were preserved.\n"
                        "</llm_retryable_pause>"
                    )
                )
            ],
            "failure_type": type(exc).__name__,
            "failure_stage": stage,
            "failure_id": failure_id,
            "recovery_status": "paused_retryable",
            "next_step": "finish",
        }

    def _current_action_contract(self, state: AgentState, task_id: str) -> str:
        plan_state = load_plan_state(self.data_path, task_id)
        feedback = self._fresh_supervisor_feedback(state, task_id)
        fixes = [str(item) for item in feedback.get("required_fix", []) if str(item).strip()]
        structured_recovery = bool(state.get("recovery_context") or state.get("recovery_decision"))
        if structured_recovery:
            fixes = []
        protocol = self._renderer_action_protocol(state, task_id)
        lines = [
            f"task_revision: {self._task_revision_for_state(dict(state))}",
            f"plan_version: {str(plan_state.get('plan_version') or 'plan_v1')}",
            "Generate exactly one structured action for the canonical current step; do not execute later steps.",
            "The plan is approved. Do not ask whether to continue; HITL handles execution approval.",
            "Allowed actions are authoritative in CurrentStepContext.",
        ]
        if protocol.get("renderer_composite"):
            lines.extend([
                f"canonical_renderer_id: {protocol.get('renderer_id') or '<missing>'}",
                "renderer_argument_schema: " + json.dumps(
                    protocol.get("argument_schema") or {}, ensure_ascii=False, sort_keys=True
                ),
                "formal_verified_inputs: " + json.dumps(
                    protocol.get("resolved_inputs") or [], ensure_ascii=False, sort_keys=True
                ),
                "projected_renderer_arguments: " + json.dumps(
                    protocol.get("argument_projection") or {}, ensure_ascii=False, sort_keys=True
                ),
                (
                    "Only the actions listed above are valid until the Renderer manifest is registered."
                    if protocol.get("manifest_status") != "registered"
                    else "The Manifest Runner owns the next action; do not generate a free-form command."
                ),
            ])
        records = [] if structured_recovery else RecoveryStateStore(self.data_path, task_id).load_execution_records()
        eligible = [
            record
            for record in records
            if isinstance(record, dict)
            and str(record.get("execution_status") or "").lower() == "succeeded"
            and (record.get("exit_code") in (None, "", 0, "0"))
        ][-3:]
        if eligible:
            lines.append("eligible_execution_evidence:")
            for record in eligible:
                evidence_id = str(
                    record.get("execution_id")
                    or record.get("action_id")
                    or record.get("attempt_id")
                    or ""
                )
                lines.append(
                    "- id={}; source_step={}; purpose={}".format(
                        evidence_id,
                        str(record.get("step_id") or ""),
                        str(record.get("purpose") or ""),
                    )
                )
            lines.append(
                "If this evidence already satisfies every success criterion for the current step, return "
                "STEP_COMPLETION_CANDIDATE with the current step_id and cited evidence_ids."
            )
        if fixes:
            lines.append("required_fix: " + " | ".join(fixes[:3]))
        return "\n".join(lines)

    def _current_action_semantic_contract(
        self,
        state: AgentState,
        task_id: str,
    ) -> Dict[str, Any]:
        """Project action meaning without plan/renderer identity or paths."""
        protocol = self._renderer_action_protocol(state, task_id)
        feedback = self._fresh_supervisor_feedback(state, task_id)
        argument_schema = protocol.get("argument_schema") or {}
        arguments: List[Dict[str, Any]] = []
        if isinstance(argument_schema, Mapping):
            for name, raw in argument_schema.items():
                spec = dict(raw) if isinstance(raw, Mapping) else {}
                arguments.append({
                    "name": str(name),
                    "required": bool(spec.get("required")),
                    "semantic_type": str(
                        spec.get("semantic_type")
                        or spec.get("type")
                        or spec.get("role")
                        or ""
                    ),
                    "description": str(spec.get("description") or spec.get("purpose") or ""),
                })
        result: Dict[str, Any] = {
            "policy": "one_structured_action_for_current_step",
        }
        if protocol.get("renderer_composite"):
            result.update({
                "execution_contract": "legacy_renderer_v1",
                "manifest_status": str(protocol.get("manifest_status") or ""),
                "legacy_renderer_managed": True,
            })
            if arguments:
                result["legacy_renderer_arguments"] = arguments
        fixes = [
            str(item) for item in feedback.get("required_fix", []) or []
            if str(item).strip()
        ]
        if fixes and not (state.get("recovery_context") or state.get("recovery_decision")):
            result["required_fixes"] = fixes[:3]
        return result

    @staticmethod
    def _step_local_messages(
        messages: List[BaseMessage],
        *,
        max_messages: int = LLM_STEP_CONTEXT_MESSAGES,
        max_chars: int = LLM_STEP_CONTEXT_CHARS,
        structured_recovery: bool = False,
    ) -> List[BaseMessage]:
        """Select evidence for the current step without mutating audit history.

        The graph keeps the complete message list for persistence and recovery.
        LLM calls receive only the original goal, explicit user answer, latest
        observation, latest control/recovery feedback, and latest action.
        """
        if not messages:
            return []

        selected_indexes: set[int] = set()

        def add(index: int) -> None:
            if 0 <= index < len(messages):
                selected_indexes.add(index)

        first_human_index = next(
            (index for index, message in enumerate(messages) if isinstance(message, HumanMessage)),
            None,
        )
        if first_human_index is not None:
            add(first_human_index)

        for index in range(len(messages) - 1, -1, -1):
            content = str(getattr(messages[index], "content", messages[index]) or "")
            if isinstance(messages[index], HumanMessage) and "<human_answer" in content:
                add(index)
                break

        if structured_recovery:
            ordered = [messages[index] for index in sorted(selected_indexes)]
            return BioAnalystAgent._bounded_message_history(
                ordered,
                max_messages=min(2, max_messages),
                max_chars=min(4000, max_chars),
            )

        for index in range(len(messages) - 1, -1, -1):
            content = str(getattr(messages[index], "content", messages[index]) or "")
            if "<observation>" in content:
                add(index)
                break

        control_markers = (
            "<supervisor_feedback",
            "<consultant_validation_error>",
            "<recovery_",
            "<action_format_repair>",
            "<step_completion_candidate_rejected>",
            "<knowledge_conflict",
            "step_completion_gate_failed",
            "final_completion_validation_failed",
            "llm_transient_failure",
            "llm_transient_retry",
        )
        for index in range(len(messages) - 1, -1, -1):
            content = str(getattr(messages[index], "content", messages[index]) or "")
            lower = content.lower()
            if any(marker in lower for marker in control_markers):
                add(index)
                break

        action_prefixes = (
            "EXECUTE",
            "SEARCH",
            "LOAD_",
            "ASK",
            "FINISH",
            "<action_json>",
        )
        for index in range(len(messages) - 1, -1, -1):
            content = str(getattr(messages[index], "content", messages[index]) or "").strip()
            if isinstance(messages[index], AIMessage) and (
                content.startswith(action_prefixes)
                or "<execute>" in content
                or "<install_tool" in content
                or "<activate_batch" in content
            ):
                add(index)
                break

        if not selected_indexes:
            add(len(messages) - 1)
        ordered = [messages[index] for index in sorted(selected_indexes)]
        return BioAnalystAgent._bounded_message_history(
            ordered,
            max_messages=max_messages,
            max_chars=max_chars,
        )

    @staticmethod
    def _consultant_effective_pool_budgets(context_limit_tokens: int) -> Dict[str, int]:
        """Return nominal and provider-safe Consultant pool sizes.

        The two configured pools are independent 100k-token ceilings.  When
        their sum reaches the provider context window, output headroom is
        deducted proportionally instead of waiting for the API to reject the
        request.
        """
        history_nominal = max(1, int(CONSULTANT_HISTORY_TOKEN_BUDGET))
        skill_nominal = max(1, int(CONSULTANT_SKILL_TOKEN_BUDGET))
        nominal_total = history_nominal + skill_nominal
        provider_limit = max(1, int(context_limit_tokens or nominal_total))
        provider_safe_input = max(
            1,
            provider_limit
            - min(CONSULTANT_RESERVED_HEADROOM_TOKENS, max(0, provider_limit - 1)),
        )
        safe_total = min(nominal_total, provider_safe_input)
        if safe_total >= nominal_total:
            history_effective = history_nominal
            skill_effective = skill_nominal
        else:
            history_effective = max(1, (safe_total * history_nominal) // nominal_total)
            skill_effective = max(1, safe_total - history_effective)
        return {
            "history_nominal_tokens": history_nominal,
            "skill_nominal_tokens": skill_nominal,
            "nominal_total_tokens": nominal_total,
            "provider_context_limit_tokens": provider_limit,
            "reserved_headroom_tokens": CONSULTANT_RESERVED_HEADROOM_TOKENS,
            "history_effective_tokens": history_effective,
            "skill_effective_tokens": skill_effective,
            "effective_input_tokens": history_effective + skill_effective,
            "history_effective_chars": history_effective * CONSULTANT_ESTIMATED_CHARS_PER_TOKEN,
            "skill_effective_chars": skill_effective * CONSULTANT_ESTIMATED_CHARS_PER_TOKEN,
        }

    @staticmethod
    def _consultant_message_partitions(
        messages: List[BaseMessage],
        *,
        max_messages: int,
    ) -> tuple[List[tuple[int, BaseMessage]], List[tuple[int, BaseMessage]]]:
        skill_tags = (
            "<loaded_workflow_template",
            "<loaded_skill_doc",
            "<loaded_skill_reference",
            "<loaded_skill_script",
        )
        control_tags = (
            "<observation>",
            "<consultant_validation_error>",
            "<consultant_semantic_constraint_validation_error>",
            "<consultant_contract_repair_error>",
            "<consultant_semantic_resolution_request>",
            "<load_error",
            "<llm_transient_retry>",
            "<llm_transient_failure>",
        )
        action_prefixes = (
            "EXECUTE",
            "SEARCH",
            "LOAD_",
            "ASK",
            "FINISH",
            "<action_json>",
        )
        history_items: List[tuple[int, BaseMessage]] = []
        skill_items: List[tuple[int, BaseMessage]] = []
        for index, message in enumerate(messages or []):
            content = str(getattr(message, "content", message) or "")
            stripped = content.strip()
            if isinstance(message, SystemMessage) and any(tag in content for tag in skill_tags):
                skill_items.append((index, message))
            elif isinstance(message, HumanMessage):
                history_items.append((index, message))
            elif isinstance(message, AIMessage) and (
                stripped.startswith(action_prefixes)
                or "<execute>" in stripped
                or "<install_tool" in stripped
                or "<activate_batch" in stripped
            ):
                history_items.append((index, message))
            elif isinstance(message, SystemMessage) and any(tag in content for tag in control_tags):
                history_items.append((index, message))

        authoritative = [item for item in history_items if isinstance(item[1], HumanMessage)]
        optional_history = [item for item in history_items if not isinstance(item[1], HumanMessage)]
        optional_slots = max(0, int(max_messages) - len(authoritative))
        recent_optional = optional_history[-optional_slots:] if optional_slots else []
        bounded_history = sorted(
            [*authoritative, *recent_optional],
            key=lambda item: item[0],
        )
        bounded_skills = skill_items[-max(1, int(max_messages)):]
        return bounded_history, bounded_skills

    @staticmethod
    def _copy_message_content(message: BaseMessage, content: str) -> BaseMessage:
        try:
            return message.model_copy(update={"content": content})
        except AttributeError:
            if isinstance(message, HumanMessage):
                return HumanMessage(content=content)
            if isinstance(message, AIMessage):
                return AIMessage(content=content)
            return SystemMessage(content=content)

    @staticmethod
    def _pack_consultant_blocks_to_token_budget(
        blocks: List[ContextBlock],
        *,
        max_chars: int,
        max_tokens: Optional[int],
        pool_name: str,
    ) -> tuple[Any, int]:
        """Use character packing as a first pass, then enforce real token units."""
        current_char_budget = max(1, int(max_chars))
        token_budget = max(1, int(max_tokens)) if max_tokens is not None else None
        last_tokens = 0
        for attempt in range(12):
            try:
                packed = ContextBudgetManager().pack(blocks, current_char_budget)
            except RequiredContextOverflow as exc:
                exc.report.update({
                    "pool": pool_name,
                    "token_budget": token_budget,
                    "tokenizer": _consultant_tokenizer_name(),
                })
                raise
            joined = "\n".join(value for value in packed.contents.values() if value)
            last_tokens = _consultant_estimate_text_tokens(joined)
            packed.report.update({
                "pool": pool_name,
                "estimated_tokens": last_tokens,
                "token_budget": token_budget,
                "tokenizer": _consultant_tokenizer_name(),
                "token_pack_attempts": attempt + 1,
            })
            if token_budget is None or last_tokens <= token_budget:
                return packed, last_tokens
            packed_chars = max(1, int(packed.report.get("packed_chars") or 1))
            next_char_budget = max(
                1,
                int(packed_chars * token_budget / max(1, last_tokens) * 0.97),
            )
            if next_char_budget >= current_char_budget:
                next_char_budget = current_char_budget - 1
            if next_char_budget <= 0:
                break
            current_char_budget = next_char_budget
        raise RequiredContextOverflow(
            f"Consultant {pool_name} context cannot fit the token budget.",
            report={
                "pool": pool_name,
                "budget_chars": current_char_budget,
                "token_budget": token_budget,
                "estimated_tokens": last_tokens,
                "tokenizer": _consultant_tokenizer_name(),
                "overflow": True,
            },
        )

    @staticmethod
    def _pack_consultant_context(
        messages: List[BaseMessage],
        *,
        history_components: Dict[str, str],
        skill_components: Dict[str, str],
        history_max_chars: int,
        skill_max_chars: int,
        static_prompt_chars: int = 0,
        history_max_tokens: Optional[int] = None,
        skill_max_tokens: Optional[int] = None,
        static_prompt_tokens: int = 0,
        max_messages: int = CONSULTANT_HISTORY_MAX_MESSAGES,
    ) -> tuple[Dict[str, str], Dict[str, str], List[BaseMessage], Dict[str, Any]]:
        """Pack Consultant inputs into true shared history and skill pools.

        Human messages and the canonical task contract are lossless required
        blocks.  Explicitly preloaded docs and the newest controller-loaded doc
        are also lossless.  Older observations, memory, catalogs, and older
        loaded docs are compressed or removed only when their pool overflows.
        """
        history_items, skill_items = BioAnalystAgent._consultant_message_partitions(
            messages,
            max_messages=max_messages,
        )
        history_budget = int(history_max_chars) - max(0, int(static_prompt_chars))
        if history_budget <= 0:
            raise RequiredContextOverflow(
                "Consultant static policy exceeds the history pool.",
                report={
                    "pool": "history",
                    "budget_chars": int(history_max_chars),
                    "static_prompt_chars": int(static_prompt_chars),
                    "overflow": True,
                },
            )

        history_specs = {
            "task_spec": dict(priority=100, pinned=True, droppable=False),
            "deterministic_base_constraints": dict(priority=100, pinned=True, droppable=False),
            "semantic_provenance_catalog": dict(priority=100, pinned=True, droppable=False),
            "contract_repair": dict(priority=100, pinned=True, droppable=False),
            "selected_skill_context": dict(priority=95, pinned=True, droppable=False),
            "input_resolution": dict(
                priority=92,
                pinned=False,
                droppable=False,
                min_chars=3000,
                compress_fn=compress_lines,
            ),
            "user_preferences": dict(
                priority=60,
                min_chars=400,
                compress_fn=compress_paragraphs,
            ),
            "memory_context": dict(
                priority=35,
                min_chars=800,
                compress_fn=compress_paragraphs,
            ),
            "rag_history": dict(
                priority=30,
                min_chars=800,
                compress_fn=compress_paragraphs,
            ),
        }
        history_blocks: List[ContextBlock] = []
        for key, value in history_components.items():
            spec = history_specs.get(key, dict(priority=50, compress_fn=compress_paragraphs))
            history_blocks.append(ContextBlock(
                f"history_component:{key}",
                "consultant_history",
                str(value or ""),
                **spec,
            ))
        for ordinal, (index, message) in enumerate(history_items):
            is_human = isinstance(message, HumanMessage)
            history_blocks.append(ContextBlock(
                f"history_message:{index}",
                "user_authority" if is_human else "consultant_action_history",
                str(getattr(message, "content", message) or ""),
                100 if is_human else 65 + min(20, ordinal),
                pinned=is_human,
                droppable=not is_human,
                min_chars=0 if is_human else 500,
                compress_fn=None if is_human else compress_tagged_text,
            ))
        history_token_budget = (
            max(1, int(history_max_tokens) - max(0, int(static_prompt_tokens)))
            if history_max_tokens is not None else None
        )
        packed_history, history_tokens = BioAnalystAgent._pack_consultant_blocks_to_token_budget(
            history_blocks,
            max_chars=history_budget,
            max_tokens=history_token_budget,
            pool_name="history",
        )

        skill_specs = {
            "preloaded_skill_docs": dict(priority=100, pinned=True, droppable=False),
            "runtime_evidence": dict(
                priority=92,
                droppable=False,
                min_chars=1500,
                compress_fn=compress_lines,
            ),
            "skill_catalog": dict(priority=75, min_chars=1200, compress_fn=compress_lines),
            "skill_tree": dict(priority=65, min_chars=1200, compress_fn=compress_lines),
            "workflow_catalog": dict(priority=70, min_chars=800, compress_fn=compress_lines),
            "controlled_discovery_hints": dict(
                priority=72,
                min_chars=500,
                compress_fn=compress_lines,
            ),
        }
        skill_blocks: List[ContextBlock] = []
        for key, value in skill_components.items():
            spec = skill_specs.get(key, dict(priority=60, compress_fn=compress_markdown_sections))
            skill_blocks.append(ContextBlock(
                f"skill_component:{key}",
                "consultant_skill",
                str(value or ""),
                **spec,
            ))
        newest_skill_index = skill_items[-1][0] if skill_items else None
        for ordinal, (index, message) in enumerate(skill_items):
            newest = index == newest_skill_index
            skill_blocks.append(ContextBlock(
                f"skill_message:{index}",
                "loaded_skill_doc",
                str(getattr(message, "content", message) or ""),
                100 if newest else 75 + min(20, ordinal),
                pinned=newest,
                droppable=not newest,
                min_chars=0 if newest else 2500,
                compress_fn=None if newest else compress_markdown_sections,
            ))
        packed_skills, skill_tokens = BioAnalystAgent._pack_consultant_blocks_to_token_budget(
            skill_blocks,
            max_chars=int(skill_max_chars),
            max_tokens=skill_max_tokens,
            pool_name="skills",
        )

        packed_history_components = {
            key: packed_history.contents.get(f"history_component:{key}", "")
            for key in history_components
        }
        packed_skill_components = {
            key: packed_skills.contents.get(f"skill_component:{key}", "")
            for key in skill_components
        }
        packed_messages: List[tuple[int, BaseMessage]] = []
        for index, message in history_items:
            content = packed_history.contents.get(f"history_message:{index}", "")
            if content:
                packed_messages.append((index, BioAnalystAgent._copy_message_content(message, content)))
        for index, message in skill_items:
            content = packed_skills.contents.get(f"skill_message:{index}", "")
            if content:
                packed_messages.append((index, BioAnalystAgent._copy_message_content(message, content)))
        report = {
            "history": packed_history.report,
            "skills": packed_skills.report,
            "static_prompt_chars": int(static_prompt_chars),
            "static_prompt_tokens": int(static_prompt_tokens),
            "estimated_history_pool_tokens": history_tokens + max(0, int(static_prompt_tokens)),
            "estimated_skill_pool_tokens": skill_tokens,
            "tokenizer": _consultant_tokenizer_name(),
        }
        return (
            packed_history_components,
            packed_skill_components,
            [message for _, message in sorted(packed_messages, key=lambda item: item[0])],
            report,
        )

    @staticmethod
    def _consultant_visible_messages(
        messages: List[BaseMessage],
        *,
        history_max_chars: int = CONSULTANT_HISTORY_CHAR_BUDGET,
        skill_max_chars: int = CONSULTANT_SKILL_CHAR_BUDGET,
        max_messages: int = CONSULTANT_HISTORY_MAX_MESSAGES,
    ) -> List[BaseMessage]:
        """Compatibility wrapper for tests and other Consultant callers."""
        _, _, visible, _ = BioAnalystAgent._pack_consultant_context(
            messages,
            history_components={},
            skill_components={},
            history_max_chars=history_max_chars,
            skill_max_chars=skill_max_chars,
            max_messages=max_messages,
        )
        return visible

    def _append_semantic_conversation_turn(
        self,
        task_id: str,
        *,
        role: str,
        content: str,
        question_id: str = "",
        content_ref: str = "",
    ) -> Tuple[List[Dict[str, Any]], str]:
        """Append one durable user/question turn and return the full chain.

        The plan state owns only the bounded chain index.  Turn content is an
        immutable object, so checkpoint compaction and graph-message pruning
        cannot erase semantic user authority.
        """
        plan_state = load_plan_state(self.data_path, task_id)
        store = StateContractStore(self.data_path, task_id)
        index = dict(plan_state.get("conversation_evidence") or {})
        existing = store.read_conversation_evidence(index) if index.get("head_ref") else []
        normalized_role = str(role or "").strip().lower()
        normalized_question = str(question_id or "")
        # LangGraph can re-enter an interrupting node.  A stable question_id
        # makes persisting the displayed question idempotent.
        for turn in existing:
            if (
                normalized_question
                and str(turn.get("question_id") or "") == normalized_question
                and str(turn.get("role") or "") == normalized_role
                and (
                    normalized_role == "consultant_question"
                    or str(turn.get("content") or "") == str(content or "")
                )
            ):
                return existing, str(turn.get("turn_ref") or "")
        next_index, turn_ref = store.append_conversation_turn(
            index,
            role=normalized_role,
            content=str(content or ""),
            content_ref=str(content_ref or ""),
            question_id=normalized_question,
        )
        plan_state["conversation_evidence"] = next_index
        save_plan_state(self.data_path, task_id, plan_state)
        return store.read_conversation_evidence(next_index), turn_ref

    def _persist_user_submission(
        self,
        task_id: str,
        prompt: Any,
        *,
        structured_source: Optional[Mapping[str, Any]] = None,
    ) -> Tuple[Dict[str, Any], bool, str]:
        """Append U(n), or create U1 plus the uninitialized bootstrap state.

        This is the sole normal-entry turn allocator used by ``go``.  Reusing
        a task ID therefore extends one durable evidence chain instead of
        creating another root or replacing earlier user authority.
        """
        store = StateContractStore(self.data_path, task_id)
        raw_submission_ref = store.put_object(
            "raw_user_submission",
            {
                "text": str(prompt),
                "structured_source": dict(structured_source or {}),
            },
        )
        existing_path = plan_state_path(self.data_path, task_id)
        existing_plan = (
            load_plan_state(self.data_path, task_id)
            if existing_path.is_file()
            else {}
        )
        existing_conversation = dict(
            existing_plan.get("conversation_evidence") or {}
        )
        is_continuation = bool(existing_conversation.get("head_ref"))
        if is_continuation:
            self._append_semantic_conversation_turn(
                task_id,
                role="user",
                content=str(prompt),
                content_ref=raw_submission_ref,
            )
        else:
            conversation_evidence, _ = store.append_conversation_turn(
                None,
                role="user",
                content=str(prompt),
                content_ref=raw_submission_ref,
            )
            initialize_consultant_bootstrap_state(
                self.data_path,
                task_id,
                raw_submission_ref=raw_submission_ref,
                conversation_evidence=conversation_evidence,
            )
        durable = load_plan_state(self.data_path, task_id)
        durable_task_state = dict(durable.get("task_state") or {})
        if (
            durable_task_state.get("skill_access_state")
            or durable.get("skill_access_state")
        ):
            invalidated_access = invalidate_skill_continuations(
                durable_task_state.get("skill_access_state")
                or durable.get("skill_access_state"),
                reason="authoritative_user_turn_changed",
            )
            durable_task_state["skill_access_state"] = invalidated_access
            durable_task_state.pop("skill_continuation_id", None)
            durable["task_state"] = durable_task_state
            durable["skill_access_state"] = deepcopy(invalidated_access)
            save_plan_state(self.data_path, task_id, durable)
            durable = load_plan_state(self.data_path, task_id)
        return durable, is_continuation, raw_submission_ref

    def _consultant_semantic_conversation(
        self,
        task_id: str,
        messages: Sequence[BaseMessage] = (),
    ) -> Tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
        """Rebuild complete chronological semantic evidence for Consultant.

        A damaged legacy session may have only ``raw_submission_ref``.  That
        is treated as an uninitialized bootstrap and linked as U1 without any
        snpEff- or filename-specific interpretation.
        """
        plan_state = load_plan_state(self.data_path, task_id)
        store = StateContractStore(self.data_path, task_id)
        index = dict(plan_state.get("conversation_evidence") or {})
        turns = store.read_conversation_evidence(index) if index.get("head_ref") else []
        if not turns:
            raw_ref = str((plan_state.get("audit_index") or {}).get("raw_submission_ref") or "")
            raw_text = ""
            if raw_ref:
                try:
                    raw_payload = store.read_object(raw_ref, expected_type="raw_user_submission")
                    if isinstance(raw_payload, Mapping):
                        raw_text = str(raw_payload.get("text") or "")
                except Exception as exc:
                    logger.warning("Could not recover raw conversation evidence for %s: %s", task_id, exc)
            if raw_text:
                turns, _ = self._append_semantic_conversation_turn(
                    task_id,
                    role="user",
                    content=raw_text,
                    content_ref=raw_ref,
                )
            else:
                # Last-resort compatibility for sessions predating the raw
                # object convention.  Preserve every actual HumanMessage in
                # order; do not select only the newest one.
                for message in messages:
                    if not isinstance(message, HumanMessage):
                        continue
                    text = str(getattr(message, "content", "") or "").strip()
                    if text:
                        turns, _ = self._append_semantic_conversation_turn(
                            task_id,
                            role="user",
                            content=text,
                        )
        evidence: List[Dict[str, Any]] = []
        for turn in turns:
            role = str(turn.get("role") or "")
            turn_id = str(turn.get("turn_id") or "")
            label = "USER" if role == "user" else "CONSULTANT"
            evidence.append({
                "evidence_id": str(turn.get("turn_ref") or turn_id),
                "kind": "user_message" if role == "user" else "consultant_question",
                "excerpt": f"[{turn_id} {label}]\n{str(turn.get('content') or '')}",
                "truncated": False,
            })
        return turns, evidence

    def _node_context_semantic_inputs(
        self,
        task_id: str,
        plan_state: Mapping[str, Any],
        *,
        messages: Sequence[BaseMessage] = (),
        accepted_contract: Optional[Mapping[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Load reusable semantic authorities for Planner/Generate/Recovery."""
        turns, _ = self._consultant_semantic_conversation(task_id, messages)
        task_state = dict(plan_state.get("task_state") or {})
        handoff = dict(task_state.get("accepted_consultant_handoff") or {})
        if not handoff and accepted_contract:
            handoff = self._accepted_consultant_handoff_projection(
                accepted_contract
            )
        recovery_store = RecoveryStateStore(self.data_path, task_id)
        return {
            "conversation_turns": turns,
            "consultant_handoff": handoff,
            "execution_records": recovery_store.load_execution_records(),
            "recovery_decisions": recovery_store.load_attempts(),
        }

    @staticmethod
    def _generate_visible_messages(
        messages: List[BaseMessage],
        *,
        structured_recovery: bool = False,
    ) -> List[BaseMessage]:
        """Drop Consultant internals, then keep only current-step evidence."""
        filtered: List[BaseMessage] = []
        internal_prefixes = ("LOAD_WORKFLOW_TEMPLATE", "LOAD_SKILL_DOC", "LOAD_REFERENCE", "LOAD_SCRIPT")
        internal_tags = (
            "<loaded_workflow_template",
            "<loaded_skill_doc",
            "<loaded_skill_reference",
            "<loaded_skill_script",
            "<load_error action=\"LOAD_",
            "<consultant_validation_error>",
        )
        for message in messages:
            content = str(getattr(message, "content", "")).strip()
            if isinstance(message, AIMessage) and content.startswith(internal_prefixes):
                continue
            if isinstance(message, SystemMessage) and any(tag in content for tag in internal_tags):
                continue
            filtered.append(message)
        return BioAnalystAgent._step_local_messages(
            filtered,
            structured_recovery=structured_recovery,
        )

    def _current_step_prompt_context(
        self,
        task_id: str,
        current_plan: str = "",
        plan_progress: str = "",
        state: Optional[AgentState] = None,
    ) -> str:
        """Serialize the controller-owned CurrentStepContext exactly once."""
        plan_state = load_plan_state(self.data_path, task_id) if task_id else {}
        state_map = dict(state or {})
        protocol = self._renderer_action_protocol(state_map, task_id) if state is not None else {}
        current_step = build_current_step_context(
            state_map,
            plan_state,
            allowed_actions=protocol.get("allowed_actions") or None,
        ).to_dict()
        if not current_step.get("step_id"):
            next_match = re.search(
                r"^Next step:\s*(.+)$",
                str(plan_progress or ""),
                re.MULTILINE | re.IGNORECASE,
            )
            current_step["title"] = (
                next_match.group(1).strip() if next_match else "No pending step."
            )
        return (
            "<current_step_context>\n"
            + json.dumps(current_step, ensure_ascii=False, sort_keys=True, default=str)
            + "\n</current_step_context>"
        )

    @staticmethod
    def _format_workflow_handoff_for_prompt(handoff: Dict[str, Any]) -> str:
        if not handoff:
            return ""
        lines = []
        workflow_id = handoff.get("workflow_id") or "none"
        lines.append(f"workflow_id: {workflow_id}")
        if handoff.get("active_batch_id"):
            lines.append(f"active_batch_id: {handoff.get('active_batch_id')}")
        stages = handoff.get("workflow_stages") or []
        if stages:
            lines.append("workflow_stages:")
            for stage in stages:
                lines.append(
                    "- "
                    f"stage={stage.get('stage', '')}; "
                    f"status={stage.get('status', '')}; "
                    f"skill={stage.get('skill', 'none')}; "
                    f"batch_id={stage.get('batch_id', '')}; "
                    f"reason={stage.get('reason', '')}"
                )
        return "\n".join(lines)

    def _activate_workflow_batch(self, state: AgentState, batch_id: str) -> Dict[str, Any]:
        handoff = self._workflow_state_from_mapping(state)
        stages = [dict(stage) for stage in handoff.get("workflow_stages", state.get("workflow_stages", [])) or []]
        if not stages:
            return {
                "messages": [HumanMessage(content="<observation>❌ No workflow stages are available to activate.</observation>")],
                "next_step": "generate",
            }
        target_batch = str(batch_id or "").strip()
        active_skills: List[str] = []
        future_skills: List[str] = []
        for stage in stages:
            stage_batch = str(stage.get("batch_id") or "").strip()
            is_active = bool(target_batch and stage_batch == target_batch)
            stage["active_now"] = is_active
            if stage.get("status") == "selected_skill":
                skill = str(stage.get("skill") or "").strip()
                normalized = self.skill_manager.normalize_selected_skills([skill], max_results=1) if self.skill_manager else [skill]
                skill = normalized[0] if normalized else ""
                if is_active and skill and skill not in active_skills:
                    active_skills.append(skill)
                elif skill and skill not in future_skills:
                    future_skills.append(skill)
        if not active_skills:
            return {
                "messages": [HumanMessage(content=f"<observation>❌ Batch {target_batch} has no selected skills.</observation>")],
                "next_step": "generate",
            }
        handoff["workflow_stages"] = stages
        handoff["active_batch_id"] = target_batch
        handoff["active_skills"] = active_skills
        handoff["future_skills"] = future_skills
        if not handoff.get("required_skills_all"):
            ordered_all: List[str] = []
            for skill in active_skills + future_skills:
                if skill not in ordered_all:
                    ordered_all.append(skill)
            handoff["required_skills_all"] = ordered_all
        result = validate_workflow_handoff(
            handoff,
            self.skill_manager,
            self.workflow_manager,
            max_active_skills=SkillManager.MAX_ACTIVE_SKILLS,
        )
        if result["errors"]:
            obs = "<observation>❌ Workflow batch activation failed:\n" + "\n".join(result["errors"]) + "\n</observation>"
            return {"messages": [HumanMessage(content=obs)], "next_step": "generate"}
        handoff = result["handoff"]
        obs = (
            f"<observation>✅ Activated workflow batch {target_batch}. "
            f"Active skills: {', '.join(handoff.get('active_skills', []))}</observation>"
        )
        return {
            "messages": [HumanMessage(content=obs)],
            "workflow_state": handoff,
            "workflow_handoff": handoff,
            "workflow_stages": handoff.get("workflow_stages", []),
            "active_batch_id": handoff.get("active_batch_id", target_batch),
            "active_skills": handoff.get("active_skills", []),
            "future_skills": handoff.get("future_skills", []),
            "required_skills_all": handoff.get("required_skills_all", []),
            "selected_skills": (state.get("selected_skills", []) or handoff.get("required_skills_all", [])),
            "next_step": "generate",
        }

    def _current_plan_step_skill_ids(self, task_id: str) -> Tuple[List[str], bool, Dict[str, Any]]:
        plan_state = load_plan_state(self.data_path, task_id)
        step = self._running_plan_step(plan_state)
        if not step:
            step = next(
                (
                    item for item in plan_state.get("steps", []) or []
                    if isinstance(item, dict) and str(item.get("status") or "").lower() == "pending"
                ),
                {},
            )
        raw = [str(item).strip() for item in step.get("skill_ids", []) or [] if str(item).strip()]
        # A persisted non-empty machine mapping is authoritative even if an
        # older PlanPatch lost the derived skills_declared marker.
        declared = bool(step.get("skills_declared") or raw)
        normalized = (
            self.skill_manager.normalize_selected_skills(raw, max_results=SkillManager.MAX_SELECTED_SKILLS)
            if self.skill_manager and raw else raw
        )
        if self.skill_manager:
            step = dict(step)
            step["unresolved_skill_ids"] = [
                item for item in raw
                if not self.skill_manager.normalize_selected_skills([item], max_results=1)
            ]
        return normalized, declared, step

    def _plan_step_skill_violations(
        self,
        plan_state: Dict[str, Any],
        selected_skills: List[str],
    ) -> List[Dict[str, Any]]:
        selected = set(self._selected_skill_ids(selected_skills))
        violations: List[Dict[str, Any]] = []
        steps = [step for step in plan_state.get("steps", []) or [] if isinstance(step, dict)]
        if not steps:
            return [validation_issue(
                "PLAN_STEPS_MISSING",
                owner="planner",
                repair_target="$.steps",
                field_path="$.steps",
                message="Plan must contain at least one structured step.",
                validator_id="plan_skill_bindings",
            )]
        for step_index, step in enumerate(steps):
            step_id = str(step.get("step_id") or "unknown")
            skill_path = f"$.steps[{step_index}].skill_ids"
            if not step.get("skills_declared"):
                violations.append(validation_issue(
                    "PLAN_STEP_SKILLS_UNDECLARED",
                    owner="planner",
                    repair_target=skill_path,
                    field_path=skill_path,
                    message="Plan step must explicitly declare its skill_ids field.",
                    validator_id="plan_skill_bindings",
                    step_id=step_id,
                ))
                continue
            raw = [str(item).strip() for item in step.get("skill_ids", []) or [] if str(item).strip()]
            normalized = (
                self.skill_manager.normalize_selected_skills(raw, max_results=SkillManager.MAX_SELECTED_SKILLS)
                if self.skill_manager and raw else raw
            )
            unknown = [
                item for item in raw
                if self.skill_manager and not self.skill_manager.normalize_selected_skills([item], max_results=1)
            ]
            for skill_id in unknown:
                raw_index = raw.index(skill_id)
                violations.append(validation_issue(
                    "PLAN_STEP_SKILL_UNKNOWN",
                    owner="planner",
                    repair_target=f"{skill_path}[{raw_index}]",
                    field_path=f"{skill_path}[{raw_index}]",
                    message=f"Plan step declares an unknown skill ID: {skill_id}",
                    validator_id="plan_skill_bindings",
                    step_id=step_id,
                    actual_value=skill_id,
                ))
            if len(normalized) > SkillManager.MAX_ACTIVE_SKILLS:
                violations.append(validation_issue(
                    "PLAN_STEP_SKILL_LIMIT_EXCEEDED",
                    owner="planner",
                    repair_target=skill_path,
                    field_path=skill_path,
                    message=(
                        f"Plan step declares {len(normalized)} skills; at most "
                        f"{SkillManager.MAX_ACTIVE_SKILLS} are allowed."
                    ),
                    validator_id="plan_skill_bindings",
                    step_id=step_id,
                    actual_value=len(normalized),
                    expected_contract={"max_active_skills": SkillManager.MAX_ACTIVE_SKILLS},
                ))
            outside = [skill_id for skill_id in normalized if skill_id not in selected]
            for skill_id in outside:
                normalized_index = normalized.index(skill_id)
                violations.append(validation_issue(
                    "PLAN_STEP_SKILL_OUTSIDE_SELECTED",
                    owner="planner",
                    repair_target=f"{skill_path}[{normalized_index}]",
                    field_path=f"{skill_path}[{normalized_index}]",
                    message=(
                        "Plan step skill ID is outside the Consultant-selected "
                        f"capability set: {skill_id}"
                    ),
                    validator_id="plan_skill_bindings",
                    step_id=step_id,
                    actual_value=skill_id,
                ))
            if not unknown and not outside and len(normalized) <= SkillManager.MAX_ACTIVE_SKILLS:
                step["skill_ids"] = normalized
        return violations

    def _active_skill_update_for_current_plan_step(self, state: AgentState, task_id: str) -> Dict[str, Any]:
        selected_pool = self._selected_skill_ids(state.get("selected_skills", []) or [])
        active, declared, step = self._current_plan_step_skill_ids(task_id)
        if not declared:
            return {
                "active_skills": [],
                "future_skills": [],
                "skill_activation_error_field": "current_step.skills_declared",
                "skill_activation_error": (
                    f"Plan step {step.get('step_id', 'unknown')} has no explicit Skills field; "
                    "Planner must repair the step-to-skill mapping."
                ),
            }
        outside = [skill_id for skill_id in active if skill_id not in selected_pool]
        unresolved = list(step.get("unresolved_skill_ids") or [])
        if unresolved or outside or len(active) > SkillManager.MAX_ACTIVE_SKILLS:
            return {
                "active_skills": [],
                "future_skills": [],
                "skill_activation_error_field": "current_step.skill_ids",
                "skill_activation_error": (
                    f"Plan step {step.get('step_id', 'unknown')} has invalid skill mapping: "
                    f"unknown={unresolved}, outside_selected={outside}, count={len(active)}."
                ),
            }
        current_active = self._selected_skill_ids(state.get("active_skills", []) or [])
        current_future = self._selected_skill_ids(state.get("future_skills", []) or [])
        current_stage = str((step.get("workflow_stage_ids") or [""])[0] or "")
        current_batch = str(step.get("batch_id") or "")
        if (
            current_active == active
            and str(state.get("current_stage_id") or "") == current_stage
            and str(state.get("active_batch_id") or "") == current_batch
            and not current_future
            and not str(state.get("skill_activation_error") or "").strip()
        ):
            return {}
        return {
            "active_skills": active,
            "future_skills": [],
            "selected_skills": selected_pool,
            "current_stage_id": current_stage,
            "active_batch_id": current_batch,
            "skill_selection_source": "plan_step_declared_skills",
            "skill_activation_error": "",
            "skill_activation_error_field": "",
        }

    def _narrow_skills_to_current_plan_step(self, skill_ids: List[str], task_id: str) -> List[str]:
        active, declared, _ = self._current_plan_step_skill_ids(task_id)
        if not declared:
            return []
        allowed = set(self._selected_skill_ids(skill_ids or []))
        return [skill_id for skill_id in active if skill_id in allowed][: SkillManager.MAX_ACTIVE_SKILLS]

    @staticmethod
    def _workflow_batch_sort_key(batch_id: str) -> Tuple[int, str]:
        text = str(batch_id or "").strip()
        if text.isdigit():
            return (int(text), text)
        return (10**9, text)

    def _next_workflow_batch_id(self, state: AgentState) -> str:
        handoff = self._workflow_state_from_mapping(state)
        stages = [dict(stage) for stage in handoff.get("workflow_stages", (state or {}).get("workflow_stages", [])) or []]
        active_batch_id = str((state or {}).get("active_batch_id") or handoff.get("active_batch_id") or "").strip()
        future_skills = set(self._selected_skill_ids((state or {}).get("future_skills", []) or handoff.get("future_skills", []) or []))
        if not stages or not active_batch_id:
            return ""

        candidates: List[str] = []
        for stage in stages:
            if stage.get("status") != "selected_skill":
                continue
            batch_id = str(stage.get("batch_id") or "").strip()
            if not batch_id or batch_id == active_batch_id:
                continue
            skill = str(stage.get("skill") or "").strip()
            canonical = self._selected_skill_ids([skill])
            skill_id = canonical[0] if canonical else skill
            if future_skills and skill_id not in future_skills:
                continue
            if self._workflow_batch_sort_key(batch_id) <= self._workflow_batch_sort_key(active_batch_id):
                continue
            if batch_id not in candidates:
                candidates.append(batch_id)
        if not candidates:
            return ""
        return sorted(candidates, key=self._workflow_batch_sort_key)[0]

    def _activate_next_workflow_batch_after_plan_completion(
        self,
        state: AgentState,
        task_id: str,
    ) -> Optional[Dict[str, Any]]:
        next_batch_id = self._next_workflow_batch_id(state)
        if not next_batch_id:
            return None
        activation = self._activate_workflow_batch(state, next_batch_id)
        if not activation.get("active_skills"):
            return None
        reset_plan_for_replanning(self.data_path, task_id)
        activation["next_step"] = "planner"
        activation["current_plan"] = ""
        activation["plan_progress"] = ""
        activation.setdefault("messages", []).append(
            SystemMessage(
                content=(
                    f"Previous workflow batch completed. Activated batch {next_batch_id}; "
                    "create a new plan for the newly active skills. Do not finish the overall task yet."
                )
            )
        )
        return activation

    def _stable_prompt_paths(self, session_id: str, project_id: str) -> Tuple[Path, Path]:
        stem = self._safe_prompt_stem(f"{session_id}__{project_id}")
        return (
            self._stable_prompt_dir / f"{stem}.prompt.md",
            self._stable_prompt_dir / f"{stem}.meta.json",
        )

    @staticmethod
    def _read_json_file(path: Path) -> Dict[str, Any]:
        if not path.exists():
            return {}
        try:
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return {}
        return data if isinstance(data, dict) else {}

    @staticmethod
    def _safe_prompt_stem(value: str) -> str:
        safe = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(value).strip())
        return safe[:180] or "session"

    @staticmethod
    def _clip_prompt_text(text: str, max_chars: int) -> str:
        text = str(text)
        if len(text) <= max_chars:
            return text
        return text[:max_chars] + "\n...[truncated]"

    @staticmethod
    def _clip_observation_text(text: str, max_chars: int) -> str:
        text = str(text or "")
        if len(text) <= max_chars:
            return text
        if max_chars < 80:
            return text[:max_chars] + f"\n...[truncated {len(text) - max_chars} chars]"
        head = max_chars // 2
        tail = max_chars - head
        omitted = len(text) - max_chars
        return text[:head] + f"\n...[truncated {omitted} chars]...\n" + text[-tail:]

    @staticmethod
    def _consultant_unbounded_output_violation(code: str) -> str:
        """Reject raw whole-file viewers in Consultant's read-only checks.

        Consultant needs filesystem evidence, not full biological data in the
        terminal.  The rule is deliberately format-agnostic and still permits
        a bounded ``cat file | head -n N`` preview when that is useful.
        """
        sequence_path = re.compile(r"\.(?:fa|fasta|fna|fq|fastq)(?:\.gz)?(?:$|[\s'\"`|;&])", re.IGNORECASE)
        for line in str(code or "").splitlines():
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            if not re.search(r"(?:^|[;&|]\s*)(?:cat|zcat|bzcat|xzcat)\s+", stripped):
                continue
            if re.search(r"\|\s*(?:head|tail)\b", stripped):
                if sequence_path.search(stripped) and not re.search(r"\b(?:head|tail)\s+-c\s+\d+\b", stripped):
                    return (
                        "Consultant read-only output guard blocked a line-bounded preview of a sequence file. "
                        "FASTA/FASTQ may contain one very long sequence line; use `head -c 2048` or a targeted "
                        "header/count query instead of `head -n`/`tail -n`."
                    )
                continue
            if sequence_path.search(stripped) and re.search(r"\b(?:head|tail)(?:\s|$)", stripped):
                return (
                    "Consultant read-only output guard blocked an unbounded sequence preview. "
                    "Use `head -c 2048` or a targeted header/count query."
                )
            return (
                "Consultant read-only output guard blocked a whole-file viewer. "
                "Use a bounded preview such as `head -n 20 <file>`, a targeted header/query, "
                "or file size/path verification; do not print an entire input file."
            )
        return ""

    def _ensure_plan_tracker(self, task_id: str, current_plan: Optional[str] = None) -> Dict[str, Any]:
        plan_file = default_plan_file(self.data_path, task_id)
        return ensure_plan_state(
            self.data_path,
            task_id,
            plan_text=current_plan or "",
            plan_file=plan_file,
        )

    def _persist_plan_tracker(self, task_id: str, state: Dict[str, Any]) -> str:
        save_plan_state(self.data_path, task_id, state)
        plan_file = state.get("plan_file") or str(default_plan_file(self.data_path, task_id))
        update_plan_markdown_status(plan_file, state)
        return render_plan_progress(state)

    def _stage_status_candidates_from_text(self, *texts: str) -> List[Path]:
        candidates: List[Path] = []
        seen: set[str] = set()
        bases = [Path(self.data_path), project_root, Path.cwd()]

        def add(path_text: str) -> None:
            cleaned = str(path_text or "").strip().strip("`'\".,;:()[]{}")
            if not cleaned:
                return
            raw = Path(cleaned)
            paths = [raw] if raw.is_absolute() else [base / raw for base in bases]
            for path in paths:
                try:
                    resolved = path.resolve()
                except OSError:
                    resolved = path
                key = str(resolved)
                if key in seen:
                    continue
                seen.add(key)
                candidates.append(resolved)

        for text in texts:
            source = str(text or "")
            for match in re.finditer(r"((?:/|[A-Za-z0-9_.+\-]+/)[^\s`'\"<>|]*stage_status\.tsv)", source):
                add(match.group(1))
            for line in source.splitlines():
                if not re.search(r"\b(output\s+dir(?:ectory)?|输出目录)\b", line, re.IGNORECASE):
                    continue
                for match in re.finditer(r"((?:/|[A-Za-z0-9_.+\-]+/)[^\s`'\"<>|]+)", line):
                    token = match.group(1).strip("`'\".,;:()[]{}")
                    if token:
                        add(str(Path(token) / "stage_status.tsv"))
        return candidates

    def _sync_plan_tracker_from_stage_status(
        self,
        task_id: str,
        state: Dict[str, Any],
        *texts: str,
    ) -> bool:
        evidence_text = json.dumps(state, ensure_ascii=False)[:20000]
        changed = 0
        for path in self._stage_status_candidates_from_text(*texts, evidence_text):
            changed += sync_plan_state_from_stage_status(
                state,
                path,
                evidence=f"terminal stage_status.tsv observed at {path}",
            )
        if changed:
            self._persist_plan_tracker(task_id, state)
            return True
        return False

    def _reconcile_completion_candidate_plan(
        self,
        task_id: str,
        state: Dict[str, Any],
    ) -> Tuple[bool, str]:
        """Reconcile a final claim from formal status evidence without trusting Generate."""
        plan_state = load_plan_state(self.data_path, task_id)
        candidate = state.get("completion_candidate") if isinstance(state.get("completion_candidate"), dict) else {}
        canonical_task_spec = canonical_task_spec_for_state(plan_state)
        changed = self._sync_plan_tracker_from_stage_status(
            task_id,
            plan_state,
            str(state.get("current_plan") or ""),
            str(candidate.get("text") or ""),
            json.dumps(canonical_task_spec, ensure_ascii=False),
        )
        return changed, render_plan_progress(load_plan_state(self.data_path, task_id))

    def _start_or_load_plan_progress(self, task_id: str, current_plan: Optional[str], evidence: str = "") -> str:
        state = self._ensure_plan_tracker(task_id, current_plan)
        if state.get("steps"):
            mark_first_pending_running(state, evidence=evidence or "generate_started")
            return self._persist_plan_tracker(task_id, state)
        return render_plan_progress(state)

    def _mark_plan_current_done(self, task_id: str, evidence: str, *, source_node: str = "controller") -> str:
        state = load_plan_state(self.data_path, task_id)
        if state.get("steps"):
            advance_plan_after_verified_step(state, str(evidence or "controller_verified"))
            return self._persist_plan_tracker(task_id, state)
        return render_plan_progress(state)

    def _validate_and_advance_step_candidate(
        self,
        task_id: str,
        candidate: Dict[str, Any],
        *,
        source_node: str = "controller",
    ) -> Tuple[bool, Any, str]:
        """Let CompletionGate validate a Generate claim, then advance in Controller."""
        plan_state = load_plan_state(self.data_path, task_id)
        records = RecoveryStateStore(self.data_path, task_id).load_execution_records()
        gate = CompletionGate.validate_step_completion_candidate(
            self.data_path,
            task_id,
            plan_state,
            candidate,
            records,
        )
        if not gate.passed:
            return False, gate, render_plan_progress(plan_state)

        record = dict((gate.reconciliation or {}).get("record") or {})
        step_id = str(candidate.get("step_id") or "")
        attached = attach_execution_evidence_relation(
            plan_state,
            step_id,
            record,
            reason=str(candidate.get("reason") or ""),
        )
        completion_reason = (
            "controller_verified_step_completion_candidate: "
            + ", ".join(str(item) for item in candidate.get("evidence_ids", []) or [])
        )
        _, current_step = current_plan_step_with_index(plan_state)
        if not attached or str((current_step or {}).get("step_id") or "") != step_id:
            gate.passed = False
            gate.message = "Controller could not apply the verified step transition."
            gate.feedback = "The current step changed while its completion candidate was being validated. Regenerate for the new step."
            gate.classification = "step_candidate_transition_stale"
            return False, gate, render_plan_progress(plan_state)
        attempt_id = str(record.get("attempt_id") or record.get("execution_id") or "")
        attempt = dict(((plan_state.get("provenance_state") or {}).get("attempts") or {}).get(attempt_id) or {})
        if str(attempt.get("status") or "").upper() == ATTEMPT_EVIDENCE_COMMITTED:
            record_provenance_event(plan_state, "attempt_state_changed", {
                "attempt_id": attempt_id,
                "status": ATTEMPT_VALIDATION_PASSED,
                "validation_evidence_ref": str((gate.reconciliation or {}).get("validation_id") or "completion_gate"),
            })
            attempt["status"] = ATTEMPT_VALIDATION_PASSED
        if str(attempt.get("status") or "").upper() in {
            ATTEMPT_VALIDATED,
            ATTEMPT_VALIDATION_PASSED,
        }:
            record_provenance_event(plan_state, "attempt_state_changed", {
                "attempt_id": attempt_id,
                "status": ATTEMPT_COMPLETED,
            })
        advance_plan_after_verified_step(plan_state, completion_reason)
        return True, gate, self._persist_plan_tracker(task_id, plan_state)

    def _advance_satisfied_validation_steps(
        self,
        task_id: str,
        execution_evidence: Dict[str, Any],
        *,
        max_steps: int = 4,
        source_node: str = "controller",
    ) -> Tuple[int, str]:
        """Converge consecutive validation steps already covered by one execution."""
        evidence_id = str(
            execution_evidence.get("execution_id")
            or execution_evidence.get("action_id")
            or execution_evidence.get("attempt_id")
            or ""
        )
        if not evidence_id:
            return 0, render_plan_progress(load_plan_state(self.data_path, task_id))
        advanced = 0
        progress = render_plan_progress(load_plan_state(self.data_path, task_id))
        for _ in range(max_steps):
            plan_state = load_plan_state(self.data_path, task_id)
            _, step = current_plan_step_with_index(plan_state)
            if not step or str(step.get("purpose") or "").strip().lower() != "validation":
                break
            candidate = {
                "step_id": str(step.get("step_id") or ""),
                "reason": "Persisted execution evidence already satisfies this consecutive validation step.",
                "evidence_ids": [evidence_id],
            }
            passed, _, progress = self._validate_and_advance_step_candidate(
                task_id,
                candidate,
                source_node=source_node,
            )
            if not passed:
                break
            advanced += 1
        return advanced, progress

    def _mark_plan_current_blocked(self, task_id: str, evidence: str) -> str:
        return self._finalize_blocked_state(task_id, evidence)

    def _mark_generate_provider_blocked(
        self,
        task_id: str,
        failure: ProviderAttemptFailure,
    ) -> str:
        """Persist a typed provider terminal without entering Recovery."""

        plan_state = load_plan_state(self.data_path, task_id)
        semantic_invocation_id = str(
            failure.record.envelope.semantic_invocation_id
        )
        all_rows = [
            row
            for row in list(
                getattr(self, "_provider_attempt_history", {}).get(task_id, [])
            )
            if str(row.get("semantic_invocation_id") or "")
            == semantic_invocation_id
        ]
        by_attempt_id = {
            str(row.get("attempt_id") or ""): row
            for row in all_rows
            if str(row.get("attempt_id") or "")
        }
        attempt_rows = []
        cursor = str(failure.record.envelope.attempt_id)
        visited = set()
        while cursor and cursor not in visited and cursor in by_attempt_id:
            visited.add(cursor)
            row = by_attempt_id[cursor]
            attempt_rows.append(row)
            cursor = str(row.get("parent_attempt_id") or "")
        attempt_rows.reverse()
        configured_max_attempts = int(
            failure.record.envelope.attempt_ordinal
            + failure.record.envelope.retry_budget_before
        )
        last_attempt_retryable = bool(failure.record.retryable)
        retry_budget_exhausted = bool(
            failure.error_code == GENERATE_PROVIDER_RETRY_EXHAUSTED
            and failure.record.retry_budget_exhausted
            and last_attempt_retryable
            and len(attempt_rows) >= configured_max_attempts
        )
        terminal_failure_reason = (
            "generate_provider_retry_exhausted"
            if retry_budget_exhausted
            else "generate_provider_terminal_request_error"
            if failure.error_code == GENERATE_PROVIDER_TERMINAL_REQUEST_ERROR
            else str(
                failure.record.terminal_failure_reason
                or "generate_provider_terminal_failure"
            )
        )
        task_state = dict(plan_state.get("task_state") or {})
        task_state["pending_action"] = {}
        plan_state["task_state"] = task_state
        plan_state["pending_action"] = {}
        durable_failure = {
            "schema_version": 2,
            "error_code": failure.error_code,
            "owner": "PROVIDER",
            "stage": "GENERATE_PROVIDER",
            "status": "terminal",
            "retryable": False,
            "last_attempt_retryable": last_attempt_retryable,
            "retry_budget_exhausted": retry_budget_exhausted,
            "attempt_count": len(attempt_rows),
            "configured_max_attempts": configured_max_attempts,
            "semantic_invocation_id": semantic_invocation_id,
            "last_attempt_id": str(failure.record.envelope.attempt_id),
            "pending_action": {},
            "generated_action_committed": False,
            "execution_started": False,
            "attempts": [
                {
                    key: row.get(key)
                    for key in (
                        "attempt_id", "attempt_ordinal", "parent_attempt_id",
                        "call_id", "request_hash", "prompt_hash",
                        "model_parameter_hash", "node_context_hash", "state",
                        "failure_type", "normalized_failure_reason",
                        "cleanup_result", "retryable", "retry_delay_seconds",
                        "total_chunk_count", "reasoning_callback_fragment_count",
                        "content_callback_fragment_count", "tool_call_fragment_count",
                        "observed_payload_callback_count", "attempt_completed_at",
                    )
                }
                for row in attempt_rows
            ],
            "last_seen_at": timestamp_now(),
            "terminal_failure_reason": terminal_failure_reason,
            "termination_reason": (
                "generate_provider_attempts_exhausted"
                if retry_budget_exhausted
                else terminal_failure_reason
            ),
        }
        plan_state["failure"] = durable_failure
        save_plan_state(self.data_path, task_id, plan_state)
        reason = (
            f"{failure.error_code}: Generate provider attempts ended without "
            "a complete response; no partial response was executed."
        )
        return self._finalize_blocked_state(task_id, reason)

    @staticmethod
    def _generate_provider_failure_response(
        failure: ProviderAttemptFailure,
        task_id: str,
    ) -> AIMessage:
        return AIMessage(content=(
            f'<provider_failure error_code="{failure.error_code}" '
            'error_owner="PROVIDER" failure_stage="GENERATE_PROVIDER">\n'
            f"Generate could not obtain a complete provider response for task "
            f"{task_id or '-'}. The provider attempt lifecycle was closed or "
            "marked outcome-unknown; no partial output was parsed or executed.\n"
            "</provider_failure>"
        ))

    def _plan_has_pending_after_block(self, task_id: str) -> bool:
        state = load_plan_state(self.data_path, task_id)
        for step in state.get("steps", []) or []:
            if not isinstance(step, dict):
                continue
            if str(step.get("status") or "").strip().lower() == "pending":
                return True
        return False

    def _next_step_after_runtime_block(self, task_id: str) -> str:
        return "finish"

    def _record_plan_current_evidence(self, task_id: str, event: str, detail: str = "") -> str:
        state = load_plan_state(self.data_path, task_id)
        if state.get("steps"):
            record_current_step_evidence(state, event, detail)
            return self._persist_plan_tracker(task_id, state)
        return render_plan_progress(state)

    def _record_generate_action(self, task_id: str, step_id: str) -> None:
        plan_state = load_plan_state(self.data_path, task_id)
        increment_plan_budget(plan_state, "generate_action_count")
        task_state = dict(plan_state.get("task_state") or {})
        budgets = dict(task_state.get("budgets") or {})
        by_step = dict(budgets.get("generate_action_count_by_step") or {})
        by_step[str(step_id or "lightweight")] = int(by_step.get(str(step_id or "lightweight")) or 0) + 1
        budgets["generate_action_count_by_step"] = by_step
        task_state["budgets"] = budgets
        plan_state["task_state"] = task_state
        save_plan_state(self.data_path, task_id, plan_state)

    def _record_action_format_failure(
        self,
        task_id: str,
        step_id: str,
        response_text: str,
        schema_error: Optional[Dict[str, Any]] = None,
    ) -> Tuple[int, int, str, RecoveryDecision]:
        protocol_error = dict(schema_error or {})
        response_hash = hashlib.sha256(
            str(response_text or "").strip().encode("utf-8", errors="replace")
        ).hexdigest()[:20]
        plan_state = load_plan_state(self.data_path, task_id)
        task_state = dict(plan_state.get("task_state") or {})
        budgets = dict(task_state.get("budgets") or {})
        step_key = str(step_id or "lightweight")
        current_count = int((budgets.get("action_format_repair_by_step") or {}).get(step_key) or 0)
        protocol_dir = Path(self.data_path) / "task_outputs" / str(task_id or "default") / "action_protocol"
        prior_duplicate_count = len(list(
            protocol_dir.glob(f"{step_key}.invalid.*.*.{response_hash}.txt")
        )) if protocol_dir.is_dir() else 0
        scoped_budgets = {**budgets, "action_format_repair_count": current_count}
        policy = RecoveryPolicy(max_format_repairs=1)
        decision = policy.decide(
            pre_action_evidence={
                "valid": False,
                "repairable": True,
                "repair_domain": PreActionRepairDomain.REPRESENTATION.value,
                "violations": [
                    str(
                        protocol_error.get("code")
                        or protocol_error.get("error_type")
                        or "unrecognized_action"
                    ),
                    f"invalid_response_hash={response_hash}",
                ],
            },
            action_id=f"generate:{step_key}",
            step_id=step_key,
            attempt_id=f"format-{current_count + 1}:{response_hash}",
            budgets=scoped_budgets,
        )
        decision = contextualize_recovery_decision(
            decision,
            action_id=f"generate:{step_key}",
            step_id=step_key,
            attempt_id=f"format-{current_count + 1}:{response_hash}",
            source_node="generate",
        )
        count = current_count + (1 if decision.consume_budget else 0)
        duplicate_count = prior_duplicate_count + 1
        protocol_dir.mkdir(parents=True, exist_ok=True)
        raw_path = protocol_dir / (
            f"{str(step_id or 'lightweight')}.invalid.{count}.{duplicate_count}.{response_hash}.txt"
        )
        raw_path.write_text(str(response_text or ""), encoding="utf-8")
        diagnosis_path = protocol_dir / (
            f"{str(step_id or 'lightweight')}.invalid.{count}.{duplicate_count}.{response_hash}.json"
        )
        protocol_stage = str(protocol_error.get("stage") or "")
        failure_type = (
            "json_decode_error"
            if protocol_stage == "json_decode"
            else "action_schema_error"
            if protocol_stage == "action_schema"
            else str(
                protocol_error.get("error_type")
                or protocol_error.get("code")
                or "action_schema_error"
            ).lower()
        )
        diagnosis_path.write_text(json.dumps({
            "root_cause": str(
                protocol_error.get("message")
                or protocol_error.get("reason")
                or "Generate returned no recognized action for the approved current step."
            ),
            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
            "failure_type": failure_type,
            "evidence": [
                f"raw_response:{raw_path}",
                f"response_hash:{response_hash}",
                *([json.dumps(protocol_error, ensure_ascii=False, sort_keys=True)] if protocol_error else []),
            ],
            "confidence": 1.0,
            "missing_evidence": [],
            "repair_strategy": self._corrective_action_repair_instruction(),
            "next_action": "ACTION_FORMAT_REPAIR",
            "requires_user_input": False,
            "protocol_error": protocol_error,
            # Compatibility field for readers that have not migrated to protocol_error.
            "schema_error": protocol_error,
        }, ensure_ascii=False, indent=2), encoding="utf-8")
        return count, duplicate_count, response_hash, decision

    def _commit_preaction_policy_decision(
        self,
        task_id: str,
        step_id: str,
        violation: str,
        *,
        attempt_id: str,
        source_node: str = "generate",
    ) -> RecoveryDecision:
        plan_state = load_plan_state(self.data_path, task_id)
        budgets = dict((plan_state.get("task_state") or {}).get("budgets") or {})
        step_key = str(step_id or "task")
        budgets["action_format_repair_count"] = int(
            (budgets.get("action_format_repair_by_step") or {}).get(step_key) or 0
        )
        decision = RecoveryPolicy().decide(
            pre_action_evidence={
                "valid": False,
                "repairable": True,
                "repair_domain": PreActionRepairDomain.REPRESENTATION.value,
                "violations": [str(violation)],
            },
            action_id=f"{source_node}:{step_id or 'task'}",
            step_id=step_id or "task",
            attempt_id=attempt_id,
            budgets=budgets,
        )
        decision = contextualize_recovery_decision(decision, source_node=source_node)
        return decision

    def _managed_preaction_recovery(
        self,
        *,
        task_id: str,
        plan_state: Mapping[str, Any],
        approved_plan_snapshot: Mapping[str, Any],
        step_id: str,
        candidate: Mapping[str, Any],
        candidate_fingerprint: str,
        previous_candidate_fingerprint: str,
        repair_domain: str,
        violations: Sequence[Mapping[str, Any]],
        visible_artifacts: Mapping[str, Mapping[str, Any]],
    ) -> Tuple[RecoveryContext, RecoveryDecision]:
        """Create one bounded, execution-free Generate repair transition."""
        task_state = dict(plan_state.get("task_state") or {})
        budgets = dict(task_state.get("budgets") or {})
        step_key = str(step_id or "task")
        if repair_domain == PreActionRepairDomain.REPRESENTATION.value:
            current_count = int(
                (budgets.get("action_format_repair_by_step") or {}).get(step_key) or 0
            )
        elif repair_domain == PreActionRepairDomain.GENERATED_SEMANTIC.value:
            current_count = int(
                (budgets.get("generate_attempts_by_step") or {}).get(step_key) or 0
            )
        else:
            current_count = 0
        repair_ordinal = current_count + 1
        snapshot_identity = str(
            approved_plan_snapshot.get("plan_snapshot_id")
            or approved_plan_snapshot.get("plan_semantic_hash")
            or ""
        )
        current_step = next(
            (
                dict(item)
                for item in approved_plan_snapshot.get("steps", []) or []
                if isinstance(item, Mapping)
                and str(item.get("step_id") or "") == step_key
            ),
            {},
        )
        context = build_preaction_recovery_context(
            task_id=task_id,
            step_id=step_key,
            approved_plan_snapshot_id=snapshot_identity,
            authoritative_state_hash=str(
                (plan_state.get("current_plan") or {}).get("plan_semantic_hash")
                or plan_state.get("semantic_plan_hash")
                or ""
            ),
            candidate=candidate,
            candidate_fingerprint=candidate_fingerprint,
            violations=violations,
            repair_ordinal=repair_ordinal,
            visible_artifacts=[
                {
                    "artifact_id": str(identity),
                    "direction": str(row.get("direction") or ""),
                    "artifact_kind": str(
                        (row.get("row") or {}).get("object_kind") or ""
                    ),
                    "source_authority": str(row.get("source_authority") or ""),
                    "runtime_available": bool(row.get("runtime_available", True)),
                }
                for identity, row in sorted(visible_artifacts.items())
            ],
            current_step=current_step,
        )
        context.validation["repair_domain"] = repair_domain
        first_owner = str(
            (violations[0] if violations else {}).get("owner")
            or RecoveryFailureOwner.GENERATED_ACTION.value
        ).upper()
        if first_owner == "CONTROLLER_PROJECTION":
            first_owner = RecoveryFailureOwner.INTERNAL_PROTOCOL.value
        scoped_budgets = {
            **budgets,
            "action_format_repair_count": (
                current_count
                if repair_domain == PreActionRepairDomain.REPRESENTATION.value
                else int(budgets.get("action_format_repair_count") or 0)
            ),
            "generated_semantic_repair_count": (
                current_count
                if repair_domain == PreActionRepairDomain.GENERATED_SEMANTIC.value
                else 0
            ),
        }
        decision = RecoveryPolicy(
            max_format_repairs=1,
            max_candidate_repairs=int(
                budgets.get("max_candidate_repairs_per_epoch") or 2
            ),
        ).decide(
            pre_action_evidence={
                "valid": False,
                "repairable": True,
                "repair_domain": repair_domain,
                "failure_owner": first_owner,
                "candidate_fingerprint": candidate_fingerprint,
                "previous_candidate_fingerprint": previous_candidate_fingerprint,
                "violations": [
                    str(item.get("code") or item.get("message") or "")
                    for item in violations
                ] + [
                    f"error_fingerprint={context.error_fingerprint}",
                    f"invalid_response_hash={candidate_fingerprint}",
                ],
            },
            action_id=context.action_id,
            step_id=step_key,
            attempt_id=context.attempt_id,
            budgets=scoped_budgets,
        )
        decision = contextualize_recovery_decision(
            decision,
            action_id=context.action_id,
            step_id=step_key,
            attempt_id=context.attempt_id,
            source_node="generate",
        )
        context.recovery_decision = decision.to_dict()
        return context, decision

    def _knowledge_conflict_root(self, task_id: str) -> Path:
        return Path(self.data_path) / "task_outputs" / str(task_id or "default")

    @staticmethod
    def _knowledge_plan_section_lines(plan_text: str, names: Tuple[str, ...]) -> List[str]:
        lines: List[str] = []
        active = False
        level = 0
        wanted = tuple(name.lower() for name in names)
        for raw in str(plan_text or "").splitlines():
            heading = re.match(r"^\s*(#{2,6})\s+(.+?)\s*$", raw)
            if heading:
                current_level = len(heading.group(1))
                title = heading.group(2).lower()
                if any(name in title for name in wanted):
                    active = True
                    level = current_level
                    continue
                if active and current_level <= level:
                    active = False
            if active and raw.strip():
                lines.append(raw.strip())
        return lines

    def _knowledge_claim_registry(
        self,
        task_id: str,
        state: Optional[Dict[str, Any]] = None,
        plan_state: Optional[Dict[str, Any]] = None,
        extra_claims: Optional[Iterable[Any]] = None,
    ) -> ClaimRegistry:
        """Build the current typed claim view; persisted prose is audit-only."""
        state = state or {}
        registry = ClaimRegistry()

        def register_semantic(
            value: Dict[str, Any],
            source_type: str,
            *,
            scope: str,
            scope_id: str,
            step_ids: Optional[List[str]] = None,
            reliability: float = 0.9,
            confidence: Optional[float] = None,
        ) -> None:
            semantic_key = str(value.get("semantic_key") or value.get("fact_key") or "").strip().lower()
            operator = str(value.get("operator") or "eq").strip().lower()
            semantic_value = value.get("value")
            if not semantic_key or semantic_value in (None, ""):
                return
            semantic_strength = str(value.get("strength") or "required").strip().lower()
            claim_strength = {
                "hard": "hard_constraint",
                "required": "required",
                "conditional": "required",
                "preference": "preferred",
                "advisory": "inference",
                "ambiguous": "inference",
            }.get(semantic_strength, "required")
            proposition = f"{semantic_key} {operator} {json.dumps(semantic_value, ensure_ascii=False, sort_keys=True, default=str)}"
            try:
                claim_confidence = float(
                    confidence if confidence is not None else value.get("confidence", 0.9)
                )
            except (TypeError, ValueError):
                claim_confidence = 0.9
            registry.register_proposition(
                proposition,
                source_type,
                strength=claim_strength,
                scope=scope,
                scope_id=scope_id,
                source_reference=str(value.get("source_ref") or "") or None,
                reliability=reliability,
                confidence=claim_confidence,
                attributes={
                    "semantic_key": semantic_key,
                    "fact_key": semantic_key,
                    "operator": operator,
                    "value": deepcopy(semantic_value),
                    "condition": deepcopy(value.get("condition")),
                    "ambiguity": deepcopy(value.get("ambiguity")),
                    "needs_clarification": bool(value.get("needs_clarification")),
                    "source_text": str(value.get("source_text") or "")[:1000],
                    "provenance": deepcopy(value.get("provenance") or []),
                    "step_ids": list(step_ids or []),
                },
            )

        plan_state = plan_state or load_plan_state(self.data_path, task_id)
        task_spec = ensure_task_spec(
            canonical_task_spec_for_state(plan_state),
            task_id=task_id,
        )
        task_constraints = semantic_constraints_from_task_spec(
            task_spec,
            selected_skill_ids=state.get("selected_skills") or plan_state.get("selected_skill_ids", []),
        )
        for item in task_constraints:
            semantic_key = str(item.get("semantic_key") or "")
            if not (
                semantic_key.startswith("failure_policy.")
                or semantic_key == "forbidden_behavior.runtime_install"
            ):
                continue
            register_semantic(
                item,
                "task_contract",
                scope="task",
                scope_id=str(task_id),
                reliability=0.98,
                confidence=float(item.get("confidence", 0.95)),
            )

        plan_version = str(plan_state.get("plan_version") or "plan_v1")
        task_inputs_by_value = {
            str(
                item.get("canonical_path") or item.get("path")
                or item.get("value") or ""
            ).strip(): "required_input." + canonical_input_role(
                str(item.get("role") or ""),
                str(item.get("canonical_path") or item.get("path") or ""),
            )
            for item in task_spec.get("inputs", []) or []
            if isinstance(item, Mapping)
            and str(item.get("canonical_path") or item.get("path") or item.get("value") or "").strip()
        }
        task_outputs_by_value = {
            str(
                item.get("canonical_path") or item.get("path")
                or item.get("filename") or item.get("value") or ""
            ).strip(): "required_output." + re.sub(
                r"[^a-z0-9]+", "_", str(item.get("role") or "output").lower()
            ).strip("_")
            for item in task_spec.get("output_contracts", []) or []
            if isinstance(item, Mapping)
            and str(item.get("canonical_path") or item.get("path") or item.get("filename") or item.get("value") or "").strip()
        }
        compatibility = dict(plan_state.get("compatibility") or {})
        legacy_plan_semantics = int(
            compatibility.get("source_schema_version")
            or plan_state.get("schema_version")
            or 1
        ) < PLAN_SCHEMA_VERSION

        def plan_binding(value: Any, *, output_binding: bool, step_id: str) -> None:
            text = str(value or "").strip()
            if not text:
                return
            known = task_outputs_by_value if output_binding else task_inputs_by_value
            semantic_key = known.get(text)
            if not semantic_key and not output_binding:
                role = canonical_input_role("", text)
                if role != "input_file":
                    semantic_key = f"required_input.{role}"
            if not semantic_key:
                return
            register_semantic(
                {"semantic_key": semantic_key, "operator": "eq", "value": text, "strength": "required"},
                "plan",
                scope="stage",
                scope_id=step_id or str(task_id),
                step_ids=[step_id] if step_id else [],
                reliability=0.9,
                confidence=0.95,
            )

        for step in plan_state.get("steps", []) or []:
            if not isinstance(step, dict):
                continue
            step_id = str(step.get("step_id") or "")
            for value in step.get("inputs", []) or step.get("input_contracts", []) or []:
                plan_binding(value, output_binding=False, step_id=step_id)
            for value in step.get("outputs", []) or step.get("output_contracts", []) or []:
                plan_binding(value, output_binding=True, step_id=step_id)
            for skill_id in step.get("skill_ids", []) or []:
                skill = str(skill_id or "").strip()
                if skill:
                    register_semantic(
                        {
                            "semantic_key": "required_skill." + re.sub(r"[^a-z0-9]+", "_", skill.lower()).strip("_"),
                            "operator": "eq", "value": skill, "strength": "required",
                        },
                        "plan", scope="stage", scope_id=step_id or str(task_id),
                        step_ids=[step_id] if step_id else [], reliability=0.95, confidence=0.98,
                    )
            for item in step.get("semantic_claims", []) or []:
                if legacy_plan_semantics and isinstance(item, dict):
                    register_semantic(
                        item, "plan", scope="stage", scope_id=step_id or str(task_id),
                        step_ids=[step_id] if step_id else [], reliability=0.9, confidence=0.9,
                    )
            invocation = dict(step.get("renderer_invocation_contract") or {})
            output_arguments = {
                str(item.get("binding_argument") or "").strip()
                for item in invocation.get("bound_outputs", []) or []
                if isinstance(item, dict) and str(item.get("binding_argument") or "").strip()
            }
            for argument, value in dict(invocation.get("arguments") or {}).items():
                # Output bindings are already projected from ``bound_outputs``
                # and the plan output contract.  File extensions must never
                # make an output argument look like an input semantic slot.
                argument_key = re.sub(r"[^a-z0-9]+", "_", str(argument).strip().lower()).strip("_")
                if (
                    str(argument).strip() in output_arguments
                    or argument_key in {"output", "output_dir", "outdir"}
                    or argument_key.startswith("output_")
                ):
                    continue
                semantic_key = task_inputs_by_value.get(str(value or "").strip())
                if not semantic_key:
                    role = canonical_input_role(str(argument), str(value or ""))
                    if role != "input_file":
                        semantic_key = f"required_input.{role}"
                if semantic_key:
                    register_semantic(
                        {"semantic_key": semantic_key, "operator": "eq", "value": value, "strength": "required"},
                        "plan", scope="stage", scope_id=step_id or str(task_id),
                        step_ids=[step_id] if step_id else [], reliability=0.99, confidence=0.99,
                    )
            for item in invocation.get("semantic_claims", []) or []:
                if isinstance(item, dict):
                    register_semantic(
                        item, "plan", scope="stage", scope_id=step_id or str(task_id),
                        step_ids=[step_id] if step_id else [], reliability=0.99, confidence=0.99,
                    )
            required_environment = str(step.get("required_environment") or "").strip()
            if required_environment:
                register_semantic(
                    {"semantic_key": "runtime_constraint.environment", "operator": "eq", "value": required_environment, "strength": "required"},
                    "plan", scope="environment", scope_id=step_id or str(task_id),
                    step_ids=[step_id] if step_id else [], reliability=0.9, confidence=0.9,
                )

        evidence = state.get("execution_evidence") or {}
        if isinstance(evidence, dict):
            command = str(evidence.get("command") or evidence.get("generated_code") or "").strip()
            current_step = self._running_plan_step(plan_state)
            step_id = str(current_step.get("step_id") or "")
            if command:
                registry.register_observation(
                    f"Runtime command: {command[:3000]}",
                    "runtime_argv",
                    strength="observation",
                    scope="command",
                    scope_id=step_id or str(task_id),
                    confidence=0.95,
                    reliability=0.95,
                    evidence_ids=[f"execute:{task_id}"],
                    attributes={"semantic_key": "runtime_constraint.execution_command", "fact_key": "runtime_constraint.execution_command", "operator": "eq", "value": command[:3000], "step_ids": [step_id] if step_id else []},
                )
            if evidence.get("returncode") is not None:
                returncode = str(evidence.get("returncode"))
                registry.register_observation(
                    f"Runtime return code: {returncode}",
                    "runtime_output",
                    strength="observation",
                    scope="command",
                    scope_id=step_id or str(task_id),
                    confidence=0.98,
                    reliability=0.98,
                    evidence_ids=[f"execute:{task_id}"],
                    attributes={"semantic_key": "runtime_constraint.returncode", "fact_key": "runtime_constraint.returncode", "operator": "eq", "value": returncode, "step_ids": [step_id] if step_id else []},
                )
            for item in evidence.get("semantic_claims", []) or []:
                if isinstance(item, dict):
                    register_semantic(
                        item, "runtime_output", scope="command", scope_id=step_id or str(task_id),
                        step_ids=[step_id] if step_id else [], reliability=0.98, confidence=0.98,
                    )

        runtime_status = state.get("runtime_status") or {}
        if isinstance(runtime_status, dict):
            environment = str(runtime_status.get("env") or runtime_status.get("environment") or "").strip()
            if environment:
                register_semantic(
                    {"semantic_key": "runtime_constraint.environment", "operator": "eq", "value": environment, "strength": "required"},
                    "environment_probe", scope="environment", scope_id=str(task_id),
                    reliability=0.95, confidence=0.9,
                )
            for item in runtime_status.get("semantic_claims", []) or []:
                if isinstance(item, dict):
                    register_semantic(
                        item, "environment_probe", scope="environment", scope_id=str(task_id),
                        reliability=0.95, confidence=0.9,
                    )

        for recovery_state in (state.get("pending_recovery_action"), state.get("recovery_decision")):
            if not isinstance(recovery_state, dict):
                continue
            for item in recovery_state.get("semantic_claims", []) or []:
                if isinstance(item, dict):
                    register_semantic(
                        item, "recovery_proposal", scope="stage",
                        scope_id=str(item.get("step_id") or state.get("failed_step_id") or task_id),
                        step_ids=[str(item.get("step_id"))] if item.get("step_id") else [],
                        reliability=0.8, confidence=0.8,
                    )

        for claim in extra_claims or []:
            registry.register(claim)
        return registry

    @staticmethod
    def _load_knowledge_conflicts(root: Path) -> List[KnowledgeConflict]:
        path = root / "conflicts" / "conflicts.jsonl"
        conflicts: List[KnowledgeConflict] = []
        try:
            for line in path.read_text(encoding="utf-8").splitlines():
                if line.strip():
                    conflicts.append(KnowledgeConflict.from_mapping(json.loads(line)))
        except (OSError, json.JSONDecodeError):
            return []
        return conflicts

    def _knowledge_conflict_update(
        self,
        task_id: str,
        state: Optional[Dict[str, Any]] = None,
        *,
        phase: str = "",
        plan_state: Optional[Dict[str, Any]] = None,
        extra_claims: Optional[Iterable[Any]] = None,
    ) -> Dict[str, Any]:
        if not feature_enabled("ENABLE_KNOWLEDGE_CONFLICT_DETECTOR", True):
            return {}
        state = dict(state or {})
        root = self._knowledge_conflict_root(task_id)
        registry = self._knowledge_claim_registry(task_id, state, plan_state, extra_claims)
        attempt = int(state.get("retry_count") or 0)
        conflicts = KnowledgeConflictDetector.detect(registry, attempt=attempt)
        conflicts.extend(KnowledgeConflictDetector.detect_stale_plan(registry, attempt=attempt))
        existing = self._load_knowledge_conflicts(root)
        by_fp: Dict[str, KnowledgeConflict] = {item.fingerprint: item for item in existing}
        new_conflicts: List[KnowledgeConflict] = []
        updated_conflicts: List[KnowledgeConflict] = []
        current_fingerprints = {item.fingerprint for item in conflicts}
        for conflict in conflicts:
            if conflict.fingerprint in by_fp:
                prior = by_fp[conflict.fingerprint]
                # Preserve an unresolved status; repeated detection is not
                # progress. A conflict that was resolved and then reappears is
                # active again and must be audited as new evidence.
                if prior.status in {"resolved", "accepted_exception", "superseded"}:
                    conflict.resolution_id = None
                    new_conflicts.append(conflict)
                else:
                    conflict.status = prior.status
                    conflict.resolution_id = prior.resolution_id
                by_fp[conflict.fingerprint] = conflict
            else:
                by_fp[conflict.fingerprint] = conflict
                new_conflicts.append(conflict)
        # Current detection is authoritative. Keep historical conflicts in the
        # audit log, but stop blocking once the same active claims are no longer
        # judged contradictory (or one side was superseded by newer evidence).
        for fingerprint, prior in by_fp.items():
            if fingerprint in current_fingerprints or prior.status in {"resolved", "accepted_exception", "superseded"}:
                continue
            prior.status = "resolved"
            prior.resolved_at_attempt = attempt
            prior.resolution_id = f"revalidated_{prior.conflict_id}_{attempt}"
            updated_conflicts.append(prior)
        all_conflicts = list(by_fp.values())
        resolutions = [ConflictResolver.resolve(item, registry) for item in all_conflicts if item.status not in {"resolved", "accepted_exception", "superseded"}]
        current_plan_state = plan_state or load_plan_state(self.data_path, task_id)
        stale = set(current_plan_state.get("stale_step_ids", []))
        revalidation = set(current_plan_state.get("revalidation_required_step_ids", []))
        for decision in resolutions:
            if decision.requires_plan_revision:
                stale.update(decision.affected_step_ids)
                revalidation.update(decision.affected_step_ids)
                revalidation.update(decision.affected_downstream_step_ids)
        if stale or revalidation:
            current_plan_state["stale_step_ids"] = sorted(stale)
            current_plan_state["revalidation_required_step_ids"] = sorted(revalidation)
            save_plan_state(self.data_path, task_id, current_plan_state)
        store = KnowledgeConflictStore(root, task_id)
        store.save_registry(registry)
        store.append("conflicts.jsonl", [*new_conflicts, *updated_conflicts])
        if resolutions:
            store.append("conflict_resolutions.jsonl", resolutions)
        store.save_summary(
            conflicts=all_conflicts,
            resolutions=resolutions,
            plan_state=current_plan_state,
            user_hard_constraints=state.get("user_constraints", []),
        )
        blocking = [item for item in all_conflicts if item.blocking]
        claim_set_hash = semantic_claim_set_hash(registry)
        typed_claims = [
            item for item in registry.active_claims()
            if str(item.attributes.get("semantic_key") or item.attributes.get("fact_key") or "").strip()
        ]
        summary = {
            "phase": phase,
            "unresolved_count": len([item for item in all_conflicts if item.status not in {"resolved", "accepted_exception", "superseded"}]),
            "blocking_conflicts": [item.conflict_id for item in blocking],
            "requires_probe": [item.conflict_id for item in all_conflicts if item.status == "needs_probe"],
            "decisions": [item.to_dict() for item in resolutions],
            "active_plan_version": current_plan_state.get("plan_version", "plan_v1"),
            "stale_steps": sorted(stale),
            "revalidation_required_steps": sorted(revalidation),
            "claim_set_hash": claim_set_hash,
            "typed_claim_count": len(typed_claims),
            "hard_claim_count": sum(item.hard for item in typed_claims),
            "preference_claim_count": sum(item.strength == "preferred" for item in typed_claims),
            "ambiguous_claim_count": sum(bool(item.attributes.get("needs_clarification")) for item in typed_claims),
            "progress_events": [
                {
                    "event": "knowledge_conflict_detected",
                    "conflict_id": item.conflict_id,
                    "conflict_type": item.conflict_type,
                    "phase": phase,
                }
                for item in new_conflicts
            ],
        }
        return {
            "knowledge_claims": [item.to_dict() for item in registry.all()],
            "knowledge_conflicts": [item.to_dict() for item in all_conflicts],
            "knowledge_conflict_summary": summary,
            "knowledge_progress_events": summary["progress_events"],
            "knowledge_claim_set_hash": claim_set_hash,
            "canonical_constraint_hash": canonical_constraint_hash(
                canonical_task_spec_for_state(current_plan_state)
            ),
            "conflict_resolution": resolutions[-1].to_dict() if resolutions else {},
            "plan_revision": (
                current_plan_state.get("revision_history", [])[-1]
                if current_plan_state.get("revision_history")
                else {"plan_version": current_plan_state.get("plan_version", "plan_v1"), "status": "initial"}
            ),
            "plan_version": current_plan_state.get("plan_version", "plan_v1"),
            "plan_stale_steps": sorted(stale),
            "plan_revalidation_steps": sorted(revalidation),
        }

    def _knowledge_conflict_execution_guard(self, task_id: str, state: Dict[str, Any]) -> Tuple[str, str]:
        """Return (action, reason); no command is run while a critical conflict is unresolved."""
        if not feature_enabled("ENABLE_KNOWLEDGE_CONFLICT_DETECTOR", True):
            return "allow", ""
        summary = state.get("knowledge_conflict_summary") or {}
        blocking = list(summary.get("blocking_conflicts", [])) if isinstance(summary, dict) else []
        if not blocking:
            plan_state = load_plan_state(self.data_path, task_id)
            current = self._running_plan_step(plan_state)
            stale = {str(item) for item in plan_state.get("stale_step_ids", [])}
            required = {str(item) for item in plan_state.get("revalidation_required_step_ids", [])}
            current_id = str(current.get("step_id") or "")
            if current_id and (current_id in stale or current_id in required):
                return "probe", f"Current plan step {current_id} requires revalidation before execution."
            return "allow", ""
        conflicts = state.get("knowledge_conflicts") or []
        details = []
        user_decision = False
        for item in conflicts:
            if not isinstance(item, dict) or item.get("conflict_id") not in blocking:
                continue
            details.append(f"{item.get('conflict_type')}: {item.get('description')}")
            decision = str((state.get("conflict_resolution") or {}).get("decision") or "")
            user_decision = user_decision or decision == "request_user_decision"
        return ("ask_user" if user_decision else "probe", "Unresolved knowledge conflict prevents execution: " + " | ".join(details[:3]))

    @staticmethod
    def _running_plan_step(state: Dict[str, Any]) -> Dict[str, Any]:
        steps = [step for step in state.get("steps", []) or [] if isinstance(step, dict)]
        cursor = str(state.get("current_step_id") or "")
        if cursor:
            current = next(
                (step for step in steps if str(step.get("step_id") or "") == cursor),
                None,
            )
            if current and str(current.get("status") or "").strip().lower() in {
                "running", "retry_pending", "repairing", "diagnosing", "ready", "pending",
            }:
                return current
        for status in ("running", "retry_pending", "repairing", "diagnosing", "ready", "pending"):
            for step in steps:
                if str(step.get("status") or "").strip().lower() == status:
                    return step
        return {}

    @staticmethod
    def _plan_step_is_activation_only(step: Dict[str, Any]) -> bool:
        title = str(step.get("title") or "")
        lower = title.lower()
        if "activate_batch" not in lower and "action: activate" not in lower:
            return False
        if re.search(r"\b(run|execute|generate|create|write|cluster|marker|annotat|de analysis|report)\b", lower):
            return False
        if any(term in title for term in ("运行", "执行", "生成", "聚类", "注释", "报告", "差异")):
            return False
        return not re.search(r"\.(?:rds|tsv|csv|txt|md|png|pdf|sh|html?)\b", lower)

    @staticmethod
    def _plan_step_action_is(step: Dict[str, Any], action: str) -> bool:
        wanted = str(action or "").strip().lower()
        declared = str(step.get("action") or "").strip().lower()
        if declared:
            return declared == wanted
        title = str(step.get("title") or "").lower()
        return bool(wanted and re.search(rf"\baction:\s*{re.escape(wanted)}\b", title))

    @staticmethod
    def _execution_purpose_completes_step(step: Dict[str, Any], execution_purpose: str) -> bool:
        """Return whether helper evidence is the declared business result."""
        purpose = str(execution_purpose or "analysis").strip().lower()
        declared = str(step.get("purpose") or "").strip().lower()
        if purpose == "record_failure":
            return declared == "record_failure"
        if purpose not in {"probe", "validation"}:
            return True
        return declared in {"probe", "validation"}

    def _record_activate_batch_progress(self, task_id: str, batch_id: str, update_text: str) -> str:
        state = load_plan_state(self.data_path, task_id)
        if not state.get("steps"):
            return render_plan_progress(state)
        if "✅" in str(update_text or ""):
            step = self._running_plan_step(state)
            if self._plan_step_is_activation_only(step):
                mark_plan_step_done(state, evidence=f"activate batch success: {batch_id}")
            else:
                record_current_step_evidence(state, "activate_batch_success", update_text[:1000])
        else:
            record_current_step_evidence(state, "activate_batch_failed", update_text[:1000])
        return self._persist_plan_tracker(task_id, state)

    @staticmethod
    def _current_step_can_emit_final_solution(plan_state: Dict[str, Any]) -> bool:
        running = BioAnalystAgent._running_plan_step(plan_state)
        if not running:
            return True
        unfinished = [
            step for step in plan_state.get("steps", []) or []
            if isinstance(step, dict)
            and str(step.get("status") or "").strip().lower()
            not in {"done", "passed", "blocked", "failed", "skipped", "skipped_upstream_blocked", "cancelled"}
        ]
        title = str(running.get("title") or "").lower()
        if len(unfinished) == 1:
            return True
        return any(term in title for term in ("final", "report", "summary", "solution", "收尾", "报告", "总结"))

    @staticmethod
    def _plan_has_unfinished_steps(plan_state: Dict[str, Any]) -> bool:
        terminal_statuses = {"done", "passed", "blocked", "failed", "skipped", "skipped_upstream_blocked", "cancelled"}
        for step in plan_state.get("steps", []) or []:
            if not isinstance(step, dict):
                continue
            status = str(step.get("status") or "").strip().lower()
            if status not in terminal_statuses:
                return True
        return False

    def _next_step_after_install_result(self, task_id: str) -> str:
        """Continue managed plans after install/register unless all planned work is terminal."""
        try:
            plan_state = load_plan_state(self.data_path, task_id)
        except Exception:
            plan_state = {}
        if plan_state.get("steps") and self._plan_has_unfinished_steps(plan_state):
            return "generate"
        return "finish"

    def _plan_has_blocking_evidence(self, task_id: str) -> bool:
        state = load_plan_state(self.data_path, task_id)
        for step in state.get("steps", []) or []:
            if not isinstance(step, dict):
                continue
            if str(step.get("status") or "").strip().lower() == "blocked":
                return True
            for item in step.get("evidence", []) or []:
                if not isinstance(item, dict):
                    continue
                event = str(item.get("event") or "").strip().lower()
                detail = str(item.get("detail") or "")
                detail_lower = detail.lower()
                if event in {
                    "execute_failed",
                    "runtime_missing_after_execute",
                    "runtime_not_ready",
                    "skill_env_runner_guard",
                    "future_skill_guard",
                    "pre_execution_boundary_gate_failed",
                    "activate_batch_failed",
                }:
                    return True
                if event in {"blocked", "install_failed"}:
                    return True
                if event == "supervisor_verdict" and "ESCALATE" in detail:
                    return True
                if (
                    "blocked:" in detail_lower
                    or "runtime missing" in detail_lower
                    or "command failed" in detail_lower
                    or "failed healthcheck" in detail_lower
                ):
                    return True
        return False

    def _prepare_final_solution_progress(
        self,
        task_id: str,
        solution_text: str,
        current_plan: str,
    ) -> Tuple[bool, str, str, str]:
        plan_state = load_plan_state(self.data_path, task_id)
        if not plan_state.get("steps"):
            return True, render_plan_progress(plan_state), "completed", ""
        self._sync_plan_tracker_from_stage_status(
            task_id,
            plan_state,
            current_plan,
            solution_text,
        )
        plan_state = load_plan_state(self.data_path, task_id)

        terminal_status = self._terminal_status_from_text(solution_text)
        if terminal_status == "blocked":
            if self._plan_has_blocking_evidence(task_id):
                progress = self._mark_plan_current_blocked(
                    task_id,
                    f"final solution blocked: {solution_text[:500]}",
                )
                return True, progress, "blocked", ""
            progress = self._record_plan_current_evidence(
                task_id,
                "final_solution_blocked_without_evidence",
                solution_text[:1000],
            )
            return (
                False,
                progress,
                "blocked",
                "The final solution claims the task is blocked, but no concrete blocking evidence "
                "was recorded in the plan. Continue execution or record the real dependency/command failure.",
            )

        if self._current_step_can_emit_final_solution(plan_state):
            mark_plan_step_done(plan_state, evidence=f"final solution generated: {solution_text[:500]}")
        else:
            record_current_step_evidence(
                plan_state,
                "premature_final_solution",
                solution_text[:1000],
            )
        progress = self._persist_plan_tracker(task_id, plan_state)
        final_state = load_plan_state(self.data_path, task_id)
        final_gate = CompletionGate.validate_final(
            self.data_path,
            task_id,
            final_state,
            current_plan,
            require_execution_evidence=True,
            require_supervisor_evidence=True,
        )
        if final_gate.passed:
            return True, progress, "completed", ""

        reopened_state = load_plan_state(self.data_path, task_id)
        reopen_last_done_step(
            reopened_state,
            f"final_solution_gate_failed: {final_gate.message}",
        )
        progress = self._persist_plan_tracker(task_id, reopened_state)
        return False, progress, "completed", final_gate.feedback

    def _planner_declares_completed_task(self, plan_content: str) -> bool:
        text = str(plan_content or "").lower()
        completion_markers = (
            "already fully complete",
            "task is already complete",
            "task is complete",
            "task status\n**complete**",
            "task status\ncomplete",
            "**complete** - no blocked",
            "all stages have been successfully executed",
            "all output artifacts are verified",
            "all output artifacts are verified and present",
            "all artifacts delivered and validated",
        )
        return any(marker in text for marker in completion_markers)

    def _planner_proposes_gate_workaround(self, plan_content: str) -> bool:
        text = str(plan_content or "").lower()
        gate_markers = (
            "validation gate",
            "completion gate",
            "gate-checked path",
            "gate checked path",
            "satisfy the completion check",
        )
        workaround_markers = (
            "symlink",
            "symbolic link",
            "copy of",
            "cp ",
            "ln -s",
            "accessible at the gate",
            "fix the path accessibility",
        )
        return any(marker in text for marker in gate_markers) and any(marker in text for marker in workaround_markers)

    def _finish_only_plan_from_completed_plan(self, plan_content: str) -> str:
        return (
            "## Section 1: Requirement Analysis\n"
            "The Planner determined that the existing task is already complete: required outputs have been generated, "
            "validated, and documented. No additional filesystem mutation is needed.\n\n"
            "## Section 2: Step-by-Step Execution Plan\n"
            "Step 1: Finalize already completed task\n"
            "  - Tool: BioMind final response\n"
            "  - Execution guidance: Do not execute shell commands or create compatibility copies/symlinks. "
            "Summarize the verified artifacts and any limitations from the existing evidence.\n"
            "  - Input: Existing verified artifacts and reports\n"
            "  - Output: Final completion summary\n"
            "  - Success criteria: The user receives a concise final summary; no extra files are modified.\n"
            "  - Cautions: Never work around validation gates by copying or symlinking artifacts into unrelated directories.\n"
            "  - Risk: LOW - final reporting only.\n\n"
            "## Execution Checklist\n"
            "- [ ] Step 1: Finalize already completed task | Goal: Report verified completion without modifying outputs | Action: FINISH | Done: final answer summarizes verified artifacts and limitations\n\n"
            "## Section 4: Validation Checklist\n"
            "- Use the existing verified outputs and status files. Do not require bigWig files unless the selected skill documents them.\n"
            "- Do not create compatibility copies or symlinks to satisfy an old validation path.\n\n"
            "## Completion Evidence Summary\n"
            "The original Planner response stated that the task was already fully complete and that output artifacts had been verified. "
            "That completion claim is preserved here without copying old artifact-path lists into new validation requirements.\n"
        )

    def _sanitize_completed_planner_plan(self, plan_content: str) -> str:
        if self._planner_declares_completed_task(plan_content):
            return self._finish_only_plan_from_completed_plan(plan_content)
        return plan_content

    def _replace_plan_tracker_with_plan(self, task_id: str, plan_content: str, reason: str = "") -> str:
        plan_file = default_plan_file(self.data_path, task_id)
        plan_file.parent.mkdir(parents=True, exist_ok=True)
        previous = load_plan_state(self.data_path, task_id)
        plan_state = build_plan_state(task_id, plan_content, plan_file=plan_file)
        task_revision = int(previous.get("generated_from_task_revision") or 0)
        bind_plan_to_task_revision(plan_state, task_revision)
        previous_task_spec = canonical_task_spec_for_state(previous)
        if previous_task_spec:
            _bind_current_task_spec_record(plan_state, previous_task_spec)
        plan_state["selected_skill_ids"] = list(previous.get("selected_skill_ids") or [])
        plan_state = carry_forward_plan_lifecycle(previous, plan_state)
        approve_plan_state(plan_state, task_revision)
        if reason and plan_state.get("steps"):
            record_current_step_evidence(plan_state, "plan_replaced", reason)
        save_plan_state(self.data_path, task_id, plan_state)
        plan_file.write_text(
            "# Task Plan\n"
            f"Generated: {datetime.now().isoformat()}\n"
            "Plan Source: sanitized completed-task resume\n\n"
            f"{plan_content}",
            encoding="utf-8",
        )
        update_plan_markdown_status(plan_file, plan_state)
        return render_plan_progress(plan_state)

    def _resume_plan_material(self, task_id: str, current_plan: str) -> str:
        parts = [str(current_plan or "")]
        state = load_plan_state(self.data_path, task_id)
        title = next_action_title(state)
        if title:
            parts.append(title)
        plan_file = str(state.get("plan_file") or "").strip()
        if plan_file:
            try:
                path = Path(plan_file)
                if path.exists() and path.is_file():
                    parts.append(path.read_text(encoding="utf-8")[:12000])
            except OSError:
                pass
        return "\n\n".join(part for part in parts if part and part.strip())

    def _current_plan_step_requests_finish(self, task_id: str) -> bool:
        state = load_plan_state(self.data_path, task_id)
        title = next_action_title(state).lower()
        return "action: finish" in title or "| finish" in title

    def _finish_solution_from_plan(self, current_plan: str) -> str:
        return (
            "Task is complete based on the existing verified outputs and status evidence. "
            "No additional shell commands or compatibility file copies are needed. "
            "The analysis outputs, report, reproducibility script, and stage status should be treated as the deliverables; "
            "any prior validation-gate path mismatch should be handled by the generalized gate logic rather than by duplicating artifacts."
        )

    def _plan_tracker_is_complete(self, task_id: str) -> bool:
        state = load_plan_state(self.data_path, task_id)
        steps = [step for step in state.get("steps", []) or [] if isinstance(step, dict)]
        return bool(steps) and all(str(step.get("status")) in {"done", "passed", "skipped"} for step in steps)

    def _llm_failure_response(self, stage: str, exc: BaseException, task_id: str) -> AIMessage:
        summary = llm_failure_summary(exc, stage, task_id)
        logger.error(summary)
        return AIMessage(content=deterministic_failure_solution(exc, stage, task_id))

    def _trace_skill_versions(self, skill_ids: List[str]) -> Dict[str, str]:
        versions: Dict[str, str] = {}
        skill_manager = getattr(self, "skill_manager", None)
        if not skill_manager:
            return versions
        for skill_id in [str(item) for item in skill_ids or [] if str(item).strip()]:
            try:
                meta = dict(skill_manager.get_skill_meta(skill_id) or {})
            except Exception:
                continue
            declared = str(meta.get("version") or meta.get("skill_version") or "").strip()
            if declared:
                versions[skill_id] = declared
                continue
            source = Path(str(meta.get("_skill_file") or meta.get("skill_file") or ""))
            if source.is_file():
                try:
                    versions[skill_id] = f"sha256:{hashlib.sha256(source.read_bytes()).hexdigest()}"
                except OSError:
                    pass
        return versions

    @staticmethod
    def _assert_v2_llm_messages_clean(messages: List[BaseMessage]) -> None:
        """Fail before dispatch when a V2 prompt leaks control-plane identity."""
        text = "\n".join(str(getattr(message, "content", message) or "") for message in messages)
        forbidden_patterns = (
            r"\b(?:object|audit|evidence):sha256:[0-9a-f]{16,}\b",
            r"\bsha256:[0-9a-f]{32,}\b",
            r'(?i)["\'](?:task|plan)_(?:semantic|record)_hash["\']\s*:',
            r'(?i)["\']state_generation["\']\s*:',
            r'(?i)["\'](?:approval_ref|cas_token|node_context_hash|projection_semantic_hash)["\']\s*:',
        )
        matched = [pattern for pattern in forbidden_patterns if re.search(pattern, text)]
        if matched:
            raise ValueError(
                "LLM_CONTROL_METADATA_LEAK: V2 message contains prohibited control-plane metadata"
            )

    async def _ainvoke_node_llm(
        self,
        messages: List[BaseMessage],
        *,
        node_context: NodeContext,
        stage: str,
        task_id: str,
        task_mode: str = "",
        trace_metadata: Optional[Dict[str, Any]] = None,
        temperature: Optional[float] = None,
        llm_override: Any = None,
        llm_policy: Optional[Mapping[str, Any]] = None,
    ) -> BaseMessage:
        """Dispatch one immutable ControllerBinding and consume it exactly once."""
        self._assert_v2_llm_messages_clean(messages)
        binding = node_context.binding
        self._node_invocations.register(binding)
        report = payload_observability_report(
            node_context.llm_payload.to_provider_dict()
        )
        logger.info(
            "NodeContext V2 dispatch: task=%s node=%s invocation=%s payload=%s",
            task_id,
            binding.node_type,
            binding.invocation_id,
            json.dumps(report, ensure_ascii=False, sort_keys=True),
        )
        metadata = dict(trace_metadata or {})
        projection_trace = (
            node_context.projection_trace.to_dict()
            if node_context.projection_trace is not None
            else {}
        )
        node_context_hash = str(projection_trace.get("node_context_hash") or "")
        if not node_context_hash:
            node_context_hash = "sha256:" + hashlib.sha256(
                json.dumps(
                    {
                        "binding": binding.to_dict(),
                        "payload": node_context.llm_payload.to_provider_dict(),
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                    default=str,
                ).encode("utf-8")
            ).hexdigest()
        semantic_invocation_id = "semantic-invocation-" + hashlib.sha256(
            json.dumps(
                {
                    "task_id": task_id,
                    "node": binding.node_type,
                    "step_id": binding.step_id,
                    "node_context_hash": node_context_hash,
                },
                ensure_ascii=False,
                sort_keys=True,
            ).encode("utf-8")
        ).hexdigest()[:24]
        metadata.update({
            "node_context_schema_version": 2,
            "controller_binding": binding.to_dict(),
            "projection_trace": projection_trace,
            "node_context_hash": node_context_hash,
            "semantic_invocation_id": semantic_invocation_id,
            "llm_payload_observability": report,
        })

        def retry_context_is_current() -> bool:
            if stage != "generate" or not task_id or not getattr(self, "data_path", ""):
                return True
            current_plan = load_plan_state(self.data_path, task_id)
            _, current_step = current_plan_step_with_index(current_plan)
            return (
                int(current_plan.get("state_generation") or 0)
                == int(binding.state_generation or 0)
                and str((current_step or {}).get("step_id") or "")
                == str(binding.step_id or "")
            )
        try:
            response = await self._ainvoke_llm(
                messages,
                stage=stage,
                task_id=task_id,
                task_mode=task_mode,
                trace_metadata=metadata,
                temperature=temperature,
                llm_override=llm_override,
                llm_policy=llm_policy,
                retry_guard=retry_context_is_current,
            )
        except BaseException:
            try:
                self._node_invocations.terminate(binding.invocation_id, status="failed")
            except InvocationProtocolError:
                pass
            raise
        self._node_invocations.consume(binding.invocation_id)
        return response

    async def _ainvoke_llm(
        self,
        messages: List[BaseMessage],
        *,
        stage: str,
        task_id: str = "",
        task_mode: str = "",
        trace_metadata: Optional[Dict[str, Any]] = None,
        temperature: Optional[float] = None,
        llm_override: Any = None,
        llm_policy: Optional[Mapping[str, Any]] = None,
        retry_guard: Optional[Callable[[], bool]] = None,
    ) -> BaseMessage:
        """Dispatch one semantic invocation through bounded provider attempts."""
        mode = str(task_mode or "").strip().lower()
        legacy_timeout = (
            self.llm_readonly_timeout_seconds
            if mode in {"readonly", "simple_execute"}
            else self.llm_timeout_seconds
        )
        prompt_chars = sum(
            len(str(getattr(message, "content", message) or ""))
            for message in messages
        )
        trace_metadata = dict(trace_metadata or {})
        provider_policy = dict(llm_policy or {})
        sdk_max_retries = int(
            provider_policy.get(
                "sdk_max_retries",
                getattr(
                    self,
                    "generate_llm_sdk_max_retries" if stage == "generate" else "llm_max_retries",
                    0,
                ),
            )
        )
        if stage == "generate" and sdk_max_retries != 0:
            raise RuntimeError("GENERATE_SDK_RETRY_POLICY_VIOLATION")
        thinking_enabled = bool(provider_policy.get("thinking_enabled"))
        effective_temperature = effective_llm_temperature(
            is_deepseek=bool(
                getattr(self, "llm_provider_is_deepseek", False)
            ),
            thinking_enabled=thinking_enabled,
            requested_temperature=temperature,
            stage=stage,
        )
        if temperature is not None:
            trace_metadata.setdefault("requested_temperature", float(temperature))
        trace_metadata["effective_temperature"] = effective_temperature
        trace_metadata["temperature"] = effective_temperature
        if provider_policy:
            trace_metadata["llm_provider_policy"] = provider_policy
        prompt_telemetry = build_prompt_budget_telemetry(
            messages,
            component_chars=trace_metadata.get("component_chars") or {},
            context_limit_tokens=getattr(self, "llm_context_limit_tokens", 200_000),
        )
        started = time.monotonic()
        logger.info(
            "LLM request started: stage=%s task=%s messages=%s chars=%s timeout=%ss",
            stage,
            task_id or "-",
            len(messages),
            prompt_chars,
            legacy_timeout,
        )
        logger.info(
            "LLM prompt budget: stage=%s task=%s %s",
            stage,
            task_id or "-",
            json.dumps(prompt_telemetry, ensure_ascii=False, sort_keys=True),
        )
        if prompt_telemetry["warning"]:
            logger.warning(
                "LLM prompt budget warning: stage=%s task=%s estimated_tokens=%s headroom=%s duplicates=%s",
                stage,
                task_id or "-",
                prompt_telemetry["estimated_input_tokens"],
                prompt_telemetry["remaining_headroom_tokens"],
                prompt_telemetry["duplicate_chars"],
            )
        trace_data_path = str(getattr(self, "data_path", "") or "")
        trace_store = ContextLineageStore(trace_data_path, task_id) if task_id and trace_data_path else None
        invocation_llm = llm_override or self.llm
        if effective_temperature is not None and hasattr(invocation_llm, "bind"):
            invocation_llm = invocation_llm.bind(
                temperature=float(effective_temperature)
            )

        total_timeout = min(
            float(legacy_timeout),
            float(getattr(self, "llm_total_timeout_seconds", legacy_timeout)),
        )
        if stage == "generate":
            timeout_policy = ProviderTimeoutPolicy(
                first_chunk_seconds=float(
                    getattr(self, "llm_first_chunk_timeout_seconds", total_timeout)
                ),
                idle_seconds=float(
                    getattr(self, "llm_stream_idle_timeout_seconds", total_timeout)
                ),
                total_seconds=total_timeout,
                cleanup_seconds=float(
                    getattr(self, "llm_cancel_cleanup_timeout_seconds", min(5.0, total_timeout))
                ),
            ).normalized()
            max_attempts = min(
                2,
                max(1, int(getattr(self, "generate_provider_max_attempts", 2))),
            )
        else:
            # Phase splitting and the controller retry budget are intentionally
            # scoped to Generate. Other nodes retain one hard total deadline.
            timeout_policy = ProviderTimeoutPolicy(
                first_chunk_seconds=total_timeout,
                idle_seconds=total_timeout,
                total_seconds=total_timeout,
                cleanup_seconds=float(
                    getattr(self, "llm_cancel_cleanup_timeout_seconds", min(5.0, total_timeout))
                ),
            ).normalized()
            max_attempts = 1

        semantic_payload = {
            "stage": stage,
            "task_id": task_id,
            "step_id": str(trace_metadata.get("step_id") or ""),
            "messages": [
                {
                    "role": type(message).__name__,
                    "content_sha256": hashlib.sha256(
                        str(getattr(message, "content", message) or "").encode(
                            "utf-8", errors="replace"
                        )
                    ).hexdigest(),
                }
                for message in messages
            ],
        }
        prompt_hash = hashlib.sha256(
            json.dumps(
                semantic_payload["messages"],
                ensure_ascii=False,
                sort_keys=True,
            ).encode("utf-8")
        ).hexdigest()
        model_parameter_hash = hashlib.sha256(
            json.dumps(
                {
                    "model": str(getattr(self, "llm_model_id", "") or "unknown"),
                    "temperature": effective_temperature,
                    "provider_policy": provider_policy,
                    "sdk_max_retries": sdk_max_retries,
                },
                ensure_ascii=False,
                sort_keys=True,
                default=str,
            ).encode("utf-8")
        ).hexdigest()
        semantic_invocation_id = str(
            trace_metadata.get("semantic_invocation_id")
            or "semantic-invocation-"
            + hashlib.sha256(
                json.dumps(
                    semantic_payload,
                    ensure_ascii=False,
                    sort_keys=True,
                ).encode("utf-8")
            ).hexdigest()[:24]
        )
        parent_attempt_id = ""
        latest_error: Optional[ProviderAttemptFailure] = None
        history = getattr(self, "_provider_attempt_history", None)
        if history is None:
            self._provider_attempt_history = {}
            history = self._provider_attempt_history

        def supports_config(llm: Any) -> bool:
            try:
                signature = inspect.signature(llm.ainvoke)
            except (TypeError, ValueError):
                return True
            return "config" in signature.parameters or any(
                parameter.kind is inspect.Parameter.VAR_KEYWORD
                for parameter in signature.parameters.values()
            )

        def record_ref(snapshot: Mapping[str, Any]) -> None:
            if not snapshot or not task_id:
                return
            refs = getattr(self, "_latest_llm_call_refs", None)
            if refs is None:
                self._latest_llm_call_refs = {}
                refs = self._latest_llm_call_refs
            refs.setdefault(task_id, []).append({
                key: snapshot.get(key)
                for key in (
                    "call_id", "snapshot_ref", "request_hash", "response_hash",
                    "task_revision", "plan_revision", "step_id", "attempt_id", "call_kind",
                )
            })
            refs[task_id] = refs[task_id][-50:]

        def progress(event: str, payload: Mapping[str, Any]) -> None:
            if stage != "generate":
                return
            attempt_id = str(payload.get("attempt_id") or "")
            attempt_ordinal = int(payload.get("attempt_ordinal") or 0)
            messages_by_event = {
                "attempt_started": f"⏳ Generate provider attempt {attempt_ordinal}/{max_attempts} started.",
                "stream_active": f"📡 Generate provider stream active (attempt {attempt_ordinal}).",
                "timeout_cleanup_started": f"⏱️ Generate provider timeout; cleaning attempt {attempt_ordinal}.",
            }
            if event in messages_by_event:
                output.print_once(
                    f"provider:{event}:{attempt_id}",
                    messages_by_event[event],
                    Fore.CYAN,
                )

        try:
            for attempt_ordinal in range(1, max_attempts + 1):
                attempt_id = (
                    f"provider-attempt-{semantic_invocation_id[-12:]}-"
                    f"{attempt_ordinal}-{uuid.uuid4().hex[:8]}"
                )
                metadata = dict(trace_metadata or {})
                metadata["prompt_budget_telemetry"] = prompt_telemetry
                call_kind = str(metadata.get("call_kind") or {
                    "planner": "planner_initial",
                    "planner_repair": "planner_repair",
                }.get(stage, stage))
                plan_state = load_plan_state(self.data_path, task_id) if trace_store else {}
                _, current_step = current_plan_step_with_index(plan_state)
                current_step = current_step or {}
                metadata.setdefault("node_name", stage)
                metadata.setdefault("call_kind", call_kind)
                metadata.setdefault("task_revision", plan_state.get("generated_from_task_revision"))
                metadata.setdefault("task_spec_revision", metadata.get("task_revision"))
                metadata.setdefault("plan_revision", plan_state.get("plan_revision"))
                metadata.setdefault("step_id", current_step.get("step_id"))
                metadata.setdefault("stage_id", (current_step.get("renderer_execution") or {}).get("current_stage_id"))
                metadata.setdefault("action_id", (current_step.get("renderer_execution") or {}).get("current_action_id"))
                metadata.setdefault("selected_skill_ids", current_step.get("skill_ids") or [])
                metadata.setdefault(
                    "skill_versions",
                    self._trace_skill_versions(list(metadata.get("selected_skill_ids") or [])),
                )
                metadata["semantic_invocation_id"] = semantic_invocation_id
                metadata["attempt_id"] = attempt_id
                metadata["attempt_ordinal"] = attempt_ordinal
                metadata["parent_attempt_id"] = parent_attempt_id
                metadata["node_context_hash"] = str(metadata.get("node_context_hash") or "")
                metadata["provider_timeout_policy"] = timeout_policy.to_dict()
                metadata["retry_budget_before"] = max_attempts - attempt_ordinal
                metadata["retry_budget_after"] = max(
                    0,
                    max_attempts - attempt_ordinal - 1,
                )
                metadata["sdk_max_retries"] = sdk_max_retries
                metadata["prompt_hash"] = prompt_hash
                metadata["model_parameter_hash"] = model_parameter_hash
                base_call_id = str(metadata.pop("call_id", "") or "")
                if base_call_id:
                    metadata["call_id"] = f"{base_call_id}-attempt-{attempt_ordinal}"
                elif trace_store:
                    ordinal = len(trace_store.list_snapshots()) + 1
                    identity = json.dumps({
                        "task": task_id,
                        "kind": call_kind,
                        "ordinal": ordinal,
                        "step": metadata.get("step_id"),
                        "attempt": attempt_id,
                    }, ensure_ascii=False, sort_keys=True)
                    metadata["call_id"] = (
                        f"{call_kind}-{ordinal:04d}-"
                        f"{hashlib.sha256(identity.encode('utf-8')).hexdigest()[:12]}"
                    )
                snapshot: Dict[str, Any] = (
                    trace_store.start_call(messages, metadata) if trace_store else {}
                )
                call_id = str(snapshot.get("call_id") or metadata.get("call_id") or attempt_id)
                request_hash = str(
                    snapshot.get("request_hash")
                    or hashlib.sha256(
                        json.dumps(
                            semantic_payload,
                            ensure_ascii=False,
                            sort_keys=True,
                        ).encode("utf-8")
                    ).hexdigest()
                )
                envelope = ProviderAttemptEnvelope(
                    node_name=stage,
                    step_id=str(metadata.get("step_id") or ""),
                    semantic_invocation_id=semantic_invocation_id,
                    attempt_id=attempt_id,
                    attempt_ordinal=attempt_ordinal,
                    parent_attempt_id=parent_attempt_id,
                    call_id=call_id,
                    node_context_hash=str(metadata.get("node_context_hash") or ""),
                    request_hash=request_hash,
                    provider=str(getattr(self, "llm_provider_id", "") or "unknown"),
                    model=str(getattr(self, "llm_model_id", "") or "unknown"),
                    thinking_policy=provider_policy,
                    timeout_policy=timeout_policy,
                    retry_budget_before=max_attempts - attempt_ordinal,
                    retry_budget_after=max(0, max_attempts - attempt_ordinal - 1),
                    sdk_max_retries=sdk_max_retries,
                    prompt_hash=prompt_hash,
                    model_parameter_hash=model_parameter_hash,
                )

                async def invoke(observer: ProviderStreamObserver) -> Any:
                    config = {
                        "callbacks": [observer],
                        "tags": ["provider-attempt", stage],
                        "metadata": {
                            "provider_attempt_id": attempt_id,
                            "semantic_invocation_id": semantic_invocation_id,
                        },
                    }
                    if supports_config(invocation_llm):
                        return await invocation_llm.ainvoke(messages, config=config)
                    return await invocation_llm.ainvoke(messages)

                try:
                    response, attempt_record = await run_provider_attempt(
                        invoke,
                        envelope,
                        progress_callback=progress,
                    )
                    if stage == "generate" and not response_has_final_content(response):
                        attempt_record.failure_type = EMPTY_FINAL_CONTENT
                        attempt_record.failure_detail = (
                            "provider stream ended normally without final content"
                        )
                        attempt_record.normalized_failure_reason = "empty_final_content"
                        attempt_record.retryable = True
                        attempt_record.state = "FAILED_TRANSIENT"
                        if attempt_record.stream_started:
                            attempt_record.partial_payload_disposition = (
                                "discarded_before_parse"
                            )
                        raise ProviderAttemptFailure(
                            EMPTY_FINAL_CONTENT,
                            attempt_record.failure_detail,
                            record=attempt_record,
                            retryable=True,
                        )
                except ProviderAttemptFailure as exc:
                    attempt_record = exc.record
                    can_retry = (
                        stage == "generate"
                        and exc.retryable
                        and attempt_ordinal < max_attempts
                    )
                    context_current = True
                    if can_retry and retry_guard is not None:
                        try:
                            context_current = bool(retry_guard())
                        except Exception:
                            logger.warning(
                                "Generate retry staleness guard failed closed: task=%s",
                                task_id or "-",
                                exc_info=True,
                            )
                            context_current = False
                    terminal_error: ProviderAttemptFailure = exc
                    if can_retry and not context_current:
                        attempt_record.caused_by = attempt_record.failure_type
                        attempt_record.failure_type = PROVIDER_CANONICAL_CONTEXT_CHANGED
                        attempt_record.retryable = False
                        attempt_record.terminal_failure_reason = (
                            "generate_canonical_context_changed"
                        )
                        terminal_error = ProviderAttemptFailure(
                            PROVIDER_CANONICAL_CONTEXT_CHANGED,
                            "Generate canonical plan context changed before retry dispatch",
                            record=attempt_record,
                            retryable=False,
                        )
                        can_retry = False
                    elif (
                        stage == "generate"
                        and exc.retryable
                        and attempt_ordinal >= max_attempts
                    ):
                        attempt_record.retry_budget_exhausted = True
                        attempt_record.terminal_failure_reason = (
                            "generate_provider_retry_exhausted"
                        )
                        terminal_error = ProviderAttemptFailure(
                            GENERATE_PROVIDER_RETRY_EXHAUSTED,
                            (
                                f"Generate consumed {max_attempts} application attempts; "
                                f"last failure was {attempt_record.failure_type}"
                            ),
                            record=attempt_record,
                            retryable=False,
                        )
                    elif stage == "generate" and not exc.retryable:
                        attempt_record.terminal_failure_reason = (
                            "generate_provider_terminal_request_error"
                            if exc.error_code
                            == GENERATE_PROVIDER_TERMINAL_REQUEST_ERROR
                            else "generate_provider_terminal_failure"
                        )

                    if can_retry:
                        jitter_source = getattr(
                            self,
                            "_provider_retry_random",
                            random.random,
                        )
                        try:
                            jitter_sample = float(jitter_source())
                        except Exception:
                            jitter_sample = 1.0
                        attempt_record.retry_delay_seconds = provider_retry_delay_seconds(
                            attempt_record,
                            attempt_ordinal=attempt_ordinal,
                            jitter_sample=jitter_sample,
                            base_seconds=float(
                                getattr(
                                    self,
                                    "generate_provider_retry_base_seconds",
                                    0.5,
                                )
                            ),
                            cap_seconds=float(
                                getattr(
                                    self,
                                    "generate_provider_retry_cap_seconds",
                                    8.0,
                                )
                            ),
                        )

                    latest_error = terminal_error
                    history.setdefault(task_id or "-", []).append(attempt_record.to_dict())
                    history[task_id or "-"] = history[task_id or "-"][-20:]
                    if trace_store and snapshot:
                        try:
                            if attempt_record.observed_payload_callback_count:
                                diagnostic_ref = persist_partial_response_diagnostic(
                                    Path(str(snapshot["snapshot_ref"])).parent
                                    / "partial_response_diagnostic.json",
                                    attempt_record,
                                )
                            else:
                                diagnostic_ref = None
                            snapshot = trace_store.fail_call(
                                snapshot["call_id"], terminal_error
                            )
                            snapshot = trace_store.annotate_call(snapshot["call_id"], {
                                "provider_attempt": attempt_record.to_dict(),
                                "partial_response_diagnostic_ref": str(diagnostic_ref or ""),
                            })
                            record_ref(snapshot)
                        except Exception as trace_exc:  # noqa: BLE001 - preserve provider failure.
                            logger.warning(
                                "Failed to persist LLM failure snapshot %s: %s",
                                snapshot.get("call_id"),
                                trace_exc,
                            )

                    if can_retry:
                        output.print_once(
                            f"provider:retry:{attempt_id}",
                            f"🔁 Retrying the same Generate request once after {exc.error_code}.",
                            Fore.YELLOW,
                        )
                        sleeper = getattr(
                            self,
                            "_provider_retry_sleep",
                            asyncio.sleep,
                        )
                        await sleeper(float(attempt_record.retry_delay_seconds or 0.0))
                        parent_attempt_id = attempt_id
                        continue
                    if (
                        stage != "generate"
                        and exc.__cause__ is not None
                        and not isinstance(exc.__cause__, asyncio.CancelledError)
                    ):
                        # Other nodes keep their established outward SDK/HTTP
                        # exception contract. They gain attempt telemetry and
                        # cleanup, but no new controller business retry policy.
                        raise exc.__cause__
                    if terminal_error is not exc:
                        raise terminal_error from exc
                    raise
                else:
                    history.setdefault(task_id or "-", []).append(attempt_record.to_dict())
                    history[task_id or "-"] = history[task_id or "-"][-20:]
                    if trace_store and snapshot:
                        try:
                            snapshot = trace_store.finish_call(snapshot["call_id"], response)
                            snapshot = trace_store.annotate_call(snapshot["call_id"], {
                                "provider_attempt": attempt_record.to_dict(),
                            })
                            record_ref(snapshot)
                        except Exception as trace_exc:
                            logger.warning(
                                "Failed to persist LLM success snapshot %s: %s",
                                snapshot.get("call_id"),
                                trace_exc,
                            )
                    return response
            if latest_error is not None:
                raise latest_error
            raise ProviderAttemptFailure(
                "PROVIDER_SDK_ERROR",
                "provider attempt loop exited without a result",
                record=ProviderAttemptRecord(envelope=envelope),
                retryable=False,
            )
        finally:
            logger.info(
                "LLM request finished: stage=%s task=%s elapsed=%.1fs",
                stage,
                task_id or "-",
                time.monotonic() - started,
            )

    def _lightweight_task_policy(self, task_mode: str) -> str:
        mode = str(task_mode or "").strip().lower()
        if mode == "readonly":
            intent = (
                "The request is read-only. Output exactly one <execute> block with the minimal "
                "inspection command(s) needed to answer it, then stop. Do not modify files, "
                "install tools, start workflows, or perform scientific analysis."
            )
        elif mode == "simple_execute":
            intent = (
                "The request is a simple execution. Output exactly one <execute> block for the "
                "explicit command or existing script requested by the user, then stop. Do not "
                "install tools, expand it into a workflow, or perform scientific review."
            )
        else:
            return ""
        return (
            f'<lightweight_task_policy mode="{mode}">\n'
            f"- {intent}\n"
            "- If the request turns out to require installation, multiple analysis steps, output validation, "
            "or unclear parameters, do not improvise a workflow; ask the user or finish with a concise "
            "explanation that this needs managed mode.\n"
            "- Allowed actions: <execute> for one lightweight command, <ask_user> for one missing detail, "
            "or <solution> for a direct non-execution answer.\n"
            "- Disallowed actions: <search>, <install_tool>, <activate_batch>, workflow planning.\n"
            "</lightweight_task_policy>"
        )

    def _execution_validation_level(self, state: AgentState, code: str) -> str:
        explicit = str(state.get("validation_level") or "").strip().lower()
        if explicit in {"none", "basic", "artifact", "scientific"}:
            return explicit
        if state.get("active_skills") or state.get("selected_skills") or state.get("workflow_id"):
            return "scientific"
        plan_text = str(state.get("current_plan") or state.get("plan_progress") or "").lower()
        code_text = str(code or "").lower()
        analysis_terms = (
            "analysis", "workflow", "pipeline", "qc", "align", "mapping",
            "cluster", "differential", "tad", "variant", "fastqc", "seurat",
        )
        if any(term in plan_text or term in code_text for term in analysis_terms):
            return "artifact"
        return "basic"

    def _validate_execution_result(
        self,
        state: AgentState,
        code: str,
        stdout: str,
        stderr: str,
        returncode: int,
    ) -> tuple:
        level = self._execution_validation_level(state, code)
        if level == "none" or not self.validator:
            return {}, "", level
        validation = self.validator.validate(stdout, stderr, code, returncode)
        status = "failed"
        if validation.get("passed"):
            status = "warning" if validation.get("warnings") else "passed"
        report = self.validator.format_report(validation)
        report = str(report or "").strip()[:1800]
        block = (
            f'\n<validation_result level="{level}" status="{status}">\n'
            f"{report}\n"
            "</validation_result>"
        )
        return validation, block, level

    def _skill_execution_context(self, skill_ids: List[str]) -> str:
        if not self.skill_manager or not skill_ids:
            return ""
        cards = self.skill_manager.get_execution_cards(skill_ids)
        return f"\n[MANDATORY SKILL EXECUTION CARDS]\n{cards}\n" if cards else ""

    def _sync_runtime_registries_at_startup(self):
        if not self.skill_manager:
            return
        try:
            if self.pm:
                self.skill_manager.sync_with_package_manager(self.pm)
            paths = self.skill_manager.runtime_registry_file_candidates(self.pm)
            self.skill_manager.import_runtime_registry_files(paths, package_manager=self.pm)
            if self.pm:
                self.skill_manager.sync_with_package_manager(self.pm)
        except Exception as e:
            logger.warning("Runtime registry startup sync failed: %s", e)

    def _runtime_status_for_task(
        self,
        task_id: str,
        selected_skills: Optional[List[str]] = None,
    ) -> Dict[str, Dict[str, Any]]:
        records = dict(self.runtime_status.get(task_id or "default", {}))
        if selected_skills is None:
            return records
        selected = set(self._selected_skill_ids(selected_skills))
        if not selected:
            return {}
        return {
            key: record
            for key, record in records.items()
            if str(record.get("skill_id") or "") in selected
        }

    def _runtime_cache_key(self, skill_id: str, env: str, mode: str = "") -> str:
        suffix = f"::{mode}" if mode else ""
        return f"{skill_id}::{env}{suffix}"

    def _cache_runtime_status(
        self,
        task_id: str,
        skill_id: str,
        env: str,
        ok: bool,
        detail: str,
        healthcheck: str,
        env_runner: str,
        mode: str = "",
    ):
        if not hasattr(self, "runtime_status") or self.runtime_status is None:
            self.runtime_status = {}
        bucket = self.runtime_status.setdefault(task_id or "default", {})
        bucket[self._runtime_cache_key(skill_id, env, mode)] = {
            "skill_id": skill_id,
            "env": env,
            "mode": mode or "",
            "ok": bool(ok),
            "detail": detail or "",
            "healthcheck": healthcheck or "",
            "env_runner": env_runner or "",
            "checked_at": datetime.now().isoformat(timespec="seconds"),
        }

    @staticmethod
    def _requires_calder_official_r_preflight(code: str) -> bool:
        text = str(code or "").lower()
        if "run_calder_compartments.py" not in text:
            return False
        if "--stats-only" in text or "--calder-mode patched-cli" in text:
            return False
        return "--calder-mode official-r" in text or "--calder-mode auto" in text or "--calder-mode" not in text

    def _mode_healthchecks_for_code(
        self,
        skill_id: str,
        requirements: Dict[str, Any],
        code: str = "",
    ) -> Tuple[str, List[str]]:
        if not self._requires_calder_official_r_preflight(code):
            return "", []
        env = str(requirements.get("env") or requirements.get("default_env") or "").strip()
        checks_by_mode = requirements.get("mode_healthchecks") or {}
        checks = []
        if isinstance(checks_by_mode, dict):
            checks = checks_by_mode.get("official-r") or checks_by_mode.get("official_r") or []
        if isinstance(checks, str):
            checks = [checks]
        checks = [str(item).replace("{env}", env).strip() for item in checks if str(item).strip()]
        if not checks:
            checks = [
                f"conda run -n {env} which Rscript",
                f"conda run -n {env} Rscript --version",
                (
                    f"conda run -n {env} Rscript -e "
                    "\"suppressPackageStartupMessages(library(CALDER)); "
                    "suppressPackageStartupMessages(library(data.table)); cat('OK\\n')\""
                ),
            ]
        return "official-r", checks

    def _verify_skill_mode_runtime(
        self,
        skill_id: str,
        env: str,
        mode: str,
        healthchecks: List[str],
        task_id: str = "default",
        use_cache: bool = True,
    ) -> Tuple[bool, str, str]:
        for index, command in enumerate(healthchecks, start=1):
            cache_mode = f"{mode}:{index}"
            cached = self.runtime_status.get(task_id or "default", {}).get(
                self._runtime_cache_key(skill_id, env, cache_mode)
            )
            if use_cache and cached and cached.get("ok"):
                continue
            ok, detail = self.pm.verify_environment(env_name=env, language="", healthcheck=command)
            self._cache_runtime_status(
                task_id,
                skill_id,
                env,
                ok,
                detail or ("OK" if ok else "Healthcheck failed."),
                command,
                f"conda run -n {env}",
                mode=cache_mode,
            )
            if not ok:
                return False, (
                    f"Mode runtime preflight failed for {skill_id} ({mode}) at `{command}`. "
                    f"{detail or 'Healthcheck failed.'}"
                ), env
        return True, f"Mode runtime preflight passed for {skill_id} ({mode}).", env

    def _verify_conda_env_presence(self, env: str) -> Tuple[bool, str]:
        env_name = str(env or "").strip()
        if not env_name or env_name in {"base", "default"}:
            return True, ""
        if not self.pm or not hasattr(self.pm, "conda_exe"):
            return True, ""
        if hasattr(self.pm, "environment_runtime_available"):
            if self.pm.environment_runtime_available(env_name):
                return True, f"Conda environment `{env_name}` exists."
            if getattr(self.pm, "conda_root", None):
                return False, f"Conda environment `{env_name}` is not available under the configured root."
        command = f"conda run -n {shlex.quote(env_name)} true"
        if hasattr(self.pm, "_command_with_configured_manager"):
            command = self.pm._command_with_configured_manager(command)
        try:
            proc = subprocess.run(command, shell=True, capture_output=True, text=True, timeout=45)
        except Exception as exc:
            return False, f"Conda environment presence check failed for `{env_name}`: {exc}"
        if proc.returncode == 0:
            return True, f"Conda environment `{env_name}` exists."
        detail = "\n".join(part.strip() for part in [proc.stdout, proc.stderr] if part and part.strip()).strip()
        return False, detail or f"Conda environment `{env_name}` is not available."

    def _resolved_runtime_healthcheck(self, healthcheck: str) -> str:
        command = str(healthcheck or "").strip()
        if not command:
            return ""
        if not self.skill_manager:
            return command
        if not re.search(r"(^|\s)(?:bash\s+|Rscript\s+|python\s+)?skills/", command):
            return command
        repo_root = Path(getattr(self.skill_manager, "skills_root", "") or "").parent
        if not repo_root or not repo_root.exists():
            return command
        resolved = command
        if hasattr(self.pm, "_command_with_configured_manager") and re.match(r"^(conda|mamba)(?:\s|$)", resolved):
            resolved = self.pm._command_with_configured_manager(resolved)
        return f"cd {shlex.quote(str(repo_root))} && {resolved}"

    def _verify_skill_runtime(self, skill_id: str, task_id: str = "default", use_cache: bool = True, code: str = "") -> Tuple[bool, str, str]:
        if not self.skill_manager or not self.pm:
            return True, "", ""
        requirements = self._skill_runtime_requirements(skill_id)
        env = requirements.get("env") or requirements.get("default_env", "")
        if not env:
            return True, "", ""
        mode, mode_healthchecks = self._mode_healthchecks_for_code(skill_id, requirements, code)
        if not self.pm.get_environment(env):
            self.pm.register_environment(
                env_name=env,
                purpose=f"Runtime for skill {skill_id}",
                packages=requirements.get("packages", []),
                skill_id=skill_id,
                notes="Auto-registered from skill runtime metadata before healthcheck.",
                language=requirements.get("language", ""),
                capabilities=requirements.get("capabilities", []),
                healthcheck=self._resolved_runtime_healthcheck(requirements.get("healthcheck", "")),
                status="registered",
            )
        cache_key = self._runtime_cache_key(skill_id, env)
        cached = self.runtime_status.get(task_id or "default", {}).get(cache_key)
        env_ok, env_detail = self._verify_conda_env_presence(env)
        if not env_ok:
            self.skill_manager.record_environment(
                skill_id,
                env=env,
                packages=requirements.get("packages", []),
                install_command=requirements.get("install_command", ""),
                status="broken",
                notes=env_detail,
                language=requirements.get("language", ""),
                capabilities=requirements.get("capabilities", []),
                healthcheck=self._resolved_runtime_healthcheck(requirements.get("healthcheck", "")),
            )
            self._cache_runtime_status(
                task_id,
                skill_id,
                env,
                False,
                env_detail,
                f"conda run -n {env} true",
                requirements.get("env_runner", ""),
            )
            return False, env_detail, env
        if use_cache and cached and cached.get("ok") and not mode_healthchecks:
            return True, str(cached.get("detail") or "Cached runtime healthcheck passed."), env
        if use_cache and cached and cached.get("ok"):
            ok, detail = True, str(cached.get("detail") or "Cached runtime healthcheck passed.")
        else:
            resolved_healthcheck = self._resolved_runtime_healthcheck(requirements.get("healthcheck", ""))
            recent_detail = None
            if use_cache and hasattr(self.pm, "recent_environment_healthcheck"):
                recent_detail = self.pm.recent_environment_healthcheck(env, resolved_healthcheck)
            if recent_detail is not None:
                ok, detail = True, recent_detail
            else:
                ok, detail = self.pm.verify_environment(
                    env_name=env,
                    language=requirements.get("language", ""),
                    healthcheck=resolved_healthcheck,
                )
            status = "verified" if ok else "broken"
            self.skill_manager.record_environment(
                skill_id,
                env=env,
                packages=requirements.get("packages", []),
                install_command=requirements.get("install_command", ""),
                status=status,
                notes=detail or ("Environment healthcheck passed." if ok else "Environment healthcheck failed."),
                language=requirements.get("language", ""),
                capabilities=requirements.get("capabilities", []),
                healthcheck=resolved_healthcheck,
            )
            self._cache_runtime_status(
                task_id,
                skill_id,
                env,
                ok,
                detail or ("OK" if ok else "Healthcheck failed."),
                resolved_healthcheck,
                requirements.get("env_runner", ""),
            )
        if not ok:
            return ok, detail, env
        if mode_healthchecks:
            return self._verify_skill_mode_runtime(
                skill_id,
                env,
                mode,
                mode_healthchecks,
                task_id=task_id,
                use_cache=use_cache,
            )
        return ok, detail, env

    def _consultant_runtime_code_hint(self, skill_id: str) -> str:
        """Return a representative command fragment for mode-specific preflight."""
        sid = str(skill_id or "")
        if sid == "3d-dna/calder2-subcompartment":
            return (
                "conda run -n calder2 python "
                "skills/3d-dna/calder2-subcompartment/scripts/run_calder_compartments.py "
                "--calder-mode official-r"
            )
        return ""

    @staticmethod
    def _brief_runtime_value(value: Any, limit: int = 500) -> str:
        text = str(value or "").replace("\n", " ").strip()
        return text[:limit] if text else "none"

    @staticmethod
    def _verified_runtime_paths(detail: str) -> Dict[str, str]:
        """Extract healthcheck-emitted KEY=/absolute/path bindings.

        Only existing, non-empty paths are retained. This keeps arbitrary
        healthcheck prose from becoming trusted execution configuration.
        """
        resolved: Dict[str, str] = {}
        for raw_line in str(detail or "").splitlines():
            match = re.fullmatch(r"\s*([A-Z][A-Z0-9_]{1,63})=(/[^\r\n]+?)\s*", raw_line)
            if not match:
                continue
            key, raw_path = match.groups()
            path = Path(raw_path).expanduser()
            try:
                valid = path.is_dir() or (path.is_file() and path.stat().st_size > 0)
            except OSError:
                valid = False
            if valid:
                resolved[key] = str(path.resolve())
        return resolved

    def _controlled_runtime_discovery_hints(self, query: str, task_id: str) -> Dict[str, Any]:
        if not self.skill_manager or not hasattr(self.skill_manager, "controlled_rg_hints"):
            return {}
        roots: List[str] = []
        for path in (
            getattr(self.pm, "root_dir", None),
            getattr(self.pm, "source_root", None),
            self.skill_manager.skills_root.parent / "docs",
            self.skill_manager.skills_root.parent / "prompts",
            Path(self.data_path) / "task_outputs" / str(task_id or "default"),
        ):
            if path and Path(path).exists():
                roots.append(str(Path(path)))
        return self.skill_manager.controlled_rg_hints(query, search_roots=roots)

    def _runtime_healthcheck_for_env(self, requirements: Dict[str, Any], env: str) -> str:
        declared_env = str(requirements.get("env") or requirements.get("default_env") or "").strip()
        target_env = str(env or "").strip()
        command = str(requirements.get("healthcheck") or "").strip()
        if command and target_env and declared_env and target_env != declared_env:
            command = command.replace("{env}", target_env)
            command = re.sub(
                rf"(?m)(\bconda\s+run\s+-n\s+){re.escape(declared_env)}(\b)",
                rf"\1{target_env}\2",
                command,
            )
        return self._resolved_runtime_healthcheck(command)

    def _registered_runtime_tools(self, requirements: Dict[str, Any]) -> List[Dict[str, str]]:
        if not self.pm:
            return []
        registry = getattr(self.pm, "registry", {}) or {}
        tools = registry.get("tools") or {}
        wanted = set()
        for item in requirements.get("tools") or []:
            token = str(item or "").strip()
            if token:
                wanted.add(token.lower())
        for item in requirements.get("packages") or []:
            token = re.split(r"[<>=!~\s]", str(item or ""))[0].strip()
            if token:
                wanted.add(token.lower())
        for item in requirements.get("capabilities") or []:
            text = str(item or "").strip()
            if text.lower().startswith("tool:"):
                wanted.add(text.split(":", 1)[1].strip().lower())
        found: List[Dict[str, str]] = []
        for name, info in tools.items():
            lower = str(name or "").lower()
            if wanted and lower not in wanted:
                continue
            found.append({
                "tool": str(name),
                "env": str((info or {}).get("env") or (info or {}).get("env_name") or ""),
                "status": str((info or {}).get("status") or "registered"),
                "shim_path": str((info or {}).get("shim_path") or ""),
            })
        return found

    def _runtime_audit_for_skill(self, skill_id: str, task_id: str) -> Dict[str, Any]:
        requirements = self._skill_runtime_requirements(skill_id)
        declared_env = str(requirements.get("env") or requirements.get("default_env") or "").strip()
        healthcheck = self._runtime_healthcheck_for_env(requirements, declared_env)
        audit: Dict[str, Any] = {
            "skill_id": skill_id,
            "declared_env": declared_env,
            "env_runner": str(requirements.get("env_runner") or ""),
            "declared_healthcheck": healthcheck,
            "tools": list(requirements.get("tools") or []),
            "packages": list(requirements.get("packages") or []),
            "capabilities": list(requirements.get("capabilities") or []),
            "metadata_present": bool(requirements.get("metadata_present", True)),
            "skill_registry": {},
            "package_manager_env": {},
            "registered_tools": [],
            "matching_env_candidate": {},
            "candidate_healthcheck": {},
            "declared_ok": True,
            "declared_detail": "",
            "checked_env": declared_env,
            "decision": "no_runtime_declared",
        }

        def finalize() -> Dict[str, Any]:
            decision = str(audit.get("decision") or "no_runtime_declared")
            declared_ok = bool(audit.get("declared_ok"))
            if decision == "runtime_ready" and declared_ok:
                status = "ready"
                availability_status = "ready"
                reason_code = "RUNTIME_READY"
                install_required = False
                reason = str(audit.get("declared_detail") or "Healthcheck passed.")
            elif decision == "runtime_missing_or_broken":
                status = "missing"
                availability_status = "unavailable"
                reason_code = (
                    "CONFIGURED_ENV_NOT_AVAILABLE"
                    if "not available under the configured root" in str(
                        audit.get("declared_detail") or ""
                    ).lower()
                    else "DECLARED_RUNTIME_MISSING"
                )
                install_required = True
                reason = str(audit.get("declared_detail") or "Declared runtime is missing or broken.")
            elif decision == "no_runtime_declared":
                status = "unknown"
                availability_status = "not_applicable"
                reason_code = "NO_EXECUTABLE_RUNTIME_DECLARED"
                install_required = False
                reason = "Skill runtime metadata is missing; discovery hints require verification."
            else:
                status = "healthcheck_failed" if not declared_ok else "unknown"
                availability_status = "broken" if not declared_ok else "unavailable"
                reason_code = {
                    "alternate_runtime_candidate_verified_needs_user_or_planner_decision": (
                        "DECLARED_RUNTIME_UNAVAILABLE_ALTERNATE_VERIFIED"
                    ),
                    "alternate_runtime_candidate_failed": "ALTERNATE_RUNTIME_BROKEN",
                    "alternate_runtime_candidate_unverified": "ALTERNATE_RUNTIME_UNVERIFIED",
                    "registered_tools_available_but_declared_env_failed": (
                        "DECLARED_RUNTIME_BROKEN_REGISTERED_TOOLS_INSUFFICIENT"
                    ),
                    "declared_runtime_healthcheck_failed": "RUNTIME_HEALTHCHECK_FAILED",
                }.get(decision, "RUNTIME_UNAVAILABLE")
                install_required = False
                reason = str(audit.get("declared_detail") or decision)
            audit.update({
                "skill": skill_id,
                "env": str(audit.get("checked_env") or declared_env),
                "status": status,
                "healthcheck": str(audit.get("declared_healthcheck") or ""),
                "healthcheck_status": "passed" if declared_ok and status == "ready" else ("not_run" if not healthcheck else "failed"),
                "install_required": install_required,
                "reason": reason,
                "reason_code": reason_code,
                "evidence_status": "checked",
                "availability_status": availability_status,
            })
            resolved_paths = self._verified_runtime_paths(
                str(audit.get("declared_detail") or "")
            )
            checked_env = str(audit.get("checked_env") or declared_env).strip()
            conda_root = Path(str(getattr(self.pm, "conda_root", "") or ""))
            if checked_env and str(conda_root) not in {"", "."}:
                env_prefix = conda_root / "envs" / checked_env
                if env_prefix.is_dir():
                    resolved_paths.setdefault(
                        "RESOLVED_ENV_PREFIX",
                        str(env_prefix.resolve()),
                    )
            audit["resolved_runtime_paths"] = resolved_paths
            return audit

        if not declared_env or not requirements.get("metadata_present", True):
            audit["declared_ok"] = False
            audit["discovery_hints"] = self._controlled_runtime_discovery_hints(skill_id, task_id)
            return finalize()

        if self.skill_manager and hasattr(self.skill_manager, "get_runtime_record"):
            try:
                audit["skill_registry"] = dict(self.skill_manager.get_runtime_record(skill_id) or {})
            except Exception as exc:
                audit["skill_registry"] = {"error": str(exc)}
        if self.pm and hasattr(self.pm, "get_environment"):
            try:
                audit["package_manager_env"] = dict(self.pm.get_environment(declared_env) or {})
            except Exception as exc:
                audit["package_manager_env"] = {"error": str(exc)}
        audit["registered_tools"] = self._registered_runtime_tools(requirements)

        code_hint = self._consultant_runtime_code_hint(skill_id)
        ok, detail, checked_env = self._verify_skill_runtime(
            skill_id,
            task_id=task_id,
            use_cache=True,
            code=code_hint,
        )
        audit["declared_ok"] = bool(ok)
        audit["declared_detail"] = detail or ("OK" if ok else "Healthcheck failed.")
        audit["checked_env"] = checked_env or declared_env
        if ok:
            audit["decision"] = "runtime_ready"
            return finalize()

        match = None
        if self.pm and hasattr(self.pm, "find_matching_environment"):
            try:
                match = self.pm.find_matching_environment(requirements)
            except Exception as exc:
                match = {"error": str(exc)}
        if isinstance(match, dict) and match.get("env") and match.get("env") != declared_env:
            record = dict(match.get("record") or {})
            audit["matching_env_candidate"] = {
                "env": str(match.get("env") or ""),
                "match_type": str(match.get("match_type") or ""),
                "matched_packages": list(match.get("matched_packages") or []),
                "matched_capabilities": list(match.get("matched_capabilities") or []),
                "missing_packages": list(match.get("missing_packages") or []),
                "missing_capabilities": list(match.get("missing_capabilities") or []),
                "status": str(record.get("status") or ""),
                "bound_tools": list(record.get("bound_tools") or []),
            }
            candidate_env = str(match.get("env") or "")
            candidate_healthcheck = self._runtime_healthcheck_for_env(requirements, candidate_env)
            if candidate_healthcheck and self.pm and hasattr(self.pm, "verify_environment"):
                cand_ok, cand_detail = self.pm.verify_environment(
                    env_name=candidate_env,
                    language=str(requirements.get("language") or ""),
                    healthcheck=candidate_healthcheck,
                )
                audit["candidate_healthcheck"] = {
                    "ok": bool(cand_ok),
                    "env": candidate_env,
                    "healthcheck": candidate_healthcheck,
                    "detail": cand_detail or ("OK" if cand_ok else "Healthcheck failed."),
                }
                self._cache_runtime_status(
                    task_id,
                    skill_id,
                    candidate_env,
                    bool(cand_ok),
                    cand_detail or ("OK" if cand_ok else "Healthcheck failed."),
                    candidate_healthcheck,
                    str(requirements.get("env_runner") or ""),
                    mode="candidate",
                )
                audit["decision"] = (
                    "alternate_runtime_candidate_verified_needs_user_or_planner_decision"
                    if cand_ok else
                    "alternate_runtime_candidate_failed"
                )
            else:
                audit["candidate_healthcheck"] = {"ok": False, "env": candidate_env, "detail": "not_run"}
                audit["decision"] = "alternate_runtime_candidate_unverified"
        elif audit["registered_tools"]:
            audit["decision"] = "registered_tools_available_but_declared_env_failed"
        else:
            missing_runtime_evidence = bool(re.search(
                r"Environment(?:Name|Location)NotFound|not a conda environment|"
                r"not available under the configured root|"
                r"environment\s+[^\n]{0,120}\s+(?:missing|not found|does not exist)",
                str(audit.get("declared_detail") or ""),
                re.IGNORECASE,
            ))
            audit["decision"] = (
                "runtime_missing_or_broken"
                if missing_runtime_evidence else
                "declared_runtime_healthcheck_failed"
            )
        return finalize()

    def _format_runtime_audit(self, audits: List[Dict[str, Any]]) -> str:
        if not audits:
            return ""
        lines = [
            "[RUNTIME_AUDIT]",
            "- Consultant checked skill runtime declarations, registered environments, registered tool shims, and healthchecks before Planner handoff.",
            "- Do not use bare `which tool` in the current shell as proof that a skill runtime exists. Use declared healthcheck, registered env/shim evidence, or ask/register/install.",
            "- Use the declared env_runner for analysis commands. Never synthesize a Conda prefix from the project or benchmark root; resolve runtime paths inside the verified environment.",
            f"- controller_python: {sys.executable}",
            "- Use controller_python only when an active skill explicitly declares a renderer/helper as a current-Python or controller-side utility.",
        ]
        for audit in audits:
            tools = audit.get("registered_tools") or []
            match = audit.get("matching_env_candidate") or {}
            cand = audit.get("candidate_healthcheck") or {}
            registered_tool_text = ", ".join(
                f"{item.get('tool')}@{item.get('env') or 'unknown'}:{item.get('status') or 'registered'}"
                for item in tools
            ) or "none"
            declared_tools = ",".join(audit.get("tools") or audit.get("packages") or []) or "none"
            lines.extend([
                f"skill: {audit.get('skill', audit.get('skill_id', ''))}",
                f"env: {audit.get('env', audit.get('declared_env', '')) or 'none'}",
                f"declared_env: {audit.get('declared_env', '') or 'none'}",
                f"env_runner: {audit.get('env_runner', '') or 'none'}",
                f"tools: {declared_tools}",
                f"status: {audit.get('status', 'unknown')}",
                f"healthcheck: {audit.get('healthcheck_status', 'not_run')}; command={self._brief_runtime_value(audit.get('healthcheck') or audit.get('declared_healthcheck'), 300)}",
                f"install_required: {'true' if audit.get('install_required') else 'false'}",
                f"reason: {self._brief_runtime_value(audit.get('reason'), 500)}",
                f"decision: {audit.get('decision', '')}",
                f"registered_tools: {registered_tool_text}",
            ])
            if match:
                lines.append(
                    "matching_env_candidate: "
                    f"env={match.get('env', '')}; type={match.get('match_type', '')}; "
                    f"missing_packages={','.join(match.get('missing_packages', []) or []) or 'none'}; "
                    f"missing_capabilities={','.join(match.get('missing_capabilities', []) or []) or 'none'}; "
                    f"bound_tools={','.join(match.get('bound_tools', []) or []) or 'none'}"
                )
            if cand:
                lines.append(
                    "candidate_healthcheck: "
                    f"{'passed' if cand.get('ok') else 'failed'}; env={cand.get('env', '')}; "
                    f"command={self._brief_runtime_value(cand.get('healthcheck'), 300)}; "
                    f"detail={self._brief_runtime_value(cand.get('detail'), 500)}"
                )
            resolved_paths = audit.get("resolved_runtime_paths") or {}
            if resolved_paths:
                lines.append(
                    "resolved_runtime_paths: "
                    + "; ".join(
                        f"{key}={value}"
                        for key, value in sorted(resolved_paths.items())
                    )
                )
                lines.append(
                    "resolved_path_policy: use these exact verified values; "
                    "do not rebuild them from project_root, cwd, or benchmark_root"
                )
            hints = audit.get("discovery_hints") or {}
            if hints:
                lines.append(
                    "discovery_hints: "
                    f"candidate_envs={','.join(hints.get('candidate_envs', []) or []) or 'none'}; "
                    f"candidate_tools={','.join(hints.get('candidate_tools', []) or []) or 'none'}; "
                    f"evidence_files={','.join(hints.get('evidence_files', []) or []) or 'none'}; "
                    "evidence_only=true"
                )
            lines.append("---")
        lines.append("[/RUNTIME_AUDIT]")
        return "\n".join(lines)

    def _consultant_runtime_preflight(
        self,
        selected_skills: Optional[List[str]],
        task_id: str,
    ) -> Tuple[List[Dict[str, Any]], str]:
        """Verify selected runtimes and return structured plus prompt-safe audit evidence."""
        if not getattr(self, "skill_manager", None) or not getattr(self, "pm", None):
            return [], ""
        selected = self._selected_skill_ids(selected_skills)
        if not selected:
            return [], ""
        effective_runtime_ids = (
            self.skill_manager.effective_runtime_skill_ids(selected)
            if hasattr(self.skill_manager, "effective_runtime_skill_ids")
            else selected
        )

        rows: List[str] = []
        audits: List[Dict[str, Any]] = []
        for sid in effective_runtime_ids:
            executable_check = getattr(
                self.skill_manager, "is_executable_runtime_skill", None
            )
            if callable(executable_check) and not bool(executable_check(sid)):
                continue
            requirements = self._skill_runtime_requirements(sid)
            env = str(requirements.get("env") or requirements.get("default_env") or "").strip()
            audit = self._runtime_audit_for_skill(sid, task_id)
            audits.append(audit)
            ok = bool(audit.get("declared_ok"))
            detail = str(audit.get("reason") or audit.get("declared_detail") or "")
            checked_env = str(audit.get("checked_env") or env)
            status = "passed" if ok else "failed"
            row = (
                f"- {sid}: {status}; env={checked_env or env}; "
                f"healthcheck={audit.get('declared_healthcheck', '') or requirements.get('healthcheck', '') or 'metadata package check'}; "
                f"detail={str(detail or '').strip()[:500] or 'OK'}"
            )
            match = audit.get("matching_env_candidate") or {}
            if not ok and match.get("env"):
                row += (
                    f"; registered_env_candidate={match.get('env')} "
                    f"({match.get('match_type', 'unknown')}; "
                    f"missing_packages={','.join(match.get('missing_packages', []) or []) or 'none'}; "
                    f"missing_capabilities={','.join(match.get('missing_capabilities', []) or []) or 'none'})"
                )
            if not ok and audit.get("decision"):
                row += f"; decision={audit.get('decision')}"
            rows.append(row)

        if not rows:
            return audits, ""
        runtime_audit = self._format_runtime_audit(audits)
        summary = (
            "[RUNTIME_PREFLIGHT]\n"
            "- Consultant checked the selected active skill runtime(s) before Planner handoff.\n"
            "- A tool registered in a different environment is not automatically available inside the active skill runtime; Planner/Generate must use the skill env_runner, a registered command shim, or a documented fallback.\n"
            + "\n".join(rows)
            + "\n[/RUNTIME_PREFLIGHT]"
            + ("\n\n" + runtime_audit if runtime_audit else "")
        )
        return audits, summary

    def _consultant_runtime_seed_evidence(
        self,
        selected_skills: Sequence[str],
        task_id: str,
    ) -> Tuple[List[Dict[str, Any]], Dict[str, Dict[str, Any]], str]:
        """Run controller-owned runtime checks and key them for the evidence ledger."""
        audits, summary = self._consultant_runtime_preflight(
            list(selected_skills or []),
            task_id,
        )
        evidence: Dict[str, Dict[str, Any]] = {}
        for audit in audits:
            skill_id = str(audit.get("skill_id") or audit.get("skill") or "").strip()
            if skill_id:
                evidence[skill_id] = dict(audit)
        return audits, evidence, summary

    def _consultant_runtime_preflight_summary(self, selected_skills: Optional[List[str]], task_id: str) -> str:
        """Backward-compatible textual view for callers and tests."""
        _audits, summary = self._consultant_runtime_preflight(selected_skills, task_id)
        return summary

    def _consultant_runtime_context(self, candidate_skill_ids: Optional[List[str]]) -> str:
        """Render only runtime metadata relevant to Consultant candidates.

        The full package-manager inventory is useful to execution nodes but is
        noisy and easy to misread during routing.  Consultant only needs the
        declared runtime plus any registered status for the few candidate
        skills it may select.
        """
        if not self.skill_manager or not candidate_skill_ids:
            return "<runtime_candidates>\nSelect a canonical skill before resolving its runtime.\n</runtime_candidates>"

        lines = ["<runtime_candidates>"]
        for skill_id in self.skill_manager.normalize_selected_skills(
            candidate_skill_ids,
            max_results=self._selection_max_skills(" ".join(candidate_skill_ids)),
        ):
            requirements = self._skill_runtime_requirements(skill_id)
            record = self.skill_manager.get_runtime_record(skill_id) or {}
            env = str(
                requirements.get("env")
                or requirements.get("default_env")
                or record.get("env")
                or "unspecified"
            ).strip()
            healthcheck = str(requirements.get("healthcheck") or record.get("healthcheck") or "declared by skill").strip()
            status = str(record.get("status") or "unknown").strip()
            lines.append(
                f"- skill={skill_id}; env={env}; registered_status={status}; "
                f"healthcheck={self._brief_runtime_value(healthcheck, 220)}"
            )
        lines.append("</runtime_candidates>")
        return "\n".join(lines)

    def _format_runtime_status_for_observation(
        self,
        task_id: str,
        selected_skills: Optional[List[str]] = None,
    ) -> str:
        records = self._runtime_status_for_task(task_id, selected_skills)
        if not records:
            return ""
        lines = ["<runtime_status>"]
        for record in records.values():
            lines.append(
                "- "
                f"skill_id={record.get('skill_id', '')}; "
                f"env={record.get('env', '')}; "
                f"mode={record.get('mode', '')}; "
                f"ok={record.get('ok', False)}; "
                f"env_runner={record.get('env_runner', '')}; "
                f"checked_at={record.get('checked_at', '')}"
            )
        lines.append("</runtime_status>")
        return "\n" + "\n".join(lines)

    def _selected_skill_env_runner_violation(self, code: str, selected_skills: Optional[List[str]]) -> str:
        if not self.skill_manager or not selected_skills:
            return ""
        code_text = str(code or "")
        normalized_code = code_text.replace("\\", "/")
        code_lines = [
            line.strip()
            for line in code_text.splitlines()
            if line.strip() and not line.strip().startswith("#")
        ]
        for sid in self._selected_skill_ids(selected_skills):
            requirements = self._skill_runtime_requirements(sid)
            runner = str(requirements.get("env_runner") or "").strip()
            if not runner:
                continue
            env = str(requirements.get("env") or requirements.get("default_env") or "").strip()
            install_tool_name = self._install_tool_name(requirements.get("install_tool") or "")
            if install_tool_name and re.search(rf"(?m)^\s*{re.escape(install_tool_name)}\b", code_text):
                install_tag = self._install_tool_tag(install_tool_name, env)
                return (
                    f"Selected skill `{sid}` declares install_tool `{install_tool_name}`, but the generated "
                    f"<execute> command invokes it like a script/interpreter. `{install_tool_name}` is only for "
                    f"installation delegation via `{install_tag}`, not for running analysis code. "
                    f"If the runtime is already available, regenerate the command with env_runner `{runner}`. "
                    f"If the runtime healthcheck fails, emit `{install_tag}` outside <execute>."
                )
            meta = self.skill_manager.get_skill_meta(sid)
            skill_dir = Path(meta.get("_skill_dir", self.skill_manager.skills_root / sid)).resolve()
            runner_present = runner in code_text or (env and f"conda run -n {env}" in code_text)
            logical_code = re.sub(r"\\\s*\n", " ", code_text)
            for script in meta.get("_scripts", []) or []:
                script_name = Path(script).name
                rel_script = str(script).replace("\\", "/")
                abs_script = str((skill_dir / script).resolve()).replace("\\", "/")
                mentions_script = (
                    script_name in code_text
                    or rel_script in normalized_code
                    or abs_script in normalized_code
                )
                if not mentions_script:
                    continue
                script_path = (skill_dir / script).resolve()
                if script_path.suffix.lower() == ".py":
                    try:
                        script_source = script_path.read_text(encoding="utf-8", errors="replace")
                    except OSError:
                        script_source = ""
                    declared_flags = set(re.findall(r"['\"](--[A-Za-z0-9][A-Za-z0-9-]*)['\"]", script_source))
                    command_tail = ""
                    for command_line in logical_code.splitlines():
                        token = next(
                            (
                                item for item in (abs_script, rel_script, script_name)
                                if item and item in command_line
                            ),
                            "",
                        )
                        if token:
                            command_tail = command_line.split(token, 1)[1]
                            break
                    used_flags = set(re.findall(r"(?<![A-Za-z0-9-])--[A-Za-z0-9][A-Za-z0-9-]*", command_tail))
                    unknown_flags = sorted(used_flags - declared_flags - {"--help"})
                    if declared_flags and unknown_flags:
                        return (
                            f"Selected skill `{sid}` script `{script_name}` was called with undeclared "
                            f"flag(s): {', '.join(unknown_flags)}. Use only the script's actual CLI "
                            "arguments from its --help/source and active skill documentation."
                        )
                    undeclared_conda_python = bool(re.search(
                        rf"\bconda\s+run\b[^\n]*\bpython(?:\d+(?:\.\d+)*)?\b[^\n]*{re.escape(script_name)}",
                        logical_code,
                    ))
                    if runner == "bash" and undeclared_conda_python:
                        return (
                            f"Selected skill `{sid}` declares env_runner `bash`, but `{script_name}` was "
                            f"wrapped with an undeclared Conda Python. Use controller Python `{sys.executable}` "
                            "when the skill identifies this as a current-Python renderer/helper; keep the "
                            "declared analysis environment only for its tools."
                        )
                if runner == "bash":
                    continue
                if mentions_script and not runner_present:
                    return (
                        f"Selected skill `{sid}` declares env_runner `{runner}` but the generated command "
                        f"mentions `{script_name}` without that runner. Regenerate the command as "
                        f"`{runner} {rel_script} ...` and do not use bare `python {rel_script}`."
                    )
            skill_terms = " ".join([
                " ".join(map(str, requirements.get("packages", []) or [])),
                " ".join(map(str, requirements.get("capabilities", []) or [])),
                " ".join(map(str, meta.get("tags", []) or [])),
            ]).lower()
            managed_tools = set()
            if any(term in skill_terms for term in ["cooler", "cool", "mcool"]):
                managed_tools.add("cooler")
            if any(term in skill_terms for term in ["hicexplorer", "hicfindtads", "hicdifferentialtad", "hi-c"]):
                managed_tools.update({
                    "hicFindTADs",
                    "hicDifferentialTAD",
                    "hicPlotTADs",
                    "hicConvertFormat",
                    "hicTransform",
                })
            for tool in sorted(managed_tools):
                bare_tool_re = re.compile(rf"^(?:env\s+[^;&|]+\s+)?{re.escape(tool)}(?:\s|$)")
                if any(bare_tool_re.search(line) for line in code_lines) and not runner_present:
                    env_prefix = f"conda run -n {env}" if env else runner.rsplit(" ", 1)[0]
                    return (
                        f"Selected skill `{sid}` uses managed runtime `{env or runner}` but the generated command "
                        f"calls bare `{tool}`. Regenerate it as `{env_prefix} {tool} ...` "
                        f"or use `{runner} -c \"...\"` for Python-based preflight. Do not ask for code review "
                        f"on bare `{tool}` commands."
                    )
            if sid == "3d-dna/calder2-subcompartment" and env and re.search(r"\bRscript\b|library\s*\(\s*CALDER", code_text, re.IGNORECASE):
                wrong_envs = []
                wrong_envs.extend(
                    match
                    for match in re.findall(r"\bconda\s+run\s+-n\s+([A-Za-z0-9_.-]+)\s+Rscript\b", code_text, re.IGNORECASE)
                    if match != env
                )
                wrong_envs.extend(
                    match
                    for match in re.findall(r"/envs/([^/\s]+)/bin/Rscript\b", code_text)
                    if match != env
                )
                wrong_envs.extend(
                    match
                    for match in re.findall(r"\bconda\s+activate\s+([A-Za-z0-9_.-]+)", code_text, re.IGNORECASE)
                    if match != env
                )
                if wrong_envs:
                    wrong = ", ".join(list(dict.fromkeys(wrong_envs)))
                    return (
                        f"Selected skill `{sid}` is bound to runtime env `{env}`, but the generated code "
                        f"uses Rscript/R from another environment: {wrong}. Repair `{env}` instead: "
                        f"install/register the selected skill runtime dependencies in `{env}` via install_subagent, then rerun "
                        f"`conda run -n {env} which Rscript` and `conda run -n {env} Rscript -e \"library(CALDER)\"`."
                    )
        return ""

    def _skill_command_names(self, skill_id: str) -> set[str]:
        if not self.skill_manager:
            return set()
        meta = self.skill_manager.get_skill_meta(skill_id)
        requirements = self._skill_runtime_requirements(skill_id)
        terms = " ".join([
            " ".join(map(str, requirements.get("packages", []) or [])),
            " ".join(map(str, requirements.get("capabilities", []) or [])),
            " ".join(map(str, meta.get("tags", []) or [])),
            " ".join(map(str, meta.get("legacy_ids", []) or [])),
        ]).lower()
        commands: set[str] = set()
        if "cooler" in terms or "mcool" in terms:
            commands.add("cooler")
        if "hicfindtads" in terms:
            commands.add("hicFindTADs")
        if "hicdifferentialtad" in terms or "differential-tad" in terms:
            commands.add("hicDifferentialTAD")
        if "hicplottads" in terms:
            commands.add("hicPlotTADs")
        if "hicconvertformat" in terms:
            commands.add("hicConvertFormat")
        if "hictransform" in terms:
            commands.add("hicTransform")
        return commands

    def _workflow_future_skill_violation(
        self,
        code: str,
        active_skills: Optional[List[str]],
        future_skills: Optional[List[str]],
    ) -> str:
        if not self.skill_manager or not future_skills:
            return ""
        code_text = str(code or "")
        normalized_code = code_text.replace("\\", "/")
        code_lines = [
            line.strip()
            for line in code_text.splitlines()
            if line.strip() and not line.strip().startswith("#")
        ]
        active_set = set(self._selected_skill_ids(active_skills or []))
        active_commands = set()
        for sid in active_set:
            active_commands.update(self._skill_command_names(sid))

        for sid in self._selected_skill_ids(future_skills):
            if sid in active_set:
                continue
            meta = self.skill_manager.get_skill_meta(sid)
            skill_dir = Path(meta.get("_skill_dir", self.skill_manager.skills_root / sid)).resolve()
            for script in meta.get("_scripts", []) or []:
                script_name = Path(script).name
                rel_script = str(script).replace("\\", "/")
                abs_script = str((skill_dir / script).resolve()).replace("\\", "/")
                if script_name in code_text or rel_script in normalized_code or abs_script in normalized_code:
                    return (
                        f"Generated command mentions future-stage skill `{sid}` script `{script_name}` "
                        "before that workflow batch is active. Finish the current active batch, then "
                        "output the appropriate <activate_batch ... /> action before using this script."
                    )
            for command in sorted(self._skill_command_names(sid) - active_commands):
                command_re = re.compile(rf"^(?:env\s+[^;&|]+\s+)?(?:conda\s+run\s+-n\s+\S+\s+)?{re.escape(command)}(?:\s|$)")
                if any(command_re.search(line) for line in code_lines):
                    return (
                        f"Generated command calls `{command}` from future-stage skill `{sid}` before "
                        "that workflow batch is active. Finish the current active batch and activate "
                        "the next batch before running it."
                    )
        return ""

    def _reuse_registered_runtime_for_install(
        self,
        selected_skills: Optional[List[str]],
        specified_env: Optional[str],
        task_id: str,
    ) -> Dict[str, Any]:
        if not self.skill_manager or not self.pm:
            return {}
        for sid in self._selected_skill_ids(selected_skills):
            requirements = self._skill_runtime_requirements(sid)
            env = requirements.get("env") or requirements.get("default_env", "")
            if not env:
                continue
            if specified_env and specified_env not in {env, "default"}:
                continue
            runtime_record = self.skill_manager.get_runtime_record(sid)
            pm_record = self.pm.get_environment(env)
            if not runtime_record and not pm_record:
                continue
            ok, detail, verified_env = self._verify_skill_runtime(sid, task_id=task_id)
            if ok:
                final_res = (
                    f"✅ Reusing registered environment '{verified_env}' for selected skill '{sid}'. "
                    "Healthcheck passed; installation is not needed."
                )
                return {"ok": True, "env": verified_env, "detail": detail, "message": final_res, "skill_id": sid}
            return {
                "ok": False,
                "env": verified_env or env,
                "detail": detail or "Healthcheck failed.",
                "skill_id": sid,
            }
        return {}

    def _skill_plan_violations(
        self,
        plan: str,
        selected_skills: List[str],
        user_msg: str = "",
        workflow_handoff: Optional[Dict[str, Any]] = None,
    ) -> List[Dict[str, Any]]:
        # Compatibility parameters remain because older callers pass the user
        # request and workflow handoff.  Neither is machine evidence that a
        # rendered Plan string covers a skill or workflow stage.  Structured
        # step fields are validated separately.
        del user_msg, workflow_handoff
        raw_issues = (
            self.skill_manager.validate_plan(plan, selected_skills)
            if self.skill_manager and selected_skills
            else []
        )
        if self.skill_manager and selected_skills:
            review_telemetry = self.skill_manager.plan_review_telemetry(
                plan,
                selected_skills,
            )
            if review_telemetry.get("undocumented_script_mentions"):
                logger.info(
                    "Planner non-authoritative script review telemetry: %s",
                    json.dumps(review_telemetry, ensure_ascii=False, sort_keys=True),
                )
        return [normalize_validation_issue(issue) for issue in raw_issues]

    def _plan_execution_capability_violations(
        self,
        plan_state: Mapping[str, Any],
        selected_skills: Sequence[str],
    ) -> List[Dict[str, Any]]:
        if not self.skill_manager:
            return []
        return [
            normalize_validation_issue(issue)
            for issue in self.skill_manager.validate_plan_execution_capabilities(
                plan_state,
                selected_skills,
            )
        ]

    def _bind_plan_execution_capability_contracts(
        self,
        plan_state: Mapping[str, Any],
        selected_skills: Sequence[str],
    ) -> Dict[str, Any]:
        if not self.skill_manager:
            return deepcopy(dict(plan_state or {}))
        return self.skill_manager.bind_plan_execution_capability_contracts(
            plan_state,
            selected_skills,
        )

    def _repair_consultant_skill_summary(
        self,
        summary: str,
        repaired_skills: List[str],
        raw_selected: List[str],
        normalized_selected: List[str],
        issues: List[str],
    ) -> str:
        """Write the validated Consultant selection and retain a repair audit note."""
        marker = "[SELECTED_SKILLS: " + (", ".join(repaired_skills) or "none") + "]"
        repaired_summary = re.sub(
            r"\[SELECTED_SKILLS\s*:\s*.*?\]",
            marker,
            summary or "",
            count=1,
            flags=re.DOTALL,
        )
        if repaired_summary == (summary or "") and marker not in repaired_summary:
            repaired_summary = marker + "\n" + repaired_summary

        audit_note = (
            "[CONSULTANT_SKILL_REPAIR]\n"
            "- Valid selections were preserved; invalid IDs were either repaired inside the original candidate allowlist or dropped.\n"
            f"- raw_selected: {', '.join(raw_selected) if raw_selected else 'None'}\n"
            f"- normalized_selected_before_repair: {', '.join(normalized_selected) if normalized_selected else 'None'}\n"
            f"- validation_issues: {'; '.join(issues) if issues else 'None'}\n"
            f"- final_selected: {', '.join(repaired_skills) if repaired_skills else 'None'}\n"
            "[/CONSULTANT_SKILL_REPAIR]"
        )
        return repaired_summary.strip() + "\n" + audit_note

    def _consultant_skill_repair_decision(
        self,
        raw_selected: List[str],
        candidate_skill_ids: List[str],
        validation_errors: List[str],
        max_skills: int,
    ) -> Dict[str, Any]:
        """Choose deterministic ID repair, one restricted reselection, or safe drop."""
        if not self.skill_manager:
            return {
                "action": "handoff",
                "selected": [],
                "valid_selected": [],
                "invalid_ids": list(raw_selected or []),
                "repaired_ids": [],
                "unresolved_invalid_ids": list(raw_selected or []),
                "feedback": "",
            }

        previous_feedback = "\n".join(str(item or "") for item in validation_errors or [])
        prior_preserved: List[str] = []
        for match in re.finditer(
            r"\[VALID_SELECTIONS_PRESERVED\s*:\s*(.*?)\]",
            previous_feedback,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            prior_preserved.extend(
                item.strip()
                for item in re.split(r"\s*(?:,|，|;|；)\s*", match.group(1))
                if item.strip() and item.strip().lower() not in {"none", "n/a", "null"}
            )

        result = self.skill_manager.repair_selected_skill_ids(
            raw_selected,
            candidate_skill_ids,
            preserved_ids=prior_preserved,
            max_results=max_skills,
        )
        reselection_already_requested = "<consultant_skill_reselection_error>" in previous_feedback
        if result["unresolved_invalid_ids"] and not reselection_already_requested:
            preserved = result["selected"]
            candidates = result["candidate_ids"]
            feedback = (
                "<consultant_validation_error>\n"
                "<consultant_skill_reselection_error>\n"
                "Your previous skill selection contained unknown IDs. Select zero or more IDs ONLY from "
                "the original candidate allowlist below. Copy canonical IDs exactly; do not invent IDs and "
                "do not expand the candidate scope.\n"
                f"Invalid previous IDs: {', '.join(result['unresolved_invalid_ids'])}\n"
                f"Original candidate allowlist: {', '.join(candidates) if candidates else 'None'}\n"
                f"[VALID_SELECTIONS_PRESERVED: {', '.join(preserved) if preserved else 'none'}]\n"
                "Return FINISH with exactly one [SELECTED_SKILLS: ...] marker.\n"
                "</consultant_skill_reselection_error>\n"
                "</consultant_validation_error>"
            )
            return {**result, "action": "reselect", "feedback": feedback}

        # A repeated invalid reselection is not retried globally. Unknown IDs
        # are dropped and only preserved/uniquely repaired canonical IDs remain.
        return {**result, "action": "handoff", "feedback": ""}

    def _selection_max_skills(self, text: str) -> int:
        """Return the task-wide selection bound; Planner owns per-step narrowing."""
        _ = text
        return self.skill_manager.MAX_SELECTED_SKILLS if self.skill_manager else 1

    def _redirect_install_command(self, code: str, selected_skills: Optional[List[str]] = None) -> Optional[str]:
        install_re = re.search(
            r"(?:^|\n)\s*(?:python(?:3)?\s+-m\s+)?pip\s+install\s+([^\n]+)|(?:^|\n)\s*(?:conda|mamba)\s+(?:install|create)\b([^\n]+)",
            code,
            re.IGNORECASE,
        )
        if not install_re:
            r_install_re = re.search(
                r"\bRscript\b.*(?:install\.packages|install_github)\s*\(",
                code,
                re.IGNORECASE | re.DOTALL,
            )
            if r_install_re:
                defaults = self._skill_runtime_defaults(selected_skills)
                env_match = re.search(r"\bconda\s+run\s+-n\s+([A-Za-z0-9_.-]+)\s+Rscript\b", code, re.IGNORECASE)
                env = defaults.get("env") or (env_match.group(1) if env_match else "") or "bio_r_runtime"
                if re.search(r"\bcalder\b", code, re.IGNORECASE) and self._calder_runtime_allowed(selected_skills, env):
                    tool_name = "calder_r_runtime"
                else:
                    tool_name = defaults.get("install_tool") or defaults.get("tool_name") or "r_package_runtime"
                return (
                    self._install_tool_tag(tool_name, env)
                    + "<!-- R package installation must be performed by install_subagent and rechecked after install. -->"
                )
            return None
        payload = install_re.group(1) or install_re.group(2) or ""
        raw_tokens = [t for t in re.split(r"\s+", payload.strip()) if t]
        tokens = []
        skip_next = False
        requested_env = ""
        for token in raw_tokens:
            if skip_next:
                skip_next = False
                continue
            if token in {"-n", "--name"} and not requested_env:
                skip_next = True
                continue
            if token in {"-n", "--name", "-p", "--prefix"}:
                skip_next = True
                continue
            if token in {"-c", "--channel"}:
                skip_next = True
                continue
            if token.startswith("-"):
                continue
            tokens.append(token)
        env_match = re.search(r"(?:^|\s)(?:-n|--name)\s+([A-Za-z0-9_.-]+)", payload)
        if env_match:
            requested_env = env_match.group(1)
        package = next((t for t in tokens if not re.match(r"^(?:python=|env=)", t, re.I)), "python-package")
        package = re.split(r"[<>=!~]", package)[0]

        defaults = self._skill_runtime_defaults(selected_skills)
        env = defaults.get("env", "")
        if not env:
            env = requested_env or f"bio_{package.lower().replace('-', '_')}"

        tool_name = defaults.get("tool_name") if defaults.get("selected") else package
        return self._install_tool_tag(tool_name, env)

    def _infer_runtime_skills_from_code(
        self,
        code: str,
        selected_skills: Optional[List[str]] = None,
    ) -> List[str]:
        skills = list(dict.fromkeys(
            sid for sid in self._selected_skill_ids(selected_skills)
            if not (
                self.skill_manager
                and hasattr(self.skill_manager, "is_workflow_router_skill")
                and self.skill_manager.is_workflow_router_skill(sid)
            )
        ))
        if not self.skill_manager:
            return skills

        text = str(code or "")
        lower = text.lower()
        candidates = []
        if (
            "run_rrblup_package.r" in lower
            or "crop-gs-rrblup-gblup" in lower
            or re.search(r"\brrblup\b", text, re.IGNORECASE)
            or re.search(r"\br-rrblup\b", text, re.IGNORECASE)
            or re.search(r"\bconda\s+run\s+-n\s+crop_gp_pro\b", text, re.IGNORECASE)
        ):
            candidates.append("crop-breeding/crop-gs-rrblup-gblup")

        if hasattr(self.skill_manager, "find_runtime_skills_for_tool"):
            for tool in self._runtime_tool_candidates_from_text(text):
                for sid in self.skill_manager.find_runtime_skills_for_tool(
                    tool,
                    selected_skill_ids=selected_skills or [],
                    max_results=3,
                ):
                    if sid not in candidates:
                        candidates.append(sid)

        for candidate in candidates:
            normalized = self.skill_manager.normalize_selected_skills([candidate], max_results=1)
            for sid in normalized:
                if sid in set(self._selected_skill_ids(selected_skills or [])) and sid not in skills:
                    skills.insert(0, sid)
        return skills

    @staticmethod
    def _looks_like_missing_runtime_dependency(text: str) -> bool:
        lower = str(text or "").lower()
        patterns = (
            r"there is no package called ['\"]?rrblup",
            r"there is no package called ['\"]?calder",
            r"there is no package called .{0,4}calder",
            r"cran package rrblup is required",
            r"\brrblup\b.*\bnot found\b",
            r"\bcalder2?\b.*\bnot available\b",
            r"\bpackage\b.*\brrblup\b.*\brequired\b",
            r"\brscript:\s*command not found\b",
            r"\bno rscript\b",
            r"environmentlocationnotfound",
            r"could not find conda environment",
            r"commandnotfounderror",
            r"\b(?:makeblastdb|blastp|blastn|blastdbcmd|hmmsearch|hmmbuild|diamond)\s*:\s*command not found\b",
            r"\b(?:no|which:\s*no)\s+(?:makeblastdb|blastp|blastn|blastdbcmd|hmmsearch|hmmbuild|diamond)\b",
            r"\bsyntaxerror:\s*invalid syntax\b",
            r"\b404:\s*not found\b",
            r"\bcorrupt(?:ed)?\s+(?:runtime|environment|installation|dependency)\b",
            r"\b(?:runtime|environment|installation|dependency)\s+corrupt(?:ed)?\b",
        )
        return any(re.search(pattern, lower, re.IGNORECASE) for pattern in patterns)

    @staticmethod
    def _missing_executables_from_error(text: str) -> List[str]:
        tools: List[str] = []
        seen: set[str] = set()

        def add(tool: str) -> None:
            cleaned = str(tool or "").strip()
            if not cleaned or "/" in cleaned or cleaned.startswith("-") or cleaned in seen:
                return
            seen.add(cleaned)
            tools.append(cleaned)

        for match in re.finditer(r"\b([A-Za-z0-9_.+-]+)\s*:\s*command not found\b", str(text or ""), re.IGNORECASE):
            add(match.group(1))
        for match in re.finditer(r"\b(?:which:\s*)?no\s+([A-Za-z0-9_.+-]+)\s+(?:in|found)\b", str(text or ""), re.IGNORECASE):
            add(match.group(1))
        for match in re.finditer(r"/bin/([A-Za-z0-9_.+-]+):\s+No such file or directory\b", str(text or ""), re.IGNORECASE):
            add(match.group(1))
        return tools

    @staticmethod
    def _shell_command_candidates_from_text(text: str) -> List[str]:
        ignored = {
            "cd", "cat", "chmod", "conda", "cut", "echo", "env", "false", "find",
            "grep", "head", "ls", "mkdir", "printf", "run", "sed", "sh", "sort",
            "tail", "test", "tr", "true", "uniq", "awk", "bash",
        }
        tools: List[str] = []

        def add(token: str) -> None:
            cleaned = str(token or "").strip().strip('"\'')
            cleaned = cleaned.split("/")[-1]
            if not cleaned or cleaned.startswith("-"):
                return
            lower = cleaned.lower()
            if lower in ignored or re.fullmatch(r"[A-Z_][A-Z0-9_]*", cleaned):
                return
            if lower not in tools:
                tools.append(lower)

        for match in re.finditer(r"\bconda\s+run\s+-n\s+\S+\s+(?:bash\s+-c\s+)?([A-Za-z0-9_.+/-]+)", str(text or ""), re.IGNORECASE):
            add(match.group(1))
        for segment in re.split(r"(?:&&|\|\||\||;|\n)", str(text or "")):
            stripped = segment.strip()
            if not stripped or re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", stripped):
                continue
            try:
                parts = shlex.split(stripped)
            except ValueError:
                parts = stripped.split()
            while parts and re.match(r"^[A-Za-z_][A-Za-z0-9_]*=", parts[0]):
                parts.pop(0)
            if not parts:
                continue
            if parts[:3] == ["conda", "run", "-n"] and len(parts) >= 5:
                add(parts[4])
            elif parts[:2] == ["conda", "run"] and len(parts) >= 4:
                add(parts[3])
            else:
                add(parts[0])
        return tools

    def _runtime_tool_candidates_from_text(self, text: str) -> List[str]:
        tools: List[str] = []
        for tool in self._missing_executables_from_error(text) + self._shell_command_candidates_from_text(text):
            if tool not in tools:
                tools.append(tool)
        return tools

    @staticmethod
    def _install_tool_parts(value: str, fallback_env: str = "") -> Tuple[str, str]:
        text = str(value or "").strip()
        if not text:
            return "", str(fallback_env or "").strip()
        match = re.fullmatch(
            r"<install_tool(?:\s+env=[\"'](?P<env>.*?)[\"'])?>(?P<name>.*?)</install_tool>",
            text,
            re.IGNORECASE | re.DOTALL,
        )
        if match:
            return match.group("name").strip(), (match.group("env") or fallback_env or "").strip()
        return text, str(fallback_env or "").strip()

    @classmethod
    def _install_tool_name(cls, value: str) -> str:
        name, _env = cls._install_tool_parts(value)
        return name

    @classmethod
    def _install_tool_tag(cls, value: str, env: str) -> str:
        name, declared_env = cls._install_tool_parts(value, env)
        return f'<install_tool env="{declared_env or env}">{name or "skill_runtime"}</install_tool>'

    @staticmethod
    def _runtime_install_disallowed_by_task_spec(
        task_spec: Dict[str, Any],
        dependency_key: str = "",
    ) -> bool:
        return not semantic_install_policy(
            task_spec,
            dependency_key=dependency_key,
        ).get("install_allowed", True)

    def _runtime_block_message(self, redirect: str, selected_skills: Optional[List[str]], evidence: str = "") -> str:
        env = ""
        tool_name = ""
        match = re.search(r"<install_tool(?:\s+env=[\"'](.*?)[\"'])?>(.*?)</install_tool>", str(redirect or ""), re.DOTALL)
        if match:
            env = (match.group(1) or "").strip()
            tool_name = self._install_tool_name(match.group(2))
        skills = ", ".join(self._selected_skill_ids(selected_skills)) or "selected skill runtime"
        detail = str(evidence or redirect or "").strip().replace("\n", " ")[:600]
        return (
            "blocked: required runtime dependency is missing, and the current task explicitly "
            "requires missing environments/dependencies to be treated as blocked instead of "
            f"delegating installation. skills={skills}; env={env or 'unknown'}; "
            f"install_tool={tool_name or 'skill_runtime'}; evidence={detail}"
        )

    def _consultant_runtime_block_handoff(
        self,
        consultant_context: str,
        code: str,
        stdout: str,
        stderr: str,
        task_id: str,
        max_skills: int = 1,
    ) -> Dict[str, Any]:
        selected: List[str] = []
        raw_selected: List[str] = []
        if self.skill_manager:
            raw_selected = self.skill_manager.match_skills(consultant_context, max_results=max_skills)
            selected = self.skill_manager.normalize_selected_skills(raw_selected, max_results=max_skills)
        if not selected:
            selected = []
        runtime_skills = self._infer_runtime_skills_from_code(code, selected)
        evidence = (stderr or stdout or "Consultant runtime verification failed.").strip()
        env_match = re.search(r"\bconda\s+run\s+-n\s+([A-Za-z0-9_.-]+)", str(code or ""), re.IGNORECASE)
        env_hint = env_match.group(1) if env_match else ""
        for sid in runtime_skills:
            requirements = self._skill_runtime_requirements(sid)
            env = str(requirements.get("env") or requirements.get("default_env") or env_hint or "").strip()
            if not env:
                continue
            self._cache_runtime_status(
                task_id,
                sid,
                env,
                False,
                evidence[:1000],
                requirements.get("healthcheck", ""),
                requirements.get("env_runner", ""),
                mode="consultant",
            )
        skill_marker = ", ".join(runtime_skills) if runtime_skills else "None"
        summary = (
            f"[SELECTED_SKILLS: {skill_marker}]\n\n"
            "[MISSING_INPUTS]\n"
            "- none\n"
            "[/MISSING_INPUTS]\n"
            "[QUESTIONS_FOR_USER]\n"
            "- none\n"
            "[/QUESTIONS_FOR_USER]\n"
            "[REQUIREMENTS_SUMMARY]\n"
            "- Intent / mode: Runtime availability verification for the requested analysis.\n"
            "- Runtime policy: The current user/benchmark instruction requires missing runtime environments/dependencies to be treated as blocked instead of installing them.\n"
            f"- Failed Consultant check: `{str(code or '').strip()[:300]}`\n"
            f"- Evidence: {evidence[:800]}\n"
            f"- Selected skill rationale: {skill_marker} matched the requested analysis context; no installation should be delegated under this task policy.\n"
            "[/REQUIREMENTS_SUMMARY]"
        )
        runtime_audits, runtime_summary = self._consultant_runtime_preflight(runtime_skills, task_id)
        if runtime_summary:
            summary = (summary.rstrip() + "\n\n" + runtime_summary).strip()
        return {
            "messages": [AIMessage(content="FINISH\n" + summary)],
            "selected_skills": runtime_skills,
            "selected_skills_raw": list(raw_selected),
            "skill_selection_source": "consultant_runtime_block",
            "requirements_summary": summary,
            "runtime_status": self._runtime_status_for_task(task_id),
            "runtime_audit": runtime_audits,
            "next_step": "planner",
        }

    def _consultant_skill_only_fallback_handoff(
        self,
        consultant_context: str,
        fallback_raw: List[str],
        task_id: str,
        consultant_memory_retrieval_context: str,
        consultant_wiki_context: str,
        input_resolution_context: str = "",
        max_skills: int = 1,
    ) -> Dict[str, Any]:
        """Hand off canonical skills to Planner when no valid workflow_state is available."""
        if not self.skill_manager:
            return {}
        raw_selected = list(dict.fromkeys([sid for sid in (fallback_raw or []) if str(sid).strip()]))
        selected = self.skill_manager.normalize_selected_skills(raw_selected, max_results=max_skills)
        if not selected:
            return {}

        audit = input_resolution_context.strip()
        summary_parts = [
            f"[SELECTED_SKILLS: {', '.join(selected)}]",
            "",
            "[CONSULTANT_SKILL_ONLY_FALLBACK]",
            "- Consultant could not produce a valid workflow_state after repeated internal repair attempts.",
            "- No workflow_state is being constructed from this fallback; Planner must decompose the task from the selected canonical skills.",
            "- Planner must assign selected skills through each step's `Skills:` field and ask the user if required inputs or parameters remain unresolved.",
            f"- raw_skill_hints: {', '.join(raw_selected) if raw_selected else 'None'}",
            "[/CONSULTANT_SKILL_ONLY_FALLBACK]",
        ]
        if audit:
            summary_parts.extend(["", audit])
        runtime_audits, runtime_summary = self._consultant_runtime_preflight(selected, task_id)
        if runtime_summary:
            summary_parts.extend(["", runtime_summary])
        summary = "\n".join(summary_parts).strip()
        return {
            "messages": [AIMessage(content="FINISH\n" + summary)],
            "selected_skills": selected,
            "selected_skills_raw": raw_selected,
            "active_skills": [],
            "future_skills": [],
            "required_skills_all": list(selected),
            "candidate_skills": [],
            "workflow_id": "",
            "workflow_stages": [],
            "workflow_state": {},
            "workflow_handoff": {},
            "active_batch_id": "",
            "runtime_status": self._runtime_status_for_task(task_id),
            "runtime_audit": runtime_audits,
            "skill_selection_source": "consultant_skill_only_fallback",
            "requirements_summary": summary,
            "memory_packet_context": self._consultant_handoff_memory_packet(summary, consultant_memory_retrieval_context),
            "wiki_memory_context": consultant_wiki_context,
            "next_step": "planner",
        }

    @staticmethod
    def _workflow_cue_present(text: str, cue: str) -> bool:
        haystack = str(text or "")
        needle = str(cue or "").strip()
        if not needle:
            return False
        if needle.startswith("re:"):
            pattern = needle[3:].strip()
            return bool(pattern and re.search(pattern, haystack, re.IGNORECASE))
        return needle.lower() in haystack.lower()

    def _workflow_exclusion_reason(self, workflow: Dict[str, Any], query_text: str) -> str:
        """Apply workflow-declared exclusion cues without embedding domain rules in core."""
        if not self.workflow_manager:
            return ""
        rules = workflow.get("exclude_when") or {}
        if not isinstance(rules, dict):
            return ""

        for cue in self.workflow_manager._ensure_list(rules.get("any")):
            if self._workflow_cue_present(query_text, str(cue)):
                return f"workflow exclude_when.any matched: {cue}"

        all_cues = [str(cue) for cue in self.workflow_manager._ensure_list(rules.get("all")) if str(cue).strip()]
        if all_cues and all(self._workflow_cue_present(query_text, cue) for cue in all_cues):
            return "workflow exclude_when.all matched: " + ", ".join(all_cues)

        groups = rules.get("all_groups") or []
        if isinstance(groups, (str, bytes)):
            groups = [[str(groups)]]
        for group in groups:
            cues = [str(cue) for cue in self.workflow_manager._ensure_list(group) if str(cue).strip()]
            if cues and all(self._workflow_cue_present(query_text, cue) for cue in cues):
                return "workflow exclude_when.all_groups matched: " + ", ".join(cues)
        return ""

    def _workflow_candidate_allowed(self, workflow: Dict[str, Any], query_text: str) -> bool:
        return not self._workflow_exclusion_reason(workflow, query_text)

    def _explicit_skill_ids_from_text(self, text: str, max_results: Optional[int] = None) -> List[str]:
        if not self.skill_manager:
            return []
        candidates = re.findall(r"\b(?:[A-Za-z0-9_.-]+/){1,4}[A-Za-z0-9_.-]+\b", str(text or ""))
        normalized: List[str] = []
        for candidate in candidates:
            for skill_id in self.skill_manager.normalize_selected_skills([candidate], max_results=1):
                if skill_id not in normalized:
                    normalized.append(skill_id)
        limit = max_results or SkillManager.MAX_SELECTED_SKILLS
        return normalized[:limit]

    def _state_update_for_user_skill_correction(
        self,
        user_answer: str,
        state: AgentState,
        task_id: str,
    ) -> Dict[str, Any]:
        explicit_skills = self._explicit_skill_ids_from_text(user_answer)
        if not explicit_skills:
            return {}
        current_skills = self._selected_skill_ids(state.get("selected_skills", []))
        if explicit_skills == current_skills:
            return {}
        update = {
            "selected_skills": explicit_skills,
            "selected_skills_raw": list(explicit_skills),
            "active_skills": [],
            "future_skills": [],
            "required_skills_all": list(explicit_skills),
            "candidate_skills": [],
            "workflow_handoff": {},
            "workflow_stages": [],
            "workflow_id": "",
            "active_batch_id": "",
            "skill_selection_source": "explicit_user_skill_correction",
        }
        selected = update.get("selected_skills") or explicit_skills
        runtime_audits, runtime_summary = self._consultant_runtime_preflight(selected, task_id)
        update["runtime_status"] = self._runtime_status_for_task(task_id, selected)
        update["runtime_audit"] = runtime_audits
        update["current_plan"] = ""
        update["requirements_summary"] = (
            "[USER_SKILL_CORRECTION]\n"
            f"- User explicitly selected skill(s): {', '.join(selected)}.\n"
            "- Discard any previous incompatible workflow activation and let Planner map these skills to steps.\n"
            "[/USER_SKILL_CORRECTION]"
        )
        if runtime_summary:
            update["requirements_summary"] += "\n\n" + runtime_summary
        update["next_step"] = "planner"
        return update

    @staticmethod
    def _runtime_install_target_from_error(text: str, fallback_name: str) -> Tuple[str, str]:
        lower = str(text or "").lower()
        if re.search(r"rscript:\s*command not found|no rscript|which:\s*no rscript", lower, re.IGNORECASE):
            return "r_base_runtime", "Rscript is missing; install/register r-base before attempting CALDER."
        if re.search(r"there is no package called .{0,4}calder|calder2?\s+not available", lower, re.IGNORECASE):
            return "calder_r_runtime", "CALDER R package is missing; install it only after Rscript passes."
        if re.search(r"\b(?:makeblastdb|blastp|blastn|blastdbcmd)\b", lower, re.IGNORECASE):
            return fallback_name, "missing_tools=[makeblastdb, blastp, blastn, blastdbcmd]; suggested_package=blast"
        return fallback_name, ""

    @staticmethod
    def _explicit_runtime_repair_kind(tool_name: str, message: str = "") -> str:
        text = f"{tool_name}\n{message}".lower()
        if re.search(r"\br_base_runtime\b|rscript:\s*command not found|which:\s*no rscript|\bno rscript\b", text, re.IGNORECASE):
            return "r_base_runtime"
        if re.search(r"\bcalder_r_runtime\b|there is no package called .{0,4}calder|calder2?\s+not available", text, re.IGNORECASE):
            return "calder_r_runtime"
        return ""

    @staticmethod
    def _runtime_repair_context(kind: str, target_env: str) -> str:
        if kind == "r_base_runtime":
            return (
                "\n\n[RUNTIME REPAIR TARGET]\n"
                f"- target_env: {target_env}\n"
                "- missing dependency: Rscript / r-base\n"
                "- Repair this exact conda environment; do not switch to another environment that happens to have Rscript.\n"
                "- Install/register r-base first. Do not run CALDER installation until these checks pass:\n"
                f"  1. conda run -n {target_env} which Rscript\n"
                f"  2. conda run -n {target_env} Rscript --version\n"
            )
        if kind == "calder_r_runtime":
            return (
                "\n\n[RUNTIME REPAIR TARGET]\n"
                f"- target_env: {target_env}\n"
                "- missing dependency: CALDER R package and/or data.table\n"
                "- First verify Rscript in this exact env. If Rscript is missing, install/register r-base before CALDER.\n"
                "- Do not use absolute Rscript paths from other conda environments.\n"
                "- If the selected skill provides an install_command, prefer that command over package-name inference.\n"
                "- Installation succeeds only after this check passes:\n"
                f"  conda run -n {target_env} Rscript -e "
                "\"suppressPackageStartupMessages(library(CALDER)); "
                "suppressPackageStartupMessages(library(data.table)); cat('OK\\n')\"\n"
            )
        return ""

    @staticmethod
    def _normalize_install_command_for_contract(command: str) -> str:
        text = str(command or "").replace("\\\n", " ").strip()
        text = re.sub(r"\s+", " ", text)
        return text.rstrip(";")

    @staticmethod
    def _adapt_install_command_env(command: str, target_env: str) -> str:
        normalized = BioAnalystAgent._normalize_install_command_for_contract(command)
        if not target_env:
            return normalized
        return re.sub(
            r"((?:^|\s)(?:-n|--name)\s+)([A-Za-z0-9_.-]+)",
            lambda match: f"{match.group(1)}{target_env}",
            normalized,
            count=1,
        ).strip()

    @staticmethod
    def _strict_runtime_contract_commands(runtime_defaults: Dict[str, Any], target_env: str) -> List[str]:
        commands: List[str] = []
        raw_commands: List[str] = []
        raw_commands.extend(runtime_defaults.get("install_commands", []) or [])
        raw_commands.extend(runtime_defaults.get("install_fallbacks", []) or [])
        install_command = str(runtime_defaults.get("install_command") or "").strip()
        if install_command and install_command not in raw_commands:
            raw_commands.insert(0, install_command)

        for command in raw_commands:
            adapted = BioAnalystAgent._adapt_install_command_env(command, target_env)
            commands.append(adapted)

        env_file = str(runtime_defaults.get("env_file") or "").strip()
        if env_file:
            commands.extend([
                f"conda env create -n {target_env} -f {env_file}",
                f"conda env update -n {target_env} -f {env_file}",
            ])
        return list(dict.fromkeys(
            BioAnalystAgent._normalize_install_command_for_contract(command)
            for command in commands
            if BioAnalystAgent._normalize_install_command_for_contract(command)
        ))

    @staticmethod
    def _selected_skill_install_command_context(runtime_defaults: Dict[str, Any], target_env: str) -> str:
        allowed_commands = BioAnalystAgent._strict_runtime_contract_commands(runtime_defaults, target_env)
        install_command = str(runtime_defaults.get("install_command") or "").strip()
        env_file = str(runtime_defaults.get("env_file") or "").strip()
        install_policy = str(runtime_defaults.get("install_policy") or "").strip()
        if not install_command and not allowed_commands and not env_file and not install_policy:
            return ""
        selected = ", ".join(map(str, runtime_defaults.get("selected", []) or [])) or "None"
        healthcheck = str(runtime_defaults.get("healthcheck") or "").strip()
        if healthcheck:
            healthcheck = BioAnalystAgent._adapt_install_command_env(healthcheck, target_env)
        packages = ", ".join(map(str, runtime_defaults.get("packages", []) or []))
        capabilities = ", ".join(map(str, runtime_defaults.get("capabilities", []) or []))
        effective_policy = install_policy or "prefer-declared"
        strict_policy = effective_policy.lower() in {"declared-only", "strict", "locked"}
        lines = [
            "",
            "[SELECTED SKILL INSTALL COMMAND]",
            f"- selected_skills: {selected}",
            f"- target_env: {target_env}",
            f"- language: {runtime_defaults.get('language', '') or ''}",
            f"- packages: {packages}",
            f"- capabilities: {capabilities}",
            f"- install_policy: {effective_policy}",
            f"- install_command: {install_command}",
            "- After installation, verify the selected skill runtime before registering success.",
        ]
        if env_file:
            lines.append(f"- env_file: {env_file}")
        if allowed_commands:
            if strict_policy:
                lines.extend([
                    "[STRICT SKILL RUNTIME CONTRACT]",
                    "- install_policy: declared-only",
                    "- You may execute only these installation commands for this selected skill runtime.",
                    "- Do not infer package names, switch to another environment, downgrade R/Python, or use CRAN/GitHub/pip fallback unless the exact command is listed here.",
                    "- If all listed commands fail, stop and report the failing command and stderr; do not fabricate a new fallback.",
                ])
            else:
                lines.extend([
                    "[DECLARED SKILL INSTALL PLAN]",
                    "- install_policy: prefer-declared",
                    "- Try the declared install command(s) first.",
                    "- If a declared command fails and the observed error clearly identifies a missing package, a generic repair is allowed, but it must stay in target_env and must pass the skill healthcheck before registration.",
                ])
            for command in allowed_commands:
                prefix = "allowed_install_command" if strict_policy else "declared_install_command"
                lines.append(f"- {prefix}: {command}")
            if strict_policy:
                lines.append("[/STRICT SKILL RUNTIME CONTRACT]")
            else:
                lines.append("[/DECLARED SKILL INSTALL PLAN]")
        if healthcheck:
            lines.append(f"- healthcheck: {healthcheck}")
        return "\n" + "\n".join(lines) + "\n"

    def _runtime_install_redirect_from_execution(
        self,
        code: str,
        stdout: str,
        stderr: str,
        selected_skills: Optional[List[str]],
        task_id: str,
    ) -> Tuple[str, List[str]]:
        combined = "\n".join(part for part in [code, stdout, stderr] if part)
        if not self._looks_like_missing_runtime_dependency(combined):
            return "", list(dict.fromkeys(self._selected_skill_ids(selected_skills)))

        runtime_skills = self._infer_runtime_skills_from_code(combined, selected_skills)
        if not runtime_skills:
            return "", []

        for sid in runtime_skills:
            requirements = self._skill_runtime_requirements(sid)
            env = requirements.get("env") or requirements.get("default_env", "")
            if not env:
                continue
            defaults = self._skill_runtime_defaults([sid])
            redirect_name = self._install_tool_name(requirements.get("install_tool")) or defaults.get("tool_name", "skill_runtime")
            install_command = requirements.get("install_command", "")
            reason = stderr.strip() or stdout.strip() or f"Runtime dependency check failed for {sid}."
            redirect_name, ordered_hint = self._runtime_install_target_from_error(reason, redirect_name)
            missing_tools = self._missing_executables_from_error(reason)
            if redirect_name == "calder_r_runtime" and not self._calder_runtime_allowed([sid], env):
                redirect_name = self._install_tool_name(requirements.get("install_tool")) or defaults.get("tool_name", "skill_runtime")
                ordered_hint = "Ignoring CALDER repair for non-CALDER2 skill; ordinary A/B compartments use PC1/eigenvector runtime."
            self._cache_runtime_status(
                task_id,
                sid,
                env,
                False,
                reason[:1000],
                requirements.get("healthcheck", ""),
                requirements.get("env_runner", ""),
                mode="execution",
            )
            comment_parts = [reason[:500]]
            if missing_tools:
                comment_parts.append(f"failure_class=missing_executable; missing_tools=[{', '.join(missing_tools)}]")
            if ordered_hint:
                comment_parts.append(ordered_hint)
            if install_command:
                comment_parts.append(f"suggested install: {install_command}")
            if requirements.get("healthcheck"):
                comment_parts.append(f"healthcheck: {requirements.get('healthcheck')}")
            return f'{self._install_tool_tag(redirect_name, env)}<!-- {"; ".join(comment_parts)} -->', runtime_skills
        return "", runtime_skills

    def _selected_skill_ids(self, state_selected: Optional[List[str]] = None) -> List[str]:
        if not state_selected:
            return []
        return list(state_selected)

    def _executable_runtime_skills(self, selected_skills: Optional[List[str]] = None) -> List[str]:
        selected = self._selected_skill_ids(selected_skills)
        if not self.skill_manager or not hasattr(self.skill_manager, "is_executable_runtime_skill"):
            return selected
        executable: List[str] = []
        for sid in selected:
            if self.skill_manager.is_executable_runtime_skill(sid) and sid not in executable:
                executable.append(sid)
        return executable

    def _skill_runtime_defaults(self, selected_skills: Optional[List[str]] = None) -> Dict[str, Any]:
        selected = self._selected_skill_ids(selected_skills)
        if not selected or not self.skill_manager:
            return {
                "selected": [],
                "env": "",
                "packages": [],
                "language": "",
                "capabilities": [],
                "healthcheck": "",
                "install_command": "",
                "install_commands": [],
                "install_fallbacks": [],
                "install_tool": "",
                "install_policy": "",
                "env_file": "",
                "tool_name": "skill_runtime",
            }
        sid = selected[0]
        requirements = self.skill_manager.get_runtime_requirements(sid)
        env = requirements.get("env") or requirements.get("default_env", "")
        packages = list(requirements.get("packages", []) or [])
        capabilities = list(requirements.get("capabilities", []) or [])
        language = requirements.get("language", "")
        safe_skill = re.sub(r"[^A-Za-z0-9_]+", "_", sid).strip("_").lower() or "skill"
        tool_name = f"{safe_skill}_runtime"
        if packages:
            tool_name = f"{safe_skill}_{language or 'deps'}"
        return {
            "selected": selected,
            "env": env,
            "packages": packages,
            "language": language,
            "capabilities": capabilities,
            "healthcheck": requirements.get("healthcheck", ""),
            "install_command": requirements.get("install_command", ""),
            "install_commands": requirements.get("install_commands", []),
            "install_fallbacks": requirements.get("install_fallbacks", []),
            "install_tool": self._install_tool_name(requirements.get("install_tool", "")),
            "install_policy": requirements.get("install_policy", ""),
            "env_file": requirements.get("env_file", ""),
            "tool_name": tool_name,
        }

    def _skill_packages(self, skill_id: str) -> List[str]:
        if not self.skill_manager:
            return []
        return list(self.skill_manager.get_runtime_requirements(skill_id).get("packages", []) or [])

    def _skill_runtime_requirements(self, skill_id: str) -> Dict[str, Any]:
        if not self.skill_manager:
            return {}
        return self.skill_manager.get_runtime_requirements(skill_id)

    def _calder_runtime_allowed(self, selected_skills: Optional[List[str]] = None, env: str = "") -> bool:
        selected = self._selected_skill_ids(selected_skills)
        if any("calder2-subcompartment" in sid or "calder2-compartment" in sid for sid in selected):
            return True
        if self.skill_manager:
            for sid in selected:
                requirements = self._skill_runtime_requirements(sid)
                if self._install_tool_name(requirements.get("install_tool") or "") == "calder_r_runtime":
                    return True
        return str(env or "").strip() == "calder2" and not selected

    def _sanitize_install_tool_for_selected_runtime(
        self,
        tool_name: str,
        selected_skills: Optional[List[str]],
        runtime_defaults: Dict[str, Any],
        requested_env: str = "",
    ) -> Tuple[str, str]:
        requested_tool = self._install_tool_name(tool_name)
        selected = self._selected_skill_ids(selected_skills)
        declared_tool = self._install_tool_name(runtime_defaults.get("install_tool") or runtime_defaults.get("tool_name") or "")
        if selected and declared_tool and requested_tool and requested_tool != declared_tool:
            if requested_tool == "calder_r_runtime" and self._calder_runtime_allowed(selected_skills, requested_env):
                return requested_tool, ""
            note = (
                "[INSTALL TOOL CORRECTION]\n"
                f"- Generated install tag requested `{requested_tool}`, but the selected skill runtime declares `{declared_tool}`.\n"
                "- Do not install undeclared package names inferred from a failed import unless the selected skill runtime contract lists them.\n"
                f"- Replaced install tool with `{declared_tool}`.\n"
            )
            return declared_tool, note
        if requested_tool != "calder_r_runtime":
            return requested_tool or tool_name, ""
        if self._calder_runtime_allowed(selected_skills, requested_env):
            return requested_tool, ""
        replacement = self._install_tool_name(runtime_defaults.get("install_tool") or runtime_defaults.get("tool_name") or "skill_runtime")
        note = (
            "[INSTALL TOOL CORRECTION]\n"
            "- Generated install tag requested `calder_r_runtime`, but the selected skill is not CALDER2.\n"
            "- Ordinary/default A/B compartment calling must use PC1/eigenvector runtime, not CALDER2/Rscript.\n"
            f"- Replaced install tool with `{replacement}`.\n"
        )
        return replacement, note

    def _runtime_owner_skill_for_install(self, tool_name: str, selected_skills: Optional[List[str]]) -> str:
        """Pick the selected skill whose runtime declares the requested install tool."""
        if not self.skill_manager:
            return ""
        normalized = self._selected_skill_ids(selected_skills)
        requested_tool = self._install_tool_name(tool_name)
        for sid in normalized:
            if (
                hasattr(self.skill_manager, "is_workflow_router_skill")
                and self.skill_manager.is_workflow_router_skill(sid)
            ):
                continue
            requirements = self._skill_runtime_requirements(sid)
            if requested_tool and requested_tool == self._install_tool_name(requirements.get("install_tool") or ""):
                return sid
            defaults = self._skill_runtime_defaults([sid])
            if requested_tool and requested_tool == str(defaults.get("tool_name") or "").strip():
                return sid
        if requested_tool == "calder_r_runtime":
            for sid in normalized:
                if "calder2-subcompartment" in sid or "calder2-compartment" in sid:
                    return sid
        return ""

    def _skill_static_default_env(self, skill_id: str) -> str:
        if not self.skill_manager:
            return ""
        meta = self.skill_manager.get_skill_meta(skill_id)
        runtime = meta.get("runtime") or {}
        return str(runtime.get("default_env", "") or "")

    def _record_installed_skill_environment(self, selected_skills: Optional[List[str]], env: str, final_res: str):
        if not self.skill_manager or not env:
            return
        if not re.search(r"(success|complete|ready|✅)", final_res, re.IGNORECASE):
            return
        for sid in self._selected_skill_ids(selected_skills):
            requirements = self._skill_runtime_requirements(sid)
            packages = requirements.get("packages", [])
            capabilities = requirements.get("capabilities", [])
            install_command = requirements.get("install_command", "")
            self.skill_manager.record_environment(
                sid,
                env=env,
                packages=packages,
                install_command=install_command,
                status="installed",
                notes=final_res,
                language=requirements.get("language", ""),
                capabilities=capabilities,
                healthcheck=requirements.get("healthcheck", ""),
            )
            if self.pm:
                self.pm.register_environment(
                    env_name=env,
                    purpose=f"Runtime for skill {sid}",
                    packages=packages,
                    skill_id=sid,
                    notes=final_res,
                    language=requirements.get("language", ""),
                    capabilities=capabilities,
                    healthcheck=requirements.get("healthcheck", ""),
                    status="installed",
                )

    def _ensure_skill_runtime_ready(self, selected_skills: Optional[List[str]], task_id: str = "default", code: str = "") -> tuple:
        if not self.skill_manager or not self.pm:
            return True, ""
        for sid in self._selected_skill_ids(selected_skills):
            requirements = self._skill_runtime_requirements(sid)
            env = requirements.get("env") or requirements.get("default_env", "")
            if not env:
                continue
            if not any([requirements.get("packages"), requirements.get("capabilities"), requirements.get("language"), requirements.get("healthcheck")]):
                continue
            ok, detail, env = self._verify_skill_runtime(sid, task_id=task_id, code=code)
            if not ok:
                redirect_name = self._install_tool_name(requirements.get("install_tool")) or self._skill_runtime_defaults([sid]).get("tool_name", "skill_runtime")
                reason = detail or f"Healthcheck failed for environment {env}"
                redirect_name, ordered_hint = self._runtime_install_target_from_error(reason, redirect_name)
                if redirect_name == "calder_r_runtime" and not self._calder_runtime_allowed([sid], env):
                    redirect_name = self._install_tool_name(requirements.get("install_tool")) or self._skill_runtime_defaults([sid]).get("tool_name", "skill_runtime")
                    ordered_hint = "Ignoring CALDER repair for non-CALDER2 skill; ordinary A/B compartments use PC1/eigenvector runtime."
                if ordered_hint:
                    reason = f"{reason} {ordered_hint}"
                return False, f'{self._install_tool_tag(redirect_name, env)}<!-- {reason} -->'
        return True, ""

    def _record_successful_skill_execution(self, selected_skills: Optional[List[str]], code: str, stdout: str):
        if not self.skill_manager or not selected_skills:
            return
        selected = self._selected_skill_ids(selected_skills)
        if not selected:
            return
        outputs = []
        for match in re.findall(r"[\w./\-\u4e00-\u9fff]+(?:\.png|\.tsv|\.pdf|\.csv)", stdout + "\n" + code):
            outputs.append(match)
        for sid in selected:
            env = self.skill_manager.get_runtime_env(sid)
            script_hit = sid in code
            meta = self.skill_manager.get_skill_meta(sid)
            for script in meta.get("_scripts", []) or []:
                if Path(script).name in code:
                    script_hit = True
                    break
            packages = self._skill_packages(sid)
            import_hits = [
                pkg for pkg in packages
                if re.search(rf"\bimport\b[^\n]*\b{re.escape(pkg)}\b", code, re.IGNORECASE)
            ]
            if not script_hit and packages and len(import_hits) == len(packages):
                requirements = self._skill_runtime_requirements(sid)
                self.skill_manager.record_environment(
                    sid,
                    env=env,
                    packages=packages,
                    status="verified",
                    notes="Dependency preflight import succeeded.",
                    language=requirements.get("language", ""),
                    capabilities=requirements.get("capabilities", []),
                    healthcheck=requirements.get("healthcheck", ""),
                )
                if self.pm and env:
                    self.pm.register_environment(
                        env_name=env,
                        purpose=f"Runtime for skill {sid}",
                        packages=packages,
                        skill_id=sid,
                        notes="Dependency preflight import succeeded.",
                        language=requirements.get("language", ""),
                        capabilities=requirements.get("capabilities", []),
                        healthcheck=requirements.get("healthcheck", ""),
                        status="verified",
                    )
                continue
            if script_hit:
                self.skill_manager.record_successful_run(
                    sid,
                    env=env,
                    command=code,
                    outputs=list(dict.fromkeys(outputs)),
                    notes="Skill command completed with exit code 0.",
                )

    def _install_choice_key(self, task_id: str, tool_name: str) -> str:
        return f"{task_id}::{tool_name}"

    @staticmethod
    def _solution_from_messages(messages: Any) -> str:
        for message in reversed(list(messages or [])):
            content = str(getattr(message, "content", message))
            match = re.search(r"<solution>(.*?)</solution>", content, re.DOTALL | re.IGNORECASE)
            if match:
                return match.group(1).strip()
        return ""

    def _record_profiler_state_update(
        self,
        task_id: str,
        node_name: str,
        state: AgentState,
        update: Any,
    ) -> None:
        if not isinstance(update, dict):
            return
        merged: Dict[str, Any] = dict(state or {})
        for key, value in update.items():
            if key != "messages":
                merged[key] = value

        try:
            durable_plan = load_plan_state(self.data_path, task_id)
            _, current_step = current_plan_step_with_index(durable_plan)
            execution = merged.get("execution_evidence") or {}
            latest_execution = {}
            if isinstance(execution, dict) and execution:
                latest_execution = {
                    key: execution.get(key)
                    for key in (
                        "execution_id", "action_id", "command", "argv", "script_file",
                        "cwd", "returncode", "signal", "language", "trace_file",
                        "plan_version", "task_revision", "step_id", "started_at",
                        "finished_at", "stdout_log", "stderr_log", "declared_outputs",
                        "observed_outputs",
                    )
                    if execution.get(key) not in (None, "", [], {})
                }
            step_states = {
                str(step.get("step_id") or ""): str(step.get("status") or "")
                for step in durable_plan.get("steps", []) or []
                if isinstance(step, dict) and str(step.get("step_id") or "")
            }
            durable_task_state = dict(durable_plan.get("task_state") or {})
            durable_budgets = dict(durable_task_state.get("budgets") or {})
            durable_budgets.update({
                "retry_count": int(merged.get("retry_count") or 0),
                "llm_retry_counts": dict(merged.get("llm_retry_counts") or {}),
                "context": merged.get("context_budget_report") or {},
            })
            recovery_projection = dict(durable_task_state.get("recovery_state") or {})
            if any(key in update for key in (
                "recovery_phase", "recovery_status", "recovery_decision",
                "pending_recovery_action", "recovery_context",
            )):
                node_recovery_projection = {
                    "phase": merged.get("recovery_phase"),
                    "status": merged.get("recovery_status"),
                    "decision": merged.get("recovery_decision") or {},
                    "pending_action": merged.get("pending_recovery_action") or {},
                    "failure_owner": str(merged.get("failure_owner") or ""),
                    "failure_fingerprint": (merged.get("recovery_context") or {}).get("error_fingerprint")
                    if isinstance(merged.get("recovery_context"), dict) else "",
                    "step_id": str(current_step.get("step_id") or ""),
                    "plan_version": str(durable_plan.get("plan_version") or ""),
                }
                # A node-local compatibility projection must never replace the
                # durable one-shot lifecycle that the transition resolver just
                # consumed or superseded.  Keep the old flat fields only for
                # sessions that do not yet have lifecycle state.
                recovery_projection["node_projection"] = node_recovery_projection
                if not any(
                    key in recovery_projection
                    for key in (
                        "active_transition", "transition_history",
                        "last_recovery_decision", "last_consumed_transition",
                    )
                ):
                    recovery_projection.update(node_recovery_projection)
            projected_task_status = task_status(durable_plan)
            explicit_task_status = str(update.get("task_status") or "").strip().lower()
            proposed_route = str(
                update.get("proposed_route")
                or update.get("node_recommended_next_step")
                or update.get("next_step")
                or ""
            )
            effective_route = str(
                update.get("effective_route") or update.get("next_step") or ""
            )
            dispatch_route = str(
                update.get("dispatch_route") or update.get("next_step") or ""
            )
            projected_next = dispatch_route
            projected_phase = str(merged.get("recovery_phase") or "").lower()
            route_projection = {
                "proposed_route": proposed_route,
                "pre_guard_effective_route": str(
                    update.get("pre_guard_effective_route") or effective_route
                ),
                "effective_route": effective_route,
                "dispatch_route": dispatch_route,
                "override_source": str(update.get("override_source") or ""),
                "override_decision_id": str(update.get("override_decision_id") or ""),
                "route_event_id": str(update.get("route_event_id") or ""),
                "current_attempt": str(update.get("current_attempt") or ""),
                "progress_guard_result": (
                    dict(update.get("progress_guard_result") or {})
                    if isinstance(update.get("progress_guard_result"), Mapping)
                    else {}
                ),
            }
            if explicit_task_status in TASK_TERMINAL_STATUSES:
                projected_task_status = explicit_task_status
            elif projected_task_status in TASK_TERMINAL_STATUSES:
                pass
            elif projected_next in {"ask_user", "human_input", "waiting_user"}:
                projected_task_status = TASK_STATUS_WAITING_USER
            elif node_name == "ask_user" and projected_next in {"planner", "generate", "consultant"}:
                projected_task_status = TASK_STATUS_RUNNING
            elif effective_route == "supervisor" and any(
                str(step.get("status") or "") == "verification_pending"
                for step in durable_plan.get("steps", []) or []
                if isinstance(step, Mapping)
            ):
                projected_task_status = TASK_STATUS_RUNNING
            elif projected_phase in {"capture", "unwrap", "diagnose", "probe", "verify"}:
                projected_task_status = TASK_STATUS_DIAGNOSING
            elif projected_phase in {"plan_repair", "apply_repair", "rerun", "rollback"}:
                projected_task_status = TASK_STATUS_REPAIRING
            update_task_state_projection(
                self.data_path,
                task_id,
                {
                    "status": projected_task_status,
                    "user_constraints": list(merged.get("user_constraints") or []),
                    "input_audit": merged.get("input_audit") or {},
                    "selected_skills": list(merged.get("selected_skills") or []),
                    "resolved_bindings": dict(merged.get("resolved_bindings") or {}),
                    "runtime_audit": list(merged.get("runtime_audit") or []),
                    "consultation_state": dict(merged.get("consultation_state") or {}),
                    "binding_phase": dict(merged.get("binding_phase") or {}),
                    "consultant_commit_rejection": dict(
                        merged.get("consultant_commit_rejection") or {}
                    ),
                    "consultant_pending_transition": dict(
                        merged.get("consultant_pending_transition") or {}
                    ),
                    "consultant_no_progress_ledger": dict(
                        merged.get("consultant_no_progress_ledger") or {}
                    ),
                    "step_states": step_states,
                    "current_step_id": str(current_step.get("step_id") or ""),
                    "latest_execution": latest_execution,
                    "diagnosis_state": merged.get("diagnostic_summary") or {},
                    "recovery_state": recovery_projection,
                    "supervisor_state": {
                        "verdict": merged.get("supervisor_verdict"),
                        "feedback": merged.get("last_supervisor_feedback") or {},
                    },
                    "pending_question": merged.get("pending_human_question") or merged.get("pending_question") or {},
                    "budgets": durable_budgets,
                    "last_transition": {
                        "from_node": node_name,
                        "to_node": effective_route,
                        **route_projection,
                        "task_status": projected_task_status,
                        "step_id": str(current_step.get("step_id") or ""),
                        "trigger": proposed_route,
                        "guard": str(update.get("transition_guard") or "allowed"),
                    },
                },
                node=node_name,
                next_step=dispatch_route,
            )
            transition_payload = {
                "from_node": node_name,
                "to_node": effective_route,
                **route_projection,
                "task_status": projected_task_status,
                "step_id": str(current_step.get("step_id") or ""),
                "plan_id": str(durable_plan.get("plan_id") or ""),
                "plan_revision": durable_plan.get("plan_revision"),
                "trigger": proposed_route,
                "guard": str(update.get("transition_guard") or "allowed"),
            }
            ContextLineageStore(self.data_path, task_id).record_event(
                "controller_route",
                transition_payload,
                event_id=(
                    str(update.get("route_event_id") or "")
                    or f"route-{node_name}-{durable_task_state.get('state_version', 0)}-"
                    f"{hashlib.sha256(json.dumps(transition_payload, sort_keys=True, default=str).encode('utf-8')).hexdigest()[:12]}"
                ),
            )
        except Exception as exc:
            logger.warning("Could not persist compact task state after %s: %s", node_name, exc)

        selected = merged.get("selected_skills", []) or []
        active = merged.get("active_skills", []) or []
        future = merged.get("future_skills", []) or []
        candidate = merged.get("candidate_skills", []) or []
        raw = merged.get("selected_skills_raw", []) or []
        handoff = self._workflow_state_from_mapping(merged)
        workflow_id = merged.get("workflow_id") or handoff.get("workflow_id", "")
        active_batch_id = merged.get("active_batch_id") or handoff.get("active_batch_id", "")
        source = merged.get("skill_selection_source", "")
        if any([selected, active, future, candidate, raw, source, workflow_id, active_batch_id]):
            self.profiler.record_skill_selection(
                task_id,
                selected_skills=selected,
                selected_skills_raw=raw,
                active_skills=active,
                future_skills=future,
                candidate_skills=candidate,
                source=str(source or ""),
                workflow_id=str(workflow_id or ""),
                active_batch_id=str(active_batch_id or ""),
                node=node_name,
            )

        if node_name == "supervisor":
            self.profiler.record_supervisor_verdict(
                task_id,
                update.get("supervisor_verdict"),
                retry_count=update.get("retry_count"),
                node=node_name,
            )

        if str(update.get("next_step") or "").strip() == "finish":
            solution = self._solution_from_messages(update.get("messages", []))
            if solution:
                status = "failed" if any(marker in solution for marker in ["❌", "Failed", "failed", "Error"]) else "completed"
                self.profiler.record_final_result(
                    task_id,
                    status=status,
                    output_result=solution,
                    node=node_name,
                )

    @staticmethod
    def _workflow_state_from_mapping(mapping: Optional[Dict[str, Any]]) -> Dict[str, Any]:
        if not isinstance(mapping, dict):
            return {}
        workflow_state = mapping.get("workflow_state")
        if isinstance(workflow_state, dict) and workflow_state:
            return dict(workflow_state)
        workflow_handoff = mapping.get("workflow_handoff")
        if isinstance(workflow_handoff, dict) and workflow_handoff:
            return dict(workflow_handoff)
        return {}

    def _normalize_state_update_aliases(
        self,
        node_name: str,
        state: AgentState,
        update: Any,
    ) -> Any:
        if not isinstance(update, dict):
            return update
        normalized = dict(update)
        # Normalize is projection-only.  It may expose a successfully
        # committed durable TaskSpec, but it never arbitrates between a graph
        # candidate, legacy alias, input audit, and durable state.
        task_spec = self._task_spec_for_state(dict(state))
        if task_spec_is_initialized(task_spec):
            normalized["task_spec"] = deepcopy(task_spec)
            normalized["task_revision"] = task_spec_revision(task_spec)
            effective_facts = resolve_effective_user_facts(task_spec)
            normalized["effective_user_facts_revision"] = effective_facts[
                "effective_facts_revision"
            ]
            if node_name == "consultant":
                normalized.setdefault("normalized_fact_mappings", {
                    key: effective_facts[key]
                    for key in (
                        "active_artifacts", "active_entities", "active_parameters",
                        "active_constraints", "active_decisions", "active_relations",
                        "unresolved_facts",
                    )
                })
                normalized.setdefault("user_source_refs", effective_facts["source_refs"])
        else:
            # An uncommitted candidate must not enter graph truth.  Omitting
            # these keys leaves any prior committed projection unchanged.
            normalized.pop("task_spec", None)
            normalized.pop("task_revision", None)
        constraints = list(state.get("user_constraints", []) or [])
        for constraint in task_spec_constraints(task_spec):
            if constraint not in constraints:
                constraints.append(constraint)
        normalized.setdefault("user_constraints", constraints)
        if str(normalized.get("next_step") or "").strip():
            normalized["node_recommended_next_step"] = str(normalized.get("next_step") or "").strip()
        workflow_state = self._workflow_state_from_mapping(normalized) or self._workflow_state_from_mapping(state)
        if workflow_state:
            normalized.setdefault("workflow_state", workflow_state)
            normalized.setdefault("workflow_handoff", workflow_state)
        if node_name in {"execute", "install_subagent"}:
            normalized.setdefault("pending_action", {})
        task_id = str(normalized.get("task_id") or state.get("task_id") or "")
        trace_refs = [
            *list(state.get("llm_call_refs") or []),
            *list(getattr(self, "_latest_llm_call_refs", {}).get(task_id, []) or []),
        ]
        trace_refs = list({str(item.get("call_id") or index): item for index, item in enumerate(trace_refs) if isinstance(item, dict)}.values())
        if trace_refs:
            normalized["llm_call_refs"] = trace_refs[-50:]
            normalized.setdefault(
                "context_lineage_ref",
                str(Path(self.data_path) / "task_outputs" / task_id / "context_trace"),
            )
            if node_name == "consultant":
                latest = next(
                    (item for item in reversed(trace_refs) if item.get("call_kind") == "consultant"),
                    {},
                )
                if latest.get("call_id"):
                    try:
                        ContextLineageStore(self.data_path, task_id).annotate_call(
                            str(latest["call_id"]),
                            {
                                "candidate_skill_ids": list(
                                    normalized.get("candidate_skills")
                                    or state.get("candidate_skills")
                                    or []
                                ),
                                "selected_skill_ids": list(normalized.get("selected_skills") or []),
                                "skill_versions": self._trace_skill_versions(
                                    list(normalized.get("selected_skills") or [])
                                ),
                                "consult_handoff": self._workflow_state_from_mapping(normalized),
                                "runtime_audit": list(normalized.get("runtime_audit") or []),
                            },
                        )
                    except Exception as exc:  # noqa: BLE001 - tracing cannot change task routing.
                        logger.warning("Could not annotate Consultant lineage snapshot: %s", exc)
        return normalized

    @staticmethod
    def _bounded_protocol_excerpt(
        text: str,
        *,
        position: Optional[int] = None,
        max_chars: int = 1200,
    ) -> str:
        raw = str(text or "")
        if len(raw) <= max_chars:
            return raw
        if position is None:
            return raw[:max_chars]
        center = max(0, min(int(position), len(raw)))
        start = max(0, center - max_chars // 2)
        end = min(len(raw), start + max_chars)
        start = max(0, end - max_chars)
        prefix = "…" if start else ""
        suffix = "…" if end < len(raw) else ""
        return prefix + raw[start:end] + suffix

    @staticmethod
    def _json_value_type(value: Any) -> str:
        if value is None:
            return "null"
        if isinstance(value, bool):
            return "boolean"
        if isinstance(value, str):
            return "string"
        if isinstance(value, Mapping):
            return "object"
        if isinstance(value, (list, tuple)):
            return "array"
        if isinstance(value, (int, float)):
            return "number"
        return type(value).__name__

    @classmethod
    def _extract_json_object_result(
        cls,
        text: str,
    ) -> Tuple[Dict[str, Any], Dict[str, Any], str]:
        """Try all legacy extraction candidates and retain the best parse error."""
        raw = str(text or "").strip()
        if not raw:
            return {}, {
                "stage": "json_decode",
                "code": "JSON_INPUT_EMPTY",
                "message": "The structured action JSON candidate is empty.",
                "raw_excerpt": "",
            }, ""

        candidates: List[str] = []

        def add_candidate(candidate: str) -> None:
            value = str(candidate or "").strip()
            if value and value not in candidates:
                candidates.append(value)

        fenced = re.search(r"```(?:json)?\s*(.*?)```", raw, re.DOTALL | re.IGNORECASE)
        if fenced:
            add_candidate(fenced.group(1))
        add_candidate(raw)
        brace = re.search(r"\{.*\}", raw, re.DOTALL)
        if brace:
            add_candidate(brace.group(0))

        errors: List[Tuple[Dict[str, Any], str]] = []
        for candidate in candidates:
            try:
                parsed = json.loads(candidate)
            except json.JSONDecodeError as exc:
                excerpt = cls._bounded_protocol_excerpt(
                    candidate,
                    position=exc.pos,
                )
                errors.append(({
                    "stage": "json_decode",
                    "code": "JSON_DECODE_ERROR",
                    "message": str(exc.msg or "JSON decoding failed."),
                    "line": int(exc.lineno),
                    "column": int(exc.colno),
                    "position": int(exc.pos),
                    "raw_excerpt": excerpt,
                }, excerpt))
                continue
            except Exception as exc:  # noqa: BLE001 - unexpected parser failures still fail closed.
                excerpt = cls._bounded_protocol_excerpt(candidate)
                errors.append(({
                    "stage": "json_decode",
                    "code": "JSON_PARSE_ERROR",
                    "message": f"{type(exc).__name__}: {exc}",
                    "raw_excerpt": excerpt,
                }, excerpt))
                continue
            if isinstance(parsed, dict):
                return parsed, {}, cls._bounded_protocol_excerpt(candidate)
            excerpt = cls._bounded_protocol_excerpt(candidate)
            errors.append(({
                "stage": "action_schema",
                "code": "ACTION_SCHEMA_TYPE_ERROR",
                "field_path": "$",
                "expected": "object",
                "actual": cls._json_value_type(parsed),
                "message": "The structured action JSON value must be an object.",
            }, excerpt))

        if not errors:
            return {}, {
                "stage": "json_decode",
                "code": "JSON_DECODE_ERROR",
                "message": "No JSON object candidate could be decoded.",
                "raw_excerpt": cls._bounded_protocol_excerpt(raw),
            }, cls._bounded_protocol_excerpt(raw)
        schema_errors = [item for item in errors if item[0].get("stage") == "action_schema"]
        if schema_errors:
            return {}, schema_errors[0][0], schema_errors[0][1]
        best_error, best_candidate = max(
            errors,
            key=lambda item: int(item[0].get("position") or -1),
        )
        return {}, best_error, best_candidate

    @classmethod
    def _extract_json_object(cls, text: str) -> Dict[str, Any]:
        parsed, _, _ = cls._extract_json_object_result(text)
        return parsed

    @staticmethod
    def _recent_nonempty_execute_body(messages: Any, window: int = 3) -> str:
        for message in reversed(list(messages or [])[-window:]):
            if not isinstance(message, AIMessage):
                continue
            content = str(getattr(message, "content", "") or "")
            match = re.search(r"<execute>(.*?)</execute>", content, re.DOTALL)
            if match and match.group(1).strip():
                return match.group(1).strip()
        return ""

    @staticmethod
    def _normalize_action_type(action_type: str) -> str:
        value = str(action_type or "").strip().lower().replace("-", "_")
        aliases = {
            "ask": "ask_user",
            "question": "ask_user",
            "install": "install_tool",
            "finish": "solution",
            "final": "solution",
            "answer": "solution",
            "activate": "activate_batch",
            "invoke_renderer": "renderer_invocation",
            "render": "renderer_invocation",
            "step_complete": "step_completion_candidate",
            "step_completion": "step_completion_candidate",
            "patch_plan": "plan_patch",
            "block": "blocked",
        }
        return aliases.get(value, value)

    @classmethod
    def _structured_action_from_object_result(
        cls,
        obj: Any,
        source: str = "action_json",
    ) -> StructuredActionParseResult:
        candidate = deepcopy(obj)

        def fail(
            code: str,
            message: str,
            *,
            field_path: str = "",
            expected: str = "",
            actual: str = "",
        ) -> StructuredActionParseResult:
            error: Dict[str, Any] = {
                "stage": "action_schema",
                "code": code,
                "message": message,
            }
            if field_path:
                error["field_path"] = field_path
            if expected:
                error["expected"] = expected
            if actual:
                error["actual"] = actual
            return StructuredActionParseResult(error=error, candidate=candidate)

        if not isinstance(obj, dict):
            return fail(
                "ACTION_SCHEMA_TYPE_ERROR",
                "The structured action must be a JSON object.",
                field_path="$",
                expected="object",
                actual=cls._json_value_type(obj),
            )
        raw_action_type = obj.get("action_type") or obj.get("type") or obj.get("action") or ""
        action_type = cls._normalize_action_type(raw_action_type)
        if not action_type:
            return fail(
                "ACTION_SCHEMA_REQUIRED_FIELD",
                "A structured action requires action_type.",
                field_path="action_type",
                expected="supported action type",
                actual="missing",
            )
        supported_action_types = {
            "renderer_invocation", "execute", "ask_user", "search", "install_tool",
            "activate_batch", "step_completion_candidate", "plan_patch", "blocked", "solution",
        }
        if action_type not in supported_action_types:
            return fail(
                "ACTION_SCHEMA_VALUE_ERROR",
                f"Unsupported structured action type: {action_type!r}.",
                field_path="action_type",
                expected="supported action type",
                actual=str(raw_action_type),
            )
        action: Dict[str, Any] = {"type": action_type, "source": source}
        if action_type == "renderer_invocation":
            arguments = obj.get("arguments") or obj.get("args") or {}
            if not isinstance(arguments, (dict, list)):
                return fail(
                    "ACTION_SCHEMA_TYPE_ERROR",
                    "renderer_invocation arguments must be an object or array.",
                    field_path="arguments",
                    expected="object or array",
                    actual=cls._json_value_type(arguments),
                )
            action.update({
                "renderer_id": str(obj.get("renderer_id") or obj.get("renderer") or "").strip(),
                "arguments": arguments,
                "outdir": str(obj.get("outdir") or "").strip(),
            })
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "execute":
            code = str(obj.get("code") or obj.get("body") or obj.get("command") or "").strip()
            argv = obj.get("argv")
            if argv is not None and not isinstance(argv, list):
                return fail(
                    "ACTION_SCHEMA_TYPE_ERROR",
                    "execute.argv must be a list of strings.",
                    field_path="argv",
                    expected="array",
                    actual=cls._json_value_type(argv),
                )
            if isinstance(argv, list) and not argv:
                return fail(
                    "ACTION_SCHEMA_VALUE_ERROR",
                    "execute.argv must not be empty when provided.",
                    field_path="argv",
                    expected="non-empty array",
                    actual="empty array",
                )
            if isinstance(argv, list):
                for index, item in enumerate(argv):
                    if not isinstance(item, str):
                        return fail(
                            "ACTION_SCHEMA_TYPE_ERROR",
                            "execute.argv items must be strings.",
                            field_path=f"argv[{index}]",
                            expected="string",
                            actual=cls._json_value_type(item),
                        )
                    if not item:
                        return fail(
                            "ACTION_SCHEMA_VALUE_ERROR",
                            "execute.argv items must be non-empty strings.",
                            field_path=f"argv[{index}]",
                            expected="non-empty string",
                            actual="empty string",
                        )
            if not code and not argv:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "execute requires non-empty code or argv.",
                    field_path="argv",
                    expected="non-empty code or argv",
                    actual="missing",
                )
            raw_outputs = obj.get("outputs") or []
            if isinstance(raw_outputs, str):
                raw_outputs = [raw_outputs]
            if not isinstance(raw_outputs, list):
                return fail(
                    "ACTION_SCHEMA_TYPE_ERROR",
                    "execute.outputs must be an array or string.",
                    field_path="outputs",
                    expected="array or string",
                    actual=cls._json_value_type(raw_outputs),
                )
            env = obj.get("env") if "env" in obj else {}
            if env is None:
                env = {}
            if not isinstance(env, Mapping):
                return fail(
                    "ACTION_SCHEMA_TYPE_ERROR",
                    "execute.env must be an object of string values.",
                    field_path="env",
                    expected="object",
                    actual=cls._json_value_type(env),
                )
            for key, value in env.items():
                if not isinstance(key, str) or not key:
                    return fail(
                        "ACTION_SCHEMA_TYPE_ERROR",
                        "execute.env keys must be non-empty strings.",
                        field_path="env",
                        expected="non-empty string keys",
                        actual=cls._json_value_type(key),
                    )
                if not isinstance(value, str):
                    return fail(
                        "ACTION_SCHEMA_TYPE_ERROR",
                        "execute.env values must be strings.",
                        field_path=f"env.{key}",
                        expected="string",
                        actual=cls._json_value_type(value),
                    )
            action.update({
                "code": code,
                "argv": deepcopy(argv) if isinstance(argv, list) else [],
                "env": deepcopy(dict(env)),
                "outputs": [str(item) for item in raw_outputs if str(item).strip()],
                "language": str(obj.get("language") or "").strip(),
            })
            purpose = str(obj.get("purpose") or "").strip().lower()
            if purpose in {"analysis", "probe", "validation", "record_failure"}:
                action["purpose"] = purpose
            command_role = str(obj.get("command_role") or obj.get("action_kind") or "").strip().lower()
            command_role = {
                "verification": "required_validation",
                "recovery": "recovery",
            }.get(command_role, command_role)
            if command_role in {
                "primary", "diagnostic", "required_validation", "optional_probe", "fallback", "recovery",
                "renderer_invocation",
            }:
                action["command_role"] = command_role
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "ask_user":
            question = str(obj.get("question") or obj.get("body") or obj.get("prompt") or "").strip()
            if not question:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "ask_user requires question.",
                    field_path="question",
                    expected="non-empty string",
                    actual="missing",
                )
            action["question"] = question
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "search":
            query = str(obj.get("query") or obj.get("question") or obj.get("body") or "").strip()
            if not query:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "search requires query.",
                    field_path="query",
                    expected="non-empty string",
                    actual="missing",
                )
            action["query"] = query
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "install_tool":
            tool = str(obj.get("tool") or obj.get("tool_name") or obj.get("body") or "").strip()
            if not tool:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "install_tool requires tool.",
                    field_path="tool",
                    expected="non-empty string",
                    actual="missing",
                )
            action.update({"tool": tool, "env": str(obj.get("env") or "").strip()})
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "activate_batch":
            batch_id = str(obj.get("batch_id") or obj.get("batch") or "").strip()
            if not batch_id:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "activate_batch requires batch_id.",
                    field_path="batch_id",
                    expected="non-empty string",
                    actual="missing",
                )
            action["batch_id"] = batch_id
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "step_completion_candidate":
            step_id = str(obj.get("step_id") or "").strip()
            reason = str(obj.get("reason") or obj.get("body") or "").strip()
            raw_evidence_ids = obj.get("evidence_ids") or obj.get("evidence_id") or []
            if isinstance(raw_evidence_ids, str):
                raw_evidence_ids = [raw_evidence_ids]
            evidence_ids = [
                str(item).strip()
                for item in raw_evidence_ids
                if str(item).strip()
            ]
            if not step_id or not reason or not evidence_ids:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "step_completion_candidate requires step_id, reason, and evidence_ids.",
                    field_path="step_completion_candidate",
                    expected="step_id, reason, and evidence_ids",
                    actual="one or more fields missing",
                )
            action.update({"step_id": step_id, "reason": reason, "evidence_ids": evidence_ids})
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "plan_patch":
            reason = str(obj.get("reason") or obj.get("body") or "").strip()
            if not reason:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "plan_patch requires reason.",
                    field_path="reason",
                    expected="non-empty string",
                    actual="missing",
                )
            action.update({
                "reason": reason,
                "patch": obj.get("patch") or {},
                "failure_owner": str(obj.get("failure_owner") or "").strip().upper(),
            })
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "blocked":
            reason = str(obj.get("reason") or obj.get("body") or "").strip()
            if not reason:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "blocked requires reason.",
                    field_path="reason",
                    expected="non-empty string",
                    actual="missing",
                )
            raw_missing = obj.get("missing_evidence") or obj.get("evidence") or []
            if isinstance(raw_missing, str):
                raw_missing = [raw_missing]
            action.update({
                "reason": reason,
                "missing_evidence": [str(item).strip() for item in raw_missing if str(item).strip()],
            })
            return StructuredActionParseResult(action=action, candidate=candidate)
        if action_type == "solution":
            text = str(obj.get("text") or obj.get("answer") or obj.get("body") or "").strip()
            if not text:
                return fail(
                    "ACTION_SCHEMA_REQUIRED_FIELD",
                    "solution requires text.",
                    field_path="text",
                    expected="non-empty string",
                    actual="missing",
                )
            action["text"] = text
            return StructuredActionParseResult(action=action, candidate=candidate)
        return fail(
            "ACTION_SCHEMA_VALUE_ERROR",
            f"Unsupported structured action type: {action_type!r}.",
            field_path="action_type",
            expected="supported action type",
            actual=action_type,
        )

    @classmethod
    def _structured_action_from_object(cls, obj: Dict[str, Any], source: str = "action_json") -> Dict[str, Any]:
        return cls._structured_action_from_object_result(obj, source=source).action

    @classmethod
    def _extract_structured_action_result(cls, text: str) -> StructuredActionParseResult:
        raw = str(text or "").strip()
        if not raw:
            return StructuredActionParseResult(error={
                "stage": "action_schema",
                "code": "ACTION_SCHEMA_REQUIRED_FIELD",
                "field_path": "$",
                "expected": "structured action",
                "actual": "empty response",
                "message": "Generate returned an empty response instead of a structured action.",
            })

        json_candidates: List[str] = []
        for match in re.finditer(r"<action_json>(.*?)</action_json>", raw, re.DOTALL | re.IGNORECASE):
            json_candidates.append(match.group(1).strip())
        fenced = re.search(r"```(?:json)?\s*(.*?)```", raw, re.DOTALL | re.IGNORECASE)
        if fenced:
            json_candidates.append(fenced.group(1).strip())
        if raw.startswith("{"):
            json_candidates.append(raw)
        parse_failures: List[StructuredActionParseResult] = []
        for candidate in json_candidates:
            obj, json_error, raw_candidate = cls._extract_json_object_result(candidate)
            if obj or (not json_error and bool(raw_candidate)):
                result = cls._structured_action_from_object_result(obj)
                if result.succeeded:
                    return StructuredActionParseResult(
                        action=result.action,
                        candidate=result.candidate,
                        raw_candidate=raw_candidate,
                    )
                parse_failures.append(StructuredActionParseResult(
                    error=result.error,
                    candidate=result.candidate,
                    raw_candidate=raw_candidate,
                ))
            elif json_error:
                parse_failures.append(StructuredActionParseResult(
                    error=json_error,
                    raw_candidate=raw_candidate,
                ))

        execute_match = re.search(r"<execute>(.*?)</execute>", raw, re.DOTALL | re.IGNORECASE)
        if execute_match and execute_match.group(1).strip():
            code = execute_match.group(1).strip()
            return StructuredActionParseResult(action={
                "type": "execute", "code": code,
                "language": detect_script_language(code), "source": "xml",
            }, raw_candidate=cls._bounded_protocol_excerpt(raw))
        ask_match = re.search(r"<ask_user>(.*?)</ask_user>", raw, re.DOTALL | re.IGNORECASE)
        if ask_match and ask_match.group(1).strip():
            return StructuredActionParseResult(action={
                "type": "ask_user", "question": ask_match.group(1).strip(), "source": "xml",
            }, raw_candidate=cls._bounded_protocol_excerpt(raw))
        search_match = re.search(r"<search>(.*?)</search>", raw, re.DOTALL | re.IGNORECASE)
        if search_match and search_match.group(1).strip():
            return StructuredActionParseResult(action={
                "type": "search", "query": search_match.group(1).strip(), "source": "xml",
            }, raw_candidate=cls._bounded_protocol_excerpt(raw))
        install_match = re.search(
            r"<install_tool(?:\s+env=[\"'](.*?)[\"'])?>(.*?)</install_tool>",
            raw,
            re.DOTALL | re.IGNORECASE,
        )
        if install_match and install_match.group(2).strip():
            return StructuredActionParseResult(action={
                "type": "install_tool",
                "env": str(install_match.group(1) or "").strip(),
                "tool": install_match.group(2).strip(),
                "source": "xml",
            }, raw_candidate=cls._bounded_protocol_excerpt(raw))
        activate_match = re.search(
            r"<activate_batch\s+batch_id=[\"']?([^\"'\s>/]+)[\"']?\s*/?>",
            raw,
            re.DOTALL | re.IGNORECASE,
        )
        if activate_match and activate_match.group(1).strip():
            return StructuredActionParseResult(action={
                "type": "activate_batch", "batch_id": activate_match.group(1).strip(), "source": "xml",
            }, raw_candidate=cls._bounded_protocol_excerpt(raw))
        solution_match = re.search(r"<solution>(.*?)</solution>", raw, re.DOTALL | re.IGNORECASE)
        if solution_match and solution_match.group(1).strip():
            return StructuredActionParseResult(action={
                "type": "solution", "text": solution_match.group(1).strip(), "source": "xml",
            }, raw_candidate=cls._bounded_protocol_excerpt(raw))
        if parse_failures:
            schema_failures = [
                item for item in parse_failures
                if str(item.error.get("stage") or "") == "action_schema"
            ]
            if schema_failures:
                return schema_failures[0]
            return max(
                parse_failures,
                key=lambda item: int(item.error.get("position") or -1),
            )
        return StructuredActionParseResult(
            error={
                "stage": "action_schema",
                "code": "ACTION_SCHEMA_REQUIRED_FIELD",
                "field_path": "$",
                "expected": "one supported structured action",
                "actual": "unrecognized response",
                "message": "Generate returned no supported structured action.",
            },
            raw_candidate=cls._bounded_protocol_excerpt(raw),
        )

    @classmethod
    def _extract_structured_action(cls, text: str) -> Dict[str, Any]:
        return cls._extract_structured_action_result(text).action

    @classmethod
    def _consultant_command_from_json(cls, text: str) -> str:
        """Normalize Consultant JSON action output into the legacy command protocol."""
        raw = str(text or "").strip()
        if not raw:
            return ""

        json_candidates: List[str] = []
        for match in re.finditer(r"<action_json>(.*?)</action_json>", raw, re.DOTALL | re.IGNORECASE):
            json_candidates.append(match.group(1).strip())
        fenced = re.search(r"```(?:json)?\s*(.*?)```", raw, re.DOTALL | re.IGNORECASE)
        if fenced:
            json_candidates.append(fenced.group(1).strip())
        if raw.startswith("{"):
            json_candidates.append(raw)

        for candidate in json_candidates:
            obj = cls._extract_json_object(candidate)
            if not obj:
                continue
            action_type = str(
                obj.get("action_type") or obj.get("type") or obj.get("action") or ""
            ).strip().lower().replace("-", "_")
            action_type = {
                "ask_user": "ask",
                "question": "ask",
                "final": "finish",
                "solution": "finish",
                "answer": "finish",
                "load_workflow": "load_workflow_template",
                "workflow_template": "load_workflow_template",
                "load_skill": "load_skill_doc",
                "skill_doc": "load_skill_doc",
                "load_ref": "load_reference",
            }.get(action_type, action_type)

            if action_type == "execute":
                code = str(obj.get("code") or obj.get("command") or obj.get("body") or "").strip()
                if code:
                    language = str(obj.get("language") or "bash").strip().lower()
                    fence = "python" if "python" in language else "bash"
                    return f"EXECUTE\n```{fence}\n{code}\n```"
            if action_type == "search":
                query = str(obj.get("query") or obj.get("body") or obj.get("question") or "").strip()
                kb = str(obj.get("kb") or obj.get("kb_name") or obj.get("category") or "SOP").strip().upper()
                if query:
                    return f"SEARCH {kb} {query}"
            if action_type == "search_skills":
                query = str(obj.get("query") or obj.get("body") or "").strip()
                queries = obj.get("queries") or []
                if query or (isinstance(queries, list) and queries):
                    return f"SEARCH_SKILLS {query}".rstrip()
            if action_type == "list_skill_categories":
                return "LIST_SKILL_CATEGORIES"
            if action_type == "list_skills":
                category = str(obj.get("category") or obj.get("domain") or "all").strip()
                return f"LIST_SKILLS {category or 'all'}"
            if action_type == "select_skill":
                selected = obj.get("selected_skills") or obj.get("skills") or []
                if isinstance(selected, str):
                    selected = [
                        item.strip() for item in re.split(r"[,，;\n]+", selected)
                        if item.strip()
                    ]
                if isinstance(selected, list) and selected:
                    return "SELECT_SKILL " + ",".join(
                        str(item).strip() for item in selected if str(item).strip()
                    )
            if action_type == "reject_skill":
                skill_id = str(obj.get("skill_id") or obj.get("id") or "").strip()
                if skill_id:
                    return f"REJECT_SKILL {skill_id}"
            if action_type == "reasoning_escalation":
                return "REASONING_ESCALATION"
            if action_type == "capability_gap":
                return "CAPABILITY_GAP"
            if action_type == "load_workflow_template":
                workflow_id = str(obj.get("workflow_id") or obj.get("id") or obj.get("body") or "").strip()
                if workflow_id:
                    return f"LOAD_WORKFLOW_TEMPLATE {workflow_id}"
            if action_type == "load_skill_doc":
                skill_ids = obj.get("skill_ids") or []
                if isinstance(skill_ids, str):
                    skill_ids = [skill_ids]
                if not isinstance(skill_ids, list):
                    skill_ids = []
                skill_id = str(
                    obj.get("skill_id")
                    or obj.get("canonical_skill_id")
                    or obj.get("id")
                    or obj.get("body")
                    or ""
                ).strip()
                normalized_ids = list(dict.fromkeys([
                    *([skill_id] if skill_id else []),
                    *[
                        str(item).strip() for item in skill_ids
                        if str(item).strip()
                    ],
                ]))
                if normalized_ids:
                    return "LOAD_SKILL_DOC " + ",".join(normalized_ids)
            if action_type == "load_reference":
                skill_id = str(obj.get("skill_id") or "").strip()
                path = str(obj.get("path") or obj.get("reference_path") or obj.get("body") or "").strip()
                if skill_id and path:
                    return f"LOAD_REFERENCE {skill_id} {path}"
            if action_type == "load_script":
                skill_id = str(obj.get("skill_id") or "").strip()
                path = str(obj.get("path") or obj.get("script_path") or obj.get("body") or "").strip()
                if skill_id and path:
                    return f"LOAD_SCRIPT {skill_id} {path}"
            if action_type == "ask":
                question = str(obj.get("question") or obj.get("body") or obj.get("prompt") or "").strip()
                if question:
                    return f"ASK {question}"
            if action_type == "finish":
                summary = str(obj.get("summary") or obj.get("text") or obj.get("body") or "").strip()
                selected = obj.get("selected_skills") or obj.get("skills") or []
                if isinstance(selected, str):
                    selected = [item.strip() for item in re.split(r"[,，;\n]+", selected) if item.strip()]
                if isinstance(selected, list) and selected and "[SELECTED_SKILLS:" not in summary:
                    selected_text = ", ".join(str(item).strip() for item in selected if str(item).strip())
                    if selected_text:
                        summary = (f"[SELECTED_SKILLS: {selected_text}]\n\n" + summary).strip()
                if summary:
                    return "FINISH " + summary
        return ""

    @classmethod
    def _consultant_json_payload(cls, text: str) -> Dict[str, Any]:
        """Return the original Consultant action object without dropping IR fields."""
        raw = str(text or "").strip()
        candidates: List[str] = [
            match.group(1).strip()
            for match in re.finditer(r"<action_json>(.*?)</action_json>", raw, re.DOTALL | re.IGNORECASE)
        ]
        fenced = re.search(r"```(?:json)?\s*(.*?)```", raw, re.DOTALL | re.IGNORECASE)
        if fenced:
            candidates.append(fenced.group(1).strip())
        if raw.startswith("{"):
            candidates.append(raw)
        for candidate in candidates:
            obj = cls._extract_json_object(candidate)
            if isinstance(obj, dict) and obj:
                return obj
        return {}

    @staticmethod
    def _consultant_task_spec_mutation_proposal(
        payload: Mapping[str, Any],
        binding: Any,
    ) -> Dict[str, Any]:
        """Translate the finite public mutation ABI into Controller IR.

        This is schema translation and evidence-handle resolution only.  It
        deliberately does not parse user prose, infer file roles, or invent
        biological meaning.
        """
        raw_operations = payload.get("task_spec_operations", [])
        if not isinstance(raw_operations, list):
            raise ValueError("TASKSPEC_MUTATION_STRUCTURE_INVALID: task_spec_operations must be a list")
        aliases = {
            "add_input": "upsert_input",
            "replace_input": "upsert_input",
            "add_output_contract": "upsert_output_contract",
            "replace_output_contract": "upsert_output_contract",
            "add_requirement": "upsert_constraint",
            "replace_requirement": "upsert_constraint",
            "remove_requirement": "remove_constraint",
            "supersede_decision": "confirm_decision",
        }
        nested_field = {
            "upsert_input": "input",
            "upsert_constraint": "constraint",
            "upsert_output_contract": "output_contract",
            "confirm_decision": "decision",
            "mark_ambiguity": "ambiguity",
        }
        normalized: List[Dict[str, Any]] = []
        all_source_refs: List[str] = []
        for index, raw in enumerate(raw_operations):
            if not isinstance(raw, Mapping):
                raise ValueError(
                    f"TASKSPEC_MUTATION_STRUCTURE_INVALID: operation {index} must be an object"
                )
            public_kind = str(raw.get("operation") or raw.get("op") or "").strip().lower()
            kind = aliases.get(public_kind, public_kind)
            operation: Dict[str, Any] = {
                "op": kind,
                "reason": str(raw.get("reason") or "consultant_semantic_proposal"),
            }
            handles = raw.get("supporting_evidence", raw.get("supporting_handles", []))
            if not handles and str(raw.get("source_turn") or "").strip():
                handles = [str(raw.get("source_turn") or "").strip()]
            if not isinstance(handles, list) or not all(isinstance(item, str) for item in handles):
                raise ValueError(
                    "TASKSPEC_MUTATION_STRUCTURE_INVALID: supporting_evidence must be a handle list"
                )
            resolved = resolve_response_handles(
                binding,
                handles,
                object_type="evidence",
                usage="cite",
            ) if handles else []
            source_refs = [str(item.get("stable_identity") or "") for item in resolved]
            source_refs = [value for value in source_refs if value]
            all_source_refs.extend(source_refs)
            operation["supporting_evidence"] = source_refs

            if kind == "set_goal":
                operation["value"] = raw.get("value", raw.get("goal"))
            elif kind in nested_field:
                field = nested_field[kind]
                value = raw.get(field)
                if not isinstance(value, Mapping):
                    semantic_key = str(raw.get("semantic_key") or raw.get("role") or "").strip()
                    if kind == "upsert_input":
                        value = {
                            "role": semantic_key,
                            "path": raw.get("value"),
                            "required": bool(raw.get("required", True)),
                        }
                    elif kind == "upsert_output_contract":
                        value = {
                            "role": semantic_key,
                            "path": raw.get("value"),
                            "required": bool(raw.get("required", True)),
                        }
                    elif kind == "upsert_constraint":
                        value = {
                            "value": raw.get("value"),
                            "strength": raw.get("strength") or raw.get("level") or "required",
                        }
                        if str(raw.get("requirement_id") or "").strip():
                            value["requirement_id"] = str(raw["requirement_id"]).strip()
                    else:
                        value = {
                            "semantic_key": semantic_key,
                            "value": raw.get("value"),
                        }
                value = deepcopy(dict(value))
                if kind == "upsert_constraint":
                    declared_key = str(value.get("semantic_key") or "").strip().lower()
                    typed_policy = bool(
                        declared_key.startswith("failure_policy.")
                        or declared_key == "forbidden_behavior.runtime_install"
                    )
                    if not typed_policy:
                        value = {
                            key: deepcopy(value.get(key))
                            for key in (
                                "requirement_id", "value", "strength", "level",
                                "ambiguity", "needs_clarification",
                                "unresolved_reason", "status",
                            )
                            if value.get(key) not in (None, "", [], {})
                        }
                if source_refs:
                    value.setdefault("source_ref", source_refs[0])
                    value.setdefault("source_id", source_refs[0])
                    value.setdefault("source_type", "user_explicit")
                    value.setdefault("source", "user_explicit")
                    value.setdefault("provenance", [{
                        "source_id": source_refs[0],
                        "source_type": "user_explicit",
                    }])
                operation[field] = value
            elif kind == "remove_input" or kind == "remove_output_contract":
                operation["role"] = raw.get("role") or raw.get("semantic_key")
            elif kind == "remove_constraint":
                requirement_id = raw.get("requirement_id")
                if requirement_id:
                    operation["requirement_id"] = requirement_id
                else:
                    operation["constraint_id"] = (
                        raw.get("constraint_id") or raw.get("semantic_key")
                    )
            elif kind == "remove_decision":
                operation["semantic_key"] = raw.get("semantic_key")
            else:
                # The closed IR validator owns the authoritative allow-list
                # and emits the stable forbidden-operation error.
                operation.update({
                    key: deepcopy(value)
                    for key, value in raw.items()
                    if key not in {
                        "operation", "op", "supporting_evidence",
                        "supporting_handles", "source_turn",
                    }
                })
            normalized.append(operation)
        unresolved = payload.get("unresolved_ambiguities", [])
        if not isinstance(unresolved, list):
            raise ValueError("TASKSPEC_MUTATION_STRUCTURE_INVALID: unresolved_ambiguities must be a list")
        return {
            "proposal_type": "task_spec_mutation",
            "schema_version": 1,
            "operations": normalized,
            "unresolved_ambiguities": deepcopy(unresolved),
            "proposal_evidence_refs": list(dict.fromkeys(all_source_refs)),
        }

    @staticmethod
    def _consultant_planner_feedback_proposal(
        payload: Mapping[str, Any],
        binding: Any,
    ) -> Dict[str, Any]:
        """Validate typed plan-level feedback without interpreting user prose."""
        raw = payload.get("planner_feedback")
        if raw in (None, "", [], {}):
            return {}
        if not isinstance(raw, Mapping):
            raise ValueError("PLANNER_FEEDBACK_PROPOSAL_INVALID: expected object")
        allowed = {"instructions", "supporting_evidence"}
        if set(raw) - allowed:
            raise ValueError("PLANNER_FEEDBACK_PROPOSAL_INVALID: unexpected fields")
        instructions = raw.get("instructions")
        if not isinstance(instructions, list) or not instructions or not all(
            isinstance(item, str) and item.strip() for item in instructions
        ):
            raise ValueError(
                "PLANNER_FEEDBACK_PROPOSAL_INVALID: instructions must be a non-empty string list"
            )
        handles = raw.get("supporting_evidence") or []
        if not isinstance(handles, list) or not handles or not all(
            isinstance(item, str) and item.strip() for item in handles
        ):
            raise ValueError(
                "PLANNER_FEEDBACK_PROPOSAL_INVALID: supporting_evidence is required"
            )
        resolved = resolve_response_handles(
            binding,
            handles,
            object_type="evidence",
            usage="cite",
        )
        return {
            "schema_version": 1,
            "instructions": [str(item).strip() for item in instructions],
            "source_refs": [
                str(item.get("stable_identity") or "") for item in resolved
                if str(item.get("stable_identity") or "")
            ],
            "status": "pending",
        }

    @classmethod
    def _consultant_action_contract_error(
        cls,
        text: str,
        payload: Optional[Mapping[str, Any]] = None,
    ) -> Tuple[str, str]:
        """Return a stable error code and field-specific repair instruction.

        Consultant actions deliberately use a single-command ABI.  Richer command
        graph shapes belong to Planner/Generate and must not be silently flattened
        here because doing so would discard runner, environment, ordering, and
        confirmation semantics.
        """
        raw = str(text or "").strip()
        if re.search(r"<\s*tool_result\b", raw, re.IGNORECASE):
            return (
                "CONTROLLER_EVIDENCE_ECHO",
                "tool_result is controller-owned evidence and cannot be emitted by Consultant. "
                "Return one supported action_json object; for a read-only probe use the exact "
                "single-command execute schema shown below.",
            )

        obj = dict(payload or cls._consultant_json_payload(raw) or {})
        action_type = cls._normalize_action_type(
            obj.get("action_type") or obj.get("type") or obj.get("action") or ""
        )
        if action_type == "execute" and not str(
            obj.get("code") or obj.get("command") or obj.get("body") or ""
        ).strip():
            if obj.get("command_groups") is not None:
                return (
                    "ACTION_FORMAT_INVALID",
                    "execute.command_groups is unsupported in Consultant. execute.code is required "
                    "and must contain exactly one bounded read-only shell script. Do not emit "
                    "commands, command_groups, runner, or env fields.",
                )
            return (
                "ACTION_FORMAT_INVALID",
                "execute.code is required and must contain exactly one bounded read-only shell script.",
            )
        return (
            "ACTION_FORMAT_INVALID",
            "Consultant response did not use any supported action format.",
        )

    @staticmethod
    def _consultant_verified_loaded_skill_ids(messages: Sequence[BaseMessage]) -> List[str]:
        """Read canonical skill IDs only from successful controller load evidence."""
        loaded: List[str] = []
        pattern = re.compile(
            r'<loaded_skill_(?:doc|reference|script)\b[^>]*\bskill_id=["\']([^"\']+)["\']',
            re.IGNORECASE,
        )
        for message in messages or []:
            if not isinstance(message, SystemMessage):
                continue
            for match in pattern.finditer(str(message.content or "")):
                skill_id = match.group(1).strip()
                if skill_id and skill_id not in loaded:
                    loaded.append(skill_id)
        return loaded

    @staticmethod
    def _consultant_payload_hash(payload: Dict[str, Any]) -> str:
        canonical = json.dumps(
            payload or {},
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    @staticmethod
    def _consultant_errors_by_field(errors: List[Dict[str, Any]]) -> Dict[str, List[int]]:
        grouped: Dict[str, List[int]] = {}
        for error in errors or []:
            if not isinstance(error, dict):
                continue
            field = str(error.get("field") or "unknown").strip() or "unknown"
            try:
                index = int(error.get("index", -1))
            except (TypeError, ValueError):
                index = -1
            grouped.setdefault(field, [])
            if index not in grouped[field]:
                grouped[field].append(index)
        return {field: sorted(indexes) for field, indexes in sorted(grouped.items())}

    @classmethod
    def _consultant_contract_repair_state(
        cls,
        payload: Dict[str, Any],
        errors: List[Dict[str, Any]],
        previous: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Checkpoint an immutable first payload plus the current repair base."""
        previous = dict(previous or {})
        base = deepcopy(dict(payload or {}))
        payload_hash = cls._consultant_payload_hash(base)
        original_payload = deepcopy(
            previous.get("original_payload")
            if isinstance(previous.get("original_payload"), dict)
            else base
        )
        initial_payload_hash = str(previous.get("initial_payload_hash") or "").strip()
        if not initial_payload_hash:
            initial_payload_hash = cls._consultant_payload_hash(original_payload)
        allowed_fields: Dict[str, List[str]] = {}
        allowed_payload_fields: List[str] = []
        for error in errors or []:
            if not isinstance(error, dict):
                continue
            field = str(error.get("field") or "").strip()
            try:
                index = int(error.get("index", -1))
            except (TypeError, ValueError):
                index = -1
            if not field:
                continue
            if index < 0:
                if field not in allowed_payload_fields:
                    allowed_payload_fields.append(field)
                continue
            key = str(index)
            allowed_fields.setdefault(key, [])
            if field not in allowed_fields[key]:
                allowed_fields[key].append(field)
        for fields in allowed_fields.values():
            fields.sort()
        return {
            "schema_version": 2,
            "original_payload": original_payload,
            "base_payload": base,
            "payload_hash": payload_hash,
            "initial_payload_hash": initial_payload_hash,
            "validation_errors": deepcopy(list(errors or [])),
            "error_count": len(errors or []),
            "errors_by_field": cls._consultant_errors_by_field(list(errors or [])),
            "allowed_fields_by_index": allowed_fields,
            "allowed_payload_fields": sorted(allowed_payload_fields),
            "repair_attempt": int(previous.get("repair_attempt") or 0) + 1,
        }

    @classmethod
    def _apply_consultant_contract_repair(
        cls,
        repair_state: Dict[str, Any],
        repair_payload: Dict[str, Any],
    ) -> Dict[str, Any]:
        """Apply a hash-bound field patch without permitting schema drift."""
        state = dict(repair_state or {})
        proposal = dict(repair_payload or {})
        errors: List[Dict[str, Any]] = []
        current_base = state.get("base_payload")
        if not isinstance(current_base, dict):
            # Compatibility with repair checkpoints written before schema v2.
            current_base = state.get("original_payload")
        base = deepcopy(dict(current_base or {}))
        unmodified_base = deepcopy(base)
        expected_hash = str(state.get("payload_hash") or "").strip()
        actual_hash = cls._consultant_payload_hash(base)
        action_type = str(
            proposal.get("action_type") or proposal.get("type") or proposal.get("action") or ""
        ).strip().lower().replace("-", "_")
        if action_type != "repair_finish":
            errors.append({
                "index": -1,
                "field": "action_type",
                "reason": "active contract repair accepts only action_type=repair_finish",
            })
        if not expected_hash or actual_hash != expected_hash:
            errors.append({
                "index": -1,
                "field": "base_payload_hash",
                "reason": "controller repair base hash is missing or inconsistent",
            })
        supplied_hash = str(proposal.get("base_payload_hash") or "").strip()
        if supplied_hash != expected_hash:
            errors.append({
                "index": -1,
                "field": "base_payload_hash",
                "reason": "base_payload_hash does not match the controller-owned payload",
            })

        allowed_fields = {
            str(index): {str(field) for field in fields or [] if str(field).strip()}
            for index, fields in (state.get("allowed_fields_by_index") or {}).items()
        }
        constraints = base.get("semantic_constraints")
        if not isinstance(constraints, list):
            constraints = []
        applied: List[Dict[str, Any]] = []
        seen_targets: set[tuple[int, str]] = set()
        patches = proposal.get("constraint_patches")
        if patches is None:
            patches = []
        if not isinstance(patches, list):
            errors.append({"index": -1, "field": "constraint_patches", "reason": "must be a JSON array"})
            patches = []
        for patch in patches:
            if not isinstance(patch, dict):
                errors.append({"index": -1, "field": "constraint_patches", "reason": "each patch must be an object"})
                continue
            raw_index = patch.get("index")
            if isinstance(raw_index, bool):
                index = -1
            else:
                try:
                    index = int(raw_index)
                except (TypeError, ValueError):
                    index = -1
            changes = patch.get("set")
            if index < 0 or index >= len(constraints):
                errors.append({"index": index, "field": "index", "reason": "constraint patch index is out of range"})
                continue
            if not isinstance(changes, dict) or not changes:
                errors.append({"index": index, "field": "set", "reason": "constraint patch set must be a non-empty object"})
                continue
            permitted = allowed_fields.get(str(index), set())
            for field, value in changes.items():
                field_name = str(field).strip()
                if field_name not in permitted:
                    errors.append({
                        "index": index,
                        "field": field_name or "set",
                        "reason": "field was not reported by deterministic validation and cannot be patched",
                    })
                    continue
                target = (index, field_name)
                if target in seen_targets:
                    errors.append({"index": index, "field": field_name, "reason": "duplicate patch target"})
                    continue
                seen_targets.add(target)
                if field_name == "constraint":
                    if not isinstance(value, dict):
                        errors.append({"index": index, "field": field_name, "reason": "replacement constraint must be an object"})
                        continue
                    constraints[index] = deepcopy(value)
                    applied.append({"index": index, "field": field_name})
                    continue
                if not isinstance(constraints[index], dict):
                    errors.append({"index": index, "field": "constraint", "reason": "repair base row is not an object"})
                    continue
                constraints[index][field_name] = deepcopy(value)
                applied.append({"index": index, "field": field_name})

        base["semantic_constraints"] = constraints
        payload_set = proposal.get("set")
        if payload_set is not None:
            if not isinstance(payload_set, dict) or not payload_set:
                errors.append({"index": -1, "field": "set", "reason": "payload set must be a non-empty object"})
            else:
                allowed_payload = {
                    str(field) for field in state.get("allowed_payload_fields", []) or []
                }
                for field, value in payload_set.items():
                    field_name = str(field).strip()
                    if field_name not in allowed_payload:
                        errors.append({
                            "index": -1,
                            "field": field_name or "set",
                            "reason": "top-level field was not reported by deterministic validation",
                        })
                        continue
                    base[field_name] = deepcopy(value)
                    applied.append({"index": -1, "field": field_name})
        if not applied and not errors:
            errors.append({"index": -1, "field": "constraint_patches", "reason": "repair did not modify an allowed field"})
        if errors:
            return {"valid": False, "payload": unmodified_base, "errors": errors, "applied": []}
        base["action_type"] = "finish"
        return {"valid": True, "payload": base, "errors": [], "applied": applied}

    @staticmethod
    def _consultant_semantic_failure_route(
        *,
        repair_attempt: int = 0,
        ambiguity_retry_count: int = 0,
    ) -> str:
        """Keep internal schema failures separate from genuine user ambiguity."""
        if int(repair_attempt or 0) >= CONSULTANT_SEMANTIC_REPAIR_LIMIT:
            return "blocked_internal_contract_error"
        if int(ambiguity_retry_count or 0) >= 2:
            return "ask_user"
        return "consultant"

    @classmethod
    def _consultant_contract_repair_context(cls, repair_state: Dict[str, Any]) -> str:
        if not repair_state:
            return "None"
        payload = {
            "action": "repair_finish",
            "base_payload_hash": repair_state.get("payload_hash"),
            "repair_attempt": repair_state.get("repair_attempt"),
            "error_count": repair_state.get("error_count"),
            "errors": repair_state.get("validation_errors") or [],
            "errors_by_field": repair_state.get("errors_by_field") or {},
            "allowed_fields_by_index": repair_state.get("allowed_fields_by_index") or {},
            "allowed_payload_fields": repair_state.get("allowed_payload_fields") or [],
            "original_payload": repair_state.get("original_payload") or {},
            "base_payload": (
                repair_state.get("base_payload")
                or repair_state.get("original_payload")
                or {}
            ),
            "required_response_shape": {
                "action_type": "repair_finish",
                "base_payload_hash": repair_state.get("payload_hash"),
                "constraint_patches": [{
                    "index": 0,
                    "set": {"provenance": [{"source_type": "user_explicit", "source_id": "choose-from-source-catalog"}]},
                }],
            },
        }
        return (
            "<consultant_contract_repair>\n"
            + json.dumps(payload, ensure_ascii=False, sort_keys=True, indent=2, default=str)
            + "\n</consultant_contract_repair>"
        )

    @classmethod
    def _looks_like_plain_final_solution(cls, text: str) -> bool:
        raw = str(text or "").strip()
        if not raw:
            return False
        if re.search(
            r"</?(?:execute|ask_user|install_tool|search|activate_batch|action_json|solution)\b",
            raw,
            re.IGNORECASE,
        ):
            return False
        lower = raw.lower()
        final_phrases = (
            "all deliverables are complete",
            "analysis is finished",
            "analysis complete",
            "task complete",
            "completed successfully",
            "final result",
            "deliverables",
        )
        if any(phrase in lower for phrase in final_phrases):
            return True
        if {"report.md", "reproduce.sh"}.issubset(set(re.findall(r"[a-z0-9_.-]+\.[a-z0-9]+", lower))):
            if re.search(r"\b(?:complete|completed|summary|conclusion|result|finished)\b|完成|结果|总结|结论", raw, re.IGNORECASE):
                return True
        if raw.startswith("#") and re.search(r"结果|总结|结论|analysis result|results summary|final", raw, re.IGNORECASE):
            return True
        return False

    @staticmethod
    def _pending_action_is(action: Any, action_type: str) -> bool:
        return (
            isinstance(action, dict)
            and str(action.get("type") or "").strip().lower() == action_type
        )

    @staticmethod
    def _plan_patch_requested(state: Dict[str, Any]) -> bool:
        """Return whether a cross-node transition explicitly requests Plan repair."""
        required = str(state.get("required_next_action") or "").strip().upper()
        decision = state.get("recovery_decision") if isinstance(state.get("recovery_decision"), dict) else {}
        pending = state.get("pending_recovery_action") if isinstance(state.get("pending_recovery_action"), dict) else {}
        recommended = str(decision.get("recommended_action") or "").strip().upper()
        pending_type = str(pending.get("type") or "").strip().lower()
        owner = str(
            state.get("failure_owner")
            or decision.get("failure_owner")
            or pending.get("failure_owner")
            or ""
        ).strip().upper()
        requested = (
            required in {"PLAN_PATCH", "PATCH_PLAN"}
            or recommended == RecoveryAction.PATCH_PLAN.value
            or pending_type in {"plan_patch", "patch_plan"}
        )
        return requested and owner == RecoveryFailureOwner.PLAN.value

    def _restore_generate_plan_authority(
        self,
        task_id: str,
        before_statuses: Dict[str, str],
    ) -> Dict[str, str]:
        """Keep Generate read-only except for starting the controller-selected step."""
        if not before_statuses:
            return {}
        plan_state = load_plan_state(self.data_path, task_id)
        attempted = restore_step_status_authority(plan_state, before_statuses)
        if attempted:
            save_plan_state(self.data_path, task_id, plan_state)
            if plan_state.get("plan_file"):
                update_plan_markdown_status(plan_state["plan_file"], plan_state)
            logger.warning(
                "Generate attempted checklist status mutation; controller restored authority: task=%s changes=%s",
                task_id,
                attempted,
            )
        return attempted

    def _finalize_blocked_state(self, task_id: str, reason: str) -> str:
        """Persist a truthful framework-level blocked result without another LLM call."""
        plan_state = load_plan_state(self.data_path, task_id)
        durable_failure = (
            dict(plan_state.get("failure") or {})
            if isinstance(plan_state.get("failure"), Mapping)
            else {}
        )
        planning_failure = dict(
            (plan_state.get("task_state") or {}).get("planning_failure") or {}
        )
        planning_terminal = (
            dict(planning_failure.get("terminal_diagnostic") or {})
            if str(planning_failure.get("status") or "") == "terminal"
            else {}
        )
        if durable_failure and not durable_failure.get("resolved_at"):
            durable_failure["repair_exhausted"] = True
            durable_failure.setdefault("termination_reason", "bounded_recovery_exhausted")
            durable_failure["last_seen_at"] = timestamp_now()
            plan_state["failure"] = durable_failure
        block_plan_and_downstream(plan_state, str(reason or "Controller blocked the task."))
        progress = self._persist_plan_tracker(task_id, plan_state)
        root = Path(self.data_path) / "task_outputs" / str(task_id or "default")
        root.mkdir(parents=True, exist_ok=True)
        blocked_payload = {
            "task_id": str(task_id),
            "status": TASK_STATUS_BLOCKED,
            "reason": str(reason)[:8000],
            "error_code": str(
                durable_failure.get("error_code")
                or planning_terminal.get("error_code")
                or "TASK_BLOCKED"
            ),
            "error_owner": str(
                durable_failure.get("owner")
                or planning_terminal.get("error_owner")
                or ""
            ),
            "failure_stage": str(
                durable_failure.get("stage")
                or planning_terminal.get("stage")
                or ("planner" if planning_terminal else "")
            ),
            "current_step_id": str((plan_state.get("task_state") or {}).get("current_step_id") or ""),
            "updated_at": datetime.now().isoformat(timespec="seconds"),
        }
        (root / "blocked_status.json").write_text(
            json.dumps(blocked_payload, ensure_ascii=False, indent=2) + "\n",
            encoding="utf-8",
        )
        stage_status = root / "stage_status.tsv"
        if not stage_status.exists():
            stage_status.write_text(
                "stage\tstatus\toutput_path\tnotes\n"
                f"task\tblocked\t-\t{str(reason).replace(chr(9), ' ')[:2000]}\n",
                encoding="utf-8",
            )
        else:
            existing_status = stage_status.read_text(encoding="utf-8", errors="replace")
            if not re.search(r"(?:^|\t)blocked(?:\t|$)", existing_status, re.IGNORECASE | re.MULTILINE):
                with stage_status.open("a", encoding="utf-8") as handle:
                    handle.write(
                        f"controller_terminal\tblocked\t-\t{str(reason).replace(chr(9), ' ')[:2000]}\n"
                    )
        report = root / "report.md"
        if not report.exists():
            report.write_text(
                "# BioMind Task Status\n\n"
                "Status: blocked\n\n"
                f"Reason: {reason}\n",
                encoding="utf-8",
            )
        else:
            existing_report = report.read_text(encoding="utf-8", errors="replace")
            if "## Controller Terminal Status" not in existing_report:
                with report.open("a", encoding="utf-8") as handle:
                    handle.write(
                        "\n\n## Controller Terminal Status\n\n"
                        "Status: blocked\n\n"
                        f"Reason: {reason}\n\n"
                        "Resume condition: provide new evidence, change the environment, or explicitly choose a different recovery strategy.\n"
                    )
        return progress

    def _apply_transition_guard(
        self,
        node_name: str,
        state: AgentState,
        update: Dict[str, Any],
        task_id: str,
        *,
        generate_mutations: Optional[Dict[str, str]] = None,
    ) -> Dict[str, Any]:
        """Deterministically validate every cross-node transition."""
        guarded = dict(update or {})
        merged = {**dict(state or {}), **guarded}
        plan_state = load_plan_state(self.data_path, task_id)

        def commit_guard_decision(decision_like: Any) -> Tuple[RecoveryDecision, Dict[str, Any]]:
            nonlocal plan_state
            decision_value = (
                decision_like.to_dict()
                if hasattr(decision_like, "to_dict")
                else dict(decision_like or {})
            )
            identity_changed = False
            for key, value in (
                ("task_id", str(plan_state.get("task_id") or task_id)),
                ("plan_id", str(plan_state.get("plan_id") or "")),
                ("plan_version", str(plan_state.get("plan_version") or "")),
            ):
                if not str(decision_value.get(key) or "") and value:
                    decision_value[key] = value
                    identity_changed = True
            if identity_changed:
                decision_value.pop("decision_id", None)
                decision_value.pop("idempotency_key", None)
            policy_value = RecoveryDecision.from_mapping(decision_value)
            application_value = apply_recovery_decision(plan_state, policy_value)
            # Every controller-created decision must carry its commit receipt
            # into the single route resolver.  Dropping it makes a transition
            # created in this node look stale before its first dispatch.
            guarded["recovery_application"] = application_value
            save_plan_state(self.data_path, task_id, plan_state)
            return policy_value, application_value

        proposed_decision = guarded.get("recovery_decision")
        if isinstance(proposed_decision, dict) and proposed_decision:
            try:
                policy_decision, application = commit_guard_decision(proposed_decision)
                guarded["recovery_decision"] = policy_decision.to_dict()
                guarded["recovery_application"] = application
                recovery_context_value = guarded.get("recovery_context") or {}
                if (
                    policy_decision.kind == RecoveryDecisionKind.FORMAT_REPAIR.value
                    and isinstance(recovery_context_value, dict)
                    and str(recovery_context_value.get("failure_stage") or "")
                    == "pre_action_contract"
                ):
                    logger.info(
                        "FORMAT_REPAIR_COMMITTED task=%s step_id=%s snapshot_id=%s "
                        "candidate_fingerprint=%s error_fingerprint=%s repair_ordinal=%s "
                        "owner=%s route=%s budget_before=%s budget_after=%s",
                        task_id,
                        str(recovery_context_value.get("step_id") or ""),
                        str(recovery_context_value.get("approved_plan_snapshot_id") or ""),
                        str(recovery_context_value.get("candidate_fingerprint") or ""),
                        str(recovery_context_value.get("error_fingerprint") or ""),
                        int(recovery_context_value.get("repair_ordinal") or 0),
                        policy_decision.failure_owner,
                        policy_decision.next_route,
                        dict(application.get("budget_before") or {}),
                        dict(application.get("budget_after") or {}),
                    )
                if application.get("current_step_id"):
                    guarded["current_step_id"] = str(application["current_step_id"])
                if application.get("current_stage_id"):
                    guarded["current_stage_id"] = str(application["current_stage_id"])
                merged = {**dict(state or {}), **guarded}
            except (TypeError, ValueError) as exc:
                # apply_recovery_decision records the rejected decision in the
                # PlanTracker state; persist that audit even though no state
                # transition or retry budget was applied.
                save_plan_state(self.data_path, task_id, plan_state)
                guarded.update({
                    "next_step": "supervisor",
                    "pending_action": {},
                    "pending_human_question": {},
                    "pending_recovery_action": {
                        "type": "internal_protocol_error",
                        "reason": f"Recovery decision commit rejected: {exc}",
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "requires_user_input": False,
                    },
                    "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    "transition_guard": "recovery_decision_commit_rejected",
                })
                return guarded
        # Recovery history is evidence only.  Route authority lives in the
        # scoped, pending active_transition and is resolved exactly once after
        # all node-local contract guards have run.
        durable_status = task_status(plan_state)
        pending_recovery = guarded.get("pending_recovery_action") or merged.get("pending_recovery_action") or {}
        recovery_type = str(pending_recovery.get("type") or "").strip().lower() if isinstance(pending_recovery, dict) else ""
        recovery_phase = str(guarded.get("recovery_phase") or merged.get("recovery_phase") or "").strip().lower()
        pending_question = guarded.get("pending_human_question") or merged.get("pending_human_question") or {}
        has_pending_question = bool(
            isinstance(pending_question, dict)
            and str(pending_question.get("question") or "").strip()
        )
        recovery_decision = merged.get("recovery_decision") if isinstance(merged.get("recovery_decision"), dict) else {}
        recovery_owner = str(
            (pending_recovery.get("failure_owner") if isinstance(pending_recovery, dict) else "")
            or recovery_decision.get("failure_owner")
            or merged.get("failure_owner")
            or ""
        ).strip().upper()
        recovery_requires_user = bool(
            (pending_recovery.get("requires_user_input") if isinstance(pending_recovery, dict) else False)
            or recovery_decision.get("requires_user_input")
        )
        attempted_block = any(
            status in {STATUS_BLOCKED, STATUS_FAILED}
            for status in (generate_mutations or {}).values()
        )
        blocked_reason = str(
            (pending_recovery.get("reason") if isinstance(pending_recovery, dict) else "")
            or guarded.get("recovery_status")
            or guarded.get("generate_exit_reason")
            or "A node reported a terminal blocked recovery state."
        )
        if recovery_type == "ask_user" and (
            recovery_owner != RecoveryFailureOwner.INPUT_DATA.value
            or not recovery_requires_user
        ):
            guarded.update({
                "next_step": "supervisor",
                "pending_action": {},
                "pending_human_question": {},
                "pending_recovery_action": {
                    **(pending_recovery if isinstance(pending_recovery, dict) else {}),
                    "type": "internal_protocol_error",
                    "reason": "Internal recovery error attempted to enter the user-decision channel.",
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    "requires_user_input": False,
                },
                "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                "transition_guard": "internal_error_cannot_ask_user",
            })
            return guarded
        if recovery_type == "ask_user" and has_pending_question:
            guarded.update({
                "next_step": "ask_user",
                "pending_action": {},
                "transition_guard": "awaiting_recovery_user_decision",
            })
            return guarded
        if durable_status in {TASK_STATUS_FAILED, TASK_STATUS_CANCELLED} and recovery_type != "blocked" and recovery_phase not in {"blocked", "exhausted"}:
            guarded.update({
                "next_step": "finish",
                "pending_action": {},
                "task_status": durable_status,
                "transition_guard": f"terminal_{durable_status}",
            })
            return guarded

        if (
            durable_status == TASK_STATUS_BLOCKED
            or recovery_type == "blocked"
            or recovery_phase in {"blocked", "exhausted"}
            or attempted_block
        ):
            progress = self._finalize_blocked_state(task_id, blocked_reason)
            guarded.update({
                "next_step": "finish",
                "pending_action": {},
                "pending_recovery_action": {},
                "plan_progress": progress,
                "task_status": TASK_STATUS_BLOCKED,
                "transition_guard": "terminal_blocked",
            })
            return guarded

        if durable_status == TASK_STATUS_COMPLETED:
            guarded.update({
                "next_step": "finish",
                "pending_action": {},
                "transition_guard": "terminal_completed",
            })
            return guarded

        committed_kind = str((guarded.get("recovery_decision") or {}).get("kind") or "")
        if (
            node_name == "supervisor"
            and committed_kind == RecoveryDecisionKind.COMPLETE_STEP.value
            and bool(plan_state.get("steps"))
            and all(
                str(step.get("status") or "") in {"done", "passed", "skipped"}
                for step in plan_state.get("steps", []) or []
                if isinstance(step, dict)
            )
        ):
            guarded.update({
                "next_step": "supervisor_final_audit",
                "final_audit_requested": True,
                "completion_candidate": {
                    "text": "Controller verified the final plan step from persisted execution evidence.",
                    "source": "supervisor_completion_policy",
                    "step_id": str((guarded.get("recovery_decision") or {}).get("step_id") or ""),
                },
                "transition_guard": "complete_step_requires_final_audit",
            })

        step_candidate = guarded.get("step_completion_candidate")
        if node_name in {"generate", "execute"} and isinstance(step_candidate, dict) and step_candidate:
            renderer_protocol = self._renderer_action_protocol(merged, task_id)
            if (
                renderer_protocol.get("renderer_composite")
                and renderer_protocol.get("manifest_status") != "registered"
            ):
                candidate_hash = hashlib.sha256(
                    json.dumps(step_candidate, ensure_ascii=False, sort_keys=True, default=str).encode("utf-8")
                ).hexdigest()[:20]
                repair_feedback = self._action_format_repair_feedback(
                    merged,
                    task_id,
                    invalid_hash=candidate_hash,
                    invalid_excerpt=json.dumps(step_candidate, ensure_ascii=False, default=str),
                    contract_error={
                        "error_type": "RENDERER_MANIFEST_REQUIRED",
                        "reason": "STEP_COMPLETION_CANDIDATE is invalid before Renderer manifest registration.",
                    },
                )
                policy_decision = self._commit_preaction_policy_decision(
                    task_id,
                    str(step_candidate.get("step_id") or "task"),
                    "renderer_invocation_required_before_step_completion",
                    attempt_id=f"step-candidate:{candidate_hash}",
                )
                policy_decision, _ = commit_guard_decision(policy_decision)
                guarded.update({
                    "next_step": policy_decision.next_route,
                    "recovery_decision": policy_decision.to_dict(),
                    "pending_action": {},
                    "step_completion_candidate": {},
                    "pending_recovery_action": {
                        "type": "ACTION_FORMAT_REPAIR",
                        "reason": "Renderer manifest is absent; invoke the declared Renderer first.",
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "allowed_actions": renderer_protocol.get("allowed_actions") or [],
                    },
                    "required_next_action": "ACTION_FORMAT_REPAIR",
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    "recovery_scope": "CURRENT_STEP",
                    "recovery_phase": "diagnose",
                    "transition_guard": "renderer_manifest_required_before_step_completion",
                    "messages": list(guarded.get("messages") or []) + [SystemMessage(content=repair_feedback)],
                })
                return guarded
            passed, gate, progress = self._validate_and_advance_step_candidate(
                task_id,
                step_candidate,
                source_node=node_name,
            )
            guarded.update({
                "pending_action": {},
                "step_completion_candidate": {},
                "completion_gate_result": gate.to_dict(),
                "plan_progress": progress,
                "pending_recovery_action": {},
                "required_next_action": "",
            })
            if passed:
                if self._plan_tracker_is_complete(task_id):
                    guarded.update({
                        "next_step": "supervisor_final_audit",
                        "final_audit_requested": True,
                        "completion_candidate": {
                            "text": "Controller verified the final plan step from persisted execution evidence.",
                            "source": "step_completion_candidate",
                            "step_id": str(step_candidate.get("step_id") or ""),
                        },
                        "transition_guard": "step_completion_candidate_final_audit",
                    })
                else:
                    guarded.update({
                        "next_step": "generate",
                        "transition_guard": "step_completion_candidate_accepted",
                    })
            else:
                rejection_signature = hashlib.sha256(json.dumps(
                    {
                        "step_id": step_candidate.get("step_id"),
                        "evidence_ids": step_candidate.get("evidence_ids") or [],
                        "classification": gate.classification,
                        "message": gate.message,
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                    default=str,
                ).encode("utf-8", errors="replace")).hexdigest()[:20]
                candidate_budgets = dict((load_plan_state(self.data_path, task_id).get("task_state") or {}).get("budgets") or {})
                candidate_sequence = int(candidate_budgets.get("generate_action_count") or 0) + 1
                policy_decision = self._commit_preaction_policy_decision(
                    task_id,
                    str(step_candidate.get("step_id") or "task"),
                    f"step_completion_candidate_rejected: {gate.message}",
                    attempt_id=f"step-candidate-rejected:{rejection_signature}:{candidate_sequence}",
                    source_node=node_name,
                )
                policy_decision, _ = commit_guard_decision(policy_decision)
                guarded.update({
                    "next_step": policy_decision.next_route,
                    "recovery_decision": policy_decision.to_dict(),
                    "pending_recovery_action": {
                        "type": (
                            "ACTION_FORMAT_REPAIR"
                            if policy_decision.kind == RecoveryDecisionKind.FORMAT_REPAIR.value
                            else "internal_protocol_error"
                        ),
                        "reason": gate.message,
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    },
                    "required_next_action": (
                        "ACTION_FORMAT_REPAIR"
                        if policy_decision.kind == RecoveryDecisionKind.FORMAT_REPAIR.value
                        else "INTERNAL_PROTOCOL_ERROR"
                    ),
                    "transition_guard": "step_completion_candidate_rejected",
                    "messages": list(guarded.get("messages") or []) + [SystemMessage(content=(
                        "<step_completion_candidate_rejected>\n"
                        f"Current step: {step_candidate.get('step_id') or '<missing>'}\n"
                        f"Reason: {gate.message}\n{gate.feedback}\n"
                        "Return one EXECUTE action that supplies the missing evidence, or another "
                        "STEP_COMPLETION_CANDIDATE citing different eligible evidence.\n"
                        "</step_completion_candidate_rejected>"
                    ))],
                })
            return guarded

        next_step = str(guarded.get("next_step") or "").strip()
        if next_step == "execute":
            contract_error = self._validate_pending_action_contract(
                guarded.get("pending_action") or merged.get("pending_action") or {},
                merged,
                task_id,
            )
            if contract_error:
                _, current_step = current_plan_step_with_index(plan_state)
                step_id = str(current_step.get("step_id") or "task")
                invalid_action = guarded.get("pending_action") or merged.get("pending_action") or {}
                invalid_excerpt = str(
                    invalid_action.get("code")
                    or invalid_action.get("reason")
                    or invalid_action
                )[:500]
                repair_feedback = self._action_format_repair_feedback(
                    merged,
                    task_id,
                    invalid_hash=hashlib.sha256(invalid_excerpt.encode("utf-8")).hexdigest()[:16],
                    invalid_excerpt=invalid_excerpt,
                    contract_error={"reason": contract_error},
                )
                current_budgets = dict((plan_state.get("task_state") or {}).get("budgets") or {})
                attempt_sequence = int(
                    (current_budgets.get("action_format_repair_by_step") or {}).get(step_id) or 0
                ) + 1
                policy_decision = self._commit_preaction_policy_decision(
                    task_id,
                    step_id,
                    contract_error,
                    attempt_id=(
                        f"preaction:{hashlib.sha256(invalid_excerpt.encode('utf-8')).hexdigest()[:16]}:"
                        f"{attempt_sequence}"
                    ),
                )
                policy_decision, _ = commit_guard_decision(policy_decision)
                pending_type = (
                    "ACTION_FORMAT_REPAIR"
                    if policy_decision.kind == RecoveryDecisionKind.FORMAT_REPAIR.value
                    else "internal_protocol_error"
                )
                guarded.update({
                    "next_step": policy_decision.next_route,
                    "recovery_decision": policy_decision.to_dict(),
                    "pending_action": {},
                    "pending_recovery_action": {
                        "type": pending_type,
                        "reason": contract_error,
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    },
                    "required_next_action": (
                        "ACTION_FORMAT_REPAIR"
                        if policy_decision.kind == RecoveryDecisionKind.FORMAT_REPAIR.value
                        else "INTERNAL_PROTOCOL_ERROR"
                    ),
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    "recovery_scope": "CURRENT_STEP",
                    "recovery_phase": "diagnose",
                    "transition_guard": (
                        "invalid_action_requires_format_repair"
                        if policy_decision.kind == RecoveryDecisionKind.FORMAT_REPAIR.value
                        else "invalid_action_budget_exhausted"
                    ),
                    "messages": list(guarded.get("messages") or []) + [SystemMessage(content=repair_feedback)],
                })
                return guarded

        if node_name == "generate" and next_step == "finish" and str(merged.get("task_mode") or "managed").lower() == "managed":
            guarded["next_step"] = "supervisor_final_audit"
            guarded["transition_guard"] = "managed_finish_requires_final_audit"
        elif next_step:
            guarded["next_step"] = next_step
        elif node_name == "generate":
            _, missing_transition_step = current_plan_step_with_index(plan_state)
            missing_transition_id = str((missing_transition_step or {}).get("step_id") or "task")
            policy_decision = self._commit_preaction_policy_decision(
                task_id,
                missing_transition_id,
                "generate_result_missing_transition",
                attempt_id=f"missing-transition:{hashlib.sha256(json.dumps(guarded, default=str, sort_keys=True).encode('utf-8')).hexdigest()[:16]}",
            )
            policy_decision, _ = commit_guard_decision(policy_decision)
            guarded.update({
                "next_step": policy_decision.next_route,
                "recovery_decision": policy_decision.to_dict(),
                "pending_action": {},
                "pending_recovery_action": {
                    "type": "ACTION_FORMAT_REPAIR",
                    "reason": "Generate produced no next-node candidate.",
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                },
                "required_next_action": "ACTION_FORMAT_REPAIR",
                "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                "recovery_scope": "CURRENT_STEP",
                "transition_guard": "node_result_missing_transition",
                "state_transition_error": "NODE_RESULT_INVALID: Generate produced no next-node candidate.",
            })
        if (
            node_name in {"generate", "execute", "supervisor", "supervisor_final_audit"}
            and str(guarded.get("next_step") or "") == "planner"
            and self._plan_patch_requested({**merged, **guarded})
        ):
            _, patch_step = current_plan_step_with_index(plan_state)
            patch_step_id = str((patch_step or {}).get("step_id") or "task")
            patch_hash = str(plan_state.get("semantic_plan_hash") or "unknown")
            patch_signature = f"{patch_step_id}:{patch_hash}"
            budgets = dict((plan_state.get("task_state") or {}).get("budgets") or {})
            no_op_counts = dict(budgets.get("no_op_plan_patch_by_signature") or {})
            approved_same_step_recovery = validate_plan_for_generate(
                plan_state,
                self._task_revision_for_state(merged),
            ).get("valid")
            if int(no_op_counts.get(patch_signature) or 0) >= 1 and approved_same_step_recovery:
                guarded.update({
                    "next_step": "generate",
                    "pending_action": {},
                    "pending_recovery_action": {
                        "type": "same_step_generate",
                        "reason": "repeated_no_op_plan_patch",
                        "step_id": patch_step_id,
                        "signature": patch_signature,
                    },
                    "recovery_decision": {},
                    "required_next_action": "SAME_STEP_GENERATE",
                    "failure_owner": "",
                    "recovery_scope": "CURRENT_STEP",
                    "recovery_phase": "apply_repair",
                    "recovery_status": "",
                    "supervisor_verdict": "",
                    "completion_gate_result": {},
                    "transition_guard": "repeated_no_op_plan_patch_fused",
                    "messages": list(guarded.get("messages") or []) + [SystemMessage(content=(
                        "The same current-step PLAN_PATCH already produced no semantic change. "
                        "Planner routing was fused; repair the execution action using the existing plan."
                    ))],
                })
        skill_plan_impact_route = bool(
            str(
                (
                    guarded.get("pending_skill_binding_proposal")
                    or merged.get("pending_skill_binding_proposal")
                    or {}
                ).get("review_route")
                or ""
            ) == "planner_plan_impact_review"
            and (
                guarded.get("pending_plan_impact_review")
                or merged.get("pending_plan_impact_review")
            )
        )
        if (
            node_name in {"generate", "execute", "supervisor", "supervisor_final_audit"}
            and str(guarded.get("next_step") or "") == "planner"
            and not self._plan_patch_requested({**merged, **guarded})
            and not skill_plan_impact_route
        ):
            guarded.update({
                "next_step": "generate",
                "pending_action": {},
                "transition_guard": "planner_requires_explicit_plan_patch",
                "state_transition_error": (
                    "NODE_RESULT_INVALID: runtime nodes may route to Planner only with required_next_action=PLAN_PATCH."
                ),
                "messages": list(guarded.get("messages") or []) + [SystemMessage(content=(
                    "Planner routing was rejected because no structured PLAN_PATCH was requested. "
                    "Keep the approved plan and repair or regenerate the current action instead."
                ))],
            })
        # The loop guard runs later against effective_route, after the one-shot
        # recovery override has been resolved.  Checking the proposal here was
        # the incident bug: Execute proposed Supervisor while the router later
        # dispatched Generate.
        return guarded

    def _resolve_and_commit_effective_transition(
        self,
        node_name: str,
        state: AgentState,
        update: Dict[str, Any],
        task_id: str,
    ) -> Dict[str, Any]:
        """Resolve one final route, enforce progress, and consume recovery once."""
        resolved = dict(update or {})
        proposed_route = str(
            resolved.get("proposed_route")
            or resolved.get("node_recommended_next_step")
            or resolved.get("next_step")
            or ""
        ).strip()
        pre_recovery_route = str(resolved.get("next_step") or proposed_route).strip()
        plan_state = load_plan_state(self.data_path, task_id)
        _, current_step = current_plan_step_with_index(plan_state)
        # Only evidence emitted by this node invocation is current.  Falling
        # back to AgentState replays the prior Execute attempt on legal early
        # returns and can revive an old exhausted guard or RecoveryDecision.
        current_evidence = (
            dict(resolved.get("execution_evidence") or {})
            if isinstance(resolved.get("execution_evidence"), Mapping)
            else {}
        )
        current_step_id = str(
            resolved.get("current_step_id")
            or current_evidence.get("step_id")
            or (current_step or {}).get("step_id")
            or ""
        )
        current_attempt = str(
            current_evidence.get("attempt_id")
            or current_evidence.get("execution_id")
            or ""
        )
        try:
            current_returncode = int(
                current_evidence.get("returncode")
                if current_evidence.get("returncode") is not None
                else current_evidence.get("exit_code")
            )
        except (TypeError, ValueError):
            current_returncode = None
        execution_validation = current_evidence.get("validation")
        command_role = str(current_evidence.get("command_role") or "primary").lower()
        current_execution_succeeded = bool(
            node_name == "execute"
            and current_evidence
            and command_role not in {
                "probe", "diagnostic", "optional_probe", "capability_probe",
            }
            and current_returncode == 0
            and str(current_evidence.get("execution_status") or "").lower() != "failed"
            and not (
                isinstance(execution_validation, dict)
                and execution_validation.get("passed") is False
            )
        )
        application = (
            dict(resolved.get("recovery_application") or {})
            if isinstance(resolved.get("recovery_application"), dict)
            else {}
        )
        newly_committed_decision_id = str(
            application.get("decision_id")
            if application.get("applied")
            else ""
        )
        if newly_committed_decision_id and not current_attempt:
            committed_decision = (
                dict(resolved.get("recovery_decision") or {})
                if isinstance(resolved.get("recovery_decision"), Mapping)
                else {}
            )
            current_attempt = str(
                committed_decision.get("trigger_event_id")
                or committed_decision.get("attempt_id")
                or ""
            )
        eligibility = recovery_transition_eligibility(
            plan_state,
            source_node=node_name,
            current_step_id=current_step_id,
            current_attempt_id=current_attempt,
            current_execution_succeeded=current_execution_succeeded,
            newly_committed_decision_id=newly_committed_decision_id,
        )

        effective_route = pre_recovery_route
        override_source = ""
        override_decision_id = ""
        if eligibility.get("eligible"):
            effective_route = str(eligibility.get("target_route") or "")
            override_source = "recovery_transition"
            override_decision_id = str(eligibility.get("decision_id") or "")
            transition = dict(eligibility.get("transition") or {})
            transition_kind = str(transition.get("kind") or "")
            controller_guard = str(resolved.get("transition_guard") or "")
            if (
                transition_kind == RecoveryDecisionKind.COMPLETE_STEP.value
                and pre_recovery_route == "supervisor_final_audit"
                and bool(resolved.get("final_audit_requested"))
            ):
                effective_route = "supervisor_final_audit"
                override_source = "controller_completion_route"
            elif (
                controller_guard in {
                    "repeated_no_op_plan_patch_fused",
                    "planner_requires_explicit_plan_patch",
                }
                and pre_recovery_route == "generate"
            ):
                effective_route = "generate"
                override_source = "controller_plan_patch_guard"
        elif str(eligibility.get("status") or "") in {"superseded", "expired"}:
            override_source = "stale_recovery_transition_ignored"
            override_decision_id = str(eligibility.get("decision_id") or "")
            logger.warning(
                "RECOVERY_TRANSITION_INELIGIBLE task=%s node=%s decision=%s status=%s reason=%s",
                task_id,
                node_name,
                str(eligibility.get("decision_id") or ""),
                str(eligibility.get("status") or ""),
                str(eligibility.get("reason") or ""),
            )
        elif eligibility.get("ignored_current_event"):
            override_source = "out_of_order_current_event_ignored"
            override_decision_id = str(eligibility.get("decision_id") or "")
            logger.warning(
                "RECOVERY_CURRENT_EVENT_INELIGIBLE task=%s node=%s decision=%s reason=%s",
                task_id,
                node_name,
                override_decision_id,
                str(eligibility.get("reason") or ""),
            )

        allowed_routes = {
            "generate", "execute", "planner", "consultant", "supervisor",
            "supervisor_final_audit", "install_subagent", "ask_user", "finish", "blocked",
        }
        if effective_route not in allowed_routes:
            effective_route = "supervisor"
            override_source = "route_protocol_guard"
            resolved["state_transition_error"] = (
                "RECOVERY_EFFECTIVE_ROUTE_INVALID: controller routed to Supervisor"
            )

        progress_guard = (
            dict(resolved.get("progress_guard_result") or {})
            if isinstance(resolved.get("progress_guard_result"), dict)
            else {}
        )
        progress_scope_matches = bool(
            progress_guard
            and not eligibility.get("ignored_current_event")
            and str(progress_guard.get("source_node") or "") == node_name
            and bool(str(progress_guard.get("step_id") or ""))
            and str(progress_guard.get("step_id") or "") == current_step_id
            and bool(str(progress_guard.get("attempt_id") or ""))
            and str(progress_guard.get("attempt_id") or "") == current_attempt
            and bool(str(progress_guard.get("trigger_event_id") or ""))
            and str(progress_guard.get("trigger_event_id") or "") == current_attempt
        )
        progress_guard["observed_route"] = effective_route
        progress_guard["scope_matches"] = progress_scope_matches
        should_block = bool(
            progress_scope_matches
            and (
                progress_guard.get("should_block") is True
                or str(progress_guard.get("classification") or "").lower() == "exhausted"
            )
        )
        block_reason_code = ""
        block_reason = ""
        if should_block:
            block_reason_code = "RECOVERY_NO_PROGRESS_EXHAUSTED"
            block_reason = str(
                progress_guard.get("reason")
                or "Recovery made no meaningful progress within the configured limit."
            )
            block_plan_and_downstream(
                plan_state,
                f"{block_reason_code}: {block_reason}",
            )
            effective_route = "blocked"
            override_source = "progress_guard"
        elif effective_route == "blocked":
            transition = dict(eligibility.get("transition") or {})
            block_reason_code = str(
                transition.get("reason_code") or "RECOVERY_POLICY_BLOCKED"
            )
            block_reason = str(
                transition.get("reason") or "RecoveryPolicy blocked the current step."
            )
            block_plan_and_downstream(
                plan_state,
                f"{block_reason_code}: {block_reason}",
            )

        pending_recovery = (
            dict(resolved.get("pending_recovery_action") or {})
            if isinstance(resolved.get("pending_recovery_action"), dict)
            else {}
        )
        if (
            not should_block
            and str(resolved.get("generate_result") or "").upper()
            not in {
                "SKILL_CONTINUATION", "SKILL_BINDING_PROPOSED",
                "SKILL_NO_PROGRESS", "STALE_NODE_RESULT",
            }
            and (
                effective_route == node_name
                or (
                    effective_route == "generate"
                    and node_name in {"generate", "execute"}
                )
            )
            and node_name in {
                "generate", "execute", "supervisor", "supervisor_final_audit",
            }
            and str(pending_recovery.get("type") or "").strip().lower() != "action_format_repair"
        ):
            task_state = dict(plan_state.get("task_state") or {})
            budgets = dict(task_state.get("budgets") or {})
            counts = dict(budgets.get("same_transition_by_signature") or {})
            signature = ":".join(
                part for part in (
                    f"{node_name}->{effective_route}",
                    current_step_id or "task",
                    str(
                        resolved.get("generate_exit_reason")
                        or resolved.get("transition_guard")
                        or resolved.get("required_next_action")
                        or "continue"
                    ).strip().lower(),
                )
                if part
            )
            count = int(counts.get(signature) or 0) + 1
            counts[signature] = count
            budgets["same_transition_by_signature"] = counts
            budgets["same_transition_count"] = count
            task_state["budgets"] = budgets
            plan_state["task_state"] = task_state
            progress_guard["same_transition_signature"] = signature
            progress_guard["same_transition_count"] = count
            if count > 2:
                block_reason_code = "STATE_MACHINE_STALLED"
                block_reason = f"{node_name}->{effective_route}"
                block_plan_and_downstream(
                    plan_state,
                    f"{block_reason_code}: {block_reason}",
                )
                effective_route = "blocked"
                override_source = "loop_guard"

        if (
            current_execution_succeeded
            and not eligibility.get("ignored_current_event")
            and effective_route == "supervisor"
        ):
            mark_step_verification_pending(
                plan_state,
                step_id=current_step_id,
                attempt_id=current_attempt,
                evidence="successful Execute awaiting Supervisor validation",
            )

        dispatch_route = "finish" if effective_route == "blocked" else effective_route
        route_state_before = dict(plan_state.get("task_state") or {})
        route_sequence = int(route_state_before.get("route_sequence") or 0) + 1
        route_identity = {
            "task_id": task_id,
            "route_sequence": route_sequence,
            "source_node": node_name,
            "proposed_route": proposed_route,
            "pre_guard_effective_route": (
                str(eligibility.get("target_route") or pre_recovery_route)
                if eligibility.get("eligible")
                else pre_recovery_route
            ),
            "effective_route": effective_route,
            "override_decision_id": override_decision_id,
            "current_step_id": current_step_id,
            "current_attempt": current_attempt,
        }
        route_event_id = "route-" + hashlib.sha256(
            json.dumps(route_identity, ensure_ascii=False, sort_keys=True).encode("utf-8")
        ).hexdigest()[:20]
        route_record = {
            **route_identity,
            "route_event_id": route_event_id,
            "dispatch_route": dispatch_route,
            "override_source": override_source,
            "progress_guard_result": progress_guard,
            "block_reason_code": block_reason_code,
            "block_reason": block_reason,
            "resolved_at": datetime.now().isoformat(timespec="seconds"),
        }
        recovery_transition_consumed = False
        if eligibility.get("eligible"):
            consumed = consume_recovery_transition(
                plan_state,
                decision_id=override_decision_id,
                route_record=route_record,
            )
            recovery_transition_consumed = bool(consumed)
            if not consumed:
                block_reason_code = "RECOVERY_TRANSITION_CONSUME_FAILED"
                block_reason = f"decision_id={override_decision_id or '<missing>'}"
                block_plan_and_downstream(
                    plan_state,
                    f"{block_reason_code}: {block_reason}",
                )
                effective_route = "blocked"
                dispatch_route = "finish"
                override_source = "recovery_transition_consume_guard"
                route_record.update({
                    "effective_route": effective_route,
                    "dispatch_route": dispatch_route,
                    "override_source": override_source,
                    "block_reason_code": block_reason_code,
                    "block_reason": block_reason,
                })
            transition = dict(eligibility.get("transition") or {})
            if consumed and str(transition.get("kind") or "") == RecoveryDecisionKind.ACCEPT_EXECUTION_FOR_VERIFICATION.value:
                resolved["reconciliation_evidence"] = {
                    "decision_id": override_decision_id,
                    "attempt_id": str(transition.get("attempt_id") or transition.get("trigger_event_id") or ""),
                    "status": "consumed",
                    "evidence": list(transition.get("evidence") or []),
                    "reason": str(transition.get("reason") or ""),
                }

        # consume_recovery_transition replaces task_state with the consumed
        # lifecycle.  Re-read it here; writing the pre-consume snapshot back
        # would resurrect active_transition=pending and recreate the incident.
        route_task_state = dict(plan_state.get("task_state") or {})
        route_task_state["route_sequence"] = route_sequence
        route_task_state["last_route_resolution"] = route_record
        route_task_state["route_resolution_history"] = [
            *list(route_task_state.get("route_resolution_history") or []),
            route_record,
        ]
        if block_reason_code:
            recovery_state = dict(route_task_state.get("recovery_state") or {})
            recovery_state.update({
                "phase": "blocked",
                "status": "BLOCKED",
                "reason_code": block_reason_code,
                "reason": block_reason,
            })
            route_task_state["recovery_state"] = recovery_state
        plan_state["task_state"] = route_task_state
        plan_progress = self._persist_plan_tracker(task_id, plan_state)

        resolved.update({
            "proposed_route": proposed_route,
            "pre_guard_effective_route": route_record["pre_guard_effective_route"],
            "effective_route": effective_route,
            "dispatch_route": dispatch_route,
            "override_source": override_source,
            "override_decision_id": override_decision_id,
            "route_event_id": route_event_id,
            "current_step_id": current_step_id,
            "current_attempt": current_attempt,
            "progress_guard_result": progress_guard,
            "route_resolution": route_record,
            "recovery_transition_consumed": recovery_transition_consumed,
            "next_step": dispatch_route,
            "plan_progress": plan_progress,
        })
        if effective_route == "blocked":
            resolved.update({
                "task_status": TASK_STATUS_BLOCKED,
                "pending_action": {},
                "pending_recovery_action": {},
                "required_next_action": "BLOCKED",
                "recovery_phase": "blocked",
                "recovery_status": block_reason_code,
                "transition_guard": (
                    "recovery_no_progress_exhausted"
                    if block_reason_code == "RECOVERY_NO_PROGRESS_EXHAUSTED"
                    else "same_transition_budget_exhausted"
                    if block_reason_code == "STATE_MACHINE_STALLED"
                    else "recovery_transition_consume_failed"
                    if block_reason_code == "RECOVERY_TRANSITION_CONSUME_FAILED"
                    else "recovery_policy_blocked"
                ),
                "state_transition_error": f"{block_reason_code}:{block_reason}",
            })
        return resolved

    @staticmethod
    def _dispatch_effective_route(state: Mapping[str, Any], source_node: str) -> str:
        """Return the current node's committed dispatch route, never Recovery history.

        ``route_resolution`` is replaced by every profiled runtime-node update,
        so matching both source node and event id prevents a prior node's route
        from becoming another sticky override.  The narrow Execute fallback is
        for checkpoints written before route records existed: a newer successful
        Execute may resume only toward Supervisor, never toward a legacy
        ``CONTINUE -> generate`` projection.
        """
        state_map = dict(state or {})
        record = (
            dict(state_map.get("route_resolution") or {})
            if isinstance(state_map.get("route_resolution"), Mapping)
            else {}
        )
        state_event_id = str(state_map.get("route_event_id") or "")
        record_event_id = str(record.get("route_event_id") or "")
        record_source = str(record.get("source_node") or "")
        if record:
            if (
                record_source != str(source_node or "")
                or not state_event_id
                or record_event_id != state_event_id
            ):
                logger.error(
                    "ROUTE_RESOLUTION_SCOPE_MISMATCH source=%s record_source=%s "
                    "state_event=%s record_event=%s",
                    source_node,
                    record_source,
                    state_event_id,
                    record_event_id,
                )
                return "finish"
            route = str(
                record.get("dispatch_route")
                or state_map.get("dispatch_route")
                or record.get("effective_route")
                or ""
            ).strip().lower()
            if route == "blocked":
                return "finish"
            if route in {
                "generate", "execute", "planner", "consultant", "supervisor",
                "supervisor_final_audit", "install_subagent", "ask_user", "finish",
            }:
                return route
            logger.error(
                "ROUTE_RESOLUTION_TARGET_INVALID source=%s event=%s route=%s",
                source_node,
                record_event_id,
                route,
            )
            return "finish"

        if str(source_node or "") == "execute":
            execution = (
                dict(state_map.get("execution_evidence") or {})
                if isinstance(state_map.get("execution_evidence"), Mapping)
                else {}
            )
            try:
                returncode = int(
                    execution.get("returncode")
                    if execution.get("returncode") is not None
                    else execution.get("exit_code")
                )
            except (TypeError, ValueError):
                returncode = None
            validation = execution.get("validation")
            execution_succeeded = bool(
                execution
                and returncode == 0
                and str(execution.get("execution_status") or "").lower() != "failed"
                and not (
                    isinstance(validation, Mapping)
                    and validation.get("passed") is False
                )
            )
            if execution_succeeded:
                logger.warning(
                    "LEGACY_EXECUTE_ROUTE_RECOVERED: successful Execute without a "
                    "route record resumes at Supervisor"
                )
                return "supervisor"

        # Read-compatible fallback for old checkpoints.  It deliberately reads
        # only the node-local proposal, never recovery_decision/history.
        return str(
            state_map.get("dispatch_route")
            or state_map.get("effective_route")
            or state_map.get("next_step")
            or "finish"
        ).strip().lower()

    def _profile_node(self, node_name: str, func):
        async def wrapped(state: AgentState):
            task_id = state.get("task_id") or state.get("session_id") or "default"
            before_plan = load_plan_state(self.data_path, task_id)
            before_statuses = {
                str(step.get("step_id") or ""): str(step.get("status") or "")
                for step in before_plan.get("steps", []) or []
                if isinstance(step, dict) and str(step.get("step_id") or "")
            }
            with self.profiler.node(task_id, node_name):
                result = await func(state)
            if not isinstance(result, dict):
                result = {
                    "messages": [SystemMessage(content=(
                        f"{node_name} returned an invalid NodeResult ({type(result).__name__}). "
                        "The state machine stopped instead of reusing a stale transition."
                    ))],
                    "pending_action": {},
                    "pending_recovery_action": {
                        "type": "blocked",
                        "reason": f"NODE_RESULT_INVALID:{node_name}",
                    },
                    "next_step": "finish",
                    "state_transition_error": f"NODE_RESULT_INVALID:{node_name}",
                }
            if isinstance(result, dict) and node_name in {"consultant", "generate"}:
                combined_messages = add_messages(
                    list(state.get("messages", []) or []),
                    list(result.get("messages", []) or []),
                )
                try:
                    compacted_messages, compressed = await self.memory_manager.maybe_compress(
                        combined_messages,
                        task_id,
                    )
                except Exception as exc:
                    logger.warning(
                        "Message compaction failed after %s for task %s; keeping graph messages unchanged: %s",
                        node_name,
                        task_id,
                        exc,
                    )
                    compacted_messages, compressed = combined_messages, False
                if compressed:
                    output.print_once(
                        f"memory_state_compacted:{task_id}:{node_name}",
                        "🗜️ Memory compressed; graph working messages were replaced with the compact state.",
                        Fore.YELLOW,
                    )
                    result = dict(result)
                    result["messages"] = [
                        RemoveMessage(id=REMOVE_ALL_MESSAGES),
                        *compacted_messages,
                    ]
            result = self._normalize_state_update_aliases(node_name, state, result)
            generate_mutations: Dict[str, str] = {}
            if node_name == "generate":
                generate_mutations = self._restore_generate_plan_authority(task_id, before_statuses)
                if isinstance(result, dict):
                    result.pop("plan_progress", None)
                    recommended = str(result.pop("next_step", "") or "").strip()
                    if recommended:
                        result["node_recommended_next_step"] = recommended
                    if recommended != "supervisor_final_audit":
                        result.setdefault("final_audit_requested", False)
                        result.setdefault("completion_candidate", {})
                    for forbidden_key in (
                        "current_step_id", "current_stage_id", "completed_steps", "step_status", "stage_status",
                        "task_status", "depends_on", "artifact_status", "provenance_state",
                    ):
                        result.pop(forbidden_key, None)
            if isinstance(result, dict):
                if node_name == "generate" and not result.get("next_step"):
                    result["next_step"] = str(result.get("node_recommended_next_step") or "")
                result.setdefault(
                    "proposed_route",
                    str(result.get("node_recommended_next_step") or result.get("next_step") or ""),
                )
                result = self._apply_transition_guard(
                    node_name,
                    state,
                    result,
                    task_id,
                    generate_mutations=generate_mutations,
                )
                if node_name in {
                    "generate", "execute", "supervisor", "supervisor_final_audit",
                }:
                    result = self._resolve_and_commit_effective_transition(
                        node_name,
                        state,
                        result,
                        task_id,
                    )
            self._record_profiler_state_update(task_id, node_name, state, result)
            return result
        return wrapped

    def _record_human_wait(
        self,
        task_id: str,
        prompt_type: str,
        wait_started: float,
        response: Any,
        payload: Optional[Dict[str, Any]] = None,
        started_at: Optional[str] = None,
    ) -> None:
        self.profiler.record_confirmation(
            task_id=task_id,
            prompt_type=prompt_type,
            response=response,
            duration_seconds=time.perf_counter() - wait_started,
            payload=payload or {},
            started_at=started_at,
        )
        self.profiler.flush(task_id)

    def _prompt_user(
        self,
        task_id: str,
        stage: str,
        prompt: str,
        payload: Optional[Dict[str, Any]] = None,
        started_at: Optional[str] = None,
        multiline: bool = False,
    ) -> str:
        """Collect human input with timeout and waiting-state persistence."""
        try:
            if multiline:
                response = safe_multiline_input(
                    prompt,
                    timeout_seconds=self.input_timeout_seconds,
                    history=False,
                )
            else:
                response = safe_input(
                    prompt,
                    timeout_seconds=self.input_timeout_seconds,
                    history=(stage == "interactive_prompt"),
                )
                if stage == "interactive_prompt":
                    continuation_lines = read_pending_paste_lines()
                    if continuation_lines:
                        response = "\n".join([response, *continuation_lines])
            clear_waiting_state(self.data_path, task_id)
            return response
        except HumanInputUnavailable as exc:
            if stage == "wiki_ingest_offer":
                # This prompt is optional terminal post-processing.  Do not
                # persist it as resumable task input or overwrite the task's
                # completed status when no interactive stdin is available.
                clear_waiting_state(self.data_path, task_id)
                restore_terminal_state()
                raise
            path = save_waiting_state(
                self.data_path,
                task_id,
                stage=stage,
                prompt=prompt,
                payload=payload or {},
                reason=type(exc).__name__,
                timeout_seconds=self.input_timeout_seconds,
                started_at=started_at,
            )
            if self.state_manager:
                try:
                    self.state_manager.update_task_status(task_id, "waiting_user")
                except Exception:
                    pass
            restore_terminal_state()
            print(
                f"\n{Fore.YELLOW}⏸ Waiting for user input saved to {path}. "
                f"Resume later with /resume {task_id}.{Style.RESET_ALL}"
            )
            raise

    async def _aprompt_user(
        self,
        task_id: str,
        stage: str,
        prompt: str,
        payload: Optional[Dict[str, Any]] = None,
        started_at: Optional[str] = None,
        multiline: bool = False,
    ) -> str:
        if os.name == "posix" and sys.stdin.isatty():
            return self._prompt_user(
                task_id,
                stage,
                prompt,
                payload,
                started_at,
                multiline,
            )
        return await asyncio.to_thread(
            self._prompt_user,
            task_id,
            stage,
            prompt,
            payload,
            started_at,
            multiline,
        )

    async def _suspend_for_human_input(
        self,
        task_id: str,
        stage: str,
        messages: List[BaseMessage],
        payload: Dict[str, Any],
        reason: str,
    ) -> Dict[str, Any]:
        content = f"⏸ Waiting for human input at {stage}: {reason}"
        await self._observe_session_memory(
            task_id,
            stage,
            messages + [HumanMessage(content=content)],
            {"decision": "waiting_user", "payload": payload, "reason": reason},
        )
        return {
            "messages": [HumanMessage(content=content)],
            "next_step": "human_input",
        }

    @staticmethod
    def _finalize_digest(value: Any) -> str:
        encoded = json.dumps(
            value,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        return hashlib.sha256(encoded.encode("utf-8")).hexdigest()

    @staticmethod
    def _finalize_constraint_source_ids(value: Mapping[str, Any]) -> List[str]:
        source_ids = [
            str(item.get("source_id") or item.get("source_ref") or "").strip()
            for item in value.get("provenance", []) or []
            if isinstance(item, Mapping)
        ]
        fallback = str(value.get("source_id") or value.get("source_ref") or "").strip()
        if fallback:
            source_ids.append(fallback)
        return list(dict.fromkeys(item for item in source_ids if item))

    def _consultant_finalize_contract_projection(
        self,
        task_spec: Mapping[str, Any],
        deterministic_base_constraints: Sequence[Mapping[str, Any]],
        *,
        fallback_source_id: str,
    ) -> Tuple[Dict[str, Any], List[Dict[str, Any]]]:
        """Project fresh open-text requirements without semantic compilation.

        Source-addressable semantic directives are retained only for explicit
        typed/legacy constraints already present in the deterministic base.
        Arbitrary TaskSpec requirements remain ordered open text and therefore
        create no fresh semantic tuple or exact coverage gap.
        """
        normalized = ensure_task_spec(task_spec)
        effective = effective_task_contract(normalized)
        directives: List[Dict[str, Any]] = []
        for constraint in deterministic_base_constraints:
            if not isinstance(constraint, Mapping):
                continue
            semantic_key = str(constraint.get("semantic_key") or "").strip()
            operator = str(constraint.get("operator") or "").strip()
            if not semantic_key or not operator:
                continue
            category = semantic_key.split(".", 1)[0]
            value = deepcopy(constraint.get("value"))
            source_ids = self._finalize_constraint_source_ids(constraint) or [fallback_source_id]
            directive_id = str(
                constraint.get("constraint_id")
                or constraint.get("directive_id")
                or ""
            ).strip() or "directive-" + self._finalize_digest({
                "semantic_key": semantic_key,
                "operator": operator,
                "value": value,
                "source_ids": source_ids,
            })[:20]
            directives.append({
                "directive_id": directive_id,
                "directive_kind": category or "typed_constraint",
                "semantic_key": semantic_key,
                "operator": operator,
                "normalized_value": value,
                "normalized_text": str(constraint.get("source_text") or value or "").strip(),
                "strength": str(constraint.get("strength") or "hard"),
                "enforcement_scope": semantic_constraint_enforcement_scope(constraint),
                "condition": deepcopy(constraint.get("condition")),
                "source_ids": source_ids,
            })

        categorized: Dict[str, List[Dict[str, Any]]] = {
            "required_behavior": [],
            "forbidden_behavior": [],
            "preference": [],
            "conditional_policy": [],
            "failure_policy": [],
            "runtime_constraint": [],
        }
        for constraint in deterministic_base_constraints:
            if not isinstance(constraint, Mapping):
                continue
            category = str(constraint.get("semantic_key") or "").split(".", 1)[0]
            if category in categorized:
                categorized[category].append(deepcopy(dict(constraint)))
        highlighted_requirements = []
        for requirement in effective.get("requirements") or []:
            if not isinstance(requirement, Mapping):
                continue
            source_refs = self._finalize_constraint_source_ids(requirement) or [
                fallback_source_id
            ]
            highlighted_requirements.append({
                "text": deepcopy(requirement.get("value")),
                "importance": str(
                    requirement.get("strength")
                    or requirement.get("level")
                    or "required"
                ),
                "source_refs": [
                    (
                        "source-ref-" + hashlib.sha256(
                            str(source_ref).encode("utf-8")
                        ).hexdigest()[:16]
                        if re.match(
                            r"^(?:sha256:[0-9a-f]{32,}|"
                            r"(?:object|audit|evidence):sha256:[0-9a-f]{16,}|"
                            r"cas:[A-Za-z0-9._:-]+)$",
                            str(source_ref),
                            flags=re.IGNORECASE,
                        )
                        else str(source_ref)
                    )
                    for source_ref in source_refs
                ],
            })
        contract = {
            "goal": str(normalized.get("goal") or ""),
            "required_inputs": deepcopy(list(effective.get("inputs") or [])),
            "required_outputs": deepcopy(list(effective.get("outputs") or [])),
            "highlighted_requirements": highlighted_requirements,
            "required_behaviors": categorized["required_behavior"],
            "forbidden_behaviors": categorized["forbidden_behavior"],
            "preferences": categorized["preference"],
            "conditional_policies": categorized["conditional_policy"],
            "failure_policies": categorized["failure_policy"],
            "runtime_constraints": categorized["runtime_constraint"],
            # ``effective_task_contract`` exposes active parameter facts as an
            # ordered array.  Treating that array as ``dict(...)`` crashes as
            # soon as a task has a real parameter binding (for example
            # ``cli.gtf22=true``), before FINALIZE can initialize its durable
            # protocol state.
            "parameters": deepcopy(list(effective.get("parameters") or [])),
            "decisions": deepcopy(list(effective.get("decisions") or [])),
            "source_refs": deepcopy(list(effective.get("source_refs") or [])),
            "source_addressable_directives": directives,
        }
        return contract, []

    @staticmethod
    def _consultant_finalize_runtime_evidence(
        consultation_state: Mapping[str, Any],
    ) -> List[Dict[str, Any]]:
        rows: List[Dict[str, Any]] = []
        for fingerprint, action in sorted((consultation_state.get("actions") or {}).items()):
            if not isinstance(action, Mapping):
                continue
            rows.append({
                "evidence_id": f"action:{fingerprint}",
                "fingerprint": str(fingerprint),
                "status": str(action.get("status") or ""),
                "requirement_ids": list(action.get("requirement_ids") or []),
                "purpose": str(action.get("purpose") or ""),
                "expected_evidence": deepcopy(action.get("expected_evidence")),
                "observation": str(action.get("observation") or ""),
                "returncode": action.get("returncode"),
                "provenance": deepcopy(dict(action.get("provenance") or {})),
                "trust": "untrusted_runtime_data",
            })
        for evidence in consultation_state.get("evidence", []) or []:
            if not isinstance(evidence, Mapping):
                continue
            evidence_id = str(evidence.get("evidence_id") or "")
            if evidence_id and not any(row.get("evidence_id") == evidence_id for row in rows):
                rows.append({
                    key: deepcopy(value)
                    for key, value in evidence.items()
                    if key not in {"recorded_at", "updated_at", "created_at"}
                })
        return rows

    def _build_consultant_finalize_context(
        self,
        *,
        task_id: str,
        task_spec: Mapping[str, Any],
        consultation_state: Mapping[str, Any],
        resolved_selected_skill_ids: Sequence[str],
        input_audit: Mapping[str, Any],
        task_is_skill_free: bool = False,
    ):
        task_revision = task_spec_revision(task_spec)
        fallback_source_id = f"task-contract:{task_id}:revision:{task_revision}"
        base_constraints = semantic_constraints_from_task_spec(task_spec)
        provenance_catalog = semantic_provenance_catalog(
            task_spec,
            consultation_state=consultation_state,
            selected_skill_ids=resolved_selected_skill_ids,
        )
        if not any(str(item.get("source_id") or "") == fallback_source_id for item in provenance_catalog):
            provenance_catalog.append({
                "source_id": fallback_source_id,
                "source_type": "task_contract",
                "label": "controller TaskSpec binding",
            })
        effective_contract, coverage_gaps = self._consultant_finalize_contract_projection(
            task_spec,
            base_constraints,
            fallback_source_id=fallback_source_id,
        )
        catalog_ids = {
            str(item.get("source_id") or "")
            for item in provenance_catalog
            if isinstance(item, Mapping)
        }
        unresolved_semantics: List[Dict[str, Any]] = []
        for requirement in effective_task_contract(task_spec).get("requirements") or []:
            if not isinstance(requirement, Mapping) or not bool(requirement.get("needs_clarification")):
                continue
            item = deepcopy(dict(requirement))
            identifier = str(item.get("requirement_id") or item.get("constraint_id") or "").strip()
            if not identifier:
                identifier = "ambiguity-" + self._finalize_digest(item)[:20]
            # FINALIZE v2's immutable ambiguity index is named constraint_id;
            # this is an ephemeral protocol alias for the canonical open-text
            # requirement_id, not a TaskSpec semantic identity.
            item["constraint_id"] = identifier
            item.setdefault(
                "unresolved_reason",
                f"TaskSpec marks open-text requirement {identifier} as unresolved.",
            )
            source_ids = self._finalize_constraint_source_ids(item)
            if not source_ids:
                item["provenance"] = [{
                    "source_type": "task_contract",
                    "source_id": fallback_source_id,
                }]
            elif not set(source_ids).issubset(catalog_ids):
                # An unresolved ambiguity without a resolvable source is an
                # internal contract defect, never a user question.
                raise ValueError(
                    "Unresolved semantic ambiguity has provenance outside the active catalog: "
                    + identifier
                )
            unresolved_semantics.append(item)

        effective_revision = str(
            effective_task_contract(task_spec).get("effective_facts_revision")
            or resolve_effective_user_facts(task_spec).get("effective_facts_revision")
            or canonical_constraint_hash(task_spec)
        )
        requirements = [
            {
                key: deepcopy(value)
                for key, value in dict(item).items()
                if key not in {"created_at", "updated_at", "recorded_at"}
            }
            for item in (consultation_state.get("requirements") or {}).values()
            if isinstance(item, Mapping)
        ]
        controller_required_constraints = canonicalize_finalize_constraints(
            semantic_constraints_from_task_spec(
                task_spec,
                selected_skill_ids=resolved_selected_skill_ids,
            )
        )
        return build_finalize_context(
            task_id=task_id,
            task_spec_revision=task_revision,
            effective_facts_revision=effective_revision,
            resolved_selected_skill_ids=list(resolved_selected_skill_ids),
            effective_task_contract=effective_contract,
            coverage_gaps=coverage_gaps,
            deterministic_base_constraints=base_constraints,
            semantic_provenance_catalog=provenance_catalog,
            runtime_evidence=self._consultant_finalize_runtime_evidence(consultation_state),
            input_audit=input_audit,
            consultation_requirements=requirements,
            unresolved_semantics=unresolved_semantics,
            task_spec_binding_hash=finalize_task_spec_binding_hash(
                task_spec,
                selected_skill_ids=resolved_selected_skill_ids,
            ),
            controller_required_constraints=controller_required_constraints,
            task_is_skill_free=bool(task_is_skill_free),
        )

    def _consultant_finalize_provider_settings(
        self,
        response_schema: Mapping[str, Any],
    ) -> Dict[str, Any]:
        endpoint = str(getattr(self, "llm_endpoint_id", LLM_BASE_URL) or "")
        model = str(getattr(self, "llm_model_id", LLM_DEFAULT_MODEL) or "")
        endpoint_hostname, endpoint_identity = _finalize_endpoint_identity(endpoint)
        provider_id = str(getattr(self, "llm_provider_id", "openai") or "openai")
        if endpoint_hostname in {"api.deepseek.com", "platform.deepseek.com"}:
            provider_id = "deepseek"
        elif endpoint_hostname in {
            "dashscope.aliyuncs.com",
            "dashscope-intl.aliyuncs.com",
        }:
            provider_id = "dashscope"
        strict_schema = bool(
            getattr(self, "llm_finalize_strict_schema_supported", None)
            if getattr(self, "llm_finalize_strict_schema_supported", None) is not None
            else provider_id == "openai" and endpoint_hostname == "api.openai.com"
        )
        idempotency_supported = bool(
            getattr(self, "llm_finalize_idempotency_supported", False)
        )
        # Every newly emitted v2 request asks for a structured JSON object.
        # ``compat_text`` is parse-only support for historical persisted
        # payloads; selecting it for an unknown current provider would silently
        # weaken the wire contract.
        structured_mode = "strict_schema" if strict_schema else "json_object"
        response_format: Optional[Dict[str, Any]] = None
        if structured_mode == "strict_schema":
            response_format = {
                "type": "json_schema",
                "json_schema": {
                    "name": str(response_schema.get("$id") or "ConsultantFinalizeResult_v2").replace(".", "_"),
                    "strict": True,
                    "schema": deepcopy(dict(response_schema)),
                },
            }
        elif structured_mode == "json_object":
            response_format = {"type": "json_object"}
        extra_body = deepcopy(dict(getattr(self, "llm_response_extra_body", {}) or {}))
        thinking = "disabled"
        if isinstance(extra_body.get("thinking"), Mapping):
            thinking = str(extra_body["thinking"].get("type") or "disabled")
        elif "enable_thinking" in extra_body:
            thinking = "enabled" if bool(extra_body.get("enable_thinking")) else "disabled"
        schema_encoded = json.dumps(
            response_schema,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            default=str,
        )
        return {
            "provider_id": provider_id,
            "endpoint_id": endpoint_identity,
            "endpoint_hostname": endpoint_hostname,
            "idempotency_supported": idempotency_supported,
            "model": model,
            "temperature": (
                float(DEEPSEEK_TEMPERATURE)
                if provider_id == "deepseek"
                else 0.0
            ),
            "top_p": 1.0,
            "max_output_tokens": int(CONSULTANT_FINALIZE_MAX_OUTPUT_TOKENS),
            "requested_output_tokens": int(CONSULTANT_FINALIZE_MAX_OUTPUT_TOKENS),
            "provider_output_cap": int(
                CONSULTANT_FINALIZE_PROVIDER_OUTPUT_CAP_TOKENS
            ),
            "provider_context_limit": int(
                min(
                    int(CONSULTANT_FINALIZE_CONTEXT_LIMIT_TOKENS),
                    int(getattr(self, "llm_context_limit_tokens", 200_000)),
                )
            ),
            "output_safety_headroom_tokens": int(
                CONSULTANT_FINALIZE_OUTPUT_HEADROOM_TOKENS
            ),
            "per_call_timeout_ms": int(
                CONSULTANT_FINALIZE_PER_CALL_TIMEOUT_MS
            ),
            "output_token_parameter": "max_tokens",
            "stream": False,
            "structured_output_mode": structured_mode,
            "response_format": response_format,
            "schema_id": str(response_schema.get("$id") or "ConsultantFinalizeResult.v2"),
            "schema_hash": hashlib.sha256(schema_encoded.encode("utf-8")).hexdigest(),
            "thinking": thinking,
            "extra_body_allowlist": extra_body,
        }

    @staticmethod
    def _consultant_finalize_patch_permissions(
        errors: Sequence[Mapping[str, Any]],
        *,
        previous_allowed_fields_by_index: Optional[Mapping[Any, Sequence[str]]] = None,
        previous_allowed_payload_fields: Optional[Sequence[str]] = None,
        preserve_previous: bool = False,
    ) -> Tuple[Dict[str, List[str]], List[str], Dict[str, List[int]]]:
        """Derive field-patch authority only from machine validation errors."""
        if preserve_previous:
            allowed_by_index = {
                str(int(index)): sorted({
                    str(field).strip()
                    for field in fields or []
                    if str(field).strip()
                })
                for index, fields in (previous_allowed_fields_by_index or {}).items()
            }
            allowed_payload = sorted({
                str(field).strip()
                for field in (previous_allowed_payload_fields or [])
                if str(field).strip()
            })
        else:
            allowed_by_index: Dict[str, List[str]] = {}
            allowed_payload: List[str] = []

        errors_by_field: Dict[str, List[int]] = {}
        for error in errors or []:
            if not isinstance(error, Mapping):
                continue
            try:
                index = int(error.get("index", -1))
            except (TypeError, ValueError):
                index = -1
            field = str(error.get("field") or "").strip()
            path = str(error.get("path") or "").strip()
            if not field and path.startswith("$."):
                first = path[2:].split("[", 1)[0].split(".", 1)[0]
                field = first.strip()
            if not field:
                continue
            errors_by_field.setdefault(field, [])
            if index not in errors_by_field[field]:
                errors_by_field[field].append(index)
            if preserve_previous:
                continue
            if index >= 0:
                key = str(index)
                allowed_by_index.setdefault(key, [])
                if field not in allowed_by_index[key]:
                    allowed_by_index[key].append(field)
            elif field not in allowed_payload:
                allowed_payload.append(field)
        for fields in allowed_by_index.values():
            fields.sort()
        return (
            dict(sorted(allowed_by_index.items(), key=lambda item: int(item[0]))),
            sorted(allowed_payload),
            {
                field: sorted(indexes)
                for field, indexes in sorted(errors_by_field.items())
            },
        )

    @staticmethod
    def _consultant_finalize_ambiguity_question(
        ambiguity: Mapping[str, Any],
    ) -> str:
        """Render one controller-owned question; never trust model wording."""
        semantic_key = str(
            ambiguity.get("semantic_key")
            or ambiguity.get("constraint_id")
            or "semantic decision"
        ).strip()
        reason = str(
            ambiguity.get("unresolved_reason")
            or ambiguity.get("ambiguity")
            or "The current task contract does not determine one required value."
        ).strip()
        alternatives = [
            str(item).strip()
            for item in ambiguity.get("alternatives", []) or []
            if str(item).strip()
        ]
        suffix = (
            " Available choices: " + "; ".join(alternatives) + "."
            if alternatives
            else ""
        )
        return f"Please clarify `{semantic_key}`: {reason}.{suffix}".replace("..", ".")

    def _resolve_consultant_finalize_skills(
        self,
        *,
        state: Mapping[str, Any],
        consultation_state: Mapping[str, Any],
        max_skills: int,
    ) -> List[str]:
        """Project only Consultant-committed selections into finalize state."""
        discovery = normalize_skill_discovery_state(
            consultation_state.get("skill_discovery")
            if isinstance(consultation_state, Mapping)
            else {}
        )
        declared = [
            *list(state.get("selected_skills") or []),
            *list(consultation_state.get("resolved_selected_skill_ids") or []),
            *[
                str(item.get("skill_id") or "")
                for item in discovery.get("selected_skill_refs") or []
                if isinstance(item, Mapping)
                and str(item.get("status") or "selected") == "selected"
            ],
        ]
        if self.skill_manager:
            resolved = self.skill_manager.normalize_selected_skills(
                declared,
                max_results=max_skills,
            )
        else:
            resolved = list(dict.fromkeys(
                str(item).strip() for item in declared if str(item).strip()
            ))[:max_skills]
        return resolved

    @staticmethod
    def _consultant_task_is_explicitly_skill_free(
        task_spec: Mapping[str, Any],
    ) -> bool:
        parameters = task_spec.get("parameters") or {}
        return bool(
            task_spec.get("task_is_skill_free") is True
            or (
                isinstance(parameters, Mapping)
                and parameters.get("task_is_skill_free") is True
            )
        )

    def _consultant_finalize_precondition_errors(
        self,
        *,
        task_spec: Mapping[str, Any],
        consultation_state: Mapping[str, Any],
        resolved_selected_skill_ids: Sequence[str],
        input_audit: Mapping[str, Any],
        task_is_skill_free: bool,
    ) -> List[str]:
        """Revalidate every controller-owned FINALIZE entry invariant."""
        errors: List[str] = []
        requirements = consultation_state.get("requirements") or {}
        requirement_rows = (
            list(requirements.values()) if isinstance(requirements, Mapping) else []
        )
        if not requirement_rows:
            errors.append("consultation evidence requirements are not seeded")
        else:
            unresolved = [
                str(item.get("id") or "unknown")
                for item in requirement_rows
                if isinstance(item, Mapping)
                and bool(item.get("mandatory", True))
                and str(item.get("status") or "") not in {"satisfied", "waived"}
            ]
            if unresolved:
                errors.append(
                    "mandatory evidence is unresolved: " + ", ".join(sorted(unresolved))
                )

        selected = [
            str(item).strip()
            for item in resolved_selected_skill_ids or []
            if str(item).strip()
        ]
        if not selected and not task_is_skill_free:
            errors.append("no controller-resolved canonical skill is bound")
        elif selected:
            if not self.skill_manager:
                errors.append("selected skill IDs cannot be validated without the skill catalog")
            else:
                canonical = self.skill_manager.normalize_selected_skills(
                    selected,
                    max_results=max(len(selected), 1),
                )
                if canonical != selected:
                    errors.append("selected skill IDs are unknown, aliases, duplicated, or non-canonical")
            ledger_selected = [
                str(item).strip()
                for item in consultation_state.get("resolved_selected_skill_ids", []) or []
                if str(item).strip()
            ]
            if ledger_selected and ledger_selected != selected:
                errors.append("resolved skill binding disagrees with the consultation ledger")

        audit = dict(input_audit or {})
        if bool(audit.get("relevant")):
            status = str(audit.get("status") or "").strip().lower()
            unresolved_inputs = bool(
                audit.get("unresolved")
                or audit.get("missing")
                or audit.get("missing_required_inputs")
                or audit.get("missing_roles")
                or audit.get("ambiguous_roles")
                or audit.get("ambiguous_samples")
                or audit.get("ambiguous_resolutions")
            )
            if status not in {"resolved", "passed", "complete", "satisfied", "success"}:
                errors.append(f"formal input audit is not complete: {status or 'missing_status'}")
            if unresolved_inputs:
                errors.append("formal input audit retains unresolved or ambiguous inputs")

        if task_spec_revision(task_spec) <= 0:
            errors.append("TaskSpec revision is not fixed")
        return errors

    async def _invoke_consultant_finalize_provider(
        self,
        messages: Sequence[BaseMessage],
        *,
        task_id: str,
        store: ContextLineageStore,
        attempt_id: str,
        call_id: str,
        call_kind: str,
        canonical_request_hash: str,
        settings: Mapping[str, Any],
        trace_metadata: Mapping[str, Any],
    ) -> Dict[str, Any]:
        """Provider adapter that protects exact content before diagnostics."""
        metadata = {
            **dict(trace_metadata or {}),
            "call_id": call_id,
            "attempt_id": attempt_id,
            "call_kind": call_kind,
            "canonical_request_hash": canonical_request_hash,
            "message_role_sequence": [str(getattr(item, "type", "")) for item in messages],
            "structured_output_mode": settings.get("structured_output_mode"),
            "diagnostic_only": True,
            "exact_content_in_projection": False,
        }
        diagnostic_messages: List[Dict[str, Any]] = []
        for item in messages:
            exact_content = str(getattr(item, "content", "") or "")
            redacted_content = redact_lineage_text(exact_content)
            excerpt_limit = 2048
            diagnostic_messages.append({
                "role": str(getattr(item, "type", "") or "message"),
                "content": redacted_content[:excerpt_limit],
                "content_char_count": len(exact_content),
                "content_sha256": hashlib.sha256(exact_content.encode("utf-8")).hexdigest(),
                "content_excerpt_truncated": len(redacted_content) > excerpt_limit,
                "diagnostic_only": True,
                "exact_content_in_projection": False,
            })
        try:
            store.start_call(diagnostic_messages, metadata)
        except Exception as exc:
            # Diagnostic lineage is intentionally non-authoritative.  Its
            # failure must neither prevent the protected provider call nor be
            # confused with request-intent/response-artifact persistence.
            logger.warning("Finalize diagnostic request projection failed: %s", exc)
        wire_payload = _build_finalize_wire_payload(messages, settings)
        effective_wire = _finalize_effective_wire_projection(
            wire_payload,
            settings,
        )
        expected_token_key = str(settings.get("output_token_parameter") or "max_tokens")
        if (
            str(effective_wire.get("output_token_parameter") or "")
            != expected_token_key
            or int(effective_wire.get("output_token_value") or 0)
            != int(settings.get("max_output_tokens") or 0)
        ):
            raise ValueError(
                "FINALIZE_PROVIDER_PARAMETER_UNSUPPORTED: requested and effective wire settings disagree"
            )
        wire_artifact = store.persist_finalize_effective_wire_settings(
            attempt_id=attempt_id,
            call_id=call_id,
            canonical_request_hash=canonical_request_hash,
            settings=effective_wire,
        )
        timeout_ms = int(settings.get("per_call_timeout_ms") or 0)
        if timeout_ms <= 0:
            raise ValueError(
                "FINALIZE_GLOBAL_BUDGET_EXHAUSTED:per_call_timeout_ms"
            )

        # The installed ChatOpenAI wrapper rewrites ``max_tokens`` to
        # ``max_completion_tokens``.  For DeepSeek, bypass only that wrapper
        # and call its already-configured AsyncCompletions resource with the
        # inspected body above.  Test doubles and non-DeepSeek providers retain
        # the ordinary LangChain invocation path.
        direct_async_client = getattr(self.llm, "async_client", None)
        use_direct_chat_completions = bool(
            str(settings.get("provider_id") or "").lower() == "deepseek"
            and direct_async_client is not None
            and callable(getattr(direct_async_client, "create", None))
        )
        completion_usage: Dict[str, Any] = {}
        if use_direct_chat_completions:
            direct_kwargs = deepcopy(wire_payload)
            if bool(settings.get("idempotency_supported")):
                direct_kwargs["extra_headers"] = {
                    "Idempotency-Key": f"finalize:{canonical_request_hash}"
                }
            invoke_task = asyncio.create_task(
                direct_async_client.create(**direct_kwargs)
            )
        else:
            invocation_llm = self.llm
            if hasattr(invocation_llm, "model_copy"):
                try:
                    invocation_llm = invocation_llm.model_copy(
                        update={"max_retries": 0, "streaming": False}
                    )
                except Exception:
                    pass
            bind_kwargs: Dict[str, Any] = {
                "temperature": float(settings.get("temperature") or 0.0),
                "top_p": float(settings.get("top_p") or 1.0),
                expected_token_key: int(settings.get("max_output_tokens") or 0),
                "stream": False,
            }
            if settings.get("response_format"):
                bind_kwargs["response_format"] = deepcopy(settings["response_format"])
            if bool(settings.get("idempotency_supported")):
                bind_kwargs["extra_headers"] = {
                    "Idempotency-Key": f"finalize:{canonical_request_hash}"
                }
            if hasattr(invocation_llm, "bind"):
                invocation_llm = invocation_llm.bind(**bind_kwargs)
            invoke_task = asyncio.create_task(invocation_llm.ainvoke(list(messages)))
        # The adapter and durable reservation must enforce one authoritative
        # timeout.  A generic LLM wrapper timeout may differ and therefore
        # cannot override the versioned FINALIZE work-budget policy.
        timeout = float(timeout_ms) / 1_000.0
        try:
            done, _ = await asyncio.wait({invoke_task}, timeout=timeout)
            if not done:
                invoke_task.cancel()
                raise TimeoutError(f"consultant finalize provider outcome unknown after {timeout:.0f}s")
            try:
                response = invoke_task.result()
            except asyncio.CancelledError as exc:
                raise TimeoutError("consultant finalize provider call was cancelled") from exc
            if use_direct_chat_completions:
                completion_projection = _finalize_completion_projection(response)
                completion_usage = deepcopy(
                    dict(completion_projection.get("usage") or {})
                )
                raw_response = str(completion_projection.get("raw_response") or "")
                finish_reason = str(completion_projection.get("finish_reason") or "")
                provider_metadata = deepcopy(
                    dict(completion_projection.get("provider_metadata") or {})
                )
                provider_metadata["effective_wire_settings_ref"] = str(
                    wire_artifact.get("effective_wire_settings_ref") or ""
                )
                provider_metadata["effective_wire_settings_hash"] = str(
                    wire_artifact.get("effective_wire_settings_hash") or ""
                )
                if finish_reason not in {"stop", "tool_calls"}:
                    integrity = (
                        "truncated" if finish_reason == "length"
                        else "content_filtered"
                        if finish_reason == "content_filter"
                        else "unknown"
                    )
                    content_available = bool(raw_response)
                    partial = store.persist_finalize_partial_response(
                        attempt_id=attempt_id,
                        call_id=call_id,
                        canonical_request_hash=canonical_request_hash,
                        raw_partial_response=(raw_response if content_available else None),
                        finish_reason=finish_reason or "unknown",
                        usage=dict(completion_projection.get("usage") or {}),
                        provider_metadata=provider_metadata,
                        content_available=content_available,
                        content_unavailable_reason=(
                            "" if content_available
                            else "provider_completion_content_unavailable"
                        ),
                        completion_integrity=integrity,
                    )
                    try:
                        store.finish_call(
                            call_id,
                            {
                                "role": "diagnostic",
                                "content": "",
                                "finish_reason": finish_reason,
                                "completion_integrity": integrity,
                                "partial_response_artifact_ref": partial.get(
                                    "partial_response_artifact_ref"
                                ),
                                "usage": completion_projection.get("usage") or {},
                            },
                            status="truncated" if integrity == "truncated" else "blocked",
                        )
                    except Exception as trace_exc:
                        logger.warning(
                            "Finalize partial diagnostic projection failed: %s",
                            trace_exc,
                        )
                    return {
                        "response": response,
                        "raw_response": "",
                        "structured_object": None,
                        "artifact": {},
                        "partial_artifact": partial,
                        "finish_reason": finish_reason,
                        "usage": deepcopy(dict(completion_projection.get("usage") or {})),
                        "completion_integrity": integrity,
                        "provider_status": "succeeded",
                        "protocol_status": "not_validated",
                        "response_reused_from_checkpoint": False,
                    }
                additional: Mapping[str, Any] = {}
                structured_object = None
            else:
                additional = getattr(response, "additional_kwargs", {}) or {}
                raw_response = ""
                finish_reason = str(
                    (getattr(response, "response_metadata", {}) or {}).get(
                        "finish_reason"
                    )
                    or "stop"
                )
            structured_object = None
            if isinstance(additional, Mapping):
                parsed = additional.get("parsed")
                if isinstance(parsed, Mapping):
                    structured_object = deepcopy(dict(parsed))
                elif hasattr(parsed, "model_dump"):
                    dumped = parsed.model_dump()
                    if isinstance(dumped, Mapping):
                        structured_object = deepcopy(dict(dumped))

            # Preserve only exact text actually exposed by the SDK.  A Python
            # list/dict serialization invented by this adapter is not an exact
            # assistant wire response and must not masquerade as one.
            content = getattr(response, "content", "")
            if not raw_response:
                raw_response = content if isinstance(content, str) else ""
            if not raw_response and isinstance(additional, Mapping):
                sdk_raw = additional.get("raw")
                sdk_raw_content = (
                    sdk_raw
                    if isinstance(sdk_raw, str)
                    else getattr(sdk_raw, "content", "")
                )
                if isinstance(sdk_raw_content, str):
                    raw_response = sdk_raw_content
            if not use_direct_chat_completions:
                provider_metadata = deepcopy(
                    dict(getattr(response, "response_metadata", {}) or {})
                )
                provider_metadata["finish_reason"] = finish_reason
                provider_metadata["effective_wire_settings_ref"] = str(
                    wire_artifact.get("effective_wire_settings_ref") or ""
                )
                provider_metadata["effective_wire_settings_hash"] = str(
                    wire_artifact.get("effective_wire_settings_hash") or ""
                )
                completion_usage = deepcopy(dict(
                    provider_metadata.get("token_usage")
                    or provider_metadata.get("usage")
                    or {}
                ))
            if finish_reason not in {"stop", "tool_calls"}:
                integrity = (
                    "truncated" if finish_reason == "length"
                    else "content_filtered"
                    if finish_reason == "content_filter"
                    else "unknown"
                )
                usage = dict(
                    provider_metadata.get("token_usage")
                    or provider_metadata.get("usage")
                    or {}
                )
                content_available = bool(raw_response)
                partial = store.persist_finalize_partial_response(
                    attempt_id=attempt_id,
                    call_id=call_id,
                    canonical_request_hash=canonical_request_hash,
                    raw_partial_response=(raw_response if content_available else None),
                    finish_reason=finish_reason or "unknown",
                    usage=usage,
                    provider_metadata=provider_metadata,
                    content_available=content_available,
                    content_unavailable_reason=(
                        "" if content_available
                        else "provider_completion_content_unavailable"
                    ),
                    completion_integrity=integrity,
                )
                try:
                    store.finish_call(
                        call_id,
                        {
                            "role": "diagnostic",
                            "content": "",
                            "finish_reason": finish_reason,
                            "completion_integrity": integrity,
                            "partial_response_artifact_ref": partial.get(
                                "partial_response_artifact_ref"
                            ),
                            "usage": usage,
                        },
                        status="truncated" if integrity == "truncated" else "blocked",
                    )
                except Exception as trace_exc:
                    logger.warning(
                        "Finalize returned-partial diagnostic projection failed: %s",
                        trace_exc,
                    )
                return {
                    "response": response,
                    "raw_response": "",
                    "structured_object": None,
                    "artifact": {},
                    "partial_artifact": partial,
                    "finish_reason": finish_reason,
                    "usage": usage,
                    "completion_integrity": integrity,
                    "provider_status": "succeeded",
                    "protocol_status": "not_validated",
                    "response_reused_from_checkpoint": False,
                }
            try:
                artifact = persist_finalize_response(
                    store,
                    attempt_id=attempt_id,
                    call_id=call_id,
                    canonical_request_hash=canonical_request_hash,
                    raw_response=raw_response,
                    structured_object=structured_object,
                    provider_metadata=provider_metadata,
                )
            except Exception as exc:
                raise FinalizeResponsePersistenceError(
                    "provider returned but protected finalize persistence failed",
                    response_content_hash=hashlib.sha256(
                        raw_response.encode("utf-8")
                    ).hexdigest(),
                ) from exc
            try:
                diagnostic = store.finalize_diagnostic_projection({
                    **artifact,
                    "raw_response": raw_response,
                })
                store.finish_call(
                    call_id,
                    {
                        "role": "diagnostic",
                        "content": "",
                        "finalize_response_projection": diagnostic,
                    },
                )
            except Exception as exc:
                logger.warning("Finalize diagnostic projection failed after protected persistence: %s", exc)
            return {
                "response": response,
                "raw_response": raw_response,
                "structured_object": structured_object,
                "artifact": artifact,
                "finish_reason": finish_reason or "stop",
                "usage": completion_usage,
                "completion_integrity": "complete",
                "provider_status": "succeeded",
                "protocol_status": "not_validated",
                "response_reused_from_checkpoint": False,
            }
        except BaseException as exc:
            delivered_completion = _finalize_exception_completion(exc)
            if delivered_completion is not None:
                projection = _finalize_completion_projection(delivered_completion)
                finish_reason = str(projection.get("finish_reason") or "unknown")
                integrity = (
                    "truncated" if finish_reason == "length"
                    else "content_filtered"
                    if finish_reason == "content_filter"
                    else "unknown"
                )
                raw_partial = str(projection.get("raw_response") or "")
                content_available = bool(raw_partial)
                provider_metadata = deepcopy(
                    dict(projection.get("provider_metadata") or {})
                )
                provider_metadata["exception_type"] = type(exc).__name__
                provider_metadata["effective_wire_settings_ref"] = str(
                    wire_artifact.get("effective_wire_settings_ref") or ""
                )
                provider_metadata["effective_wire_settings_hash"] = str(
                    wire_artifact.get("effective_wire_settings_hash") or ""
                )
                try:
                    partial = store.persist_finalize_partial_response(
                        attempt_id=attempt_id,
                        call_id=call_id,
                        canonical_request_hash=canonical_request_hash,
                        raw_partial_response=(raw_partial if content_available else None),
                        finish_reason=finish_reason,
                        usage=dict(projection.get("usage") or {}),
                        provider_metadata=provider_metadata,
                        content_available=content_available,
                        content_unavailable_reason=(
                            "" if content_available
                            else "provider_exception_completion_content_unavailable"
                        ),
                        completion_integrity=integrity,
                    )
                except Exception as persist_exc:
                    raise FinalizeResponsePersistenceError(
                        "provider delivered a partial completion but protected persistence failed",
                        response_content_hash=hashlib.sha256(
                            raw_partial.encode("utf-8")
                        ).hexdigest(),
                    ) from persist_exc
                try:
                    store.finish_call(
                        call_id,
                        {
                            "role": "diagnostic",
                            "content": "",
                            "finish_reason": finish_reason,
                            "completion_integrity": integrity,
                            "partial_response_artifact_ref": partial.get(
                                "partial_response_artifact_ref"
                            ),
                            "usage": projection.get("usage") or {},
                        },
                        status="truncated" if integrity == "truncated" else "blocked",
                    )
                except Exception as trace_exc:
                    logger.warning(
                        "Finalize typed partial diagnostic projection failed: %s",
                        trace_exc,
                    )
                return {
                    "response": delivered_completion,
                    "raw_response": "",
                    "structured_object": None,
                    "artifact": {},
                    "partial_artifact": partial,
                    "finish_reason": finish_reason,
                    "usage": deepcopy(dict(projection.get("usage") or {})),
                    "completion_integrity": integrity,
                    "provider_status": "succeeded",
                    "protocol_status": "not_validated",
                    "response_reused_from_checkpoint": False,
                }
            try:
                store.fail_call(call_id, exc)
            except Exception as trace_exc:
                logger.warning("Failed to persist finalize diagnostic failure: %s", trace_exc)
            raise
        finally:
            if not invoke_task.done():
                invoke_task.cancel()

    async def _run_consultant_finalize(
        self,
        *,
        state: Mapping[str, Any],
        task_id: str,
        task_spec: Mapping[str, Any],
        consultation_state: Mapping[str, Any],
        resolved_selected_skill_ids: Sequence[str],
        input_audit: Mapping[str, Any],
        consultant_wiki_context: str = "",
        consultant_memory_retrieval_context: str = "",
    ) -> Dict[str, Any]:
        """Dispatch FINALIZE without ever interpreting one wire ABI as another.

        Fresh work is schema-v4/wire-v3.  A legacy protocol that has already
        emitted an intent remains pinned to the frozen v2 runner.  The only
        automatic migration is a ready v2 owner with no provider intent; that
        creates a newly bound v4 child rather than mutating an in-flight ABI.
        """
        current = deepcopy(dict(consultation_state or {}))
        protocol_value = current.get("finalize_protocol")
        try:
            runner = finalize_protocol_runner(
                protocol_value if isinstance(protocol_value, Mapping) else None
            )
        except (TypeError, ValueError) as exc:
            diagnostic = {
                "error_code": "FINALIZE_PROTOCOL_VERSION_UNSUPPORTED",
                "error_owner": "controller",
                "detail": redact_lineage_text(str(exc))[:2000],
            }
            current.update({
                "phase": "blocked",
                "consultation_status": "blocked",
                "completion_decision": "blocked",
                "completion_reason": diagnostic["error_code"],
                "terminal_diagnostic": deepcopy(diagnostic),
                "resolved_selected_skill_ids": list(resolved_selected_skill_ids),
            })
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_finalize_internal_error>"
                    + json.dumps(diagnostic, ensure_ascii=False, sort_keys=True)
                    + "</consultant_finalize_internal_error>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": deepcopy(dict(task_spec or {})),
                "task_revision": task_spec_revision(task_spec),
                "selected_skills": list(resolved_selected_skill_ids),
                "selected_skills_raw": list(resolved_selected_skill_ids),
                "active_skills": list(resolved_selected_skill_ids),
                "required_skills_all": list(resolved_selected_skill_ids),
                "consultation_state": current,
                "pending_human_question": {},
                "contract_status": "blocked_internal_contract_error",
                "task_status": TASK_STATUS_BLOCKED,
                "failure_type": diagnostic["error_code"],
                "failure_owner": diagnostic["error_owner"],
                "next_step": "finish",
            }

        migrate_legacy = False
        if runner == "legacy_v2":
            eligibility = legacy_finalize_migration_eligibility(
                dict(protocol_value or {})
            )
            migrate_legacy = bool(eligibility.get("eligible"))
            if not migrate_legacy:
                return await self._run_consultant_finalize_v2(
                    state=state,
                    task_id=task_id,
                    task_spec=task_spec,
                    consultation_state=current,
                    resolved_selected_skill_ids=resolved_selected_skill_ids,
                    input_audit=input_audit,
                    consultant_wiki_context=consultant_wiki_context,
                    consultant_memory_retrieval_context=(
                        consultant_memory_retrieval_context
                    ),
                )

        return await self._run_consultant_finalize_v4(
            state=state,
            task_id=task_id,
            task_spec=task_spec,
            consultation_state=current,
            resolved_selected_skill_ids=resolved_selected_skill_ids,
            input_audit=input_audit,
            consultant_wiki_context=consultant_wiki_context,
            consultant_memory_retrieval_context=(
                consultant_memory_retrieval_context
            ),
            migrate_legacy_ready=migrate_legacy,
        )

    async def _run_consultant_finalize_v4(
        self,
        *,
        state: Mapping[str, Any],
        task_id: str,
        task_spec: Mapping[str, Any],
        consultation_state: Mapping[str, Any],
        resolved_selected_skill_ids: Sequence[str],
        input_audit: Mapping[str, Any],
        consultant_wiki_context: str = "",
        consultant_memory_retrieval_context: str = "",
        migrate_legacy_ready: bool = False,
    ) -> Dict[str, Any]:
        """Run the artifact-first schema-v4 controller and compact wire-v3 path."""
        current_task_spec = merge_task_spec_input_audit(task_spec, input_audit)
        current_consultation = deepcopy(dict(consultation_state or {}))
        selected = list(dict.fromkeys(
            str(item).strip()
            for item in resolved_selected_skill_ids or []
            if str(item).strip()
        ))
        current_consultation["resolved_selected_skill_ids"] = list(selected)
        task_is_skill_free = self._consultant_task_is_explicitly_skill_free(
            current_task_spec
        )

        def protocol() -> Dict[str, Any]:
            value = current_consultation.get("finalize_protocol")
            return dict(value) if isinstance(value, Mapping) else {}

        def terminal_update(
            *,
            error_code: str,
            error_owner: str,
            detail: str,
            context_initialized: bool = True,
        ) -> Dict[str, Any]:
            nonlocal current_consultation
            safe_detail = redact_lineage_text(detail or error_code).strip()[:4000]
            diagnostic = {
                "error_code": str(error_code),
                "error_owner": str(error_owner),
                "finalize_context_id": str(protocol().get("finalize_context_id") or ""),
                "base_contract_hash": str(protocol().get("base_contract_hash") or ""),
                "detail": safe_detail,
            }
            for prefix in ("work_budget", "work_preflight"):
                ref = str(protocol().get(f"{prefix}_ref") or "")
                digest = str(protocol().get(f"{prefix}_hash") or "")
                if ref and digest:
                    diagnostic[f"{prefix}_ref"] = ref
                    diagnostic[f"{prefix}_hash"] = digest
            if context_initialized and protocol() and str(
                protocol().get("finalize_status") or ""
            ) not in {"blocked", "compiled", "needs_user"}:
                try:
                    current_consultation = commit_finalize_v4_transition(
                        current_consultation,
                        {
                            "transition": "blocked",
                            "error_code": error_code,
                            "error_owner": error_owner,
                            "terminal_diagnostic": diagnostic,
                        },
                    )
                except Exception as commit_exc:
                    diagnostic["transition_error"] = (
                        f"{type(commit_exc).__name__}: {commit_exc}"
                    )[:1000]
            current_consultation.pop("final_contract", None)
            current_consultation.update({
                "phase": "blocked",
                "consultation_status": "blocked",
                "completion_decision": "blocked",
                "completion_reason": error_code,
                "resolved_selected_skill_ids": list(selected),
                "terminal_diagnostic": deepcopy(diagnostic),
            })
            output.print_once(
                f"consultant_finalize_v4_internal:{task_id}:{error_code}",
                f"⛔ Consultant FINALIZE v4 stopped before Planner: {error_code}. {safe_detail[:500]}",
                Fore.RED,
            )
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_finalize_internal_error>\n"
                    + json.dumps(diagnostic, ensure_ascii=False, sort_keys=True)
                    + "\n</consultant_finalize_internal_error>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": current_task_spec,
                "task_revision": task_spec_revision(current_task_spec),
                "selected_skills": list(selected),
                "selected_skills_raw": list(selected),
                "active_skills": list(selected),
                "required_skills_all": list(selected),
                "consultation_state": current_consultation,
                "consultant_contract_repair": {},
                "pending_human_question": {},
                "contract_status": (
                    "blocked_internal_provider_error"
                    if error_owner in {"provider", "controller_provider"}
                    else "blocked_internal_contract_error"
                ),
                "consultant_constraint_metrics": {
                    "schema_validation": "failed",
                    "protocol_schema_version": 4,
                    "wire_schema_version": 3,
                    "provider_status": str(protocol().get("provider_status") or "not_called"),
                    "completion_integrity": str(protocol().get("completion_integrity") or "not_called"),
                    "protocol_status": str(protocol().get("protocol_status") or "blocked"),
                    "error_code": error_code,
                    "error_owner": error_owner,
                },
                "task_status": TASK_STATUS_BLOCKED,
                "failure_type": error_code,
                "failure_owner": error_owner,
                "next_step": "finish",
            }

        precondition_errors = self._consultant_finalize_precondition_errors(
            task_spec=current_task_spec,
            consultation_state=current_consultation,
            resolved_selected_skill_ids=selected,
            input_audit=input_audit,
            task_is_skill_free=task_is_skill_free,
        )
        existing_protocol = protocol()
        existing_terminal_v4 = bool(
            int(existing_protocol.get("schema_version") or 0) == 4
            and int(existing_protocol.get("wire_schema_version") or 0) == 3
            and str(existing_protocol.get("finalize_status") or "")
            in {"compiled", "blocked", "needs_user"}
        )
        if existing_terminal_v4:
            # Terminal replay is artifact-first.  Rebuilding the pre-finalize
            # context from an already compiled TaskSpec would manufacture a new
            # base hash and incorrectly rebind a terminal protocol.
            context_value = {}
            context_id = str(existing_protocol.get("finalize_context_id") or "")
            base_contract_hash = str(
                existing_protocol.get("base_contract_hash") or ""
            )
        else:
            try:
                finalize_context = self._build_consultant_finalize_context(
                    task_id=task_id,
                    task_spec=current_task_spec,
                    consultation_state=current_consultation,
                    resolved_selected_skill_ids=selected,
                    input_audit=input_audit,
                    task_is_skill_free=task_is_skill_free,
                )
                context_value = thaw_finalize_value(finalize_context)
                context_id = str(context_value.get("finalize_context_id") or "")
                base_contract_hash = str(context_value.get("base_contract_hash") or "")
                previous = protocol()
                current_consultation = initialize_finalize_protocol_v4(
                    current_consultation,
                    finalize_context_id=context_id,
                    base_contract_hash=base_contract_hash,
                    replay_scope_id=f"{task_id}:finalize:{task_spec_revision(current_task_spec)}",
                    source_task_spec_revision=task_spec_revision(current_task_spec),
                    parent_finalize_context_id=(
                        str(previous.get("finalize_context_id") or "")
                        if migrate_legacy_ready else ""
                    ),
                    migration_reason=(
                        "ready_without_provider_intent" if migrate_legacy_ready else ""
                    ),
                    source_protocol_schema_version=(
                        int(previous.get("schema_version") or 0)
                        if migrate_legacy_ready else None
                    ),
                    source_wire_schema_version=(
                        int(previous.get("wire_schema_version") or 0)
                        if migrate_legacy_ready else None
                    ),
                    replace=migrate_legacy_ready,
                )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_CONTEXT_INVALID",
                    error_owner="controller",
                    detail=f"Finalize context construction failed: {type(exc).__name__}: {exc}",
                    context_initialized=False,
                )

        active_v4 = protocol()
        existing_status = str(active_v4.get("finalize_status") or "")
        if existing_status == "blocked":
            return terminal_update(
                error_code=str(
                    active_v4.get("terminal_error_code")
                    or "FINALIZE_REPAIR_EXHAUSTED"
                ),
                error_owner=str(active_v4.get("terminal_owner") or "controller"),
                detail=str(
                    (active_v4.get("terminal_diagnostic") or {}).get("detail")
                    or "FINALIZE v4 is already in a typed blocked state."
                ),
            )
        if existing_status == "needs_user":
            pending = current_consultation.get("pending_human_question")
            if not isinstance(pending, Mapping) or not str(
                pending.get("ambiguity_id") or ""
            ):
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail="A needs-user v4 checkpoint has no durable question projection.",
                )
            current_consultation.update({
                "phase": "needs_user",
                "consultation_status": "needs_user",
                "completion_decision": "needs_user",
                "completion_reason": "validated_semantic_ambiguity",
            })
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_semantic_resolution_request>"
                    + json.dumps({
                        "ambiguity_id": pending.get("ambiguity_id"),
                    }, ensure_ascii=False, sort_keys=True)
                    + "</consultant_semantic_resolution_request>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": current_task_spec,
                "task_revision": task_spec_revision(current_task_spec),
                "selected_skills": list(selected),
                "selected_skills_raw": list(selected),
                "active_skills": list(selected),
                "required_skills_all": list(selected),
                "consultation_state": current_consultation,
                "consultant_contract_repair": {},
                "pending_human_question": deepcopy(dict(pending)),
                "contract_status": "blocked_need_user_decision",
                "next_step": "ask_user",
            }
        if existing_status == "compiled":
            try:
                durable_compiled = self._load_verified_finalize_v4_contract(
                    task_id=task_id,
                    protocol=active_v4,
                    task_spec=current_task_spec,
                    selected_skill_ids=selected,
                )
                compiled_task_spec = apply_task_spec_mutation_proposal(
                    current_task_spec,
                    constraint_mutation_proposal(
                        durable_compiled.get("constraints") or []
                    ),
                    project_root=project_root,
                )
                summary = str(
                    durable_compiled.get("summary")
                    or "Consultant FINALIZE v4 reused a verified compiled contract."
                )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=f"Compiled v4 replay failed: {type(exc).__name__}: {exc}",
                )
            current_consultation.pop("final_contract", None)
            current_consultation.update({
                "phase": "finalize",
                "consultation_status": "completed",
                "completion_decision": "ready_to_finalize",
                "completion_reason": "formal_contract_compiled_v4_replay",
                "resolved_selected_skill_ids": list(selected),
                "compiled_contract_ref": str(durable_compiled.get("compiled_contract_ref") or ""),
                "compiled_contract_hash": str(durable_compiled.get("compiled_contract_hash") or ""),
            })
            return {
                "messages": [AIMessage(content="FINISH\n" + summary)],
                "input_audit": deepcopy(dict(input_audit or {})),
                "selected_skills": list(selected),
                "selected_skills_raw": list(selected),
                "active_skills": list(selected),
                "future_skills": [],
                "required_skills_all": list(selected),
                "candidate_skills": [],
                "runtime_status": self._runtime_status_for_task(task_id, selected),
                "runtime_audit": [],
                "skill_selection_source": "consultation_controller_finalize_v4",
                "requirements_summary": summary,
                "task_spec": compiled_task_spec,
                "task_revision": task_spec_revision(compiled_task_spec),
                "consultant_constraint_metrics": {
                    "schema_validation": "passed",
                    "protocol_schema_version": 4,
                    "wire_schema_version": 3,
                    "compile_mode": str(active_v4.get("compile_mode") or ""),
                    "provider_status": str(active_v4.get("provider_status") or ""),
                    "completion_integrity": str(
                        active_v4.get("completion_integrity") or ""
                    ),
                    "protocol_status": "valid",
                    "compiled_contract_ref": durable_compiled["compiled_contract_ref"],
                    "compiled_contract_hash": durable_compiled["compiled_contract_hash"],
                    "reused_from_checkpoint": True,
                },
                "consultation_state": current_consultation,
                "consultant_contract_repair": {},
                "pending_human_question": {},
                "contract_status": "semantic_contract_compiled",
                "memory_packet_context": self._consultant_handoff_memory_packet(
                    summary,
                    consultant_memory_retrieval_context,
                ),
                "wiki_memory_context": consultant_wiki_context,
                "next_step": "planner",
            }

        if precondition_errors:
            return terminal_update(
                error_code="FINALIZE_PRECONDITION_FAILED",
                error_owner="controller",
                detail="; ".join(precondition_errors),
            )

        store = ContextLineageStore(self.data_path, task_id)
        try:
            durable_context = store.persist_finalize_context_artifact(
                context_value
            )
            verified_context = store.lookup_finalize_context_artifact(
                finalize_context_id=context_id,
                base_contract_hash=base_contract_hash,
            )
            if verified_context != durable_context:
                raise SnapshotConflictError(
                    "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                )
            domain_coverage = classify_directive_coverage(context_value)
            validation = validate_directive_coverage(
                domain_coverage,
                finalize_context=context_value,
            )
            if not bool(validation.get("valid")):
                raise ValueError(
                    "coverage validation failed: "
                    + json.dumps(validation.get("errors") or [], ensure_ascii=False)
                )
            # The protected store owns its own envelope hash.  Retain the pure
            # controller hash explicitly so both identities remain auditable.
            coverage_to_persist = deepcopy(dict(domain_coverage))
            coverage_to_persist["domain_record_type"] = str(
                coverage_to_persist.pop("record_type", "")
            )
            coverage_to_persist["record_type"] = "directive_coverage_artifact"
            coverage_to_persist.update({
                "finalize_context_artifact_ref": durable_context[
                    "finalize_context_artifact_ref"
                ],
                "finalize_context_artifact_hash": durable_context[
                    "finalize_context_artifact_hash"
                ],
            })
            if str(protocol().get("coverage_artifact_hash") or ""):
                durable_coverage = store.lookup_finalize_coverage_artifact(
                    coverage_artifact_hash=str(
                        protocol().get("coverage_artifact_hash") or ""
                    ),
                    finalize_context_id=context_id,
                )
                if (
                    durable_coverage is None
                    or str(durable_coverage.get("coverage_artifact_ref") or "")
                    != str(protocol().get("coverage_artifact_ref") or "")
                    or str(durable_coverage.get("coverage_artifact_hash") or "")
                    != str(domain_coverage.get("coverage_artifact_hash") or "")
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
            else:
                durable_coverage = store.persist_finalize_coverage_artifact(
                    coverage_to_persist
                )
            expected_resolution_ids = [
                str(item.get("resolution_id") or "")
                for item in domain_coverage.get("model_resolution_items") or []
                if isinstance(item, Mapping)
                and str(item.get("resolution_id") or "")
            ]
            if (
                not str(protocol().get("coverage_artifact_hash") or "")
                and not expected_resolution_ids
            ):
                current_consultation = commit_finalize_v4_transition(
                    current_consultation,
                    {
                        "transition": "coverage_ready",
                        "coverage_artifact_ref": durable_coverage["coverage_artifact_ref"],
                        "coverage_artifact_hash": durable_coverage["coverage_artifact_hash"],
                        "expected_resolution_ids": expected_resolution_ids,
                    },
                )
        except Exception as exc:
            return terminal_update(
                error_code="FINALIZE_COVERAGE_CLASSIFICATION_INCOMPLETE",
                error_owner="controller",
                detail=f"Coverage classification/persistence failed: {type(exc).__name__}: {exc}",
            )

        unresolved = [
            deepcopy(dict(item))
            for item in context_value.get("unresolved_semantics") or []
            if isinstance(item, Mapping)
        ]
        if unresolved:
            ambiguity = unresolved[0]
            ambiguity_id = str(
                ambiguity.get("constraint_id")
                or ambiguity.get("ambiguity_id")
                or ""
            ).strip()
            if not ambiguity_id:
                return terminal_update(
                    error_code="FINALIZE_UNAUTHORIZED_ASK",
                    error_owner="controller",
                    detail="Validated user ambiguity has no stable ambiguity ID.",
                )
            pending_question = {
                "type": "semantic_constraint_clarification_v4",
                "stage": "consultant",
                "question": self._consultant_finalize_ambiguity_question(ambiguity),
                "ambiguity_id": ambiguity_id,
                "finalize_context_id": context_id,
                "base_contract_hash": base_contract_hash,
                "task_spec_revision": task_spec_revision(current_task_spec),
                "resume_step": "consultant",
            }
            try:
                current_consultation["pending_human_question"] = deepcopy(
                    pending_question
                )
                current_consultation = commit_finalize_v4_transition(
                    current_consultation,
                    {
                        "transition": "needs_user",
                        "pending_ambiguity_id": ambiguity_id,
                    },
                )
                current_consultation.update({
                    "phase": "needs_user",
                    "consultation_status": "needs_user",
                    "completion_decision": "needs_user",
                    "completion_reason": "validated_semantic_ambiguity",
                    "pending_human_question": deepcopy(pending_question),
                })
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_UNAUTHORIZED_ASK",
                    error_owner="controller",
                    detail=f"Ambiguity transition failed: {type(exc).__name__}: {exc}",
                )
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_semantic_resolution_request>"
                    + json.dumps({
                        "ambiguity_id": ambiguity_id,
                        "semantic_key": ambiguity.get("semantic_key"),
                    }, ensure_ascii=False, sort_keys=True)
                    + "</consultant_semantic_resolution_request>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": current_task_spec,
                "task_revision": task_spec_revision(current_task_spec),
                "selected_skills": list(selected),
                "selected_skills_raw": list(selected),
                "active_skills": list(selected),
                "required_skills_all": list(selected),
                "consultation_state": current_consultation,
                "consultant_contract_repair": {},
                "pending_human_question": pending_question,
                "consultant_constraint_metrics": {
                    "schema_validation": "passed",
                    "compile_mode": str(protocol().get("compile_mode") or ""),
                    "provider_status": "not_called",
                    "completion_integrity": "not_called",
                    "protocol_status": "needs_user",
                    "error_code": "FINALIZE_SEMANTIC_AMBIGUITY",
                    "error_owner": "user_semantic",
                },
                "contract_status": "blocked_need_user_decision",
                "next_step": "ask_user",
            }

        if expected_resolution_ids:
            return await self._run_consultant_finalize_v4_batches(
                state=state,
                task_id=task_id,
                current_task_spec=current_task_spec,
                current_consultation=current_consultation,
                context_value=context_value,
                domain_coverage=domain_coverage,
                durable_coverage=durable_coverage,
                durable_context=durable_context,
                selected=selected,
                input_audit=input_audit,
                consultant_wiki_context=consultant_wiki_context,
                consultant_memory_retrieval_context=(
                    consultant_memory_retrieval_context
                ),
                terminal_update=terminal_update,
            )

        try:
            deterministic = compile_deterministic_coverage(
                context_value,
                domain_coverage,
                required_skill_constraints=context_value.get(
                    "controller_required_constraints"
                ) or [],
            )
            domain_compiled = deepcopy(dict(deterministic["compiled_contract"]))
            semantic_metrics = {
                "schema_validation": "passed",
                "protocol_schema_version": 4,
                "wire_schema_version": 3,
                "compile_mode": "controller_deterministic",
                "provider_status": "not_called",
                "completion_integrity": "not_called",
                "protocol_status": "valid",
                "directive_count": int(domain_coverage.get("directive_count") or 0),
                "coverage_counts": deepcopy(dict(domain_coverage.get("counts") or {})),
                "coverage_artifact_ref": durable_coverage["coverage_artifact_ref"],
                "coverage_artifact_hash": durable_coverage["coverage_artifact_hash"],
                "domain_coverage_artifact_hash": domain_coverage["coverage_artifact_hash"],
            }
            compiled_task_spec = apply_task_spec_mutation_proposal(
                current_task_spec,
                constraint_mutation_proposal(
                    domain_compiled.get("constraints") or []
                ),
                project_root=project_root,
            )
            selected_constraints = semantic_constraints_from_task_spec(
                compiled_task_spec,
                selected_skill_ids=selected,
            )
            compiled_task_spec = merge_compiled_constraints(
                compiled_task_spec,
                selected_constraints,
                project_root=project_root,
                metrics=semantic_metrics,
            )
            final_constraints = semantic_constraints_from_task_spec(
                compiled_task_spec,
                selected_skill_ids=selected,
            )
            compiled_to_persist = deepcopy(domain_compiled)
            compiled_to_persist["domain_record_type"] = str(
                compiled_to_persist.pop("record_type", "")
            )
            compiled_to_persist["record_type"] = "finalize_compiled_contract"
            compiled_to_persist.update({
                "finalize_context_artifact_ref": durable_context[
                    "finalize_context_artifact_ref"
                ],
                "finalize_context_artifact_hash": durable_context[
                    "finalize_context_artifact_hash"
                ],
                "coverage_artifact_ref": durable_coverage["coverage_artifact_ref"],
                "coverage_artifact_hash": durable_coverage["coverage_artifact_hash"],
                "selected_skills": list(selected),
                "task_spec_revision": task_spec_revision(compiled_task_spec),
                "semantic_constraint_count": len(
                    domain_compiled.get("constraints") or []
                ),
                "summary": (
                    "Consultant FINALIZE v4 deterministically compiled the "
                    f"complete {int(domain_coverage.get('directive_count') or 0)}-directive "
                    "coverage proof; no finalizer provider call was required."
                ),
            })
            durable_compiled = store.persist_finalize_compiled_contract(
                compiled_to_persist
            )
            verified_compiled = store.lookup_finalize_compiled_contract(
                compiled_contract_id=str(durable_compiled["compiled_contract_id"]),
                compiled_contract_hash=str(durable_compiled["compiled_contract_hash"]),
                finalize_context_id=context_id,
            )
            if verified_compiled != durable_compiled:
                raise SnapshotConflictError(
                    "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                )
            current_consultation = commit_finalize_v4_transition(
                current_consultation,
                {
                    "transition": "compiled",
                    "compile_mode": "controller_deterministic",
                    "coverage_artifact_ref": durable_coverage["coverage_artifact_ref"],
                    "coverage_artifact_hash": durable_coverage["coverage_artifact_hash"],
                    "compiled_contract_ref": durable_compiled["compiled_contract_ref"],
                    "compiled_contract_hash": durable_compiled["compiled_contract_hash"],
                },
            )
            validate_finalize_protocol_v4(protocol())
        except Exception as exc:
            return terminal_update(
                error_code="FINALIZE_COMPILE_FAILED",
                error_owner=(
                    "controller_storage"
                    if isinstance(exc, (SnapshotConflictError, OSError))
                    else "controller"
                ),
                detail=f"Deterministic compile failed: {type(exc).__name__}: {exc}",
            )

        summary = str(durable_compiled.get("summary") or "")
        current_consultation.pop("final_contract", None)
        current_consultation.update({
            "phase": "finalize",
            "consultation_status": "completed",
            "completion_decision": "ready_to_finalize",
            "completion_reason": "formal_contract_compiled_v4_deterministic",
            "resolved_selected_skill_ids": list(selected),
            "compiled_contract_ref": str(durable_compiled.get("compiled_contract_ref") or ""),
            "compiled_contract_hash": str(durable_compiled.get("compiled_contract_hash") or ""),
        })
        output.print_once(
            f"consultant_finalize_v4:{task_id}",
            "✓ Consultant FINALIZE v4 compiled complete coverage without a provider call.",
            Fore.GREEN,
        )
        return {
            "messages": [AIMessage(content="FINISH\n" + summary)],
            "input_audit": deepcopy(dict(input_audit or {})),
            "selected_skills": list(selected),
            "selected_skills_raw": list(selected),
            "active_skills": list(selected),
            "future_skills": [],
            "required_skills_all": list(selected),
            "candidate_skills": [],
            "runtime_status": self._runtime_status_for_task(task_id, selected),
            "runtime_audit": [],
            "skill_selection_source": "consultation_controller_finalize_v4",
            "requirements_summary": summary,
            "task_spec": compiled_task_spec,
            "task_revision": task_spec_revision(compiled_task_spec),
            "consultant_constraint_metrics": {
                **semantic_metrics,
                "compiled_contract_ref": durable_compiled["compiled_contract_ref"],
                "compiled_contract_hash": durable_compiled["compiled_contract_hash"],
            },
            "consultation_state": current_consultation,
            "consultant_contract_repair": {},
            "pending_human_question": {},
            "contract_status": "semantic_contract_compiled",
            "memory_packet_context": self._consultant_handoff_memory_packet(
                summary,
                consultant_memory_retrieval_context,
            ),
            "wiki_memory_context": consultant_wiki_context,
            "next_step": "planner",
        }

    async def _run_consultant_finalize_v4_batches(
        self,
        **kwargs: Any,
    ) -> Dict[str, Any]:
        """Resolve only finite candidate IDs under capacity and work budgets."""
        task_id = str(kwargs["task_id"])
        current_task_spec = deepcopy(dict(kwargs["current_task_spec"]))
        current_consultation: Dict[str, Any] = kwargs["current_consultation"]
        context_value = deepcopy(dict(kwargs["context_value"]))
        domain_coverage = deepcopy(dict(kwargs["domain_coverage"]))
        durable_coverage = deepcopy(dict(kwargs["durable_coverage"]))
        durable_context = deepcopy(dict(kwargs["durable_context"]))
        selected = list(kwargs["selected"])
        input_audit = deepcopy(dict(kwargs["input_audit"] or {}))
        consultant_wiki_context = str(kwargs.get("consultant_wiki_context") or "")
        consultant_memory_retrieval_context = str(
            kwargs.get("consultant_memory_retrieval_context") or ""
        )
        terminal_update: Callable[..., Dict[str, Any]] = kwargs["terminal_update"]
        context_id = str(context_value.get("finalize_context_id") or "")
        base_contract_hash = str(context_value.get("base_contract_hash") or "")
        store = ContextLineageStore(self.data_path, task_id)

        def protocol() -> Dict[str, Any]:
            value = current_consultation.get("finalize_protocol")
            return dict(value) if isinstance(value, Mapping) else {}

        def commit(decision: Mapping[str, Any]) -> None:
            updated = commit_finalize_v4_transition(
                current_consultation,
                decision,
            )
            current_consultation.clear()
            current_consultation.update(updated)

        def persist_controller(
            kind: str,
            artifact: Mapping[str, Any],
            *,
            record_type: str,
            id_rename: Optional[Tuple[str, str]] = None,
            hash_rename: Optional[Tuple[str, str]] = None,
        ) -> Dict[str, Any]:
            payload = deepcopy(dict(artifact))
            domain_record_type = str(payload.pop("record_type", ""))
            payload["record_type"] = record_type
            payload["domain_record_type"] = domain_record_type
            if id_rename:
                old, new = id_rename
                payload[f"domain_{old}"] = str(payload.pop(old, ""))
                payload[new] = ""
            if hash_rename:
                old, new = hash_rename
                payload[f"domain_{old}"] = str(payload.pop(old, ""))
                payload[new] = ""
            return store.persist_finalize_controller_artifact(kind, payload)

        try:
            candidate_catalog = build_finalize_candidate_catalog(domain_coverage)
        except Exception as exc:
            return terminal_update(
                error_code="FINALIZE_CANDIDATE_CATALOG_INCOMPLETE",
                error_owner="controller",
                detail=(
                    "Model-owned coverage has no finite source-bound candidate set: "
                    f"{type(exc).__name__}: {exc}"
                ),
            )
        try:
            durable_catalog = persist_controller(
                "candidate_catalog",
                candidate_catalog,
                record_type="finalize_candidate_catalog",
            )
            probe_batch = build_finalize_decision_batch(candidate_catalog)
            probe_schema = build_finalize_batch_schema(probe_batch)
            probe_messages = build_finalize_batch_messages(
                probe_batch,
                probe_schema,
            )
            probe_settings = self._consultant_finalize_provider_settings(
                finalize_batch_llm_response_schema(probe_schema, probe_batch)
            )
            direct_client = getattr(self.llm, "async_client", None)
            exact_wire_cap_verified = bool(
                str(probe_settings.get("provider_id") or "") == "deepseek"
                and direct_client is not None
                and callable(getattr(direct_client, "create", None))
                and str(probe_settings.get("output_token_parameter") or "")
                == "max_tokens"
            )
            provider_capability = {
                "record_type": "finalize_provider_capability",
                "provider_id": str(probe_settings.get("provider_id") or ""),
                "endpoint_id": str(probe_settings.get("endpoint_id") or ""),
                "model": str(probe_settings.get("model") or ""),
                "api_surface": "chat_completions",
                "output_token_parameter": str(
                    probe_settings.get("output_token_parameter") or ""
                ),
                "effective_token_cap_verified": exact_wire_cap_verified,
                "supports_bounded_output_grammar": False,
                "maximum_raw_wire_tokens": None,
                "stream": False,
            }
            if not exact_wire_cap_verified:
                raise ValueError("FINALIZE_PROVIDER_PARAMETER_UNSUPPORTED")
            # The full-catalog wire is an upper bound for every stable child;
            # the profile then adds the batch projection again, deliberately
            # preferring safe over-admission to optimistic token estimates.
            base_input_tokens = sum(
                len(str(getattr(item, "content", "") or "").encode("utf-8")) + 4
                for item in probe_messages
            )
            budget_policy_projection = {
                "budget_policy_id": str(
                    CONSULTANT_FINALIZE_BUDGET_POLICY_VERSION
                ),
                "max_resolution_items": int(
                    CONSULTANT_FINALIZE_MAX_RESOLUTION_ITEMS
                ),
                "max_created_batches": int(
                    CONSULTANT_FINALIZE_MAX_CREATED_BATCHES
                ),
                "max_provider_calls": int(
                    CONSULTANT_FINALIZE_MAX_PROVIDER_CALLS
                ),
                "max_repartition_depth": int(
                    CONSULTANT_FINALIZE_MAX_REPARTITION_DEPTH
                ),
                "max_total_completion_tokens": int(
                    CONSULTANT_FINALIZE_MAX_TOTAL_COMPLETION_TOKENS
                ),
                "max_total_estimated_cost_microusd": int(
                    CONSULTANT_FINALIZE_MAX_TOTAL_ESTIMATED_COST_MICROUSD
                ),
                "max_wall_time_ms": int(
                    CONSULTANT_FINALIZE_MAX_WALL_TIME_MS
                ),
                "per_call_timeout_ms": int(
                    CONSULTANT_FINALIZE_PER_CALL_TIMEOUT_MS
                ),
                "estimated_cost_microusd_per_token": int(
                    CONSULTANT_FINALIZE_ESTIMATED_MICROUSD_PER_TOKEN
                ),
            }
            partition_basis = build_partition_capacity_basis(
                candidate_catalog,
                provider_capability=provider_capability,
                requested_output_tokens=int(
                    probe_settings["requested_output_tokens"]
                ),
                provider_output_cap=int(probe_settings["provider_output_cap"]),
                provider_context_limit=int(
                    probe_settings["provider_context_limit"]
                ),
                safety_headroom_tokens=int(
                    probe_settings["output_safety_headroom_tokens"]
                ),
                max_batch_items=int(CONSULTANT_FINALIZE_MAX_BATCH_ITEMS),
                base_input_tokens=base_input_tokens,
                budget_policy=budget_policy_projection,
            )
            durable_basis = persist_controller(
                "partition_basis",
                partition_basis,
                record_type="finalize_partition_capacity_basis",
            )
            now = datetime.now(timezone.utc)
            work_budget = store.persist_finalize_work_budget({
                "record_type": "finalize_work_budget",
                "finalize_context_id": context_id,
                "replay_scope_id": str(protocol().get("replay_scope_id") or ""),
                **budget_policy_projection,
                "run_started_at": now.isoformat(),
                "absolute_deadline_at": (
                    now
                    + timedelta(
                        milliseconds=int(CONSULTANT_FINALIZE_MAX_WALL_TIME_MS)
                    )
                ).isoformat(),
            })
            if str(work_budget.get("budget_policy_hash") or "") != str(
                partition_basis.get("budget_policy_hash") or ""
            ):
                raise SnapshotConflictError(
                    "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                )
            stable_partition = stable_partition_finalize_batches(
                candidate_catalog,
                partition_basis,
            )
            durable_partition = persist_controller(
                "stable_partition",
                stable_partition,
                record_type="finalize_stable_partition",
                id_rename=("partition_id", "stable_partition_id"),
                hash_rename=("partition_hash", "stable_partition_hash"),
            )
            work_preflight = build_finalize_work_preflight(
                stable_partition,
                candidate_catalog,
                partition_basis,
                max_resolution_items=int(
                    CONSULTANT_FINALIZE_MAX_RESOLUTION_ITEMS
                ),
                max_created_batches=int(
                    CONSULTANT_FINALIZE_MAX_CREATED_BATCHES
                ),
                max_provider_calls=int(
                    CONSULTANT_FINALIZE_MAX_PROVIDER_CALLS
                ),
                max_repartition_depth=int(
                    CONSULTANT_FINALIZE_MAX_REPARTITION_DEPTH
                ),
                max_total_completion_tokens=int(
                    CONSULTANT_FINALIZE_MAX_TOTAL_COMPLETION_TOKENS
                ),
                max_total_estimated_cost_microusd=int(
                    CONSULTANT_FINALIZE_MAX_TOTAL_ESTIMATED_COST_MICROUSD
                ),
                estimated_cost_microusd_per_token=int(
                    CONSULTANT_FINALIZE_ESTIMATED_MICROUSD_PER_TOKEN
                ),
                work_budget_ref=str(work_budget["work_budget_ref"]),
                work_budget_hash=str(work_budget["work_budget_hash"]),
                budget_policy_hash=str(work_budget["budget_policy_hash"]),
            )
            preflight_to_persist = {
                **work_preflight,
                "candidate_catalog_ref": durable_catalog[
                    "candidate_catalog_ref"
                ],
                "partition_capacity_basis_ref": durable_basis[
                    "partition_capacity_basis_ref"
                ],
                "stable_partition_ref": durable_partition[
                    "stable_partition_ref"
                ],
                "durable_stable_partition_hash": durable_partition[
                    "stable_partition_hash"
                ],
            }
            durable_preflight = persist_controller(
                "work_preflight",
                preflight_to_persist,
                record_type="finalize_work_preflight",
                id_rename=("preflight_id", "work_preflight_id"),
                hash_rename=("preflight_hash", "work_preflight_hash"),
            )
            verified_preflight = store.lookup_finalize_controller_artifact(
                "work_preflight",
                artifact_hash=str(
                    durable_preflight["work_preflight_hash"]
                ),
                finalize_context_id=context_id,
            )
            if verified_preflight != durable_preflight:
                raise SnapshotConflictError(
                    "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                )
            if not str(protocol().get("coverage_artifact_hash") or ""):
                commit({
                    "transition": "coverage_ready",
                    "coverage_artifact_ref": durable_coverage["coverage_artifact_ref"],
                    "coverage_artifact_hash": durable_coverage["coverage_artifact_hash"],
                    "candidate_catalog_ref": durable_catalog["candidate_catalog_ref"],
                    "candidate_catalog_hash": durable_catalog["candidate_catalog_hash"],
                    "partition_capacity_basis_ref": durable_basis[
                        "partition_capacity_basis_ref"
                    ],
                    "partition_capacity_basis_hash": durable_basis[
                        "partition_capacity_basis_hash"
                    ],
                    "work_budget_ref": work_budget["work_budget_ref"],
                    "work_budget_hash": work_budget["work_budget_hash"],
                    "work_preflight_ref": durable_preflight[
                        "work_preflight_ref"
                    ],
                    "work_preflight_hash": durable_preflight[
                        "work_preflight_hash"
                    ],
                    "expected_resolution_ids": list(
                        stable_partition.get("ordered_resolution_ids") or []
                    ),
                })
            else:
                existing = protocol()
                expected_bindings = {
                    "coverage_artifact_ref": durable_coverage[
                        "coverage_artifact_ref"
                    ],
                    "coverage_artifact_hash": durable_coverage[
                        "coverage_artifact_hash"
                    ],
                    "candidate_catalog_ref": durable_catalog[
                        "candidate_catalog_ref"
                    ],
                    "candidate_catalog_hash": durable_catalog[
                        "candidate_catalog_hash"
                    ],
                    "partition_capacity_basis_ref": durable_basis[
                        "partition_capacity_basis_ref"
                    ],
                    "partition_capacity_basis_hash": durable_basis[
                        "partition_capacity_basis_hash"
                    ],
                    "work_budget_ref": work_budget["work_budget_ref"],
                    "work_budget_hash": work_budget["work_budget_hash"],
                    "work_preflight_ref": durable_preflight[
                        "work_preflight_ref"
                    ],
                    "work_preflight_hash": durable_preflight[
                        "work_preflight_hash"
                    ],
                }
                if (
                    any(
                        str(existing.get(field) or "") != str(value or "")
                        for field, value in expected_bindings.items()
                    )
                    or sorted(
                        str(item)
                        for item in (
                            existing.get("aggregate") or {}
                        ).get("expected_resolution_ids") or []
                    )
                    != sorted(
                        str(item)
                        for item in stable_partition.get(
                            "ordered_resolution_ids"
                        ) or []
                    )
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
            if not bool(durable_preflight.get("admitted")):
                raise ValueError(
                    "FINALIZE_GLOBAL_BUDGET_EXHAUSTED:"
                    + ",".join(
                        durable_preflight.get("exceeded_fields") or []
                    )
                )
        except Exception as exc:
            return terminal_update(
                error_code=(
                    "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    if isinstance(exc, (SnapshotConflictError, OSError))
                    else "FINALIZE_PROVIDER_PARAMETER_UNSUPPORTED"
                    if "FINALIZE_PROVIDER_PARAMETER_UNSUPPORTED" in str(exc)
                    else "FINALIZE_GLOBAL_BUDGET_EXHAUSTED"
                    if "FINALIZE_GLOBAL_BUDGET_EXHAUSTED" in str(exc)
                    else "FINALIZE_OUTPUT_CAPACITY_UNSATISFIED"
                ),
                error_owner=(
                    "controller_storage"
                    if isinstance(exc, (SnapshotConflictError, OSError))
                    else "controller"
                ),
                detail=f"Batch capacity admission failed: {type(exc).__name__}: {exc}",
            )

        queue: List[Dict[str, Any]] = []
        validated_decisions: List[Dict[str, Any]] = []
        cost_rate_microusd_per_token = int(
            work_budget.get("estimated_cost_microusd_per_token") or 0
        )
        if (
            cost_rate_microusd_per_token <= 0
            or cost_rate_microusd_per_token
            != int(
                durable_preflight.get(
                    "estimated_cost_microusd_per_token"
                ) or 0
            )
        ):
            return terminal_update(
                error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                error_owner="controller_storage",
                detail="Durable work budget and preflight cost policies disagree.",
            )
        created_batch_ids = {
            str(item.get("batch_id") or "")
            for item in protocol().get("batches") or []
            if isinstance(item, Mapping)
        }

        def prepare_batch_row(
            batch: Mapping[str, Any],
            schema: Mapping[str, Any],
            profile: Mapping[str, Any],
        ) -> Dict[str, Any]:
            durable_batch = persist_controller(
                "decision_batch",
                batch,
                record_type="finalize_decision_batch",
            )
            durable_schema = persist_controller(
                "response_schema",
                schema,
                record_type="finalize_response_schema",
            )
            durable_profile = store.persist_finalize_capacity_profile(profile)
            batch_id = str(batch.get("decision_batch_id") or "")
            if batch_id not in created_batch_ids:
                commit({
                    "transition": "batch_created",
                    "batch": {
                        "batch_id": batch_id,
                        "batch_hash": str(batch.get("decision_batch_hash") or ""),
                        "item_ids": list(batch.get("item_ids") or []),
                        "parent_batch_id": str(batch.get("parent_batch_id") or ""),
                        "repartition_depth": int(batch.get("repartition_depth") or 0),
                        "derivation_kind": str(batch.get("derivation_kind") or ""),
                        "decision_batch_ref": durable_batch["decision_batch_ref"],
                        "response_schema_ref": durable_schema["response_schema_ref"],
                        "response_schema_hash": durable_schema["response_schema_hash"],
                        "capacity_profile_ref": durable_profile[
                            "capacity_profile_ref"
                        ],
                        "capacity_profile_hash": durable_profile["profile_hash"],
                    },
                })
                created_batch_ids.add(batch_id)
            return {
                "batch": deepcopy(dict(batch)),
                "response_schema_artifact": deepcopy(dict(schema)),
                "capacity_profile": deepcopy(dict(profile)),
                "durable_batch": durable_batch,
                "durable_schema": durable_schema,
                "durable_profile": durable_profile,
            }

        try:
            for row in stable_partition.get("batches") or []:
                queue.append(prepare_batch_row(
                    row["batch"],
                    row["response_schema_artifact"],
                    row["capacity_profile"],
                ))
        except Exception as exc:
            return terminal_update(
                error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                error_owner="controller_storage",
                detail=f"Batch artifact commit failed: {type(exc).__name__}: {exc}",
            )

        def project_reservation(record: Mapping[str, Any]) -> Dict[str, Any]:
            ledger = store.aggregate_finalize_budget_reservations(
                work_budget_ref=str(work_budget["work_budget_ref"]),
                work_budget_hash=str(work_budget["work_budget_hash"]),
                finalize_context_id=context_id,
            )
            commit({
                "transition": "reservation_projected",
                "reservation_ledger_ref": ledger["reservation_ledger_ref"],
                "reservation_ledger_hash": ledger["reservation_ledger_hash"],
                "reservation_id": str(record.get("reservation_id") or ""),
                "reservation_hash": str(record.get("reservation_hash") or ""),
                "reservation_ref": str(record.get("reservation_ref") or ""),
                "attempt_lineage_hash": str(
                    record.get("attempt_lineage_hash") or ""
                ),
                "wire_request_hash": str(
                    record.get("wire_request_hash") or ""
                ),
                "status": str(record.get("status") or ""),
                "record_revision": int(record.get("record_revision") or 0),
            })
            return ledger

        def graph_attempt(attempt_id: str) -> Optional[Dict[str, Any]]:
            return next(
                (
                    dict(item)
                    for item in protocol().get("attempts") or []
                    if isinstance(item, Mapping)
                    and str(item.get("attempt_id") or "") == str(attempt_id)
                ),
                None,
            )

        def graph_batch(batch_id: str) -> Optional[Dict[str, Any]]:
            return next(
                (
                    dict(item)
                    for item in protocol().get("batches") or []
                    if isinstance(item, Mapping)
                    and str(item.get("batch_id") or "") == str(batch_id)
                ),
                None,
            )

        def usage_value(usage: Mapping[str, Any], field: str) -> Optional[int]:
            if field not in usage or usage.get(field) is None:
                return None
            return max(0, int(usage[field]))

        def actual_estimated_cost(usage: Mapping[str, Any]) -> Optional[int]:
            total = usage_value(usage, "total_tokens")
            if total is None:
                prompt = usage_value(usage, "prompt_tokens")
                completion = usage_value(usage, "completion_tokens")
                if prompt is None or completion is None:
                    return None
                total = prompt + completion
            return int(total) * cost_rate_microusd_per_token

        def matching_reservation(
            wire_request_hash: str,
            *,
            attempt_id: str = "",
        ) -> Optional[Dict[str, Any]]:
            rows = store.list_finalize_budget_reservations(
                replay_scope_id=str(protocol().get("replay_scope_id") or ""),
                wire_request_hash=wire_request_hash,
            )
            active_or_consumed = [
                row for row in rows
                if str(row.get("status") or "") != "released"
                and (
                    not attempt_id
                    or str(row.get("attempt_id") or "") == str(attempt_id)
                )
            ]
            if len(active_or_consumed) > 1:
                raise SnapshotConflictError(
                    "FINALIZE_RESERVATION_LEDGER_INVALID"
                )
            return deepcopy(active_or_consumed[0]) if active_or_consumed else None

        def ensure_graph_request_started(
            *,
            attempt_id: str,
            call_id: str,
            call_kind: str,
            batch: Mapping[str, Any],
            claim: Mapping[str, Any],
            request_intent_hash: str,
            protocol_request_hash: str,
            wire_request_hash: str,
            row: Mapping[str, Any],
            wire_artifact: Mapping[str, Any],
            reservation: Mapping[str, Any],
        ) -> None:
            existing = graph_attempt(attempt_id)
            if existing is not None:
                if (
                    str(existing.get("call_id") or "") != str(call_id)
                    or str(existing.get("wire_request_hash") or "")
                    != str(wire_request_hash)
                    or str(existing.get("protocol_request_hash") or "")
                    != str(protocol_request_hash)
                    or str(existing.get("decision_batch_id") or "")
                    != str(batch.get("decision_batch_id") or "")
                    or str(existing.get("decision_batch_hash") or "")
                    != str(batch.get("decision_batch_hash") or "")
                    or str(existing.get("capacity_profile_ref") or "")
                    != str(row["durable_profile"]["capacity_profile_ref"])
                    or str(existing.get("capacity_profile_hash") or "")
                    != str(row["durable_profile"]["profile_hash"])
                    or str(existing.get("response_schema_ref") or "")
                    != str(row["durable_schema"]["response_schema_ref"])
                    or str(existing.get("response_schema_hash") or "")
                    != str(row["durable_schema"]["response_schema_hash"])
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
                return
            commit({
                "transition": "request_started",
                "attempt": {
                    "attempt_id": attempt_id,
                    "call_id": call_id,
                    "call_kind": call_kind,
                    "parent_attempt_id": str(
                        reservation.get("parent_attempt_id") or ""
                    ),
                    "decision_batch_id": batch["decision_batch_id"],
                    "decision_batch_hash": batch["decision_batch_hash"],
                    "request_intent_ref": str(
                        claim.get("intent_ref")
                        or (claim.get("intent") or {}).get("intent_ref")
                        or ""
                    ),
                    "request_intent_hash": request_intent_hash,
                    "protocol_request_hash": protocol_request_hash,
                    "wire_request_hash": wire_request_hash,
                    "capacity_profile_ref": row["durable_profile"][
                        "capacity_profile_ref"
                    ],
                    "capacity_profile_hash": row["durable_profile"][
                        "profile_hash"
                    ],
                    "response_schema_ref": row["durable_schema"][
                        "response_schema_ref"
                    ],
                    "response_schema_hash": row["durable_schema"][
                        "response_schema_hash"
                    ],
                    "effective_wire_settings_ref": wire_artifact[
                        "effective_wire_settings_ref"
                    ],
                    "effective_wire_settings_hash": wire_artifact[
                        "effective_wire_settings_hash"
                    ],
                    "reservation_id": reservation["reservation_id"],
                    "reservation_hash": reservation["reservation_hash"],
                    "reservation_ref": reservation["reservation_ref"],
                    "attempt_lineage_hash": reservation[
                        "attempt_lineage_hash"
                    ],
                    "lease_epoch": reservation["lease_epoch"],
                },
            })

        def reconcile_result_reservation(
            reservation: Mapping[str, Any],
            *,
            provider_status: str,
            completion_integrity: str,
            usage: Mapping[str, Any],
            artifact_ref: str,
            artifact_hash: str,
            actual_wall_time_ms: Optional[int],
        ) -> Dict[str, Any]:
            current = deepcopy(dict(reservation))
            status = str(current.get("status") or "")
            if status == "consumed":
                if (
                    str(current.get("provider_status") or "") != provider_status
                    or str(current.get("completion_integrity") or "")
                    != completion_integrity
                    or str(current.get("reconciled_artifact_ref") or "")
                    != str(artifact_ref)
                    or str(current.get("reconciled_artifact_hash") or "")
                    != str(artifact_hash)
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_RESERVATION_RECONCILIATION_FAILED"
                    )
                project_reservation(current)
                return current
            consume = (
                store.reconcile_finalize_budget_reservation
                if status == "reconcile_required"
                else store.consume_finalize_budget_reservation
            )
            if status not in {"dispatched", "reconcile_required"}:
                raise SnapshotConflictError(
                    "FINALIZE_RESERVATION_RECONCILIATION_FAILED"
                )
            current = consume(
                str(current["reservation_id"]),
                provider_status=provider_status,
                completion_integrity=completion_integrity,
                retry_safe=False,
                actual_completion_tokens=usage_value(
                    usage, "completion_tokens"
                ),
                actual_cost_microusd=actual_estimated_cost(usage),
                actual_wall_time_ms=actual_wall_time_ms,
                reconciled_artifact_ref=artifact_ref,
                reconciled_artifact_hash=artifact_hash,
                expected_reservation_hash=str(current["reservation_hash"]),
                expected_protected_record_hash=str(
                    current["protected_record_hash"]
                ),
                lease_owner=str(current["lease_owner"]),
                lease_epoch=int(current["lease_epoch"]),
            )
            project_reservation(current)
            return current

        def provider_in_progress_update(
            *, attempt_id: str, call_id: str, wire_request_hash: str
        ) -> Dict[str, Any]:
            current_consultation.update({
                "phase": "finalize",
                "consultation_status": "ready",
                "completion_decision": "ready_to_finalize",
                "completion_reason": "provider_attempt_in_progress",
            })
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_finalize_provider_in_progress>"
                    + json.dumps({
                        "attempt_id": attempt_id,
                        "call_id": call_id,
                        "wire_request_hash": wire_request_hash,
                        "provider_status": "in_flight",
                    }, ensure_ascii=False, sort_keys=True)
                    + "</consultant_finalize_provider_in_progress>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": current_task_spec,
                "task_revision": task_spec_revision(current_task_spec),
                "selected_skills": list(selected),
                "selected_skills_raw": list(selected),
                "active_skills": list(selected),
                "required_skills_all": list(selected),
                "consultation_state": current_consultation,
                "consultant_contract_repair": {},
                "pending_human_question": {},
                "consultant_constraint_metrics": {
                    "schema_validation": "not_run",
                    "protocol_schema_version": 4,
                    "wire_schema_version": 3,
                    "provider_status": "in_flight",
                    "protocol_status": "not_validated",
                },
                "contract_status": "finalize_provider_in_progress",
                "next_step": "consultant",
            }

        def provider_retry_pending_update(
            *,
            attempt_id: str,
            call_id: str,
            wire_request_hash: str,
            error_code: str,
            error_owner: str,
        ) -> Dict[str, Any]:
            current_consultation.update({
                "phase": "finalize",
                "consultation_status": "ready",
                "completion_decision": "ready_to_finalize",
                "completion_reason": "safe_transport_retry_pending",
            })
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_finalize_provider_retry>"
                    + json.dumps({
                        "attempt_id": attempt_id,
                        "call_id": call_id,
                        "wire_request_hash": wire_request_hash,
                        "provider_status": "transient_failed",
                        "retry_safe": True,
                        "error_code": error_code,
                        "error_owner": error_owner,
                    }, ensure_ascii=False, sort_keys=True)
                    + "</consultant_finalize_provider_retry>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": current_task_spec,
                "task_revision": task_spec_revision(current_task_spec),
                "selected_skills": list(selected),
                "selected_skills_raw": list(selected),
                "active_skills": list(selected),
                "required_skills_all": list(selected),
                "consultation_state": current_consultation,
                "consultant_contract_repair": {},
                "pending_human_question": {},
                "consultant_constraint_metrics": {
                    "schema_validation": "not_run",
                    "protocol_schema_version": 4,
                    "wire_schema_version": 3,
                    "provider_status": "transient_failed",
                    "completion_integrity": "missing",
                    "protocol_status": "not_validated",
                    "error_code": error_code,
                    "error_owner": error_owner,
                    "retry_safe": True,
                },
                "contract_status": "semantic_schema_retry",
                "next_step": "consultant",
            }

        async def obtain_provider_result(
            *,
            row: Mapping[str, Any],
            batch: Mapping[str, Any],
            messages: Sequence[BaseMessage],
            settings: Mapping[str, Any],
            provider_parameters: Mapping[str, Any],
            canonical_request_hash: str,
        ) -> Dict[str, Any]:
            """Resume protected provider evidence or dispatch exactly once."""
            protocol_request_hash = self._finalize_digest({
                "wire_request_hash": canonical_request_hash,
                "provider_parameters": provider_parameters,
            })
            existing = store.lookup_finalize_attempt(canonical_request_hash)
            reservation = matching_reservation(
                canonical_request_hash,
                attempt_id=str((existing or {}).get("attempt_id") or ""),
            )
            derivation_kind = str(
                batch.get("derivation_kind") or "initial"
            )
            if derivation_kind == "length_repartition":
                call_kind = "length_repair"
            elif derivation_kind in {"wire_repair", "field_repair"}:
                call_kind = derivation_kind
            else:
                call_kind = "decision_batch"
            request_metadata = {
                "finalize_context_id": context_id,
                "base_contract_hash": base_contract_hash,
                "wire_schema_version": 3,
                "decision_batch_id": batch["decision_batch_id"],
                "decision_batch_hash": batch["decision_batch_hash"],
                "capacity_profile_ref": row["durable_profile"][
                    "capacity_profile_ref"
                ],
                "capacity_profile_hash": row["durable_profile"][
                    "profile_hash"
                ],
                "response_schema_ref": row["durable_schema"][
                    "response_schema_ref"
                ],
                "response_schema_hash": row["durable_schema"][
                    "response_schema_hash"
                ],
            }
            if reservation is not None and (
                str(reservation.get("finalize_context_id") or "")
                != context_id
                or str(reservation.get("protocol_request_hash") or "")
                != protocol_request_hash
                or str(reservation.get("wire_request_hash") or "")
                != canonical_request_hash
                or str(reservation.get("work_budget_ref") or "")
                != str(work_budget["work_budget_ref"])
                or str(reservation.get("work_budget_hash") or "")
                != str(work_budget["work_budget_hash"])
                or str(reservation.get("batch_id") or "")
                != str(batch["decision_batch_id"])
                or int(reservation.get("reserved_completion_tokens") or 0)
                != int(settings["max_output_tokens"])
                or int(reservation.get("timeout_ms") or 0)
                != int(settings["per_call_timeout_ms"])
            ):
                return {"terminal": terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=(
                        "Durable reservation conflicts with the current "
                        "budget/preflight/request identity closure."
                    ),
                )}
            retry_authorization: Dict[str, Any] = {}
            parent_attempt_id = ""
            retry_dispatch = False
            if existing is not None:
                attempt_id = str(existing.get("attempt_id") or "")
                call_id = str(existing.get("call_id") or "")
                intent = dict(existing.get("intent") or {})
                intent_metadata = dict(
                    intent.get("request_metadata") or {}
                )
                if (
                    not attempt_id
                    or not call_id
                    or str(intent.get("call_kind") or call_kind) != call_kind
                    or any(
                        intent_metadata.get(field) != value
                        for field, value in request_metadata.items()
                    )
                ):
                    return {"terminal": terminal_update(
                        error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        error_owner="controller_storage",
                        detail="Durable batch attempt identity conflicts with the stable partition.",
                    )}
                # ``held`` (or intent-only) proves provider dispatch did not
                # begin.  Every later ledger status must reconcile artifacts
                # before any network operation.
                safe_to_resume_dispatch = reservation is None or str(
                    reservation.get("status") or ""
                ) == "held"
                if not safe_to_resume_dispatch:
                    if graph_attempt(attempt_id) is None:
                        wire_ref = str(
                            existing.get("effective_wire_settings_ref") or ""
                        )
                        wire_hash = str(
                            existing.get("effective_wire_settings_hash") or ""
                        )
                        if reservation is None or not wire_ref or not wire_hash:
                            return {"terminal": terminal_update(
                                error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                                error_owner="controller_storage",
                                detail="Dispatched attempt is missing its wire/reservation projection.",
                            )}
                        ensure_graph_request_started(
                            attempt_id=attempt_id,
                            call_id=call_id,
                            call_kind=call_kind,
                            batch=batch,
                            claim=existing,
                            request_intent_hash=str(
                                reservation.get("request_intent_hash") or ""
                            ),
                            protocol_request_hash=protocol_request_hash,
                            wire_request_hash=canonical_request_hash,
                            row=row,
                            wire_artifact={
                                "effective_wire_settings_ref": wire_ref,
                                "effective_wire_settings_hash": wire_hash,
                            },
                            reservation=reservation,
                        )
                    reconciliation = reconcile_finalize_attempt(
                        store,
                        attempt_id=attempt_id,
                        call_id=call_id,
                        canonical_request_hash=canonical_request_hash,
                    )
                    decision = str(reconciliation.get("decision") or "")
                    if decision == "reuse_response":
                        return {
                            "attempt_id": attempt_id,
                            "call_id": call_id,
                            "reservation": reservation,
                            "provider_result": {
                                "raw_response": str(
                                    reconciliation.get("raw_response") or ""
                                ),
                                "artifact": deepcopy(dict(reconciliation)),
                                "finish_reason": str(
                                    reconciliation.get("finish_reason") or "stop"
                                ),
                                "usage": deepcopy(dict(
                                    reconciliation.get("usage") or {}
                                )),
                                "completion_integrity": "complete",
                                "provider_status": "succeeded",
                                "protocol_status": str(
                                    reconciliation.get("protocol_status")
                                    or "not_validated"
                                ),
                                "response_reused_from_checkpoint": True,
                            },
                            "provider_wall_time_ms": None,
                            "reused": True,
                        }
                    if decision == "reuse_partial_response":
                        return {
                            "attempt_id": attempt_id,
                            "call_id": call_id,
                            "reservation": reservation,
                            "provider_result": {
                                "raw_response": "",
                                "artifact": {},
                                "partial_artifact": deepcopy(dict(reconciliation)),
                                "finish_reason": str(
                                    reconciliation.get("finish_reason") or "unknown"
                                ),
                                "usage": deepcopy(dict(
                                    reconciliation.get("usage") or {}
                                )),
                                "completion_integrity": str(
                                    reconciliation.get("completion_integrity")
                                    or "unknown"
                                ),
                                "provider_status": "succeeded",
                                "protocol_status": "not_validated",
                                "response_reused_from_checkpoint": True,
                            },
                            "provider_wall_time_ms": None,
                            "reused": True,
                        }
                    if decision == "attempt_in_progress":
                        return {"terminal": provider_in_progress_update(
                            attempt_id=attempt_id,
                            call_id=call_id,
                            wire_request_hash=canonical_request_hash,
                        )}
                    if decision == "safe_transport_retry":
                        try:
                            if (
                                reservation is None
                                or str(reservation.get("status") or "")
                                != "consumed"
                                or str(reservation.get("provider_status") or "")
                                != "transient_failed"
                                or str(
                                    reservation.get("completion_integrity") or ""
                                ) != "missing"
                                or reservation.get("retry_safe") is not True
                            ):
                                raise SnapshotConflictError(
                                    "FINALIZE_RESERVATION_RECONCILIATION_FAILED"
                                )
                            parent_attempt_id = attempt_id
                            retry_authorization = (
                                store.persist_finalize_retry_authorization({
                                    "retry_authorization_id": (
                                        "retry-auth-"
                                        + self._finalize_digest({
                                            "reservation_id": reservation[
                                                "reservation_id"
                                            ],
                                            "reservation_hash": reservation[
                                                "reservation_hash"
                                            ],
                                        })[:24]
                                    ),
                                    "finalize_context_id": context_id,
                                    "replay_scope_id": str(
                                        protocol().get("replay_scope_id") or ""
                                    ),
                                    "wire_request_hash": canonical_request_hash,
                                    "prior_reservation_id": reservation[
                                        "reservation_id"
                                    ],
                                    "prior_reservation_hash": reservation[
                                        "reservation_hash"
                                    ],
                                    "provider_status": "transient_failed",
                                    "completion_integrity": "missing",
                                    "retry_safe": True,
                                    "no_completion_proven": True,
                                    "authorized_retry_count": 1,
                                })
                            )
                            suffix = uuid.uuid4().hex
                            attempt_id = f"finalize-v4-{suffix}"
                            call_id = (
                                f"consultant-finalize-v4-transport-retry-{suffix}"
                            )
                            call_kind = "transport_retry"
                            claim = persist_finalize_attempt_intent(
                                store,
                                attempt_id=attempt_id,
                                call_id=call_id,
                                call_kind=call_kind,
                                canonical_request_hash=canonical_request_hash,
                                request_metadata=request_metadata,
                            )
                            request_intent_hash = self._finalize_digest({
                                key: value for key, value in claim.items()
                                if key not in {
                                    "claim_acquired", "claim_reused"
                                }
                            })
                            reservation = None
                            retry_dispatch = True
                        except Exception as exc:
                            return {"terminal": terminal_update(
                                error_code="FINALIZE_RESERVATION_RECONCILIATION_FAILED",
                                error_owner="controller_storage",
                                detail=(
                                    "Safe transport-retry authorization failed: "
                                    f"{type(exc).__name__}: {exc}"
                                ),
                            )}
                    else:
                        try:
                            if reservation is not None and str(
                                reservation.get("status") or ""
                            ) == "dispatched":
                                reservation = store.mark_finalize_reservation_reconcile_required(
                                    str(reservation["reservation_id"]),
                                    reason="provider outcome cannot be proven after checkpoint resume",
                                    expected_reservation_hash=str(
                                        reservation["reservation_hash"]
                                    ),
                                    expected_protected_record_hash=str(
                                        reservation["protected_record_hash"]
                                    ),
                                    lease_owner=str(reservation["lease_owner"]),
                                    lease_epoch=int(reservation["lease_epoch"]),
                                )
                                project_reservation(reservation)
                            if reservation is not None and str(
                                reservation.get("status") or ""
                            ) == "reconcile_required":
                                reservation = store.reconcile_finalize_budget_reservation(
                                    str(reservation["reservation_id"]),
                                    provider_status="outcome_unknown",
                                    completion_integrity="unknown",
                                    expected_reservation_hash=str(
                                        reservation["reservation_hash"]
                                    ),
                                    expected_protected_record_hash=str(
                                        reservation["protected_record_hash"]
                                    ),
                                    lease_owner=str(reservation["lease_owner"]),
                                    lease_epoch=int(reservation["lease_epoch"]),
                                )
                                project_reservation(reservation)
                            projection = graph_attempt(attempt_id)
                            if projection is not None and str(
                                projection.get("provider_status") or ""
                            ) == "in_flight":
                                commit({
                                    "transition": "provider_failed",
                                    "attempt_id": attempt_id,
                                    "provider_status": "outcome_unknown",
                                    "error_code": str(
                                        reconciliation.get("error_code")
                                        or "FINALIZE_PROVIDER_OUTCOME_UNKNOWN"
                                    ),
                                    "error_owner": str(
                                        reconciliation.get("error_owner")
                                        or "controller_provider"
                                    ),
                                    "retry_safe": False,
                                })
                        except Exception as exc:
                            return {"terminal": terminal_update(
                                error_code="FINALIZE_RESERVATION_RECONCILIATION_FAILED",
                                error_owner="controller_storage",
                                detail=f"Stale dispatched attempt reconciliation failed: {type(exc).__name__}: {exc}",
                            )}
                        return {"terminal": terminal_update(
                            error_code=str(
                                reconciliation.get("error_code")
                                or "FINALIZE_PROVIDER_OUTCOME_UNKNOWN"
                            ),
                            error_owner=str(
                                reconciliation.get("error_owner")
                                or "controller_provider"
                            ),
                            detail="A dispatched provider attempt has no safely reusable completion.",
                        )}
                if not retry_dispatch:
                    claim = deepcopy(dict(existing))
                    status_record = dict(existing.get("status_record") or {})
                    request_intent_hash = (
                        str((reservation or {}).get("request_intent_hash") or "")
                        or self._finalize_digest(status_record)
                    )
                    try:
                        store.acquire_finalize_provider_lease(attempt_id)
                    except (BlockingIOError, SnapshotConflictError):
                        return {"terminal": provider_in_progress_update(
                            attempt_id=attempt_id,
                            call_id=call_id,
                            wire_request_hash=canonical_request_hash,
                        )}
            else:
                suffix = uuid.uuid4().hex
                attempt_id = f"finalize-v4-{suffix}"
                call_id = f"consultant-finalize-v4-{suffix}"
                try:
                    claim = persist_finalize_attempt_intent(
                        store,
                        attempt_id=attempt_id,
                        call_id=call_id,
                        call_kind=call_kind,
                        canonical_request_hash=canonical_request_hash,
                        request_metadata=request_metadata,
                    )
                    request_intent_hash = self._finalize_digest({
                        key: value for key, value in claim.items()
                        if key not in {"claim_acquired", "claim_reused"}
                    })
                except SnapshotConflictError:
                    competing = store.lookup_finalize_attempt(
                        canonical_request_hash
                    )
                    if competing is not None:
                        return {"terminal": provider_in_progress_update(
                            attempt_id=str(competing.get("attempt_id") or ""),
                            call_id=str(competing.get("call_id") or ""),
                            wire_request_hash=canonical_request_hash,
                        )}
                    raise

            reservation_dispatched = False
            provider_started_monotonic = time.monotonic()
            try:
                wire_payload = _build_finalize_wire_payload(messages, settings)
                effective_wire = _finalize_effective_wire_projection(
                    wire_payload, settings
                )
                rebuilt_wire_hash = self._finalize_digest({
                    "wire_hash_schema_version": 1,
                    "endpoint_id": str(settings["endpoint_id"]),
                    "api_surface": "chat_completions",
                    "method": "POST",
                    "provider_id": str(settings["provider_id"]),
                    "payload_digest": str(effective_wire["payload_digest"]),
                })
                if rebuilt_wire_hash != canonical_request_hash:
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
                wire_artifact = store.persist_finalize_effective_wire_settings(
                    attempt_id=attempt_id,
                    call_id=call_id,
                    canonical_request_hash=canonical_request_hash,
                    settings=effective_wire,
                )
                if reservation is None:
                    reserved_cost = (
                        int(row["capacity_profile"].get("input_token_estimate") or 0)
                        + int(settings["max_output_tokens"])
                    ) * cost_rate_microusd_per_token
                    reservation = store.hold_finalize_budget_reservation(
                        replay_scope_id=str(protocol().get("replay_scope_id") or ""),
                        finalize_context_id=context_id,
                        attempt_id=attempt_id,
                        call_id=call_id,
                        protocol_request_hash=protocol_request_hash,
                        wire_request_hash=canonical_request_hash,
                        work_budget_ref=str(work_budget["work_budget_ref"]),
                        work_budget_hash=str(work_budget["work_budget_hash"]),
                        reserved_completion_tokens=int(settings["max_output_tokens"]),
                        reserved_cost_microusd=reserved_cost,
                        reserved_wall_time_ms=min(
                            int(settings["per_call_timeout_ms"]),
                            int(CONSULTANT_FINALIZE_MAX_WALL_TIME_MS),
                        ),
                        timeout_ms=int(settings["per_call_timeout_ms"]),
                        batch_id=str(batch["decision_batch_id"]),
                        request_intent_hash=request_intent_hash,
                        call_kind=call_kind,
                        parent_attempt_id=parent_attempt_id,
                        retry_authorization_ref=(
                            str(
                                retry_authorization.get(
                                    "retry_authorization_ref"
                                ) or ""
                            )
                            or None
                        ),
                        retry_authorization_hash=(
                            str(
                                retry_authorization.get(
                                    "retry_authorization_hash"
                                ) or ""
                            )
                            or None
                        ),
                        resolution_item_count=(
                            len(batch.get("item_ids") or [])
                            if str(batch.get("derivation_kind") or "initial")
                            == "initial"
                            and call_kind != "transport_retry"
                            else 0
                        ),
                        created_batch_count=(
                            0 if call_kind == "transport_retry" else 1
                        ),
                        repartition_depth=int(batch.get("repartition_depth") or 0),
                    )
                project_reservation(reservation)
                ensure_graph_request_started(
                    attempt_id=attempt_id,
                    call_id=call_id,
                    call_kind=call_kind,
                    batch=batch,
                    claim=claim,
                    request_intent_hash=request_intent_hash,
                    protocol_request_hash=protocol_request_hash,
                    wire_request_hash=canonical_request_hash,
                    row=row,
                    wire_artifact=wire_artifact,
                    reservation=reservation,
                )
                reservation = store.dispatch_finalize_budget_reservation(
                    str(reservation["reservation_id"]),
                    expected_reservation_hash=str(reservation["reservation_hash"]),
                    expected_protected_record_hash=str(
                        reservation["protected_record_hash"]
                    ),
                    lease_owner=str(reservation["lease_owner"]),
                    lease_epoch=int(reservation["lease_epoch"]),
                    call_started_at=datetime.now(timezone.utc).isoformat(),
                )
                reservation_dispatched = True
                project_reservation(reservation)
                provider_started_monotonic = time.monotonic()
                provider_result = await self._invoke_consultant_finalize_provider(
                    messages,
                    task_id=task_id,
                    store=store,
                    attempt_id=attempt_id,
                    call_id=call_id,
                    call_kind=call_kind,
                    canonical_request_hash=canonical_request_hash,
                    settings=settings,
                    trace_metadata={
                        "node_name": "consultant",
                        "protocol_schema_version": 4,
                        "wire_schema_version": 3,
                        "finalize_context_id": context_id,
                        "decision_batch_id": batch["decision_batch_id"],
                    },
                )
                return {
                    "attempt_id": attempt_id,
                    "call_id": call_id,
                    "reservation": reservation,
                    "provider_result": provider_result,
                    "provider_wall_time_ms": max(
                        0,
                        int((time.monotonic() - provider_started_monotonic) * 1000),
                    ),
                    "reused": False,
                }
            except BaseException as exc:
                if isinstance(exc, asyncio.CancelledError):
                    store.release_finalize_provider_lease(attempt_id)
                    raise
                if reservation is None or not reservation_dispatched:
                    try:
                        if reservation is not None and str(
                            reservation.get("status") or ""
                        ) == "held":
                            reservation = store.release_finalize_budget_reservation(
                                str(reservation["reservation_id"]),
                                dispatch_never_began=True,
                                release_reason="controller_failure_before_provider_dispatch",
                                expected_reservation_hash=str(
                                    reservation["reservation_hash"]
                                ),
                                expected_protected_record_hash=str(
                                    reservation["protected_record_hash"]
                                ),
                                lease_owner=str(reservation["lease_owner"]),
                                lease_epoch=int(reservation["lease_epoch"]),
                            )
                            project_reservation(reservation)
                    except Exception as release_exc:
                        logger.error(
                            "Could not release pre-dispatch v4 reservation: %s",
                            release_exc,
                        )
                    finally:
                        store.release_finalize_provider_lease(attempt_id)
                    return {"terminal": terminal_update(
                        error_code=(
                            "FINALIZE_GLOBAL_BUDGET_EXHAUSTED"
                            if "FINALIZE_GLOBAL_BUDGET_EXHAUSTED" in str(exc)
                            else "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        ),
                        error_owner="controller_storage",
                        detail=f"Bounded batch preparation failed before provider dispatch: {type(exc).__name__}: {exc}",
                    )}
                failure = _classify_finalize_provider_exception(
                    exc,
                    idempotency_supported=bool(settings.get("idempotency_supported")),
                )
                try:
                    failure_integrity = (
                        "unknown"
                        if str(failure["provider_status"]) == "outcome_unknown"
                        else "missing"
                    )
                    store.record_finalize_attempt_failure(
                        attempt_id=attempt_id,
                        call_id=call_id,
                        canonical_request_hash=canonical_request_hash,
                        provider_status=str(failure["provider_status"]),
                        error_code=str(failure["error_code"]),
                        error_owner=str(failure["error_owner"]),
                        error_details={
                            "error_type": type(exc).__name__,
                            "message": str(exc)[:2000],
                        },
                        retry_safe=bool(failure["retry_safe"]),
                    )
                    reservation = store.consume_finalize_budget_reservation(
                        str(reservation["reservation_id"]),
                        provider_status=str(failure["provider_status"]),
                        completion_integrity=failure_integrity,
                        retry_safe=bool(failure["retry_safe"]),
                        actual_wall_time_ms=max(
                            0,
                            int((time.monotonic() - provider_started_monotonic) * 1000),
                        ),
                        expected_reservation_hash=str(reservation["reservation_hash"]),
                        expected_protected_record_hash=str(
                            reservation["protected_record_hash"]
                        ),
                        lease_owner=str(reservation["lease_owner"]),
                        lease_epoch=int(reservation["lease_epoch"]),
                    )
                    project_reservation(reservation)
                    if str((graph_attempt(attempt_id) or {}).get("provider_status") or "") == "in_flight":
                        commit({
                            "transition": "provider_failed",
                            "attempt_id": attempt_id,
                            "provider_status": str(failure["provider_status"]),
                            "error_code": str(failure["error_code"]),
                            "error_owner": str(failure["error_owner"]),
                            "retry_safe": bool(failure["retry_safe"]),
                        })
                except Exception as persist_exc:
                    logger.error("Could not persist/commit v4 provider failure: %s", persist_exc)
                finally:
                    store.release_finalize_provider_lease(attempt_id)
                if bool(failure["retry_safe"]) and call_kind != "transport_retry":
                    return {"terminal": provider_retry_pending_update(
                        attempt_id=attempt_id,
                        call_id=call_id,
                        wire_request_hash=canonical_request_hash,
                        error_code=str(failure["error_code"]),
                        error_owner=str(failure["error_owner"]),
                    )}
                return {"terminal": terminal_update(
                    error_code=str(failure["error_code"]),
                    error_owner=str(failure["error_owner"]),
                    detail=f"Bounded batch provider call failed: {type(exc).__name__}: {exc}",
                )}

        while queue:
            if int(protocol().get("aggregate", {}).get("used_provider_calls") or 0) >= int(
                CONSULTANT_FINALIZE_MAX_PROVIDER_CALLS
            ):
                return terminal_update(
                    error_code="FINALIZE_GLOBAL_BUDGET_EXHAUSTED",
                    error_owner="controller",
                    detail="Provider-call budget was exhausted before all batches resolved.",
                )
            row = queue.pop(0)
            batch = row["batch"]
            schema_artifact = row["response_schema_artifact"]
            capacity_profile = row["capacity_profile"]
            if not bool(capacity_profile.get("canonical_admissible")):
                return terminal_update(
                    error_code="FINALIZE_OUTPUT_CAPACITY_UNSATISFIED",
                    error_owner="controller",
                    detail="A batch lost canonical capacity admission before dispatch.",
                )
            messages = build_finalize_batch_messages(batch, schema_artifact)
            settings = self._consultant_finalize_provider_settings(
                finalize_batch_llm_response_schema(schema_artifact, batch)
            )
            settings["per_call_timeout_ms"] = int(
                work_budget["per_call_timeout_ms"]
            )
            settings["max_output_tokens"] = int(
                capacity_profile.get("effective_output_tokens") or 0
            )
            if settings["max_output_tokens"] <= int(
                capacity_profile.get("safety_headroom_tokens") or 0
            ):
                return terminal_update(
                    error_code="FINALIZE_OUTPUT_CAPACITY_UNSATISFIED",
                    error_owner="controller",
                    detail="Effective output cap does not retain mandatory headroom.",
                )
            provider_parameters = {
                "top_p": settings["top_p"],
                "max_output_tokens": settings["max_output_tokens"],
                "output_token_parameter": settings["output_token_parameter"],
                "stream": False,
                "coverage_artifact_hash": domain_coverage[
                    "coverage_artifact_hash"
                ],
                "candidate_catalog_hash": candidate_catalog[
                    "candidate_catalog_hash"
                ],
                "decision_batch_hash": batch["decision_batch_hash"],
                "response_schema_hash": schema_artifact["response_schema_hash"],
                "capacity_profile_hash": capacity_profile["profile_hash"],
                "provider_capability_hash": partition_basis[
                    "provider_capability_hash"
                ],
                "partition_capacity_basis_hash": partition_basis[
                    "partition_capacity_basis_hash"
                ],
                "stable_partition_hash": stable_partition["partition_hash"],
                "work_preflight_hash": durable_preflight[
                    "work_preflight_hash"
                ],
                "work_budget_hash": work_budget["work_budget_hash"],
                "budget_policy_hash": work_budget["budget_policy_hash"],
                "safety_policy_version": partition_basis[
                    "safety_policy_version"
                ],
                "tokenizer_id": capacity_profile["tokenizer_id"],
                "tokenizer_version": capacity_profile["tokenizer_version"],
                "estimator_mode": capacity_profile["estimator_mode"],
            }
            planned_wire = _finalize_effective_wire_projection(
                _build_finalize_wire_payload(messages, settings),
                settings,
            )
            canonical_request_hash = self._finalize_digest({
                "wire_hash_schema_version": 1,
                "endpoint_id": str(settings["endpoint_id"]),
                "api_surface": "chat_completions",
                "method": "POST",
                "provider_id": str(settings["provider_id"]),
                "payload_digest": str(planned_wire["payload_digest"]),
            })

            obtained = await obtain_provider_result(
                row=row,
                batch=batch,
                messages=messages,
                settings=settings,
                provider_parameters=provider_parameters,
                canonical_request_hash=canonical_request_hash,
            )
            if "terminal" in obtained:
                return deepcopy(dict(obtained["terminal"]))
            attempt_id = str(obtained["attempt_id"])
            call_id = str(obtained["call_id"])
            reservation = deepcopy(dict(obtained["reservation"]))
            provider_result = deepcopy(dict(obtained["provider_result"]))
            provider_wall_time_ms = obtained.get("provider_wall_time_ms")
            integrity = str(
                provider_result.get("completion_integrity") or "complete"
            )
            usage = deepcopy(dict(provider_result.get("usage") or {}))

            if integrity != "complete":
                partial = dict(provider_result.get("partial_artifact") or {})
                finish_reason = str(
                    provider_result.get("finish_reason") or "unknown"
                )
                try:
                    reservation = reconcile_result_reservation(
                        reservation,
                        provider_status="succeeded",
                        completion_integrity=integrity,
                        usage=usage,
                        artifact_ref=str(
                            partial["partial_response_artifact_ref"]
                        ),
                        artifact_hash=str(
                            partial["partial_response_artifact_hash"]
                        ),
                        actual_wall_time_ms=provider_wall_time_ms,
                    )
                    attempt_projection = graph_attempt(attempt_id)
                    if attempt_projection is None:
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    if str(attempt_projection.get("provider_status") or "") == "in_flight":
                        commit({
                            "transition": (
                                "response_truncated"
                                if integrity == "truncated"
                                else "response_blocked"
                            ),
                            "attempt_id": attempt_id,
                            "finish_reason": finish_reason,
                            "usage": usage,
                            "completion_integrity": integrity,
                            "partial_response_artifact_ref": partial[
                                "partial_response_artifact_ref"
                            ],
                            "partial_response_artifact_hash": partial[
                                "partial_response_artifact_hash"
                            ],
                        })
                    elif (
                        str(attempt_projection.get("provider_status") or "")
                        != "succeeded"
                        or str(attempt_projection.get("completion_integrity") or "")
                        != integrity
                        or str(attempt_projection.get("partial_response_artifact_hash") or "")
                        != str(partial["partial_response_artifact_hash"])
                    ):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                except Exception as exc:
                    store.release_finalize_provider_lease(attempt_id)
                    return terminal_update(
                        error_code="FINALIZE_RESERVATION_RECONCILIATION_FAILED",
                        error_owner="controller_storage",
                        detail=(
                            "Non-committable response is protected but checkpoint "
                            f"reconciliation failed: {type(exc).__name__}: {exc}"
                        ),
                    )
                finally:
                    store.release_finalize_provider_lease(attempt_id)

                item_ids = list(batch.get("item_ids") or [])
                depth = int(batch.get("repartition_depth") or 0)
                if (
                    integrity != "truncated"
                    or len(item_ids) <= 1
                    or depth >= int(CONSULTANT_FINALIZE_MAX_REPARTITION_DEPTH)
                ):
                    return terminal_update(
                        error_code=(
                            "FINALIZE_RESPONSE_TRUNCATED"
                            if integrity == "truncated"
                            else "FINALIZE_RESPONSE_CONTENT_FILTERED"
                            if integrity == "content_filtered"
                            else "FINALIZE_PROVIDER_RESOURCE_UNKNOWN"
                        ),
                        error_owner="controller_model_protocol",
                        detail=(
                            "The protected partial completion was retained and never "
                            "parsed; no smaller safe partition remains."
                        ),
                    )
                midpoint = max(1, len(item_ids) // 2)
                children: List[Dict[str, Any]] = []
                child_ids: List[str] = []
                try:
                    for child_item_ids in (
                        item_ids[:midpoint], item_ids[midpoint:]
                    ):
                        if not child_item_ids:
                            continue
                        child = build_finalize_decision_batch(
                            candidate_catalog,
                            child_item_ids,
                            parent_batch_id=str(batch["decision_batch_id"]),
                            repartition_depth=depth + 1,
                            derivation_kind="length_repartition",
                        )
                        child_schema = build_finalize_batch_schema(child)
                        child_profile = build_finalize_capacity_profile(
                            child, child_schema, partition_basis
                        )
                        if not bool(child_profile.get("canonical_admissible")):
                            raise ValueError(
                                "FINALIZE_OUTPUT_CAPACITY_UNSATISFIED"
                            )
                        children.append(prepare_batch_row(
                            child, child_schema, child_profile
                        ))
                        child_ids.append(str(child["decision_batch_id"]))
                    parent_projection = graph_batch(
                        str(batch["decision_batch_id"])
                    )
                    if str((parent_projection or {}).get("status") or "") != "superseded":
                        commit({
                            "transition": "batch_superseded",
                            "parent_batch_id": batch["decision_batch_id"],
                            "child_batch_ids": child_ids,
                        })
                    elif list(
                        (parent_projection or {}).get("superseded_by_batch_ids")
                        or []
                    ) != child_ids:
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    queue = [*children, *queue]
                    continue
                except Exception as exc:
                    return terminal_update(
                        error_code="FINALIZE_OUTPUT_CAPACITY_UNSATISFIED",
                        error_owner="controller",
                        detail=f"Length repartition failed: {type(exc).__name__}: {exc}",
                    )

            raw_response = str(provider_result.get("raw_response") or "")
            response_artifact = dict(provider_result.get("artifact") or {})
            try:
                reservation = reconcile_result_reservation(
                    reservation,
                    provider_status="succeeded",
                    completion_integrity="complete",
                    usage=usage,
                    artifact_ref=str(response_artifact["response_artifact_ref"]),
                    artifact_hash=str(response_artifact["response_content_hash"]),
                    actual_wall_time_ms=provider_wall_time_ms,
                )
                validation = validate_finalize_batch_response(
                    raw_response,
                    decision_batch=batch,
                    candidate_catalog=candidate_catalog,
                    response_schema_artifact=schema_artifact,
                )
                delivered_finish_reason = str(
                    provider_result.get("finish_reason") or "stop"
                )
                if delivered_finish_reason == "tool_calls":
                    validation = {
                        "valid": False,
                        "protocol_status": "wire_invalid",
                        "errors": [{
                            "path": "$",
                            "reason": "tool_calls finish reason is not legal for FINALIZE",
                        }],
                        "parsed_payload": validation.get("parsed_payload"),
                    }
                protocol_status = str(
                    validation.get("protocol_status") or "wire_invalid"
                )
                record_finalize_protocol_outcome(
                    store,
                    attempt_id=attempt_id,
                    call_id=call_id,
                    canonical_request_hash=canonical_request_hash,
                    protocol_status=protocol_status,
                    error_code=(
                        "" if validation.get("valid")
                        else "FINALIZE_SCHEMA_INVALID"
                    ),
                    error_owner=(
                        "" if validation.get("valid")
                        else "controller_model_protocol"
                    ),
                    validation_summary={
                        "decision_batch_hash": batch["decision_batch_hash"],
                        "response_schema_hash": schema_artifact[
                            "response_schema_hash"
                        ],
                        "capacity_profile_hash": capacity_profile["profile_hash"],
                        "errors": validation.get("errors") or [],
                    },
                )
                attempt_projection = graph_attempt(attempt_id)
                if attempt_projection is None:
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
                if str(attempt_projection.get("provider_status") or "") == "in_flight":
                    commit({
                        "transition": "response_complete",
                        "attempt_id": attempt_id,
                        "finish_reason": delivered_finish_reason,
                        "usage": usage,
                        "protocol_status": protocol_status,
                        "response_artifact_ref": response_artifact[
                            "response_artifact_ref"
                        ],
                        "response_artifact_hash": response_artifact[
                            "response_content_hash"
                        ],
                    })
                elif (
                    str(attempt_projection.get("provider_status") or "")
                    != "succeeded"
                    or str(attempt_projection.get("completion_integrity") or "")
                    != "complete"
                    or str(attempt_projection.get("response_artifact_hash") or "")
                    != str(response_artifact["response_content_hash"])
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
            except Exception as exc:
                store.release_finalize_provider_lease(attempt_id)
                return terminal_update(
                    error_code=(
                        "FINALIZE_RESERVATION_RECONCILIATION_FAILED"
                        if "RESERVATION" in str(exc)
                        else "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    ),
                    error_owner="controller_storage",
                    detail=f"Complete batch checkpoint reconciliation failed: {type(exc).__name__}: {exc}",
                )
            finally:
                store.release_finalize_provider_lease(attempt_id)

            if not bool(validation.get("valid")):
                repair_kind = {
                    "wire_invalid": "wire_repair",
                    "field_invalid": "field_repair",
                }.get(protocol_status, "")
                prior_derivation = str(
                    batch.get("derivation_kind") or "initial"
                )
                repair_depth = int(batch.get("repartition_depth") or 0)
                if (
                    not repair_kind
                    or prior_derivation in {"wire_repair", "field_repair"}
                    or repair_depth >= int(
                        CONSULTANT_FINALIZE_MAX_REPARTITION_DEPTH
                    )
                ):
                    return terminal_update(
                        error_code="FINALIZE_BATCH_PROTOCOL_INVALID",
                        error_owner="controller_model_protocol",
                        detail=(
                            "A complete bounded response failed strict "
                            "wire/field validation. The protected response was "
                            "never merged and the sole bounded repair is "
                            "unavailable or exhausted."
                        ),
                    )
                try:
                    repair_batch = build_finalize_decision_batch(
                        candidate_catalog,
                        list(batch.get("item_ids") or []),
                        parent_batch_id=str(batch["decision_batch_id"]),
                        repartition_depth=repair_depth + 1,
                        derivation_kind=repair_kind,
                    )
                    repair_schema = build_finalize_batch_schema(repair_batch)
                    repair_profile = build_finalize_capacity_profile(
                        repair_batch,
                        repair_schema,
                        partition_basis,
                    )
                    if not bool(repair_profile.get("canonical_admissible")):
                        raise ValueError(
                            "FINALIZE_OUTPUT_CAPACITY_UNSATISFIED"
                        )
                    repair_row = prepare_batch_row(
                        repair_batch,
                        repair_schema,
                        repair_profile,
                    )
                    child_ids = [str(repair_batch["decision_batch_id"])]
                    parent_projection = graph_batch(
                        str(batch["decision_batch_id"])
                    )
                    if str((parent_projection or {}).get("status") or "") != "superseded":
                        commit({
                            "transition": "batch_superseded",
                            "parent_batch_id": batch["decision_batch_id"],
                            "child_batch_ids": child_ids,
                        })
                    elif list(
                        (parent_projection or {}).get(
                            "superseded_by_batch_ids"
                        ) or []
                    ) != child_ids:
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    queue = [repair_row, *queue]
                    continue
                except Exception as exc:
                    return terminal_update(
                        error_code=(
                            "FINALIZE_OUTPUT_CAPACITY_UNSATISFIED"
                            if "FINALIZE_OUTPUT_CAPACITY_UNSATISFIED" in str(exc)
                            else "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                            if isinstance(exc, (SnapshotConflictError, OSError))
                            else "FINALIZE_BATCH_PROTOCOL_INVALID"
                        ),
                        error_owner=(
                            "controller_storage"
                            if isinstance(exc, (SnapshotConflictError, OSError))
                            else "controller_model_protocol"
                        ),
                        detail=(
                            "Bounded protocol-repair child creation failed: "
                            f"{type(exc).__name__}: {exc}"
                        ),
                    )
            if protocol_status == "needs_user":
                return terminal_update(
                    error_code="FINALIZE_UNAUTHORIZED_ASK",
                    error_owner="controller_model_protocol",
                    detail="A batch attempted user routing without a controller-owned ambiguity transition.",
                )
            decision_artifact = deepcopy(dict(validation["decision_artifact"]))
            try:
                durable_decision = persist_controller(
                    "batch_decision",
                    decision_artifact,
                    record_type="finalize_batch_decision",
                    id_rename=("decision_artifact_id", "batch_decision_id"),
                    hash_rename=("decision_artifact_hash", "batch_decision_hash"),
                )
                resolved_ids = [
                    str(item.get("resolution_id") or "")
                    for item in decision_artifact.get("resolutions") or []
                    if isinstance(item, Mapping)
                ]
                batch_projection = graph_batch(
                    str(batch["decision_batch_id"])
                )
                if str((batch_projection or {}).get("status") or "") != "resolved":
                    commit({
                        "transition": "batch_resolved",
                        "batch_id": batch["decision_batch_id"],
                        "resolved_resolution_ids": resolved_ids,
                        "decision_artifact_ref": durable_decision[
                            "batch_decision_ref"
                        ],
                        "decision_artifact_hash": durable_decision[
                            "batch_decision_hash"
                        ],
                    })
                elif (
                    str((batch_projection or {}).get("decision_artifact_hash") or "")
                    != str(durable_decision["batch_decision_hash"])
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
                validated_decisions.append(validation)
                # The artifact-first branch handles both new calls and replay.
                continue
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=f"Validated batch checkpoint commit failed: {type(exc).__name__}: {exc}",
                )

        try:
            required_skill_constraints = list(
                context_value.get("controller_required_constraints") or []
            )
            merged = merge_finalize_batch_decisions(
                context_value,
                domain_coverage,
                candidate_catalog,
                validated_decisions,
                required_skill_constraints=required_skill_constraints,
            )
            domain_compiled = deepcopy(dict(merged["compiled_contract"]))
            final_ledger = store.aggregate_finalize_budget_reservations(
                work_budget_ref=str(work_budget["work_budget_ref"]),
                work_budget_hash=str(work_budget["work_budget_hash"]),
                finalize_context_id=context_id,
            )
            ledger_totals = dict(final_ledger.get("totals") or {})
            reservation_rows = store.list_finalize_budget_reservations(
                replay_scope_id=str(protocol().get("replay_scope_id") or "")
            )
            completion_usage_known = all(
                row.get("actual_completion_tokens") is not None
                for row in reservation_rows
                if str(row.get("status") or "") == "consumed"
            )
            semantic_metrics = {
                "schema_validation": "passed",
                "protocol_schema_version": 4,
                "wire_schema_version": 3,
                "compile_mode": "model_batched",
                "provider_status": "succeeded",
                "completion_integrity": "complete",
                "protocol_status": "valid",
                "directive_count": int(domain_coverage.get("directive_count") or 0),
                "coverage_counts": deepcopy(dict(domain_coverage.get("counts") or {})),
                "coverage_artifact_ref": durable_coverage["coverage_artifact_ref"],
                "coverage_artifact_hash": durable_coverage["coverage_artifact_hash"],
                "candidate_catalog_ref": durable_catalog["candidate_catalog_ref"],
                "candidate_catalog_hash": durable_catalog["candidate_catalog_hash"],
                "stable_partition_ref": durable_partition["stable_partition_ref"],
                "stable_partition_hash": durable_partition["stable_partition_hash"],
                "work_budget_ref": work_budget["work_budget_ref"],
                "work_budget_hash": work_budget["work_budget_hash"],
                "work_preflight_ref": durable_preflight[
                    "work_preflight_ref"
                ],
                "work_preflight_hash": durable_preflight[
                    "work_preflight_hash"
                ],
                "reservation_ledger_ref": final_ledger[
                    "reservation_ledger_ref"
                ],
                "reservation_ledger_hash": final_ledger[
                    "reservation_ledger_hash"
                ],
                "provider_call_count": int(
                    ledger_totals.get("provider_calls") or 0
                ),
                "completion_tokens": int(
                    ledger_totals.get("completion_tokens") or 0
                ),
                "completion_usage_known": completion_usage_known,
                "estimated_cost_microusd": int(
                    ledger_totals.get("estimated_cost_microusd") or 0
                ),
            }
            compiled_task_spec = apply_task_spec_mutation_proposal(
                current_task_spec,
                constraint_mutation_proposal(
                    domain_compiled.get("constraints") or []
                ),
                project_root=project_root,
            )
            selected_constraints = required_skill_constraints
            compiled_task_spec = merge_compiled_constraints(
                compiled_task_spec,
                selected_constraints,
                project_root=project_root,
                metrics=semantic_metrics,
            )
            active_leaf_decisions: List[Dict[str, Any]] = []
            for leaf in protocol().get("batches") or []:
                if (
                    not isinstance(leaf, Mapping)
                    or str(leaf.get("status") or "") != "resolved"
                ):
                    continue
                decision_hash = str(
                    leaf.get("decision_artifact_hash") or ""
                )
                decision_ref = str(
                    leaf.get("decision_artifact_ref") or ""
                )
                durable_leaf = store.lookup_finalize_controller_artifact(
                    "batch_decision",
                    artifact_hash=decision_hash,
                    finalize_context_id=context_id,
                )
                if (
                    not durable_leaf
                    or str(durable_leaf.get("batch_decision_ref") or "")
                    != decision_ref
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
                active_leaf_decisions.append({
                    "batch_id": str(leaf.get("batch_id") or ""),
                    "batch_hash": str(leaf.get("batch_hash") or ""),
                    "decision_artifact_ref": decision_ref,
                    "decision_artifact_hash": decision_hash,
                    "domain_decision_artifact_hash": str(
                        durable_leaf.get("domain_decision_artifact_hash") or ""
                    ),
                })
            compiled_to_persist = deepcopy(domain_compiled)
            compiled_to_persist["domain_record_type"] = str(
                compiled_to_persist.pop("record_type", "")
            )
            compiled_to_persist.update({
                "record_type": "finalize_compiled_contract",
                "finalize_context_artifact_ref": durable_context[
                    "finalize_context_artifact_ref"
                ],
                "finalize_context_artifact_hash": durable_context[
                    "finalize_context_artifact_hash"
                ],
                "coverage_artifact_ref": durable_coverage[
                    "coverage_artifact_ref"
                ],
                "candidate_catalog_ref": durable_catalog[
                    "candidate_catalog_ref"
                ],
                "active_leaf_decisions": active_leaf_decisions,
                "summary": (
                    "Consultant FINALIZE v4 resolved the finite candidate catalog "
                    f"in {semantic_metrics['provider_call_count']} bounded provider call(s)."
                ),
                "task_spec_revision": task_spec_revision(compiled_task_spec),
                "semantic_constraint_count": len(
                    domain_compiled.get("constraints") or []
                ),
            })
            durable_compiled = store.persist_finalize_compiled_contract(
                compiled_to_persist
            )
            verified = store.lookup_finalize_compiled_contract(
                compiled_contract_hash=durable_compiled["compiled_contract_hash"],
                finalize_context_id=context_id,
            )
            if verified != durable_compiled:
                raise SnapshotConflictError(
                    "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                )
            commit({
                "transition": "compiled",
                "compile_mode": "model_batched",
                "coverage_artifact_ref": durable_coverage[
                    "coverage_artifact_ref"
                ],
                "coverage_artifact_hash": durable_coverage[
                    "coverage_artifact_hash"
                ],
                "compiled_contract_ref": durable_compiled[
                    "compiled_contract_ref"
                ],
                "compiled_contract_hash": durable_compiled[
                    "compiled_contract_hash"
                ],
            })
            validate_finalize_protocol_v4(protocol())
        except Exception as exc:
            return terminal_update(
                error_code="FINALIZE_COMPILE_FAILED",
                error_owner=(
                    "controller_storage"
                    if isinstance(exc, (SnapshotConflictError, OSError))
                    else "controller"
                ),
                detail=f"Atomic batch merge failed: {type(exc).__name__}: {exc}",
            )

        summary = str(durable_compiled.get("summary") or "")
        current_consultation.pop("final_contract", None)
        current_consultation.update({
            "phase": "finalize",
            "consultation_status": "completed",
            "completion_decision": "ready_to_finalize",
            "completion_reason": "formal_contract_compiled_v4_batched",
            "resolved_selected_skill_ids": list(selected),
            "compiled_contract_ref": str(durable_compiled.get("compiled_contract_ref") or ""),
            "compiled_contract_hash": str(durable_compiled.get("compiled_contract_hash") or ""),
        })
        return {
            "messages": [AIMessage(content="FINISH\n" + summary)],
            "input_audit": input_audit,
            "selected_skills": list(selected),
            "selected_skills_raw": list(selected),
            "active_skills": list(selected),
            "future_skills": [],
            "required_skills_all": list(selected),
            "candidate_skills": [],
            "runtime_status": self._runtime_status_for_task(task_id, selected),
            "runtime_audit": [],
            "skill_selection_source": "consultation_controller_finalize_v4",
            "requirements_summary": summary,
            "task_spec": compiled_task_spec,
            "task_revision": task_spec_revision(compiled_task_spec),
            "consultant_constraint_metrics": {
                **semantic_metrics,
                "compiled_contract_ref": durable_compiled[
                    "compiled_contract_ref"
                ],
                "compiled_contract_hash": durable_compiled[
                    "compiled_contract_hash"
                ],
            },
            "consultation_state": current_consultation,
            "consultant_contract_repair": {},
            "pending_human_question": {},
            "contract_status": "semantic_contract_compiled",
            "memory_packet_context": self._consultant_handoff_memory_packet(
                summary,
                consultant_memory_retrieval_context,
            ),
            "wiki_memory_context": consultant_wiki_context,
            "next_step": "planner",
        }

    async def _run_consultant_finalize_v2(
        self,
        *,
        state: Mapping[str, Any],
        task_id: str,
        task_spec: Mapping[str, Any],
        consultation_state: Mapping[str, Any],
        resolved_selected_skill_ids: Sequence[str],
        input_audit: Mapping[str, Any],
        consultant_wiki_context: str = "",
        consultant_memory_retrieval_context: str = "",
    ) -> Dict[str, Any]:
        """Run the isolated, artifact-first Consultant FINALIZE protocol."""
        current_task_spec = merge_task_spec_input_audit(task_spec, input_audit)
        current_consultation = deepcopy(dict(consultation_state or {}))
        legacy_projection = state.get("consultant_contract_repair")
        historical_legacy_migration = bool(
            isinstance(legacy_projection, Mapping)
            and legacy_projection
            and not isinstance(current_consultation.get("finalize_protocol"), Mapping)
            and int(legacy_projection.get("schema_version") or 0) < 3
        )
        if isinstance(legacy_projection, Mapping) and legacy_projection:
            migration_input = deepcopy(current_consultation)
            migration_input["consultant_contract_repair"] = deepcopy(dict(legacy_projection))
            current_consultation = migrate_finalize_protocol_state(migration_input)
        elif isinstance(current_consultation.get("finalize_protocol"), Mapping):
            current_consultation = migrate_finalize_protocol_state(current_consultation)

        task_is_skill_free = self._consultant_task_is_explicitly_skill_free(
            current_task_spec
        )

        def protocol() -> Dict[str, Any]:
            value = current_consultation.get("finalize_protocol")
            return dict(value) if isinstance(value, Mapping) else {}

        def terminal_update(
            *,
            error_code: str,
            error_owner: str,
            detail: str,
            provider_block: Optional[bool] = None,
        ) -> Dict[str, Any]:
            nonlocal current_consultation
            active = protocol()
            if active and str(active.get("status") or "") not in {
                "compiled",
                "blocked_internal_contract",
                "blocked_internal_provider",
            }:
                current_consultation = commit_finalize_decision(
                    current_consultation,
                    {
                        "transition": "blocked_internal",
                        "error_code": error_code,
                        "error_owner": error_owner,
                        "provider_block": provider_block,
                    },
                )
            current_consultation.update({
                "phase": "blocked",
                "consultation_status": "blocked",
                "completion_decision": "blocked",
                "completion_reason": error_code,
                "resolved_selected_skill_ids": list(
                    resolved_selected_skill_ids
                ),
            })
            active = protocol()
            provider_terminal = str(active.get("status") or "") == "blocked_internal_provider"
            safe_detail = redact_lineage_text(detail or error_code).strip()[:4000]
            diagnostic = {
                "error_code": error_code,
                "error_owner": error_owner,
                "finalize_context_id": str(active.get("finalize_context_id") or ""),
                "base_contract_hash": str(active.get("base_contract_hash") or ""),
                "detail": safe_detail,
            }
            current_consultation["terminal_diagnostic"] = deepcopy(diagnostic)
            logger.error(
                "Consultant FINALIZE v2 stopped internally: task=%s code=%s owner=%s detail=%s",
                task_id,
                error_code,
                error_owner,
                safe_detail,
            )
            output.print_once(
                f"consultant_finalize_internal:{task_id}:{error_code}",
                (
                    "⛔ Consultant FINALIZE stopped before Planner: "
                    f"{error_code}. {safe_detail[:500]}"
                ),
                Fore.RED,
            )
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_finalize_internal_error>\n"
                    + json.dumps(diagnostic, ensure_ascii=False, sort_keys=True)
                    + "\n</consultant_finalize_internal_error>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": current_task_spec,
                "task_revision": task_spec_revision(current_task_spec),
                "selected_skills": list(resolved_selected_skill_ids),
                "selected_skills_raw": list(resolved_selected_skill_ids),
                "active_skills": list(resolved_selected_skill_ids),
                "required_skills_all": list(resolved_selected_skill_ids),
                "consultation_state": current_consultation,
                "consultant_contract_repair": finalize_repair_projection(current_consultation),
                "pending_human_question": {},
                "contract_status": (
                    "blocked_internal_provider_error"
                    if provider_terminal
                    else "blocked_internal_contract_error"
                ),
                "consultant_constraint_metrics": {
                    "schema_validation": "failed",
                    "error_code": error_code,
                    "error_owner": error_owner,
                },
                "task_status": TASK_STATUS_BLOCKED,
                "failure_type": error_code,
                "failure_owner": error_owner,
                "next_step": "finish",
            }

        def resume_existing_terminal_protocol() -> Optional[Dict[str, Any]]:
            """Project an already-terminal protocol without rebuilding its context.

            A compiled TaskSpec contains the Consultant's accepted delta, so using it
            to rebuild the *pre-finalize* context would manufacture a different
            binding before the durable response can be verified.  Terminal replay is
            therefore artifact-first and uses only the binding already committed in
            ``finalize_protocol``.
            """
            nonlocal current_consultation
            active = protocol()
            status = str(active.get("status") or "")

            def fail_checkpoint_integrity(detail: str) -> Dict[str, Any]:
                nonlocal current_consultation
                try:
                    current_consultation = commit_finalize_decision(
                        current_consultation,
                        {
                            "transition": "checkpoint_integrity_failure",
                            "error_code": "FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                            "error_owner": "controller_storage",
                        },
                    )
                except Exception as commit_exc:
                    logger.error(
                        "Could not commit finalize checkpoint failure: %s",
                        commit_exc,
                    )
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=detail,
                )

            def verified_terminal_artifact(
                expected_protocol_status: str,
            ) -> Tuple[Dict[str, Any], Dict[str, Any]]:
                attempts = [
                    dict(item)
                    for item in active.get("attempts", []) or []
                    if isinstance(item, Mapping)
                ]
                if not attempts:
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
                completed_attempt = attempts[-1]
                attempt_id = str(completed_attempt.get("attempt_id") or "")
                call_id = str(completed_attempt.get("call_id") or "")
                request_hash = str(
                    completed_attempt.get("canonical_request_hash") or ""
                )
                response_ref = str(
                    completed_attempt.get("response_artifact_ref") or ""
                )
                response_hash = str(
                    completed_attempt.get("response_content_hash") or ""
                )
                if (
                    not attempt_id
                    or not call_id
                    or not request_hash
                    or not response_ref
                    or not response_hash
                    or request_hash
                    != str(active.get("active_canonical_request_hash") or "")
                    or str(completed_attempt.get("provider_status") or "")
                    != "succeeded"
                    or str(completed_attempt.get("protocol_status") or "")
                    != expected_protocol_status
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
                artifact = ContextLineageStore(
                    self.data_path,
                    task_id,
                ).lookup_finalize_response_artifact(
                    attempt_id=attempt_id,
                    call_id=call_id,
                    canonical_request_hash=request_hash,
                )
                if (
                    not artifact
                    or str(artifact.get("provider_status") or "") != "succeeded"
                    or str(artifact.get("protocol_status") or "")
                    != expected_protocol_status
                    or not str(artifact.get("protocol_outcome_ref") or "")
                    or str(artifact.get("canonical_request_hash") or "")
                    != request_hash
                    or str(artifact.get("response_artifact_ref") or "")
                    != response_ref
                    or str(artifact.get("response_content_hash") or "")
                    != response_hash
                ):
                    raise SnapshotConflictError(
                        "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    )
                if expected_protocol_status == "valid":
                    if (
                        str(completed_attempt.get("error_code") or "")
                        or str(completed_attempt.get("error_owner") or "")
                        or str(artifact.get("error_code") or "")
                        or str(artifact.get("error_owner") or "")
                    ):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                elif expected_protocol_status == "needs_user":
                    if (
                        str(completed_attempt.get("error_code") or "")
                        != "FINALIZE_SEMANTIC_AMBIGUITY"
                        or str(completed_attempt.get("error_owner") or "")
                        != "user_semantic"
                        or str(artifact.get("error_code") or "")
                        != "FINALIZE_SEMANTIC_AMBIGUITY"
                        or str(artifact.get("error_owner") or "")
                        != "user_semantic"
                    ):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                return completed_attempt, dict(artifact)

            if status in {"blocked_internal_contract", "blocked_internal_provider"}:
                return terminal_update(
                    error_code=str(
                        active.get("terminal_error_code")
                        or "FINALIZE_REPAIR_EXHAUSTED"
                    ),
                    error_owner=str(active.get("terminal_owner") or "controller"),
                    detail="Finalize protocol is already in a typed terminal state.",
                    provider_block=status == "blocked_internal_provider",
                )
            if status == "compiled":
                final_contract = deepcopy(
                    dict(current_consultation.get("final_contract") or {})
                )
                try:
                    completed_attempt, completed_artifact = (
                        verified_terminal_artifact("valid")
                    )
                    outcome_summary = completed_artifact.get(
                        "validation_summary"
                    )
                    if not isinstance(outcome_summary, Mapping):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    durable_contract_hash = str(
                        outcome_summary.get("compiled_contract_hash") or ""
                    )
                    controller_selected = list(
                        current_consultation.get("resolved_selected_skill_ids") or []
                    )
                    final_selected = final_contract.get("selected_skills")
                    final_constraints_value = final_contract.get("constraints")
                    if (
                        not durable_contract_hash
                        or str(final_contract.get("compiled_contract_hash") or "")
                        != durable_contract_hash
                        or canonical_compiled_contract_hash(final_contract)
                        != durable_contract_hash
                        or deepcopy(outcome_summary.get("coverage_audit"))
                        != deepcopy(final_contract.get("coverage_audit"))
                        or int(outcome_summary.get("constraint_count") or -1)
                        != int(final_contract.get("semantic_constraint_count") or -2)
                        or not isinstance(final_constraints_value, list)
                        or int(final_contract.get("semantic_constraint_count") or -1)
                        != len(final_constraints_value or [])
                        or not isinstance(final_selected, list)
                        or final_selected != controller_selected
                        or controller_selected != list(resolved_selected_skill_ids)
                        or str(final_contract.get("finalize_context_id") or "")
                        != str(active.get("finalize_context_id") or "")
                        or str(final_contract.get("base_contract_hash") or "")
                        != str(active.get("base_contract_hash") or "")
                        or str(final_contract.get("canonical_request_hash") or "")
                        != str(completed_attempt.get("canonical_request_hash") or "")
                        or str(final_contract.get("response_artifact_ref") or "")
                        != str(completed_artifact.get("response_artifact_ref") or "")
                        or str(final_contract.get("response_content_hash") or "")
                        != str(completed_artifact.get("response_content_hash") or "")
                        or int(final_contract.get("task_spec_revision") or -1)
                        != task_spec_revision(current_task_spec)
                    ):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                except (SnapshotConflictError, OSError, TypeError, ValueError) as exc:
                    return fail_checkpoint_integrity(
                        detail=(
                            "Compiled finalize artifact verification failed: "
                            f"{type(exc).__name__}: {exc}"
                        ),
                    )
                return {
                    "messages": [AIMessage(content=(
                        "FINISH\n"
                        + str(
                            final_contract.get("summary")
                            or "Contract already compiled."
                        )
                    ))],
                    "input_audit": deepcopy(dict(input_audit or {})),
                    "task_spec": current_task_spec,
                    "task_revision": task_spec_revision(current_task_spec),
                    "selected_skills": deepcopy(final_contract["selected_skills"]),
                    "consultation_state": current_consultation,
                    "consultant_contract_repair": finalize_repair_projection(
                        current_consultation
                    ),
                    "pending_human_question": {},
                    "contract_status": "semantic_contract_compiled",
                    "next_step": "planner",
                }
            if status == "needs_user":
                try:
                    verified_terminal_artifact("needs_user")
                    pending = current_consultation.get("pending_human_question")
                    if not isinstance(pending, Mapping):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    pending = dict(pending)
                    ambiguity_id = str(pending.get("ambiguity_id") or "").strip()
                    current_revision = task_spec_revision(current_task_spec)
                    requirements = [
                        dict(item)
                        for item in current_task_spec.get("requirements", []) or []
                        if isinstance(item, Mapping)
                        and str(
                            item.get("constraint_id")
                            or item.get("requirement_id")
                            or ""
                        ).strip()
                        == ambiguity_id
                    ]
                    if len(requirements) != 1:
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    ambiguity = requirements[0]
                    catalog = semantic_provenance_catalog(
                        current_task_spec,
                        consultation_state=current_consultation,
                        selected_skill_ids=list(resolved_selected_skill_ids),
                    )
                    catalog_ids = {
                        str(item.get("source_id") or "").strip()
                        for item in catalog
                        if isinstance(item, Mapping)
                        and str(item.get("source_id") or "").strip()
                    }
                    source_ids = set(
                        self._finalize_constraint_source_ids(ambiguity)
                    )
                    unresolved_rows = [
                        dict(item)
                        for item in current_task_spec.get("unresolved_questions", []) or []
                        if isinstance(item, Mapping)
                        and bool(item.get("active", True))
                        and str(
                            item.get("ambiguity_id")
                            or item.get("constraint_id")
                            or ""
                        ).strip()
                        == ambiguity_id
                    ]
                    if unresolved_rows:
                        unresolved = unresolved_rows[0]
                        if (
                            len(unresolved_rows) != 1
                            or not bool(unresolved.get("needs_clarification"))
                            or str(unresolved.get("semantic_key") or "").strip()
                            != str(ambiguity.get("semantic_key") or "").strip()
                        ):
                            raise SnapshotConflictError(
                                "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                            )
                    if (
                        not ambiguity_id
                        or ambiguity_id
                        != str(active.get("pending_ambiguity_id") or "").strip()
                        or str(pending.get("question") or "").strip()
                        != self._consultant_finalize_ambiguity_question(ambiguity)
                        or str(pending.get("finalize_context_id") or "")
                        != str(active.get("finalize_context_id") or "")
                        or str(pending.get("base_contract_hash") or "")
                        != str(active.get("base_contract_hash") or "")
                        or int(pending.get("task_spec_revision") or -1)
                        != current_revision
                        or not bool(ambiguity.get("needs_clarification"))
                        or str(ambiguity.get("strength") or "").strip().lower()
                        not in {"hard", "required", "conditional", "ambiguous"}
                        or not str(ambiguity.get("semantic_key") or "").strip()
                        or not str(ambiguity.get("unresolved_reason") or "").strip()
                        or not source_ids
                        or not source_ids.issubset(catalog_ids)
                        or (
                            active.get("superseded_by_task_spec_revision")
                            not in (None, "")
                            and str(active.get("superseded_by_task_spec_revision"))
                            != str(current_revision)
                        )
                    ):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                except (SnapshotConflictError, OSError, TypeError, ValueError) as exc:
                    return fail_checkpoint_integrity(
                        "Needs-user finalize binding verification failed: "
                        f"{type(exc).__name__}: {exc}"
                    )
                else:
                    return {
                        "messages": [],
                        "input_audit": deepcopy(dict(input_audit or {})),
                        "task_spec": current_task_spec,
                        "task_revision": task_spec_revision(current_task_spec),
                        "consultation_state": current_consultation,
                        "consultant_contract_repair": finalize_repair_projection(
                            current_consultation
                        ),
                        "pending_human_question": deepcopy(dict(pending)),
                        "contract_status": "blocked_need_user_decision",
                        "next_step": "ask_user",
                    }
            return None

        terminal_projection = resume_existing_terminal_protocol()
        if terminal_projection is not None:
            return terminal_projection

        precondition_errors = self._consultant_finalize_precondition_errors(
            task_spec=current_task_spec,
            consultation_state=current_consultation,
            resolved_selected_skill_ids=resolved_selected_skill_ids,
            input_audit=input_audit,
            task_is_skill_free=task_is_skill_free,
        )
        if precondition_errors:
            return terminal_update(
                error_code="FINALIZE_REPAIR_EXHAUSTED",
                error_owner="controller",
                detail="Finalize entry preconditions failed: " + "; ".join(precondition_errors),
            )

        try:
            finalize_context = self._build_consultant_finalize_context(
                task_id=task_id,
                task_spec=current_task_spec,
                consultation_state=current_consultation,
                resolved_selected_skill_ids=resolved_selected_skill_ids,
                input_audit=input_audit,
                task_is_skill_free=task_is_skill_free,
            )
        except Exception as exc:
            return terminal_update(
                error_code="FINALIZE_REPAIR_EXHAUSTED",
                error_owner="controller",
                detail=f"Finalize context construction failed: {type(exc).__name__}: {exc}",
            )
        context_value = thaw_finalize_value(finalize_context)
        context_id = str(context_value.get("finalize_context_id") or "")
        base_contract_hash = str(context_value.get("base_contract_hash") or "")
        wire_schema_version = int(context_value.get("wire_schema_version") or 2)

        active = protocol()
        if active and str(active.get("terminal_error_code") or "") == (
            "FINALIZE_CONTEXT_BINDING_UNRECOVERABLE"
        ):
            return terminal_update(
                error_code="FINALIZE_CONTEXT_BINDING_UNRECOVERABLE",
                error_owner="controller_storage",
                detail="Historical repair state has no deterministically recoverable v2 context binding.",
            )
        if not active:
            current_consultation = initialize_finalize_protocol(
                current_consultation,
                finalize_context_id=context_id,
                base_contract_hash=base_contract_hash,
                wire_schema_version=wire_schema_version,
            )
        elif (
            str(active.get("finalize_context_id") or "") != context_id
            or str(active.get("base_contract_hash") or "") != base_contract_hash
            or int(active.get("wire_schema_version") or 0) != wire_schema_version
        ):
            superseded_revision = active.get("superseded_by_task_spec_revision")
            if superseded_revision not in (None, ""):
                if (
                    str(active.get("status") or "") != "ready"
                    or str(superseded_revision)
                    != str(task_spec_revision(current_task_spec))
                ):
                    return terminal_update(
                        error_code="FINALIZE_CONTEXT_BINDING_UNRECOVERABLE",
                        error_owner="controller_storage",
                        detail=(
                            "Superseded finalize binding does not match one exact "
                            "applied-answer TaskSpec revision."
                        ),
                    )
                try:
                    current_consultation = commit_finalize_decision(
                        current_consultation,
                        {
                            "transition": "replace_context",
                            "new_finalize_context_id": context_id,
                            "new_base_contract_hash": base_contract_hash,
                            "new_wire_schema_version": wire_schema_version,
                            "max_wire_repair_attempts": 2,
                            "max_field_repair_attempts": 2,
                        },
                    )
                except Exception as exc:
                    return terminal_update(
                        error_code="FINALIZE_CONTEXT_BINDING_UNRECOVERABLE",
                        error_owner="controller_storage",
                        detail=f"Superseded context replacement failed: {type(exc).__name__}: {exc}",
                    )
            else:
                return terminal_update(
                    error_code="FINALIZE_CONTEXT_BINDING_UNRECOVERABLE",
                    error_owner="controller_storage",
                    detail=(
                        "The active finalize binding differs from the current immutable "
                        "TaskSpec/evidence context without a recorded user-answer supersession."
                    ),
                )

        active = protocol()
        repair = deepcopy(dict(active.get("repair") or {}))
        prior_attempts = [
            deepcopy(dict(item))
            for item in active.get("attempts", []) or []
            if isinstance(item, Mapping)
        ]
        last_attempt = prior_attempts[-1] if prior_attempts else {}
        transport_retry = bool(
            str(last_attempt.get("provider_status") or "") == "transient_failed"
            and bool(last_attempt.get("retry_safe"))
            and not str(last_attempt.get("response_artifact_ref") or "")
        )
        repair_kind = str(repair.get("repair_kind") or "none")
        message_kind = "initial"
        if repair_kind == "wire_format":
            message_kind = "wire_repair"
        elif repair_kind == "field_patch":
            message_kind = "field_repair"
        call_kind = "transport_retry" if transport_retry else message_kind
        store = ContextLineageStore(self.data_path, task_id)

        try:
            if message_kind == "initial":
                response_schema = finalize_result_schema(finalize_context)
                system_policy = PromptManager.get_consultant_finalize_system_prompt(
                    finalize_context_id=context_id,
                    base_contract_hash=base_contract_hash,
                    allowed_actions=list(context_value.get("allowed_actions") or []),
                    response_schema=response_schema,
                )
                finalize_messages = build_finalize_messages(
                    finalize_context,
                    system_policy=system_policy,
                    response_schema=response_schema,
                )
            elif message_kind == "wire_repair":
                artifact = None
                for attempt in reversed(prior_attempts):
                    if not str(attempt.get("response_artifact_ref") or ""):
                        continue
                    artifact = store.lookup_finalize_response_artifact(
                        attempt_id=str(attempt.get("attempt_id") or ""),
                        call_id=str(attempt.get("call_id") or ""),
                        canonical_request_hash=str(attempt.get("canonical_request_hash") or ""),
                    )
                    if artifact:
                        break
                if not artifact:
                    return terminal_update(
                        error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        error_owner="controller_storage",
                        detail="Wire repair cannot locate its protected preceding response artifact.",
                    )
                wire_attempt = int(repair.get("wire_repair_attempt") or 0)
                if not transport_retry:
                    wire_attempt += 1
                failure = {
                    "error_code": str(repair.get("error_code") or "FINALIZE_RESPONSE_NOT_JSON"),
                    "response_content_hash": str(artifact.get("response_content_hash") or ""),
                    "errors": deepcopy(list(repair.get("validation_errors") or [])),
                }
                response_schema = finalize_result_schema(finalize_context)
                system_policy = PromptManager.get_consultant_finalize_wire_repair_prompt(
                    finalize_context_id=context_id,
                    base_contract_hash=base_contract_hash,
                    allowed_actions=list(context_value.get("allowed_actions") or []),
                    response_schema=response_schema,
                )
                finalize_messages = build_wire_repair_messages(
                    finalize_context,
                    failure,
                    wire_repair_attempt=wire_attempt,
                    system_policy=system_policy,
                    response_schema=response_schema,
                    invalid_response=str(artifact.get("raw_response") or ""),
                )
            else:
                base_payload = repair.get("base_payload")
                allowed_by_index = repair.get("allowed_fields_by_index") or {}
                allowed_payload = repair.get("allowed_payload_fields") or []
                if not isinstance(base_payload, Mapping):
                    return terminal_update(
                        error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        error_owner="controller_storage",
                        detail="Field repair has no immutable parsed base payload.",
                    )
                field_attempt = int(repair.get("field_repair_attempt") or 0)
                if not transport_retry:
                    field_attempt += 1
                response_schema = field_patch_schema(
                    finalize_context=finalize_context,
                    base_payload_hash=finalize_payload_hash(base_payload),
                    allowed_fields_by_index=allowed_by_index,
                    allowed_payload_fields=allowed_payload,
                )
                system_policy = PromptManager.get_consultant_finalize_field_repair_prompt(
                    finalize_context_id=context_id,
                    base_contract_hash=base_contract_hash,
                    base_payload_hash=finalize_payload_hash(base_payload),
                    allowed_fields_by_index=allowed_by_index,
                    allowed_payload_fields=allowed_payload,
                    response_schema=response_schema,
                )
                finalize_messages = build_field_repair_messages(
                    finalize_context,
                    base_payload=base_payload,
                    field_repair_attempt=field_attempt,
                    validation_errors=list(repair.get("validation_errors") or []),
                    allowed_fields_by_index=allowed_by_index,
                    allowed_payload_fields=allowed_payload,
                    last_patch_protocol_errors=list(
                        repair.get("last_patch_protocol_errors") or []
                    ),
                    system_policy=system_policy,
                    response_schema=response_schema,
                )
        except (SnapshotConflictError, OSError, ValueError, TypeError) as exc:
            return terminal_update(
                error_code=(
                    "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                    if isinstance(exc, (SnapshotConflictError, OSError))
                    else "FINALIZE_REPAIR_EXHAUSTED"
                ),
                error_owner=(
                    "controller_storage"
                    if isinstance(exc, (SnapshotConflictError, OSError))
                    else "controller"
                ),
                detail=f"Finalize request construction failed: {type(exc).__name__}: {exc}",
            )

        if [str(getattr(item, "type", "")) for item in finalize_messages] != ["system", "human"]:
            return terminal_update(
                error_code="FINALIZE_REPAIR_EXHAUSTED",
                error_owner="controller",
                detail="Finalize request role sequence is not exactly system,human.",
            )
        estimated_tokens = sum(
            _consultant_estimate_text_tokens(str(getattr(item, "content", "") or "")) + 4
            for item in finalize_messages
        )
        safe_input_tokens = max(
            1,
            int(self.llm_context_limit_tokens)
            - min(
                CONSULTANT_RESERVED_HEADROOM_TOKENS,
                max(0, int(self.llm_context_limit_tokens) - 1),
            ),
        )
        if estimated_tokens > safe_input_tokens:
            return terminal_update(
                error_code="FINALIZE_REPAIR_EXHAUSTED",
                error_owner="controller",
                detail=(
                    "Lossless finalize context exceeds the safe provider input budget: "
                    f"{estimated_tokens}>{safe_input_tokens} tokens."
                ),
            )

        try:
            settings = self._consultant_finalize_provider_settings(response_schema)
        except (TypeError, ValueError) as exc:
            return terminal_update(
                error_code="FINALIZE_REPAIR_EXHAUSTED",
                error_owner="controller",
                detail=(
                    "Finalize provider capability resolution failed: "
                    f"{type(exc).__name__}: {exc}"
                ),
            )
        provider_parameters = {
            "top_p": settings["top_p"],
            "max_output_tokens": settings["max_output_tokens"],
            "schema_id": settings["schema_id"],
            "schema_hash": settings["schema_hash"],
            "provider_response_options": {
                "thinking": settings["thinking"],
                "extra_body_allowlist": deepcopy(settings["extra_body_allowlist"]),
            },
        }
        canonical_request_hash = durable_finalize_request_hash(
            finalize_messages,
            finalize_context_id=context_id,
            wire_schema_version=wire_schema_version,
            provider_id=str(settings["provider_id"]),
            endpoint_id=str(settings["endpoint_id"]),
            model=str(settings["model"]),
            temperature=float(settings["temperature"]),
            structured_output_mode=str(settings["structured_output_mode"]),
            provider_parameters=provider_parameters,
        )

        request_metadata = {
            "finalize_context_id": context_id,
            "base_contract_hash": base_contract_hash,
            "wire_schema_version": wire_schema_version,
            "provider_id": settings["provider_id"],
            "endpoint_id": settings["endpoint_id"],
            "model": settings["model"],
            "structured_output_mode": settings["structured_output_mode"],
            "provider_parameters": provider_parameters,
            "message_role_sequence": ["system", "human"],
            "task_spec_revision": task_spec_revision(current_task_spec),
            "effective_facts_revision": context_value.get("effective_facts_revision"),
            "selected_skill_ids": list(resolved_selected_skill_ids),
        }

        def hydrate_durable_chain() -> None:
            """Project monotonic durable attempts into a stale graph checkpoint."""
            nonlocal current_consultation
            rows = list_finalize_attempts(
                store,
                canonical_request_hash=canonical_request_hash,
            )
            for row in rows:
                intent = dict(row.get("intent") or {})
                durable_attempt_id = str(intent.get("attempt_id") or row.get("attempt_id") or "")
                durable_call_id = str(intent.get("call_id") or row.get("call_id") or "")
                if not durable_attempt_id or not durable_call_id:
                    raise SnapshotConflictError("Durable finalize intent has incomplete identity")
                graph_row = next(
                    (
                        item for item in protocol().get("attempts", []) or []
                        if str((item or {}).get("attempt_id") or "") == durable_attempt_id
                    ),
                    None,
                )
                if graph_row is None:
                    current_consultation = commit_finalize_decision(
                        current_consultation,
                        {
                            "transition": "request_started",
                            "attempt_id": durable_attempt_id,
                            "call_id": durable_call_id,
                            "call_kind": str(intent.get("call_kind") or row.get("call_kind") or "initial"),
                            "canonical_request_hash": canonical_request_hash,
                            "finalize_context_id": context_id,
                            "base_contract_hash": base_contract_hash,
                            "started_at": str(intent.get("created_at") or ""),
                        },
                    )
                    graph_row = next(
                        item for item in protocol().get("attempts", []) or []
                        if str((item or {}).get("attempt_id") or "") == durable_attempt_id
                    )
                provider_status = str(row.get("provider_status") or "in_flight")
                if provider_status == "succeeded":
                    artifact = store.lookup_finalize_response_artifact(
                        attempt_id=durable_attempt_id,
                        call_id=durable_call_id,
                        canonical_request_hash=canonical_request_hash,
                    )
                    if artifact is None:
                        # A dedicated storage-failure marker is projected below;
                        # any other succeeded-without-artifact record is corrupt.
                        if str(row.get("error_code") or "") != "FINALIZE_CHECKPOINT_ARTIFACT_MISSING":
                            raise SnapshotConflictError("FINALIZE_CHECKPOINT_ARTIFACT_MISSING")
                        if str(graph_row.get("provider_status") or "") != "succeeded":
                            current_consultation = commit_finalize_decision(
                                current_consultation,
                                {
                                    "transition": "response_persistence_failure",
                                    "attempt_id": durable_attempt_id,
                                },
                            )
                        continue
                    if not str(graph_row.get("response_artifact_ref") or ""):
                        diagnostic = store.finalize_diagnostic_projection(artifact)
                        current_consultation = commit_finalize_decision(
                            current_consultation,
                            {
                                "transition": "provider_response",
                                "attempt_id": durable_attempt_id,
                                "call_id": durable_call_id,
                                "canonical_request_hash": canonical_request_hash,
                                "response_artifact_ref": str(artifact.get("response_artifact_ref") or ""),
                                "response_content_hash": str(artifact.get("response_content_hash") or ""),
                                "response_excerpt": str(diagnostic.get("response_excerpt") or ""),
                                "response_excerpt_truncated": bool(
                                    diagnostic.get("response_excerpt_truncated")
                                ),
                            },
                        )
                elif provider_status in {"transient_failed", "fatal_failed", "outcome_unknown"}:
                    if str(graph_row.get("provider_status") or "") in {"in_flight", "not_called"}:
                        current_consultation = commit_finalize_decision(
                            current_consultation,
                            {
                                "transition": "provider_failure",
                                "attempt_id": durable_attempt_id,
                                "provider_status": provider_status,
                                "error_code": str(row.get("error_code") or ""),
                                "error_owner": str(row.get("error_owner") or "provider"),
                                "retry_safe": bool(row.get("retry_safe", False)),
                                "completed_at": str(row.get("failed_at") or row.get("updated_at") or ""),
                            },
                        )

        replay_artifact: Optional[Dict[str, Any]] = None
        durable_existing: Optional[Dict[str, Any]] = None

        async def reconcile_with_live_wait(
            *,
            durable_attempt_id: str,
            durable_call_id: str,
        ) -> Dict[str, Any]:
            """Wait briefly for a live owner; never terminalize its active call."""
            loop = asyncio.get_running_loop()
            wait_budget = min(
                max(float(getattr(self, "llm_timeout_seconds", 0) or 0) + 1.0, 1.0),
                30.0,
            )
            deadline = loop.time() + wait_budget
            while True:
                value = reconcile_finalize_attempt(
                    store,
                    attempt_id=durable_attempt_id,
                    call_id=durable_call_id,
                    canonical_request_hash=canonical_request_hash,
                )
                if str(value.get("decision") or "") != "attempt_in_progress":
                    return dict(value)
                remaining = deadline - loop.time()
                if remaining <= 0:
                    return dict(value)
                await asyncio.sleep(min(0.05, remaining))

        def provider_in_progress_update(
            reconciliation: Mapping[str, Any],
        ) -> Dict[str, Any]:
            current_consultation.update({
                "phase": "finalize",
                "consultation_status": "ready",
                "completion_decision": "ready_to_finalize",
                "completion_reason": "provider_attempt_in_progress",
            })
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_finalize_provider_in_progress>"
                    + json.dumps({
                        "attempt_id": str(reconciliation.get("attempt_id") or ""),
                        "call_id": str(reconciliation.get("call_id") or ""),
                        "canonical_request_hash": canonical_request_hash,
                        "provider_status": "in_flight",
                    }, ensure_ascii=False, sort_keys=True)
                    + "</consultant_finalize_provider_in_progress>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": current_task_spec,
                "task_revision": task_spec_revision(current_task_spec),
                "consultation_state": current_consultation,
                "consultant_contract_repair": finalize_repair_projection(
                    current_consultation
                ),
                "pending_human_question": {},
                "consultant_constraint_metrics": {
                    "schema_validation": "not_run",
                    "provider_status": "in_flight",
                    "protocol_status": "not_validated",
                },
                "contract_status": "finalize_provider_in_progress",
                "next_step": "consultant",
            }

        try:
            durable_existing = lookup_finalize_attempt(store, canonical_request_hash)
            graph_same_hash = [
                item for item in protocol().get("attempts", []) or []
                if str((item or {}).get("canonical_request_hash") or "") == canonical_request_hash
                and str((item or {}).get("provider_status") or "") != "not_called"
            ]
            if graph_same_hash and not durable_existing:
                raise SnapshotConflictError("FINALIZE_CHECKPOINT_ARTIFACT_MISSING")
            if durable_existing:
                hydrate_durable_chain()
                reconciliation = await reconcile_with_live_wait(
                    durable_attempt_id=str(durable_existing.get("attempt_id") or ""),
                    durable_call_id=str(durable_existing.get("call_id") or ""),
                )
                # Reconciliation may have persisted a failure/unknown marker.
                hydrate_durable_chain()
                durable_decision = str(reconciliation.get("decision") or "")
                if durable_decision == "reuse_response":
                    replay_artifact = dict(reconciliation)
                elif durable_decision == "safe_transport_retry":
                    call_kind = "transport_retry"
                    transport_retry = True
                elif durable_decision == "attempt_in_progress":
                    return provider_in_progress_update(reconciliation)
                else:
                    return terminal_update(
                        error_code=str(
                            reconciliation.get("error_code")
                            or "FINALIZE_PROVIDER_OUTCOME_UNKNOWN"
                        ),
                        error_owner=str(
                            reconciliation.get("error_owner")
                            or "controller_provider"
                        ),
                        detail="Durable finalize attempt cannot be invoked again safely.",
                        provider_block=str(reconciliation.get("error_owner") or "") in {
                            "provider", "controller_provider"
                        },
                    )
        except (SnapshotConflictError, OSError, ValueError) as exc:
            return terminal_update(
                error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                error_owner="controller_storage",
                detail=f"Finalize checkpoint reconciliation failed: {type(exc).__name__}: {exc}",
            )

        unique_suffix = uuid.uuid4().hex
        attempt_id = (
            str((replay_artifact or {}).get("attempt_id") or "")
            or f"finalize-{context_id[-12:]}-{unique_suffix}"
        )
        call_id = (
            str((replay_artifact or {}).get("call_id") or "")
            or f"consultant-finalize-{call_kind}-{unique_suffix}"
        )

        # The durable canonical-hash claim precedes graph projection.  This
        # closes the lookup/begin window in which two workers could both call.
        if replay_artifact is None:
            try:
                claim = persist_finalize_attempt_intent(
                    store,
                    attempt_id=attempt_id,
                    call_id=call_id,
                    call_kind=call_kind,
                    canonical_request_hash=canonical_request_hash,
                    request_metadata=request_metadata,
                )
                if not bool(claim.get("claim_acquired")):
                    reconciliation = await reconcile_with_live_wait(
                        durable_attempt_id=attempt_id,
                        durable_call_id=call_id,
                    )
                    hydrate_durable_chain()
                    if str(reconciliation.get("decision") or "") == "reuse_response":
                        replay_artifact = dict(reconciliation)
                    elif str(reconciliation.get("decision") or "") == "attempt_in_progress":
                        return provider_in_progress_update(reconciliation)
                    else:
                        return terminal_update(
                            error_code=str(
                                reconciliation.get("error_code")
                                or "FINALIZE_PROVIDER_OUTCOME_UNKNOWN"
                            ),
                            error_owner=str(
                                reconciliation.get("error_owner")
                                or "controller_provider"
                            ),
                            detail="This finalize attempt was already durably claimed; it was not invoked again.",
                            provider_block=True,
                        )
            except SnapshotConflictError:
                try:
                    competing = lookup_finalize_attempt(store, canonical_request_hash)
                    if not competing:
                        raise SnapshotConflictError("Finalize claim conflict has no durable winner")
                    reconciliation = await reconcile_with_live_wait(
                        durable_attempt_id=str(competing.get("attempt_id") or ""),
                        durable_call_id=str(competing.get("call_id") or ""),
                    )
                    hydrate_durable_chain()
                    if str(reconciliation.get("decision") or "") == "reuse_response":
                        replay_artifact = dict(reconciliation)
                        attempt_id = str(replay_artifact.get("attempt_id") or "")
                        call_id = str(replay_artifact.get("call_id") or "")
                    elif str(reconciliation.get("decision") or "") == "attempt_in_progress":
                        return provider_in_progress_update(reconciliation)
                    else:
                        return terminal_update(
                            error_code=str(
                                reconciliation.get("error_code")
                                or "FINALIZE_PROVIDER_OUTCOME_UNKNOWN"
                            ),
                            error_owner=str(
                                reconciliation.get("error_owner")
                                or "controller_provider"
                            ),
                            detail="Another worker already owns this canonical finalize request.",
                            provider_block=True,
                        )
                except (SnapshotConflictError, OSError, ValueError) as exc:
                    return terminal_update(
                        error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        error_owner="controller_storage",
                        detail=f"Finalize atomic claim reconciliation failed: {type(exc).__name__}: {exc}",
                    )
            except (OSError, ValueError) as exc:
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=f"Could not persist finalize request intent: {type(exc).__name__}: {exc}",
                )

        graph_attempt = next(
            (
                item for item in protocol().get("attempts", []) or []
                if str((item or {}).get("attempt_id") or "") == attempt_id
            ),
            None,
        )
        if graph_attempt is None:
            try:
                current_consultation = commit_finalize_decision(
                    current_consultation,
                    {
                        "transition": "request_started",
                        "attempt_id": attempt_id,
                        "call_id": call_id,
                        "call_kind": call_kind,
                        "canonical_request_hash": canonical_request_hash,
                        "finalize_context_id": context_id,
                        "base_contract_hash": base_contract_hash,
                    },
                )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_IDENTICAL_REQUEST_BLOCKED",
                    error_owner="controller",
                    detail=f"Finalize request state commit was rejected: {type(exc).__name__}: {exc}",
                )
            if str(protocol().get("status") or "") in {
                "blocked_internal_contract", "blocked_internal_provider"
            }:
                return terminal_update(
                    error_code=str(protocol().get("terminal_error_code") or "FINALIZE_REPAIR_EXHAUSTED"),
                    error_owner=str(protocol().get("terminal_owner") or "controller"),
                    detail="Finalize request was blocked before provider invocation by controller budget/identity guards.",
                )

        if replay_artifact is None:
            try:
                provider_result = await self._invoke_consultant_finalize_provider(
                    finalize_messages,
                    task_id=task_id,
                    store=store,
                    attempt_id=attempt_id,
                    call_id=call_id,
                    call_kind=call_kind,
                    canonical_request_hash=canonical_request_hash,
                    settings=settings,
                    trace_metadata={
                        "node_name": "consultant",
                        "finalize_context_id": context_id,
                        "base_contract_hash": base_contract_hash,
                        "wire_schema_version": wire_schema_version,
                        "task_spec_revision": task_spec_revision(current_task_spec),
                        "effective_facts_revision": context_value.get("effective_facts_revision"),
                        "selected_skill_ids": list(resolved_selected_skill_ids),
                        "repair_kind": repair_kind,
                        "wire_repair_attempt": int(repair.get("wire_repair_attempt") or 0),
                        "field_repair_attempt": int(repair.get("field_repair_attempt") or 0),
                    },
                )
            except BaseException as exc:
                if isinstance(exc, asyncio.CancelledError):
                    store.release_finalize_provider_lease(attempt_id)
                    raise
                if isinstance(exc, FinalizeResponsePersistenceError):
                    try:
                        store.record_finalize_response_persistence_failure(
                            attempt_id=attempt_id,
                            call_id=call_id,
                            canonical_request_hash=canonical_request_hash,
                            response_content_hash=exc.response_content_hash,
                            error_details={
                                "error_type": type(exc.__cause__ or exc).__name__,
                                "message": str(exc.__cause__ or exc)[:2000],
                            },
                        )
                    except Exception as persist_exc:
                        logger.error(
                            "Could not persist finalize storage-failure marker: %s",
                            persist_exc,
                        )
                    finally:
                        store.release_finalize_provider_lease(attempt_id)
                    try:
                        current_consultation = commit_finalize_decision(
                            current_consultation,
                            {
                                "transition": "response_persistence_failure",
                                "attempt_id": attempt_id,
                            },
                        )
                    except Exception as commit_exc:
                        logger.error(
                            "Could not commit finalize response-persistence failure: %s",
                            commit_exc,
                        )
                    return terminal_update(
                        error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        error_owner="controller_storage",
                        detail=(
                            "Finalize provider returned successfully, but its exact protected "
                            "response could not be committed. The provider will not be invoked again."
                        ),
                        provider_block=False,
                    )
                provider_failure = _classify_finalize_provider_exception(
                    exc,
                    idempotency_supported=bool(
                        settings.get("idempotency_supported")
                    ),
                )
                provider_status = str(provider_failure["provider_status"])
                error_code = str(provider_failure["error_code"])
                error_owner = str(provider_failure["error_owner"])
                retry_safe = bool(provider_failure["retry_safe"])
                try:
                    store.record_finalize_attempt_failure(
                        attempt_id=attempt_id,
                        call_id=call_id,
                        canonical_request_hash=canonical_request_hash,
                        provider_status=provider_status,
                        error_code=error_code,
                        error_owner=error_owner,
                        error_details={
                            "error_type": type(exc).__name__,
                            "message": str(exc)[:2000],
                        },
                        retry_safe=retry_safe,
                    )
                except Exception as persist_exc:
                    logger.error("Could not persist finalize provider failure: %s", persist_exc)
                finally:
                    store.release_finalize_provider_lease(attempt_id)
                try:
                    current_consultation = commit_finalize_decision(
                        current_consultation,
                        {
                            "transition": "provider_failure",
                            "attempt_id": attempt_id,
                            "provider_status": provider_status,
                            "error_code": error_code,
                            "error_owner": error_owner,
                            "retry_safe": retry_safe,
                        },
                    )
                except Exception as commit_exc:
                    logger.error("Could not commit finalize provider failure: %s", commit_exc)
                if retry_safe:
                    current_consultation.update({
                        "phase": "finalize",
                        "consultation_status": "ready",
                        "completion_decision": "ready_to_finalize",
                        "completion_reason": "safe_transport_retry_pending",
                    })
                    return {
                        "messages": [SystemMessage(content=(
                            "<consultant_finalize_provider_retry>\n"
                            + json.dumps({
                                "error_code": error_code,
                                "error_owner": error_owner,
                                "provider_status": provider_status,
                                "retry_safe": True,
                                "canonical_request_hash": canonical_request_hash,
                            }, ensure_ascii=False, sort_keys=True)
                            + "\n</consultant_finalize_provider_retry>"
                        ))],
                        "input_audit": deepcopy(dict(input_audit or {})),
                        "task_spec": current_task_spec,
                        "task_revision": task_spec_revision(current_task_spec),
                        "consultation_state": current_consultation,
                        "consultant_contract_repair": finalize_repair_projection(
                            current_consultation
                        ),
                        "pending_human_question": {},
                        "contract_status": "semantic_schema_retry",
                        "next_step": "consultant",
                    }
                return terminal_update(
                    error_code=error_code,
                    error_owner=error_owner,
                    detail=f"Finalize provider call failed: {type(exc).__name__}: {exc}",
                    provider_block=True,
                )
            completion_integrity = str(
                provider_result.get("completion_integrity") or "complete"
            )
            if completion_integrity != "complete":
                partial = dict(provider_result.get("partial_artifact") or {})
                finish_reason = str(
                    provider_result.get("finish_reason") or "unknown"
                )
                error_code = (
                    "FINALIZE_RESPONSE_TRUNCATED"
                    if completion_integrity == "truncated"
                    else "FINALIZE_RESPONSE_CONTENT_FILTERED"
                    if completion_integrity == "content_filtered"
                    else "FINALIZE_PROVIDER_RESOURCE_UNKNOWN"
                )
                try:
                    current_consultation = commit_finalize_decision(
                        current_consultation,
                        {
                            "transition": "provider_partial_response",
                            "attempt_id": attempt_id,
                            "completion_integrity": completion_integrity,
                            "finish_reason": finish_reason,
                            "usage": deepcopy(
                                dict(provider_result.get("usage") or {})
                            ),
                            "partial_response_artifact_ref": str(
                                partial.get("partial_response_artifact_ref") or ""
                            ),
                            "partial_response_artifact_hash": str(
                                partial.get("partial_response_artifact_hash") or ""
                            ),
                        },
                    )
                except Exception as commit_exc:
                    return terminal_update(
                        error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        error_owner="controller_storage",
                        detail=(
                            "Partial FINALIZE response was durable but its graph transition failed: "
                            f"{type(commit_exc).__name__}: {commit_exc}"
                        ),
                    )
                return terminal_update(
                    error_code=error_code,
                    error_owner="controller_model_protocol",
                    detail=(
                        f"Provider delivered a non-committable FINALIZE response "
                        f"(finish_reason={finish_reason}, completion_integrity={completion_integrity}). "
                        "The protected partial artifact was retained and was not parsed or retried."
                    ),
                    provider_block=False,
                )
            raw_response = str(provider_result.get("raw_response") or "")
            structured_object = provider_result.get("structured_object")
            response_artifact = dict(provider_result.get("artifact") or {})
            response_reused = False
        else:
            raw_response = str(replay_artifact.get("raw_response") or "")
            structured_object = replay_artifact.get("structured_object")
            response_artifact = dict(replay_artifact)
            response_reused = True

        def persist_protocol_outcome_once(
            *,
            protocol_status: str,
            error_code: str = "",
            error_owner: str = "",
            validation_summary: Optional[Mapping[str, Any]] = None,
        ) -> Dict[str, Any]:
            existing_ref = str(response_artifact.get("protocol_outcome_ref") or "")
            if response_reused and existing_ref:
                existing_status = str(response_artifact.get("protocol_status") or "")
                existing_code = str(response_artifact.get("error_code") or "")
                existing_owner = str(response_artifact.get("error_owner") or "")
                if (
                    existing_status != protocol_status
                    or existing_code != str(error_code or "")
                    or existing_owner != str(error_owner or "")
                ):
                    raise SnapshotConflictError(
                        "Replayed protected response has a conflicting durable protocol outcome"
                    )
                return response_artifact
            return record_finalize_protocol_outcome(
                store,
                attempt_id=attempt_id,
                call_id=call_id,
                canonical_request_hash=canonical_request_hash,
                protocol_status=protocol_status,
                error_code=error_code,
                error_owner=error_owner,
                validation_summary=validation_summary,
            )

        diagnostic = store.finalize_diagnostic_projection({
            **response_artifact,
            "raw_response": raw_response,
        })
        graph_attempt = next(
            (
                item for item in protocol().get("attempts", []) or []
                if str((item or {}).get("attempt_id") or "") == attempt_id
            ),
            None,
        )
        if not isinstance(graph_attempt, Mapping) or not str(graph_attempt.get("response_artifact_ref") or ""):
            try:
                current_consultation = commit_finalize_decision(
                    current_consultation,
                    {
                        "transition": "provider_response",
                        "attempt_id": attempt_id,
                        "call_id": call_id,
                        "canonical_request_hash": canonical_request_hash,
                        "response_artifact_ref": str(response_artifact.get("response_artifact_ref") or ""),
                        "response_content_hash": str(response_artifact.get("response_content_hash") or ""),
                        "response_excerpt": diagnostic.get("response_excerpt") or "",
                        "response_excerpt_truncated": bool(diagnostic.get("response_excerpt_truncated")),
                    },
                )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=f"Protected response pointer commit failed: {type(exc).__name__}: {exc}",
                )
        if str(protocol().get("status") or "") in {
            "blocked_internal_contract", "blocked_internal_provider"
        }:
            error_code = str(protocol().get("terminal_error_code") or "FINALIZE_IDENTICAL_RESPONSE_LOOP")
            error_owner = str(protocol().get("terminal_owner") or "controller_model_protocol")
            try:
                persist_protocol_outcome_once(
                    protocol_status="blocked",
                    error_code=error_code,
                    error_owner=error_owner,
                    validation_summary={"identical_response_detected": True},
                )
            except Exception as exc:
                logger.warning("Could not record identical-response outcome: %s", exc)
            return terminal_update(
                error_code=error_code,
                error_owner=error_owner,
                detail="A repair returned a response content hash already seen in this context.",
            )

        if message_kind == "field_repair":
            immutable_base = deepcopy(dict(repair.get("base_payload") or {}))
            patch_result = validate_field_patch(
                (
                    structured_object
                    if isinstance(structured_object, Mapping)
                    else raw_response
                ),
                finalize_context=finalize_context,
                base_payload=immutable_base,
                allowed_fields_by_index=repair.get("allowed_fields_by_index") or {},
                allowed_payload_fields=repair.get("allowed_payload_fields") or [],
                validation_errors=repair.get("validation_errors") or [],
            )
            if patch_result.get("valid"):
                repaired_payload = deepcopy(dict(patch_result.get("payload") or {}))
                repaired_wire = json.dumps(
                    repaired_payload,
                    ensure_ascii=False,
                    sort_keys=True,
                    separators=(",", ":"),
                    default=str,
                )
                result = parse_finalize_response(
                    repaired_wire,
                    finalize_context=finalize_context,
                    allow_compatibility=False,
                    provider_status="succeeded",
                )
                # Loop identity and observability always bind to the exact
                # provider response, not the controller-rendered merged payload.
                result["response_content_hash"] = str(
                    response_artifact.get("response_content_hash") or ""
                )
                result["raw_response"] = raw_response
                if not result.get("valid"):
                    result["parsed_payload"] = repaired_payload
            else:
                result = dict(patch_result)
                result["response_content_hash"] = str(
                    response_artifact.get("response_content_hash") or ""
                )
                result["raw_response"] = raw_response
                # A rejected patch is atomic. The next attempt is bound to the
                # unchanged base, never to the invalid repair envelope.
                result["parsed_payload"] = immutable_base
        else:
            result = parse_finalize_response(
                raw_response,
                finalize_context=finalize_context,
                structured_object=(
                    structured_object if isinstance(structured_object, Mapping) else None
                ),
                allow_compatibility=historical_legacy_migration,
                provider_status="succeeded",
            )
            result["response_content_hash"] = str(
                response_artifact.get("response_content_hash") or ""
            )

        current_attempts = [
            dict(item)
            for item in protocol().get("attempts", []) or []
            if isinstance(item, Mapping)
        ]
        previous_response_hashes = [
            str(item.get("response_content_hash") or "")
            for item in current_attempts
            if str(item.get("attempt_id") or "") != attempt_id
            and str(item.get("response_content_hash") or "")
        ]
        active_repair = dict(protocol().get("repair") or {})
        decision = propose_finalize_decision(
            result,
            call_kind=message_kind,
            wire_repair_attempt=int(active_repair.get("wire_repair_attempt") or 0),
            max_wire_repair_attempts=int(active_repair.get("max_wire_repair_attempts") or 2),
            field_repair_attempt=int(active_repair.get("field_repair_attempt") or 0),
            max_field_repair_attempts=int(active_repair.get("max_field_repair_attempts") or 2),
            previous_response_hashes=previous_response_hashes,
            provider_retry_attempt=(1 if transport_retry else 0),
            response_artifact_exists=True,
        )

        # A pre-existing, controller-validated ambiguity remains authoritative
        # even if the model incorrectly returns finish instead of ask.
        if (
            str(decision.get("decision") or "") == "compile"
            and list(context_value.get("unresolved_semantics") or [])
        ):
            ambiguity = deepcopy(dict(context_value["unresolved_semantics"][0]))
            decision = {
                "decision": "needs_user",
                "next_step": "ask_user",
                "finalize_status": "needs_user",
                "protocol_status": "needs_user",
                "error_code": "FINALIZE_SEMANTIC_AMBIGUITY",
                "error_owner": "user_semantic",
                "clear_pending_human_question": False,
                "ambiguity": ambiguity,
                "deterministic_question_required": True,
                "repair_kind": "none",
            }

        validation_errors = [
            deepcopy(dict(item))
            for item in result.get("errors", []) or []
            if isinstance(item, Mapping)
        ]
        for error in validation_errors:
            try:
                error["index"] = int(error.get("index", -1))
            except (TypeError, ValueError):
                error["index"] = -1
            if not str(error.get("field") or "").strip():
                path = str(error.get("path") or "")
                if path.startswith("$."):
                    error["field"] = (
                        path[2:].split("[", 1)[0].split(".", 1)[0].strip()
                    )
        preserve_permissions = bool(
            message_kind == "field_repair"
            and str(result.get("error_code") or "") == "FINALIZE_PATCH_PROTOCOL_INVALID"
        )
        allowed_by_index, allowed_payload, errors_by_field = (
            self._consultant_finalize_patch_permissions(
                validation_errors,
                previous_allowed_fields_by_index=active_repair.get("allowed_fields_by_index") or {},
                previous_allowed_payload_fields=active_repair.get("allowed_payload_fields") or [],
                preserve_previous=preserve_permissions,
            )
        )
        parsed_base = result.get("parsed_payload")
        if preserve_permissions:
            parsed_base = deepcopy(dict(active_repair.get("base_payload") or {}))

        decision_name = str(decision.get("decision") or "")
        if decision_name == "compile":
            payload = deepcopy(dict(decision.get("payload") or result.get("payload") or {}))
            deterministic_base = [
                deepcopy(dict(item))
                for item in context_value.get("deterministic_base_constraints", []) or []
                if isinstance(item, Mapping)
            ]
            semantic_delta = [
                deepcopy(dict(item))
                for item in payload.get("semantic_constraints", []) or []
                if isinstance(item, Mapping)
            ]
            semantic_metrics = {
                "schema_validation": "passed",
                "deterministic_base_constraint_count": len(deterministic_base),
                "consultant_semantic_delta_count": len(semantic_delta),
                "provider_status": "succeeded",
                "protocol_status": "valid",
                "response_reused_from_checkpoint": response_reused,
            }
            coverage_internal_exception = False
            try:
                compiled_task_spec = apply_task_spec_mutation_proposal(
                    current_task_spec,
                    constraint_mutation_proposal(
                        [*deterministic_base, *semantic_delta]
                    ),
                    project_root=project_root,
                )
                selected_constraints = semantic_constraints_from_task_spec(
                    compiled_task_spec,
                    selected_skill_ids=resolved_selected_skill_ids,
                )
                compiled_task_spec = merge_compiled_constraints(
                    compiled_task_spec,
                    selected_constraints,
                    project_root=project_root,
                    metrics=semantic_metrics,
                )
                final_constraints = semantic_constraints_from_task_spec(
                    compiled_task_spec,
                    selected_skill_ids=resolved_selected_skill_ids,
                )
                coverage = finalize_coverage_audit(
                    finalize_context,
                    {
                        "selected_skills": list(resolved_selected_skill_ids),
                        "semantic_constraints": final_constraints,
                    },
                )
            except Exception as exc:
                coverage_internal_exception = True
                coverage = {
                    "valid": False,
                    "errors": [{
                        "path": "$",
                        "reason": f"controller merge failed: {type(exc).__name__}: {exc}",
                    }],
                }
                compiled_task_spec = current_task_spec
                final_constraints = []
            if not coverage.get("valid"):
                audit_errors = [
                    deepcopy(dict(item))
                    for item in coverage.get("errors", []) or []
                    if isinstance(item, Mapping)
                ]
                if coverage_internal_exception:
                    return terminal_update(
                        error_code="FINALIZE_REPAIR_EXHAUSTED",
                        error_owner="controller",
                        detail="Controller merge failed before coverage could be evaluated.",
                    )
                for error in audit_errors:
                    try:
                        error["index"] = int(error.get("index", -1))
                    except (TypeError, ValueError):
                        error["index"] = -1
                    if not str(error.get("field") or "").strip():
                        path = str(error.get("path") or "")
                        if path.startswith("$."):
                            error["field"] = (
                                path[2:].split("[", 1)[0].split(".", 1)[0].strip()
                            )
                (
                    coverage_allowed_by_index,
                    coverage_allowed_payload,
                    coverage_errors_by_field,
                ) = self._consultant_finalize_patch_permissions(audit_errors)
                if not coverage_allowed_by_index and not coverage_allowed_payload:
                    return terminal_update(
                        error_code="FINALIZE_REPAIR_EXHAUSTED",
                        error_owner="controller",
                        detail="Coverage audit failed without a model-owned patchable field.",
                    )
                try:
                    persist_protocol_outcome_once(
                        protocol_status="field_invalid",
                        error_code="FINALIZE_SCHEMA_INVALID",
                        error_owner="controller_model_protocol",
                        validation_summary={
                            "coverage_audit": coverage,
                            "response_reused_from_checkpoint": response_reused,
                        },
                    )
                    current_consultation = commit_finalize_decision(
                        current_consultation,
                        {
                            "transition": "protocol_validation",
                            "attempt_id": attempt_id,
                            "protocol_status": "field_invalid",
                            "error_code": "FINALIZE_SCHEMA_INVALID",
                            "error_owner": "controller_model_protocol",
                            "validation_errors": audit_errors,
                            "errors_by_field": coverage_errors_by_field,
                            "allowed_fields_by_index": coverage_allowed_by_index,
                            "allowed_payload_fields": coverage_allowed_payload,
                            "parsed_payload": payload,
                            "payload_hash": finalize_payload_hash(payload),
                        },
                    )
                except Exception as exc:
                    return terminal_update(
                        error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        error_owner="controller_storage",
                        detail=f"Could not commit finalize coverage repair: {type(exc).__name__}: {exc}",
                    )
                current_consultation.update({
                    "phase": "finalize",
                    "consultation_status": "ready",
                    "completion_decision": "ready_to_finalize",
                    "completion_reason": "field_invalid_repair_pending",
                    "resolved_selected_skill_ids": list(resolved_selected_skill_ids),
                })
                return {
                    "messages": [SystemMessage(content=(
                        "<consultant_finalize_protocol_error>\n"
                        + json.dumps({
                            "error_code": "FINALIZE_SCHEMA_INVALID",
                            "error_owner": "controller_model_protocol",
                            "protocol_status": "field_invalid",
                            "repair_kind": "field_patch",
                            "coverage_audit_failed": True,
                            "response_artifact_ref": str(response_artifact.get("response_artifact_ref") or ""),
                            "response_content_hash": str(response_artifact.get("response_content_hash") or ""),
                        }, ensure_ascii=False, sort_keys=True)
                        + "\n</consultant_finalize_protocol_error>"
                    ))],
                    "input_audit": deepcopy(dict(input_audit or {})),
                    "task_spec": current_task_spec,
                    "task_revision": task_spec_revision(current_task_spec),
                    "consultation_state": current_consultation,
                    "consultant_contract_repair": finalize_repair_projection(current_consultation),
                    "pending_human_question": {},
                    "consultant_constraint_metrics": {
                        **semantic_metrics,
                        "schema_validation": "failed",
                        "protocol_status": "field_invalid",
                        "error_code": "FINALIZE_SCHEMA_INVALID",
                        "coverage_audit": coverage,
                    },
                    "contract_status": "semantic_schema_retry",
                    "next_step": "consultant",
                }

            try:
                runtime_audits, runtime_summary = self._consultant_runtime_preflight(
                    list(resolved_selected_skill_ids),
                    task_id,
                )
                summary = str(payload.get("summary") or "").strip()
                if runtime_summary:
                    summary = (summary.rstrip() + "\n\n" + runtime_summary).strip()
                final_contract = {
                    "intent": str(compiled_task_spec.get("goal") or ""),
                    "selected_skills": list(resolved_selected_skill_ids),
                    "summary": summary,
                    "constraints": final_constraints,
                    "verified_evidence": [
                        deepcopy(dict(item))
                        for item in (current_consultation.get("requirements") or {}).values()
                        if isinstance(item, Mapping) and item.get("status") == "satisfied"
                    ],
                    "remaining_uncertainty": [],
                    "required_capabilities": list(resolved_selected_skill_ids),
                    "input_status": str(input_audit.get("status") or "not_applicable"),
                    "runtime_status": runtime_audits,
                    "semantic_constraint_count": len(final_constraints),
                    "task_spec_revision": task_spec_revision(compiled_task_spec),
                    "finalize_context_id": context_id,
                    "base_contract_hash": base_contract_hash,
                    "canonical_request_hash": canonical_request_hash,
                    "response_content_hash": str(response_artifact.get("response_content_hash") or ""),
                    "response_artifact_ref": str(response_artifact.get("response_artifact_ref") or ""),
                    "response_reused_from_checkpoint": response_reused,
                    "coverage_audit": coverage,
                }
                compiled_contract_hash = canonical_compiled_contract_hash(
                    final_contract
                )
                final_contract["compiled_contract_hash"] = compiled_contract_hash
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_REPAIR_EXHAUSTED",
                    error_owner="controller",
                    detail=(
                        "Compiled final-contract construction failed before durable commit: "
                        f"{type(exc).__name__}: {exc}"
                    ),
                )

            try:
                persist_protocol_outcome_once(
                    protocol_status="valid",
                    validation_summary={
                        "coverage_audit": coverage,
                        "constraint_count": len(final_constraints),
                        "compiled_contract_hash": compiled_contract_hash,
                        "response_reused_from_checkpoint": response_reused,
                    },
                )
                current_consultation = commit_finalize_decision(
                    current_consultation,
                    {
                        "transition": "protocol_validation",
                        "attempt_id": attempt_id,
                        "protocol_status": "valid",
                        "error_code": "",
                        "error_owner": "",
                        "validation_errors": [],
                        "errors_by_field": {},
                        "allowed_fields_by_index": {},
                        "allowed_payload_fields": [],
                        "parsed_payload": payload,
                        "payload_hash": finalize_payload_hash(payload),
                    },
                )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=f"Finalize success commit failed: {type(exc).__name__}: {exc}",
                )
            try:
                current_consultation = commit_finalize_decision(
                    current_consultation,
                    {
                        "transition": "compiled",
                        "finalize_context_id": context_id,
                        "base_contract_hash": base_contract_hash,
                    },
                )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_REPAIR_EXHAUSTED",
                    error_owner="controller",
                    detail=f"Compiled finalize transition failed: {type(exc).__name__}: {exc}",
                )
            current_consultation.update({
                "phase": "finalize",
                "consultation_status": "completed",
                "completion_decision": "ready_to_finalize",
                "completion_reason": "formal_contract_compiled_v2",
                "resolved_selected_skill_ids": list(resolved_selected_skill_ids),
                "final_contract": final_contract,
            })
            output.print_once(
                f"consultant_finalize_v2:{task_id}",
                "✓ Consultant FINALIZE v2 compiled a hash-bound semantic contract.",
                Fore.GREEN,
            )
            return {
                "messages": [AIMessage(content="FINISH\n" + summary)],
                "input_audit": deepcopy(dict(input_audit or {})),
                "selected_skills": list(resolved_selected_skill_ids),
                "selected_skills_raw": list(resolved_selected_skill_ids),
                "active_skills": list(resolved_selected_skill_ids),
                "future_skills": [],
                "required_skills_all": list(resolved_selected_skill_ids),
                "candidate_skills": [],
                "runtime_status": self._runtime_status_for_task(
                    task_id,
                    list(resolved_selected_skill_ids),
                ),
                "runtime_audit": runtime_audits,
                "skill_selection_source": "consultation_controller_finalize_v2",
                "requirements_summary": summary,
                "task_spec": compiled_task_spec,
                "task_revision": task_spec_revision(compiled_task_spec),
                "consultant_constraint_metrics": semantic_metrics,
                "consultation_state": current_consultation,
                "consultant_contract_repair": finalize_repair_projection(current_consultation),
                "pending_human_question": {},
                "contract_status": "semantic_contract_compiled",
                "memory_packet_context": self._consultant_handoff_memory_packet(
                    summary,
                    consultant_memory_retrieval_context,
                ),
                "wiki_memory_context": consultant_wiki_context,
                "next_step": "planner",
            }

        if decision_name in {"needs_user", "register_ambiguity"}:
            ambiguity = decision.get("ambiguity")
            if not isinstance(ambiguity, Mapping):
                return terminal_update(
                    error_code="FINALIZE_UNAUTHORIZED_ASK",
                    error_owner="controller_model_protocol",
                    detail="User routing was proposed without one validated ambiguity record.",
                )
            ambiguity_record = deepcopy(dict(ambiguity))
            ambiguity_id = str(
                ambiguity_record.get("constraint_id")
                or ambiguity_record.get("requirement_id")
                or ""
            ).strip()
            question = self._consultant_finalize_ambiguity_question(ambiguity_record)
            pending_question = {
                "type": "semantic_constraint_clarification_v2",
                "stage": "consultant",
                "question": question,
                "ambiguity_id": ambiguity_id,
                "finalize_context_id": context_id,
                "base_contract_hash": base_contract_hash,
                "task_spec_revision": task_spec_revision(current_task_spec),
                "resume_step": "consultant",
            }
            try:
                persist_protocol_outcome_once(
                    protocol_status="needs_user",
                    error_code="FINALIZE_SEMANTIC_AMBIGUITY",
                    error_owner="user_semantic",
                    validation_summary={
                        "ambiguity_id": ambiguity_id,
                        "response_reused_from_checkpoint": response_reused,
                    },
                )
                current_consultation = commit_finalize_decision(
                    current_consultation,
                    {
                        "transition": "protocol_validation",
                        "attempt_id": attempt_id,
                        "protocol_status": "needs_user",
                        "error_code": "FINALIZE_SEMANTIC_AMBIGUITY",
                        "error_owner": "user_semantic",
                        "validation_errors": [],
                        "errors_by_field": {},
                        "allowed_fields_by_index": {},
                        "allowed_payload_fields": [],
                        "parsed_payload": (
                            deepcopy(dict(result.get("parsed_payload")))
                            if isinstance(result.get("parsed_payload"), Mapping)
                            else None
                        ),
                    },
                )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=f"Ambiguity outcome commit failed: {type(exc).__name__}: {exc}",
                )

            updated_task_spec = current_task_spec
            try:
                if decision_name == "register_ambiguity":
                    updated_task_spec = register_validated_semantic_ambiguity(
                        current_task_spec,
                        ambiguity_record,
                        provenance_catalog=context_value.get("semantic_provenance_catalog") or [],
                    )
                    ambiguity_id = str(
                        ambiguity_record.get("constraint_id")
                        or ambiguity_record.get("requirement_id")
                        or ambiguity_id
                    ).strip()
                    pending_question["ambiguity_id"] = ambiguity_id
                    pending_question["task_spec_revision"] = task_spec_revision(
                        updated_task_spec
                    )
                    current_consultation = commit_finalize_decision(
                        current_consultation,
                        {
                            "transition": "supersede",
                            "task_spec_revision": task_spec_revision(updated_task_spec),
                            "ambiguity_id": ambiguity_id,
                            "pending_human_question": pending_question,
                        },
                    )
                else:
                    current_consultation = commit_finalize_decision(
                        current_consultation,
                        {
                            "transition": "needs_user",
                            "ambiguity_id": ambiguity_id,
                            "ambiguity_ids": [ambiguity_id],
                            "context_unresolved_semantic_ids": list(
                                context_value.get("unresolved_semantic_ids") or []
                            ),
                            "pending_human_question": pending_question,
                        },
                    )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_UNAUTHORIZED_ASK",
                    error_owner="controller_model_protocol",
                    detail=f"Validated ambiguity transition failed: {type(exc).__name__}: {exc}",
                )
            current_consultation.update({
                "phase": "needs_user",
                "consultation_status": "needs_user",
                "completion_decision": "needs_user",
                "completion_reason": "validated_semantic_ambiguity",
            })
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_semantic_resolution_request>\n"
                    + json.dumps({
                        "ambiguity_id": ambiguity_id,
                        "semantic_key": ambiguity_record.get("semantic_key"),
                        "unresolved_reason": ambiguity_record.get("unresolved_reason"),
                    }, ensure_ascii=False, sort_keys=True)
                    + "\n</consultant_semantic_resolution_request>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": updated_task_spec,
                "task_revision": task_spec_revision(updated_task_spec),
                "consultation_state": current_consultation,
                "consultant_contract_repair": finalize_repair_projection(current_consultation),
                "pending_human_question": pending_question,
                "consultant_constraint_metrics": {
                    "schema_validation": "passed",
                    "error_code": "FINALIZE_SEMANTIC_AMBIGUITY",
                    "error_owner": "user_semantic",
                    "response_reused_from_checkpoint": response_reused,
                },
                "contract_status": "blocked_need_user_decision",
                "next_step": "ask_user",
            }

        if decision_name in {"wire_repair", "field_patch", "block_internal"}:
            protocol_status = (
                "wire_invalid"
                if decision_name == "wire_repair"
                else "field_invalid"
                if decision_name == "field_patch"
                else "blocked"
            )
            error_code = str(
                decision.get("error_code")
                or result.get("error_code")
                or "FINALIZE_REPAIR_EXHAUSTED"
            )
            error_owner = str(
                decision.get("error_owner")
                or result.get("error_owner")
                or "controller_model_protocol"
            )
            validation_transition: Dict[str, Any] = {
                "transition": "protocol_validation",
                "attempt_id": attempt_id,
                "protocol_status": protocol_status,
                "error_code": error_code,
                "error_owner": error_owner,
                "validation_errors": validation_errors,
                "errors_by_field": errors_by_field,
                "allowed_fields_by_index": allowed_by_index,
                "allowed_payload_fields": allowed_payload,
            }
            if preserve_permissions:
                validation_transition.update({
                    "preserve_patch_targets": True,
                    "patch_protocol_errors": validation_errors,
                })
            if isinstance(parsed_base, Mapping):
                validation_transition["parsed_payload"] = deepcopy(dict(parsed_base))
                validation_transition["payload_hash"] = finalize_payload_hash(parsed_base)
            try:
                persist_protocol_outcome_once(
                    protocol_status=protocol_status,
                    error_code=error_code,
                    error_owner=error_owner,
                    validation_summary={
                        "errors": validation_errors,
                        "errors_by_field": errors_by_field,
                        "response_reused_from_checkpoint": response_reused,
                    },
                )
                current_consultation = commit_finalize_decision(
                    current_consultation,
                    validation_transition,
                )
            except Exception as exc:
                return terminal_update(
                    error_code="FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                    error_owner="controller_storage",
                    detail=f"Finalize protocol outcome commit failed: {type(exc).__name__}: {exc}",
                )
            if decision_name == "block_internal":
                return terminal_update(
                    error_code=error_code,
                    error_owner=error_owner,
                    detail="Finalize repair budget or typed loop guard reached a terminal state.",
                    provider_block=error_owner in {"provider", "controller_provider"},
                )
            current_consultation.update({
                "phase": "finalize",
                "consultation_status": "ready",
                "completion_decision": "ready_to_finalize",
                "completion_reason": f"{protocol_status}_repair_pending",
                "resolved_selected_skill_ids": list(resolved_selected_skill_ids),
            })
            feedback = {
                "error_code": error_code,
                "error_owner": error_owner,
                "protocol_status": protocol_status,
                "repair_kind": str(protocol().get("repair", {}).get("repair_kind") or "none"),
                "wire_repair_attempt": int(protocol().get("repair", {}).get("wire_repair_attempt") or 0),
                "field_repair_attempt": int(protocol().get("repair", {}).get("field_repair_attempt") or 0),
                "response_artifact_ref": str(response_artifact.get("response_artifact_ref") or ""),
                "response_content_hash": str(response_artifact.get("response_content_hash") or ""),
            }
            return {
                "messages": [SystemMessage(content=(
                    "<consultant_finalize_protocol_error>\n"
                    + json.dumps(feedback, ensure_ascii=False, sort_keys=True)
                    + "\n</consultant_finalize_protocol_error>"
                ))],
                "input_audit": deepcopy(dict(input_audit or {})),
                "task_spec": current_task_spec,
                "task_revision": task_spec_revision(current_task_spec),
                "consultation_state": current_consultation,
                "consultant_contract_repair": finalize_repair_projection(current_consultation),
                "pending_human_question": {},
                "consultant_constraint_metrics": {
                    "schema_validation": "failed",
                    "provider_status": "succeeded",
                    "protocol_status": protocol_status,
                    "error_code": error_code,
                    "error_owner": error_owner,
                    "response_reused_from_checkpoint": response_reused,
                },
                "contract_status": "semantic_schema_retry",
                "next_step": "consultant",
            }

        return terminal_update(
            error_code="FINALIZE_REPAIR_EXHAUSTED",
            error_owner="controller",
            detail=f"Unsupported finalize controller decision: {decision_name or 'empty'}.",
        )

    # ────────────────────────────────────────────────────────────
    #  图构建
    # ────────────────────────────────────────────────────────────

    def _build_graph(self):
        workflow = StateGraph(AgentState)

        # ════════════════════════════════════════════
        # Node -1: Triage（轻量四分类路由）
        # ════════════════════════════════════════════
        async def triage(state: AgentState):
            output.print_node_header("triage")
            messages = state.get("messages", [])
            task_id = state.get("task_id", "default")

            resume_node = str(state.get("resolved_resume_node") or "").strip()
            if str(state.get("resume_mode") or "") == "business_state" and resume_node:
                audit = state.get("resume_audit") or {}
                durable_resume = load_plan_state(self.data_path, task_id)
                durable_admission = dict(
                    (durable_resume.get("task_state") or {}).get("intent_admission")
                    or state.get("intent_admission")
                    or {}
                )
                output.print_once(
                    f"resume_route:{task_id}:{resume_node}",
                    f"↪ Resume router: {resume_node} | {audit.get('resume_reason', 'durable business state')}",
                    Fore.CYAN,
                )
                return {
                    "task_mode": str(state.get("task_mode") or "managed"),
                    "retrieval_mode": str(state.get("retrieval_mode") or "kb"),
                    "use_scientific_review": True,
                    "validation_level": str(state.get("validation_level") or "scientific"),
                    "intent_admission": durable_admission,
                    "request_intent": dict(state.get("request_intent") or durable_admission),
                    "managed_intent_admitted": (
                        managed_execution_admitted(durable_admission)
                        or task_spec_is_initialized(canonical_task_spec_for_state(durable_resume))
                    ),
                    "next_step": resume_node,
                }

            conversation_turns, _ = self._consultant_semantic_conversation(
                task_id,
                messages,
            )
            user_text = "\n\n".join(
                str(turn.get("content") or "").strip()
                for turn in conversation_turns
                if str(turn.get("role") or "") == "user"
                and str(turn.get("content") or "").strip()
            )

            decision = await classify_task_mode(self.llm,
                user_text,
                data_path=self.data_path,
                task_id=task_id,
                trace_metadata={
                    "task_revision": self._task_revision_for_state(dict(state)),
                    "task_spec_revision": self._task_revision_for_state(dict(state)),
                    "effective_facts_revision": str(state.get("effective_user_facts_revision") or ""),
                    "user_source_refs": list(state.get("user_source_refs") or []),
                },
            )
            mode = str(decision.get("task_mode") or "chat").strip().lower()
            if mode not in {"chat", "readonly", "simple_execute", "managed"}:
                mode = "chat"
            retrieval_mode = str(decision.get("retrieval_mode") or "none").strip().lower()
            request_intent = {
                key: deepcopy(decision.get(key))
                for key in (
                    "schema_version", "request_kind", "execution_scope",
                    "managed_intent_explicit", "task_mode", "retrieval_mode",
                    "confidence", "admission_status", "consultation_required",
                    "reason", "llm_call_ref",
                )
                if decision.get(key) is not None
            }
            intent_admission = {
                **request_intent,
                "decision_source": "llm_request_intent_router",
                "task_id": task_id,
                "admission_id": "intent-admission-" + self._finalize_digest({
                    key: value
                    for key, value in request_intent.items()
                    if key != "llm_call_ref"
                })[:20],
                "decided_at": timestamp_now(),
            }
            if mode in {"readonly", "simple_execute", "managed"} or bool(
                decision.get("consultation_required")
            ):
                durable_intent_state = load_plan_state(self.data_path, task_id)
                durable_task_state = dict(durable_intent_state.get("task_state") or {})
                durable_task_state["intent_admission"] = deepcopy(intent_admission)
                durable_intent_state["task_state"] = durable_task_state
                save_plan_state(self.data_path, task_id, durable_intent_state)

            validation_by_mode = {
                "chat": "none",
                "readonly": "basic",
                "simple_execute": "basic",
                "managed": "scientific",
            }
            next_by_mode = {
                "chat": "direct_chat",
                "readonly": "generate",
                "simple_execute": "generate",
                "managed": "consultant",
            }
            next_step = (
                "consultant"
                if bool(decision.get("consultation_required"))
                else next_by_mode.get(mode, "consultant")
            )
            update = {
                "task_mode": mode,
                "retrieval_mode": retrieval_mode,
                "request_intent": request_intent,
                "intent_admission": intent_admission,
                "managed_intent_admitted": managed_execution_admitted(intent_admission),
                "use_scientific_review": mode == "managed",
                "validation_level": validation_by_mode.get(mode, "none"),
                "next_step": next_step,
            }
            if decision.get("llm_call_ref"):
                update["llm_call_refs"] = [dict(decision["llm_call_ref"])]
                update["context_lineage_ref"] = str(
                    Path(self.data_path) / "task_outputs" / task_id / "context_trace"
                )
            output.print_once(
                f"triage:{task_id}",
                (
                    f"↪ Router: {mode}"
                    f" | kind={decision.get('request_kind', 'question')}"
                    f" | scope={decision.get('execution_scope', 'none')}"
                    f" | retrieval={retrieval_mode}"
                    f" | confidence={decision.get('confidence', 0):.2f}"
                    f" | {decision.get('reason', '')}"
                ),
                Fore.CYAN,
            )
            return update

        # ════════════════════════════════════════════
        # Node -0.5: Direct Chat（轻量知识问答）
        # ════════════════════════════════════════════
        async def direct_chat(state: AgentState):
            output.print_node_header("direct_chat")
            messages = state.get("messages", [])
            task_id = state.get("task_id", "default")
            project_id = state.get("project_id") or self.default_project_id
            query = "\n".join(
                str(m.content) for m in messages if isinstance(m, HumanMessage)
            ).strip()
            retrieval_mode = str(state.get("retrieval_mode") or "none").strip().lower()
            request_kind = str(
                (state.get("request_intent") or {}).get("request_kind") or "question"
            ).strip().lower()

            context_parts = []
            if retrieval_mode in {"kb", "skill_docs"}:
                wiki_context = self._wiki_memory_stage_context(
                    task_id=task_id,
                    project_id=project_id,
                    query=query,
                    digest_chars=1200,
                    context_chars=2400,
                )
                if wiki_context:
                    context_parts.append(wiki_context)
                if self.retriever and KB_MAP.get("SOP"):
                    try:
                        rag_result = self.retriever.retrieve(query, target_datasets=[KB_MAP["SOP"]])
                        if rag_result and str(rag_result).strip() and "Nothing found" not in str(rag_result):
                            context_parts.append(f"<kb_context>\n{str(rag_result)[:3000]}\n</kb_context>")
                    except Exception as exc:
                        logger.warning("Direct chat KB retrieval failed: %s", exc)

            if retrieval_mode == "skill_docs" and self.skill_manager:
                try:
                    matched = self.skill_manager.match_skills(query, max_results=2)
                    if matched:
                        skill_docs = self.skill_manager.load_skills_for_prompt(matched)
                        if skill_docs:
                            context_parts.append(
                                "<skill_docs_readonly>\n"
                                f"{skill_docs[:5000]}\n"
                                "</skill_docs_readonly>"
                            )
                except Exception as exc:
                    logger.warning("Direct chat skill-doc retrieval failed: %s", exc)

            context = "\n\n".join(context_parts) if context_parts else "No retrieved context."
            response_contract = (
                "Provide an advisory, reviewable plan, but do not execute it or create an executable TaskSpec."
                if request_kind == "plan"
                else "Answer the user's question directly."
            )
            prompt = f"""You are BioMind's non-executable response node.

{response_contract}
Be direct and concise.
You may use the read-only context below.
Do not execute commands, install tools, mutate files, create an executable TaskSpec,
or emit XML action tags such as <execute>, <install_tool>, <search>, or <activate_batch>.
If the user is actually asking you to run analysis or inspect local files, say that it should be handled outside chat mode.

<read_only_context>
{context}
</read_only_context>
"""
            try:
                response = await self._ainvoke_llm(
                    [SystemMessage(content=prompt)] + messages,
                    stage="direct_chat",
                    task_id=task_id,
                    task_mode="chat",
                )
            except Exception as exc:
                response = self._llm_failure_response("direct_chat", exc, task_id)

            content = str(response.content or "").strip()
            if re.search(r"<\s*(execute|install_tool|search|activate_batch|ask_user)\b", content, re.IGNORECASE):
                content = (
                    "这个问题不能在 chat 模式里执行动作。请把需求改成明确的只读检查、"
                    "简单执行，或者交给 managed 流程处理。"
                )
                response = AIMessage(content=content)
            output.print_ai(content)
            await self._finalize_task_memory(
                task_id,
                "completed",
                messages + [response],
                {"task_mode": "chat", "retrieval_mode": retrieval_mode, "solution": content[:3000]},
            )
            return {"messages": [response], "next_step": "finish"}

        # ════════════════════════════════════════════
        # Node 0: Consultant
        # ════════════════════════════════════════════
        async def consultant(state: AgentState):
            output.print_node_header("consultant")
            messages = state["messages"]
            rag_history = state.get("rag_history", [])
            task_id = state.get("task_id", "default")

            durable_consultant_state = load_plan_state(self.data_path, task_id)
            pending_impact_question = dict(
                (durable_consultant_state.get("task_state") or {}).get(
                    "pending_plan_impact_review"
                ) or {}
            )
            if (
                str(pending_impact_question.get("status") or "")
                == "waiting_user"
            ):
                return {
                    "messages": [SystemMessage(content=(
                        "Consultant is routing the Planner-owned semantic gap "
                        "to the user without answering it on Planner's behalf."
                    ))],
                    "pending_human_question": {
                        "type": "plan_impact_review",
                        "stage": "consultant",
                        "question": str(
                            pending_impact_question.get("question") or ""
                        ),
                        "requested_slots": list(
                            pending_impact_question.get("requested_slots") or []
                        ),
                        "resume_step": "planner",
                        "owner": "user",
                    },
                    "next_step": "ask_user",
                }
            pending_skill_proposal = dict(
                (durable_consultant_state.get("task_state") or {}).get(
                    "pending_skill_binding_proposal"
                )
                or {}
            )
            pending_proposal_status = str(
                pending_skill_proposal.get("status") or ""
            )
            if pending_proposal_status == "approved_for_plan_impact":
                return {
                    "messages": [SystemMessage(content=(
                        "The reviewed step-scoped Skill proposal belongs to "
                        "Planner plan-impact review."
                    ))],
                    "pending_action": {},
                    "next_step": "planner",
                }
            if (
                pending_skill_proposal
                and pending_proposal_status != "approved_for_task_commit"
            ):
                try:
                    return await self._run_consultant_skill_resolution(
                        state,
                        task_id=task_id,
                        durable=durable_consultant_state,
                        proposal=pending_skill_proposal,
                    )
                except StateCASConflict as exc:
                    return self._skill_access_cas_stale_update(
                        caller_node="consultant",
                        next_step="consultant",
                        detail=str(exc),
                    )
                except SkillAccessError as exc:
                    return {
                        "messages": [SystemMessage(content=json.dumps(
                            exc.to_dict(), ensure_ascii=False, sort_keys=True,
                        ))],
                        "skill_decision_result": exc.to_dict(),
                        "pending_action": {},
                        "next_step": "consultant",
                    }
            pending_task_skill_change = (
                deepcopy(pending_skill_proposal)
                if pending_proposal_status == "approved_for_task_commit"
                else {}
            )
            pending_task_skill_context: Dict[str, Any] = {}
            if pending_task_skill_change:
                try:
                    pending_access = normalize_skill_access_state(
                        (durable_consultant_state.get("task_state") or {}).get(
                            "skill_access_state"
                        )
                        or durable_consultant_state.get("skill_access_state")
                    )
                    pending_snapshot = SkillAccessService._verified_snapshot(
                        pending_access,
                        str(
                            pending_task_skill_change.get(
                                "candidate_snapshot_id"
                            )
                            or ""
                        ),
                    )
                    pending_excerpt_ids = {
                        str(item)
                        for item in (
                            pending_task_skill_change.get(
                                "verified_excerpt_refs"
                            )
                            or pending_task_skill_change.get("evidence_refs")
                            or []
                        )
                        if str(item) in (pending_access.get("excerpts") or {})
                    }
                    pending_excerpts = [
                        SkillAccessService._verified_excerpt(
                            pending_access, excerpt_id
                        )
                        for excerpt_id in sorted(pending_excerpt_ids)
                    ]
                    pending_task_skill_context = {
                        "candidate_skill_id": str(
                            pending_snapshot.get("skill_id") or ""
                        ),
                        "candidate_snapshot_id": str(
                            pending_snapshot.get("snapshot_id") or ""
                        ),
                        "content_hash": str(
                            pending_snapshot.get("content_hash") or ""
                        ),
                        "requested_scope": str(
                            pending_task_skill_change.get("requested_scope")
                            or ""
                        ),
                        "relation": str(
                            pending_task_skill_change.get("relation") or ""
                        ),
                        "justification": str(
                            pending_task_skill_change.get("justification") or ""
                        ),
                        "consultant_review": deepcopy(dict(
                            pending_task_skill_change.get("review") or {}
                        )),
                        "available_headings": deepcopy(list(
                            pending_snapshot.get("heading_index") or []
                        )),
                        "relevant_skill_excerpts": pending_excerpts,
                        "required_transaction": (
                            "Interpret the authoritative user evidence in the "
                            "normal TaskSpec candidate flow. If it truly changes "
                            "task method/capability semantics, commit the typed "
                            "TaskSpec operations and select this reviewed "
                            "candidate together. Do not merely echo a Skill ID."
                        ),
                    }
                except SkillAccessError as exc:
                    return {
                        "messages": [SystemMessage(content=json.dumps(
                            exc.to_dict(), ensure_ascii=False, sort_keys=True,
                        ))],
                        "skill_decision_result": exc.to_dict(),
                        "pending_action": {},
                        "next_step": "consultant",
                    }

            def commit_candidate_update(
                update: Mapping[str, Any],
            ) -> Dict[str, Any]:
                if not pending_task_skill_change:
                    return self._commit_consultant_update(task_id, update)

                before = load_plan_state(self.data_path, task_id)
                before_task_state = dict(before.get("task_state") or {})
                before_access = normalize_skill_access_state(
                    before_task_state.get("skill_access_state")
                    or before.get("skill_access_state")
                )
                prepared_update = dict(update or {})
                candidate_skill_id = str(
                    pending_task_skill_change.get("candidate_skill_id") or ""
                )
                selected_ids = {
                    str(item)
                    for item in (
                        prepared_update.get("selected_skills")
                        or prepared_update.get("selected_skill_ids")
                        or []
                    )
                    if str(item)
                }
                proposed_task = prepared_update.get("task_spec")
                proposed_revision = task_spec_revision(proposed_task)
                base_task_revision = int(
                    pending_task_skill_change.get("base_task_revision") or 0
                )
                current_pointer = dict(
                    before_task_state.get(
                        "pending_skill_binding_proposal"
                    ) or {}
                )
                pointer_matches = bool(
                    str(current_pointer.get("proposal_id") or "")
                    == str(
                        pending_task_skill_change.get("proposal_id") or ""
                    )
                    and str(current_pointer.get("status") or "")
                    == "approved_for_task_commit"
                    and str(
                        current_pointer.get("candidate_snapshot_id") or ""
                    ) == str(
                        pending_task_skill_change.get(
                            "candidate_snapshot_id"
                        )
                        or ""
                    )
                )
                proposal_authority_current = bool(
                    pointer_matches
                    and base_task_revision
                    == task_spec_revision(
                        canonical_task_spec_for_state(before)
                    )
                    and int(
                        pending_task_skill_change.get(
                            "base_plan_revision"
                        )
                        or 0
                    ) == int(before.get("plan_revision") or 0)
                    and int(
                        pending_task_skill_change.get(
                            "base_user_turn_revision"
                        )
                        if pending_task_skill_change.get(
                            "base_user_turn_revision"
                        ) is not None
                        else self._authoritative_user_turn_revision(before)
                    ) == self._authoritative_user_turn_revision(before)
                )
                if not proposal_authority_current:
                    if pointer_matches:
                        stale_access = normalize_skill_access_state(
                            before_access
                        )
                        stale_proposal = (
                            stale_access.get("binding_proposals") or {}
                        ).get(str(
                            pending_task_skill_change.get("proposal_id") or ""
                        ))
                        if isinstance(stale_proposal, MutableMapping):
                            stale_proposal["status"] = "stale"
                            stale_proposal["stale_reason"] = (
                                "authoritative_revision_changed"
                            )
                        snapshot_id = str(
                            pending_task_skill_change.get(
                                "candidate_snapshot_id"
                            )
                            or ""
                        )
                        for ref in stale_access.get(
                            "selected_skill_refs"
                        ) or []:
                            if (
                                isinstance(ref, MutableMapping)
                                and str(ref.get("snapshot_id") or "")
                                == snapshot_id
                                and str(ref.get("status") or "")
                                == "candidate"
                            ):
                                ref["candidate_disposition"] = "stale"
                                ref["stale_reason"] = (
                                    "authoritative_revision_changed"
                                )
                        stale_access = record_skill_access_event(
                            stale_access,
                            "stale_skill_binding_proposal_discarded",
                            {
                                "proposal_id": str(
                                    pending_task_skill_change.get(
                                        "proposal_id"
                                    )
                                    or ""
                                ),
                                "reason": (
                                    "authoritative_revision_changed"
                                ),
                            },
                        )
                        before_task_state.pop(
                            "pending_skill_binding_proposal", None
                        )
                        before_task_state["skill_access_state"] = stale_access
                        before["task_state"] = before_task_state
                        before["skill_access_state"] = deepcopy(stale_access)
                        try:
                            save_plan_state(self.data_path, task_id, before)
                        except StateCASConflict:
                            pass
                    return {
                        "messages": [SystemMessage(content=json.dumps({
                            "decision_result": "STALE_NODE_RESULT",
                            "caller_node": "consultant",
                            "changed_preconditions": [
                                "skill_binding_transaction"
                            ],
                            "counts_as_failure": False,
                        }, ensure_ascii=False, sort_keys=True))],
                        "stale_node_result": {
                            "decision_result": "STALE_NODE_RESULT",
                            "caller_node": "consultant",
                            "changed_preconditions": [
                                "skill_binding_transaction"
                            ],
                        },
                        "next_step": "consultant",
                    }
                semantic_commit_succeeded = bool(
                    str(prepared_update.get("next_step") or "") == "planner"
                    and task_spec_is_initialized(proposed_task)
                    and proposed_revision == base_task_revision + 1
                    and task_semantic_hash(proposed_task)
                    != task_semantic_hash(
                        canonical_task_spec_for_state(before)
                    )
                )
                proposed_task_selected_ids = list(dict.fromkeys(
                    str(item)
                    for item in (
                        (proposed_task.get("capability_intent") or {}).get(
                            "selected_skill_ids"
                        )
                        if isinstance(proposed_task, Mapping)
                        else []
                    )
                    or []
                    if str(item)
                ))
                selection_error = ""
                try:
                    authorised_selected_ids = (
                        self._authorised_task_skill_selection(
                            before_access,
                            pending_task_skill_change,
                        )
                    )
                except SkillAccessError as exc:
                    authorised_selected_ids = []
                    selection_error = exc.code
                selected_set_exact = bool(
                    not selection_error
                    and selected_ids == set(authorised_selected_ids)
                    and set(proposed_task_selected_ids)
                    == set(authorised_selected_ids)
                    and len(proposed_task_selected_ids)
                    == len(authorised_selected_ids)
                )
                candidate_selected = candidate_skill_id in selected_ids
                if not (
                    semantic_commit_succeeded
                    and candidate_selected
                    and selected_set_exact
                ):
                    prepared_update.update({
                        "skill_access_state": deepcopy(before_access),
                        "selected_skill_refs": deepcopy(list(
                            before_access.get("selected_skill_refs") or []
                        )),
                        "pending_skill_binding_proposal": deepcopy(
                            pending_task_skill_change
                        ),
                    })
                    if str(prepared_update.get("next_step") or "") != "ask_user":
                        prepared_update["messages"] = [
                            *list(prepared_update.get("messages") or []),
                            SystemMessage(content=json.dumps({
                                "decision_result": (
                                    "TASK_SKILL_CHANGE_COMMIT_INCOMPLETE"
                                ),
                                "proposal_id": str(
                                    pending_task_skill_change.get("proposal_id")
                                    or ""
                                ),
                                "semantic_commit_succeeded": (
                                    semantic_commit_succeeded
                                ),
                                "candidate_selected": candidate_selected,
                                "selected_set_exact": selected_set_exact,
                                "selection_error": selection_error,
                                "expected_selected_skill_ids": list(
                                    authorised_selected_ids
                                ),
                                "observed_selected_skill_ids": sorted(
                                    selected_ids
                                ),
                                "observed_task_skill_ids": list(
                                    proposed_task_selected_ids
                                ),
                                "required_next_action": (
                                    "Main Consultant must commit the explicit "
                                    "user-intent method/capability change and "
                                    "the exact reviewed supplement/replace "
                                    "Skill set in one candidate transaction."
                                ),
                            }, ensure_ascii=False, sort_keys=True)),
                        ]
                        prepared_update["next_step"] = "consultant"
                    return prepared_update

                access = normalize_skill_access_state(before_access)
                old_active_refs = [
                    deepcopy(dict(item))
                    for item in access.get("selected_skill_refs") or []
                    if isinstance(item, Mapping)
                    and str(item.get("status") or "") == "active"
                ]
                proposal_id = str(
                    pending_task_skill_change.get("proposal_id") or ""
                )
                durable_proposal = (
                    access.get("binding_proposals") or {}
                ).get(proposal_id)
                if not isinstance(durable_proposal, MutableMapping):
                    raise SkillAccessError(
                        "SKILL_BINDING_PROPOSAL_UNAVAILABLE", proposal_id
                    )
                if str(durable_proposal.get("status") or "") != (
                    "approved_for_task_commit"
                ):
                    raise SkillAccessError(
                        "SKILL_BINDING_REVIEW_REQUIRED", proposal_id
                    )
                # The TaskSpec method/capability change is now canonical, but
                # the binding remains a candidate until Planner accepts its
                # effect on the current Plan.  This keeps formal activation
                # strictly behind plan_impact_review.
                durable_proposal["status"] = "approved_for_plan_impact"
                durable_proposal["task_committed_at_revision"] = (
                    proposed_revision
                )
                candidate_refs = [
                    deepcopy(dict(item))
                    for item in access.get("selected_skill_refs") or []
                    if isinstance(item, Mapping)
                    and str(item.get("snapshot_id") or "")
                    == str(
                        pending_task_skill_change.get(
                            "candidate_snapshot_id"
                        )
                        or ""
                    )
                    and str(item.get("status") or "") == "candidate"
                ]
                if len(candidate_refs) != 1:
                    raise SkillAccessError(
                        "SKILL_BINDING_CANDIDATE_UNAVAILABLE",
                        f"candidate_refs={len(candidate_refs)}",
                    )
                active_ids = self._active_skill_ids_from_refs(
                    access.get("selected_skill_refs") or []
                )
                access = record_skill_access_event(
                    access,
                    "task_skill_change_committed_pending_plan_impact",
                    {
                        "proposal_id": proposal_id,
                        "old_task_revision": int(
                            pending_task_skill_change.get("base_task_revision") or 0
                        ),
                        "new_task_revision": proposed_revision,
                        "candidate_snapshot_id": str(
                            pending_task_skill_change.get(
                                "candidate_snapshot_id"
                            )
                            or ""
                        ),
                    },
                )
                pending_impact = {
                    "mode": "plan_impact_review",
                    "proposal_id": str(
                        pending_task_skill_change.get("proposal_id") or ""
                    ),
                    "base_task_revision": int(
                        pending_task_skill_change.get("base_task_revision") or 0
                    ),
                    "new_task_revision": proposed_revision,
                    "base_plan_revision": int(
                        pending_task_skill_change.get("base_plan_revision")
                        if pending_task_skill_change.get("base_plan_revision")
                        is not None
                        else before.get("plan_revision") or 0
                    ),
                    "base_user_turn_revision": (
                        self._authoritative_user_turn_revision(before)
                    ),
                    "skill_change": {
                        "proposal": deepcopy(pending_task_skill_change),
                        "consultant_review": deepcopy(dict(
                            pending_task_skill_change.get("review") or {}
                        )),
                        "old_task_spec": deepcopy(
                            canonical_task_spec_for_state(before)
                        ),
                        "old_active_skill_refs": old_active_refs,
                        "candidate_skill_refs": candidate_refs,
                        "relation": str(
                            pending_task_skill_change.get("relation") or ""
                        ),
                    },
                    "status": "pending",
                }
                # One CAS commit owns TaskSpec, the inactive canonical
                # candidate ref, and the pending Planner review.  No partial
                # TaskSpec mutation is observable if validation or the write
                # fails.
                prepared_update.update({
                    "skill_access_state": deepcopy(access),
                    "selected_skill_refs": deepcopy(list(
                        access.get("selected_skill_refs") or []
                    )),
                    "selected_skills": list(active_ids),
                    "selected_skill_ids": list(active_ids),
                    "pending_skill_binding_proposal": {},
                    "pending_plan_impact_review": deepcopy(pending_impact),
                    "expected_state_generation": int(
                        before.get("state_generation") or 0
                    ),
                    "expected_plan_revision": int(
                        before.get("plan_revision") or 0
                    ),
                    "expected_user_turn_revision": (
                        self._authoritative_user_turn_revision(before)
                    ),
                    "expected_pending_skill_proposal_id": proposal_id,
                    "expected_pending_skill_proposal_status": (
                        "approved_for_task_commit"
                    ),
                    "expected_pending_skill_snapshot_id": str(
                        pending_task_skill_change.get(
                            "candidate_snapshot_id"
                        )
                        or ""
                    ),
                })
                try:
                    committed = self._commit_consultant_update(
                        task_id, prepared_update
                    )
                except StateCASConflict as exc:
                    return {
                        "messages": [
                            *list(prepared_update.get("messages") or []),
                            SystemMessage(content=json.dumps({
                                "decision_result": "STALE_NODE_RESULT",
                                "caller_node": "consultant",
                                "changed_preconditions": [
                                    "skill_binding_transaction"
                                ],
                                "detail": str(exc),
                                "counts_as_failure": False,
                            }, ensure_ascii=False, sort_keys=True)),
                        ],
                        "stale_node_result": {
                            "decision_result": "STALE_NODE_RESULT",
                            "caller_node": "consultant",
                            "changed_preconditions": [
                                "skill_binding_transaction"
                            ],
                        },
                        "next_step": "consultant",
                    }
                committed["selected_skills"] = list(active_ids)
                committed["selected_skill_ids"] = list(active_ids)
                committed["pending_skill_binding_proposal"] = {}
                committed["pending_plan_impact_review"] = deepcopy(
                    pending_impact
                )
                committed["next_step"] = "planner"
                return committed

            durable_consultant_entry = load_plan_state(self.data_path, task_id)
            durable_consultant_task_state = dict(
                durable_consultant_entry.get("task_state") or {}
            )
            task_spec = self._task_spec_for_state(dict(state), messages)
            stale_consultation = dict(
                state.get("consultation_state")
                or durable_consultant_task_state.get("consultation_state")
                or {}
            )
            entry_state = consultant_entry_disposition(
                durable_consultant_entry,
                consultation_state=stale_consultation,
            )
            if entry_state.get("disposition") == (
                ConsultantEntryDisposition.FAIL_CANONICAL_INCONSISTENCY.value
            ):
                failure = deepcopy(entry_state)
                return {
                    "messages": [SystemMessage(content=json.dumps(
                        failure, ensure_ascii=False, sort_keys=True,
                    ))],
                    "consultation_state": stale_consultation,
                    "binding_phase": deepcopy(dict(
                        failure.get("binding_phase") or {}
                    )),
                    "consultant_commit_rejection": deepcopy(dict(
                        durable_consultant_task_state.get(
                            "consultant_commit_rejection"
                        ) or failure
                    )),
                    "consultant_pending_transition": deepcopy(dict(
                        durable_consultant_task_state.get(
                            "consultant_pending_transition"
                        ) or {}
                    )),
                    "consultant_no_progress_ledger": deepcopy(dict(
                        durable_consultant_task_state.get(
                            "consultant_no_progress_ledger"
                        ) or {}
                    )),
                    "skill_decision_result": failure,
                    "canonical_commit": {
                        "succeeded": False,
                        "error_code": (
                            "CONSULTANT_CANONICAL_STATE_INCONSISTENT"
                        ),
                    },
                    "task_status": TASK_STATUS_FAILED,
                    "failure_owner": "controller",
                    "contract_status": "internal_protocol",
                    "pending_human_question": {},
                    "next_step": str(
                        failure.get("terminal_route") or "finish"
                    ),
                }
            if not task_spec_is_initialized(task_spec):
                legacy_reset = legacy_uninitialized_task_reset_decision(
                    durable_consultant_entry,
                    consultation_state=stale_consultation,
                    contract_repair_present=bool(
                        state.get("consultant_contract_repair")
                    ),
                )
                if legacy_reset["allowed"]:
                    # A legacy semantic-empty TaskSpec cannot own a valid
                    # finalized contract.  Preserve raw conversation and any
                    # skill hint, but reset only the stale consultation phase
                    # so Consultant can perform a general bootstrap repair.
                    recovered_consultation = new_consultation_state(
                        f"{task_id}:consultant:legacy-bootstrap",
                        task_id,
                        max_total_execute=4,
                        max_no_progress=2,
                    )
                    recovered_consultation["last_feedback"] = [{
                        "code": "LEGACY_UNINITIALIZED_TASKSPEC",
                        "instruction": (
                            "The prior semantic-empty TaskSpec was not canonical. "
                            "Rebuild candidate semantics from the complete conversation evidence."
                        ),
                    }]
                    state = {
                        **dict(state),
                        "consultation_state": recovered_consultation,
                        "consultant_contract_repair": {},
                        "consultant_no_progress_ledger": deepcopy(dict(
                            legacy_reset.get(
                                "preserved_consultant_no_progress_ledger"
                            ) or {}
                        )),
                        "pending_human_question": {},
                    }
            task_spec_repair_issues = [
                dict(item) for item in state.get("validation_issues", []) or []
                if isinstance(item, Mapping)
                and str(item.get("owner") or "") in {"task_spec", "external_input"}
                and str(item.get("severity") or "").lower() in {"error", "blocking", "fatal"}
            ]
            if task_spec_repair_issues:
                external_issues = [
                    item for item in task_spec_repair_issues
                    if str(item.get("owner") or "") == "external_input"
                ]
                selected_for_repair = list(state.get("selected_skills") or [])
                repair_task_state = dict(
                    load_plan_state(self.data_path, task_id).get("task_state") or {}
                )
                legacy_renderer_repair = bool(
                    repair_task_state.get("legacy_renderer_mode") is True
                    or str(repair_task_state.get("execution_contract") or "")
                    == "legacy_renderer_v1"
                )
                repair_renderer_records = [
                    self.skill_manager.get_renderer_record(skill_id)
                    for skill_id in selected_for_repair
                    if (
                        legacy_renderer_repair
                        and self.skill_manager
                        and self.skill_manager.has_renderer(skill_id)
                    )
                ]
                declarative_repair = apply_declarative_task_spec_rules(
                    task_spec,
                    repair_renderer_records,
                )
                if canonical_constraint_hash(declarative_repair) != canonical_constraint_hash(task_spec):
                    old_revision = task_spec_revision(task_spec)
                    declarative_repair["revision"] = old_revision + 1
                    declarative_repair.setdefault("change_log", []).append({
                        "revision": declarative_repair["revision"],
                        "source": "skill_contract_derived",
                        "reason": "validation_issue_owned_taskspec_repair",
                        "recorded_at": datetime.now().isoformat(),
                    })
                    return commit_candidate_update({
                        "messages": [SystemMessage(content=(
                            "<consultant_task_spec_repair status=\"deterministic_committed\" />"
                        ))],
                        "task_spec": declarative_repair,
                        "task_revision": declarative_repair["revision"],
                        "validation_issues": task_spec_repair_issues,
                        "next_step": "planner",
                    })
                missing_fields = list(dict.fromkeys(
                    str(item.get("renderer_field") or item.get("field_path") or item.get("repair_target") or "required value")
                    for item in task_spec_repair_issues
                ))
                if external_issues:
                    question = (
                        "The deterministic plan contract is missing authoritative external value(s): "
                        + ", ".join(missing_fields)
                        + ". Please provide the exact value or input path; BioMind will not guess it."
                    )
                    return {
                        "messages": [SystemMessage(content=(
                            "<consultant_task_spec_repair>"
                            + json.dumps(external_issues, ensure_ascii=False, sort_keys=True, default=str)
                            + "</consultant_task_spec_repair>"
                        ))],
                        "pending_human_question": {
                            "type": "task_spec_contract_repair",
                            "stage": "consultant",
                            "question": question,
                            "resume_step": "consultant",
                            "validation_issue_fingerprints": [
                                str(item.get("fingerprint") or "") for item in external_issues
                            ],
                        },
                        "consultant_repair_scope": {
                            "allowed_target": "task_spec",
                            "forbidden_targets": ["selected_skills", "plan", "renderer_contract", "validation_issues"],
                        },
                        "next_step": "ask_user",
                    }

                issue_fingerprints = sorted(
                    str(item.get("fingerprint") or "") for item in task_spec_repair_issues
                )
                repair_fingerprint = hashlib.sha256(json.dumps({
                    "task_spec_hash": canonical_constraint_hash(task_spec),
                    "issue_fingerprints": issue_fingerprints,
                }, ensure_ascii=False, sort_keys=True).encode("utf-8")).hexdigest()
                repair_history = [
                    dict(item) for item in state.get("task_spec_repair_history", []) or []
                    if isinstance(item, Mapping)
                ]
                if any(str(item.get("fingerprint") or "") == repair_fingerprint for item in repair_history):
                    reason = (
                        "TASKSPEC_REPAIR_NON_CONVERGENT: the same TaskSpec and blocking issue set "
                        "reappeared without new user or external evidence."
                    )
                    return {
                        "messages": [SystemMessage(content=reason)],
                        "task_spec_repair_history": repair_history,
                        "plan_progress": self._mark_plan_current_blocked(state.get("task_id", "default"), reason),
                        "task_status": TASK_STATUS_BLOCKED,
                        "failure_owner": "task_spec",
                        "next_step": "finish",
                    }

                allowed_slots: List[str] = []
                for issue in task_spec_repair_issues:
                    target_text = " ".join([
                        str(issue.get("repair_target") or ""),
                        str(issue.get("field_path") or ""),
                    ])
                    for match in re.finditer(r"role=([A-Za-z0-9_.-]+)", target_text):
                        slot = match.group(1).strip()
                        if slot and slot not in allowed_slots:
                            allowed_slots.append(slot)
                    for match in re.finditer(
                        r"(?:required_behavior|required_input|required_output|runtime_constraint|failure_policy)\.([A-Za-z0-9_.-]+)",
                        target_text,
                    ):
                        slot = match.group(1).strip()
                        if slot and slot not in allowed_slots:
                            allowed_slots.append(slot)
                if not allowed_slots:
                    reason = (
                        "TASKSPEC_REPAIR_SCOPE_EMPTY: TaskSpec-owned validation issues did not "
                        "identify an authorized semantic slot."
                    )
                    return {
                        "messages": [SystemMessage(content=reason)],
                        "plan_progress": self._mark_plan_current_blocked(state.get("task_id", "default"), reason),
                        "task_status": TASK_STATUS_BLOCKED,
                        "failure_owner": "internal",
                        "next_step": "finish",
                    }

                provenance_catalog = semantic_provenance_catalog(
                    task_spec,
                    consultation_state=state.get("consultation_state") or {},
                    selected_skill_ids=selected_for_repair,
                )
                repairable_semantic_keys = sorted({
                    str(item.get("semantic_key") or "").strip()
                    for item in task_spec.get("requirements", []) or []
                    if isinstance(item, Mapping)
                    and str(item.get("semantic_key") or "").strip()
                    and str(item.get("semantic_key") or "").split(".", 1)[-1]
                    in allowed_slots
                })
                repair_source_evidence = [
                    {
                        "evidence_id": str(item.get("source_id") or item.get("source_ref") or f"source:{index}"),
                        "kind": str(item.get("source_type") or "task_source"),
                        "excerpt": str(item.get("label") or item.get("source_text") or "Authorized semantic source"),
                        "truncated": False,
                    }
                    for index, item in enumerate(provenance_catalog, start=1)
                    if isinstance(item, Mapping)
                ]
                repair_plan_state = load_plan_state(
                    self.data_path, state.get("task_id", "default")
                )
                repair_node_context = build_node_context(
                    node_type="consultant",
                    task_spec=task_spec,
                    plan_state=repair_plan_state,
                    state_generation=int(repair_plan_state.get("state_generation") or 0),
                    feedback={"allowed_semantic_slots": allowed_slots},
                    evidence=repair_source_evidence,
                    violations=task_spec_repair_issues,
                    allowed_operations=[
                        "add_constraint", "replace_constraint", "request_user_input",
                    ],
                    violation_set_identity=repair_fingerprint,
                    trace_enabled=bool(os.getenv("NODE_CONTEXT_V2_TRACE", "")),
                    max_payload_chars=max(1, int(self.llm_context_limit_tokens) * 4),
                )
                repair_prompt = f"""You are performing a constrained TaskSpec repair.
Return exactly one JSON object and no prose with these exact fields:
{{
  "constraints": [],
  "needs_user_input": false,
  "question": ""
}}

You may replace only existing legacy keyed constraints for these semantic slots:
{json.dumps(allowed_slots, ensure_ascii=False)}

Existing repairable legacy keys:
{json.dumps(repairable_semantic_keys, ensure_ascii=False)}

Every constraint must contain constraint_id, semantic_key, operator, value,
strength, confidence, and provenance. Each provenance entry must contain only
one `source_handle`, copied from an evidence handle in the payload. The
Controller resolves it to the immutable source identity. Preserve all unaffected TaskSpec
semantics. Do not create a new generic semantic key or ontology row. If no
listed legacy key is applicable, request user input instead. Do not modify
selected skills, plan steps, renderer metadata,
validation issues, or approval state. If no catalog source authorizes the
missing value, return constraints=[], needs_user_input=true, and one exact
question. Never guess a scientific or database identity.

<llm_payload>
{repair_node_context.llm_payload.to_json(indent=2)}
</llm_payload>"""
                try:
                    repair_response = await self._ainvoke_node_llm(
                        [HumanMessage(content=repair_prompt)],
                        node_context=repair_node_context,
                        stage="consultant_task_spec_repair",
                        task_id=state.get("task_id", "default"),
                        task_mode=str(state.get("task_mode") or "managed"),
                        trace_metadata={
                            "call_kind": "consultant_task_spec_repair",
                            "task_spec_revision": task_spec_revision(task_spec),
                            "issue_fingerprints": issue_fingerprints,
                            "allowed_semantic_slots": allowed_slots,
                        },
                    )
                    raw_repair = str(repair_response.content or "").strip()
                    fence = re.fullmatch(
                        r"```(?:json)?\s*\n?(?P<body>.*)\n?```",
                        raw_repair,
                        re.IGNORECASE | re.DOTALL,
                    )
                    if raw_repair.startswith("```"):
                        if not fence:
                            raise ValueError("TASKSPEC_REPAIR_STRUCTURE_INVALID: mixed JSON fence")
                        raw_repair = fence.group("body").strip()
                    repair_payload = json.loads(raw_repair)
                    if not isinstance(repair_payload, Mapping):
                        raise ValueError("TASKSPEC_REPAIR_STRUCTURE_INVALID: response must be an object")
                    expected_repair_fields = {
                        "constraints", "needs_user_input", "question",
                    }
                    if set(repair_payload) != expected_repair_fields:
                        raise ValueError("TASKSPEC_REPAIR_STRUCTURE_INVALID: unexpected or missing fields")
                    repair_payload = dict(repair_payload)
                    current_repair_state = load_plan_state(
                        self.data_path, state.get("task_id", "default")
                    )
                    current_repair_task = canonical_task_spec_for_state(
                        current_repair_state
                    )
                    current_repair_binding = build_node_context(
                        node_type="consultant",
                        task_spec=current_repair_task,
                        plan_state=current_repair_state,
                        state_generation=int(current_repair_state.get("state_generation") or 0),
                    ).binding
                    repair_staleness = evaluate_node_staleness(
                        repair_node_context.binding,
                        current_repair_binding.to_dict(),
                    )
                    if not repair_staleness.usable:
                        self._node_invocations.mark_stale_signature_handled(
                            repair_staleness.stale_signature
                        )
                        raise RuntimeError(repair_staleness.code)
                    source_types = {
                        str(item.get("source_id") or item.get("source_ref") or ""):
                        str(item.get("source_type") or "")
                        for item in provenance_catalog
                        if isinstance(item, Mapping)
                    }
                    for constraint in repair_payload.get("constraints") or []:
                        if not isinstance(constraint, MutableMapping):
                            raise ValueError("TASKSPEC_REPAIR_STRUCTURE_INVALID: constraint must be an object")
                        resolved_provenance: List[Dict[str, str]] = []
                        for source in constraint.get("provenance") or []:
                            if not isinstance(source, Mapping) or set(source) != {"source_handle"}:
                                raise ValueError("TASKSPEC_REPAIR_STRUCTURE_INVALID: provenance must use source_handle")
                            resolved = resolve_response_handles(
                                repair_node_context.binding,
                                [str(source.get("source_handle") or "")],
                                object_type="evidence",
                                usage="cite",
                            )[0]
                            source_id = str(resolved.get("stable_identity") or "")
                            resolved_provenance.append({
                                "source_id": source_id,
                                "source_ref": source_id,
                                "source_type": source_types.get(source_id, ""),
                            })
                        constraint["provenance"] = resolved_provenance
                    repair_payload["base_task_spec_revision"] = task_spec_revision(task_spec)
                    history_entry = {
                        "fingerprint": repair_fingerprint,
                        "issue_fingerprints": issue_fingerprints,
                        "base_task_spec_revision": task_spec_revision(task_spec),
                        "recorded_at": datetime.now().isoformat(),
                    }
                    repair_history.append(history_entry)
                    if repair_payload.get("needs_user_input") is True:
                        question = str(repair_payload.get("question") or "").strip()
                        if repair_payload.get("constraints") or not question:
                            raise ValueError("TASKSPEC_REPAIR_STRUCTURE_INVALID: invalid user-input response")
                        history_entry["status"] = "needs_user_input"
                        return {
                            "messages": [SystemMessage(content="<consultant_task_spec_repair status=\"needs_user_input\" />")],
                            "pending_human_question": {
                                "type": "task_spec_contract_repair",
                                "stage": "consultant",
                                "question": question,
                                "resume_step": "consultant",
                                "validation_issue_fingerprints": issue_fingerprints,
                            },
                            "task_spec_repair_history": repair_history[-12:],
                            "next_step": "ask_user",
                        }
                    repaired_task_spec = apply_authorized_task_spec_constraint_repair(
                        task_spec,
                        repair_payload,
                        allowed_semantic_slots=allowed_slots,
                        provenance_catalog=provenance_catalog,
                        project_root=project_root,
                    )
                    history_entry["status"] = "committed_pending_revalidation"
                    history_entry["new_task_spec_revision"] = task_spec_revision(repaired_task_spec)
                    return commit_candidate_update({
                        "messages": [SystemMessage(content="<consultant_task_spec_repair status=\"committed_pending_revalidation\" />")],
                        "task_spec": repaired_task_spec,
                        "task_revision": task_spec_revision(repaired_task_spec),
                        "validation_issues": task_spec_repair_issues,
                        "task_spec_repair_history": repair_history[-12:],
                        "consultant_repair_scope": {
                            "allowed_target": "task_spec.requirements",
                            "allowed_semantic_slots": allowed_slots,
                            "forbidden_targets": ["selected_skills", "plan", "renderer_contract", "validation_issues"],
                        },
                        "next_step": "planner",
                    })
                except Exception as exc:
                    if is_transient_llm_failure(exc) and not is_llm_input_rejected(exc):
                        return self._pause_retryable_llm_failure(
                            state,
                            state.get("task_id", "default"),
                            "consultant_task_spec_repair",
                            exc,
                        )
                    reason = (
                        "TASKSPEC_REPAIR_REJECTED: constrained Consultant repair was not committed: "
                        f"{type(exc).__name__}: {exc}"
                    )
                    repair_history.append({
                        "fingerprint": repair_fingerprint,
                        "issue_fingerprints": issue_fingerprints,
                        "base_task_spec_revision": task_spec_revision(task_spec),
                        "status": "rejected",
                        "error_type": type(exc).__name__,
                        "recorded_at": datetime.now().isoformat(),
                    })
                    return {
                        "messages": [SystemMessage(content=reason)],
                        "task_spec_repair_history": repair_history[-12:],
                        "plan_progress": self._mark_plan_current_blocked(state.get("task_id", "default"), reason),
                        "task_status": TASK_STATUS_BLOCKED,
                        "failure_owner": "internal",
                        "next_step": "finish",
                    }
            # One discovery episode owns a stable preprocessing base.  LLM
            # decisions, feedback, skill documents and routing remain dynamic.
            preprocess_task_started = time.perf_counter()
            preprocess_started_at = datetime.now(timezone.utc).isoformat()
            task_id = state.get("task_id", "default")
            project_id = state.get("project_id") or self.default_project_id
            work_dir = self.pm.work_dir if self.pm else os.getcwd()
            durable_preprocess_state = load_plan_state(self.data_path, task_id)
            durable_preprocess_task_state = dict(
                durable_preprocess_state.get("task_state") or {}
            )
            consultation_state = dict(
                state.get("consultation_state")
                or durable_preprocess_task_state.get("consultation_state")
                or {}
            )
            if not consultation_state:
                consultation_state = new_consultation_state(
                    f"{task_id}:consultant:{task_spec_revision(task_spec)}",
                    task_id,
                    max_total_execute=4,
                    max_no_progress=2,
                )
            discovery_state = normalize_skill_discovery_state(
                consultation_state.get("skill_discovery")
            )
            intent_admission = dict(
                durable_preprocess_task_state.get("intent_admission")
                or state.get("intent_admission")
                or {}
            )
            continuation_identity = build_continuation_identity(
                task_id=task_id,
                consultation_id=str(consultation_state.get("consultation_id") or ""),
                conversation_evidence=dict(
                    durable_preprocess_state.get("conversation_evidence")
                    or state.get("conversation_evidence")
                    or {}
                ),
                task_spec=task_spec,
                project_id=project_id,
                task_mode=str(state.get("task_mode") or "managed"),
                task_ownership={
                    key: intent_admission.get(key)
                    for key in (
                        "admission_id", "admission_status", "request_kind",
                        "execution_scope", "managed_intent_explicit",
                        "decision_source",
                    )
                    if intent_admission.get(key) not in (None, "", [], {})
                },
                resolved_bindings=dict(
                    state.get("resolved_bindings")
                    or durable_preprocess_task_state.get("resolved_bindings")
                    or {}
                ),
                work_dir=str(work_dir),
            )
            prior_continuation = dict(
                consultation_state.get("discovery_continuation") or {}
            )
            cache_decision = evaluate_continuation_cache(
                prior_continuation,
                identity=continuation_identity,
            )
            continuation_invocation = (
                int(prior_continuation.get("invocation_count") or 0) + 1
            )
            preprocess_recorder = ConsultantPreprocessRecorder(
                task_id=task_id,
                episode_id=str(continuation_identity.get("episode_id") or ""),
                invocation=continuation_invocation,
                started_perf=preprocess_task_started,
                started_at=preprocess_started_at,
            )
            preprocess_recorder.mark(
                "task_state",
                elapsed_ms=(time.perf_counter() - preprocess_task_started) * 1000,
                call_count=1,
                cache_hit=bool(cache_decision.get("cache_hit")),
                cache_miss=not bool(cache_decision.get("cache_hit")),
                cache_reason=str(cache_decision.get("reason") or ""),
            )
            self._record_consultant_progress(
                task_id,
                code="CONSULTANT_CONTEXT_PREPARING",
                message="Consultant is preparing the bounded discovery context.",
                detail={
                    "episode_id": str(continuation_identity.get("episode_id") or ""),
                    "invocation": continuation_invocation,
                    "cache_hit": bool(cache_decision.get("cache_hit")),
                },
            )

            continuation_base: Dict[str, Any]
            archive_telemetry: Dict[str, Any]
            if cache_decision.get("cache_hit"):
                continuation_base = deepcopy(dict(cache_decision.get("base") or {}))
                conversation_turns = deepcopy(
                    list(continuation_base.get("conversation_turns") or [])
                )
                semantic_conversation_evidence = deepcopy(
                    list(continuation_base.get("semantic_conversation_evidence") or [])
                )
                consultant_context = str(
                    continuation_base.get("consultant_context") or ""
                )
                consultant_wiki_context = str(
                    continuation_base.get("consultant_wiki_context") or ""
                )
                consultant_memory_retrieval_context = str(
                    continuation_base.get("consultant_memory_retrieval_context") or ""
                )
                user_preferences_context = str(
                    continuation_base.get("user_preferences_context") or ""
                )
                input_resolution_result = deepcopy(dict(
                    continuation_base.get("input_resolution_result") or {}
                ))
                input_resolution_context = str(
                    continuation_base.get("input_resolution_context") or ""
                )
                workflow_candidate_ids = list(
                    continuation_base.get("workflow_candidate_ids") or []
                )
                workflow_catalog = str(
                    continuation_base.get("workflow_catalog") or ""
                )
                base_archive_telemetry = deepcopy(dict(
                    continuation_base.get("archive_telemetry") or {}
                ))
                archive_telemetry = {
                    **base_archive_telemetry,
                    "origin_query_count": int(
                        base_archive_telemetry.get("query_count") or 0
                    ),
                    "query_count": 0,
                    "cache_hit": True,
                }
                for phase in (
                    "memory", "session_archive", "input_inventory",
                    "input_resolution", "skill_catalog",
                ):
                    preprocess_recorder.mark(
                        phase,
                        cache_hit=True,
                        call_count=0,
                    )
            else:
                with preprocess_recorder.phase("task_state", cache_miss=True):
                    conversation_turns, semantic_conversation_evidence = (
                        self._consultant_semantic_conversation(task_id, messages)
                    )
                    consultant_context = "\n".join(
                        dict.fromkeys(
                            part
                            for part in [
                                str(task_spec.get("goal") or "").strip(),
                                *[
                                    str(turn.get("content") or "").strip()
                                    for turn in conversation_turns
                                    if str(turn.get("role") or "") == "user"
                                ],
                            ]
                            if part
                        )
                    ).strip()
                with preprocess_recorder.phase("input_inventory", cache_miss=True) as phase_stats:
                    required_candidate_input_roles = list(dict.fromkeys(
                        canonical_input_role(
                            str(item.get("role") or ""),
                            str(item.get("path") or item.get("resolved_path") or ""),
                        )
                        for item in task_spec.get("inputs") or []
                        if isinstance(item, Mapping)
                        and bool(item.get("required", True))
                        and not str(
                            item.get("path") or item.get("resolved_path") or ""
                        ).strip()
                    ))
                    consultant_requested_input_roles = list(dict.fromkeys([
                        *required_candidate_input_roles,
                        *list(
                            discovery_state.get("requested_input_candidate_roles")
                            or []
                        ),
                    ]))
                    input_resolution_result = resolve_formal_upstream_artifacts(
                        consultant_context,
                        work_dir=work_dir,
                        task_id=task_id,
                        project_root=project_root,
                        candidate_search_roles=consultant_requested_input_roles,
                        required_input_roles=required_candidate_input_roles,
                    )
                    phase_stats["candidate_count"] = len(
                        input_resolution_result.get("formal_candidates") or []
                    )
                with preprocess_recorder.phase("input_resolution", cache_miss=True) as phase_stats:
                    input_resolution_context = format_formal_upstream_context(
                        input_resolution_result
                    )
                    phase_stats["resolved_role_count"] = len(
                        discovery_input_roles(
                            input_audit=input_resolution_result,
                            task_spec=task_spec,
                        )
                    )
                    phase_stats["output_chars"] = len(input_resolution_context)
                with preprocess_recorder.phase("memory", cache_miss=True) as phase_stats:
                    consultant_wiki_context = self._wiki_memory_stage_context(
                        task_id=task_id,
                        project_id=project_id,
                        query=consultant_context,
                    )
                    phase_stats["wiki_chars"] = len(consultant_wiki_context)
                archive_query = compact_archive_query(
                    consultant_context=consultant_context,
                    task_hypothesis=str(discovery_state.get("task_hypothesis") or ""),
                    task_goal=str(task_spec.get("goal") or ""),
                    input_roles=discovery_input_roles(
                        input_audit=input_resolution_result,
                        task_spec=task_spec,
                    ),
                )
                with preprocess_recorder.phase("session_archive", cache_miss=True) as phase_stats:
                    # Cross-task archive facts are advisory only.  Running the
                    # SQLite lookup here used to add a fixed timeout to the
                    # canonical Consultant path.  Defer it and fail open; the
                    # current task's durable state remains the sole authority.
                    archive_context = ""
                    archive_rows_returned = 0
                    archive_enrichment = {
                        "value": "",
                        "timed_out": False,
                        "failed_open": True,
                        "busy_or_locked": False,
                        "error_type": "OptionalArchiveObservationDeferred",
                        "elapsed_ms": 0.0,
                        "deferred": True,
                    }
                    archive_telemetry = {
                        "query_count": 0,
                        "query_chars": len(archive_query),
                        "result_chars": len(archive_context),
                        "rows_returned": archive_rows_returned,
                        "timed_out": bool(archive_enrichment.get("timed_out")),
                        "failed_open": bool(archive_enrichment.get("failed_open")),
                        "busy_or_locked": bool(archive_enrichment.get("busy_or_locked")),
                        "error_type": str(archive_enrichment.get("error_type") or ""),
                        "elapsed_ms": float(archive_enrichment.get("elapsed_ms") or 0.0),
                        "deferred": True,
                    }
                    phase_stats.update({
                        "call_count": 0,
                        "query_chars": len(archive_query),
                        "output_chars": len(archive_context),
                        "returned_item_count": archive_rows_returned,
                        "timed_out": archive_telemetry["timed_out"],
                        "failed_open": archive_telemetry["failed_open"],
                        "busy_or_locked": archive_telemetry["busy_or_locked"],
                        "deferred": True,
                    })
                with preprocess_recorder.phase("memory", cache_miss=True) as phase_stats:
                    consultant_memory_retrieval_context = await self._consultant_memory_retrieval_context(
                        task_id=task_id,
                        project_id=project_id,
                        query=consultant_context,
                        wiki_context=consultant_wiki_context,
                        archive_context=archive_context,
                    )
                    phase_stats["output_chars"] = len(
                        consultant_memory_retrieval_context
                    )
                    user_preferences_context = self._load_user_preferences()
                    phase_stats["preference_chars"] = len(user_preferences_context)
                with preprocess_recorder.phase("skill_catalog", cache_miss=True) as phase_stats:
                    workflow_candidate_ids = []
                    if self.workflow_manager:
                        workflow_candidate_ids = self.workflow_manager.candidate_workflow_ids_for_prompt(
                            consultant_context,
                            max_results=2,
                        )
                        if workflow_candidate_ids:
                            workflow_catalog = self.workflow_manager.get_workflow_catalog_prompt(
                                workflow_ids=workflow_candidate_ids,
                                max_entries=2,
                                description_chars=180,
                            )
                        else:
                            workflow_catalog = (
                                "<workflow_catalog>\n"
                                "No metadata workflow match was found. Do not invent a workflow ID; use canonical skills directly unless a loaded template proves a match.\n"
                                "</workflow_catalog>"
                            )
                    else:
                        workflow_catalog = "<workflow_catalog>\nNo workflow templates available.\n</workflow_catalog>"
                    phase_stats["candidate_count"] = len(workflow_candidate_ids)
                    phase_stats["output_chars"] = len(workflow_catalog)
                continuation_base = {
                    "conversation_turns": deepcopy(conversation_turns),
                    "semantic_conversation_evidence": deepcopy(
                        semantic_conversation_evidence
                    ),
                    "consultant_context": consultant_context,
                    "consultant_wiki_context": consultant_wiki_context,
                    "consultant_memory_retrieval_context": consultant_memory_retrieval_context,
                    "user_preferences_context": user_preferences_context,
                    "input_resolution_result": deepcopy(input_resolution_result),
                    "input_resolution_context": input_resolution_context,
                    "workflow_candidate_ids": list(workflow_candidate_ids),
                    "workflow_catalog": workflow_catalog,
                    "archive_telemetry": archive_telemetry,
                }

            consultant_max_skills = self._selection_max_skills(consultant_context)
            last_human_index = -1
            for idx, msg in enumerate(messages):
                if isinstance(msg, HumanMessage):
                    last_human_index = idx
            recent_consultant_messages = messages[last_human_index + 1:] if last_human_index >= 0 else messages
            load_actions = [
                str(m.content).strip()
                for m in recent_consultant_messages
                if isinstance(m, AIMessage) and str(m.content).strip().startswith("LOAD_")
            ]
            consultant_observations = [
                str(m.content)
                for m in recent_consultant_messages
                if isinstance(m, SystemMessage) and "<observation>" in str(m.content)
            ]
            validation_errors = [
                str(m.content)
                for m in recent_consultant_messages
                if isinstance(m, SystemMessage) and "<consultant_validation_error>" in str(m.content)
            ]
            semantic_validation_errors = [
                str(m.content)
                for m in recent_consultant_messages
                if isinstance(m, SystemMessage)
                and "<consultant_semantic_constraint_validation_error>" in str(m.content)
            ]
            semantic_resolution_requests = [
                str(m.content)
                for m in recent_consultant_messages
                if isinstance(m, SystemMessage)
                and "<consultant_semantic_resolution_request>" in str(m.content)
            ]
            contract_repair_state = dict(state.get("consultant_contract_repair") or {})
            existing_consultation_state = state.get("consultation_state") or {}
            finalize_controller_active = bool(
                contract_repair_state
                or (
                    isinstance(existing_consultation_state, Mapping)
                    and (
                        str(existing_consultation_state.get("phase") or "") in {
                            "ready_to_finalize", "finalize"
                        }
                        or str(existing_consultation_state.get("completion_decision") or "")
                        == "ready_to_finalize"
                        or isinstance(existing_consultation_state.get("finalize_protocol"), Mapping)
                    )
                )
            )
            format_repair_errors = [
                err for err in validation_errors
                if _consultant_validation_is_format_repair_error(err)
            ]
            internal_validation_errors = [
                err for err in validation_errors
                if not _consultant_validation_is_format_repair_error(err)
            ]
            load_errors = [
                str(m.content)
                for m in recent_consultant_messages
                if isinstance(m, SystemMessage) and "<load_error" in str(m.content)
            ]
            failed_consultant_execs = [
                str(m.content)
                for m in recent_consultant_messages
                if isinstance(m, SystemMessage)
                and "<observation>" in str(m.content)
                and "❌" in str(m.content)
            ]
            verified_loaded_skill_ids = self._consultant_verified_loaded_skill_ids(
                recent_consultant_messages
            )
            if input_resolution_context.strip():
                output.print_once(
                    f"formal_upstream_audit:{task_id}",
                    "🔎 Consultant checked formal upstream artifacts before asking or blocking.",
                    Fore.CYAN,
                )

            semantic_failure_route = (
                "consultant"
                if finalize_controller_active
                else self._consultant_semantic_failure_route(
                    repair_attempt=(
                        int(contract_repair_state.get("repair_attempt") or 0)
                        if contract_repair_state
                        else len(semantic_validation_errors)
                    ),
                    ambiguity_retry_count=len(semantic_resolution_requests),
                )
            )
            if semantic_failure_route == "blocked_internal_contract_error":
                reason = (
                    "Consultant exhausted the bounded internal semantic-contract repair budget. "
                    "The user request is preserved and was not treated as ambiguous."
                )
                blocked_consultation = dict(state.get("consultation_state") or {})
                blocked_consultation.update({
                    "phase": "blocked",
                    "consultation_status": "blocked",
                    "completion_decision": "blocked",
                    "completion_reason": "internal_semantic_contract_error",
                })
                return {
                    "messages": [SystemMessage(content=f"<blocked_internal_contract_error>{reason}</blocked_internal_contract_error>")],
                    "consultant_constraint_metrics": {
                        "schema_validation": "failed",
                        "parse_retry_count": int(contract_repair_state.get("repair_attempt") or len(semantic_validation_errors)),
                        "semantic_resolution_retry_count": len(semantic_resolution_requests),
                    },
                    "consultation_state": blocked_consultation,
                    "consultant_contract_repair": contract_repair_state,
                    "pending_human_question": {},
                    "contract_status": "blocked_internal_contract_error",
                    "next_step": "finish",
                }
            if semantic_failure_route == "ask_user":
                reason = (
                    "A schema-valid critical constraint remains explicitly marked "
                    "needs_clarification after bounded context resolution."
                )
                return {
                    "messages": [SystemMessage(content=f"<blocked_need_user_decision>{reason}</blocked_need_user_decision>")],
                    "consultant_constraint_metrics": {
                        "schema_validation": "passed",
                        "parse_retry_count": int(contract_repair_state.get("repair_attempt") or len(semantic_validation_errors)),
                        "semantic_resolution_retry_count": len(semantic_resolution_requests),
                    },
                    "pending_human_question": {
                        "type": "semantic_constraint_clarification",
                        "stage": "consultant",
                        "question": reason + " Please clarify that specific semantic decision.",
                        "resume_step": "consultant",
                    },
                    "contract_status": "blocked_need_user_decision",
                    "next_step": "ask_user",
                }

            if not finalize_controller_active and len(failed_consultant_execs) >= 3:
                recent_error_preview = "\n".join(
                    f"- {re.sub(r'<[^>]+>', '', err).strip()[:500]}"
                    for err in failed_consultant_execs[-3:]
                    if str(err).strip()
                )
                obs = (
                    '<blocked_internal_contract_error code="CONSULTANT_EXECUTE_REPAIR_EXHAUSTED">\n'
                    "Repeated Consultant EXECUTE failures reached the loop guard. "
                    "Automatic read-only checks are stopped as a controller/runtime-evidence failure, "
                    "not a missing user decision.\n"
                    f"Recent failed observations:\n{recent_error_preview or '- none'}\n"
                    "</blocked_internal_contract_error>"
                )
                blocked_consultation = deepcopy(dict(state.get("consultation_state") or {}))
                blocked_consultation.update({
                    "phase": "blocked",
                    "consultation_status": "blocked",
                    "completion_decision": "blocked",
                    "completion_reason": "consultant_execute_repair_exhausted",
                })
                output.print_once(
                    "consultant_execute_loop_guard_internal_block",
                    "⚠️ Consultant read-only checks failed repeatedly; stopping as an internal/runtime-evidence failure.",
                    Fore.YELLOW,
                )
                return {
                    "messages": [SystemMessage(content=obs)],
                    "consultation_state": blocked_consultation,
                    "pending_human_question": {},
                    "contract_status": "blocked_internal_contract_error",
                    "next_step": "finish",
                }

            kb_list_desc = ", ".join(KB_MAP.keys())
            input_roles = discovery_input_roles(
                input_audit=input_resolution_result,
                task_spec=task_spec,
            )
            candidate_skill_ids: List[str] = []
            candidate_skill_cards: List[Dict[str, Any]] = []
            skill_tree = ""
            skill_catalog = ""
            preloaded_skill_docs = ""
            preloaded_skill_docs_context = ""
            observed_skill_mentions: List[str] = []
            if self.skill_manager:
                # Literal canonical IDs are observable prompt evidence only.
                # The Controller must not use raw text as a discovery query,
                # load the document, select the Skill, or seed a runtime row.
                observed_skill_mentions = (
                    self.skill_manager.observed_canonical_skill_mentions(
                        consultant_context
                    )
                )
                discovery_state = record_observed_skill_mentions(
                    discovery_state,
                    observed_skill_mentions,
                )
                with preprocess_recorder.phase(
                    "skill_ranking", cache_hit=bool(
                        discovery_state.get("search_history")
                    )
                ) as phase_stats:
                    phase_stats["call_count"] = 0
                    for ref in discovery_state.get("candidate_skill_refs") or []:
                        if not isinstance(ref, Mapping):
                            continue
                        skill_id = str(ref.get("skill_id") or "")
                        card = self.skill_manager.skill_discovery_card(
                            skill_id,
                            score=int(ref.get("deterministic_score") or 0),
                            reasons=list(
                                (discovery_state.get("candidate_evidence") or {})
                                .get(skill_id, {})
                                .get("reasons", [])
                            ),
                            matched_metadata_fields=list(
                                ref.get("matched_metadata_fields") or []
                            ),
                            source_query_id=str(ref.get("source_query_id") or ""),
                            document_loaded=bool(ref.get("document_loaded")),
                        )
                        if card:
                            candidate_skill_cards.append(card)
                    phase_stats["candidate_count"] = len(candidate_skill_cards)
                candidate_skill_ids = [
                    str(card.get("skill_id") or "")
                    for card in candidate_skill_cards
                    if str(card.get("skill_id") or "")
                ]
                pending_candidate_id = str(
                    pending_task_skill_context.get("candidate_skill_id") or ""
                )
                if pending_candidate_id and pending_candidate_id not in candidate_skill_ids:
                    pending_card = self.skill_manager.skill_discovery_card(
                        pending_candidate_id,
                        score=0,
                        reasons=["consultant_reviewed_binding_candidate"],
                    )
                    if pending_card:
                        candidate_skill_cards.append(pending_card)
                    candidate_skill_ids.append(pending_candidate_id)
                with preprocess_recorder.phase("skill_catalog") as phase_stats:
                    if candidate_skill_cards:
                        skill_catalog = self.skill_manager.format_skill_discovery_cards(
                            candidate_skill_cards
                        )
                    else:
                        skill_catalog = (
                            "<skill_catalog>\n"
                            "No Consultant-requested search result exists yet. Form a semantic intent "
                            "and issue SEARCH_SKILLS, or directly LOAD_SKILL_DOC for an observed exact "
                            "canonical ID.\n"
                            "</skill_catalog>"
                        )
                    phase_stats["candidate_count"] = len(candidate_skill_cards)
                    phase_stats["output_chars"] = len(skill_catalog)
            else:
                skill_catalog = "None"
                preprocess_recorder.mark("skill_ranking", call_count=0)
            consultation_state["skill_discovery"] = discovery_state
            runtime_phase_started = time.perf_counter()
            runtime_discovery_hints: Dict[str, Any] = {}
            controlled_discovery_hints = ""
            # Runtime discovery is post-selection machine evidence. Candidate
            # metadata may say whether a runtime is declared, but no preflight
            # is run and no runtime row is created before Consultant selection.
            runtime_evidence_context = self._consultant_runtime_context(
                list(state.get("selected_skills") or [])
            )
            consultation_state["iteration"] = int(consultation_state.get("iteration") or 0) + 1
            loaded_skill_ids = list(verified_loaded_skill_ids)
            for skill_id in loaded_skill_ids:
                if skill_id in set(discovery_state.get("loaded_skill_ids") or []):
                    continue
                document = self.skill_manager.load_skill(skill_id) if self.skill_manager else ""
                meta = self.skill_manager.get_skill_meta(skill_id) if self.skill_manager else {}
                discovery_state = record_loaded_skill_doc(
                    discovery_state,
                    skill_id=skill_id,
                    path=str((meta or {}).get("_skill_md") or ""),
                    document=document,
                    summary=str((meta or {}).get("summary") or (meta or {}).get("description") or ""),
                    document_digest=str(
                        (meta or {}).get("_skill_content_hash") or ""
                    ),
                )
            current_selected_skill_ids = list(dict.fromkeys([
                *list(state.get("selected_skills") or []),
                *list(discovery_state.get("selected_skill_ids") or []),
            ]))
            consultation_state["skill_discovery"] = discovery_state
            runtime_seed_skill_ids = list(current_selected_skill_ids)
            runtime_seed_audits, runtime_seed_evidence, _runtime_seed_summary = (
                self._consultant_runtime_seed_evidence(runtime_seed_skill_ids, task_id)
                if runtime_seed_skill_ids
                else ([], {}, "")
            )
            preprocess_recorder.mark(
                "runtime_evidence",
                elapsed_ms=(time.perf_counter() - runtime_phase_started) * 1000,
                call_count=1,
                candidate_count=len(runtime_seed_skill_ids),
                audit_count=len(runtime_seed_audits),
            )
            discovery_projection_started = time.perf_counter()
            consultation_state = seed_structured_evidence(
                consultation_state,
                input_audit=input_resolution_result,
                candidate_skill_ids=runtime_seed_skill_ids,
                routing_candidate_ids=current_selected_skill_ids,
                runtime_evidence=runtime_seed_evidence,
            )
            preprocess_recorder.mark(
                "discovery_projection",
                elapsed_ms=(time.perf_counter() - discovery_projection_started) * 1000,
                call_count=1,
                discovery_round=int(discovery_state.get("normal_search_count") or 0),
                loaded_skill_count=len(discovery_state.get("loaded_skill_ids") or []),
            )
            continuation_cache = build_continuation_cache(
                identity=continuation_identity,
                base=continuation_base,
                prior=prior_continuation,
                cache_hit=bool(cache_decision.get("cache_hit")),
            )
            continuation_cache.update({
                "invocation_count": continuation_invocation,
                "last_cache_reason": str(cache_decision.get("reason") or ""),
                "discovery_delta": consultant_discovery_delta(discovery_state),
                "archive_telemetry": archive_telemetry,
            })
            consultation_state["discovery_continuation"] = continuation_cache
            # Do not enter FINALIZE from the pre-response state.  Candidate
            # mutations, selected skills and Controller bindings must be
            # applied before completion is evaluated.
            finalize_mode = bool(contract_repair_state) or consultation_state.get("phase") == "finalize"
            if isinstance(consultation_state.get("finalize_protocol"), Mapping):
                finalize_mode = True
            loop_guard_exhausted = bool(
                self.skill_manager
                and (
                    len(load_actions) >= CONSULTANT_LOAD_ACTION_LOOP_LIMIT
                    or len(internal_validation_errors) >= CONSULTANT_INTERNAL_VALIDATION_ERROR_LIMIT
                    or len(load_errors) >= CONSULTANT_LOAD_ERROR_LOOP_LIMIT
                    or len(format_repair_errors) > CONSULTANT_PARSE_REPAIR_LIMIT
                )
            )
            if not finalize_mode and loop_guard_exhausted:
                selected = self.skill_manager.normalize_selected_skills(
                    loaded_skill_ids,
                    max_results=consultant_max_skills,
                )
                if selected:
                    unresolved = list(consultation_state.get("unresolved_requirement_ids") or [])
                    reason = (
                        "Consultant action repair was exhausted after canonical skill loading, but "
                        "controller-owned evidence is still unresolved. This is an internal protocol "
                        "or runtime-evidence failure, not a missing user decision. "
                        f"selected_skills={','.join(selected)}; unresolved={','.join(unresolved) or 'unknown'}"
                    )
                    blocked_consultation = deepcopy(consultation_state)
                    blocked_consultation.update({
                        "phase": "blocked",
                        "consultation_status": "blocked",
                        "completion_decision": "blocked",
                        "completion_reason": "internal_action_contract_or_runtime_evidence_failure",
                        "resolved_selected_skill_ids": list(selected),
                    })
                    output.print_once(
                        "consultant_loop_guard_internal_block",
                        "⚠️ Consultant repair budget exhausted after a canonical skill was verified; stopping as an internal failure without asking the user.",
                        Fore.YELLOW,
                    )
                    return {
                        "messages": [SystemMessage(content=(
                            '<blocked_internal_contract_error code="CONSULTANT_ACTION_REPAIR_EXHAUSTED">'
                            + reason
                            + "</blocked_internal_contract_error>"
                        ))],
                        "input_audit": input_resolution_result,
                        "selected_skills": list(selected),
                        "runtime_audit": runtime_seed_audits,
                        "consultation_state": blocked_consultation,
                        "pending_human_question": {},
                        "contract_status": "blocked_internal_contract_error",
                        "next_step": "finish",
                    }

                reason = (
                    "Consultant action repair was exhausted before a canonical skill was successfully "
                    "selected. This is an internal action-contract failure, not a user ambiguity. "
                    "The Controller did not derive candidate IDs from the raw prompt."
                )
                blocked_consultation = deepcopy(consultation_state)
                blocked_consultation.update({
                    "phase": "blocked",
                    "consultation_status": "blocked",
                    "completion_decision": "blocked",
                    "completion_reason": "consultant_action_repair_exhausted_without_canonical_skill",
                })
                output.print_once(
                    "consultant_loop_guard_internal_block_no_skill",
                    "⚠️ Consultant action repair exhausted before canonical skill verification; stopping without asking the user.",
                    Fore.YELLOW,
                )
                return {
                    "messages": [SystemMessage(content=(
                        '<blocked_internal_contract_error code="CONSULTANT_ACTION_REPAIR_EXHAUSTED">'
                        + reason
                        + "</blocked_internal_contract_error>"
                    ))],
                    "input_audit": input_resolution_result,
                    "consultation_state": blocked_consultation,
                    "pending_human_question": {},
                    "contract_status": "blocked_internal_contract_error",
                    "next_step": "finish",
                }
            discovery_escalated = False
            if finalize_mode:
                resolved_selected_skill_ids = self._resolve_consultant_finalize_skills(
                    state=state,
                    consultation_state=consultation_state,
                    max_skills=consultant_max_skills,
                )
                if resolved_selected_skill_ids:
                    consultation_state["resolved_selected_skill_ids"] = list(
                        resolved_selected_skill_ids
                    )
                return await self._run_consultant_finalize(
                    state=state,
                    task_id=task_id,
                    task_spec=task_spec,
                    consultation_state=consultation_state,
                    resolved_selected_skill_ids=resolved_selected_skill_ids,
                    input_audit=input_resolution_result,
                    consultant_wiki_context=consultant_wiki_context,
                    consultant_memory_retrieval_context=consultant_memory_retrieval_context,
                )
            prompt_build_started = time.perf_counter()
            deterministic_base_constraints = semantic_constraints_from_task_spec(task_spec)
            provenance_catalog = semantic_provenance_catalog(
                task_spec,
                consultation_state=consultation_state,
                selected_skill_ids=[
                    *candidate_skill_ids,
                    *loaded_skill_ids,
                    *list(state.get("selected_skills") or []),
                ],
            )
            deterministic_base_constraints_context = json.dumps(
                deterministic_base_constraints,
                ensure_ascii=False,
                sort_keys=True,
                indent=2,
                default=str,
            )
            semantic_provenance_catalog_context = json.dumps(
                provenance_catalog,
                ensure_ascii=False,
                sort_keys=True,
                indent=2,
                default=str,
            )
            selected_skill_context = json.dumps({
                "candidate_skill_ids": candidate_skill_ids,
                "observed_skill_mentions": observed_skill_mentions,
                "loaded_skill_ids": loaded_skill_ids,
                "current_selected_skill_ids": list(state.get("selected_skills") or []),
                "workflow_candidate_ids": workflow_candidate_ids,
            }, ensure_ascii=False, sort_keys=True, indent=2, default=str)
            contract_repair_context = self._consultant_contract_repair_context(
                contract_repair_state
            )
            consultation_state_context = consultation_prompt_context(consultation_state)
            rag_history_text = "\n".join(str(item) for item in rag_history)
            task_spec_context = format_effective_user_facts_context(
                task_spec,
                audience="consultant",
                max_chars=CONSULTANT_HISTORY_CHAR_BUDGET,
                include_task_goal=not any(isinstance(message, HumanMessage) for message in messages),
            )
            if "CONTEXT_BUDGET_UNSATISFIED" in task_spec_context:
                reason = (
                    "CONSULTANT_CONTEXT_BUDGET_UNSATISFIED: the lossless canonical user "
                    "contract exceeds the configured 100k-token history pool."
                )
                logger.error("%s task=%s", reason, task_id)
                return {
                    "messages": [SystemMessage(content=reason)],
                    "plan_progress": self._mark_plan_current_blocked(task_id, reason),
                    "next_step": "finish",
                }

            pool_budgets = self._consultant_effective_pool_budgets(
                self.llm_context_limit_tokens
            )
            dynamic_marker = "__CONSULTANT_DYNAMIC_BLOCK__"
            if finalize_mode:
                static_probe = PromptManager.get_consultant_finalize_prompt(
                    work_dir=self.pm.work_dir if self.pm else ".",
                    max_skills=consultant_max_skills,
                    consultation_state_context=dynamic_marker,
                    task_spec_context=dynamic_marker,
                    input_resolution_context=dynamic_marker,
                    runtime_evidence_context=dynamic_marker,
                    selected_skill_context=dynamic_marker,
                    deterministic_base_constraints_context=dynamic_marker,
                    semantic_provenance_catalog_context=dynamic_marker,
                    contract_repair_context=dynamic_marker,
                )
            else:
                static_probe = PromptManager.get_consultant_prompt(
                    intent=str(state.get("task_mode") or "managed"),
                    kb_list_desc=kb_list_desc,
                    rag_history=[dynamic_marker],
                    skills_summary=dynamic_marker,
                    runtime_evidence_context=dynamic_marker,
                    work_dir=self.pm.work_dir if self.pm else ".",
                    max_skills=consultant_max_skills,
                    wiki_memory_context=dynamic_marker,
                    input_resolution_context=dynamic_marker,
                    workflow_catalog=dynamic_marker,
                    user_preferences_context=dynamic_marker,
                    task_spec_context=dynamic_marker,
                    consultation_state_context=dynamic_marker,
                )
            dynamic_slots = static_probe.count(dynamic_marker)
            static_prompt_chars = (
                len(static_probe)
                - dynamic_slots * len(dynamic_marker)
                + dynamic_slots * len("None")
            )
            if finalize_mode:
                static_token_probe = PromptManager.get_consultant_finalize_prompt(
                    work_dir=self.pm.work_dir if self.pm else ".",
                    max_skills=consultant_max_skills,
                    consultation_state_context="None",
                    task_spec_context="None",
                    input_resolution_context="None",
                    runtime_evidence_context="None",
                    selected_skill_context="None",
                    deterministic_base_constraints_context="None",
                    semantic_provenance_catalog_context="None",
                    contract_repair_context="None",
                )
                packing_messages = [
                    message for message in messages
                    if not (
                        isinstance(message, SystemMessage)
                        and any(tag in str(message.content) for tag in (
                            "<loaded_skill_doc",
                            "<loaded_skill_reference",
                            "<loaded_skill_script",
                        ))
                    )
                ]
                history_components = {
                    "task_spec": task_spec_context,
                    "input_resolution": input_resolution_context,
                    "selected_skill_context": selected_skill_context,
                    "deterministic_base_constraints": deterministic_base_constraints_context,
                    "semantic_provenance_catalog": semantic_provenance_catalog_context,
                    "contract_repair": contract_repair_context,
                }
                skill_components = {
                    "runtime_evidence": runtime_evidence_context,
                }
            else:
                # V2 Consultant gets a deterministic NodeContext plus the
                # bounded semantic capability catalog built below.  Running
                # the legacy history/doc packer here could block a valid call
                # because of material that is not sent to the model at all.
                static_token_probe = ""
                packing_messages = []
                history_components = {}
                skill_components = {}
            static_prompt_tokens = _consultant_estimate_text_tokens(static_token_probe)
            try:
                (
                    packed_history,
                    packed_skills,
                    consultant_visible_messages,
                    consultant_pack_report,
                ) = self._pack_consultant_context(
                    packing_messages,
                    history_components=history_components,
                    skill_components=skill_components,
                    history_max_chars=pool_budgets["history_effective_chars"],
                    skill_max_chars=pool_budgets["skill_effective_chars"],
                    static_prompt_chars=static_prompt_chars,
                    history_max_tokens=pool_budgets["history_effective_tokens"],
                    skill_max_tokens=pool_budgets["skill_effective_tokens"],
                    static_prompt_tokens=static_prompt_tokens,
                    max_messages=CONSULTANT_HISTORY_MAX_MESSAGES,
                )
            except RequiredContextOverflow as exc:
                reason = (
                    "CONSULTANT_CONTEXT_BUDGET_UNSATISFIED: required user authority or "
                    f"complete selected-skill documentation cannot fit safely. {exc}"
                )
                logger.error(
                    "%s task=%s report=%s",
                    reason,
                    task_id,
                    json.dumps(exc.report, ensure_ascii=False, sort_keys=True),
                )
                return {
                    "messages": [SystemMessage(content=reason)],
                    "plan_progress": self._mark_plan_current_blocked(task_id, reason),
                    "next_step": "finish",
                }

            if finalize_mode:
                task_spec_context = packed_history.get("task_spec") or "None"
                input_resolution_context = packed_history.get("input_resolution") or "None"
                selected_skill_context = packed_history.get("selected_skill_context") or selected_skill_context
                deterministic_base_constraints_context = (
                    packed_history.get("deterministic_base_constraints")
                    or deterministic_base_constraints_context
                )
                semantic_provenance_catalog_context = (
                    packed_history.get("semantic_provenance_catalog")
                    or semantic_provenance_catalog_context
                )
                contract_repair_context = packed_history.get("contract_repair") or contract_repair_context
                user_preferences_context = packed_history.get("user_preferences") or "None"
                consultant_memory_retrieval_context = packed_history.get("memory_context") or "None"
                rag_history_text = packed_history.get("rag_history") or "None"
                workflow_catalog = packed_skills.get("workflow_catalog") or "None"
                skill_catalog = packed_skills.get("skill_catalog") or ""
                skill_tree = packed_skills.get("skill_tree") or ""
                controlled_discovery_hints = packed_skills.get("controlled_discovery_hints") or ""
                preloaded_skill_docs_context = packed_skills.get("preloaded_skill_docs") or ""
                runtime_evidence_context = packed_skills.get("runtime_evidence") or "None"
            rag_history_for_prompt = [rag_history_text or "None"]
            skills_summary = "\n".join(
                value
                for value in (
                    skill_catalog,
                    skill_tree,
                    controlled_discovery_hints,
                    preloaded_skill_docs_context,
                )
                if value
            ) or "None"

            # Formerly: consultant_visible_messages = self._step_local_messages(
            # That generic selector hid original Human authority and loaded skill docs.

            if finalize_mode:
                consultant_prompt = PromptManager.get_consultant_finalize_prompt(
                    work_dir=self.pm.work_dir if self.pm else ".",
                    max_skills=consultant_max_skills,
                    consultation_state_context=consultation_state_context,
                    task_spec_context=task_spec_context,
                    input_resolution_context=input_resolution_context,
                    runtime_evidence_context=runtime_evidence_context,
                    selected_skill_context=selected_skill_context,
                    deterministic_base_constraints_context=deterministic_base_constraints_context,
                    semantic_provenance_catalog_context=semantic_provenance_catalog_context,
                    contract_repair_context=contract_repair_context,
                )
            else:
                discovery_projection_render_started = time.perf_counter()
                durable_consultant_state = load_plan_state(self.data_path, task_id)
                durable_consultant_task_state = dict(
                    durable_consultant_state.get("task_state") or {}
                )
                durable_consultation = dict(
                    durable_consultant_task_state.get("consultation_state") or {}
                )
                actionable_feedback = list(
                    consultation_state.get("last_feedback")
                    or durable_consultation.get("last_feedback")
                    or []
                )[-8:]
                durable_reconciliation = dict(
                    durable_consultant_task_state.get("planner_reconciliation")
                    or {}
                )
                durable_reconciliation_ledger = dict(
                    durable_consultant_task_state.get("reconciliation_ledger")
                    or {}
                )
                durable_review_classification = dict(
                    durable_consultant_task_state.get(
                        "pending_review_classification"
                    ) or {}
                )
                visible_capability_ids = self.skill_manager.normalize_selected_skills(
                    [
                        *loaded_skill_ids,
                        *list(state.get("selected_skills") or []),
                        *candidate_skill_ids[:5],
                    ],
                    max_results=consultant_max_skills,
                ) if self.skill_manager else []
                discovery_prompt_state = {
                    "routing_status": discovery_state.get("routing_status"),
                    "reasoning_level": discovery_state.get("reasoning_level"),
                    "task_hypothesis": discovery_state.get("task_hypothesis"),
                    "observed_skill_mentions": list(
                        discovery_state.get("observed_skill_mentions") or []
                    ),
                    "input_roles": list(discovery_state.get("input_roles") or []),
                    "search_queries_attempted": list(
                        discovery_state.get("search_queries_attempted") or []
                    ),
                    "search_history": [
                        {
                            key: deepcopy(item.get(key))
                            for key in (
                                "source", "query", "queries", "category",
                                "candidate_ids", "catalog_digest", "repeated",
                            )
                            if item.get(key) not in (None, "", [], {})
                        }
                        for item in list(discovery_state.get("search_history") or [])[-8:]
                        if isinstance(item, Mapping)
                    ],
                    "candidate_skill_ids": list(visible_capability_ids),
                    "candidate_skill_refs": deepcopy(list(
                        discovery_state.get("candidate_skill_refs") or []
                    )),
                    "loaded_skill_ids": list(discovery_state.get("loaded_skill_ids") or []),
                    "loaded_skill_refs": deepcopy(list(
                        discovery_state.get("loaded_skill_refs") or []
                    )),
                    "selected_skill_refs": deepcopy(list(
                        discovery_state.get("selected_skill_refs") or []
                    )),
                    "excluded_skill_refs": deepcopy(list(
                        discovery_state.get("excluded_skill_refs") or []
                    )),
                    "rejected_candidates": list(discovery_state.get("rejected_candidates") or []),
                    "normal_search_count": int(discovery_state.get("normal_search_count") or 0),
                    "catalog_expansion_count": int(discovery_state.get("catalog_expansion_count") or 0),
                    "reasoning_escalation_count": int(discovery_state.get("reasoning_escalation_count") or 0),
                    "budgets": dict(discovery_state.get("budgets") or {}),
                    "next_actions": discovery_next_actions(discovery_state),
                }
                _, consultant_current_step = current_plan_step_with_index(
                    durable_consultant_state
                )
                consultant_step_id = str(
                    (consultant_current_step or {}).get("step_id") or ""
                )
                consultant_continuation_id = str(
                    durable_consultant_task_state.get("skill_continuation_id")
                    or ""
                )
                consultant_access = normalize_skill_access_state(
                    durable_consultant_task_state.get("skill_access_state")
                    or durable_consultant_state.get("skill_access_state")
                )
                consultant_continuation: Dict[str, Any] = {}
                if consultant_continuation_id:
                    consultant_continuation = dict(
                        (consultant_access.get("continuations") or {}).get(
                            consultant_continuation_id
                        )
                        or {}
                    )
                consultant_skill_projection = self._skill_context_projection(
                    durable_consultant_state,
                    caller_node="consultant",
                    current_step_id=consultant_step_id,
                    continuation_id=consultant_continuation_id,
                )
                if pending_task_skill_context:
                    candidate_headings = {
                        "skill_id": pending_task_skill_context.get(
                            "candidate_skill_id"
                        ),
                        "snapshot_id": pending_task_skill_context.get(
                            "candidate_snapshot_id"
                        ),
                        "heading_index": deepcopy(list(
                            pending_task_skill_context.get(
                                "available_headings"
                            )
                            or []
                        )),
                        "status": "candidate",
                    }
                    consultant_skill_projection[
                        "available_skill_headings"
                    ] = [
                        *list(consultant_skill_projection.get(
                            "available_skill_headings"
                        ) or []),
                        candidate_headings,
                    ]
                    known_excerpt_ids = {
                        str(item.get("excerpt_id") or "")
                        for item in consultant_skill_projection.get(
                            "relevant_skill_excerpts", []
                        ) or []
                        if isinstance(item, Mapping)
                    }
                    consultant_skill_projection[
                        "relevant_skill_excerpts"
                    ] = [
                        *list(consultant_skill_projection.get(
                            "relevant_skill_excerpts"
                        ) or []),
                        *[
                            deepcopy(dict(item))
                            for item in pending_task_skill_context.get(
                                "relevant_skill_excerpts", []
                            ) or []
                            if isinstance(item, Mapping)
                            and str(item.get("excerpt_id") or "")
                            not in known_excerpt_ids
                        ],
                    ]
                consultant_node_context = build_node_context(
                    node_type="consultant",
                    task_spec=task_spec,
                    plan_state=durable_consultant_state,
                    state_generation=int(
                        durable_consultant_state.get("state_generation") or 0
                    ),
                    feedback={
                        "consultation": {
                            key: deepcopy(consultation_state.get(key))
                            for key in (
                                "phase", "consultation_status", "completion_decision",
                                "completion_reason", "unresolved_requirement_ids",
                                "selected_skills", "resolved_selected_skill_ids",
                                "resolved_bindings", "pending_question",
                            )
                            if consultation_state.get(key) not in (None, "", [], {})
                        } | {"skill_discovery": discovery_prompt_state},
                        "last_actionable_feedback": actionable_feedback,
                        # The Consultant sees only semantic work to classify.
                        # Controller fingerprints, revisions, refs, scopes and
                        # approval pointers remain outside LLMPayload.
                        "planner_reconciliation": {
                            key: deepcopy(durable_reconciliation.get(key))
                            for key in (
                                "outcome_type", "missing_semantic_facts", "status",
                            )
                            if durable_reconciliation.get(key) not in (None, "", [], {})
                        },
                        "reconciliation_ledger": {
                            key: deepcopy(durable_reconciliation_ledger.get(key))
                            for key in (
                                "reconciliation_nonprogress_count",
                                "last_consultant_outcome", "terminal_status",
                            )
                            if durable_reconciliation_ledger.get(key) not in (None, "", [], {})
                        },
                        "pending_review_classification": {
                            "classification_required": True,
                            "status": str(
                                durable_review_classification.get("status")
                                or "pending_consultant_classification"
                            ),
                        } if durable_review_classification else {},
                        "pending_task_skill_change": deepcopy(
                            pending_task_skill_context
                        ),
                        "conversation_turn_count": len(conversation_turns),
                        "formal_input_audit": {
                            "status": str(input_resolution_result.get("status") or "not_applicable"),
                            "artifact_role": str(input_resolution_result.get("artifact_role") or ""),
                            "unresolved": bool(input_resolution_result.get("unresolved")),
                            "unresolved_reasons": list(input_resolution_result.get("unresolved_reasons") or []),
                            "missing_roles": list(input_resolution_result.get("missing_roles") or []),
                            "ambiguous_roles": list(input_resolution_result.get("ambiguous_roles") or []),
                            "resolved_input_roles": list(input_roles),
                            "candidate_basenames": sorted({
                                Path(str(item.get("path") or "")).name
                                for item in input_resolution_result.get("formal_candidates", []) or []
                                if isinstance(item, Mapping) and str(item.get("path") or "")
                            }),
                        },
                        "runtime_checks": deepcopy(runtime_seed_audits),
                    },
                    evidence=semantic_conversation_evidence,
                    allowed_operations=[
                        "set_goal", "upsert_input", "remove_input",
                        "upsert_constraint", "remove_constraint",
                        "upsert_output_contract", "remove_output_contract",
                        "confirm_decision", "remove_decision", "mark_ambiguity",
                        "search_skills", "list_skill_categories", "list_skills",
                        "load_skill_doc", "reject_skill", "select_skill", "reasoning_escalation",
                        "capability_gap", "ask_user", "finish",
                        REQUEST_SKILL_CONTEXT, SEARCH_SKILLS,
                        PROPOSE_SKILL_BINDING,
                    ],
                    current_step_id=consultant_step_id,
                    authoritative_user_turn_revision=(
                        self._authoritative_user_turn_revision(
                            durable_consultant_state
                        )
                    ),
                    skill_context=consultant_skill_projection,
                    continuation_id=consultant_continuation_id,
                    touched_entity_versions=dict(
                        state.get("task_entity_versions") or {}
                    ),
                    trace_enabled=bool(os.getenv("NODE_CONTEXT_V2_TRACE", "")),
                    max_payload_chars=max(1, int(self.llm_context_limit_tokens) * 4),
                )
                if (
                    consultant_continuation_id
                    and str(consultant_continuation.get("caller_node") or "")
                    == "consultant"
                    and str(consultant_continuation.get("status") or "")
                    in {"served", "rejected"}
                ):
                    consultant_access = mark_continuation_resumed(
                        consultant_access,
                        consultant_continuation_id,
                        resumed_invocation_id=(
                            consultant_node_context.binding.invocation_id
                        ),
                    )
                    try:
                        self._persist_durable_skill_access(
                            task_id,
                            consultant_access,
                            continuation_id=consultant_continuation_id,
                            expected_state_generation=int(
                                durable_consultant_state.get(
                                    "state_generation"
                                )
                                or 0
                            ),
                        )
                    except StateCASConflict as exc:
                        return self._skill_access_cas_stale_update(
                            caller_node="consultant",
                            next_step="consultant",
                            detail=str(exc),
                        )
                semantic_capabilities, _consultant_operation_bindings = (
                    self.skill_manager.get_semantic_execution_capabilities(
                        visible_capability_ids
                    )
                    if self.skill_manager
                    else ([], {})
                )
                visible_candidate_cards = [
                    dict(card) for card in candidate_skill_cards
                    if str(card.get("skill_id") or "") in set(visible_capability_ids)
                ]
                loaded_skill_documents: Dict[str, str] = {}
                pending_injection_ids = list(
                    discovery_state.get("pending_document_injection_ids") or []
                )[:5]
                for skill_id in pending_injection_ids:
                    document = self.skill_manager.load_skill(skill_id) if self.skill_manager else ""
                    if document:
                        meta = self.skill_manager.get_skill_meta(skill_id) or {}
                        current_digest = str(meta.get("_skill_content_hash") or "")
                        stored_digest = str(
                            (
                                (discovery_state.get("loaded_skill_docs") or {}).get(skill_id)
                                or {}
                            ).get("document_digest")
                            or ""
                        )
                        if current_digest and current_digest != stored_digest:
                            discovery_state = record_loaded_skill_doc(
                                discovery_state,
                                skill_id=skill_id,
                                path=str(meta.get("_skill_md") or ""),
                                document=document,
                                summary=str(
                                    meta.get("summary")
                                    or meta.get("description")
                                    or ""
                                ),
                                loaded_at_revision=task_spec_revision(task_spec),
                                document_digest=current_digest,
                            )
                        loaded_skill_documents[skill_id] = document
                if loaded_skill_documents:
                    injected = dict(
                        discovery_state.get("injected_document_digests") or {}
                    )
                    loaded_meta = dict(
                        discovery_state.get("loaded_skill_docs") or {}
                    )
                    for skill_id in loaded_skill_documents:
                        injected[skill_id] = str(
                            (loaded_meta.get(skill_id) or {}).get(
                                "document_digest"
                            )
                            or ""
                        )
                    discovery_state["injected_document_digests"] = injected
                    discovery_state["pending_document_injection_ids"] = [
                        skill_id
                        for skill_id in discovery_state.get(
                            "pending_document_injection_ids"
                        ) or []
                        if skill_id not in loaded_skill_documents
                    ]
                    consultation_state["skill_discovery"] = discovery_state
                consultant_capability_context = json.dumps(
                    {
                        "capabilities": semantic_capabilities,
                        "discovery_state": discovery_prompt_state,
                        "discovery_cards": visible_candidate_cards,
                        "loaded_skill_documents": loaded_skill_documents,
                        "catalog": [
                            {
                                "skill_id": str(meta.get("_skill_id") or ""),
                                "name": str(meta.get("name") or ""),
                                "description": str(meta.get("description") or ""),
                                "task_types": self.skill_manager.metadata_list(meta, "task_types"),
                                "stage_tags": self.skill_manager.metadata_list(meta, "stage_tags"),
                                "inputs": self.skill_manager.metadata_list(meta, "inputs"),
                                "outputs": self.skill_manager.metadata_list(meta, "outputs"),
                            }
                            for meta in (
                                self.skill_manager.get_skill_meta(skill_id)
                                for skill_id in visible_capability_ids
                            )
                            if meta
                        ],
                        "workflow_candidates": list(workflow_candidate_ids),
                        "continuation_context": {
                            "policy": (
                                "Stable episode facts are reused only while conversation, "
                                "TaskSpec semantics, formal bindings, ownership and input inventory match. "
                                "Discovery decisions below are always current-round facts."
                            ),
                            "episode_id": str(continuation_identity.get("episode_id") or ""),
                            "invocation": continuation_invocation,
                            "cache_hit": bool(cache_decision.get("cache_hit")),
                            "cache_reason": str(cache_decision.get("reason") or ""),
                            "memory_context": consultant_memory_retrieval_context,
                            "input_resolution_context": input_resolution_context,
                            "workflow_catalog": workflow_catalog,
                            "user_preferences": user_preferences_context,
                            "rag_history": rag_history_text,
                            "archive_telemetry": archive_telemetry,
                            "discovery_delta": consultant_discovery_delta(discovery_state),
                        },
                    },
                    ensure_ascii=False,
                    sort_keys=True,
                    indent=2,
                    default=str,
                )
                preprocess_recorder.mark(
                    "discovery_projection",
                    elapsed_ms=(time.perf_counter() - discovery_projection_render_started) * 1000,
                    call_count=1,
                    visible_candidate_count=len(visible_candidate_cards),
                    loaded_document_count=len(loaded_skill_documents),
                )
                discovery_escalated = bool(
                    discovery_state.get("reasoning_level") == "escalated"
                    and discovery_state.get("routing_status")
                    not in {SELECTED, CAPABILITY_GAP, "NEED_USER_CLARIFICATION"}
                )
                if discovery_escalated:
                    escalation_context = build_discovery_escalation_context(
                        raw_user_request=consultant_context,
                        task_spec=task_spec,
                        input_inventory=input_resolution_result,
                        discovery_state=discovery_state,
                        candidate_cards=visible_candidate_cards,
                    )
                    consultant_prompt = PromptManager.get_consultant_discovery_escalation_prompt(
                        escalation_context,
                        loaded_skill_documents=loaded_skill_documents,
                        max_skills=consultant_max_skills,
                    )
                else:
                    consultant_prompt = PromptManager.get_consultant_v2_prompt(
                        consultant_node_context.llm_payload.to_dict(),
                        capability_context=consultant_capability_context,
                        consultation_context="Current semantic consultation state is included in LLMPayload.feedback.",
                        max_skills=consultant_max_skills,
                    )
                # Full semantic conversation is carried once, inside the
                # payload evidence section.  Graph history is intentionally
                # omitted so it cannot duplicate or replace that durable view.
                consultant_visible_messages = []
            preprocess_recorder.mark(
                "prompt_build",
                elapsed_ms=(time.perf_counter() - prompt_build_started) * 1000,
                call_count=1,
                prompt_chars=len(consultant_prompt),
            )
            prompt_serialize_started = time.perf_counter()
            visible_message_chars = sum(
                len(str(getattr(message, "content", message) or ""))
                for message in consultant_visible_messages
            )
            history_message_chars = sum(
                int(block.get("final_chars") or 0)
                for block in consultant_pack_report["history"].get("blocks", [])
                if str(block.get("id") or "").startswith("history_message:")
            )
            skill_message_chars = sum(
                int(block.get("final_chars") or 0)
                for block in consultant_pack_report["skills"].get("blocks", [])
                if str(block.get("id") or "").startswith("skill_message:")
            )
            prompt_chars = len(consultant_prompt) + visible_message_chars
            consultant_prompt_accounting = {
                "assembled_prompt_chars": prompt_chars,
                "component_chars": {
                    "assembled_system_prompt": len(consultant_prompt),
                    "visible_messages": visible_message_chars,
                },
                "inclusive_subcomponent_chars": {
                "skill_tree": len(skill_tree),
                "candidate_skill_catalog": len(skill_catalog),
                "workflow_catalog": len(workflow_catalog),
                "runtime_evidence": len(runtime_evidence_context),
                "memory_context": len(consultant_memory_retrieval_context),
                "input_resolution": len(input_resolution_context),
                "rag_history": len(rag_history_text),
                "user_preferences": len(user_preferences_context),
                },
                "candidate_skill_count": len(visible_capability_ids),
                "retrieved_candidate_skill_count": len(candidate_skill_ids),
                "preloaded_skill_doc_chars": len(preloaded_skill_docs_context),
                "history_message_chars": history_message_chars,
                "skill_message_chars": skill_message_chars,
                "pool_budgets": pool_budgets,
                "pack_report": consultant_pack_report,
                "component_accounting": "component_chars are non-overlapping; inclusive_subcomponent_chars are children of assembled_system_prompt",
            }
            logger.info(
                "Consultant prompt components: task=%s %s",
                task_id,
                json.dumps(consultant_prompt_accounting, ensure_ascii=False, sort_keys=True),
            )
            effective_prompt_budget_chars = (
                pool_budgets["effective_input_tokens"]
                * CONSULTANT_ESTIMATED_CHARS_PER_TOKEN
            )
            if prompt_chars > effective_prompt_budget_chars:
                logger.warning(
                    "Consultant prompt exceeds warning budget: task=%s chars=%s warning=%s",
                    task_id,
                    prompt_chars,
                    effective_prompt_budget_chars,
                )

            consultant_llm_messages = [
                SystemMessage(content=consultant_prompt),
                *consultant_visible_messages,
            ]
            consultant_budget = assess_prompt_budget(
                consultant_llm_messages,
                component_chars=consultant_prompt_accounting["component_chars"],
                context_limit_tokens=self.llm_context_limit_tokens,
                nominal_char_budget=effective_prompt_budget_chars,
                compressible_chars=sum(
                    len(value)
                    for value in (
                        consultant_memory_retrieval_context,
                        rag_history_text,
                        workflow_catalog,
                        runtime_evidence_context,
                    )
                ),
                noncompressible_chars=max(
                    0,
                    prompt_chars
                    - sum(
                        len(value)
                        for value in (
                            consultant_memory_retrieval_context,
                            rag_history_text,
                            workflow_catalog,
                            runtime_evidence_context,
                        )
                    ),
                ),
                soft_warning_ratio=0.75,
                compression_ratio=0.90,
                hard_safety_ratio=1.0,
                reserved_headroom_tokens=CONSULTANT_RESERVED_HEADROOM_TOKENS,
            )
            consultant_token_estimate = sum(
                _consultant_estimate_text_tokens(
                    str(getattr(message, "content", message) or "")
                ) + 4
                for message in consultant_llm_messages
            )
            consultant_safe_input_tokens = max(
                1,
                int(self.llm_context_limit_tokens)
                - min(
                    CONSULTANT_RESERVED_HEADROOM_TOKENS,
                    max(0, int(self.llm_context_limit_tokens) - 1),
                ),
            )
            legacy_estimator_hard_block = bool(consultant_budget.get("hard_block"))
            accurate_hard_block = consultant_token_estimate > consultant_safe_input_tokens
            consultant_budget.update({
                "consultant_tokenizer": _consultant_tokenizer_name(),
                "consultant_estimated_input_tokens": consultant_token_estimate,
                "consultant_safe_input_tokens": consultant_safe_input_tokens,
                "pool_pack_report": consultant_pack_report,
                "legacy_char_estimator_hard_block": legacy_estimator_hard_block,
                "hard_block": accurate_hard_block,
                "decision": "block_context_safety" if accurate_hard_block else "no_compression",
            })
            preprocess_recorder.mark(
                "prompt_serialize",
                elapsed_ms=(time.perf_counter() - prompt_serialize_started) * 1000,
                call_count=1,
                prompt_chars=prompt_chars,
                estimated_input_tokens=consultant_token_estimate,
            )
            consultant_preprocess_total = self._flush_consultant_preprocess_trace(
                task_id,
                preprocess_recorder,
            )
            if consultant_budget["hard_block"]:
                reason = (
                    "CONSULTANT_CONTEXT_BUDGET_UNSATISFIED: estimated input is "
                    f"{consultant_budget['consultant_estimated_input_tokens']} / "
                    f"{consultant_budget['context_limit_tokens']} tokens with "
                    f"{max(0, consultant_budget['context_limit_tokens'] - consultant_budget['consultant_estimated_input_tokens'])} "
                    "tokens remaining. "
                    "The current user request and canonical contract were not silently truncated."
                )
                logger.error("%s task=%s", reason, task_id)
                plan_progress = self._mark_plan_current_blocked(task_id, reason)
                return {
                    "messages": [SystemMessage(content=reason)],
                    "plan_progress": plan_progress,
                    "consultation_state": consultation_state,
                    "next_step": "finish",
                }

            if not finalize_mode:
                no_progress = consultant_no_progress_decision(
                    consultation_state.get("last_invocation_guard"),
                    task_revision=task_spec_revision(task_spec),
                    conversation_turn_count=len(conversation_turns),
                    feedback=[
                        *actionable_feedback,
                        *([{
                            "code": "SKILL_CONTINUATION_READY",
                            "continuation_id": consultant_continuation_id,
                        }] if consultant_continuation_id else []),
                        *([{
                            "code": "TASK_SKILL_CHANGE_PENDING_MAIN_COMMIT",
                            "candidate_skill_id": str(
                                pending_task_skill_context.get(
                                    "candidate_skill_id"
                                )
                                or ""
                            ),
                        }] if pending_task_skill_context else []),
                    ],
                    route="consultant",
                    discovery_state=discovery_state,
                )
                if not no_progress.get("allow"):
                    reason = (
                        "CONSULTANT_NO_PROGRESS: the same task revision, conversation evidence, "
                        "controller feedback, and Consultant route would be invoked again."
                    )
                    blocked = deepcopy(consultation_state)
                    blocked.update({
                        "phase": "blocked",
                        "consultation_status": "blocked",
                        "completion_decision": "blocked",
                        "completion_reason": "CONSULTANT_NO_PROGRESS",
                    })
                    return {
                        "messages": [SystemMessage(content=reason)],
                        "consultation_state": blocked,
                        "pending_human_question": {},
                        "task_status": TASK_STATUS_BLOCKED,
                        "failure_owner": "controller",
                        "next_step": "finish",
                    }
                current_invocation_guard = dict(no_progress.get("guard") or {})
            else:
                current_invocation_guard = {}

            self._record_consultant_progress(
                task_id,
                code="CONSULTANT_CONTEXT_READY",
                message="Consultant context is ready; requesting the next discovery decision.",
                detail={
                    "episode_id": str(continuation_identity.get("episode_id") or ""),
                    "invocation": continuation_invocation,
                    "cache_hit": bool(cache_decision.get("cache_hit")),
                    "preprocess_ms": float(
                        consultant_preprocess_total.get("elapsed_ms") or 0.0
                    ),
                    "input_status": str(input_resolution_result.get("status") or "not_applicable"),
                    "candidate_count": len(candidate_skill_ids),
                    "loaded_skill_count": len(discovery_state.get("loaded_skill_ids") or []),
                },
            )
            output.print_once(
                f"consultant_context_ready:{task_id}:{continuation_invocation}",
                "🧭 Consultant context ready; evaluating the next skill-discovery step.",
                Fore.CYAN,
            )
            try:
                response = await self._ainvoke_node_llm(
                    consultant_llm_messages,
                    node_context=consultant_node_context,
                    stage="consultant",
                    task_id=task_id,
                    task_mode=str(state.get("task_mode") or "managed"),
                    trace_metadata={
                        "call_kind": (
                            "consultant_contract_repair"
                            if contract_repair_state
                            else "consultant_finalize" if finalize_mode
                            else "consultant_skill_discovery_escalation" if discovery_escalated
                            else "consultant"
                        ),
                        "task_spec_revision": task_spec_revision(task_spec),
                        "consultant_continuation": {
                            "episode_id": str(continuation_identity.get("episode_id") or ""),
                            "invocation": continuation_invocation,
                            "cache_hit": bool(cache_decision.get("cache_hit")),
                            "cache_reason": str(cache_decision.get("reason") or ""),
                            "preprocess_total": consultant_preprocess_total,
                            "preprocess_phases": preprocess_recorder.phase_rows(),
                            "archive_telemetry": archive_telemetry,
                        },
                        "effective_facts_revision": str(state.get("effective_user_facts_revision") or ""),
                        "candidate_skill_ids": visible_capability_ids,
                        "retrieved_candidate_skill_ids": candidate_skill_ids,
                        "selected_skill_ids": list(state.get("selected_skills") or []),
                        "skill_discovery": {
                            "discovery_round": int(discovery_state.get("normal_search_count") or 0),
                            "reasoning_level": str(discovery_state.get("reasoning_level") or "normal"),
                            "routing_status": str(discovery_state.get("routing_status") or "UNRESOLVED"),
                            "search_queries_attempted": list(discovery_state.get("search_queries_attempted") or []),
                            "input_roles": list(discovery_state.get("input_roles") or []),
                            "candidate_ids": list(discovery_state.get("candidate_skill_ids") or []),
                            "loaded_skill_ids": list(discovery_state.get("loaded_skill_ids") or []),
                            "rejected_candidates": list(discovery_state.get("rejected_candidates") or []),
                            "reasoning_escalation_trigger": str(discovery_state.get("reasoning_escalation_trigger") or ""),
                        },
                        "retrieval_refs": [
                            {
                                "sha256": hashlib.sha256(str(item).encode("utf-8")).hexdigest(),
                                "chars": len(str(item)),
                            }
                            for item in list(state.get("rag_history") or [])
                        ],
                        "component_token_counts": {
                            "assembled_system_prompt": _consultant_estimate_text_tokens(consultant_prompt),
                            "visible_messages": sum(
                                _consultant_estimate_text_tokens(
                                    str(getattr(message, "content", message) or "")
                                )
                                for message in consultant_visible_messages
                            ),
                        },
                        "component_chars": consultant_prompt_accounting["component_chars"],
                        "prompt_component_accounting": consultant_prompt_accounting,
                        "consultant_budget": consultant_budget,
                        "formal_input_audit": input_resolution_context,
                        "user_source_refs": list(state.get("user_source_refs") or []),
                    },
                    temperature=0.0 if finalize_mode else None,
                    llm_override=(
                        self.consultant_reasoning_llm if discovery_escalated else None
                    ),
                    llm_policy=(
                        self.consultant_reasoning_llm_policy if discovery_escalated else None
                    ),
                )
            except Exception as exc:
                failure_summary = llm_failure_summary(exc, "consultant", task_id)
                retry_counts = dict(state.get("llm_retry_counts") or {})
                retry_attempt = int(retry_counts.get("consultant") or 0)
                if is_transient_llm_failure(exc) and not is_llm_input_rejected(exc) and retry_attempt < 1:
                    retry_counts["consultant"] = retry_attempt + 1
                    logger.warning(
                        "Transient Consultant LLM failure; retrying once without changing task state: task=%s attempt=%s",
                        task_id,
                        retry_counts["consultant"],
                    )
                    return {
                        "messages": [
                            SystemMessage(
                                content=(
                                    "<llm_transient_retry>\n"
                                    f"{failure_summary}\n"
                                    "Retry the same Consultant decision once; do not repeat read-only actions.\n"
                                    "</llm_transient_retry>"
                                )
                            )
                        ],
                        "llm_retry_counts": retry_counts,
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                if is_transient_llm_failure(exc) and not is_llm_input_rejected(exc):
                    question = (
                        "The Consultant LLM connection failed after one bounded retry. "
                        f"{failure_summary} Verify the API/network connection, then resume this task; "
                        "the verified task state and read-only evidence were preserved."
                    )
                    output.print_once(
                        f"consultant_llm_wait:{task_id}",
                        "⚠️ Consultant API connection failed after the bounded retry; task state was preserved for resume.",
                        Fore.YELLOW,
                    )
                    return {
                        "messages": [SystemMessage(content=f"<llm_transient_failure>\n{failure_summary}\n</llm_transient_failure>")],
                        "pending_human_question": {
                            "type": "llm_retry_question",
                            "stage": "consultant",
                            "question": question,
                            "resume_step": "consultant",
                        },
                        "llm_retry_counts": retry_counts,
                        "consultation_state": consultation_state,
                        "next_step": "ask_user",
                    }
                response = self._llm_failure_response("consultant", exc, task_id)
                output.print_ai(response.content)
                plan_progress = self._mark_plan_current_blocked(task_id, failure_summary)
                await self._finalize_task_memory(
                    task_id,
                    "failed",
                    messages + [response],
                    {"reason": failure_summary, "plan_progress": plan_progress},
                )
                return {"messages": [response], "plan_progress": plan_progress, "next_step": "finish"}
            raw_content = str(response.content or "").strip()
            current_consultant_state = load_plan_state(self.data_path, task_id)
            _, current_consultant_step = current_plan_step_with_index(
                current_consultant_state
            )
            current_consultant_task_state = dict(
                current_consultant_state.get("task_state") or {}
            )
            current_consultant_continuation_id = str(
                current_consultant_task_state.get("skill_continuation_id")
                or ""
            )
            current_consultant_context = build_node_context(
                node_type="consultant",
                task_spec=canonical_task_spec_for_state(
                    current_consultant_state
                ),
                plan_state=current_consultant_state,
                state_generation=int(
                    current_consultant_state.get("state_generation") or 0
                ),
                current_step_id=str(
                    (current_consultant_step or {}).get("step_id") or ""
                ),
                authoritative_user_turn_revision=(
                    self._authoritative_user_turn_revision(
                        current_consultant_state
                    )
                ),
                continuation_id=current_consultant_continuation_id,
            )
            consultant_staleness = evaluate_node_staleness(
                consultant_node_context.binding,
                current_consultant_context.binding.to_dict(),
            )
            if not consultant_staleness.usable:
                self._node_invocations.mark_stale_signature_handled(
                    consultant_staleness.stale_signature
                )
                self._record_durable_skill_event(
                    task_id,
                    "stale_node_result_discarded",
                    {
                        "caller_node": "consultant",
                        "caller_invocation_id": (
                            consultant_node_context.binding.invocation_id
                        ),
                        "changed_preconditions": list(
                            consultant_staleness.changed_preconditions
                        ),
                    },
                )
                return {
                    "messages": [response, SystemMessage(content=json.dumps({
                        "decision_result": "STALE_NODE_RESULT",
                        "caller_node": "consultant",
                        "changed_preconditions": list(
                            consultant_staleness.changed_preconditions
                        ),
                        "counts_as_failure": False,
                    }, ensure_ascii=False, sort_keys=True))],
                    "stale_node_result": {
                        "decision_result": "STALE_NODE_RESULT",
                        "caller_node": "consultant",
                        "changed_preconditions": list(
                            consultant_staleness.changed_preconditions
                        ),
                    },
                    "next_step": "consultant",
                }
            try:
                consultant_skill_decision = parse_typed_skill_decision(
                    raw_content
                )
            except SkillAccessError as exc:
                completed_projection = (
                    self._complete_durable_skill_continuation(
                        task_id, caller_node="consultant"
                    )
                    if current_consultant_continuation_id
                    else {}
                )
                rejected = {
                    "decision_result": "SKILL_DECISION_REJECTED",
                    **exc.to_dict(),
                    "counts_as_failure": False,
                }
                return {
                    **completed_projection,
                    "messages": [response, SystemMessage(content=json.dumps(
                        rejected, ensure_ascii=False, sort_keys=True,
                    ))],
                    "skill_decision_result": rejected,
                    "pending_action": {},
                    "next_step": "consultant",
                }
            if consultant_skill_decision is not None:
                try:
                    return await self._handle_skill_node_decision(
                        task_id=task_id,
                        caller_node="consultant",
                        graph_node="consultant",
                        decision=consultant_skill_decision,
                        node_context=consultant_node_context,
                        response=response,
                        selected_skill_ids=(
                            state.get("selected_skills")
                            or current_consultant_task_state.get(
                                "selected_skills"
                            )
                            or []
                        ),
                    )
                except SkillAccessError as exc:
                    rejected = {
                        "decision_result": "SKILL_DECISION_REJECTED",
                        **exc.to_dict(),
                        "counts_as_failure": False,
                    }
                    return {
                        "messages": [response, SystemMessage(content=json.dumps(
                            rejected, ensure_ascii=False, sort_keys=True,
                        ))],
                        "skill_decision_result": rejected,
                        "pending_action": {},
                        "next_step": "consultant",
                    }
            if current_consultant_continuation_id:
                self._complete_durable_skill_continuation(
                    task_id, caller_node="consultant"
                )
            await self._observe_session_memory(
                task_id,
                "consultant",
                messages + [response],
                {"consultant_output": raw_content[:3000]},
            )
            consultant_json_payload = self._consultant_json_payload(raw_content)
            contract_repair_audit: Dict[str, Any] = {}
            if contract_repair_state:
                repair_result = self._apply_consultant_contract_repair(
                    contract_repair_state,
                    consultant_json_payload,
                )
                if not repair_result.get("valid"):
                    repair_errors = list(repair_result.get("errors") or [])
                    next_repair_state = deepcopy(contract_repair_state)
                    next_repair_state["repair_attempt"] = int(
                        next_repair_state.get("repair_attempt") or 0
                    ) + 1
                    next_repair_state["last_repair_protocol_errors"] = repair_errors
                    next_repair_state["last_repair_response_hash"] = hashlib.sha256(
                        raw_content.encode("utf-8")
                    ).hexdigest()
                    obs = (
                        "<consultant_contract_repair_error>\n"
                        "The response violated the hash-bound repair protocol. The controller did not apply it; "
                        "the complete base payload and original validation errors remain unchanged.\n"
                        + json.dumps({
                            "error_count": len(repair_errors),
                            "errors": repair_errors,
                            "required_action_type": "repair_finish",
                            "base_payload_hash": contract_repair_state.get("payload_hash"),
                            "allowed_fields_by_index": contract_repair_state.get("allowed_fields_by_index") or {},
                            "allowed_payload_fields": contract_repair_state.get("allowed_payload_fields") or [],
                        }, ensure_ascii=False, sort_keys=True, default=str)
                        + "\n</consultant_contract_repair_error>"
                    )
                    route = self._consultant_semantic_failure_route(
                        repair_attempt=int(next_repair_state.get("repair_attempt") or 0),
                        ambiguity_retry_count=len(semantic_resolution_requests),
                    )
                    if route == "blocked_internal_contract_error":
                        blocked_consultation = dict(consultation_state)
                        blocked_consultation.update({
                            "phase": "blocked",
                            "consultation_status": "blocked",
                            "completion_decision": "blocked",
                            "completion_reason": "internal_semantic_contract_error",
                        })
                        return {
                            "messages": [
                                AIMessage(content=raw_content),
                                SystemMessage(content=obs),
                                SystemMessage(content=(
                                    "<blocked_internal_contract_error>Semantic contract repair budget exhausted; "
                                    "no user clarification is required.</blocked_internal_contract_error>"
                                )),
                            ],
                            "consultation_state": blocked_consultation,
                            "consultant_contract_repair": next_repair_state,
                            "pending_human_question": {},
                            "contract_status": "blocked_internal_contract_error",
                            "next_step": "finish",
                        }
                    return {
                        "messages": [AIMessage(content=raw_content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "consultant_contract_repair": next_repair_state,
                        "consultant_constraint_metrics": {
                            "schema_validation": "failed",
                            "repair_attempt": next_repair_state.get("repair_attempt"),
                        },
                        "pending_human_question": {},
                        "contract_status": "semantic_schema_retry",
                        "next_step": "consultant",
                    }
                consultant_json_payload = dict(repair_result.get("payload") or {})
                contract_repair_audit = {
                    "status": "applied",
                    "initial_payload_hash": contract_repair_state.get("initial_payload_hash"),
                    "base_payload_hash": contract_repair_state.get("payload_hash"),
                    "repaired_payload_hash": self._consultant_payload_hash(consultant_json_payload),
                    "repair_attempt": contract_repair_state.get("repair_attempt"),
                    "applied_fields": list(repair_result.get("applied") or []),
                }
                repaired_wire = (
                    "<action_json>"
                    + json.dumps(consultant_json_payload, ensure_ascii=False, sort_keys=True, default=str)
                    + "</action_json>"
                )
                consultant_json_command = self._consultant_command_from_json(repaired_wire)
            else:
                consultant_json_command = self._consultant_command_from_json(raw_content)
            content = raw_content
            if consultant_json_command:
                output.print_once(
                    f"consultant_json_action:{task_id}:{consultant_json_command.splitlines()[0][:80]}",
                    "• Consultant action parsed; validating...",
                    Fore.CYAN,
                )
                content = consultant_json_command
            payload_action_type = self._normalize_action_type(
                consultant_json_payload.get("action_type")
                or consultant_json_payload.get("type")
                or consultant_json_payload.get("action")
                or ""
            )
            if content.startswith("SELECT_SKILL") and payload_action_type != "select_skill":
                payload_action_type = "select_skill"
                consultant_json_payload = dict(consultant_json_payload)
                consultant_json_payload.setdefault(
                    "selected_skills",
                    [
                        item.strip()
                        for item in re.split(
                            r"[,，;\n]+",
                            content.removeprefix("SELECT_SKILL").strip(),
                        )
                        if item.strip()
                    ],
                )

            def sync_discovery_continuation(
                current_consultation: MutableMapping[str, Any],
                current_discovery: Mapping[str, Any],
            ) -> None:
                cached = dict(current_consultation.get("discovery_continuation") or {})
                cached["discovery_delta"] = consultant_discovery_delta(current_discovery)
                cached["updated_at"] = datetime.now(timezone.utc).isoformat()
                current_consultation["discovery_continuation"] = cached

            # EXECUTE 动作
            if content.startswith("EXECUTE"):
                output.print_node_header("execute")
                code_match = re.search(r"```(?:bash|python)?\n(.*?)```", content, re.DOTALL)
                clean_code = code_match.group(1).strip() if code_match else content.replace("EXECUTE", "").strip()
                output_violation = self._consultant_unbounded_output_violation(clean_code)
                if output_violation:
                    obs = (
                        "<consultant_validation_error>\n"
                        f"{output_violation}\n"
                        "Regenerate one bounded read-only command.\n"
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }

                proposal = {
                    "command": clean_code,
                    "requirement_ids": consultant_json_payload.get("requirement_ids") or [],
                    "purpose": consultant_json_payload.get("purpose") or "",
                    "expected_evidence": consultant_json_payload.get("expected_evidence"),
                }
                environment_identity = {
                    "conda_prefix": str(os.environ.get("CONDA_PREFIX") or ""),
                    "path_digest": hashlib.sha256(str(os.environ.get("PATH") or "").encode("utf-8")).hexdigest(),
                }
                action_context = {"task_spec_revision": task_spec_revision(task_spec)}
                preflight = preflight_execute(
                    consultation_state,
                    proposal,
                    cwd=work_dir,
                    environment=environment_identity,
                    context=action_context,
                )
                consultation_state = dict(preflight.get("state") or consultation_state)
                fingerprint = str(preflight.get("fingerprint") or "")

                def record_lifecycle(stage: str, detail: Optional[Dict[str, Any]] = None) -> None:
                    requirement_status_counts: Dict[str, int] = {}
                    for requirement in (consultation_state.get("requirements") or {}).values():
                        status_key = str(requirement.get("status") or "unknown")
                        requirement_status_counts[status_key] = requirement_status_counts.get(status_key, 0) + 1
                    lifecycle_payload = {
                        "stage": stage,
                        "consultation_id": consultation_state.get("consultation_id"),
                        "iteration": consultation_state.get("iteration"),
                        "action_fingerprint": fingerprint,
                        "requirement_ids": list(proposal.get("requirement_ids") or []),
                        "execute_call_count": consultation_state.get("execute_call_count", 0),
                        "duplicate_reuse_count": consultation_state.get("duplicate_reuse_count", 0),
                        "no_progress_count": consultation_state.get("no_progress_count", 0),
                        "phase": consultation_state.get("phase"),
                        "completion_decision": consultation_state.get("completion_decision"),
                        "completion_reason": consultation_state.get("completion_reason"),
                        "requirement_count": len(consultation_state.get("requirements") or {}),
                        "requirement_status_counts": requirement_status_counts,
                        "detail": dict(detail or {}),
                    }
                    self.profiler.record_executor_lifecycle(
                        task_id,
                        stage,
                        action_fingerprint=fingerprint,
                        consultation_id=str(consultation_state.get("consultation_id") or ""),
                        requirement_ids=list(proposal.get("requirement_ids") or []),
                        detail=lifecycle_payload,
                    )
                    try:
                        ContextLineageStore(self.data_path, task_id).record_event(
                            "consultant_executor_lifecycle",
                            lifecycle_payload,
                            event_id=(
                                f"consultant-executor-{consultation_state.get('iteration', 0)}-"
                                f"{stage.lower()}-{fingerprint[:16] or 'unfingerprinted'}"
                            ),
                        )
                    except Exception as exc:
                        logger.warning("Could not persist Consultant executor lifecycle: %s", exc)

                record_lifecycle("REQUESTED", {"purpose": proposal.get("purpose")})
                if preflight.get("decision") in {"evidence_already_satisfied", "duplicate_action_reused", "duplicate_failed_action_suppressed", "finalize_execute_forbidden"}:
                    if consultation_state.get("completion_decision") == "ready_to_finalize":
                        consultation_state = begin_finalize(consultation_state)
                    reused_observation = str(preflight.get("observation") or "Previously recorded structured evidence already satisfies the declared requirement.")
                    obs = (
                        "<consultant_evidence_reused>\n"
                        f"{self._clip_observation_text(reused_observation, 1200)}\n"
                        "No executor call was made. The completion evaluator now requires FINISH or ASK.\n"
                        "</consultant_evidence_reused>"
                    )
                    record_lifecycle("OBSERVATION_REUSED", {"decision": preflight.get("decision")})
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                if preflight.get("decision") != "allow":
                    obs = (
                        "<consultant_validation_error>\n"
                        f"EXECUTE proposal rejected by the consultation controller: {preflight.get('decision')}. "
                        "Every probe must declare unresolved requirement_ids, purpose, and expected_evidence.\n"
                        "</consultant_validation_error>"
                    )
                    record_lifecycle("REQUEST_REJECTED", {"decision": preflight.get("decision"), "reason": preflight.get("reason")})
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }

                wait_started = time.perf_counter()
                wait_started_at = timestamp_now()
                user_response = await asyncio.to_thread(
                    self.confirmation_manager.request_confirmation,
                    code=clean_code, language="Bash",
                )
                self._record_human_wait(
                    task_id,
                    "legacy_code_review",
                    wait_started,
                    user_response,
                    {"content": clean_code},
                    started_at=wait_started_at,
                )
                if user_response == 'y':
                    record_lifecycle("APPROVED")
                    shim_path = self.pm.get_shim_dir_str()
                    record_lifecycle("SPAWN_STARTED")
                    record_lifecycle("PROCESS_STARTED")
                    try:
                        stdout, stderr, ret = await run_bash_script(f'export PATH="$PATH:{shim_path}"\n{clean_code}')
                    except asyncio.CancelledError:
                        record_lifecycle("CANCELLED")
                        raise
                    except TimeoutError:
                        record_lifecycle("TIMEOUT")
                        raise
                    except BaseException as exc:
                        failure_stage = "SPAWN_FAILED" if isinstance(exc, OSError) else "PROCESS_TERMINATED"
                        record_lifecycle(failure_stage, {"error": type(exc).__name__})
                        raise
                    record_lifecycle(
                        "PROCESS_TERMINATED" if int(ret) < 0 else "PROCESS_COMPLETED",
                        {"returncode": ret},
                    )
                    obs = (
                        f"<observation>\n{'✅' if ret==0 else '❌'}\n"
                        f"{self._clip_observation_text(stdout, 1000)}\n"
                        f"{self._clip_observation_text(stderr, 500)}\n"
                        "</observation>"
                    )
                    consultation_state = record_execution_observation(
                        consultation_state,
                        fingerprint=fingerprint,
                        proposal=proposal,
                        returncode=ret,
                        observation=obs,
                        provenance={
                            "kind": "consultant_read_only_execute",
                            "action_fingerprint": fingerprint,
                            "cwd": os.path.realpath(work_dir),
                            "task_spec_revision": task_spec_revision(task_spec),
                        },
                    )
                    if consultation_state.get("completion_decision") == "ready_to_finalize":
                        consultation_state = begin_finalize(consultation_state)
                    record_lifecycle("OBSERVATION_RECORDED", {
                        "returncode": ret,
                        "completion_decision": consultation_state.get("completion_decision"),
                        "phase": consultation_state.get("phase"),
                    })
                    output.print_observation(obs)
                    if (
                        ret != 0
                        and self._looks_like_missing_runtime_dependency("\n".join([clean_code, stdout, stderr]))
                        and self._runtime_install_disallowed_by_task_spec(
                            task_spec,
                            (self._runtime_tool_candidates_from_text("\n".join([clean_code, stdout, stderr])) or [""])[0],
                        )
                    ):
                        return self._consultant_runtime_block_handoff(
                            consultant_context,
                            clean_code,
                            stdout,
                            stderr,
                            task_id,
                            max_skills=consultant_max_skills,
                        )
                else:
                    obs = f"User denied. Feedback: {user_response}" if len(user_response) > 1 else "User denied execution."
                    record_lifecycle("APPROVAL_REJECTED", {"response": str(user_response)[:200]})
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                    "consultation_state": consultation_state,
                    "next_step": "consultant",
                }

            if content.startswith("SEARCH_SKILLS"):
                raw_queries = consultant_json_payload.get("queries")
                if raw_queries is None:
                    query = str(
                        consultant_json_payload.get("query")
                        or content.removeprefix("SEARCH_SKILLS").strip()
                    ).strip()
                    raw_queries = [{
                        "query_id": "q1",
                        "text": query,
                        "purpose": str(
                            consultant_json_payload.get("purpose") or ""
                        ),
                    }]
                if not isinstance(raw_queries, list):
                    raw_queries = []
                queries: List[Dict[str, str]] = []
                for index, raw_query in enumerate(raw_queries, start=1):
                    item = (
                        dict(raw_query)
                        if isinstance(raw_query, Mapping)
                        else {"text": str(raw_query)}
                    )
                    text_value = str(
                        item.get("text") or item.get("query") or ""
                    ).strip()
                    if text_value:
                        queries.append({
                            "query_id": str(
                                item.get("query_id") or f"q{index}"
                            ).strip(),
                            "text": text_value,
                            "purpose": str(item.get("purpose") or "")[:300],
                        })
                task_hypothesis = str(
                    consultant_json_payload.get("task_hypothesis")
                    or discovery_state.get("task_hypothesis")
                    or ""
                ).strip()
                if not 1 <= len(queries) <= 3 or len({
                    item["query_id"] for item in queries
                }) != len(queries):
                    obs = (
                        '<consultant_validation_error code="SKILL_SEARCH_QUERY_REQUIRED">'
                        "SEARCH_SKILLS requires 1-3 semantic queries with unique query_id values."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                search_limits = dict(discovery_state.get("budgets") or {})
                if (
                    discovery_state.get("reasoning_level") != "escalated"
                    and int(discovery_state.get("normal_search_count") or 0)
                    >= int(search_limits.get("normal_searches") or 2)
                ):
                    obs = (
                        '<consultant_validation_error code="NORMAL_SKILL_SEARCH_BUDGET_EXHAUSTED">'
                        "Normal semantic search is exhausted. Browse the catalog, then request "
                        "reasoning escalation if routing remains unresolved."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                try:
                    top_k = max(1, min(
                        int(consultant_json_payload.get("top_k") or 5),
                        8,
                    ))
                except (TypeError, ValueError):
                    top_k = 5
                excluded_query_ids = consultant_json_payload.get(
                    "exclude_skill_ids"
                ) or []
                if not isinstance(excluded_query_ids, list):
                    excluded_query_ids = []
                search_batch = self.skill_manager.search_skill_queries(
                    queries,
                    input_roles=input_roles,
                    top_k=top_k,
                    total_limit=CONSULTANT_CANDIDATE_SKILL_LIMIT,
                    exclude_skill_ids=[
                        str(item) for item in excluded_query_ids if str(item)
                    ],
                ) if self.skill_manager else {
                    "candidates": [], "catalog_digest": ""
                }
                cards = list(search_batch.get("candidates") or [])
                discovery_state = record_skill_search_batch(
                    discovery_state,
                    queries=queries,
                    candidate_cards=cards,
                    catalog_digest=str(
                        search_batch.get("catalog_digest") or ""
                    ),
                    input_roles=input_roles,
                    task_hypothesis=task_hypothesis,
                    source=(
                        "reasoning_escalation_search"
                        if discovery_state.get("reasoning_level") == "escalated"
                        else "consultant_query_reformulation"
                    ),
                )
                consultation_state["skill_discovery"] = discovery_state
                sync_discovery_continuation(consultation_state, discovery_state)
                self._record_consultant_progress(
                    task_id,
                    code="CONSULTANT_SKILL_SEARCHED",
                    message="Consultant completed a bounded semantic skill search.",
                    detail={
                        "discovery_round": int(discovery_state.get("normal_search_count") or 0),
                        "candidate_count": len(cards),
                        "query_count": len(queries),
                    },
                )
                logger.info(
                    "Consultant skill search: task=%s round=%s level=%s queries=%s candidates=%s",
                    task_id,
                    discovery_state.get("normal_search_count"),
                    discovery_state.get("reasoning_level"),
                    [item["text"] for item in queries],
                    [card.get("skill_id") for card in cards],
                )
                obs = (
                    '<skill_search_result owner="consultant_internal">\n'
                    + json.dumps({
                        "queries": queries,
                        "catalog_digest": search_batch.get("catalog_digest"),
                        "candidates": cards,
                    }, ensure_ascii=False, sort_keys=True, indent=2, default=str)
                    + "\nnext_actions="
                    + json.dumps(discovery_next_actions(discovery_state), ensure_ascii=False)
                    + "\n</skill_search_result>"
                )
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                    "consultation_state": consultation_state,
                    "pending_human_question": {},
                    "next_step": "consultant",
                }

            if content.startswith("LIST_SKILL_CATEGORIES"):
                if int(discovery_state.get("normal_search_count") or 0) < int(
                    (discovery_state.get("budgets") or {}).get("normal_searches") or 2
                ):
                    obs = (
                        '<consultant_validation_error code="QUERY_REFORMULATION_REQUIRED">'
                        "Perform the bounded normal semantic searches before catalog expansion."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                categories = self.skill_manager.list_skill_categories() if self.skill_manager else []
                discovery_state = normalize_skill_discovery_state(discovery_state)
                discovery_state["routing_status"] = "EXPANDING_DISCOVERY"
                discovery_state["category_index_listed"] = True
                discovery_state["search_history"] = [
                    *list(discovery_state.get("search_history") or []),
                    {"source": "category_index", "categories": categories},
                ][-12:]
                consultation_state["skill_discovery"] = discovery_state
                sync_discovery_continuation(consultation_state, discovery_state)
                obs = (
                    '<skill_category_index owner="consultant_internal">\n'
                    + json.dumps(categories, ensure_ascii=False)
                    + "\nChoose one relevant canonical category with LIST_SKILLS."
                    + "\n</skill_category_index>"
                )
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                    "consultation_state": consultation_state,
                    "pending_human_question": {},
                    "next_step": "consultant",
                }

            if content.startswith("LIST_SKILLS"):
                category = str(
                    consultant_json_payload.get("category")
                    or content.removeprefix("LIST_SKILLS").strip()
                    or "all"
                ).strip()
                if not normal_discovery_exhausted(discovery_state):
                    obs = (
                        '<consultant_validation_error code="QUERY_REFORMULATION_REQUIRED">'
                        "Catalog expansion is available only after normal semantic search is exhausted."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                if (
                    discovery_state.get("reasoning_level") != "escalated"
                    and int(discovery_state.get("catalog_expansion_count") or 0)
                    >= int((discovery_state.get("budgets") or {}).get("catalog_expansions") or 1)
                ):
                    obs = (
                        '<consultant_validation_error code="CATALOG_EXPANSION_BUDGET_EXHAUSTED">'
                        "Catalog expansion is exhausted; request reasoning escalation."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                cards = self.skill_manager.list_skill_cards(
                    category,
                    max_results=CONSULTANT_CANDIDATE_SKILL_LIMIT,
                ) if self.skill_manager else []
                discovery_state = record_catalog_expansion(
                    discovery_state,
                    category=category,
                    candidate_cards=cards,
                )
                consultation_state["skill_discovery"] = discovery_state
                sync_discovery_continuation(consultation_state, discovery_state)
                logger.info(
                    "Consultant catalog expansion: task=%s category=%s candidates=%s",
                    task_id,
                    category,
                    [card.get("skill_id") for card in cards],
                )
                obs = (
                    f'<skill_catalog_result category="{category}" owner="consultant_internal">\n'
                    + (self.skill_manager.format_skill_discovery_cards(cards) if self.skill_manager else "{}")
                    + "\n</skill_catalog_result>"
                )
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                    "consultation_state": consultation_state,
                    "pending_human_question": {},
                    "next_step": "consultant",
                }

            if content.startswith("REJECT_SKILL"):
                skill_id = str(
                    consultant_json_payload.get("skill_id")
                    or content.removeprefix("REJECT_SKILL").strip()
                ).strip()
                reason = str(consultant_json_payload.get("reason") or "").strip()
                known_candidates = set(discovery_state.get("candidate_skill_ids") or [])
                if not skill_id or skill_id not in known_candidates or not reason:
                    obs = (
                        '<consultant_validation_error code="SKILL_REJECTION_EVIDENCE_REQUIRED">'
                        "Reject only a current candidate and provide its documented incompatibility reason."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                discovery_state = record_rejected_candidate(
                    discovery_state,
                    skill_id=skill_id,
                    reason=reason,
                    reason_code=str(
                        consultant_json_payload.get("reason_code")
                        or "documented_incompatibility"
                    ),
                    decision_revision=task_spec_revision(task_spec),
                )
                consultation_state["skill_discovery"] = discovery_state
                sync_discovery_continuation(consultation_state, discovery_state)
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=(
                        '<skill_candidate_rejected owner="consultant">'
                        + json.dumps({"skill_id": skill_id, "reason": reason}, ensure_ascii=False)
                        + "</skill_candidate_rejected>"
                    ))],
                    "consultation_state": consultation_state,
                    "pending_human_question": {},
                    "next_step": "consultant",
                }

            if content.startswith("REASONING_ESCALATION"):
                try:
                    discovery_state = record_reasoning_escalation(
                        discovery_state,
                        trigger=str(
                            consultant_json_payload.get("reason")
                            or "normal discovery exhausted without reliable selection"
                        ),
                    )
                except ValueError as exc:
                    obs = (
                        '<consultant_validation_error code="REASONING_ESCALATION_NOT_ALLOWED">'
                        + str(exc)
                        + "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                consultation_state["skill_discovery"] = discovery_state
                sync_discovery_continuation(consultation_state, discovery_state)
                self._record_consultant_progress(
                    task_id,
                    code="CONSULTANT_REASONING_ESCALATED",
                    message="Normal discovery was exhausted; Consultant is entering one narrow reasoning pass.",
                    detail={"reasoning_level": "escalated"},
                )
                logger.info(
                    "Consultant discovery reasoning escalation: task=%s trigger=%s",
                    task_id,
                    discovery_state.get("reasoning_escalation_trigger"),
                )
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=(
                        '<skill_discovery_reasoning_escalated>'
                        "The next Consultant invocation uses the narrow discovery context and node-scoped thinking policy."
                        "</skill_discovery_reasoning_escalated>"
                    ))],
                    "consultation_state": consultation_state,
                    "pending_human_question": {},
                    "next_step": "consultant",
                }

            if content.startswith("CAPABILITY_GAP"):
                reason = str(
                    consultant_json_payload.get("reason")
                    or "No compatible documented capability was found."
                ).strip()
                if not capability_gap_allowed(discovery_state):
                    obs = (
                        '<consultant_validation_error code="CAPABILITY_GAP_PREMATURE">'
                        "Capability gap is unavailable until normal discovery and one narrow reasoning escalation are exhausted."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                discovery_state = record_capability_gap(discovery_state, reason=reason)
                blocked = deepcopy(consultation_state)
                blocked.update({
                    "skill_discovery": discovery_state,
                    "phase": "blocked",
                    "consultation_status": "blocked",
                    "completion_decision": "blocked",
                    "completion_reason": CAPABILITY_GAP,
                })
                sync_discovery_continuation(blocked, discovery_state)
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=(
                        '<consultant_capability_gap owner="consultant_internal">'
                        + reason
                        + "</consultant_capability_gap>"
                    ))],
                    "consultation_state": blocked,
                    "pending_human_question": {},
                    "task_status": TASK_STATUS_BLOCKED,
                    "failure_owner": "consultant_internal",
                    "next_step": "finish",
                }

            # SEARCH 动作（知识库，不是本地 Skill discovery）
            if content.startswith("SEARCH"):
                parts = content.split(" ", 2)
                if len(parts) >= 3:
                    kb_cat, query = parts[1].upper(), parts[2]
                    target_kb = KB_MAP.get(kb_cat, KB_MAP.get("SOP"))
                    output.print_once(f"search:{query[:30]}", f"🔍 Searching [{kb_cat}]: {query}", Fore.CYAN)

                    new_knowledge = "Nothing found."
                    if self.retriever:
                        retrieved = self.retriever.retrieve(query, target_datasets=[target_kb])
                        if retrieved and retrieved.strip() and "Nothing found" not in retrieved:
                            print(f"{Fore.GREEN}📚 RAG: Found relevant content.{Style.RESET_ALL}")
                            new_knowledge = retrieved
                        else:
                            print(f"{Fore.YELLOW}📭 RAG: No results for '{query}'.{Style.RESET_ALL}")
                    else:
                        print(f"{Fore.RED}🔴 RAG: Retriever not initialized.{Style.RESET_ALL}")

                    rag_history.append(f"--- [Search: {kb_cat}] {query} ---\n{new_knowledge}")
                    return {
                        "messages": [AIMessage(content=f"(Searching {kb_cat}...)"),
                                     SystemMessage(content=f"Search Result:\n{new_knowledge}")],
                        "rag_history": rag_history,
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }

            if content.startswith("LOAD_WORKFLOW_TEMPLATE"):
                parts = content.split(maxsplit=1)
                workflow_id = parts[1].strip() if len(parts) == 2 else ""
                if content in load_actions:
                    obs = (
                        "<consultant_validation_error>\n"
                        f"The workflow requested by `{content}` is already loaded. Use the loaded template to FINISH or ASK.\n"
                        "</consultant_validation_error>"
                    )
                    return {"messages": [AIMessage(content=content), SystemMessage(content=obs)], "consultation_state": consultation_state, "next_step": "consultant"}
                output.print_once(f"consultant_load:{content}", f"📖 Consultant loading workflow template: {workflow_id}", Fore.CYAN)
                loaded = self.workflow_manager.load_workflow_prompt(workflow_id) if self.workflow_manager and workflow_id else ""
                if loaded:
                    obs = f'<loaded_workflow_template workflow_id="{workflow_id}">\n{loaded}\n</loaded_workflow_template>'
                else:
                    obs = (
                        f'<load_error action="LOAD_WORKFLOW_TEMPLATE" workflow_id="{workflow_id or "unknown"}">\n'
                        "Unable to load that workflow template. Use a workflow_id from Available Workflow Templates.\n"
                        "</load_error>"
                    )
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                    "consultation_state": consultation_state,
                    "next_step": "consultant",
                }

            if content.startswith("LOAD_SKILL_DOC"):
                parts = content.split(maxsplit=1)
                command_ids = [
                    item.strip()
                    for item in re.split(
                        r"[,，;\n]+", parts[1] if len(parts) == 2 else ""
                    )
                    if item.strip()
                ]
                payload_ids = consultant_json_payload.get("skill_ids") or []
                if isinstance(payload_ids, str):
                    payload_ids = [payload_ids]
                if not isinstance(payload_ids, list):
                    payload_ids = []
                single_payload_id = str(
                    consultant_json_payload.get("skill_id")
                    or consultant_json_payload.get("canonical_skill_id")
                    or ""
                ).strip()
                requested_ids = list(dict.fromkeys([
                    *([single_payload_id] if single_payload_id else []),
                    *[
                        str(item).strip() for item in payload_ids
                        if str(item).strip()
                    ],
                    *command_ids,
                ]))
                if not requested_ids or len(requested_ids) > 5:
                    obs = (
                        '<consultant_validation_error code="SKILL_DOC_BATCH_INVALID">'
                        "LOAD_SKILL_DOC requires 1-5 exact canonical skill IDs."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                invalid_ids = [
                    skill_id for skill_id in requested_ids
                    if not self.skill_manager
                    or not self.skill_manager.get_skill_meta(skill_id)
                ]
                if invalid_ids:
                    obs = (
                        '<consultant_validation_error code="UNKNOWN_CANONICAL_SKILL_ID">'
                        + json.dumps({
                            "invalid_skill_ids": invalid_ids,
                            "allowed_action": "search_skills",
                        }, ensure_ascii=False, sort_keys=True)
                        + "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                doc_budget = int(
                    (discovery_state.get("budgets") or {}).get("loaded_skill_docs")
                    or 8
                )
                loaded_ids_before = set(
                    discovery_state.get("loaded_skill_ids") or []
                )
                if len(loaded_ids_before.union(requested_ids)) > doc_budget:
                    obs = (
                        '<consultant_validation_error code="SKILL_DOC_BUDGET_EXHAUSTED">'
                        "The bounded unique skill-document reading budget would be exceeded. "
                        "Compare cached evidence, reject incompatible candidates, or narrow the batch."
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                output.print_once(
                    f"consultant_load:{','.join(requested_ids)}",
                    "📖 Consultant loading skill docs: " + ", ".join(requested_ids),
                    Fore.CYAN,
                )
                loaded_documents: List[Dict[str, Any]] = []
                load_failures: List[str] = []
                loaded_by_id: Dict[str, Dict[str, Any]] = {}
                for skill_id in requested_ids:
                    loaded = self.skill_manager.load_skill(skill_id)
                    if not loaded:
                        load_failures.append(skill_id)
                        continue
                    meta = self.skill_manager.get_skill_meta(skill_id) or {}
                    loaded_by_id[skill_id] = {
                        "skill_id": skill_id,
                        "source_path": str(meta.get("_skill_md") or ""),
                        "document": loaded,
                        "safe_summary": str(
                            meta.get("summary") or meta.get("description") or ""
                        ),
                        "document_digest": str(
                            meta.get("_skill_content_hash") or ""
                        ),
                    }
                if load_failures:
                    obs = (
                        '<load_error action="LOAD_SKILL_DOC" code="SKILL_DOC_BATCH_LOAD_FAILED">\n'
                        + json.dumps({
                            "failed_skill_ids": load_failures,
                            "persisted_skill_ids": [],
                            "allowed_action": "search_skills",
                        }, ensure_ascii=False, sort_keys=True)
                        + "\n</load_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                stored_documents = dict(
                    discovery_state.get("loaded_skill_docs") or {}
                )
                already_loaded = {
                    skill_id
                    for skill_id in requested_ids
                    if skill_id in loaded_ids_before
                    and str(
                        (stored_documents.get(skill_id) or {}).get(
                            "document_digest"
                        )
                        or ""
                    )
                    == str(
                        (loaded_by_id.get(skill_id) or {}).get(
                            "document_digest"
                        )
                        or ""
                    )
                }
                new_ids = [
                    skill_id for skill_id in requested_ids
                    if skill_id not in already_loaded
                ]
                aggregate_chars = sum(
                    len(str((loaded_by_id.get(skill_id) or {}).get("document") or ""))
                    for skill_id in new_ids
                )
                aggregate_limit = min(
                    int(CONSULTANT_SKILL_CHAR_BUDGET),
                    int(SKILL_FULL_READ_MAX_CHARS) * 3,
                )
                for skill_id in new_ids:
                    loaded_documents.append(loaded_by_id[skill_id])
                if aggregate_chars > aggregate_limit:
                    obs = (
                        '<consultant_validation_error code="SKILL_DOC_BATCH_CHAR_BUDGET_EXCEEDED">'
                        + json.dumps({
                            "requested_skill_ids": requested_ids,
                            "aggregate_chars": aggregate_chars,
                            "aggregate_limit": aggregate_limit,
                            "allowed_action": "load_skill_doc",
                        }, ensure_ascii=False, sort_keys=True)
                        + "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                transition_resolution: Dict[str, Any] = {}
                if loaded_documents or not new_ids:
                    discovery_state = record_loaded_skill_docs(
                        discovery_state,
                        loaded_documents,
                        loaded_at_revision=task_spec_revision(task_spec),
                    )
                    if str(consultant_json_payload.get("task_hypothesis") or "").strip():
                        discovery_state["task_hypothesis"] = str(
                            consultant_json_payload.get("task_hypothesis")
                        ).strip()
                    consultation_state["skill_discovery"] = discovery_state
                    sync_discovery_continuation(consultation_state, discovery_state)
                    self._record_consultant_progress(
                        task_id,
                        code="CONSULTANT_SKILL_DOC_LOADED",
                        message="Consultant loaded candidate skill documents for compatibility evaluation.",
                        detail={
                            "skill_ids": [
                                item["skill_id"] for item in loaded_documents
                            ],
                            "cache_reused_skill_ids": [
                                item for item in requested_ids if item in already_loaded
                            ],
                        },
                    )
                    rendered_docs = [
                        f'<loaded_skill_doc skill_id="{item["skill_id"]}">\n'
                        f'{item["document"]}\n</loaded_skill_doc>'
                        for item in loaded_documents
                    ]
                    cache_rows = [
                        '<loaded_skill_doc_cache_reused skill_id="'
                        + skill_id
                        + '" reinjected="false" />'
                        for skill_id in requested_ids if skill_id in already_loaded
                    ]
                    obs = "\n".join([*rendered_docs, *cache_rows])
                    transition_resolution = {
                        "consultant_pending_transition": {},
                        "consultant_no_progress_ledger": {},
                    }
                else:
                    obs = (
                        '<load_error action="LOAD_SKILL_DOC">\n'
                        + json.dumps({
                            "failed_skill_ids": load_failures or requested_ids,
                            "allowed_action": "search_skills",
                        }, ensure_ascii=False, sort_keys=True)
                        + "\n"
                        "</load_error>"
                    )
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                    "consultation_state": consultation_state,
                    "next_step": "consultant",
                    **transition_resolution,
                }

            if content.startswith("LOAD_REFERENCE"):
                parts = content.split(maxsplit=2)
                skill_id = parts[1].strip() if len(parts) >= 2 else ""
                ref_path = parts[2].strip() if len(parts) >= 3 else ""
                if content in load_actions:
                    obs = (
                        "<consultant_validation_error>\n"
                        f"The artifact requested by `{content}` is already loaded. Do not request it again; FINISH or ASK.\n"
                        "</consultant_validation_error>"
                    )
                    return {"messages": [AIMessage(content=content), SystemMessage(content=obs)], "consultation_state": consultation_state, "next_step": "consultant"}
                output.print_once(f"consultant_load:{content}", f"📖 Consultant loading reference: {skill_id} {ref_path}", Fore.CYAN)
                loaded = self.skill_manager.load_reference(skill_id, ref_path) if self.skill_manager and skill_id and ref_path else ""
                if loaded:
                    obs = (
                        f'<loaded_skill_reference skill_id="{skill_id}" path="{ref_path}">\n'
                        f"{loaded}\n"
                        "</loaded_skill_reference>"
                    )
                else:
                    obs = (
                        f'<load_error action="LOAD_REFERENCE" skill_id="{skill_id or "unknown"}" path="{ref_path}">\n'
                        "Unable to load that reference. Use a reference path listed by the loaded skill doc.\n"
                        "</load_error>"
                    )
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                    "consultation_state": consultation_state,
                    "next_step": "consultant",
                }

            if content.startswith("LOAD_SCRIPT"):
                parts = content.split(maxsplit=2)
                skill_id = parts[1].strip() if len(parts) >= 2 else ""
                script_path = parts[2].strip() if len(parts) >= 3 else ""
                if content in load_actions:
                    obs = (
                        "<consultant_validation_error>\n"
                        f"The artifact requested by `{content}` is already loaded. Do not request it again; FINISH or ASK.\n"
                        "</consultant_validation_error>"
                    )
                    return {"messages": [AIMessage(content=content), SystemMessage(content=obs)], "consultation_state": consultation_state, "next_step": "consultant"}
                output.print_once(f"consultant_load:{content}", f"📖 Consultant loading script: {skill_id} {script_path}", Fore.CYAN)
                loaded = self.skill_manager.load_script(skill_id, script_path) if self.skill_manager and skill_id and script_path else ""
                if loaded:
                    obs = (
                        f'<loaded_skill_script skill_id="{skill_id}" path="{script_path}">\n'
                        f"{loaded}\n"
                        "</loaded_skill_script>"
                    )
                else:
                    obs = (
                        f'<load_error action="LOAD_SCRIPT" skill_id="{skill_id or "unknown"}" path="{script_path}">\n'
                        "Unable to load that script. Use a script path listed by the loaded skill doc.\n"
                        "</load_error>"
                    )
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                    "consultation_state": consultation_state,
                    "next_step": "consultant",
                }

            # Consultant-first typed ASK / FINISH.  Legacy semantic_constraints
            # responses remain readable below, but all new V2 prompts use this
            # candidate-state path.
            if (
                payload_action_type in {"ask_user", "solution", "select_skill"}
                and (
                    "task_spec_operations" in consultant_json_payload
                    or payload_action_type == "select_skill"
                )
            ):
                durable_before = load_plan_state(self.data_path, task_id)
                raw_submission_ref = str(
                    (durable_before.get("audit_index") or {}).get("raw_submission_ref") or ""
                )
                raw_selected = consultant_json_payload.get("selected_skills") or []
                if isinstance(raw_selected, str):
                    raw_selected = [
                        item.strip() for item in re.split(r"[,，;\n]+", raw_selected)
                        if item.strip()
                    ]
                if not isinstance(raw_selected, list):
                    raw_selected = []
                if not raw_selected:
                    raw_selected = list(
                        state.get("selected_skills")
                        or consultation_state.get("resolved_selected_skill_ids")
                        or []
                    )
                selected = (
                    self.skill_manager.normalize_selected_skills(
                        raw_selected,
                        max_results=consultant_max_skills,
                    )
                    if self.skill_manager
                    else []
                )
                selection_issues = (
                    self.skill_manager.validate_selected_skills(
                        raw_selected,
                        max_results=consultant_max_skills,
                    )
                    if self.skill_manager and raw_selected
                    else []
                )
                planner_feedback: Dict[str, Any] = {}

                def candidate_rejection(
                    code: str,
                    instruction: str,
                    *,
                    candidate: Optional[Mapping[str, Any]] = None,
                    recoverable: bool = False,
                    required_action: str = "",
                    skill_id: str = "",
                ) -> Dict[str, Any]:
                    candidate_state = dict(candidate or {})
                    next_consultation = deepcopy(dict(
                        candidate_state.get("consultation_state") or consultation_state
                    ))
                    feedback_item = {
                        "code": str(code),
                        "instruction": str(instruction),
                    }
                    if consultant_json_payload.get("requested_slots"):
                        feedback_item["slots"] = list(
                            consultant_json_payload.get("requested_slots") or []
                        )
                    next_consultation["last_feedback"] = [
                        *list(next_consultation.get("last_feedback") or [])[-7:],
                        feedback_item,
                    ]
                    next_consultation["last_invocation_guard"] = {
                        **current_invocation_guard,
                        # The semantic commit ledger, not the legacy coarse
                        # invocation guard, owns identical rejection retries.
                        "retry_pending": False,
                    }
                    next_consultation.update({
                        "phase": "consulting",
                        "consultation_status": "active",
                        "completion_decision": "needs_evidence",
                        "completion_reason": str(code),
                    })
                    obs = (
                        f'<consultant_validation_error code="{code}">\n'
                        f"{instruction}\n"
                        "</consultant_validation_error>"
                    )
                    rejection_record = {
                        "classification": "CANDIDATE_VALIDATION",
                        "code": str(code),
                        "detail": str(instruction),
                    }
                    pending_transition: Dict[str, Any] = {}
                    ledger: Dict[str, Any] = {}
                    if recoverable:
                        pending_transition = {
                            "schema_version": 1,
                            "code": str(code),
                            "recoverable": True,
                            "terminal": False,
                            "owner": "consultant",
                            "next_route": "consultant",
                            "required_action": str(required_action),
                            "skill_id": str(skill_id),
                            "candidate_action_type": str(payload_action_type),
                        }
                        transition = consultant_validation_no_progress_fingerprint(
                            durable_before,
                            rejection_code=str(code),
                            skill_id=str(skill_id),
                            candidate_action_type=str(payload_action_type),
                            consultation_state=next_consultation,
                        )
                        ledger = advance_consultant_commit_no_progress(
                            durable_consultant_task_state.get(
                                "consultant_no_progress_ledger"
                            ),
                            transition,
                            limit=MAX_CONSULTANT_IDENTICAL_NO_PROGRESS_TRANSITIONS,
                        )
                        rejection_record.update({
                            "recoverable": True,
                            "terminal": False,
                            "owner": "consultant",
                            "next_route": "consultant",
                            "required_action": str(required_action),
                            "skill_id": str(skill_id),
                            "fingerprint": str(
                                transition.get("fingerprint") or ""
                            ),
                        })
                        pending_transition["fingerprint"] = str(
                            transition.get("fingerprint") or ""
                        )
                    update: Dict[str, Any] = {
                        "messages": [AIMessage(content=raw_content), SystemMessage(content=obs)],
                        "consultation_state": next_consultation,
                        "pending_human_question": {},
                        "contract_status": "consultant_candidate_retry",
                        "skill_decision_result": deepcopy(rejection_record),
                        "consultant_commit_rejection": deepcopy(
                            rejection_record
                        ),
                        "consultant_pending_transition": deepcopy(
                            pending_transition
                        ),
                        "next_step": "consultant",
                    }
                    if ledger:
                        update["consultant_no_progress_ledger"] = deepcopy(
                            ledger
                        )
                    if ledger.get("terminal"):
                        terminal = {
                            "classification": "CANDIDATE_VALIDATION",
                            "code": "CONSULTANT_VALIDATION_NO_PROGRESS",
                            "detail": (
                                "The same Consultant validation rejection "
                                "repeated without a loaded document, action, "
                                "or canonical-state progress."
                            ),
                            "rejection": deepcopy(rejection_record),
                        }
                        update.update({
                            "messages": [
                                *list(update.get("messages") or []),
                                SystemMessage(content=json.dumps(
                                    terminal,
                                    ensure_ascii=False,
                                    sort_keys=True,
                                )),
                            ],
                            "skill_decision_result": terminal,
                            "consultant_pending_transition": {
                                **deepcopy(pending_transition),
                                "recoverable": False,
                                "terminal": True,
                                "next_route": "finish",
                            },
                            "canonical_commit": {
                                "succeeded": False,
                                "error_code": (
                                    "CONSULTANT_VALIDATION_NO_PROGRESS"
                                ),
                            },
                            "task_status": TASK_STATUS_FAILED,
                            "failure_owner": "controller",
                            "contract_status": "internal_protocol",
                            "next_step": "finish",
                        })
                    candidate_task = candidate_state.get("task_spec")
                    if task_spec_is_initialized(candidate_task):
                        update.update({
                            "task_spec": candidate_task,
                            "task_revision": task_spec_revision(candidate_task),
                            "selected_skills": list(candidate_state.get("selected_skills") or selected),
                            "resolved_bindings": dict(candidate_state.get("resolved_bindings") or {}),
                        })
                        if planner_feedback:
                            update["planner_feedback"] = planner_feedback
                    return commit_candidate_update(update)

                if selection_issues:
                    return candidate_rejection(
                        "CONSULTANT_SKILL_SELECTION_INVALID",
                        "Use only canonical skill IDs from the visible capability catalog: "
                        + json.dumps(selection_issues, ensure_ascii=False, default=str),
                    )
                if payload_action_type == "select_skill":
                    if not selected:
                        return candidate_rejection(
                            "CONSULTANT_SKILL_SELECTION_INVALID",
                            "select_skill requires at least one canonical selected skill.",
                        )
                    document_errors = selection_document_errors(
                        discovery_state,
                        selected,
                        current_document_digests={
                            skill_id: str(
                                (
                                    self.skill_manager.get_skill_meta(skill_id)
                                    or {}
                                ).get("_skill_content_hash")
                                or ""
                            )
                            for skill_id in selected
                        } if self.skill_manager else {},
                    )
                    if document_errors:
                        return candidate_rejection(
                            "SKILL_DOC_REQUIRED",
                            json.dumps(
                                document_errors,
                                ensure_ascii=False,
                                sort_keys=True,
                            ),
                            recoverable=True,
                            required_action="LOAD_SKILL_DOC",
                            skill_id=str(document_errors[0].get("skill_id") or ""),
                        )
                if selected:
                    raw_decisions = consultant_json_payload.get(
                        "skill_decisions"
                    ) or consultant_json_payload.get("selected_skill_refs") or []
                    if not isinstance(raw_decisions, list):
                        raw_decisions = []
                    selected_decisions = [
                        dict(item) for item in raw_decisions
                        if isinstance(item, Mapping)
                        and str(item.get("skill_id") or "") in set(selected)
                        and str(
                            item.get("disposition")
                            or item.get("status")
                            or "selected"
                        ).lower() == "selected"
                    ]
                    raw_excluded = consultant_json_payload.get(
                        "excluded_skills"
                    ) or consultant_json_payload.get("excluded_skill_refs") or []
                    if not isinstance(raw_excluded, list):
                        raw_excluded = []
                    exclusion_decisions: List[Dict[str, Any]] = []
                    for item in [*raw_decisions, *raw_excluded]:
                        if isinstance(item, Mapping):
                            row = dict(item)
                            disposition = str(
                                row.get("disposition")
                                or row.get("status")
                                or ("excluded" if item in raw_excluded else "")
                            ).lower()
                            if disposition == "excluded":
                                exclusion_decisions.append(row)
                        elif item in raw_excluded and str(item).strip():
                            exclusion_decisions.append({
                                "skill_id": str(item).strip(),
                                "reason_code": "not_required",
                                "reason": "Not required by the selected task method.",
                            })
                    excluded_ids = [
                        str(item.get("skill_id") or "").strip()
                        for item in exclusion_decisions
                        if str(item.get("skill_id") or "").strip()
                    ]
                    overlap = sorted(set(selected).intersection(excluded_ids))
                    exclusion_issues = (
                        self.skill_manager.validate_selected_skills(
                            excluded_ids,
                            max_results=CONSULTANT_CANDIDATE_SKILL_LIMIT,
                        )
                        if self.skill_manager and excluded_ids else []
                    )
                    if overlap or exclusion_issues:
                        return candidate_rejection(
                            "CONSULTANT_SKILL_DECISION_SET_INVALID",
                            json.dumps({
                                "selected_excluded_overlap": overlap,
                                "excluded_skill_issues": exclusion_issues,
                            }, ensure_ascii=False, sort_keys=True, default=str),
                        )
                    discovery_state = record_excluded_skills(
                        discovery_state,
                        exclusion_decisions,
                        decision_revision=task_spec_revision(task_spec),
                    )
                    try:
                        discovery_state = record_selected_skills(
                            discovery_state,
                            selected,
                            decisions=selected_decisions,
                            selection_revision=task_spec_revision(task_spec),
                            reason=str(
                                consultant_json_payload.get("selection_reason")
                                or ""
                            ),
                        )
                    except ValueError as exc:
                        return candidate_rejection(
                            "CONSULTANT_SKILL_DECISION_SET_INVALID",
                            str(exc),
                        )
                    consultation_state["skill_discovery"] = discovery_state
                    sync_discovery_continuation(consultation_state, discovery_state)
                    if payload_action_type == "select_skill":
                        logger.info(
                            "Consultant selected documented skills: task=%s selected=%s reason=%s",
                            task_id,
                            selected,
                            str(consultant_json_payload.get("selection_reason") or "")[:600],
                        )
                try:
                    mutation_proposal = self._consultant_task_spec_mutation_proposal(
                        consultant_json_payload,
                        consultant_node_context.binding,
                    )
                    planner_feedback = self._consultant_planner_feedback_proposal(
                        consultant_json_payload,
                        consultant_node_context.binding,
                    )
                    renderer_records = [
                        self.skill_manager.get_renderer_record(skill_id)
                        for skill_id in selected
                        if self.skill_manager and self.skill_manager.has_renderer(skill_id)
                    ]
                    candidate_runtime_audits, candidate_runtime_evidence, _ = (
                        self._consultant_runtime_seed_evidence(selected, task_id)
                        if selected
                        else ([], {}, "")
                    )
                    candidate = build_consultant_candidate(
                        task_spec if task_spec_is_initialized(task_spec) else None,
                        consultation_state,
                        mutation_proposal,
                        selected_skills=selected,
                        task_id=task_id,
                        raw_submission_ref=raw_submission_ref,
                        source_refs=mutation_proposal.get("proposal_evidence_refs") or [],
                        renderer_records=renderer_records,
                        input_audit=input_resolution_result,
                        runtime_evidence=candidate_runtime_evidence,
                        project_root=str(project_root),
                    )
                except (InvocationProtocolError, ValueError) as exc:
                    return candidate_rejection(
                        "TASKSPEC_MUTATION_REJECTED",
                        str(exc),
                    )

                if payload_action_type == "ask_user":
                    requested_slots = list(consultant_json_payload.get("requested_slots") or [])
                    prior_asked = {
                        str(item)
                        for item in consultation_state.get("asked_slots", []) or []
                        if str(item)
                    }
                    repeated = sorted(prior_asked.intersection(str(item) for item in requested_slots))
                    ask_decision = evaluate_consultant_ask(
                        consultant_json_payload,
                        capabilities=semantic_capabilities,
                        resolved_bindings=candidate.get("resolved_bindings") or {},
                        task_spec=candidate.get("task_spec") or {},
                    )
                    if repeated and ask_decision.get("allowed"):
                        ask_decision = {
                            "allowed": False,
                            "code": "INVALID_ASK_REPEATED_SLOT",
                            "resolved_slots": {},
                        }
                    if not ask_decision.get("allowed"):
                        code = str(ask_decision.get("code") or "INVALID_ASK")
                        instruction = {
                            "INVALID_ASK_CONTROLLER_OWNED_SLOT": (
                                "Do not ask the user. This value is resolved by the Controller."
                            ),
                            "INVALID_ASK_RUNTIME_OWNED_SLOT": (
                                "Do not ask the user. Resolve this value through runtime evidence."
                            ),
                            "INVALID_ASK_ALREADY_KNOWN_SLOT": (
                                "Do not ask the user. The candidate state already contains this value."
                            ),
                            "INVALID_ASK_OPTIONAL_SLOT": (
                                "Do not ask the user for an optional value."
                            ),
                            "INVALID_ASK_REPEATED_SLOT": (
                                "Do not repeat the same question without new evidence."
                            ),
                        }.get(code, "ASK requires a missing, required, user-owned slot from the capability contract.")
                        if (
                            code in {
                                "INVALID_ASK_CONTROLLER_OWNED_SLOT",
                                "INVALID_ASK_ALREADY_KNOWN_SLOT",
                                "INVALID_ASK_OPTIONAL_SLOT",
                            }
                            and candidate.get("completion", {}).get("decision") == "ready_to_finalize"
                        ):
                            resolved_consultation = deepcopy(dict(candidate.get("consultation_state") or {}))
                            resolved_consultation.update({
                                "phase": "ready_to_plan",
                                "consultation_status": "ready",
                                "completion_decision": "ready_to_finalize",
                                "completion_reason": "controller_resolved_unnecessary_ask",
                                "last_feedback": [{"code": code, "instruction": instruction}],
                                "last_invocation_guard": {
                                    **current_invocation_guard,
                                    "retry_pending": False,
                                },
                                "pending_question": None,
                                "pending_human_question": None,
                            })
                            return commit_candidate_update({
                                "messages": [AIMessage(content=raw_content), SystemMessage(content=(
                                    f'<consultant_ask_resolved code="{code}">{instruction}</consultant_ask_resolved>'
                                ))],
                                "task_spec": candidate["task_spec"],
                                "task_revision": task_spec_revision(candidate["task_spec"]),
                                "selected_skills": selected,
                                "selected_skills_raw": list(raw_selected),
                                "resolved_bindings": candidate.get("resolved_bindings") or {},
                                "runtime_audit": candidate_runtime_audits,
                                "consultation_state": resolved_consultation,
                                "pending_human_question": {},
                                "contract_status": "canonical_task_ready",
                                "requirements_summary": instruction,
                                **({"planner_feedback": planner_feedback} if planner_feedback else {}),
                                "next_step": "planner",
                            })
                        return candidate_rejection(code, instruction, candidate=candidate)
                    question = str(consultant_json_payload.get("question") or "").strip()
                    if not question:
                        return candidate_rejection(
                            "ASK_QUESTION_REQUIRED",
                            "Provide one precise question for the validated requested_slots.",
                            candidate=candidate,
                        )
                    question_id = "Q-" + uuid.uuid4().hex[:12]
                    pending = {
                        "type": "consultant_question",
                        "stage": "consultant",
                        "question_id": question_id,
                        "question": question,
                        "requested_slots": requested_slots,
                        "expected_type": str(consultant_json_payload.get("expected_type") or "string"),
                        "owner": "user",
                        "resume_step": "consultant",
                    }
                    candidate_consultation = deepcopy(dict(candidate.get("consultation_state") or {}))
                    ask_discovery = normalize_skill_discovery_state(
                        candidate_consultation.get("skill_discovery") or discovery_state
                    )
                    ask_discovery.update({
                        "routing_status": "NEED_USER_CLARIFICATION",
                        "ask_user_ownership_reason": (
                            "validated missing required user-owned scientific decision"
                        ),
                        "asked_user_slots": list(requested_slots),
                    })
                    candidate_consultation["skill_discovery"] = ask_discovery
                    candidate_consultation["asked_slots"] = list(dict.fromkeys([
                        *list(candidate_consultation.get("asked_slots") or []),
                        *requested_slots,
                    ]))
                    candidate_consultation["last_feedback"] = []
                    candidate["consultation_state"] = candidate_consultation
                    candidate = build_consultant_candidate(
                        candidate.get("task_spec"),
                        candidate_consultation,
                        {
                            "proposal_type": "task_spec_mutation",
                            "schema_version": 1,
                            "operations": [],
                            "unresolved_ambiguities": [],
                            "proposal_evidence_refs": [],
                        },
                        selected_skills=selected,
                        task_id=task_id,
                        renderer_records=renderer_records,
                        input_audit=input_resolution_result,
                        runtime_evidence=candidate_runtime_evidence,
                        pending_question=pending,
                        project_root=str(project_root),
                    )
                    committed_update = commit_candidate_update({
                        "messages": [AIMessage(content=raw_content)],
                        "task_spec": candidate["task_spec"],
                        "task_revision": task_spec_revision(candidate["task_spec"]),
                        "selected_skills": selected,
                        "resolved_bindings": candidate.get("resolved_bindings") or {},
                        "runtime_audit": candidate_runtime_audits,
                        "consultation_state": candidate["consultation_state"],
                        "pending_human_question": pending,
                        **({"planner_feedback": planner_feedback} if planner_feedback else {}),
                        "contract_status": "needs_user",
                        "next_step": "ask_user",
                    })
                    self._append_semantic_conversation_turn(
                        task_id,
                        role="consultant_question",
                        content=question,
                        question_id=question_id,
                    )
                    return committed_update

                candidate_consultation = deepcopy(dict(candidate.get("consultation_state") or {}))
                candidate_consultation["last_feedback"] = []
                candidate_consultation["last_invocation_guard"] = {
                    **current_invocation_guard,
                    "retry_pending": False,
                }
                candidate["consultation_state"] = candidate_consultation
                route_decision = evaluate_consultant_candidate_route(candidate)
                if route_decision.get("route") != "planner":
                    if route_decision.get("route") == "finish":
                        candidate_consultation.update({
                            "phase": "blocked",
                            "consultation_status": "blocked",
                            "completion_decision": "blocked",
                            "completion_reason": str(
                                route_decision.get("code")
                                or "INTERNAL_PROTOCOL"
                            ),
                        })
                        return commit_candidate_update({
                            "messages": [
                                AIMessage(content=raw_content),
                                SystemMessage(content=json.dumps(
                                    route_decision,
                                    ensure_ascii=False,
                                    sort_keys=True,
                                )),
                            ],
                            "task_spec": candidate.get("task_spec"),
                            "task_revision": task_spec_revision(
                                candidate.get("task_spec")
                            ),
                            "selected_skills": selected,
                            "consultation_state": candidate_consultation,
                            "pending_human_question": {},
                            "task_status": TASK_STATUS_FAILED,
                            "failure_owner": str(
                                route_decision.get("failure_owner")
                                or "controller"
                            ),
                            "contract_status": "internal_protocol",
                            "execution_started": False,
                            "next_step": "finish",
                        })
                    unresolved_ids = list(
                        route_decision.get("unresolved_requirement_ids")
                        or candidate.get("completion", {}).get("unresolved_requirement_ids")
                        or []
                    )
                    if "skill-routing" in unresolved_ids and not selected:
                        next_discovery, guidance = reject_premature_finish(
                            candidate_consultation.get("skill_discovery") or discovery_state
                        )
                        candidate_consultation["skill_discovery"] = next_discovery
                        candidate["consultation_state"] = candidate_consultation
                        return candidate_rejection(
                            "DISCOVERY_REQUIRED",
                            json.dumps(guidance, ensure_ascii=False, sort_keys=True),
                            candidate=candidate,
                        )
                    return candidate_rejection(
                        str(route_decision.get("code") or "FINISH_CANDIDATE_INCOMPLETE"),
                        str(route_decision.get("reason") or (
                            "Valid TaskSpec and skill progress was committed, but candidate completion "
                            "still has unresolved Controller/runtime evidence: "
                            + ", ".join(unresolved_ids)[:1200]
                        )),
                            candidate=candidate,
                        )
                runtime_route = route_runtime_preflight(
                    candidate.get("task_spec"),
                    candidate_runtime_evidence,
                )
                candidate_consultation["runtime_route_decision"] = deepcopy(
                    runtime_route
                )
                if runtime_route.get("route") == "consultant":
                    unavailable_feedback = {
                        "code": "RUNTIME_SUBSTITUTION_REQUIRED",
                        "owner": "runtime_preflight",
                        "selected_skill_ids": list(selected),
                        "unavailable": deepcopy(
                            runtime_route.get("unavailable") or []
                        ),
                        "allowed_actions": list(
                            runtime_route.get("allowed_actions") or []
                        ),
                        "instruction": (
                            "Typed TaskSpec policy permits substitution. Search, load, "
                            "and select a documented alternative; do not reinterpret the "
                            "runtime result as a user-owned ambiguity."
                        ),
                    }
                    candidate_consultation["last_feedback"] = [
                        *list(candidate_consultation.get("last_feedback") or [])[-7:],
                        unavailable_feedback,
                    ]
                    return commit_candidate_update({
                        "messages": [
                            AIMessage(content=raw_content),
                            SystemMessage(content=(
                                '<runtime_substitution_required owner="runtime_preflight">'
                                + json.dumps(
                                    unavailable_feedback,
                                    ensure_ascii=False,
                                    sort_keys=True,
                                )
                                + "</runtime_substitution_required>"
                            )),
                        ],
                        "input_audit": input_resolution_result,
                        "selected_skills": selected,
                        "task_spec": candidate["task_spec"],
                        "task_revision": task_spec_revision(candidate["task_spec"]),
                        "runtime_audit": candidate_runtime_audits,
                        "consultation_state": candidate_consultation,
                        "pending_human_question": {},
                        "contract_status": "runtime_substitution_required",
                        "failure_owner": "runtime_preflight",
                        "execution_started": False,
                        "next_step": "consultant",
                    })
                if runtime_route.get("route") == "finish":
                    candidate_consultation.update({
                        "phase": "blocked",
                        "consultation_status": "blocked",
                        "completion_decision": "blocked",
                        "completion_reason": str(
                            runtime_route.get("code") or "RUNTIME_UNAVAILABLE"
                        ),
                    })
                    return commit_candidate_update({
                        "messages": [
                            AIMessage(content=raw_content),
                            SystemMessage(content=json.dumps(
                                runtime_route,
                                ensure_ascii=False,
                                sort_keys=True,
                            )),
                        ],
                        "input_audit": input_resolution_result,
                        "selected_skills": selected,
                        "task_spec": candidate["task_spec"],
                        "task_revision": task_spec_revision(candidate["task_spec"]),
                        "runtime_audit": candidate_runtime_audits,
                        "consultation_state": candidate_consultation,
                        "pending_human_question": {},
                        "task_status": TASK_STATUS_FAILED,
                        "contract_status": "runtime_unavailable",
                        "failure_owner": "runtime_preflight",
                        "execution_started": False,
                        "next_step": "finish",
                    })
                candidate_consultation.update({
                    "phase": "ready_to_plan",
                    "consultation_status": "ready",
                    "completion_decision": "ready_to_finalize",
                    "completion_reason": "candidate_state_complete",
                    "pending_question": None,
                    "pending_human_question": None,
                })
                sync_discovery_continuation(candidate_consultation, discovery_state)
                summary = str(
                    consultant_json_payload.get("summary")
                    or consultant_json_payload.get("selection_reason")
                    or "Consultant semantic contract complete."
                ).strip()
                committed_update = commit_candidate_update({
                    "messages": [AIMessage(content=raw_content)],
                    "input_audit": input_resolution_result,
                    "selected_skills": selected,
                    "selected_skills_raw": list(raw_selected),
                    "resolved_bindings": candidate.get("resolved_bindings") or {},
                    "runtime_audit": candidate_runtime_audits,
                    "runtime_route_decision": runtime_route,
                    **({
                        "runtime_stage_block": runtime_route,
                    } if runtime_route.get("code") == "RUNTIME_STAGE_BLOCKED" else {}),
                    "skill_selection_source": (
                        "consultant_select_completion"
                        if payload_action_type == "select_skill"
                        else "consultant_candidate_finish"
                    ),
                    "requirements_summary": summary,
                    "task_spec": candidate["task_spec"],
                    "task_revision": task_spec_revision(candidate["task_spec"]),
                    "consultation_state": candidate_consultation,
                    "pending_human_question": {},
                    **({"planner_feedback": planner_feedback} if planner_feedback else {}),
                    "contract_status": (
                        "canonical_task_ready_runtime_stage_blocked"
                        if runtime_route.get("code") == "RUNTIME_STAGE_BLOCKED"
                        else "canonical_task_ready"
                    ),
                    "memory_packet_context": self._consultant_handoff_memory_packet(
                        summary, consultant_memory_retrieval_context
                    ),
                    "wiki_memory_context": consultant_wiki_context,
                    "next_step": "planner",
                })
                return self._finalize_consultant_commit_events(
                    task_id,
                    committed_update,
                    source=payload_action_type,
                    selected_skill_ids=selected,
                )

            # ASK 动作
            if content.startswith("ASK"):
                question = content.replace("ASK", "").strip()
                feedback_item = {
                    "code": "ASK_REQUESTED_SLOTS_REQUIRED",
                    "instruction": (
                        "ASK must be a typed JSON action with requested_slots; "
                        "do not display this untyped question to the user."
                    ),
                }
                rejected_consultation = deepcopy(consultation_state)
                rejected_consultation["last_feedback"] = [
                    *list(rejected_consultation.get("last_feedback") or [])[-7:],
                    feedback_item,
                ]
                rejected_consultation["last_invocation_guard"] = {
                    **current_invocation_guard,
                    "retry_pending": True,
                }
                return {
                    "messages": [AIMessage(content=content), SystemMessage(content=(
                        '<consultant_validation_error code="ASK_REQUESTED_SLOTS_REQUIRED">'
                        + feedback_item["instruction"]
                        + "</consultant_validation_error>"
                    ))],
                    "consultation_state": rejected_consultation,
                    "pending_human_question": {},
                    "next_step": "consultant",
                }

            # FINISH 动作. Some models omit the literal FINISH prefix while still
            # returning a complete structured handoff; accept those robustly.
            looks_like_structured_handoff = (
                "[WORKFLOW_DECISION]" in content
                or "[WORKFLOW_STAGES]" in content
                or "[SELECTED_SKILLS:" in content
            )
            if content.startswith("FINISH") or looks_like_structured_handoff:
                consultation_state = evaluate_consultation_completion(consultation_state)
                if consultation_state.get("completion_decision") != "ready_to_finalize":
                    obs = (
                        "<consultant_validation_error>\n"
                        "FINISH was rejected because mandatory evidence is unresolved. "
                        f"Unresolved requirement IDs: {', '.join(consultation_state.get('unresolved_requirement_ids') or []) or 'unknown'}. "
                        "Use one purpose-bound EXECUTE for a listed evidence requirement or ASK for the missing user decision.\n"
                        "</consultant_validation_error>"
                    )
                    return {
                        "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "next_step": "consultant",
                    }
                consultation_state = begin_finalize(consultation_state)
                summary = content[len("FINISH"):].strip() if content.startswith("FINISH") else content.strip()
                payload_type = str(
                    consultant_json_payload.get("action_type")
                    or consultant_json_payload.get("type")
                    or consultant_json_payload.get("action")
                    or ""
                ).strip().lower().replace("-", "_")
                payload_type = {"final": "finish", "solution": "finish", "answer": "finish"}.get(payload_type, payload_type)
                payload_selected = consultant_json_payload.get("selected_skills") or []
                if isinstance(payload_selected, str):
                    payload_selected = [
                        item.strip()
                        for item in re.split(r"[,，;\n]+", payload_selected)
                        if item.strip()
                    ]
                payload_selected = [
                    str(item).strip()
                    for item in payload_selected
                    if str(item).strip()
                ] if isinstance(payload_selected, list) else []
                validation_base_constraints = semantic_constraints_from_task_spec(
                    task_spec,
                    selected_skill_ids=payload_selected,
                )
                validation_provenance_catalog = semantic_provenance_catalog(
                    task_spec,
                    consultation_state=consultation_state,
                    selected_skill_ids=[
                        *candidate_skill_ids,
                        *loaded_skill_ids,
                        *list(state.get("selected_skills") or []),
                        *payload_selected,
                    ],
                )
                if payload_type != "finish" or "semantic_constraints" not in consultant_json_payload:
                    semantic_validation = {
                        "valid": False,
                        "constraints": [],
                        "errors": [{
                            "index": -1,
                            "field": "semantic_constraints",
                            "reason": "finish must be JSON and explicitly include the semantic_constraints array",
                        }],
                        "metrics": {"schema_validation": "failed", "constraint_count": 0},
                    }
                else:
                    semantic_validation = validate_compiled_constraints(
                        consultant_json_payload.get("semantic_constraints"),
                        provenance_catalog=validation_provenance_catalog,
                        require_resolvable_provenance=True,
                        base_constraints=validation_base_constraints,
                    )
                if not semantic_validation.get("valid"):
                    all_errors = list(semantic_validation.get("errors") or [])
                    repair_base_payload = deepcopy(consultant_json_payload)
                    if not repair_base_payload and content.startswith("FINISH"):
                        repair_base_payload = {
                            "action_type": "finish",
                            "selected_skills": [],
                            "summary": summary,
                        }
                    next_repair_state = self._consultant_contract_repair_state(
                        repair_base_payload,
                        all_errors,
                        previous=contract_repair_state,
                    )
                    machine_feedback = {
                        "error_count": len(all_errors),
                        "errors": all_errors,
                        "errors_by_field": next_repair_state.get("errors_by_field") or {},
                        "base_payload_hash": next_repair_state.get("payload_hash"),
                        "allowed_fields_by_index": next_repair_state.get("allowed_fields_by_index") or {},
                        "allowed_payload_fields": next_repair_state.get("allowed_payload_fields") or [],
                        "valid_categories": [
                            "required_input", "required_output", "required_skill", "required_behavior",
                            "forbidden_behavior", "preference", "conditional_policy", "failure_policy",
                            "runtime_constraint",
                        ],
                        "valid_operators": [
                            "eq", "neq", "contains", "forbid", "require", "prefer", "on_condition",
                        ],
                        "valid_strengths": [
                            "hard", "required", "preference", "conditional", "advisory", "ambiguous",
                        ],
                        "required_action_type": "repair_finish",
                    }
                    obs = (
                        "<consultant_semantic_constraint_validation_error>\n"
                        "The FINISH semantic contract failed deterministic schema validation. "
                        "Return a hash-bound repair_finish patch for only the reported fields. "
                        "Do not regenerate the FINISH payload or change any valid field.\n"
                        + json.dumps(machine_feedback, ensure_ascii=False, sort_keys=True, default=str)
                        + "\n</consultant_semantic_constraint_validation_error>"
                    )
                    logger.warning(
                        "Consultant semantic constraint validation failed: task=%s error_count=%s display_errors=%s",
                        task_id,
                        len(all_errors),
                        json.dumps(all_errors[:8], ensure_ascii=False, sort_keys=True, default=str),
                    )
                    route = self._consultant_semantic_failure_route(
                        repair_attempt=int(next_repair_state.get("repair_attempt") or 0),
                        ambiguity_retry_count=len(semantic_resolution_requests),
                    )
                    if route == "blocked_internal_contract_error":
                        blocked_consultation = dict(consultation_state)
                        blocked_consultation.update({
                            "phase": "blocked",
                            "consultation_status": "blocked",
                            "completion_decision": "blocked",
                            "completion_reason": "internal_semantic_contract_error",
                        })
                        return {
                            "messages": [
                                AIMessage(content=raw_content),
                                SystemMessage(content=obs),
                                SystemMessage(content=(
                                    "<blocked_internal_contract_error>Semantic contract repair budget exhausted; "
                                    "no user clarification is required.</blocked_internal_contract_error>"
                                )),
                            ],
                            "consultation_state": blocked_consultation,
                            "consultant_contract_repair": next_repair_state,
                            "consultant_constraint_metrics": semantic_validation.get("metrics") or {},
                            "pending_human_question": {},
                            "contract_status": "blocked_internal_contract_error",
                            "next_step": "finish",
                        }
                    return {
                        "messages": [AIMessage(content=raw_content), SystemMessage(content=obs)],
                        "consultation_state": consultation_state,
                        "consultant_contract_repair": next_repair_state,
                        "consultant_constraint_metrics": semantic_validation.get("metrics") or {},
                        "pending_human_question": {},
                        "contract_status": "semantic_schema_retry",
                        "next_step": "consultant",
                    }
                critical_ambiguities = [
                    item for item in semantic_validation.get("constraints", [])
                    if item.get("needs_clarification")
                    and item.get("strength") in {"hard", "required", "conditional", "ambiguous"}
                ]
                if critical_ambiguities:
                    unresolved = [
                        {
                            "constraint_id": item.get("requirement_id"),
                            "semantic_key": item.get("semantic_key"),
                            "ambiguity": item.get("ambiguity"),
                            "source_text": str(item.get("source_text") or "")[:300],
                        }
                        for item in critical_ambiguities[:6]
                    ]
                    obs = (
                        "<consultant_semantic_resolution_request>\n"
                        "A schema-valid critical constraint is explicitly AMBIGUOUS/UNKNOWN/UNMAPPED after the "
                        "Consultant received TaskSpec, input audit, and runtime evidence. This is a genuine semantic "
                        "clarification, not an internal schema failure.\n"
                        + json.dumps(unresolved, ensure_ascii=False, sort_keys=True, default=str)
                        + "\n</consultant_semantic_resolution_request>"
                    )
                    ambiguity_keys = ", ".join(
                        str(item.get("semantic_key") or item.get("constraint_id") or "requirement")
                        for item in unresolved
                    )
                    needs_user_consultation = dict(consultation_state)
                    needs_user_consultation.update({
                        "phase": "needs_user",
                        "consultation_status": "needs_user",
                        "completion_decision": "needs_user",
                        "completion_reason": "validated_semantic_ambiguity",
                    })
                    return {
                        "messages": [AIMessage(content=raw_content), SystemMessage(content=obs)],
                        "consultation_state": needs_user_consultation,
                        "consultant_contract_repair": {},
                        "consultant_constraint_metrics": semantic_validation.get("metrics") or {},
                        "pending_human_question": {
                            "type": "semantic_constraint_clarification",
                            "stage": "consultant",
                            "question": (
                                "Please clarify the unresolved semantic decision for: "
                                + (ambiguity_keys or "the critical requirement")
                                + "."
                            ),
                            "resume_step": "consultant",
                        },
                        "contract_status": "blocked_need_user_decision",
                        "next_step": "ask_user",
                    }
                controller_base_constraints = semantic_constraints_from_task_spec(task_spec)
                consultant_semantic_delta = [
                    item
                    for item in semantic_validation.get("constraints", [])
                    if not str(item.get("semantic_key") or "").startswith("required_skill.")
                ]
                semantic_metrics = dict(semantic_validation.get("metrics") or {})
                semantic_metrics.update({
                    "deterministic_base_constraint_count": len(controller_base_constraints),
                    "consultant_semantic_delta_count": len(consultant_semantic_delta),
                })
                if contract_repair_audit:
                    semantic_metrics["contract_repair"] = deepcopy(contract_repair_audit)
                compiled_task_spec = apply_task_spec_mutation_proposal(
                    task_spec,
                    constraint_mutation_proposal(
                        consultant_semantic_delta
                    ),
                    project_root=project_root,
                )
                logger.info(
                    "Consultant constraint extraction: task=%s %s",
                    task_id,
                    json.dumps(semantic_metrics, ensure_ascii=False, sort_keys=True, default=str),
                )
                for item in semantic_validation.get("constraints", []):
                    logger.debug(
                        "Consultant constraint: task=%s id=%s key=%s value=%s strength=%s confidence=%s source=%s",
                        task_id,
                        item.get("requirement_id"),
                        item.get("semantic_key"),
                        json.dumps(item.get("value"), ensure_ascii=False, sort_keys=True, default=str)[:500],
                        item.get("strength"),
                        item.get("confidence"),
                        item.get("source_ref") or "source_text",
                    )
                workflow_handoff = parse_workflow_handoff(summary)
                has_workflow_handoff = bool(
                    workflow_handoff.get("workflow_id")
                    or workflow_handoff.get("workflow_stages")
                )
                if has_workflow_handoff:
                    workflow_handoff = strip_workflow_activation(workflow_handoff)
                active_skills: List[str] = []
                future_skills: List[str] = []
                required_skills_all: List[str] = []
                candidate_skills: List[str] = []
                active_batch_id = ""
                if self.skill_manager:
                    if has_workflow_handoff:
                        validation = validate_workflow_handoff(
                            workflow_handoff,
                            self.skill_manager,
                            self.workflow_manager,
                            max_active_skills=SkillManager.MAX_ACTIVE_SKILLS,
                        )
                        if validation["errors"]:
                            repaired = repair_workflow_handoff(
                                workflow_handoff,
                                self.skill_manager,
                                self.workflow_manager,
                                max_active_skills=SkillManager.MAX_ACTIVE_SKILLS,
                            )
                            if repaired.get("repaired"):
                                validation = {
                                    "errors": repaired.get("errors", []),
                                    "warnings": list(repaired.get("warnings", []))
                                    + [
                                        f"Auto-repaired workflow handoff: {note}"
                                        for note in repaired.get("notes", [])
                                    ],
                                    "handoff": repaired.get("handoff", workflow_handoff),
                                }
                                output.print_once(
                                    f"workflow_autorepair:{len(validation_errors)}",
                                    "🔧 Auto-repaired Consultant workflow handoff using workflow stage metadata.",
                                    Fore.YELLOW,
                                )
                            else:
                                validation["errors"].extend(
                                    f"Auto-repair could not resolve: {note}"
                                    for note in repaired.get("notes", [])
                                    if note
                                )
                        if validation["errors"]:
                            obs = (
                                "<consultant_validation_error>\n"
                                "Workflow handoff is invalid:\n"
                                + "\n".join(f"- {issue}" for issue in validation["errors"])
                                + "\nRepair by choosing one valid path:\n"
                                "1. If a loaded workflow template clearly matches the task, repair WORKFLOW_STAGES using exact template stage names. "
                                "Do not include ACTIVE_SKILLS, FUTURE_SKILLS, active_batch_id, or active_now; Planner owns step scheduling.\n"
                                "2. If no available workflow template clearly matches the task, discard all workflow blocks and FINISH with only "
                                "[SELECTED_SKILLS: canonical_skill_id, ...]. Do not invent workflow_id, WORKFLOW_STAGES, or placeholder stages.\n"
                                "</consultant_validation_error>"
                            )
                            output.print_once(
                                f"workflow_validation:{len(validation_errors)}",
                                "⚠️ Consultant workflow handoff failed validation; asking it to repair the stage coverage.",
                                Fore.YELLOW,
                            )
                            return {
                                "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                                "consultant_contract_repair": {},
                                "next_step": "consultant",
                            }
                        workflow_handoff = strip_workflow_activation(validation["handoff"])
                        active_skills = []
                        future_skills = []
                        required_skills_all = workflow_handoff.get("required_skills_all", [])
                        candidate_skills = workflow_handoff.get("candidate_skills", [])
                        active_batch_id = workflow_handoff.get("active_batch_id", "")
                        stage_skills = [
                            str(stage.get("skill") or "").strip()
                            for stage in (workflow_handoff.get("workflow_stages", []) or [])
                            if isinstance(stage, dict)
                            and str(stage.get("status") or "").strip() == "selected_skill"
                            and str(stage.get("skill") or "").strip()
                        ]
                        # Planner needs the complete Consultant-selected pool;
                        # workflow activation is deliberately stripped here.
                        explicit_selected = self.skill_manager.parse_selected_skill_ids(summary)
                        raw_selected = list(dict.fromkeys(
                            [
                                *explicit_selected,
                                *required_skills_all,
                                *stage_skills,
                            ]
                        ))
                        selected = self.skill_manager.normalize_selected_skills(
                            raw_selected,
                            max_results=SkillManager.MAX_SELECTED_SKILLS,
                        )
                        if validation["warnings"]:
                            summary += (
                                "\n[WORKFLOW_VALIDATION_WARNINGS]\n"
                                + "\n".join(f"- {warning}" for warning in validation["warnings"])
                                + "\n[/WORKFLOW_VALIDATION_WARNINGS]"
                            )
                    elif "[SELECTED_SKILLS:" not in summary:
                        obs = (
                            "<consultant_validation_error>\n"
                            "FINISH must include either a coarse workflow handoff ([WORKFLOW_DECISION], [WORKFLOW_STAGES]) or a [SELECTED_SKILLS: ...] marker.\n"
                            "</consultant_validation_error>"
                        )
                        output.print_once(
                            f"consultant_validation:{len(validation_errors)}",
                            "⚠️ Consultant FINISH was missing skill/workflow handoff markers; asking it to repair.",
                            Fore.YELLOW,
                        )
                        return {
                            "messages": [AIMessage(content=content), SystemMessage(content=obs)],
                            "consultant_contract_repair": {},
                            "next_step": "consultant",
                        }
                    else:
                        raw_selected = self.skill_manager.parse_selected_skill_ids(summary)
                        selected = self.skill_manager.normalize_selected_skills(raw_selected, max_results=consultant_max_skills)
                        issues = self.skill_manager.validate_selected_skills(raw_selected, max_results=consultant_max_skills) if raw_selected else []
                    reselection_pending = any(
                        "<consultant_skill_reselection_error>" in error
                        for error in validation_errors
                    )
                    if not has_workflow_handoff and (issues or reselection_pending):
                        repair_decision = self._consultant_skill_repair_decision(
                            raw_selected,
                            candidate_skill_ids,
                            validation_errors,
                            consultant_max_skills,
                        )
                        output.print_once(
                            f"consultant_validation:{len(validation_errors)}",
                            (
                                "⚠️ Consultant skill selection required bounded repair; "
                                f"raw_selected={raw_selected}; "
                                f"normalized_selected={selected}; "
                                f"issues={issues}; "
                                f"repair_action={repair_decision['action']}; "
                                f"final_selected={repair_decision['selected']}"
                            ),
                            Fore.YELLOW,
                        )
                        if repair_decision["action"] == "reselect":
                            return {
                                "messages": [
                                    AIMessage(content=content),
                                    SystemMessage(content=repair_decision["feedback"]),
                                ],
                                "consultant_contract_repair": {},
                                "next_step": "consultant",
                            }

                        selected = list(repair_decision["selected"])
                        selected_base_constraints = semantic_constraints_from_task_spec(
                            compiled_task_spec,
                            selected_skill_ids=selected,
                        )
                        compiled_task_spec = merge_compiled_constraints(
                            compiled_task_spec,
                            selected_base_constraints,
                            project_root=project_root,
                            metrics=semantic_metrics,
                        )
                        final_semantic_constraints = semantic_constraints_from_task_spec(
                            compiled_task_spec,
                            selected_skill_ids=selected,
                        )
                        semantic_metrics["final_constraint_count"] = len(final_semantic_constraints)
                        runtime_audits, runtime_summary = self._consultant_runtime_preflight(selected, task_id)
                        repaired_summary = self._repair_consultant_skill_summary(
                            summary,
                            selected,
                            list(raw_selected),
                            list(repair_decision["valid_selected"]),
                            list(issues),
                        )
                        if runtime_summary:
                            repaired_summary = (repaired_summary.rstrip() + "\n\n" + runtime_summary).strip()
                        output.print_once(
                            f"consultant_bounded_repair:{len(validation_errors)}",
                            "✓ Consultant skill repair converged; entering versioned FINALIZE.",
                            Fore.GREEN,
                        )
                        # The FINISH handoff is represented by the committed
                        # TaskSpec plus selected-skill/runtime projections.
                        # Do not persist a second inline semantic contract;
                        # FINALIZE v4 owns the immutable compiled artifact.
                        consultation_state.pop("final_contract", None)
                        consultation_state.update({
                            "phase": "finalize",
                            "consultation_status": "ready",
                            "completion_decision": "ready_to_finalize",
                            "completion_reason": "formal_contract_ready_for_versioned_finalize",
                        })
                        return commit_candidate_update({
                            "messages": [AIMessage(content="FINISH\n" + repaired_summary)],
                            "input_audit": input_resolution_result,
                            "selected_skills": selected,
                            "selected_skills_raw": list(raw_selected),
                            "skill_selection_source": "consultant_bounded_repair",
                            "requirements_summary": repaired_summary,
                            "runtime_audit": runtime_audits,
                            "runtime_status": self._runtime_status_for_task(task_id),
                            "memory_packet_context": self._consultant_handoff_memory_packet(repaired_summary, consultant_memory_retrieval_context),
                            "wiki_memory_context": consultant_wiki_context,
                            "task_spec": compiled_task_spec,
                            "task_revision": task_spec_revision(compiled_task_spec),
                            "consultant_constraint_metrics": semantic_metrics,
                            "consultation_state": consultation_state,
                            "consultant_contract_repair": {},
                            "pending_human_question": {},
                            "contract_status": "semantic_contract_finalize_pending",
                            "next_step": "consultant",
                        })
                else:
                    raw_selected = []
                    selected = []
                selected_base_constraints = semantic_constraints_from_task_spec(
                    compiled_task_spec,
                    selected_skill_ids=selected,
                )
                compiled_task_spec = merge_compiled_constraints(
                    compiled_task_spec,
                    selected_base_constraints,
                    project_root=project_root,
                    metrics=semantic_metrics,
                )
                final_semantic_constraints = semantic_constraints_from_task_spec(
                    compiled_task_spec,
                    selected_skill_ids=selected,
                )
                semantic_metrics["final_constraint_count"] = len(final_semantic_constraints)
                runtime_audits, runtime_preflight_summary = self._consultant_runtime_preflight(selected, task_id)
                if runtime_preflight_summary:
                    summary = (summary.rstrip() + "\n\n" + runtime_preflight_summary).strip()
                output.print_once(
                    "consultant_finish",
                    "✓ Consultant evidence complete; entering versioned FINALIZE.",
                    Fore.GREEN,
                )
                # Fresh work advances by reference into FINALIZE v4.  Inline
                # ``final_contract`` is retained only in the frozen v2 replay
                # implementation below; it is never a new-session write.
                consultation_state.pop("final_contract", None)
                consultation_state.update({
                    "phase": "finalize",
                    "consultation_status": "ready",
                    "completion_decision": "ready_to_finalize",
                    "completion_reason": "formal_contract_ready_for_versioned_finalize",
                })
                return commit_candidate_update({
                    "messages": [AIMessage(content=content)],
                    "input_audit": input_resolution_result,
                    "selected_skills": selected,
                    "selected_skills_raw": list(raw_selected),
                    "active_skills": active_skills,
                    "future_skills": future_skills,
                    "required_skills_all": required_skills_all,
                    "candidate_skills": candidate_skills,
                    "workflow_id": workflow_handoff.get("workflow_id", ""),
                    "workflow_stages": workflow_handoff.get("workflow_stages", []),
                    "workflow_state": workflow_handoff if has_workflow_handoff else {},
                    "workflow_handoff": workflow_handoff if has_workflow_handoff else {},
                    "active_batch_id": active_batch_id,
                    "runtime_status": self._runtime_status_for_task(task_id),
                    "runtime_audit": runtime_audits,
                    "skill_selection_source": "consultant_finish",
                    "requirements_summary": summary,
                    "task_spec": compiled_task_spec,
                    "task_revision": task_spec_revision(compiled_task_spec),
                    "consultant_constraint_metrics": semantic_metrics,
                    "consultation_state": consultation_state,
                    "consultant_contract_repair": {},
                    "pending_human_question": {},
                    "contract_status": "semantic_contract_finalize_pending",
                    "memory_packet_context": self._consultant_handoff_memory_packet(summary, consultant_memory_retrieval_context),
                    "wiki_memory_context": consultant_wiki_context,
                    "next_step": "consultant",
                })
            error_code, repair_instruction = self._consultant_action_contract_error(
                raw_content,
                consultant_json_payload,
            )
            obs = (
                f'<consultant_validation_error code="{error_code}">\n'
                f"{repair_instruction}\n"
                "Reply with exactly one "
                "<action_json> block or one legacy command: EXECUTE, SEARCH, LOAD_WORKFLOW_TEMPLATE, "
                "LOAD_SKILL_DOC, LOAD_REFERENCE, LOAD_SCRIPT, ASK, or FINISH.\n"
                "JSON examples: "
                '<action_json>{"action_type":"execute","requirement_ids":["requirement-id"],'
                '"purpose":"one bounded read-only verification","expected_evidence":{"field":"value"},'
                '"language":"bash","code":"printf ready"}</action_json> '
                '<action_json>{"action_type":"load_skill_doc","skill_id":"genomics/wgs-short-read-mapping"}</action_json> '
                'or <action_json>{"action_type":"finish","selected_skills":["skill/id"],"summary":"verified context"}</action_json>.\n'
                "If verification is complete, use FINISH with [SELECTED_SKILLS: ...] or a valid workflow handoff. "
                "Use workflow handoff only when a loaded workflow template clearly matches; otherwise use only [SELECTED_SKILLS: ...]. "
                "For workflow handoff, ACTIVE_SKILLS may be empty when Planner should choose the current batch.\n"
                f"Unrecognized response preview:\n{content[:1200]}\n"
                "</consultant_validation_error>"
            )
            output.print_once(
                f"consultant_unrecognized:{len(validation_errors)}",
                "⚠️ Consultant returned an unrecognized response; asking it to repair the command.",
                Fore.YELLOW,
            )
            return {"messages": [AIMessage(content=content), SystemMessage(content=obs)], "next_step": "consultant"}

        async def ask_user(state: AgentState):
            task_id = state.get("task_id", "default")
            pending = state.get("pending_human_question") or {}
            question = str(pending.get("question") or "").strip()
            if not question:
                return {
                    "messages": [SystemMessage(content="No pending human question was found.")],
                    "pending_human_question": {},
                    "next_step": "consultant",
                }
            question_id = str(pending.get("question_id") or "").strip()
            if not question_id:
                question_id = "Q-" + hashlib.sha256(
                    f"{task_id}\n{question}".encode("utf-8")
                ).hexdigest()[:12]
                pending = {**dict(pending), "question_id": question_id}
            # Persist the exact question before the interrupt.  Re-entry is
            # idempotent by question_id, so a crash cannot create duplicates.
            self._append_semantic_conversation_turn(
                task_id,
                role="consultant_question",
                content=question,
                question_id=question_id,
            )
            output.print_once(
                f"consultant_question:{task_id}:{question}",
                f"{Fore.GREEN}🗣️  {question}{Style.RESET_ALL}",
            )
            user_answer = interrupt({
                "type": pending.get("type", "consultant_question"),
                "stage": pending.get("stage", "consultant"),
                "question": question,
                "question_id": question_id,
                "requested_slots": list(pending.get("requested_slots") or []),
            })
            stage = str(pending.get("stage") or "consultant")
            current_task_spec = self._task_spec_for_state(
                dict(state),
                state.get("messages", []),
            )
            turns, answer_turn_ref = self._append_semantic_conversation_turn(
                task_id,
                role="user",
                content=str(user_answer or ""),
                question_id=question_id,
            )
            # requested_slots are context for Consultant interpretation, never
            # a string-fill instruction.  The answer may also correct old
            # facts, add constraints, or revoke requirements.
            updated_consultation_state = deepcopy(dict(state.get("consultation_state") or {}))
            answered_question = {
                **dict(pending),
                "status": "answered_pending_interpretation",
                "answer_turn_ref": answer_turn_ref,
            }
            updated_consultation_state.update({
                "phase": "consulting",
                "consultation_status": "active",
                "completion_decision": "needs_evidence",
                "completion_reason": "user_answer_requires_consultant_interpretation",
                "pending_question": answered_question,
                "pending_human_question": answered_question,
                "last_invocation_guard": {},
            })
            plan_state = load_plan_state(self.data_path, task_id)
            plan_impact_answer = (
                str(pending.get("type") or "") == "plan_impact_review"
            )
            running_step = self._running_plan_step(plan_state)
            pending_step_id = str(
                pending.get("plan_step_id") or pending.get("step_id") or ""
            )
            if (
                not plan_impact_answer
                and self._plan_step_action_is(running_step, "ask_user")
                and pending_step_id
                and pending_step_id == str(running_step.get("step_id") or "")
            ):
                plan_progress = self._mark_plan_current_done(
                    task_id,
                    f"user_answered: {str(user_answer or '')[:500]}",
                )
            else:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "user_answered",
                    str(user_answer or "")[:500],
                )
            # Every new authoritative user turn invalidates all same-node
            # continuations.  A Planner-owned impact question resumes the
            # existing impact transaction; it does not create a new
            # Consultant interpretation loop or leave ``waiting_user`` set.
            plan_state = load_plan_state(self.data_path, task_id)
            plan_task_state = dict(plan_state.get("task_state") or {})
            if (
                plan_task_state.get("skill_access_state")
                or plan_state.get("skill_access_state")
            ):
                invalidated_access = invalidate_skill_continuations(
                    plan_task_state.get("skill_access_state")
                    or plan_state.get("skill_access_state"),
                    reason="authoritative_user_turn_changed",
                )
                plan_task_state["skill_access_state"] = invalidated_access
                plan_task_state.pop("skill_continuation_id", None)
                plan_state["skill_access_state"] = deepcopy(invalidated_access)
            if plan_impact_answer:
                durable_impact = dict(
                    plan_task_state.get("pending_plan_impact_review") or {}
                )
                if durable_impact:
                    durable_impact.update({
                        "status": "pending",
                        "answer_turn_ref": str(answer_turn_ref or ""),
                        "answer_question_id": question_id,
                        "base_user_turn_revision": (
                            self._authoritative_user_turn_revision(plan_state)
                        ),
                    })
                    plan_task_state["pending_plan_impact_review"] = (
                        durable_impact
                    )
            if str(pending.get("type") or "") == "skill_resolution":
                proposal_id = str(pending.get("proposal_id") or "")
                access = normalize_skill_access_state(
                    plan_task_state.get("skill_access_state")
                    or plan_state.get("skill_access_state")
                )
                access_proposal = (
                    access.get("binding_proposals") or {}
                ).get(proposal_id)
                if isinstance(access_proposal, MutableMapping):
                    answer_refs = list(dict.fromkeys(
                        str(item)
                        for item in (
                            list(access_proposal.get("user_answer_refs") or [])
                            + [answer_turn_ref]
                        )
                        if str(item)
                    ))
                    access_proposal["user_answer_refs"] = answer_refs
                    access_proposal["last_answer_question_id"] = question_id
                    access_proposal["base_user_turn_revision"] = (
                        self._authoritative_user_turn_revision(plan_state)
                    )
                    plan_task_state["skill_access_state"] = access
                    plan_state["skill_access_state"] = deepcopy(access)
                    pending_proposal = dict(
                        plan_task_state.get(
                            "pending_skill_binding_proposal"
                        ) or {}
                    )
                    if str(pending_proposal.get("proposal_id") or "") == (
                        proposal_id
                    ):
                        pending_proposal["user_answer_refs"] = answer_refs
                        pending_proposal["last_answer_question_id"] = (
                            question_id
                        )
                        pending_proposal["base_user_turn_revision"] = (
                            self._authoritative_user_turn_revision(plan_state)
                        )
                        plan_task_state[
                            "pending_skill_binding_proposal"
                        ] = pending_proposal
            plan_state["task_state"] = plan_task_state
            save_plan_state(self.data_path, task_id, plan_state)
            plan_state = load_plan_state(self.data_path, task_id)
            base_update = {
                "messages": [HumanMessage(
                    content=f"<human_answer stage=\"{stage}\">\nQuestion: {question}\nAnswer: {user_answer}\n</human_answer>",
                    additional_kwargs={"message_origin": "user"},
                )],
                "pending_human_question": {},
                "llm_retry_counts": {},
                "plan_progress": plan_progress,
                "conversation_evidence": dict(plan_state.get("conversation_evidence") or {}),
                "consultation_state": updated_consultation_state,
                "next_step": "planner" if plan_impact_answer else "consultant",
                "skill_access_state": deepcopy(dict(
                    plan_state.get("skill_access_state") or {}
                )),
                "skill_continuation_id": "",
            }
            if plan_impact_answer:
                updated_consultation_state.update({
                    "completion_decision": "needs_evidence",
                    "completion_reason": (
                        "plan_impact_user_answer_requires_planner_review"
                    ),
                })
                base_update["consultation_state"] = (
                    updated_consultation_state
                )
            if str(pending.get("type") or "") == "task_spec_contract_repair":
                # The old issues describe the superseded TaskSpec revision.
                # Planner will deterministically reproject and derive a fresh
                # issue set; stale issues cannot force another identical ASK.
                base_update["validation_issues"] = []
            if task_spec_is_initialized(current_task_spec):
                base_update.update({
                    "task_spec": current_task_spec,
                    "task_revision": task_spec_revision(current_task_spec),
                })
            if stage == "recovery":
                base_update.update({
                    "pending_recovery_action": {},
                    "recovery_decision": {},
                    "recovery_phase": "",
                    "recovery_status": "USER_DECISION_RECEIVED",
                    "forbidden_recovery_actions": [],
                })
            return base_update

        # ════════════════════════════════════════════
        # Node 1: Planner（详细规划 + 脚本预生成）
        # ════════════════════════════════════════════
        async def planner(state: AgentState):
            output.print_node_header("planner")
            messages   = state["messages"]
            task_spec = self._task_spec_for_state(dict(state), messages)
            task_revision = task_spec_revision(task_spec)
            task_id = state.get("task_id", "default")
            planner_entry_state = load_plan_state(self.data_path, task_id)
            pending_plan_impact = dict(
                (planner_entry_state.get("task_state") or {}).get(
                    "pending_plan_impact_review"
                )
                or {}
            )
            if pending_plan_impact:
                try:
                    return await self._run_planner_plan_impact_review(
                        state,
                        task_id=task_id,
                        durable=planner_entry_state,
                        pending=pending_plan_impact,
                    )
                except StateCASConflict as exc:
                    stale = {
                        "decision_result": "STALE_NODE_RESULT",
                        "caller_node": "planner",
                        "changed_preconditions": [
                            "plan_impact_transaction"
                        ],
                        "detail": str(exc),
                        "counts_as_failure": False,
                        "consumes_execution_retry": False,
                        "consumes_recovery_retry": False,
                    }
                    return {
                        "messages": [SystemMessage(content=json.dumps(
                            stale,
                            ensure_ascii=False,
                            sort_keys=True,
                        ))],
                        "stale_node_result": deepcopy(stale),
                        "plan_impact_review_error": deepcopy(stale),
                        "pending_action": {},
                        "next_step": "planner",
                    }
                except SkillAccessError as exc:
                    return {
                        "messages": [SystemMessage(content=json.dumps(
                            exc.to_dict(), ensure_ascii=False, sort_keys=True,
                        ))],
                        "plan_impact_review_error": exc.to_dict(),
                        "pending_action": {},
                        "next_step": "planner",
                    }
            consultation_owner = dict(state.get("consultation_state") or {})
            planner_protocol = dict(
                consultation_owner.get("finalize_protocol") or {}
            )
            canonical_candidate_ready = bool(
                task_spec_is_initialized(task_spec)
                and (state.get("selected_skills") or consultation_owner.get("resolved_selected_skill_ids"))
                and str(consultation_owner.get("completion_decision") or "") == "ready_to_finalize"
                and str(consultation_owner.get("phase") or "") in {"ready", "ready_to_plan", "ready_to_finalize"}
            )
            immutable_consultant_contract: Dict[str, Any] = {}
            if (
                str(state.get("task_mode") or "managed") == "managed"
                and not planner_protocol
                and not canonical_candidate_ready
            ):
                pending_consultation = deepcopy(consultation_owner)
                pending_consultation.update({
                    "phase": "finalize",
                    "consultation_status": "ready",
                    "completion_decision": "ready_to_finalize",
                    "completion_reason": (
                        "planner_gate_requires_versioned_finalize"
                    ),
                })
                return {
                    "messages": [SystemMessage(content=(
                        "<planner_contract_gate_pending>"
                        "Managed tasks require a versioned, immutable "
                        "FINALIZE contract before Planner."
                        "</planner_contract_gate_pending>"
                    ))],
                    "consultation_state": pending_consultation,
                    "contract_status": "semantic_contract_finalize_pending",
                    "next_step": "consultant",
                }
            planner_protocol_pair = (
                int(planner_protocol.get("schema_version") or 0),
                int(planner_protocol.get("wire_schema_version") or 0),
            )
            if planner_protocol_pair == (0, 0) and canonical_candidate_ready:
                # Consultant-first candidate state is already the canonical
                # contract.  Do not force a second LLM re-render/finalize pass.
                pass
            elif planner_protocol_pair == (4, 3):
                try:
                    immutable_consultant_contract = (
                        self._load_verified_finalize_v4_contract(
                            task_id=task_id,
                            protocol=planner_protocol,
                            task_spec=task_spec,
                            selected_skill_ids=(
                                state.get("selected_skills")
                                or consultation_owner.get(
                                    "resolved_selected_skill_ids"
                                )
                                or []
                            ),
                            # Planner still verifies every immutable FINALIZE
                            # artifact and skill binding.  The live TaskSpec
                            # projection may contain controller-owned merge
                            # updates after the context was frozen, so do not
                            # reject the checkpoint on that derived hash alone.
                            enforce_task_spec_binding_hash=False,
                        )
                    )
                except (OSError, ValueError, SnapshotConflictError) as exc:
                    blocked_consultation = deepcopy(consultation_owner)
                    blocked_consultation.update({
                        "phase": "blocked",
                        "consultation_status": "blocked",
                        "completion_decision": "blocked",
                        "completion_reason": "FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        "terminal_diagnostic": {
                            "error_code": "FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                            "error_owner": "controller_storage",
                            "detail": (
                                "Planner could not reload the immutable compiled "
                                f"contract: {type(exc).__name__}: {exc}"
                            ),
                        },
                    })
                    return {
                        "messages": [SystemMessage(content=(
                            "<planner_contract_gate_error>"
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                            "</planner_contract_gate_error>"
                        ))],
                        "consultation_state": blocked_consultation,
                        "task_status": TASK_STATUS_BLOCKED,
                        "failure_type": "FINALIZE_CHECKPOINT_ARTIFACT_MISSING",
                        "failure_owner": "controller_storage",
                        "next_step": "finish",
                    }
            elif planner_protocol_pair in {(2, 0), (2, 2), (3, 2)}:
                try:
                    if str(planner_protocol.get("status") or "") != "compiled":
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    legacy_attempts = [
                        dict(item)
                        for item in planner_protocol.get("attempts") or []
                        if isinstance(item, Mapping)
                    ]
                    if not legacy_attempts:
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    legacy_attempt = legacy_attempts[-1]
                    if (
                        str(legacy_attempt.get("provider_status") or "")
                        != "succeeded"
                        or str(legacy_attempt.get("protocol_status") or "")
                        != "valid"
                    ):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    legacy_artifact = (
                        ContextLineageStore(
                            self.data_path, task_id
                        ).lookup_finalize_response_artifact(
                            attempt_id=str(
                                legacy_attempt.get("attempt_id") or ""
                            ),
                            call_id=str(legacy_attempt.get("call_id") or ""),
                            canonical_request_hash=str(
                                legacy_attempt.get("canonical_request_hash")
                                or ""
                            ),
                        )
                        or {}
                    )
                    legacy_contract = dict(
                        consultation_owner.get("final_contract") or {}
                    )
                    outcome_summary = legacy_artifact.get(
                        "validation_summary"
                    )
                    controller_selected = list(
                        consultation_owner.get(
                            "resolved_selected_skill_ids"
                        ) or []
                    )
                    state_selected = list(
                        state.get("selected_skills")
                        or controller_selected
                    )
                    final_selected = legacy_contract.get("selected_skills")
                    final_constraints = legacy_contract.get("constraints")
                    durable_contract_hash = str(
                        (outcome_summary or {}).get(
                            "compiled_contract_hash"
                        ) or ""
                    ) if isinstance(outcome_summary, Mapping) else ""
                    if (
                        not legacy_artifact
                        or not legacy_contract
                        or not isinstance(outcome_summary, Mapping)
                        or not str(
                            legacy_artifact.get("protocol_outcome_ref") or ""
                        )
                        or str(
                            legacy_artifact.get("provider_status") or ""
                        ) != "succeeded"
                        or str(
                            legacy_artifact.get("protocol_status") or ""
                        ) != "valid"
                        or str(
                            legacy_attempt.get("canonical_request_hash") or ""
                        ) != str(
                            planner_protocol.get(
                                "active_canonical_request_hash"
                            ) or ""
                        )
                        or str(
                            legacy_contract.get("response_artifact_ref") or ""
                        )
                        != str(
                            legacy_artifact.get("response_artifact_ref") or ""
                        )
                        or str(
                            legacy_contract.get("response_content_hash") or ""
                        )
                        != str(
                            legacy_artifact.get("response_content_hash") or ""
                        )
                        or str(
                            legacy_contract.get("compiled_contract_hash") or ""
                        )
                        != durable_contract_hash
                        or canonical_compiled_contract_hash(legacy_contract)
                        != durable_contract_hash
                        or deepcopy(outcome_summary.get("coverage_audit"))
                        != deepcopy(legacy_contract.get("coverage_audit"))
                        or int(outcome_summary.get("constraint_count") or -1)
                        != int(
                            legacy_contract.get(
                                "semantic_constraint_count"
                            ) or -2
                        )
                        or not isinstance(final_constraints, list)
                        or int(
                            legacy_contract.get(
                                "semantic_constraint_count"
                            ) or -1
                        ) != len(final_constraints or [])
                        or not isinstance(final_selected, list)
                        or final_selected != controller_selected
                        or controller_selected != state_selected
                        or str(
                            legacy_contract.get("finalize_context_id") or ""
                        ) != str(
                            planner_protocol.get("finalize_context_id") or ""
                        )
                        or str(
                            legacy_contract.get("base_contract_hash") or ""
                        ) != str(
                            planner_protocol.get("base_contract_hash") or ""
                        )
                        or str(
                            legacy_contract.get("canonical_request_hash") or ""
                        ) != str(
                            legacy_attempt.get("canonical_request_hash") or ""
                        )
                        or int(
                            legacy_contract.get("task_spec_revision") or -1
                        ) != task_revision
                    ):
                        raise SnapshotConflictError(
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        )
                    immutable_consultant_contract = legacy_contract
                except (OSError, ValueError, SnapshotConflictError) as exc:
                    blocked_consultation = deepcopy(consultation_owner)
                    blocked_consultation.update({
                        "phase": "blocked",
                        "consultation_status": "blocked",
                        "completion_decision": "blocked",
                        "completion_reason": (
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        ),
                        "terminal_diagnostic": {
                            "error_code": (
                                "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                            ),
                            "error_owner": "controller_storage",
                            "detail": (
                                "Planner could not verify the frozen legacy "
                                "FINALIZE artifact chain: "
                                f"{type(exc).__name__}: {exc}"
                            ),
                        },
                    })
                    return {
                        "messages": [SystemMessage(content=(
                            "<planner_contract_gate_error>"
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                            "</planner_contract_gate_error>"
                        ))],
                        "consultation_state": blocked_consultation,
                        "task_status": TASK_STATUS_BLOCKED,
                        "failure_type": (
                            "FINALIZE_CHECKPOINT_ARTIFACT_MISSING"
                        ),
                        "failure_owner": "controller_storage",
                        "next_step": "finish",
                    }
            else:
                blocked_consultation = deepcopy(consultation_owner)
                blocked_consultation.update({
                    "phase": "blocked",
                    "consultation_status": "blocked",
                    "completion_decision": "blocked",
                    "completion_reason": (
                        "FINALIZE_PROTOCOL_VERSION_UNSUPPORTED"
                    ),
                    "terminal_diagnostic": {
                        "error_code": (
                            "FINALIZE_PROTOCOL_VERSION_UNSUPPORTED"
                        ),
                        "error_owner": "controller",
                        "detail": (
                            "Planner rejected unsupported FINALIZE protocol/"
                            f"wire pair {planner_protocol_pair}."
                        ),
                    },
                })
                return {
                    "messages": [SystemMessage(content=(
                        "<planner_contract_gate_error>"
                        "FINALIZE_PROTOCOL_VERSION_UNSUPPORTED"
                        "</planner_contract_gate_error>"
                    ))],
                    "consultation_state": blocked_consultation,
                    "task_status": TASK_STATUS_BLOCKED,
                    "failure_type": (
                        "FINALIZE_PROTOCOL_VERSION_UNSUPPORTED"
                    ),
                    "failure_owner": "controller",
                    "next_step": "finish",
                }
            task_requirement_text = "\n".join(
                [
                    str(task_spec.get("goal") or ""),
                    *[
                        str(item.get("text") or "")
                        for item in task_spec.get("user_directives", [])
                        if isinstance(item, dict) and str(item.get("kind") or "") != "initial_request"
                    ],
                ]
            ).strip()
            user_msg = str(task_spec.get("goal") or "")
            consultant_result = (
                immutable_consultant_contract
                or dict(consultation_owner.get("final_contract") or {})
            )
            runtime_audits = list(state.get("runtime_audit", []) or [])
            selected_skills = state.get("selected_skills", []) or []
            # Planner schedules the Consultant-selected pool. No skill is
            # active until an approved plan step starts.
            active_skills_state: List[str] = []
            planner_context_skills: List[str] = []
            selected_skills_raw = state.get("selected_skills_raw", []) or list(selected_skills)
            skill_selection_source = state.get("skill_selection_source", "consultant_finish")
            workflow_handoff = self._workflow_state_from_mapping(state)
            workflow_handoff = strip_workflow_activation(workflow_handoff)
            active_batch_id = ""
            future_skills: List[str] = []
            required_skills_all = state.get("required_skills_all", []) or workflow_handoff.get("required_skills_all", []) or []
            candidate_skills = state.get("candidate_skills", []) or workflow_handoff.get("candidate_skills", []) or []
            planner_skill_pool = list(selected_skills)
            if not planner_skill_pool and workflow_handoff:
                legacy_stage_skills = [
                    str(stage.get("skill") or "").strip()
                    for stage in workflow_handoff.get("workflow_stages", []) or []
                    if isinstance(stage, dict)
                    and str(stage.get("status") or "").strip() == "selected_skill"
                    and str(stage.get("skill") or "").strip()
                ]
                planner_skill_pool = self.skill_manager.normalize_selected_skills(
                    legacy_stage_skills,
                    max_results=SkillManager.MAX_SELECTED_SKILLS,
                ) if self.skill_manager else []
                if planner_skill_pool:
                    selected_skills = planner_skill_pool
                    skill_selection_source = "legacy_workflow_stage_migration"
            if self.skill_manager and not planner_skill_pool:
                return {
                    "messages": [
                        SystemMessage(
                            content=(
                                "Planner cannot proceed because Consultant did not provide a canonical skill pool. "
                                "Return to Consultant for skill discovery; Planner must not search the full catalog or invent skills."
                            )
                        )
                    ],
                    "next_step": "consultant",
                }
            # Planner may inspect only Consultant-selected skills. It never
            # receives the global catalog and activates skills per plan step.
            planner_context_skills = list(planner_skill_pool)
            renderer_records = [
                self.skill_manager.get_renderer_record(skill_id)
                for skill_id in selected_skills
                if self.skill_manager and self.skill_manager.has_renderer(skill_id)
            ]
            canonical_output_contracts = effective_output_contracts(
                task_spec,
                project_root=project_root,
            )
            planner_source_state = load_plan_state(self.data_path, task_id)
            planner_task_state = dict(planner_source_state.get("task_state") or {})
            planner_skill_access = self._prepare_durable_skill_access(
                planner_source_state,
                selected_skill_ids=planner_skill_pool,
                task_revision=task_revision,
            )
            planner_selected_refs = deepcopy(list(
                planner_skill_access.get("selected_skill_refs") or []
            ))
            planner_task_state["skill_access_state"] = deepcopy(
                planner_skill_access
            )
            planner_task_state["selected_skill_refs"] = planner_selected_refs
            planner_source_state["skill_access_state"] = deepcopy(
                planner_skill_access
            )
            planner_source_state["selected_skill_refs"] = deepcopy(
                planner_selected_refs
            )
            if not planner_task_state.get("accepted_consultant_handoff"):
                legacy_handoff = self._accepted_consultant_handoff_projection(
                    consultant_result
                )
                if legacy_handoff:
                    # Migration-on-read for verified pre-contract sessions.
                    # Planner already verified the immutable FINALIZE chain.
                    planner_task_state["accepted_consultant_handoff"] = (
                        legacy_handoff
                    )
            prior_epoch = dict(planner_task_state.get("planning_epoch") or {})
            committed_plan = dict(planner_source_state.get("current_plan") or {})
            base_snapshot_id = str(committed_plan.get("plan_snapshot_ref") or "")
            base_plan_semantic_identity = (
                str(committed_plan.get("plan_semantic_hash") or "")
                if base_snapshot_id
                else ""
            )
            epoch_feedback = dict(planner_task_state.get("planner_feedback") or {})
            planner_feedback_revision = int(epoch_feedback.get("revision") or 0)
            task_semantic_identity = task_semantic_hash(task_spec)
            if planning_epoch_matches(
                prior_epoch,
                task_semantic_identity=task_semantic_identity,
                base_plan_snapshot_id=base_snapshot_id,
                base_plan_semantic_identity=base_plan_semantic_identity,
                planner_feedback_revision=planner_feedback_revision,
            ):
                planning_epoch = deepcopy(prior_epoch)
            else:
                prior_identity = str(
                    prior_epoch.get("base_task_semantic_identity") or ""
                )
                prior_plan_identity = str(
                    prior_epoch.get("base_plan_semantic_identity") or ""
                )
                prior_status = str(prior_epoch.get("status") or "")
                planning_epoch = start_planning_epoch(
                    task_revision=task_revision,
                    task_semantic_identity=task_semantic_identity,
                    base_plan_revision=(
                        int(committed_plan.get("plan_revision") or 0)
                        if base_snapshot_id
                        else 0
                    ),
                    base_plan_snapshot_id=base_snapshot_id,
                    base_plan_semantic_identity=base_plan_semantic_identity,
                    parent_epoch_id=str(prior_epoch.get("planning_epoch_id") or ""),
                    start_reason=(
                        "semantic_base_stale"
                        if (
                            (prior_identity and prior_identity != task_semantic_identity)
                            or (
                                prior_plan_identity
                                and prior_plan_identity != base_plan_semantic_identity
                            )
                        )
                        else "reconciliation_successor"
                        if prior_status == "reconciliation_completed"
                        else "initial_planning"
                    ),
                    planner_feedback_revision=planner_feedback_revision,
                )
            planner_calls_total = int(
                planning_epoch.get("planner_calls_total") or 0
            )
            max_planner_calls = int(
                (planner_task_state.get("budgets") or {}).get(
                    "max_planner_calls_per_epoch", 4
                )
            )
            if planner_calls_total >= max_planner_calls:
                planning_epoch["status"] = "exhausted"
                planner_task_state["planning_epoch"] = planning_epoch
                planner_source_state["task_state"] = planner_task_state
                prior_failure = dict(
                    planner_task_state.get("planning_failure") or {}
                )
                exhaustion_issues = list(
                    prior_failure.get("validation_issues") or []
                ) or [{
                    "code": "PLANNING_EPOCH_EXHAUSTED",
                    "field_path": "$.current_focus.planning",
                    "affected_step_ids": [],
                    "machine_evidence": {
                        "planner_calls_total": int(
                            planner_calls_total
                        ),
                        "max_planner_calls_per_epoch": max_planner_calls,
                    },
                }]
                terminal_diagnostic = {
                    "error_code": "PLANNING_EPOCH_EXHAUSTED",
                    "error_owner": "planner",
                    "machine_evidence": {
                        "planner_calls_total": planner_calls_total,
                        "max_planner_calls_per_epoch": max_planner_calls,
                        "last_validation_codes": [
                            str(issue.get("code") or "PLAN_CANDIDATE_INVALID")
                            for issue in exhaustion_issues
                            if isinstance(issue, Mapping)
                        ],
                    },
                }
                planner_source_state = terminalize_planning_failure(
                    planner_source_state,
                    planning_epoch_id=str(
                        planning_epoch.get("planning_epoch_id") or ""
                    ),
                    task_spec_revision_value=task_revision,
                    terminal_diagnostic=terminal_diagnostic,
                    fallback_validation_issues=exhaustion_issues,
                )
                save_plan_state(self.data_path, task_id, planner_source_state)
                last_issue = (
                    dict(exhaustion_issues[0])
                    if exhaustion_issues
                    and isinstance(exhaustion_issues[0], Mapping)
                    else {}
                )
                last_code = str(
                    last_issue.get("code") or "PLAN_CANDIDATE_INVALID"
                )
                last_field = str(last_issue.get("field_path") or "$")
                last_message = str(last_issue.get("message") or "").strip()
                terminal_summary = (
                    "PLANNING_EPOCH_EXHAUSTED: Planner call budget was exhausted "
                    "without a committed PlanSnapshot. Last blocking validation: "
                    f"{last_code} at {last_field}"
                    + (f" — {last_message.rstrip('.')}" if last_message else "")
                    + "."
                )
                return {
                    "messages": [SystemMessage(content=terminal_summary)],
                    "task_status": TASK_STATUS_BLOCKED,
                    "planning_epoch": planning_epoch,
                    "next_step": "finish",
                }
            planning_epoch["planner_calls_total"] = planner_calls_total + 1
            planner_task_state["planning_epoch"] = planning_epoch
            planner_source_state["task_state"] = planner_task_state
            save_plan_state(self.data_path, task_id, planner_source_state)
            planner_source_state = load_plan_state(self.data_path, task_id)
            planner_source_state = supersede_planning_failure(
                planner_source_state,
                task_spec_revision_value=task_revision,
            )
            active_planning_failure = current_planning_failure(
                planner_source_state,
                task_spec_revision_value=task_revision,
            )
            if (
                active_planning_failure
                and str(active_planning_failure.get("planning_epoch_id") or "")
                != str(planning_epoch.get("planning_epoch_id") or "")
            ):
                # A Plan Review failure can be created after the prior epoch
                # committed a pending snapshot.  Rebind that correction
                # capsule to the successor epoch instead of carrying counters
                # or fingerprints across semantic bases.
                planner_source_state = record_planning_failure(
                    planner_source_state,
                    validation_issues=list(
                        active_planning_failure.get("validation_issues") or []
                    ),
                    planning_epoch_id=str(
                        planning_epoch.get("planning_epoch_id") or ""
                    ),
                    task_spec_revision_value=task_revision,
                    validation_source=str(
                        active_planning_failure.get("validation_source")
                        or "planner_candidate_admission"
                    ),
                    candidate=(
                        active_planning_failure.get("previous_candidate")
                        if isinstance(
                            active_planning_failure.get("previous_candidate"),
                            Mapping,
                        )
                        else None
                    ),
                    previous_correction=dict(
                        active_planning_failure.get("previous_correction") or {}
                    ),
                )
                active_planning_failure = current_planning_failure(
                    planner_source_state,
                    task_spec_revision_value=task_revision,
                )
            legacy_failure_issues: List[Dict[str, Any]] = []
            if not active_planning_failure:
                resume_audit = state.get("resume_audit") or {}
                for missing_field in resume_audit.get("missing_fields", []) or []:
                    legacy_failure_issues.append({
                        "code": "PLAN_FIELD_MISSING",
                        "field_path": str(missing_field),
                        "expected_type": "present",
                        "received_type": "missing",
                        "affected_step_ids": [],
                        "machine_evidence": {"missing_field": str(missing_field)},
                    })
                stale_step_ids_for_failure = [
                    str(value)
                    for value in planner_source_state.get(
                        "revalidation_required_step_ids", []
                    ) or []
                    if str(value)
                ]
                if stale_step_ids_for_failure:
                    legacy_failure_issues.append({
                        "code": "PLAN_REVALIDATION_REQUIRED",
                        "field_path": "$.steps",
                        "affected_step_ids": stale_step_ids_for_failure,
                        "machine_evidence": {
                            "revalidation_required_step_ids": stale_step_ids_for_failure,
                        },
                    })
                if self._plan_patch_requested(dict(state)):
                    recovery_decision = (
                        dict(state.get("recovery_decision") or {})
                        if isinstance(state.get("recovery_decision"), Mapping)
                        else {}
                    )
                    _, failed_step = current_plan_step_with_index(planner_source_state)
                    affected_step = str(
                        state.get("failed_step_id")
                        or recovery_decision.get("failed_step_id")
                        or (failed_step or {}).get("step_id")
                        or ""
                    )
                    legacy_failure_issues.append({
                        "code": "LEGACY_PLAN_PATCH_REQUEST",
                        "field_path": "$.steps",
                        "affected_step_ids": [affected_step] if affected_step else [],
                        "machine_evidence": {
                            "legacy_route": "PLAN_PATCH_REQUEST",
                            "recovery_action": str(
                                recovery_decision.get("action")
                                or recovery_decision.get("decision")
                                or state.get("required_next_action")
                                or ""
                            ),
                        },
                    })
            if legacy_failure_issues:
                planner_source_state = record_planning_failure(
                    planner_source_state,
                    validation_issues=legacy_failure_issues,
                    planning_epoch_id=str(
                        planning_epoch.get("planning_epoch_id") or ""
                    ),
                    task_spec_revision_value=task_revision,
                    validation_source="legacy_recovery_route",
                )
            save_plan_state(self.data_path, task_id, planner_source_state)
            planner_source_state = load_plan_state(self.data_path, task_id)
            active_planning_failure = current_planning_failure(
                planner_source_state,
                task_spec_revision_value=task_revision,
            )
            planner_feedback = dict(
                (planner_source_state.get("task_state") or {}).get("planner_feedback")
                or state.get("planner_feedback")
                or {}
            )
            if str(planner_feedback.get("status") or "pending") != "pending":
                planner_feedback = {}
            planner_approved_snapshot: Dict[str, Any] = {}
            planner_pending_snapshot: Dict[str, Any] = {}
            planner_snapshot_status = str(
                (planner_source_state.get("current_approval") or {}).get("status")
                or ""
            )
            if (
                base_snapshot_id
                and planner_snapshot_status == "approved"
            ):
                planner_approved_snapshot = load_approved_plan_snapshot(
                    self.data_path,
                    task_id,
                    state=planner_source_state,
                )
            elif (
                base_snapshot_id
                and planner_snapshot_status == "pending"
                and active_planning_failure
            ):
                planner_pending_snapshot = load_current_plan_snapshot(
                    self.data_path,
                    task_id,
                    state=planner_source_state,
                )
            planner_semantic_inputs = self._node_context_semantic_inputs(
                task_id,
                planner_source_state,
                messages=messages,
                accepted_contract=consultant_result,
            )
            planner_semantic_capabilities, _planner_operation_bindings = (
                self.skill_manager.get_semantic_execution_capabilities(planner_context_skills)
                if self.skill_manager
                else ([], {})
            )
            planner_node_context = build_node_context(
                node_type="planner",
                task_spec=task_spec,
                plan_state=planner_source_state,
                state_generation=int(planner_source_state.get("state_generation") or 0),
                current_step_id=str(
                    planner_source_state.get("current_step_id")
                    or (current_plan_step_with_index(planner_source_state)[1] or {}).get(
                        "step_id"
                    )
                    or ""
                ),
                authoritative_user_turn_revision=(
                    self._authoritative_user_turn_revision(planner_source_state)
                ),
                runtime={
                    "input_audit": runtime_audits,
                    "available_capabilities": list(selected_skills),
                    "capability_contract": planner_semantic_capabilities,
                },
                feedback={"planner_feedback": planner_feedback} if planner_feedback else {},
                skill_context=self._skill_context_projection(
                    planner_source_state,
                    caller_node="planner",
                    current_step_id=str(
                        planner_source_state.get("current_step_id") or ""
                    ),
                ),
                continuation_id=str(
                    (planner_source_state.get("task_state") or {}).get(
                        "skill_continuation_id"
                    ) or ""
                ),
                allowed_operations=["create_plan", "report_task_semantics_incomplete"],
                trace_enabled=bool(os.getenv("NODE_CONTEXT_V2_TRACE", "")),
                max_payload_chars=max(1, int(self.llm_context_limit_tokens) * 4),
                approved_plan_snapshot=planner_approved_snapshot or None,
                plan_snapshot=planner_pending_snapshot or None,
                plan_snapshot_status=(
                    planner_snapshot_status if planner_pending_snapshot else ""
                ),
                **planner_semantic_inputs,
            )
            planner_system_prompt = PromptManager.get_planner_v2_system_prompt()
            planner_human_prompt = PromptManager.get_planner_v2_human_prompt(
                planner_node_context.llm_payload.to_provider_dict()
            )
            planner_no_structural_progress = planner_correction_requires_thinking(
                active_planning_failure
            )
            planner_correction_policy = (
                dict(getattr(self, "planner_correction_llm_policy", {}) or {})
                if planner_no_structural_progress
                else {}
            )
            planner_correction_llm = (
                getattr(self, "planner_correction_llm", None)
                if planner_no_structural_progress
                else None
            )

            def planner_prompt_accounting() -> Dict[str, Any]:
                component_map = {
                    "system_policy": len(planner_system_prompt),
                    "llm_payload": len(planner_human_prompt),
                }
                return {
                    "assembled_prompt_chars": sum(component_map.values()),
                    "component_chars": component_map,
                    "component_accounting": "non_overlapping",
                }

            planner_accounting = planner_prompt_accounting()
            compressible_chars = 0
            planner_budget = assess_prompt_budget(
                [planner_system_prompt, planner_human_prompt],
                component_chars=planner_accounting["component_chars"],
                context_limit_tokens=self.llm_context_limit_tokens,
                nominal_char_budget=PLANNER_NOMINAL_CHAR_BUDGET,
                compressible_chars=compressible_chars,
                noncompressible_chars=max(
                    0,
                    planner_accounting["assembled_prompt_chars"] - compressible_chars,
                ),
                soft_warning_ratio=PLANNER_SOFT_TOKEN_RATIO,
                compression_ratio=PLANNER_COMPRESSION_TOKEN_RATIO,
                hard_safety_ratio=PLANNER_HARD_TOKEN_RATIO,
                reserved_headroom_tokens=PLANNER_RESERVED_HEADROOM_TOKENS,
            )
            planner_budget["optional_compression_applied"] = False
            planner_prompt_components = planner_accounting["component_chars"]
            logger.info(
                "Planner prompt components: task=%s %s",
                task_id,
                json.dumps(planner_accounting, ensure_ascii=False, sort_keys=True),
            )
            logger.info(
                "Planner prompt budget decision: task=%s %s",
                task_id,
                json.dumps(planner_budget, ensure_ascii=False, sort_keys=True),
            )
            if planner_budget["hard_block"]:
                logger.error(
                    "Planner prompt exceeds token safety boundary after optional compression: task=%s chars=%s estimated_tokens=%s headroom=%s",
                    task_id,
                    planner_accounting["assembled_prompt_chars"],
                    planner_budget["estimated_input_tokens"],
                    planner_budget["remaining_headroom_tokens"],
                )
                reason = (
                    "PLANNER_CONTEXT_BUDGET_UNSATISFIED: estimated input is "
                    f"{planner_budget['estimated_input_tokens']} / {planner_budget['context_limit_tokens']} tokens "
                    f"with {planner_budget['remaining_headroom_tokens']} reserved-headroom tokens remaining."
                )
                plan_progress = self._mark_plan_current_blocked(task_id, reason)
                return {
                    "messages": [SystemMessage(content=reason)],
                    "plan_progress": plan_progress,
                    "next_step": "finish",
                }

            # Persist the Planner input contract before the remote call so a
            # timeout/restart cannot erase Consultant-selected skills or task facts.
            durable_preplan = load_plan_state(self.data_path, task_id)
            _bind_current_task_spec_record(durable_preplan, task_spec)
            durable_preplan["selected_skill_ids"] = list(selected_skills)
            if not durable_preplan.get("steps"):
                durable_preplan["generated_from_task_revision"] = task_revision
            save_plan_state(self.data_path, task_id, durable_preplan)

            plan_content = ""
            violations: List[Any] = []
            try:
                response = await self._ainvoke_node_llm(
                    [
                        SystemMessage(content=planner_system_prompt),
                        HumanMessage(content=planner_human_prompt),
                    ],
                    node_context=planner_node_context,
                    stage="planner",
                    task_id=task_id,
                    task_mode=str(state.get("task_mode") or "managed"),
                    temperature=0.1,
                    trace_metadata={
                        "call_kind": "planner_initial",
                        "task_spec_revision": task_spec_revision(task_spec),
                        "effective_facts_revision": str(state.get("effective_user_facts_revision") or ""),
                        "selected_skill_ids": selected_skills,
                        "runtime_audit_ref": str(
                            Path(self.data_path) / "task_outputs" / task_id / "runtime_audit.json"
                        ),
                        "component_chars": planner_prompt_components,
                        "prompt_component_accounting": planner_accounting,
                        "planner_budget_decision": planner_budget,
                        "planner_correction_escalation": {
                            "triggered": planner_no_structural_progress,
                            "reason": (
                                "no_structural_progress"
                                if planner_no_structural_progress
                                else ""
                            ),
                            "repeat_count": int(
                                active_planning_failure.get("repeat_count") or 0
                            ) if active_planning_failure else 0,
                            "thinking_enabled": bool(
                                planner_correction_policy.get("thinking_enabled")
                            ),
                        },
                    },
                    llm_override=planner_correction_llm,
                    llm_policy=planner_correction_policy,
                )
            except Exception as exc:
                if is_transient_llm_failure(exc) and not is_llm_input_rejected(exc):
                    update = self._pause_retryable_llm_failure(state, task_id, "planner", exc)
                    output.print_ai(str(update["messages"][0].content))
                    return update
                response = self._llm_failure_response("planner", exc, task_id)
                output.print_ai(response.content)
                plan_progress = self._mark_plan_current_blocked(task_id, llm_failure_summary(exc, "planner", task_id))
                await self._finalize_task_memory(
                    task_id,
                    "failed",
                    messages + [response],
                    {"reason": llm_failure_summary(exc, "planner", task_id), "plan_progress": plan_progress},
                )
                return {"messages": [response], "plan_progress": plan_progress, "next_step": "finish"}

            raw_plan_content = str(response.content or "").strip()
            try:
                typed_planner_skill_decision = parse_typed_skill_decision(
                    raw_plan_content
                )
            except SkillAccessError as exc:
                return {
                    "messages": [response, SystemMessage(content=json.dumps(
                        exc.to_dict(), ensure_ascii=False, sort_keys=True,
                    ))],
                    "pending_action": {},
                    "skill_decision_result": exc.to_dict(),
                    "next_step": "planner",
                }
            planner_envelope = None
            planner_envelope_error: Dict[str, Any] = {}
            if typed_planner_skill_decision is None:
                try:
                    planner_envelope = parse_planner_outcome_envelope(
                        raw_plan_content,
                        # Every live Planner response is a new candidate and
                        # therefore must use the typed 1.2.1 envelope. Legacy
                        # persisted plans are migrated at the state-reader
                        # boundary, never by weakening this admission gate.
                        allow_legacy_plan=False,
                    )
                except PlannerEnvelopeError as exc:
                    planner_envelope_error = exc.to_diagnostic()

            current_planner_state = load_plan_state(self.data_path, task_id)
            current_planner_task = canonical_task_spec_for_state(
                current_planner_state
            ) or task_spec
            current_planner_context = build_node_context(
                node_type="planner",
                task_spec=current_planner_task,
                plan_state=current_planner_state,
                authoritative_user_turn_revision=(
                    self._authoritative_user_turn_revision(current_planner_state)
                ),
                continuation_id=str(
                    (current_planner_state.get("task_state") or {}).get(
                        "skill_continuation_id"
                    ) or ""
                ),
            )
            planner_staleness = evaluate_node_staleness(
                planner_node_context.binding,
                current_planner_context.binding.to_dict(),
            )
            if not planner_staleness.usable:
                stale_task_state = dict(current_planner_state.get("task_state") or {})
                stale_epoch = dict(stale_task_state.get("planning_epoch") or {})
                if stale_epoch:
                    stale_epoch["status"] = "stale_semantic_base"
                    stale_task_state["planning_epoch"] = stale_epoch
                    current_planner_state["task_state"] = stale_task_state
                    save_plan_state(self.data_path, task_id, current_planner_state)
                self._node_invocations.mark_stale_signature_handled(
                    planner_staleness.stale_signature
                )
                self._record_durable_skill_event(
                    task_id,
                    "stale_node_result_discarded",
                    {
                        "caller_node": "planner",
                        "caller_invocation_id": planner_node_context.binding.invocation_id,
                        "changed_preconditions": list(
                            planner_staleness.changed_preconditions
                        ),
                    },
                )
                return {
                    "messages": [SystemMessage(content=json.dumps({
                        "decision_result": "STALE_NODE_RESULT",
                        "caller_node": "planner",
                        "caller_invocation_id": planner_node_context.binding.invocation_id,
                        "changed_preconditions": list(
                            planner_staleness.changed_preconditions
                        ),
                        "counts_as_failure": False,
                        "consumes_execution_retry": False,
                    }, ensure_ascii=False, sort_keys=True))],
                    "stale_node_result": {
                        "decision_result": "STALE_NODE_RESULT",
                        "caller_node": "planner",
                        "caller_invocation_id": planner_node_context.binding.invocation_id,
                        "changed_preconditions": list(
                            planner_staleness.changed_preconditions
                        ),
                    },
                    "next_step": "planner",
                }
            if typed_planner_skill_decision is not None:
                self._refund_planner_call_for_skill_continuation(
                    task_id,
                    str(planning_epoch.get("planning_epoch_id") or ""),
                )
                try:
                    return await self._handle_skill_node_decision(
                        task_id=task_id,
                        caller_node="planner",
                        graph_node="planner",
                        decision=typed_planner_skill_decision,
                        node_context=planner_node_context,
                        response=response,
                        selected_skill_ids=planner_skill_pool,
                    )
                except SkillAccessError as exc:
                    return {
                        "messages": [response, SystemMessage(content=json.dumps(
                            exc.to_dict(), ensure_ascii=False, sort_keys=True,
                        ))],
                        "pending_action": {},
                        "skill_decision_result": exc.to_dict(),
                        "next_step": "planner",
                    }
            self._complete_durable_skill_continuation(
                task_id,
                caller_node="planner",
            )
            if (
                planner_envelope is not None
                and planner_envelope.outcome_type == TASKSPEC_RECONCILIATION_REQUIRED
            ):
                try:
                    fingerprint, fingerprint_payload = reconciliation_fingerprint(
                        planner_envelope.payload,
                        task_semantic_identity=current_planner_context.binding.task_semantic_hash,
                    )
                except PlannerCandidateError as exc:
                    reconciliation_issues = [exc.to_diagnostic()]
                    current_planner_state = record_planning_failure(
                        current_planner_state,
                        validation_issues=reconciliation_issues,
                        planning_epoch_id=str(
                            planning_epoch.get("planning_epoch_id") or ""
                        ),
                        task_spec_revision_value=task_revision,
                        validation_source="planner_reconciliation_admission",
                        candidate=planner_envelope.payload,
                        previous_correction={
                            "status": "rejected",
                            "outcome_code": exc.code,
                        },
                    )
                    reconciliation_issues = list(
                        ((current_planner_state.get("task_state") or {}).get(
                            "planning_failure"
                        ) or {}).get("validation_issues")
                        or []
                    )
                    save_plan_state(self.data_path, task_id, current_planner_state)
                    return {
                        "messages": [SystemMessage(content=json.dumps(
                            {
                                "code": "PLANNER_CANDIDATE_INVALID",
                                "validation_issues": reconciliation_issues,
                            },
                            ensure_ascii=False,
                            sort_keys=True,
                        ))],
                        "validation_issues": reconciliation_issues,
                        "next_step": "planner",
                    }
                current_task_state = dict(current_planner_state.get("task_state") or {})
                current_ledger = dict(
                    current_task_state.get("reconciliation_ledger") or {}
                )
                relevant_evidence_revision = (
                    relevant_reconciliation_evidence_revision(
                        planner_envelope.payload,
                        current_planner_task,
                    )
                )
                guard = reconciliation_guard_status(
                    current_ledger,
                    fingerprint=fingerprint,
                    task_semantic_identity=current_planner_context.binding.task_semantic_hash,
                    relevant_evidence_revision=relevant_evidence_revision,
                )
                if guard["terminal"]:
                    current_task_state["terminal_status"] = (
                        "TASKSPEC_RECONCILIATION_NONPROGRESS"
                    )
                    current_planner_state["task_state"] = current_task_state
                    save_plan_state(self.data_path, task_id, current_planner_state)
                    return {
                        "messages": [SystemMessage(content=(
                            "TASKSPEC_RECONCILIATION_NONPROGRESS: the same typed "
                            "reconciliation repeated without TaskSpec or relevant-evidence progress."
                        ))],
                        "task_status": TASK_STATUS_BLOCKED,
                        "next_step": "finish",
                    }
                reconciliation_record = {
                    "outcome_type": TASKSPEC_RECONCILIATION_REQUIRED,
                    "fingerprint": fingerprint,
                    "fingerprint_payload": fingerprint_payload,
                    "missing_semantic_facts": deepcopy(list(
                        planner_envelope.payload.get("missing_semantic_facts") or []
                    )),
                    "task_semantic_revision": task_spec_revision(current_planner_task),
                    "task_semantic_identity": current_planner_context.binding.task_semantic_hash,
                    "relevant_evidence_revision": relevant_evidence_revision,
                    "candidate_scope_id": planner_node_context.binding.candidate_scope_id,
                    "status": "pending_consultant",
                }
                current_task_state["planner_reconciliation"] = reconciliation_record
                ended_epoch = dict(current_task_state.get("planning_epoch") or {})
                ended_epoch["status"] = "reconciliation_required"
                current_task_state["planning_epoch"] = ended_epoch
                current_planner_state["task_state"] = current_task_state
                current_planner_state = resolve_planning_failure(
                    current_planner_state,
                    outcome_code=TASKSPEC_RECONCILIATION_REQUIRED,
                )
                save_plan_state(self.data_path, task_id, current_planner_state)
                return {
                    "messages": [SystemMessage(content=(
                        "<taskspec_reconciliation_required>"
                        + json.dumps(fingerprint_payload, ensure_ascii=False, sort_keys=True)
                        + "</taskspec_reconciliation_required>"
                    ))],
                    "planner_reconciliation": reconciliation_record,
                    "planning_epoch": ended_epoch,
                    "next_step": "consultant",
                }

            plan_content = (
                json.dumps(
                    planner_envelope.plan_candidate_body(),
                    ensure_ascii=False,
                    sort_keys=True,
                )
                if planner_envelope is not None
                else raw_plan_content
            )
            structure_errors: List[Dict[str, Any]] = (
                [validation_issue(
                    str(planner_envelope_error.get("code") or "PLANNER_CANDIDATE_INVALID"),
                    owner="planner",
                    repair_target="$",
                    field_path="$",
                    message=str(
                        planner_envelope_error.get("parser_message")
                        or planner_envelope_error.get("message")
                        or planner_envelope_error.get("code")
                        or "Planner envelope is invalid."
                    ),
                    validator_id="planner_envelope",
                    **{
                        key: deepcopy(value)
                        for key, value in planner_envelope_error.items()
                        if key not in {"code", "field_path", "message"}
                    },
                )]
                if planner_envelope_error
                else []
            )
            candidate_ref_keys: Dict[str, Any] = {}
            candidate_usage: List[Dict[str, Any]] = []
            allocation_intent: Dict[str, Any] = {}
            plan_proposal: Any = {}
            try:
                plan_proposal = json.loads(plan_content)
                if isinstance(plan_proposal, Mapping):
                    if planner_envelope is not None and not planner_envelope.legacy_envelope:
                        artifact_handles = {
                            str(handle): str(item.get("stable_identity") or "")
                            for handle, item in planner_node_context.binding.semantic_handle_map.items()
                            if isinstance(item, Mapping)
                            and item.get("object_type") == "artifact"
                        }
                        availability_origins = {
                            str(item.get("stable_identity") or ""): (
                                "verified_task_input"
                                if str(item.get("direction") or "") == "input"
                                else "not_yet_available"
                            )
                            for item in planner_node_context.binding.semantic_handle_map.values()
                            if isinstance(item, Mapping)
                            and item.get("object_type") == "artifact"
                            and str(item.get("stable_identity") or "")
                        }
                        (
                            candidate_ref_keys,
                            candidate_usage,
                            deterministic_issues,
                        ) = validate_planner_candidate_deterministically(
                            plan_proposal,
                            candidate_scope_id=(
                                planner_node_context.binding.candidate_scope_id
                            ),
                            authoritative_handles=artifact_handles,
                            availability_origins=availability_origins,
                            authoritative_bindings={
                                str(handle): dict(item)
                                for handle, item in planner_node_context.binding.semantic_handle_map.items()
                                if isinstance(item, Mapping)
                                and item.get("object_type") == "artifact"
                            },
                        )
                        if deterministic_issues:
                            structure_errors = [
                                normalize_validation_issue(issue)
                                for issue in deterministic_issues
                            ]
                        else:
                            allocation_intent = prepare_allocation_intent(
                                plan_proposal,
                                candidate_scope_id=(
                                    planner_node_context.binding.candidate_scope_id
                                ),
                                planning_epoch_id=str(
                                    planning_epoch.get("planning_epoch_id") or ""
                                ),
                            )
                    plan_proposal = resolve_plan_proposal_handles(
                        plan_proposal,
                        planner_node_context.binding,
                    )
                    plan_content = json.dumps(
                        plan_proposal,
                        ensure_ascii=False,
                        sort_keys=True,
                    )
            except json.JSONDecodeError:
                pass
            except SemanticHandleError as exc:
                structure_errors = [validation_issue(
                    "PLANNER_CANDIDATE_INVALID",
                    owner="planner",
                    repair_target="$",
                    field_path="$",
                    message=str(exc),
                    validator_id="semantic_handle_resolver",
                )]
            except PlannerCandidateError as exc:
                structure_errors = [normalize_validation_issue({
                    **exc.to_diagnostic(),
                    "validator_id": "plan_artifact_refs",
                    "repair_target": exc.field_path,
                })]
            if not structure_errors:
                try:
                    candidate_for_repair = build_plan_state(
                        task_id,
                        plan_content,
                        strict=True,
                    )
                    candidate_for_repair["artifact_usage"] = deepcopy(candidate_usage)
                    candidate_for_repair["allocation_intent"] = deepcopy(allocation_intent)
                    candidate_for_repair["candidate_scope_id"] = str(
                        planner_node_context.binding.candidate_scope_id
                    )
                    candidate_for_repair["planning_epoch_id"] = str(
                        planning_epoch.get("planning_epoch_id") or ""
                    )
                except PlanStructureError as first_error:
                    structure_errors = [
                        validation_issue(
                            "PLAN_STRUCTURE_INVALID",
                            owner="planner",
                            repair_target=str(item.get("field_path") or "$"),
                            field_path=str(item.get("field_path") or "$"),
                            message=str(item.get("message") or item),
                            validator_id="structured_plan_schema",
                        )
                        for item in first_error.diagnostics
                    ]
            if structure_errors:
                rejected_state = load_plan_state(self.data_path, task_id)
                rejected_state = record_planning_failure(
                    rejected_state,
                    validation_issues=structure_errors,
                    planning_epoch_id=str(
                        planning_epoch.get("planning_epoch_id") or ""
                    ),
                    task_spec_revision_value=task_revision,
                    validation_source="planner_candidate_admission",
                    candidate=(
                        plan_proposal
                        if isinstance(plan_proposal, Mapping)
                        else None
                    ),
                    previous_correction={
                        "status": "rejected",
                        "outcome_code": str(
                            structure_errors[0].get("code")
                            if structure_errors
                            else "PLANNER_CANDIDATE_INVALID"
                        ),
                    },
                )
                structure_errors = list(
                    ((rejected_state.get("task_state") or {}).get(
                        "planning_failure"
                    ) or {}).get("validation_issues")
                    or []
                )
                save_plan_state(self.data_path, task_id, rejected_state)
                rejected_epoch = dict(
                    (rejected_state.get("task_state") or {}).get("planning_epoch")
                    or {}
                )
                return {
                    "messages": [SystemMessage(content=json.dumps(
                        {
                            "code": "PLANNER_CANDIDATE_REJECTED",
                            "validation_issues": structure_errors,
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                        default=str,
                    ))],
                    "validation_issues": structure_errors,
                    "pending_action": {},
                    "failure_owner": "planner",
                    "planning_epoch": rejected_epoch,
                    "next_step": "planner",
                }
            candidate_for_repair, renderer_normalization, violations = normalize_plan_contracts(
                candidate_for_repair,
                renderer_records=renderer_records,
                output_contracts=canonical_output_contracts,
                task_spec=task_spec,
            )
            candidate_for_repair = self._bind_plan_execution_capability_contracts(
                candidate_for_repair,
                selected_skills,
            )
            plan_content = render_structured_plan(candidate_for_repair)
            violations.extend(self._skill_plan_violations(
                plan_content,
                selected_skills,
                user_msg=task_requirement_text,
                workflow_handoff=workflow_handoff,
            ))
            violations.extend(self._plan_step_skill_violations(candidate_for_repair, selected_skills))
            violations.extend(self._plan_execution_capability_violations(
                candidate_for_repair,
                selected_skills,
            ))

            candidate_for_repair = derive_plan_validation_state(
                candidate_for_repair,
                violations,
            )
            violations = list(candidate_for_repair.get("validation_issues") or [])
            initial_contract_violations = deepcopy(violations)
            validation_reason_codes = sorted({
                str(item.get("code") or item.get("violation_code") or item.get("field") or "semantic_plan_violation")
                if isinstance(item, dict) else "semantic_plan_violation"
                for item in violations
            })
            if violations:
                logger.info(
                    "Planner candidate rejected: task=%s reason_codes=%s",
                    task_id,
                    validation_reason_codes,
                )

            workflow_handoff = strip_workflow_activation(workflow_handoff)
            active_skills_state = []
            future_skills = []
            active_batch_id = ""

            # 保存计划文件
            plan_dir = os.path.join(self.data_path, "task_outputs", task_id)
            os.makedirs(plan_dir, exist_ok=True)
            plan_file = os.path.join(plan_dir, "plan.md")
            previous_plan_state = load_plan_state(self.data_path, task_id)
            if violations:
                rejected_state = record_planning_failure(
                    previous_plan_state,
                    validation_issues=violations,
                    planning_epoch_id=str(
                        planning_epoch.get("planning_epoch_id") or ""
                    ),
                    task_spec_revision_value=task_revision,
                    validation_source="plan_contract_validation",
                    candidate=candidate_for_repair,
                    previous_correction={
                        "status": "rejected",
                        "outcome_code": str(
                            (violations[0] or {}).get("code")
                            if isinstance(violations[0], Mapping)
                            else "PLAN_CONTRACT_INVALID"
                        ),
                    },
                )
                violations = list(
                    ((rejected_state.get("task_state") or {}).get(
                        "planning_failure"
                    ) or {}).get("validation_issues")
                    or []
                )
                save_plan_state(self.data_path, task_id, rejected_state)
                rejected_epoch = dict(
                    (rejected_state.get("task_state") or {}).get("planning_epoch")
                    or {}
                )
                return {
                    "messages": [SystemMessage(content=json.dumps(
                        {
                            "code": "PLANNER_CANDIDATE_REJECTED",
                            "validation_issues": violations,
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                        default=str,
                    ))],
                    "validation_issues": violations,
                    "pending_action": {},
                    "failure_owner": "planner",
                    "planning_epoch": rejected_epoch,
                    "next_step": "planner",
                }
            # The normalized object contains controller-owned renderer args and
            # bound outputs that are intentionally absent from rendered
            # Markdown.  Never reparse the display text and discard them.
            candidate_plan_state = deepcopy(candidate_for_repair)
            candidate_plan_state["plan_file"] = plan_file
            bind_plan_to_task_revision(candidate_plan_state, task_revision)
            self._plan_step_skill_violations(candidate_plan_state, selected_skills)
            candidate_plan_state["user_constraints"] = list(state.get("user_constraints", []) or [])
            candidate_plan_state["selected_skill_ids"] = list(selected_skills)
            _bind_current_task_spec_record(candidate_plan_state, task_spec)
            # The atomic writer consumes this Controller marker only after all
            # deterministic candidate validation has succeeded.  Legacy and
            # runtime-only saves never create a new PlanSnapshot implicitly.
            candidate_plan_state["plan_commit_requested"] = not bool(violations)
            candidate_plan_state["planner_quality_telemetry"] = {
                "schema_version": 2,
                "first_pass_schema_valid": bool(candidate_for_repair.get("steps")),
                "first_pass_contract_valid": not bool(initial_contract_violations),
                "repair_required": bool(active_planning_failure),
                "validation_reason_codes": sorted({
                    str(item.get("code") or item.get("violation_code") or item.get("field") or "contract_violation")
                    if isinstance(item, dict) else str(item)[:120]
                    for item in initial_contract_violations
                }),
                "correction_context_present": bool(active_planning_failure),
                "final_contract_valid": not bool(violations),
                "planner_llm_calls": 1,
            }
            transition_issues = full_replan_transition_issues(
                previous_plan_state,
                candidate_plan_state,
            )
            if transition_issues:
                rejected_state = record_planning_failure(
                    previous_plan_state,
                    validation_issues=transition_issues,
                    planning_epoch_id=str(
                        planning_epoch.get("planning_epoch_id") or ""
                    ),
                    task_spec_revision_value=task_revision,
                    validation_source="full_replan_transition_gate",
                    candidate=candidate_plan_state,
                    previous_correction={
                        "status": "rejected",
                        "outcome_code": str(
                            transition_issues[0].get("code")
                            or "FULL_REPLAN_TRANSITION_INVALID"
                        ),
                    },
                )
                transition_issues = list(
                    ((rejected_state.get("task_state") or {}).get(
                        "planning_failure"
                    ) or {}).get("validation_issues")
                    or []
                )
                save_plan_state(self.data_path, task_id, rejected_state)
                return {
                    "messages": [SystemMessage(content=json.dumps(
                        {
                            "code": "FULL_REPLAN_TRANSITION_INVALID",
                            "validation_issues": transition_issues,
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                        default=str,
                    ))],
                    "validation_issues": transition_issues,
                    "failure_owner": "planner",
                    "pending_action": {},
                    "next_step": "planner",
                }
            candidate_plan_state = carry_forward_plan_lifecycle(previous_plan_state, candidate_plan_state)
            candidate_plan_state = carry_forward_completed_execution_history(
                previous_plan_state,
                candidate_plan_state,
            )
            candidate_plan_state = resolve_planning_failure(candidate_plan_state)
            candidate_plan_state["pending_review_diff"] = []
            revision_result: Dict[str, Any] = {}
            replan_requested = bool(
                previous_plan_state.get("steps")
                and (
                    previous_plan_state.get("stale_step_ids")
                    or previous_plan_state.get("revalidation_required_step_ids")
                    or (state.get("knowledge_conflict_summary") or {}).get("blocking_conflicts")
                )
            )
            if feature_enabled("ENABLE_PLAN_VERSIONING", True) and replan_requested:
                plan_manager = PlanRevisionManager(
                    previous_plan_state,
                    self._knowledge_conflict_root(task_id),
                    task_id=task_id,
                )
                changed_ids = changed_plan_step_ids(previous_plan_state, candidate_plan_state)
                revision = plan_manager.revise(
                    new_plan_state=candidate_plan_state,
                    trigger_conflict_ids=(state.get("knowledge_conflict_summary") or {}).get("blocking_conflicts", []),
                    revision_scope="stage",
                    changed_step_ids=changed_ids,
                    preserved_constraints=list(state.get("user_constraints", []) or []),
                    reason="Planner regenerated the affected plan after a knowledge conflict or stale-step audit.",
                )
                revision_result = revision.to_dict()
                if revision.status == "applied":
                    plan_state = plan_manager.plan_state
                else:
                    # A budget/constraint/oscillation rejection must not let a
                    # newly generated but unapproved plan leak into execution.
                    plan_state = previous_plan_state
                    preserved_plan = str(state.get("current_plan") or "").strip()
                    if preserved_plan:
                        plan_content = preserved_plan
                    else:
                        try:
                            plan_content = Path(plan_file).read_text(encoding="utf-8")
                        except OSError:
                            plan_content = ""
                    plan_content += (
                        "\n\n## Plan Revision Blocked\n"
                        f"- {revision.blocked_reason or 'The proposed revision was not applied.'}\n"
                    )
            else:
                plan_state = candidate_plan_state
                if feature_enabled("ENABLE_PLAN_VERSIONING", True):
                    plan_manager = PlanRevisionManager(
                        plan_state,
                        self._knowledge_conflict_root(task_id),
                        task_id=task_id,
                    )
                    plan_state = plan_manager.plan_state
                    plan_manager.persist_active()
            plan_state["user_constraints"] = list(state.get("user_constraints", []) or [])
            bind_plan_to_task_revision(plan_state, task_revision)
            if planner_feedback:
                task_state_for_plan = dict(plan_state.get("task_state") or {})
                task_state_for_plan["planner_feedback"] = {
                    **planner_feedback,
                    "status": "applied",
                    "applied_plan_version": str(plan_state.get("plan_version") or ""),
                }
                plan_state["task_state"] = task_state_for_plan
            try:
                save_plan_state(self.data_path, task_id, plan_state)
            except StateCASConflict:
                # The candidate was valid, but another writer advanced the
                # authoritative generation after this invocation's final
                # staleness check.  This is not a Planner candidate defect and
                # must never enter candidate repair.
                stale_code = "STALE_PLANNER_INVOCATION_NON_SEMANTIC"
                stale_epoch: Dict[str, Any] = {}
                bookkeeping_committed = False
                for _ in range(3):
                    latest = load_plan_state(self.data_path, task_id)
                    latest_task = canonical_task_spec_for_state(latest) or task_spec
                    latest_context = build_node_context(
                        node_type="planner",
                        task_spec=latest_task,
                        plan_state=latest,
                    )
                    semantic_base_changed = bool(
                        latest_context.binding.task_semantic_hash
                        != planner_node_context.binding.task_semantic_hash
                        or latest_context.binding.plan_semantic_hash
                        != planner_node_context.binding.plan_semantic_hash
                    )
                    latest_task_state = dict(latest.get("task_state") or {})
                    stale_epoch = dict(latest_task_state.get("planning_epoch") or {})
                    if (
                        stale_epoch
                        and str(stale_epoch.get("planning_epoch_id") or "")
                        == str(planning_epoch.get("planning_epoch_id") or "")
                    ):
                        if semantic_base_changed:
                            stale_code = "STALE_PLANNER_INVOCATION_SEMANTIC_BASE"
                            stale_epoch["status"] = "semantic_base_stale"
                        else:
                            stale_epoch["stale_redispatches"] = int(
                                stale_epoch.get("stale_redispatches") or 0
                            ) + 1
                            stale_epoch["status"] = "active"
                        latest_task_state["planning_epoch"] = stale_epoch
                        latest["task_state"] = latest_task_state
                    elif semantic_base_changed:
                        stale_code = "STALE_PLANNER_INVOCATION_SEMANTIC_BASE"
                    try:
                        save_plan_state(self.data_path, task_id, latest)
                        bookkeeping_committed = True
                        break
                    except StateCASConflict:
                        continue
                    except Exception as exc:
                        classification = classify_io_exception(exc)
                        logger.exception(
                            "Planner stale-redispatch bookkeeping failed: task=%s class=%s code=%s",
                            task_id,
                            classification["error_class"],
                            classification["code"],
                        )
                        return {
                            "messages": [SystemMessage(content=(
                                f"{classification['error_class']}: {classification['code']}"
                            ))],
                            "failure_type": classification["error_class"],
                            "failure_stage": "planner_atomic_commit",
                            "recovery_status": (
                                "paused_retryable"
                                if classification["retry_safe"]
                                else "blocked_internal"
                            ),
                            "task_status": (
                                "paused_retryable"
                                if classification["retry_safe"]
                                else TASK_STATUS_BLOCKED
                            ),
                            "next_step": "finish",
                        }
                if not bookkeeping_committed:
                    return {
                        "messages": [SystemMessage(content=(
                            "INTERNAL_CONTROLLER_INVARIANT_ERROR: "
                            "STATE_CAS_REDISPATCH_NONCONVERGENT"
                        ))],
                        "failure_type": "INTERNAL_CONTROLLER_INVARIANT_ERROR",
                        "failure_stage": "planner_atomic_commit",
                        "task_status": TASK_STATUS_BLOCKED,
                        "next_step": "finish",
                    }
                return {
                    "messages": [SystemMessage(content=stale_code)],
                    "planning_epoch": stale_epoch,
                    "pending_action": {},
                    "next_step": "planner",
                }
            except Exception as exc:
                classification = classify_io_exception(exc)
                logger.exception(
                    "Planner atomic commit failed: task=%s class=%s code=%s",
                    task_id,
                    classification["error_class"],
                    classification["code"],
                )
                return {
                    "messages": [SystemMessage(content=(
                        f"{classification['error_class']}: {classification['code']}"
                    ))],
                    "failure_type": classification["error_class"],
                    "failure_stage": "planner_atomic_commit",
                    "recovery_status": (
                        "paused_retryable"
                        if classification["retry_safe"]
                        else "blocked_internal"
                    ),
                    "task_status": (
                        "paused_retryable"
                        if classification["retry_safe"]
                        else TASK_STATUS_BLOCKED
                    ),
                    "next_step": "finish",
                }
            blocking_plan_issues = [
                dict(item) for item in plan_state.get("validation_issues", []) or []
                if isinstance(item, Mapping)
                and str(item.get("severity") or "").lower() in {"error", "blocking", "fatal"}
            ]
            repair_status = str((plan_state.get("repair_convergence") or {}).get("status") or "")
            deterministic_block_reason = ""
            validation_route = "plan_review"
            if blocking_plan_issues:
                owners = {str(item.get("owner") or "internal") for item in blocking_plan_issues}
                deterministic_block_reason = (
                    "Plan contract validation is unresolved: "
                    + json.dumps(blocking_plan_issues, ensure_ascii=False, sort_keys=True, default=str)
                )
                if repair_status == "blocked_non_convergent":
                    validation_route = "finish"
                elif owners.issubset({"planner"}):
                    validation_route = "planner"
                elif owners.intersection({"task_spec", "external_input"}):
                    validation_route = "consultant"
                else:
                    validation_route = "finish"
                if validation_route == "finish":
                    self._mark_plan_current_blocked(task_id, deterministic_block_reason)
                    plan_state = load_plan_state(self.data_path, task_id)
            with open(plan_file, "w", encoding="utf-8") as f:
                f.write(
                    "# Task Plan\n"
                    f"Generated: {datetime.now().isoformat()}\n"
                    f"Selected Skills: {', '.join(selected_skills) if selected_skills else 'None'}\n"
                    f"Workflow ID: {workflow_handoff.get('workflow_id', 'None') if workflow_handoff else 'None'}\n"
                    f"Active Batch: {active_batch_id or 'None'}\n"
                    f"Active Skills: {', '.join(active_skills_state) if active_skills_state else 'None'}\n"
                    f"Future Skills: {', '.join(future_skills) if future_skills else 'None'}\n"
                    f"Required Skills All: {', '.join(required_skills_all) if required_skills_all else 'None'}\n"
                    f"Selected Skills Raw: {', '.join(selected_skills_raw) if selected_skills_raw else 'None'}\n"
                    f"Skill Selection Source: {skill_selection_source}\n\n"
                    f"{plan_content}"
                )
            update_plan_markdown_status(plan_file, plan_state)
            plan_progress = render_plan_progress(plan_state)

            conflict_update = self._knowledge_conflict_update(
                task_id,
                {
                    **dict(state),
                    "current_plan": plan_content,
                    "user_constraints": state.get("user_constraints", []),
                },
                phase="plan_generated",
                plan_state=plan_state,
            )
            if revision_result:
                conflict_update["plan_revision_result"] = revision_result
            conflict_update["plan_revision"] = int(
                plan_state.get("plan_revision") or 0
            )

            # 写入思维链日志
            log_plan_to_cot(self.supervisor_node, task_id, plan_content)
            await self._observe_session_memory(
                task_id,
                "planner",
                messages + [AIMessage(content=plan_content)],
                {
                    "plan_file": plan_file,
                    "selected_skills": selected_skills,
                    "runtime_audit": runtime_audits,
                    "active_skills": active_skills_state,
                    "future_skills": future_skills,
                    "required_skills_all": required_skills_all,
                    "workflow_id": workflow_handoff.get("workflow_id", "") if workflow_handoff else "",
                "active_batch_id": active_batch_id,
                "skill_selection_source": skill_selection_source,
                "plan_progress": plan_progress,
                "task_spec": task_spec,
                "task_revision": task_revision,
                "knowledge_conflicts": conflict_update.get("knowledge_conflicts", []),
                "knowledge_conflict_summary": conflict_update.get("knowledge_conflict_summary", {}),
                "plan_version": conflict_update.get("plan_version", plan_state.get("plan_version", "plan_v1")),
                "plan_stale_steps": conflict_update.get("plan_stale_steps", []),
                "plan_revalidation_steps": conflict_update.get("plan_revalidation_steps", []),
                "plan": plan_content[:4000],
            },
        )

            return {
                "current_plan": plan_content,
                "plan_progress": plan_progress,
                "task_spec": task_spec,
                "task_revision": task_revision,
                "validation_issues": blocking_plan_issues,
                "selected_skills": selected_skills,
                "runtime_audit": runtime_audits,
                "selected_skills_raw": selected_skills_raw,
                "active_skills": active_skills_state,
                "future_skills": future_skills,
                "required_skills_all": required_skills_all,
                "candidate_skills": candidate_skills,
                **conflict_update,
                "workflow_state": workflow_handoff,
                "workflow_handoff": workflow_handoff,
                "workflow_stages": workflow_handoff.get("workflow_stages", []) if workflow_handoff else [],
                "workflow_id": workflow_handoff.get("workflow_id", "") if workflow_handoff else "",
                "active_batch_id": active_batch_id,
                "skill_selection_source": skill_selection_source,
                "messages": [AIMessage(content=(
                    f"⛔ {deterministic_block_reason}"
                    if deterministic_block_reason
                    else f"📋 Plan ready (saved to {plan_file})"
                ))],
                "pending_action": {},
                "pending_recovery_action": {},
                "recovery_decision": {},
                "required_next_action": "",
                "failure_owner": "",
                "recovery_scope": "",
                "recovery_phase": "",
                "recovery_status": "",
                "supervisor_verdict": "",
                "completion_gate_result": {},
                "next_step": validation_route,
            }

        # ════════════════════════════════════════════
        # Node 1.5: Plan Review（带记忆状态展示）
        # ════════════════════════════════════════════
        async def plan_review(state: AgentState):
            output.print_node_header("plan_review")
            plan    = state.get("current_plan", "")
            task_id = state.get("task_id", "default")
            messages = state.get("messages", [])
            task_revision = self._task_revision_for_state(dict(state))
            persisted_plan = load_plan_state(self.data_path, task_id)
            task_spec = self._task_spec_for_state(dict(state), messages)
            review_skill_ids = list(
                persisted_plan.get("selected_skill_ids")
                or state.get("selected_skills")
                or []
            )
            review_renderer_records = [
                self.skill_manager.get_renderer_record(skill_id)
                for skill_id in review_skill_ids
                if self.skill_manager and self.skill_manager.has_renderer(skill_id)
            ]
            persisted_plan, _, review_issues = normalize_plan_contracts(
                persisted_plan,
                renderer_records=review_renderer_records,
                output_contracts=effective_output_contracts(task_spec, project_root=project_root),
                task_spec=task_spec,
            )
            persisted_plan = self._bind_plan_execution_capability_contracts(
                persisted_plan,
                review_skill_ids,
            )
            review_issues.extend(self._plan_execution_capability_violations(
                persisted_plan,
                review_skill_ids,
            ))
            persisted_plan = derive_plan_validation_state(
                persisted_plan,
                review_issues,
            )
            review_issues = list(persisted_plan.get("validation_issues") or [])
            bind_plan_to_task_revision(persisted_plan, task_revision)
            save_plan_state(self.data_path, task_id, persisted_plan)
            blocking_review_issues = [
                dict(item) for item in review_issues
                if isinstance(item, Mapping)
                and str(item.get("severity") or "").lower() in {"error", "blocking", "fatal"}
            ]
            if blocking_review_issues:
                owners = {str(item.get("owner") or "internal") for item in blocking_review_issues}
                convergence = str((persisted_plan.get("repair_convergence") or {}).get("status") or "")
                if convergence == "blocked_non_convergent":
                    route = "finish"
                elif owners.issubset({"planner"}):
                    route = "planner"
                elif owners.intersection({"task_spec", "external_input"}):
                    route = "consultant"
                else:
                    route = "finish"
                if route == "planner":
                    persisted_plan = record_planning_failure(
                        persisted_plan,
                        validation_issues=blocking_review_issues,
                        planning_epoch_id=str(
                            ((persisted_plan.get("task_state") or {}).get(
                                "planning_epoch"
                            ) or {}).get("planning_epoch_id")
                            or ""
                        ),
                        task_spec_revision_value=task_revision,
                        validation_source="plan_review",
                    )
                    blocking_review_issues = list(
                        ((persisted_plan.get("task_state") or {}).get(
                            "planning_failure"
                        ) or {}).get("validation_issues")
                        or []
                    )
                    save_plan_state(self.data_path, task_id, persisted_plan)
                review_message = (
                    json.dumps(
                        {
                            "code": "PLAN_REVIEW_REJECTED",
                            "validation_issues": blocking_review_issues,
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                        default=str,
                    )
                    if route == "planner"
                    else (
                        "Plan Review refused an invalid plan before human approval: "
                        + json.dumps(
                            blocking_review_issues,
                            ensure_ascii=False,
                            sort_keys=True,
                            default=str,
                        )
                    )
                )
                return {
                    "messages": [SystemMessage(content=review_message)],
                    "validation_issues": blocking_review_issues,
                    "required_next_action": "PLAN_CONTRACT_REPAIR",
                    "next_step": route,
                }
            _bind_current_task_spec_record(persisted_plan, task_spec)
            current_registry = self._knowledge_claim_registry(
                task_id,
                {**dict(state), "task_spec": task_spec},
                persisted_plan,
            )
            current_claim_hash = semantic_claim_set_hash(current_registry)
            current_constraint_hash = canonical_constraint_hash(task_spec)
            semantic_delta = approval_semantic_delta(
                persisted_plan,
                current_constraint_hash=current_constraint_hash,
                current_claim_set_hash=current_claim_hash,
            )
            reused_validation = validate_plan_for_generate(persisted_plan, task_revision)
            if reused_validation.get("valid") and not semantic_delta["changed"]:
                plan_progress = render_plan_progress(persisted_plan)
                logger.info(
                    "Plan Review skipped for unchanged approved plan: task=%s plan_revision=%s semantic_hash=%s",
                    task_id,
                    persisted_plan.get("plan_revision"),
                    str(persisted_plan.get("semantic_plan_hash") or "")[:16],
                )
                return {
                    "messages": [SystemMessage(content="<control_event type=\"plan_approval_reused\" />")],
                    "plan_progress": plan_progress,
                    "next_step": "generate",
                }

            ambiguous_critical = [
                item for item in semantic_constraints_from_task_spec(task_spec)
                if item.get("needs_clarification")
                and item.get("strength") in {"hard", "required", "conditional", "ambiguous"}
            ]
            if ambiguous_critical:
                keys = ", ".join(str(item.get("semantic_key")) for item in ambiguous_critical[:5])
                return {
                    "messages": [SystemMessage(content=(
                        "Plan Review cannot approve unresolved critical semantic constraints: " + keys
                    ))],
                    "pending_human_question": {
                        "type": "semantic_constraint_clarification",
                        "stage": "plan_review",
                        "question": "Please clarify the unresolved critical constraint(s): " + keys,
                        "resume_step": "consultant",
                    },
                    "next_step": "ask_user",
                }

            conflict_update = self._knowledge_conflict_update(
                task_id,
                {**dict(state), "task_spec": task_spec},
                phase="before_plan_review",
                plan_state=persisted_plan,
            )
            persisted_plan["canonical_constraint_hash"] = current_constraint_hash
            persisted_plan["knowledge_claim_set_hash"] = current_claim_hash
            persisted_plan["approved_conflict_validation"] = {
                "phase": "before_plan_review",
                "blocking_conflicts": list(
                    (conflict_update.get("knowledge_conflict_summary") or {}).get("blocking_conflicts") or []
                ),
                "claim_set_hash": current_claim_hash,
                "canonical_constraint_hash": current_constraint_hash,
            }
            save_plan_state(self.data_path, task_id, persisted_plan)
            blocking_conflicts = list(
                (conflict_update.get("knowledge_conflict_summary") or {}).get("blocking_conflicts") or []
            )
            if blocking_conflicts:
                conflict_types = sorted({
                    str(item.get("conflict_type") or "")
                    for item in conflict_update.get("knowledge_conflicts", []) or []
                    if isinstance(item, dict) and item.get("conflict_id") in blocking_conflicts
                })
                reason = (
                    "Plan Review blocked before approval by typed semantic conflict(s): "
                    + ", ".join(conflict_types or blocking_conflicts)
                )
                return {
                    **conflict_update,
                    "messages": [SystemMessage(content=reason)],
                    "pending_action": {},
                    "required_next_action": "PLAN_PATCH",
                    "failure_owner": RecoveryFailureOwner.PLAN.value,
                    "next_step": "planner",
                }

            identity = plan_identity(persisted_plan)
            review_content = render_plan_review_content(persisted_plan, plan)

            # 显示内存状态
            mem_status = self.memory_manager.status(messages)
            print(f"\n📊 Memory: {mem_status}")

            # 展示计划（限制行数避免刷屏）
            wait_started = time.perf_counter()
            wait_started_at = timestamp_now()
            print(f"\n{Fore.CYAN}{'='*60}")
            print(f"  📋  PLAN REVIEW  |  Task: {task_id}")
            print(f"{'='*60}{Style.RESET_ALL}")
            output.page_text(f"Plan Review | Task: {task_id}", review_content, Fore.CYAN)
            print(f"{'─'*60}")

            try:
                user_input = self._prompt_user(
                    task_id,
                    "plan_review",
                    f"\n{Fore.YELLOW}Approve? [y/n/q] or type feedback > {Style.RESET_ALL}",
                    payload={"content": review_content[:2000]},
                    started_at=wait_started_at,
                ).strip()
            except HumanInputUnavailable as exc:
                self._record_human_wait(
                    task_id,
                    "plan_review",
                    wait_started,
                    f"<waiting_user:{type(exc).__name__}>",
                    {"content": review_content[:2000]},
                    started_at=wait_started_at,
                )
                return await self._suspend_for_human_input(
                    task_id,
                    "plan_review",
                    messages,
                    {"content": review_content[:2000]},
                    type(exc).__name__,
                )
            self._record_human_wait(
                task_id,
                "plan_review",
                wait_started,
                user_input,
                {"content": plan[:2000]},
                started_at=wait_started_at,
            )

            il = user_input.lower()

            if il in ["y", "yes", "approve", ""]:
                print(f"{Fore.GREEN}✓ Plan approved. Executing...{Style.RESET_ALL}")
                plan_state = self._ensure_plan_tracker(task_id, plan)
                _bind_current_task_spec_record(plan_state, task_spec)
                plan_state["canonical_constraint_hash"] = current_constraint_hash
                plan_state["knowledge_claim_set_hash"] = current_claim_hash
                plan_state["approved_conflict_validation"] = {
                    "phase": "before_plan_review",
                    "blocking_conflicts": [],
                    "claim_set_hash": current_claim_hash,
                    "canonical_constraint_hash": current_constraint_hash,
                }
                review_event_id = "review-" + hashlib.sha256(
                    f"{task_id}|{identity['plan_version']}|{identity['plan_semantic_hash']}".encode("utf-8")
                ).hexdigest()[:20]
                approve_plan_state(
                    plan_state,
                    task_revision,
                    approval_source="human_plan_review",
                    review_event_id=review_event_id,
                )
                plan_progress = self._persist_plan_tracker(task_id, plan_state) if plan_state.get("steps") else render_plan_progress(plan_state)
                approval_event = SystemMessage(
                    content=(
                        "<control_event type=\"plan_approved\" "
                        f"plan_revision=\"{int(plan_state.get('plan_revision') or 1)}\" "
                        f"semantic_hash=\"{str(plan_state.get('approved_plan_hash') or '')}\" />"
                    )
                )
                await self._observe_session_memory(
                    task_id,
                    "plan_review",
                    messages + [approval_event],
                    {"decision": "approved", "plan_excerpt": plan[:2000], "plan_progress": plan_progress},
                )
                return {
                    **conflict_update,
                    "messages": [approval_event],
                    "plan_progress": plan_progress,
                    "approval_scope": dict(plan_state.get("approval_scope") or {}),
                    "approval_projection": dict(plan_state.get("approval_projection") or {}),
                    "next_step": "generate",
                }
            elif il in ["q", "quit", "exit"]:
                print(f"{Fore.MAGENTA}🛑 Task cancelled.{Style.RESET_ALL}")
                await self._finalize_task_memory(
                    task_id,
                    "cancelled",
                    messages + [HumanMessage(content="Cancelled.")],
                    {"decision": "cancelled_at_plan_review"},
                )
                return {"messages": [HumanMessage(content="Cancelled.")], "next_step": "finish"}
            else:
                feedback = user_input if il not in ["n", "no"] else ""
                if not feedback:
                    feedback_wait_started = time.perf_counter()
                    feedback_started_at = timestamp_now()
                    try:
                        feedback = self._prompt_user(
                            task_id,
                            "plan_review_feedback",
                            f"{Fore.YELLOW}Feedback (Enter=auto-retry): {Style.RESET_ALL}",
                            payload={"content": plan[:2000]},
                            started_at=feedback_started_at,
                        ).strip()
                    except HumanInputUnavailable as exc:
                        self._record_human_wait(
                            task_id,
                            "plan_review_feedback",
                            feedback_wait_started,
                            f"<waiting_user:{type(exc).__name__}>",
                            {"content": plan[:2000]},
                            started_at=feedback_started_at,
                        )
                        return await self._suspend_for_human_input(
                            task_id,
                            "plan_review_feedback",
                            messages,
                            {"content": plan[:2000]},
                            type(exc).__name__,
                        )
                    if not feedback:
                        feedback = "Rejected. Try a different approach."
                print(f"{Fore.CYAN}📡 Feedback captured: {feedback}{Style.RESET_ALL}")
                turns, feedback_turn_ref = self._append_semantic_conversation_turn(
                    task_id,
                    role="user",
                    content=feedback,
                )
                feedback_turn = next(
                    (
                        item for item in reversed(turns)
                        if str(item.get("turn_ref") or "") == feedback_turn_ref
                    ),
                    {},
                )
                feedback_handle = str(
                    feedback_turn.get("turn_id") or feedback_turn_ref or "latest user turn"
                )
                review_consultation = deepcopy(dict(
                    state.get("consultation_state")
                    or (persisted_plan.get("task_state") or {}).get("consultation_state")
                    or {}
                ))
                review_consultation.update({
                    "phase": "consulting",
                    "consultation_status": "active",
                    "completion_decision": "needs_evidence",
                    "completion_reason": "plan_review_feedback_requires_semantic_classification",
                    "pending_question": None,
                    "pending_human_question": None,
                })
                review_consultation["last_feedback"] = [
                    *list(review_consultation.get("last_feedback") or [])[-7:],
                    {
                        "code": "PLAN_REVIEW_FEEDBACK",
                        "source_turn": feedback_handle,
                        "instruction": (
                            "Classify the latest Plan Review UserTurn into typed "
                            "TaskSpec operations, planner_feedback, both, or neither."
                        ),
                    },
                ]
                # Classification-first: durable free text alone does not
                # invalidate the PlanSnapshot or approval.  The Consultant's
                # typed result (TaskSpec mutation, PlannerFeedback, both, or
                # neither) owns the later transition.
                classification_state = load_plan_state(self.data_path, task_id)
                classification_task_state = dict(
                    classification_state.get("task_state") or {}
                )
                review_event_id = "review-classification-" + hashlib.sha256(
                    f"{task_id}|{feedback_turn_ref}".encode("utf-8")
                ).hexdigest()[:20]
                classification_task_state["pending_review_classification"] = {
                    "schema_version": 1,
                    "review_event_id": review_event_id,
                    "feedback_turn_ref": feedback_turn_ref,
                    "feedback_turn_id": feedback_handle,
                    "plan_snapshot_ref": str(
                        (classification_state.get("current_plan") or {}).get(
                            "plan_snapshot_ref"
                        )
                        or classification_state.get("plan_snapshot_ref")
                        or ""
                    ),
                    "approval_record_ref": str(
                        classification_state.get("approval_record_ref") or ""
                    ),
                    "status": "pending_consultant_classification",
                }
                classification_state["task_state"] = classification_task_state
                save_plan_state(self.data_path, task_id, classification_state)
                classification_state = load_plan_state(self.data_path, task_id)
                await self._observe_session_memory(
                    task_id,
                    "plan_review",
                    messages + [HumanMessage(content=f"Plan review input: {feedback}")],
                    {
                        "decision": "pending_typed_classification",
                        "feedback": feedback,
                        "plan_excerpt": plan[:2000],
                        "review_event_id": review_event_id,
                    },
                )
                return {
                    "messages": [HumanMessage(
                        content=f"Plan review input: {feedback}",
                        additional_kwargs={"message_origin": "user"},
                    )],
                    "current_plan": plan,
                    "plan_progress": render_plan_progress(classification_state),
                    "conversation_evidence": dict(
                        classification_state.get("conversation_evidence")
                        or {}
                    ),
                    "consultation_state": review_consultation,
                    "pending_human_question": {},
                    "validation_issues": deepcopy(list(
                        classification_state.get("validation_issues") or []
                    )),
                    "next_step": "consultant",
                }

        # ════════════════════════════════════════════
        # Node 2: Generate
        # ════════════════════════════════════════════
        generate_call_audit: Dict[str, bool] = {}

        async def _generate_impl(state: AgentState):
            output.print_node_header("generate")
            messages         = state["messages"]
            current_plan     = state.get("current_plan", "No plan.")
            task_id          = state.get("task_id", "unknown")

            generate_validation = self._validate_generate_context(state, task_id)
            if not generate_validation.get("valid"):
                return self._generate_plan_redirect(state, task_id, generate_validation)

            resume_plan_material = self._resume_plan_material(task_id, str(current_plan or ""))
            sanitized_current_plan = self._sanitize_completed_planner_plan(resume_plan_material)
            if sanitized_current_plan != resume_plan_material:
                current_plan = sanitized_current_plan
                self._replace_plan_tracker_with_plan(
                    task_id,
                    current_plan,
                    reason="generate replaced completed-task plan with FINISH-only plan",
                )

            plan_progress = self._start_or_load_plan_progress(
                task_id,
                current_plan,
                evidence="entered generate after compression check",
            )
            step_skill_update = (
                self._active_skill_update_for_current_plan_step(state, task_id)
                if str(state.get("task_mode") or "managed").lower() == "managed"
                else {}
            )
            if step_skill_update:
                state = dict(state)
                state.update(step_skill_update)
                activation_error = str(step_skill_update.get("skill_activation_error") or "").strip()
                if activation_error:
                    redirect = self._generate_plan_redirect(
                        state,
                        task_id,
                        {
                            "valid": False,
                            "reason_code": "invalid_step_skill_mapping",
                            "missing_fields": [
                                str(step_skill_update.get("skill_activation_error_field") or "current_step.skill_ids")
                            ],
                            "recoverable": True,
                            "validation_function": "_active_skill_update_for_current_plan_step",
                        },
                        message=activation_error,
                    )
                    redirect.update({
                        "active_skills": [],
                        "future_skills": [],
                        "skill_activation_error": activation_error,
                    })
                    return redirect
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "active_skills_derived_from_plan_step",
                    ", ".join(step_skill_update.get("active_skills", [])),
                )
            if self._current_plan_step_requests_finish(task_id):
                solution_text = self._finish_solution_from_plan(str(current_plan or ""))
                response = AIMessage(content=f"<solution>{solution_text}</solution>")
                output.print_ai(response.content)
                can_finish, plan_progress, final_status, gate_feedback = self._prepare_final_solution_progress(
                    task_id,
                    solution_text,
                    str(current_plan or ""),
                )
                if not can_finish:
                    gate_message = (
                        "Final solution validation failed.\n\n"
                        f"{gate_feedback}\n\n"
                        "Do not execute compatibility copies or symlinks to appease validation. "
                        "Repair the validation context or report the real blocker."
                    )
                    return {
                        "messages": [response, SystemMessage(content=gate_message)],
                        "plan_progress": plan_progress,
                        "next_step": "generate",
                    }
                await self._finalize_task_memory(
                    task_id,
                    final_status,
                    messages + [response],
                    {"solution": solution_text[:3000], "plan_progress": plan_progress},
                )
                return {"messages": [response], "plan_progress": plan_progress, "next_step": "finish"}
            # 熔断（连续 5 次 AI 消息含错误）
            recent_errors = sum(
                1 for m in messages[-8:]
                if isinstance(m, AIMessage) and
                any(k in str(m.content) for k in ["❌", "Failed", "Error"])
            )
            if recent_errors >= 5:
                plan_progress = self._record_plan_current_evidence(task_id, "system_aborted", "Too many recent errors.")
                return {
                    "messages": [AIMessage(content="<solution>❌ System Aborted: Too many errors.</solution>")],
                    "plan_progress": plan_progress,
                    "next_step": "finish",
                }

            # 技能加载
            loaded_skills = ""
            generate_operation_bindings: Dict[str, str] = {}
            if self.skill_manager and current_plan:
                selected = state.get("active_skills", []) or []
                if selected:
                    capability_view, generate_operation_bindings = (
                        self.skill_manager.get_semantic_execution_capabilities(selected)
                    )
                    if capability_view:
                        self.profiler.record_skill_usage(
                            task_id,
                            selected,
                            usage_type="semantic_capability_resolution_for_generate",
                            node="generate",
                            detail=(
                                "Controller resolved operation handles internally; Provider "
                                "guidance is projected later from the current capability only."
                            ),
                        )

            lightweight_policy = self._lightweight_task_policy(str(state.get("task_mode") or ""))
            if lightweight_policy:
                loaded_skills = (loaded_skills + "\n\n" + lightweight_policy).strip()

            # Build step-local memory. Broad retrieval stays in Consultant; Generate only retrieves on triggers.
            last_msg_content = str(messages[-1].content) if messages else ""
            step_plan_context = self._current_step_prompt_context(
                task_id,
                current_plan=str(current_plan or ""),
                plan_progress=plan_progress,
                state=state,
            )
            md_query = "\n".join(
                part for part in [last_msg_content[:600], step_plan_context[:1200]]
                if part
            )
            session_id = state.get("session_id") or task_id
            project_id = state.get("project_id") or self.default_project_id
            memory_packet_context = state.get("memory_packet_context", "") or ""
            # Generate V2 consumes only the current-step semantic closure.
            # Broad archive/wiki retrieval remains a Consultant responsibility.
            task_summary_context: Dict[str, Any] = {}
            archive_context = ""
            wiki_context = ""
            wiki_digest = ""

            # RecoveryPolicy, not the compatibility Supervisor verdict, owns
            # repair context and routing.
            supervisor_instr = ""
            recovery_instr = ""
            recovery_context_obj: Optional[RecoveryContext] = None
            recovery_action = state.get("pending_recovery_action") or {}
            recovery_decision = state.get("recovery_decision") or {}
            recovery_execution_envelope = (
                state.get("recovery_execution_envelope")
                or recovery_action.get("execution_envelope")
                or {}
            )
            recovery_generated = bool(recovery_action or recovery_decision)
            if recovery_action or recovery_decision:
                recovery_store = RecoveryStateStore(self.data_path, task_id)
                recovery_history = recovery_store.load_attempts()
                recovery_history.extend(recovery_store.load_execution_records())
                recovery_state = {
                    **dict(state),
                    "recovery_decision": recovery_decision,
                    "recovery_progress": (
                        state.get("recovery_progress")
                        or recovery_action.get("progress")
                        or {}
                    ),
                }
                renderer_protocol = self._renderer_action_protocol(recovery_state, task_id)
                persisted_recovery_context = (
                    dict(state.get("recovery_context") or {})
                    if isinstance(state.get("recovery_context"), Mapping)
                    else {}
                )
                if str(persisted_recovery_context.get("failure_stage") or "") == "pre_action_contract":
                    recovery_context_obj = RecoveryContext.from_mapping(
                        persisted_recovery_context
                    )
                else:
                    recovery_context_obj = build_recovery_context(
                        recovery_state,
                        dict(state.get("execution_evidence") or {}),
                        plan_state=load_plan_state(self.data_path, task_id),
                        task_root=Path(self.data_path) / "task_outputs" / task_id,
                        skill_policy={
                            "skill_ids": list(state.get("active_skills") or []),
                            "relevant_context": self._clip_observation_text(loaded_skills, 3000),
                        },
                        recovery_history=recovery_history,
                    )
                canonical_step = build_current_step_context(
                    recovery_state,
                    load_plan_state(self.data_path, task_id),
                    allowed_actions=renderer_protocol.get("allowed_actions") or None,
                ).to_dict()
                recovery_context_obj.current_step = canonical_step
                recovery_context_obj.allowed_actions = list(
                    canonical_step.get("allowed_actions") or []
                )
                recovery_context_obj.recovery_decision = dict(recovery_decision)
                recovery_store.save_diagnostic_context(recovery_context_obj)
                state = dict(state)
                state["recovery_context"] = recovery_context_obj.to_dict()
                state["recovery_context_digest"] = recovery_context_obj.context_id
                state["current_step_context"] = canonical_step
                # The V2 builder below selects failure facts and evidence
                # excerpts directly.  Do not invoke the legacy load-all then
                # tail-compact prompt projection.
                recovery_instr = ""
            conflict_summary = state.get("knowledge_conflict_summary") or {}
            if conflict_summary:
                conflict_payload = self._clip_observation_text(
                    json.dumps(
                        {
                            "summary": conflict_summary,
                            "conflicts": (state.get("knowledge_conflicts") or [])[-6:],
                            "plan_version": state.get("plan_version") or "plan_v1",
                            "stale_steps": state.get("plan_stale_steps") or [],
                            "revalidation_steps": state.get("plan_revalidation_steps") or [],
                        },
                        ensure_ascii=False,
                        default=str,
                    ),
                    4000,
                )
                supervisor_instr += (
                    "\n<knowledge_conflict_context>\n"
                    + conflict_payload
                    + "\nDo not silently edit a hard constraint or execute a stale step. "
                    "If a probe is required, emit one concrete targeted probe; if a plan revision is required, "
                    "request Planner rather than inventing a new workflow inside Generate.\n</knowledge_conflict_context>\n"
                )
            task_mode = str(state.get("task_mode") or "").strip().lower()
            context_budget_report: Dict[str, Any] = {
                "projection_mode": "node_context_v2_required_closure",
                "truncation_manifest": [],
                "component_token_counts": {},
            }
            generate_plan_state = load_plan_state(self.data_path, task_id)
            generate_task_spec = self._task_spec_for_state(dict(state), messages)
            generate_task_state = dict(generate_plan_state.get("task_state") or {})
            generate_skill_access = self._prepare_durable_skill_access(
                generate_plan_state,
                selected_skill_ids=(
                    generate_task_state.get("selected_skills")
                    or state.get("selected_skills")
                    or generate_plan_state.get("selected_skill_ids")
                    or []
                ),
                task_revision=task_spec_revision(generate_task_spec),
            )
            generate_continuation_id = str(
                generate_task_state.get("skill_continuation_id")
                or ""
            )
            try:
                generate_skill_projection = self._persist_durable_skill_access(
                    task_id,
                    generate_skill_access,
                    continuation_id=generate_continuation_id,
                    expected_state_generation=int(
                        generate_plan_state.get("state_generation") or 0
                    ),
                )
            except StateCASConflict as exc:
                stale_update = self._skill_access_cas_stale_update(
                    caller_node=(
                        "corrective_generate"
                        if recovery_context_obj is not None
                        else "generate"
                    ),
                    next_step="generate",
                    detail=str(exc),
                )
                stale_update.update({
                    "generate_result": "STALE_NODE_RESULT",
                    "generate_exit_reason": "skill_access_transaction_stale",
                })
                return stale_update
            generate_plan_state = load_plan_state(self.data_path, task_id)
            state = {**dict(state), **generate_skill_projection}
            _, generate_step = current_plan_step_with_index(generate_plan_state)
            generate_step = generate_step or {}
            current_step_id = str(generate_step.get("step_id") or "")
            active_skills = [
                str(item)
                for item in (
                    state.get("active_skills")
                    or generate_step.get("skill_ids")
                    or []
                )
                if str(item).strip()
            ]
            generate_protocol = self._renderer_action_protocol(state, task_id)
            generate_feedback: Dict[str, Any] = {
                "supervisor": {
                    key: deepcopy((state.get("last_supervisor_feedback") or {}).get(key))
                    for key in ("assessment", "concerns", "suggestions", "required_fix")
                    if (state.get("last_supervisor_feedback") or {}).get(key)
                    not in (None, "", [], {})
                },
                "recovery_action": {
                    key: deepcopy(recovery_action.get(key))
                    for key in ("type", "reason", "failure_owner", "violation")
                    if recovery_action.get(key) not in (None, "", [], {})
                },
                "recovery_decision": {
                    key: deepcopy(recovery_decision.get(key))
                    for key in (
                        "verdict", "root_cause", "action_type", "failure_owner",
                        "recommended_action", "missing_tools", "verification_checks",
                        "expected_new_evidence", "forbidden_next_actions",
                        "repair_target", "repair_instruction",
                        "machine_findings_considered",
                    )
                    if recovery_decision.get(key) not in (None, "", [], {})
                },
                "recovery_execution_envelope": {
                    key: deepcopy(recovery_execution_envelope.get(key))
                    for key in (
                        "recovery_decision_id", "recovery_context_id", "step_id",
                        "action_id", "recovery_strategy", "execution_purpose",
                        "execution_mode", "result_contract", "probe_id",
                        "scratch_capability", "policy_version", "immutable_hash",
                    )
                    if recovery_execution_envelope.get(key) not in (None, "", [], {})
                },
            }
            action_repair_projection = self._action_repair_projection(
                state,
                recovery_action,
                recovery_decision,
            )
            if action_repair_projection:
                generate_feedback["action_repair"] = action_repair_projection
            generate_approval = validate_plan_for_generate(
                generate_plan_state,
                task_spec_revision(generate_task_spec),
            )
            generate_approved_snapshot: Dict[str, Any] = {}
            generate_runtime_resolution: Dict[str, Any] = {}
            generate_runtime_audit_view: Dict[str, Any] = {}
            generate_selected_skill_id = ""
            generate_artifact_environment: List[Dict[str, Any]] = []
            generate_action_provider_context: Dict[str, Any] = {}
            generate_script_protocol = False
            recovery_evidence: List[Dict[str, Any]] = []
            if recovery_context_obj and recovery_context_obj.bounded_log_excerpt:
                recovery_evidence.append({
                    "evidence_id": recovery_context_obj.context_id or "recovery-log",
                    "kind": "execution_log",
                    "excerpt": recovery_context_obj.bounded_log_excerpt,
                    "truncated": True,
                })
            try:
                generate_approved_snapshot = load_approved_plan_snapshot(
                    self.data_path,
                    task_id,
                    state=generate_plan_state,
                )
                execution_capability_id = str(
                    generate_step.get("execution_capability_id") or ""
                ).strip()
                capability_registry = (
                    self.skill_manager.get_execution_capability_registry(active_skills)
                    if self.skill_manager
                    else {}
                )
                selected_contract = capability_registry.get(execution_capability_id) or {}
                generate_selected_skill_id = str(
                    selected_contract.get("selected_skill_id") or ""
                )
                generate_runtime_resolution = resolve_action_runtime_bindings(
                    selected_skill_id=generate_selected_skill_id,
                    execution_capability_id=execution_capability_id,
                    approved_capability_contract_hash=str(
                        generate_step.get("capability_contract_hash") or ""
                    ),
                    capability_registry=capability_registry,
                    ready_runtime_binding_registry=build_runtime_binding_registry(state),
                    current_action_identity={
                        "plan_id": str(generate_plan_state.get("plan_id") or ""),
                        "step_id": current_step_id,
                    },
                )
                generate_runtime_audit_view = {
                    "status": "passed",
                    "bindings": dict(
                        generate_runtime_resolution.get(
                            "effective_runtime_bindings"
                        ) or {}
                    ),
                    "runtime_snapshot_digest": str(
                        generate_runtime_resolution.get(
                            "runtime_binding_manifest_hash"
                        ) or ""
                    ),
                }
                generate_visible_artifacts = build_approved_visible_artifact_set(
                    generate_task_spec,
                    plan_state=generate_plan_state,
                    approved_plan_snapshot=generate_approved_snapshot,
                    current_step_id=current_step_id,
                )
                generate_managed_bindings = build_managed_artifact_bindings(
                    generate_task_spec,
                    plan_state=generate_plan_state,
                    approved_plan_snapshot=generate_approved_snapshot,
                    current_step_id=current_step_id,
                    visible_artifacts=generate_visible_artifacts,
                )
                generate_artifact_environment = script_artifact_environment(
                    generate_managed_bindings
                )
                generate_step_action = str(
                    generate_step.get("action") or "execute"
                ).strip().lower()
                generate_script_protocol = generate_step_action not in {
                    "ask_user", "install", "install_tool", "search", "finish",
                    "solution", "blocked", "plan_patch",
                }
                if generate_script_protocol:
                    generate_action_provider_context = (
                        project_action_capability_context_for_provider(
                            generate_runtime_resolution,
                            generate_artifact_environment,
                        )
                    )
                    loaded_skills = json.dumps(
                        {
                            **generate_action_provider_context,
                            "script_protocol": (
                                "Use only current-action runtime and artifact shell references. "
                                "Capability and binding scope are Controller-owned."
                            ),
                        },
                        ensure_ascii=False,
                        sort_keys=True,
                    )
                    if lightweight_policy:
                        loaded_skills = (
                            loaded_skills + "\n\n" + lightweight_policy
                        ).strip()
                generate_semantic_inputs = self._node_context_semantic_inputs(
                    task_id,
                    generate_plan_state,
                    messages=messages,
                )
                generate_node_context = build_node_context(
                    node_type="generate",
                    task_spec=generate_task_spec,
                    plan_state=generate_plan_state,
                    state_generation=int(generate_plan_state.get("state_generation") or 0),
                    authoritative_user_turn_revision=(
                        self._authoritative_user_turn_revision(generate_plan_state)
                    ),
                    current_step_id=current_step_id,
                    runtime={
                        "progress": {
                            "current_step_status": str(generate_step.get("status") or "pending"),
                            "remaining_step_count": sum(
                                1
                                for step in generate_plan_state.get("steps", []) or []
                                if isinstance(step, Mapping)
                                and str(step.get("status") or "").lower()
                                not in {"done", "completed", "skipped"}
                            ),
                        },
                        "current_action_contract": self._current_action_semantic_contract(
                            state, task_id
                        ),
                        **generate_action_provider_context,
                        "generate_output_contract": (
                            "script_block_v1"
                            if generate_script_protocol
                            else "semantic_action_v2"
                        ),
                    },
                    feedback=generate_feedback,
                    evidence=recovery_evidence,
                    skill_context=self._skill_context_projection(
                        generate_plan_state,
                        caller_node=(
                            "corrective_generate"
                            if recovery_context_obj is not None
                            else "generate"
                        ),
                        current_step_id=current_step_id,
                        continuation_id=generate_continuation_id,
                    ),
                    continuation_id=generate_continuation_id,
                    allowed_operations=list(generate_protocol.get("allowed_actions") or []),
                    approval_ref=str(
                        generate_plan_state.get("approval_snapshot_ref")
                        or (generate_plan_state.get("approval_snapshot") or {}).get("approval_id")
                        or (generate_plan_state.get("approval_record") or {}).get("approval_id")
                        or ""
                    ),
                    approval_applicability=(
                        "applicable" if generate_approval.get("valid") else str(generate_approval.get("reason") or "unverifiable")
                    ),
                    execution_epoch=(
                        generate_step.get("execution_epoch")
                        or (generate_plan_state.get("runtime_state") or {}).get("execution_epoch")
                        or state.get("execution_epoch")
                        or 0
                    ),
                    attempt_id=str(
                        state.get("attempt_id")
                        or (state.get("execution_evidence") or {}).get("attempt_id")
                        or ""
                    ),
                    failure_fingerprint=str(
                        (recovery_context_obj.error_fingerprint if recovery_context_obj else "")
                    ),
                    trace_enabled=bool(os.getenv("NODE_CONTEXT_V2_TRACE", "")),
                    max_payload_chars=max(
                        1,
                        int(getattr(self, "llm_context_limit_tokens", 200_000)) * 4,
                    ),
                    approved_plan_snapshot=generate_approved_snapshot,
                    **generate_semantic_inputs,
                )
                call_msgs = [HumanMessage(content=PromptManager.get_generate_v2_prompt(
                    generate_node_context.llm_payload.to_provider_dict(),
                    capability_instructions=loaded_skills,
                ))]
            except Exception as exc:
                compact_exc = self._clip_observation_text(
                    f"{type(exc).__name__}: {exc}",
                    1200,
                )
                reason = f"PROMPT_ASSEMBLY_FAILURE: {compact_exc}"
                logger.exception("Generate V2 LLMPayload assembly failed: task=%s", task_id)
                await self._finalize_task_memory(
                    task_id,
                    "failed",
                    messages,
                    {"reason": reason, "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value},
                )
                return {
                    "messages": [SystemMessage(content=reason)],
                    "pending_action": {},
                    "pending_recovery_action": {
                        "type": "internal_protocol_error",
                        "reason": reason,
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    },
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                    "generate_result": "BLOCKED",
                    "generate_exit_reason": "prompt_assembly_failure",
                    "task_status": TASK_STATUS_FAILED,
                    "next_step": "finish",
                }
            generate_response_cached = False
            try:
                recovery_store = RecoveryStateStore(self.data_path, task_id)
                recovery_stage = str(
                    recovery_decision.get("recommended_action")
                    or recovery_action.get("type")
                    or ""
                ).strip().upper()
                recovery_cache_identity = {
                    "approved_plan_snapshot_id": str(
                        generate_approved_snapshot.get("plan_snapshot_id") or ""
                    ),
                    "approved_plan_snapshot_ref": str(
                        (generate_plan_state.get("current_plan") or {}).get("plan_snapshot_ref")
                        or generate_plan_state.get("plan_snapshot_ref")
                        or ""
                    ),
                    "task_semantic_hash": str(
                        generate_node_context.binding.task_semantic_hash or ""
                    ),
                    "task_revision": int(
                        generate_node_context.binding.task_revision or 0
                    ),
                    "plan_semantic_hash": str(
                        generate_node_context.binding.plan_semantic_hash or ""
                    ),
                    "plan_revision": int(
                        generate_node_context.binding.plan_revision or 0
                    ),
                    "authoritative_user_turn_revision": int(
                        generate_node_context.binding.authoritative_user_turn_revision
                        or 0
                    ),
                    "step_id": str(current_step_id or ""),
                    "approval_ref": str(
                        generate_node_context.binding.approval_ref or ""
                    ),
                    "approval_applicability": str(
                        generate_node_context.binding.approval_applicability
                        or ""
                    ),
                    "execution_epoch": str(
                        generate_node_context.binding.execution_epoch or ""
                    ),
                    "continuation_id": str(
                        generate_node_context.binding.continuation_id or ""
                    ),
                    "failure_stage": str(
                        recovery_context_obj.failure_stage
                        if recovery_context_obj
                        else ""
                    ),
                    "error_fingerprint": str(
                        recovery_context_obj.error_fingerprint
                        if recovery_context_obj
                        else ""
                    ),
                    "candidate_fingerprint": str(
                        recovery_context_obj.candidate_fingerprint
                        if recovery_context_obj
                        else ""
                    ),
                    "repair_ordinal": int(
                        recovery_context_obj.repair_ordinal
                        if recovery_context_obj
                        else 0
                    ),
                }
                cache_budgets = dict(
                    (generate_plan_state.get("task_state") or {}).get("budgets")
                    or {}
                )
                invalid_candidate_fingerprints = list(
                    dict(
                        (cache_budgets.get("invalid_action_hashes_by_step") or {}).get(
                            str(current_step_id or "lightweight")
                        )
                        or {}
                    ).keys()
                )
                cached_generate = (
                    recovery_store.load_llm_result(
                        recovery_context_obj.context_id,
                        f"generate:{recovery_stage or 'RECOVERY'}",
                        cache_identity=recovery_cache_identity,
                        invalid_candidate_fingerprints=invalid_candidate_fingerprints,
                    )
                    if recovery_context_obj
                    else {}
                )
                if cached_generate.get("raw_response"):
                    generate_response_cached = True
                    response = AIMessage(content=str(cached_generate["raw_response"]))
                    logger.info(
                        "RECOVERY_CACHE_HIT task=%s context_id=%s stage=%s step_id=%s "
                        "snapshot_id=%s candidate_fingerprint=%s error_fingerprint=%s repair_ordinal=%s",
                        task_id,
                        recovery_context_obj.context_id,
                        recovery_stage or "RECOVERY",
                        current_step_id,
                        recovery_cache_identity["approved_plan_snapshot_id"],
                        str(cached_generate.get("candidate_fingerprint") or ""),
                        recovery_cache_identity["error_fingerprint"],
                        recovery_cache_identity["repair_ordinal"],
                    )
                else:
                    if recovery_context_obj:
                        logger.info(
                            "RECOVERY_CACHE_REJECTED_AS_STALE_OR_INVALID task=%s context_id=%s "
                            "stage=%s step_id=%s snapshot_id=%s candidate_fingerprint=%s "
                            "error_fingerprint=%s repair_ordinal=%s",
                            task_id,
                            recovery_context_obj.context_id,
                            recovery_stage or "RECOVERY",
                            current_step_id,
                            recovery_cache_identity["approved_plan_snapshot_id"],
                            recovery_cache_identity["candidate_fingerprint"],
                            recovery_cache_identity["error_fingerprint"],
                            recovery_cache_identity["repair_ordinal"],
                        )
                    generate_call_audit[str(task_id)] = True
                    response = await self._ainvoke_node_llm(
                        call_msgs,
                        node_context=generate_node_context,
                        stage="generate",
                        task_id=task_id,
                        task_mode=task_mode,
                        trace_metadata={
                            "call_kind": "generate",
                            "task_spec_revision": self._task_revision_for_state(dict(state)),
                            "effective_facts_revision": str(state.get("effective_user_facts_revision") or ""),
                            "step_id": str(current_step_id or ""),
                            "selected_skill_ids": active_skills,
                            "component_token_counts": dict(
                                (context_budget_report or {}).get("component_token_counts") or {}
                            ),
                            "truncation_manifest": list(
                                (context_budget_report or {}).get("truncation_manifest") or []
                            ),
                            "action_contract_ref": str(
                                Path(self.data_path) / "task_outputs" / task_id / "plan_state.json"
                            ),
                            "provider_context_manifest": provider_context_manifest(
                                generate_node_context.llm_payload
                            ),
                            "generate_llm_policy": dict(self.generate_llm_policy),
                        },
                        llm_override=self.generate_llm,
                        llm_policy=self.generate_llm_policy,
                    )
                    if recovery_context_obj:
                        try:
                            cache_skill_decision = parse_typed_skill_decision(
                                str(response.content or "")
                            )
                        except SkillAccessError:
                            cache_skill_decision = {"decision": "INVALID_SKILL_DECISION"}
                        if cache_skill_decision is None:
                            if generate_script_protocol:
                                try:
                                    cached_structured_action = adapt_script_block_to_action(
                                        parse_executable_script_block(str(response.content or "")),
                                        generate_artifact_environment,
                                        execution_envelope=(
                                            recovery_execution_envelope or None
                                        ),
                                        recovery_generated=recovery_generated,
                                        payload_revision=int(
                                            recovery_action.get("payload_revision") or 0
                                        ),
                                    )
                                except (ScriptBlockError, RecoveryExecutionContractError):
                                    cached_structured_action = {}
                            else:
                                cached_structured_action = self._extract_structured_action(
                                    str(response.content or "")
                                )
                            recovery_store.save_llm_result(
                                recovery_context_obj.context_id,
                                f"generate:{recovery_stage or 'RECOVERY'}",
                                raw_response=str(response.content or ""),
                                parsed_result={
                                    "action_type": str(
                                        cached_structured_action.get("type") or ""
                                    )
                                },
                                cache_identity=recovery_cache_identity,
                                candidate_fingerprint=(
                                    managed_action_fingerprint(cached_structured_action)
                                    if cached_structured_action
                                    else ""
                                ),
                            )
            except Exception as exc:
                if isinstance(exc, ProviderAttemptFailure):
                    response = self._generate_provider_failure_response(exc, task_id)
                    plan_progress = self._mark_generate_provider_blocked(task_id, exc)
                    failure_reason = (
                        f"{exc.error_code}: Generate provider attempt lifecycle terminated"
                    )
                else:
                    response = self._llm_failure_response("generate", exc, task_id)
                    failure_reason = llm_failure_summary(exc, "generate", task_id)
                    plan_progress = self._mark_plan_current_blocked(
                        task_id,
                        failure_reason,
                    )
                content = response.content
                output.print_ai(content)
                await self._finalize_task_memory(
                    task_id,
                    "failed",
                    messages + [response],
                    {
                        "reason": failure_reason,
                        "plan_progress": plan_progress,
                        "failure_owner": (
                            "PROVIDER"
                            if isinstance(exc, ProviderAttemptFailure)
                            else ""
                        ),
                        "failure_stage": (
                            "GENERATE_PROVIDER"
                            if isinstance(exc, ProviderAttemptFailure)
                            else ""
                        ),
                    },
                )
                return {
                    "messages": [response],
                    "plan_progress": plan_progress,
                    "failure_owner": (
                        "PROVIDER" if isinstance(exc, ProviderAttemptFailure) else ""
                    ),
                    "required_next_action": (
                        "STOP_PROVIDER_FAILURE"
                        if isinstance(exc, ProviderAttemptFailure)
                        else ""
                    ),
                    "generate_result": "BLOCKED",
                    "generate_exit_reason": (
                        "provider_attempt_terminal"
                        if isinstance(exc, ProviderAttemptFailure)
                        else "llm_failure"
                    ),
                    "task_status": TASK_STATUS_BLOCKED,
                    "next_step": "finish",
                }
            # Cached and newly generated responses cross the same current
            # authority gate before parsing or action binding.
            if response is not None:
                current_generate_plan = load_plan_state(self.data_path, task_id)
                _, current_generate_step = current_plan_step_with_index(current_generate_plan)
                current_generate_step = current_generate_step or {}
                current_generate_task = canonical_task_spec_for_state(
                    current_generate_plan
                )
                current_generate_snapshot = load_approved_plan_snapshot(
                    self.data_path,
                    task_id,
                    state=current_generate_plan,
                )
                current_generate_context = build_node_context(
                    node_type="generate",
                    task_spec=current_generate_task,
                    plan_state=current_generate_plan,
                    authoritative_user_turn_revision=(
                        self._authoritative_user_turn_revision(current_generate_plan)
                    ),
                    current_step_id=str(current_generate_step.get("step_id") or ""),
                    approval_ref=str(
                        current_generate_plan.get("approval_snapshot_ref")
                        or (current_generate_plan.get("approval_snapshot") or {}).get("approval_id")
                        or (current_generate_plan.get("approval_record") or {}).get("approval_id")
                        or ""
                    ),
                    approval_applicability=(
                        "applicable"
                        if validate_plan_for_generate(
                            current_generate_plan,
                            task_spec_revision(current_generate_task),
                        ).get("valid")
                        else "unverifiable"
                    ),
                    execution_epoch=(
                        current_generate_step.get("execution_epoch")
                        or (current_generate_plan.get("runtime_state") or {}).get("execution_epoch")
                        or state.get("execution_epoch")
                        or 0
                    ),
                    approved_plan_snapshot=current_generate_snapshot,
                    continuation_id=str(
                        (current_generate_plan.get("task_state") or {}).get(
                            "skill_continuation_id"
                        ) or ""
                    ),
                )
                generate_staleness = evaluate_node_staleness(
                    generate_node_context.binding,
                    current_generate_context.binding.to_dict(),
                )
                if not generate_staleness.usable:
                    self._node_invocations.mark_stale_signature_handled(
                        generate_staleness.stale_signature
                    )
                    self._record_durable_skill_event(
                        task_id,
                        "stale_node_result_discarded",
                        {
                            "caller_node": "generate",
                            "caller_invocation_id": generate_node_context.binding.invocation_id,
                            "changed_preconditions": list(
                                generate_staleness.changed_preconditions
                            ),
                        },
                    )
                    return {
                        "messages": [SystemMessage(content=json.dumps({
                            "decision_result": "STALE_NODE_RESULT",
                            "caller_node": "generate",
                            "caller_invocation_id": generate_node_context.binding.invocation_id,
                            "changed_preconditions": list(
                                generate_staleness.changed_preconditions
                            ),
                            "counts_as_failure": False,
                            "consumes_execution_retry": False,
                            "execute": False,
                        }, ensure_ascii=False, sort_keys=True))],
                        "stale_node_result": {
                            "decision_result": "STALE_NODE_RESULT",
                            "caller_node": "generate",
                            "caller_invocation_id": generate_node_context.binding.invocation_id,
                            "changed_preconditions": list(
                                generate_staleness.changed_preconditions
                            ),
                        },
                        "next_step": "generate",
                        "generate_result": "STALE_NODE_RESULT",
                        "generate_exit_reason": "node_result_stale_discarded",
                    }
            content   = response.content

            try:
                typed_generate_skill_decision = parse_typed_skill_decision(
                    str(content or "")
                )
            except SkillAccessError as exc:
                return {
                    "messages": [response, SystemMessage(content=json.dumps(
                        exc.to_dict(), ensure_ascii=False, sort_keys=True,
                    ))],
                    "pending_action": {},
                    "skill_decision_result": exc.to_dict(),
                    "next_step": "generate",
                    "generate_result": "SKILL_CONTINUATION",
                    "generate_exit_reason": "skill_decision_rejected",
                }
            if typed_generate_skill_decision is not None:
                try:
                    return await self._handle_skill_node_decision(
                        task_id=task_id,
                        caller_node=(
                            "corrective_generate"
                            if recovery_context_obj is not None
                            else "generate"
                        ),
                        graph_node="generate",
                        decision=typed_generate_skill_decision,
                        node_context=generate_node_context,
                        response=response,
                        selected_skill_ids=(
                            (generate_plan_state.get("task_state") or {}).get(
                                "selected_skills"
                            )
                            or state.get("selected_skills")
                            or []
                        ),
                    )
                except SkillAccessError as exc:
                    return {
                        "messages": [response, SystemMessage(content=json.dumps(
                            exc.to_dict(), ensure_ascii=False, sort_keys=True,
                        ))],
                        "pending_action": {},
                        "skill_decision_result": exc.to_dict(),
                        "next_step": "generate",
                        "generate_result": "SKILL_CONTINUATION",
                        "generate_exit_reason": "skill_decision_rejected",
                    }
            self._complete_durable_skill_continuation(
                task_id,
                caller_node=(
                    "corrective_generate"
                    if recovery_context_obj is not None
                    else "generate"
                ),
            )

            # 打印（去重）
            output.print_ai(content)

            # 解析
            search_match  = re.search(r"<search>(.*?)</search>", content, re.DOTALL)
            install_match = re.search(r"<install_tool.*?>.*?</install_tool>", content, re.DOTALL)
            execute_match = re.search(r"<execute>(.*?)</execute>", content, re.DOTALL)
            ask_user_match = re.search(r"<ask_user>(.*?)</ask_user>", content, re.DOTALL)
            answer_match  = re.search(r"<solution>(.*?)</solution>", content, re.DOTALL)
            activate_match = re.search(r"<activate_batch\s+batch_id=[\"']?([^\"'\s>/]+)[\"']?\s*/?>", content, re.DOTALL)
            structured_parse_result = self._extract_structured_action_result(content)
            structured_action = structured_parse_result.action
            action_parse_error = deepcopy(structured_parse_result.error)
            if generate_script_protocol:
                try:
                    script_block = parse_executable_script_block(content)
                    structured_action = adapt_script_block_to_action(
                        script_block,
                        generate_artifact_environment,
                        execution_envelope=(
                            recovery_execution_envelope or None
                        ),
                        recovery_generated=recovery_generated,
                        payload_revision=int(
                            recovery_action.get("payload_revision") or 0
                        ),
                    )
                    # Carry only the current capability resolution. The full
                    # task runtime snapshot is neither provider-visible nor an
                    # action authorization fallback.
                    structured_action.update({
                        "selected_skill_id": generate_selected_skill_id,
                        "execution_capability_id": str(
                            generate_step.get("execution_capability_id") or ""
                        ),
                        "capability_contract": deepcopy(
                            generate_runtime_resolution.get("capability_contract") or {}
                        ),
                        "capability_contract_hash": str(
                            generate_runtime_resolution.get("capability_contract_hash") or ""
                        ),
                        "runtime_bindings": dict(
                            generate_runtime_resolution.get("effective_runtime_bindings") or {}
                        ),
                        "runtime_binding_records": deepcopy(
                            generate_runtime_resolution.get("runtime_binding_records") or []
                        ),
                        "runtime_binding_manifest": deepcopy(
                            generate_runtime_resolution.get("runtime_binding_manifest") or {}
                        ),
                        "runtime_binding_manifest_hash": str(
                            generate_runtime_resolution.get("runtime_binding_manifest_hash") or ""
                        ),
                    })
                    structured_action["controller_artifact_environment"] = deepcopy(
                        generate_artifact_environment
                    )
                    action_parse_error = {}
                    script_findings = audit_generated_script(
                        script_block,
                        runtime_snapshot=generate_runtime_audit_view,
                        artifact_environment=generate_artifact_environment,
                        evidence_refs=[
                            str(
                                Path(self.data_path)
                                / "task_outputs"
                                / task_id
                                / "plan_state.json"
                            )
                        ],
                    )
                    source_audit_findings = [
                        dict(item) for item in script_findings
                        if not bool(item.get("authoritative", True))
                    ]
                    if source_audit_findings:
                        structured_action["controller_source_diagnostics"] = source_audit_findings
                    if any(
                        str(item.get("severity") or "").upper() == "HIGH"
                        and bool(item.get("authoritative", True))
                        for item in script_findings
                    ):
                        candidate_hash = hashlib.sha256(
                            script_block.body.encode("utf-8", errors="replace")
                        ).hexdigest()
                        candidate_ref = self._persist_script_version(
                            task_id,
                            load_plan_state(self.data_path, task_id),
                            current_step_id,
                            f"candidate_{candidate_hash[:16]}",
                            "generated_candidate",
                            script_block.body,
                            extension={"python": ".py", "r": ".R"}.get(
                                script_block.language, ".sh"
                            ),
                            mutation_reason="controller_pre_execution_audit",
                            producer="generate",
                        )
                        audit_error = {
                            "stage": "controller_script_audit",
                            "code": "CONTROLLER_SCRIPT_AUDIT_FAILED",
                            "findings": script_findings,
                        }
                        format_count, duplicate_count, invalid_hash, format_decision = (
                            self._record_action_format_failure(
                                task_id,
                                current_step_id or "lightweight",
                                script_block.body,
                                audit_error,
                            )
                        )
                        repeated_audit_repair = str(
                            (state.get("pending_recovery_action") or {}).get("type") or ""
                        ).lower() == "controller_audit_repair"
                        if repeated_audit_repair or duplicate_count > 1:
                            return {
                                "messages": [response, SystemMessage(content=(
                                    "Controller re-audit rejected the corrective script with the same "
                                    "authoritative machine findings; no unmodified execution is allowed."
                                ))],
                                "pending_action": {},
                                "pending_recovery_action": {
                                    "type": "internal_protocol_error",
                                    "reason": "controller_script_audit_non_convergent",
                                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                                    "machine_audit_findings": script_findings,
                                },
                                "recovery_decision": format_decision.to_dict(),
                                "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                                "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                                "generate_result": "BLOCKED",
                                "generate_exit_reason": "controller_script_audit_non_convergent",
                                "next_step": "finish",
                            }
                        return {
                            "messages": [response, SystemMessage(content=(
                                "<controller_machine_audit>\n"
                                "These findings are authoritative machine observations, not a root-cause diagnosis.\n"
                                + json.dumps(script_findings, ensure_ascii=False, indent=2)
                                + "\nRepair only these findings and preserve unrelated valid script logic.\n"
                                "</controller_machine_audit>"
                            ))],
                            "pending_action": {},
                            "pending_recovery_action": {
                                "type": "controller_audit_repair",
                                "reason": "pre_execution_machine_audit_failed",
                                "failure_owner": RecoveryFailureOwner.GENERATED_ACTION.value,
                                "previous_script": script_block.body,
                                "previous_script_ref": candidate_ref,
                                "machine_audit_findings": script_findings,
                                "repair_target": "previous_generated_script",
                                "repair_instruction": (
                                    "Fix the deterministic machine findings only; preserve unrelated valid logic."
                                ),
                                "invalid_response_hash": invalid_hash,
                                "repair_ordinal": format_count,
                            },
                            "controller_machine_audit_findings": script_findings,
                            "required_next_action": "CORRECTIVE_GENERATE",
                            "recovery_decision": format_decision.to_dict(),
                            "failure_owner": RecoveryFailureOwner.GENERATED_ACTION.value,
                            "generate_result": "NEEDS_RECOVERY",
                            "generate_exit_reason": "controller_script_audit_failed",
                            "next_step": "generate",
                        }
                except RecoveryExecutionContractError as exc:
                    return {
                        "messages": [response, SystemMessage(content=json.dumps({
                            "code": exc.code,
                            "message": exc.message,
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "execution_started": False,
                        }, ensure_ascii=False, sort_keys=True))],
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "internal_protocol_error",
                            "reason": exc.code,
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "execution_started": False,
                        },
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                        "generate_result": "NEEDS_RECOVERY",
                        "generate_exit_reason": "recovery_execution_contract_invalid",
                        "next_step": "supervisor",
                    }
                except ScriptBlockError as exc:
                    structured_action = {}
                    action_parse_error = {
                        "stage": "script_block",
                        "code": ScriptBlockError.code,
                        "message": str(exc),
                    }
            candidate_fingerprint = (
                managed_action_fingerprint(structured_action)
                if structured_action
                else ""
            )
            renderer_contract_error: Dict[str, Any] = {}
            if (
                str(structured_action.get("type") or "") == "execute"
                and isinstance(structured_action.get("argv"), list)
                and structured_action.get("argv")
            ):
                task_spec_for_action = self._task_spec_for_state(dict(state), messages)
                current_action_plan = load_plan_state(self.data_path, task_id)
                _, current_action_step = current_plan_step_with_index(current_action_plan)
                current_action_step_id = str(
                    (current_action_step or {}).get("step_id") or current_step_id or "task"
                )
                approved_action_snapshot = load_approved_plan_snapshot(
                    self.data_path,
                    task_id,
                    state=current_action_plan,
                )
                visible_artifacts = build_approved_visible_artifact_set(
                    task_spec_for_action,
                    plan_state=current_action_plan,
                    approved_plan_snapshot=approved_action_snapshot,
                    current_step_id=current_action_step_id,
                )
                managed_bindings = build_managed_artifact_bindings(
                    task_spec_for_action,
                    plan_state=current_action_plan,
                    approved_plan_snapshot=approved_action_snapshot,
                    current_step_id=current_action_step_id,
                    visible_artifacts=visible_artifacts,
                )
                materialized_action, artifact_violations = materialize_managed_action(
                    structured_action,
                    managed_bindings,
                    allow_legacy_exact_literals=False,
                    operation_bindings=generate_operation_bindings,
                    approved_visible_artifacts=visible_artifacts,
                )
                controller_runtime_keys = {
                    *dict(
                        generate_runtime_resolution.get(
                            "effective_runtime_bindings"
                        ) or {}
                    ).keys(),
                    "BIOMIND_TASK_ID",
                    "BIOMIND_ACTION_ID",
                    "BIOMIND_STEP_ID",
                }
                conflicting_env_keys = sorted(
                    set((materialized_action.get("env") or {}).keys())
                    & controller_runtime_keys
                )
                if conflicting_env_keys:
                    artifact_violations.append(ArtifactViolation(
                        code="MANAGED_ACTION_ENV_KEY_CONFLICT",
                        owner="GENERATED_ACTION",
                        route="generate",
                        message=(
                            "Structured action env conflicts with a Controller runtime binding. "
                            "Remove the action-owned definition and use the Controller-provided variable."
                        ),
                        field_path="env",
                        proposed=",".join(conflicting_env_keys),
                        failure_stage="pre_action_contract",
                    ))
                artifact_violations.extend(
                    validate_materialized_artifacts(materialized_action, managed_bindings)
                )
                action_result_contract = str(
                    materialized_action.get("result_contract") or ""
                ).upper()
                if (
                    action_result_contract
                    == RecoveryResultContract.DIAGNOSTIC_EVIDENCE.value
                ):
                    diagnostic_allowed, diagnostic_error = (
                        validate_diagnostic_action(materialized_action)
                    )
                    if not diagnostic_allowed:
                        artifact_violations.append(ArtifactViolation(
                            code="DIAGNOSTIC_ACTION_POLICY_VIOLATION",
                            owner="GENERATED_ACTION",
                            route="generate",
                            message=diagnostic_error,
                            field_path="code",
                            failure_stage="pre_action_contract",
                        ))
                elif (
                    action_result_contract
                    != RecoveryResultContract.EXECUTION_BUNDLE.value
                ):
                    artifact_violations.extend(
                        validate_generate_output_coverage(
                            current_action_plan,
                            materialized_action,
                            managed_bindings,
                        )
                    )
                if artifact_violations:
                    violation_payload = [item.to_dict() for item in artifact_violations]
                    if (
                        action_result_contract
                        == RecoveryResultContract.DIAGNOSTIC_EVIDENCE.value
                    ):
                        diagnostic_envelope = RecoveryExecutionEnvelope.from_mapping(
                            materialized_action.get(
                                "recovery_execution_envelope"
                            )
                        )
                        validation_fingerprint = hashlib.sha256(
                            json.dumps(
                                violation_payload,
                                ensure_ascii=False,
                                sort_keys=True,
                                separators=(",", ":"),
                            ).encode("utf-8", errors="replace")
                        ).hexdigest()[:24]
                        diagnostic_store = RecoveryStateStore(
                            self.data_path, task_id
                        )
                        diagnostic_store.save_probe_lifecycle(
                            ProbeLifecycleRecord(
                                recovery_decision_id=(
                                    diagnostic_envelope.recovery_decision_id
                                ),
                                probe_id=str(
                                    diagnostic_envelope.probe_id or ""
                                ),
                                probe_objective=str(
                                    recovery_decision.get("probe_objective")
                                    or recovery_decision.get("probe_reason")
                                    or recovery_decision.get("repair_strategy")
                                    or ""
                                ),
                                status=(
                                    ProbeLifecycleStatus.NOT_EXECUTED.value
                                ),
                                action_id=diagnostic_envelope.action_id,
                                validation_fingerprint=validation_fingerprint,
                            )
                        )
                        diagnostic_store.append_trace(
                            "DIAGNOSTIC_ACTION_NOT_EXECUTED",
                            {
                                "probe_id": diagnostic_envelope.probe_id,
                                "action_id": diagnostic_envelope.action_id,
                                "validation_fingerprint": validation_fingerprint,
                                "violations": violation_payload,
                            },
                        )
                    first_violation = violation_payload[0]
                    raw_first_owner = str(
                        first_violation.get("owner") or "GENERATED_ACTION"
                    ).upper()
                    first_owner = (
                        RecoveryFailureOwner.INTERNAL_PROTOCOL.value
                        if raw_first_owner in {
                            "CONTROLLER_PROJECTION",
                            RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        }
                        else raw_first_owner
                    )
                    if first_owner == RecoveryFailureOwner.INTERNAL_PROTOCOL.value:
                        # Rebuilding from the same snapshot, bindings, action,
                        # and validator cannot change the result.  A visible
                        # exact handle with no binding is a Controller defect,
                        # so persist it and fail closed without a no-op retry.
                        conflict = {
                            **first_violation,
                            "owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "subowner": "controller_projection",
                            "route": "terminal",
                            "failure_stage": "pre_action_contract",
                            "candidate_fingerprint": candidate_fingerprint,
                        }
                        error_fingerprint = hashlib.sha256(json.dumps(
                            conflict,
                            ensure_ascii=False,
                            sort_keys=True,
                            separators=(",", ":"),
                            default=str,
                        ).encode("utf-8", errors="replace")).hexdigest()
                        durable_failure = record_preaction_contract_failure(
                            current_action_plan,
                            conflict,
                            error_fingerprint=error_fingerprint,
                            candidate_fingerprint=candidate_fingerprint,
                            repair_attempt_count=0,
                            termination_reason="internal_protocol_not_repairable",
                        )
                        save_plan_state(self.data_path, task_id, current_action_plan)
                        return {
                            "messages": [response, SystemMessage(content=(
                                "<managed_artifact_internal_conflict>\n"
                                + json.dumps(conflict, ensure_ascii=False, sort_keys=True)
                                + "\n</managed_artifact_internal_conflict>"
                            ))],
                            "pending_action": {},
                            "pending_recovery_action": {
                                "type": "blocked",
                                "reason": str(conflict.get("message") or "Internal artifact binding conflict."),
                                "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                                "violation": conflict,
                            },
                            "failure": durable_failure,
                            "primary_failure": durable_failure,
                            "execution_started": False,
                            "required_next_action": "INTERNAL_CONTRACT_CONFLICT",
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "generate_result": "BLOCKED",
                            "generate_exit_reason": "managed_artifact_projection_conflict",
                            "recovery_phase": "exhausted",
                            "next_step": "finish",
                        }
                    if artifact_violations:
                        violation_payload = [item.to_dict() for item in artifact_violations]
                        first_violation = violation_payload[0]
                        script_violation_payload = (
                            project_script_artifact_repair_violations(
                                violation_payload,
                                list(
                                    structured_action.get(
                                        "controller_artifact_environment"
                                    )
                                    or []
                                ),
                                language=str(
                                    structured_action.get("language") or "bash"
                                ),
                            )
                            if str(structured_action.get("script_adapter") or "")
                            == "script_block_v1"
                            else violation_payload
                        )
                        raw_first_owner = str(
                            first_violation.get("owner") or "GENERATED_ACTION"
                        ).upper()
                        first_owner = (
                            RecoveryFailureOwner.INTERNAL_PROTOCOL.value
                            if raw_first_owner in {
                                "CONTROLLER_PROJECTION",
                                RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            }
                            else raw_first_owner
                        )
                        if first_owner == RecoveryFailureOwner.DEPENDENCY.value:
                            dependency_context = build_preaction_recovery_context(
                                task_id=task_id,
                                step_id=current_action_step_id,
                                approved_plan_snapshot_id=str(
                                    approved_action_snapshot.get("plan_snapshot_id") or ""
                                ),
                                authoritative_state_hash=str(
                                    (current_action_plan.get("current_plan") or {}).get("plan_semantic_hash")
                                    or ""
                                ),
                                candidate=structured_action,
                                candidate_fingerprint=candidate_fingerprint,
                                violations=violation_payload,
                                repair_ordinal=1,
                                visible_artifacts=[],
                                current_step=current_action_step or {},
                            )
                            RecoveryStateStore(self.data_path, task_id).save_diagnostic_context(
                                dependency_context
                            )
                            return {
                                "messages": [response, SystemMessage(content=(
                                    "<managed_artifact_dependency_unavailable>\n"
                                    + json.dumps(violation_payload, ensure_ascii=False, sort_keys=True)
                                    + "\n</managed_artifact_dependency_unavailable>"
                                ))],
                                "pending_action": {},
                                "pending_recovery_action": {
                                    "type": "dependency_not_ready",
                                    "reason": str(first_violation.get("message") or "dependency unavailable"),
                                    "failure_owner": RecoveryFailureOwner.DEPENDENCY.value,
                                    "violation": first_violation,
                                },
                                "recovery_context": dependency_context.to_dict(),
                                "recovery_context_digest": dependency_context.context_id,
                                "required_next_action": "DEPENDENCY_NOT_READY",
                                "failure_owner": RecoveryFailureOwner.DEPENDENCY.value,
                                "generate_result": "NEEDS_RECOVERY",
                                "generate_exit_reason": "managed_artifact_dependency_unavailable",
                                "next_step": "supervisor",
                            }
                        violation_codes = {
                            str(item.get("code") or "") for item in violation_payload
                        }
                        representation_codes = {
                            "ACTION_ARGV_INVALID",
                            "ACTION_ENV_INVALID",
                            "ACTION_ENV_KEY_INVALID",
                            "ACTION_ENV_VALUE_INVALID",
                        }
                        repair_domain = (
                            PreActionRepairDomain.REPRESENTATION.value
                            if violation_codes and violation_codes <= representation_codes
                            else PreActionRepairDomain.GENERATED_SEMANTIC.value
                        )
                        previous_candidate_fingerprint = str(
                            recovery_context_obj.candidate_fingerprint
                            if recovery_context_obj
                            and recovery_context_obj.failure_stage == "pre_action_contract"
                            else ""
                        )
                        recovery_context, policy_decision = self._managed_preaction_recovery(
                            task_id=task_id,
                            plan_state=current_action_plan,
                            approved_plan_snapshot=approved_action_snapshot,
                            step_id=current_action_step_id,
                            candidate=structured_action,
                            candidate_fingerprint=candidate_fingerprint,
                            previous_candidate_fingerprint=previous_candidate_fingerprint,
                            repair_domain=repair_domain,
                            violations=violation_payload,
                            visible_artifacts=visible_artifacts,
                        )
                        RecoveryStateStore(self.data_path, task_id).save_diagnostic_context(
                            recovery_context
                        )
                        format_repair_allowed = (
                            policy_decision.kind == RecoveryDecisionKind.FORMAT_REPAIR.value
                        )
                        corrective_generate_allowed = bool(
                            policy_decision.kind
                            == RecoveryDecisionKind.RETRY_CURRENT_ACTION.value
                            and policy_decision.repair_domain
                            == PreActionRepairDomain.GENERATED_SEMANTIC.value
                        )
                        repair_allowed = format_repair_allowed or corrective_generate_allowed
                        repair_no_progress = bool(
                            policy_decision.reason_code == "corrective_generate_no_progress"
                        )
                        termination_reason = (
                            "repair_no_progress"
                            if repair_no_progress
                            else (
                                "action_format_repair_budget_exhausted"
                                if not repair_allowed
                                and repair_domain == PreActionRepairDomain.REPRESENTATION.value
                                else "corrective_generate_budget_exhausted"
                                if not repair_allowed
                                else ""
                            )
                        )
                        durable_failure = record_preaction_contract_failure(
                            current_action_plan,
                            first_violation,
                            error_fingerprint=recovery_context.error_fingerprint,
                            candidate_fingerprint=candidate_fingerprint,
                            repair_attempt_count=(
                                recovery_context.repair_ordinal
                                if not repair_allowed
                                else max(0, recovery_context.repair_ordinal - 1)
                            ),
                            termination_reason=termination_reason,
                        )
                        save_plan_state(
                            self.data_path,
                            task_id,
                            current_action_plan,
                        )
                        pending_type = (
                            "ACTION_FORMAT_REPAIR"
                            if format_repair_allowed
                            else "same_step_repair"
                            if corrective_generate_allowed
                            else "generated_action_contract_error"
                        )
                        logger.info(
                            "PRE_ACTION_CONTRACT_FAILURE task=%s step_id=%s snapshot_id=%s candidate_fingerprint=%s "
                            "error_fingerprint=%s repair_ordinal=%s owner=%s route=%s",
                            task_id,
                            current_action_step_id,
                            recovery_context.approved_plan_snapshot_id,
                            candidate_fingerprint,
                            recovery_context.error_fingerprint,
                            recovery_context.repair_ordinal,
                            first_owner,
                            policy_decision.next_route,
                        )
                        if repair_no_progress:
                            logger.info(
                                "RECOVERY_NO_PROGRESS_TERMINAL task=%s step_id=%s snapshot_id=%s "
                                "candidate_fingerprint=%s error_fingerprint=%s repair_ordinal=%s "
                                "owner=%s route=%s",
                                task_id,
                                current_action_step_id,
                                recovery_context.approved_plan_snapshot_id,
                                candidate_fingerprint,
                                recovery_context.error_fingerprint,
                                recovery_context.repair_ordinal,
                                first_owner,
                                policy_decision.next_route,
                            )
                        return {
                            "messages": [response, SystemMessage(content=(
                                "<managed_artifact_action_repair>\n"
                                + json.dumps(script_violation_payload, ensure_ascii=False, sort_keys=True)
                                + (
                                    "\nRepair only the reported deterministic structured violation. "
                                    "Preserve unrelated executable source text. "
                                    if str(structured_action.get("script_adapter") or "")
                                    == "script_block_v1"
                                    else "\nUse the required semantic handle placeholder in structured argv/env. "
                                )
                                + "Do not modify the Task or Plan.\n"
                                "</managed_artifact_action_repair>"
                            ))],
                            "pending_action": {},
                            "pending_recovery_action": {
                                "type": pending_type,
                                "reason": str(first_violation.get("message") or "managed artifact mismatch"),
                                "failure_owner": first_owner,
                                "violation": first_violation,
                                "candidate_fingerprint": candidate_fingerprint,
                                "error_fingerprint": recovery_context.error_fingerprint,
                                "failure_stage": "pre_action_contract",
                                "repair_domain": repair_domain,
                                "repair_ordinal": recovery_context.repair_ordinal,
                                "termination_reason": termination_reason,
                                "execution_started": False,
                                "execution_envelope": deepcopy(
                                    structured_action.get(
                                        "recovery_execution_envelope"
                                    ) or {}
                                ),
                                "payload_revision": int(
                                    structured_action.get("payload_revision")
                                    or 0
                                ) + 1,
                            },
                            "recovery_context": recovery_context.to_dict(),
                            "recovery_context_digest": recovery_context.context_id,
                            "recovery_decision": policy_decision.to_dict(),
                            "failure": durable_failure,
                            "primary_failure": durable_failure,
                            "termination_reason": termination_reason,
                            "execution_started": False,
                            "required_next_action": (
                                "ACTION_FORMAT_REPAIR"
                                if format_repair_allowed
                                else "CORRECTIVE_GENERATE"
                                if corrective_generate_allowed
                                else "GENERATED_ACTION_CONTRACT_ERROR"
                            ),
                            "failure_owner": first_owner,
                            "generate_result": (
                                "NEEDS_RECOVERY" if repair_allowed else "BLOCKED"
                            ),
                            "generate_exit_reason": "managed_artifact_preaction_rejected",
                            "next_step": policy_decision.next_route,
                        }
                if (
                    action_result_contract
                    == RecoveryResultContract.DIAGNOSTIC_EVIDENCE.value
                ):
                    diagnostic_envelope = RecoveryExecutionEnvelope.from_mapping(
                        materialized_action.get("recovery_execution_envelope")
                    )
                    diagnostic_store = RecoveryStateStore(
                        self.data_path, task_id
                    )
                    diagnostic_store.save_probe_lifecycle(
                        ProbeLifecycleRecord(
                            recovery_decision_id=(
                                diagnostic_envelope.recovery_decision_id
                            ),
                            probe_id=str(diagnostic_envelope.probe_id or ""),
                            probe_objective=str(
                                recovery_decision.get("probe_objective")
                                or recovery_decision.get("probe_reason")
                                or recovery_decision.get("repair_strategy")
                                or ""
                            ),
                            status=ProbeLifecycleStatus.VALIDATED.value,
                            action_id=diagnostic_envelope.action_id,
                        )
                    )
                    diagnostic_store.append_trace(
                        "DIAGNOSTIC_ACTION_VALIDATED",
                        diagnostic_envelope.to_dict(),
                    )
                materialized_action["candidate_fingerprint"] = candidate_fingerprint
                if str(materialized_action.get("script_adapter") or "") == "script_block_v1":
                    materialized_action["code"] = str(structured_action.get("code") or "")
                    materialized_action["language"] = str(
                        structured_action.get("language") or "bash"
                    )
                else:
                    materialized_action["code"] = shlex.join(
                        [str(item) for item in materialized_action.get("argv") or []]
                    )
                    materialized_action["language"] = "bash"
                structured_action = materialized_action
            active_plan_state = load_plan_state(self.data_path, task_id)
            active_task_state = dict(active_plan_state.get("task_state") or {})
            legacy_renderer_mode = bool(
                active_task_state.get("legacy_renderer_mode") is True
                or str(active_task_state.get("execution_contract") or "")
                == "legacy_renderer_v1"
            )
            if (
                str(structured_action.get("type") or "") == "renderer_invocation"
                and not legacy_renderer_mode
            ):
                renderer_contract_error = {
                    "error_type": "RENDERER_ACTIVE_PATH_RETIRED",
                    "reason": (
                        "V2 managed execution requires Generate to return an execute action "
                        "with typed managed-artifact references."
                    ),
                }
                structured_action = {}
            if structured_action and str(structured_action.get("type") or "") not in {
                "step_completion_candidate", "plan_patch", "blocked"
            }:
                structured_action = self._bind_pending_action(structured_action, state, task_id)
            action_type = str(structured_action.get("type") or "").strip()
            has_execute_body = bool(
                (execute_match and execute_match.group(1).strip())
                or (action_type == "execute" and str(structured_action.get("code") or "").strip())
            )
            plain_final_solution = (
                not any([search_match, install_match, execute_match, ask_user_match, activate_match])
                and not structured_action
                and self._looks_like_plain_final_solution(content)
            )

            generated_action = (
                "finish" if answer_match or action_type == "solution" or plain_final_solution else
                "ask_user" if ask_user_match or action_type == "ask_user" else
                "activate_batch" if activate_match or action_type == "activate_batch" else
                "install" if install_match or action_type == "install_tool" else
                "execute" if has_execute_body else
                "search" if search_match or action_type == "search" else
                "step_completion_candidate" if action_type == "step_completion_candidate" else
                "plan_patch" if action_type == "plan_patch" else
                "blocked" if action_type == "blocked" else
                "continue"
            )
            if generated_action != "continue" and not generate_response_cached:
                current_state = load_plan_state(self.data_path, task_id)
                _, counted_step = current_plan_step_with_index(current_state)
                self._record_generate_action(task_id, str(counted_step.get("step_id") or "lightweight"))
            await self._observe_session_memory(
                task_id,
                "generate",
                messages + [response],
                {
                    "action": generated_action,
                    "content": content[:3000],
                    "current_plan_excerpt": str(current_plan)[:1200],
                    "plan_progress": plan_progress,
                },
            )
            if task_mode in {"readonly", "simple_execute"} and generated_action in {"install", "activate_batch", "search"}:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "lightweight_disallowed_action",
                    f"{task_mode} task emitted disallowed action: {generated_action}",
                )
                repair = (
                    f"{task_mode} task mode forbids `{generated_action}`. Do not install tools, activate workflow batches, "
                    "or search memory. For this lightweight request, output exactly one <execute> block with the explicit "
                    "read-only/check command requested by the user, one <ask_user> if a detail is missing, or one "
                    "<solution> explaining the observed state."
                )
                return {
                    "messages": [response, SystemMessage(content=repair)],
                    "plan_progress": plan_progress,
                    "next_step": "generate",
                    "pending_action": {},
                }
            if answer_match or action_type == "solution" or plain_final_solution:
                solution_text = (
                    answer_match.group(1).strip()
                    if answer_match
                    else str(structured_action.get("text") or "").strip()
                    if action_type == "solution"
                    else str(content or "").strip()
                )
                if task_mode == "managed":
                    plan_state = load_plan_state(self.data_path, task_id)
                    _, candidate_step = current_plan_step_with_index(plan_state)
                    candidate_step = candidate_step or {}
                    return {
                        "messages": [response],
                        "pending_action": {},
                        "completion_candidate": {
                            "text": solution_text[:12000],
                            "source": (
                                "solution_tag" if answer_match
                                else "structured_solution" if action_type == "solution"
                                else "plain_language_completion"
                            ),
                            "step_id": str(candidate_step.get("step_id") or ""),
                            "plan_version": str(plan_state.get("plan_version") or ""),
                            "created_at": datetime.now().isoformat(timespec="seconds"),
                        },
                        "final_audit_requested": True,
                        "generate_result": "GENERATED_ACTION",
                        "generate_exit_reason": "completion_candidate",
                        "next_step": "supervisor_final_audit",
                    }
                can_finish, plan_progress, final_status, gate_feedback = self._prepare_final_solution_progress(
                    task_id,
                    solution_text,
                    str(current_plan or ""),
                )
                if not can_finish:
                    gate_message = (
                        "Final solution validation failed.\n\n"
                        f"{gate_feedback}\n\n"
                        "Do not finish yet. Continue the current plan step, run concrete verification, "
                        "and only produce <solution> after the promised artifacts exist or a real blocker is recorded."
                    )
                    return {
                        "messages": [response, SystemMessage(content=gate_message)],
                        "plan_progress": plan_progress,
                        "next_step": "generate",
                        "pending_action": {},
                    }
                await self._finalize_task_memory(
                    task_id,
                    final_status,
                    messages + [response],
                    {"solution": solution_text[:3000], "plan_progress": plan_progress},
                )
                return {"messages": [response], "plan_progress": plan_progress, "next_step": "finish", "pending_action": {}}

            if action_type == "step_completion_candidate":
                return {
                    "messages": [response],
                    "pending_action": {},
                    "step_completion_candidate": dict(structured_action),
                    "generate_result": "GENERATED_ACTION",
                    "generate_exit_reason": "step_completion_candidate",
                    "next_step": "generate",
                }

            if action_type == "plan_patch":
                failure_owner = str(structured_action.get("failure_owner") or "").strip().upper()
                if failure_owner != RecoveryFailureOwner.PLAN.value:
                    return {
                        "messages": [response, SystemMessage(content=(
                            "PLAN_PATCH was rejected because it did not declare failure_owner=PLAN. "
                            "Execution, generated-action, script, runtime, dependency, artifact, and verification "
                            "failures must be repaired in the current step. Return one current-step action."
                        ))],
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "same_step_generate",
                            "reason": "plan_patch_without_confirmed_plan_owner",
                            "failure_owner": RecoveryFailureOwner.GENERATED_ACTION.value,
                        },
                        "required_next_action": "SAME_STEP_GENERATE",
                        "failure_owner": RecoveryFailureOwner.GENERATED_ACTION.value,
                        "recovery_scope": "CURRENT_STEP",
                        "generate_result": "NEEDS_RECOVERY",
                        "generate_exit_reason": "plan_patch_owner_rejected",
                        "next_step": "generate",
                    }
                return {
                    "messages": [response],
                    "pending_action": {},
                    "pending_recovery_action": {
                        "type": "plan_patch",
                        "reason": str(structured_action.get("reason") or ""),
                        "patch": structured_action.get("patch") or {},
                        "failure_owner": RecoveryFailureOwner.PLAN.value,
                    },
                    "required_next_action": "PLAN_PATCH",
                    "failure_owner": RecoveryFailureOwner.PLAN.value,
                    "recovery_scope": "CURRENT_STEP",
                    "generate_result": "NEEDS_RECOVERY",
                    "generate_exit_reason": "plan_patch",
                    "next_step": "planner",
                }

            if action_type == "blocked":
                renderer_protocol = self._renderer_action_protocol(state, task_id)
                if (
                    renderer_protocol.get("renderer_composite")
                    and renderer_protocol.get("manifest_status") != "registered"
                    and not self._renderer_blocked_has_deterministic_evidence(
                        structured_action, renderer_protocol
                    )
                ):
                    blocked_hash = hashlib.sha256(
                        json.dumps(structured_action, ensure_ascii=False, sort_keys=True).encode("utf-8")
                    ).hexdigest()[:20]
                    repair_feedback = self._action_format_repair_feedback(
                        state,
                        task_id,
                        invalid_hash=blocked_hash,
                        invalid_excerpt=str(content or ""),
                        contract_error={
                            "error_type": "BLOCKED_WITHOUT_DETERMINISTIC_MISSING_EVIDENCE",
                            "missing_roles": renderer_protocol.get("missing_roles") or [],
                            "ambiguous_roles": renderer_protocol.get("ambiguous_roles") or [],
                        },
                    )
                    return {
                        "messages": [response, SystemMessage(content=repair_feedback)],
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "ACTION_FORMAT_REPAIR",
                            "reason": "BLOCKED lacked deterministic missing-input evidence.",
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        },
                        "required_next_action": "ACTION_FORMAT_REPAIR",
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "generate_result": "NEEDS_RECOVERY",
                        "generate_exit_reason": "blocked_evidence_rejected",
                        "next_step": "generate",
                    }
                return {
                    "messages": [response],
                    "pending_action": {},
                    "pending_recovery_action": {
                        "type": "blocked",
                        "reason": str(structured_action.get("reason") or ""),
                    },
                    "generate_result": "BLOCKED",
                    "generate_exit_reason": "blocked",
                    "next_step": "finish",
                }

            if execute_match and not has_execute_body:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "execute_empty_body",
                    "Generate emitted an empty <execute> block.",
                )
                repair = (
                    "Generate emitted an empty <execute> block. The next response must either provide a non-empty "
                    "<execute>...</execute> command for the current checklist step, ask the user for a missing decision, "
                    "or write truthful blocked/partial-success artifacts. Do not explain only."
                )
                return {
                    "messages": [response, SystemMessage(content=repair)],
                    "plan_progress": plan_progress,
                    "next_step": "generate",
                    "pending_action": {},
                }

            if (activate_match or action_type == "activate_batch") and not answer_match:
                plan_state = load_plan_state(self.data_path, task_id)
                if int(plan_state.get("plan_schema_version") or plan_state.get("schema_version") or 0) >= 2:
                    plan_progress = self._record_plan_current_evidence(
                        task_id,
                        "generate_attempted_activation",
                        "Generate emitted legacy ACTIVATE_BATCH for a step-scheduled plan.",
                    )
                    return {
                        "messages": [
                            response,
                            SystemMessage(
                                content=(
                                    "ACTIVATE_BATCH is not valid for a structured step-scheduled plan. The controller already derived "
                                    "the current stage and ACTIVE_SKILLS from the running step. Execute that step, ask "
                                    "for required input, install its declared runtime, or finish as specified."
                                )
                            ),
                        ],
                        "plan_progress": plan_progress,
                        "next_step": "generate",
                        "pending_action": {},
                    }
                batch_id = (
                    activate_match.group(1).strip()
                    if activate_match
                    else str(structured_action.get("batch_id") or "").strip()
                )
                update = self._activate_workflow_batch(state, batch_id)
                update_messages = update.get("messages", []) if isinstance(update, dict) else []
                update_text = "\n".join(str(getattr(msg, "content", msg)) for msg in update_messages)
                plan_progress = self._record_activate_batch_progress(
                    task_id,
                    batch_id,
                    update_text,
                )
                return {
                    **update,
                    "messages": [response] + update.get("messages", []),
                    "plan_progress": plan_progress,
                    "next_step": "generate",
                    "pending_action": {},
                }

            if (ask_user_match or action_type == "ask_user") and not answer_match:
                question = (
                    ask_user_match.group(1).strip()
                    if ask_user_match
                    else str(structured_action.get("question") or "").strip()
                )
                plan_progress = self._record_plan_current_evidence(task_id, "generate_asked_user", question[:1000])
                return {
                    "messages": [response],
                    "pending_human_question": {
                        "type": "generate_question",
                        "stage": "generate",
                        "question": question,
                        "context": str(current_plan)[:1200],
                        "resume_step": "generate",
                    },
                    "plan_progress": plan_progress,
                    "next_step": "ask_user",
                    "pending_action": structured_action if structured_action else {},
                }

            # Active RAG
            if search_match or action_type == "search":
                query = search_match.group(1).strip() if search_match else str(structured_action.get("query") or "").strip()
                search_plan_state = load_plan_state(self.data_path, task_id)
                search_step = self._running_plan_step(search_plan_state)
                if step_requires_execution_evidence(search_step):
                    reason = (
                        "SEARCH retrieves knowledge-base text and cannot satisfy local filesystem validation. "
                        "Return an EXECUTE action containing a bounded read-only check for the current step."
                    )
                    plan_progress = self._record_plan_current_evidence(
                        task_id,
                        "knowledge_search_rejected_for_local_validation",
                        reason,
                    )
                    return {
                        "messages": [response, SystemMessage(content=f"<action_protocol_error>\n{reason}\n</action_protocol_error>")],
                        "plan_progress": plan_progress,
                        "next_step": "generate",
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "ACTION_FORMAT_REPAIR",
                            "reason": reason,
                            "required_next_action": "EXECUTE",
                        },
                        "required_next_action": "ACTION_FORMAT_REPAIR",
                    }
                output.print_once(f"rag:{query[:30]}", f"🔍 Searching KB: {query}", Fore.CYAN)
                rag_result = "No info found."
                if self.retriever:
                    try:
                        is_error = "error" in query.lower()
                        target_kb = KB_MAP.get("ERRORS" if is_error else "SOP")
                        rag_result = self.retriever.retrieve(query, target_datasets=[target_kb]) or "No info found."
                    except Exception as e:
                        rag_result = f"Search error: {e}"
                if str(rag_result).startswith("Search error:"):
                    plan_progress = self._record_plan_current_evidence(task_id, "search_failed", rag_result[:1000])
                elif self._plan_step_action_is(self._running_plan_step(load_plan_state(self.data_path, task_id)), "search"):
                    plan_progress = self._mark_plan_current_done(task_id, f"search completed: {query[:500]}")
                else:
                    plan_progress = self._record_plan_current_evidence(task_id, "search_completed", query[:500])
                tool_msg = HumanMessage(content=f"<rag_result>\n{query}\n{rag_result}\n</rag_result>")
                return {"messages": [response, tool_msg], "plan_progress": plan_progress, "next_step": "generate", "pending_action": {}}

            next_step = "generate"
            if answer_match or action_type == "solution":
                next_step = "finish"
            elif ask_user_match or action_type == "ask_user":
                next_step = "ask_user"
            elif (install_match or action_type == "install_tool") and task_mode not in {"readonly", "simple_execute"}:
                next_step = "install_subagent"
            elif has_execute_body:
                next_step = "execute"

            if generated_action == "continue":
                protocol_error = deepcopy(renderer_contract_error or action_parse_error)
                repair_stage = str(protocol_error.get("stage") or "action_schema")
                previous_candidate: Any = (
                    deepcopy(structured_parse_result.candidate)
                    if repair_stage == "action_schema"
                    and structured_parse_result.candidate not in (None, "", [], {})
                    else structured_parse_result.raw_candidate
                )
                if previous_candidate in (None, "", [], {}):
                    previous_candidate = self._bounded_protocol_excerpt(str(content or ""))
                format_count, duplicate_count, invalid_hash, format_decision = self._record_action_format_failure(
                    task_id,
                    str((current_plan_step_with_index(load_plan_state(self.data_path, task_id))[1] or {}).get("step_id") or "lightweight"),
                    str(content or ""),
                    protocol_error,
                )
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "generate_unrecognized_action",
                    json.dumps(
                        {
                            "response_hash": invalid_hash,
                            "format_attempt": format_count,
                            "duplicate_count": duplicate_count,
                            "response_excerpt": str(content or "")[:700],
                            "protocol_error": protocol_error,
                            "schema_error": protocol_error,
                        },
                        ensure_ascii=False,
                    ),
                )
                current_step_state = load_plan_state(self.data_path, task_id)
                _, format_step = current_plan_step_with_index(current_step_state)
                format_step_id = str(format_step.get("step_id") or "lightweight")
                protocol_error_text = (
                    json.dumps(protocol_error, ensure_ascii=False, sort_keys=True)
                    if protocol_error
                    else ""
                )
                protocol_failure_type = (
                    "json_decode_error"
                    if repair_stage == "json_decode"
                    else "action_schema_error"
                )
                format_repair_already_used = (
                    str((state.get("pending_recovery_action") or {}).get("type") or "").strip().lower()
                    in {"action_format_repair", "format_repair"}
                )
                if format_repair_already_used:
                    internal_error = (
                        f"INTERNAL_PROTOCOL_ERROR: Generate failed the structured action protocol after its one repair "
                        f"for {format_step_id}. The raw responses were persisted and no execution retry "
                        "was consumed."
                    )
                    plan_progress = self._finalize_blocked_state(task_id, internal_error)
                    return {
                        "messages": [response, SystemMessage(content=(
                            "<action_format_repair>\n"
                            f"Escalated after repeated invalid actions for {format_step_id}; response_hash={invalid_hash}.\n"
                            "No third identical-context LLM call is permitted.\n"
                            f"{internal_error}\n"
                            "</action_format_repair>"
                        ))],
                        "plan_progress": plan_progress,
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "internal_protocol_error",
                            "reason": "action_format_repair_exhausted",
                            "step_id": format_step_id,
                            "invalid_response_hash": invalid_hash,
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        },
                        "diagnostic_summary": {
                            "root_cause": internal_error,
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "failure_type": protocol_failure_type,
                            "protocol_error": protocol_error,
                            "evidence": [
                                f"response_hash:{invalid_hash}",
                                *([protocol_error_text] if protocol_error_text else []),
                            ],
                            "confidence": 1.0,
                            "missing_evidence": [],
                            "repair_strategy": "Repair the internal action protocol before resuming the step.",
                            "next_action": "INTERNAL_PROTOCOL_ERROR",
                            "requires_user_input": False,
                        },
                        "pending_human_question": {},
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                        "generate_result": "BLOCKED",
                        "generate_exit_reason": "internal_protocol_error",
                        "task_status": TASK_STATUS_BLOCKED,
                        "recovery_decision": format_decision.to_dict(),
                        "next_step": "finish",
                    }
                repair_feedback = self._action_format_repair_feedback(
                    state,
                    task_id,
                    invalid_hash=invalid_hash,
                    invalid_excerpt=str(content or ""),
                    contract_error=protocol_error,
                )
                renderer_protocol = self._renderer_action_protocol(state, task_id)
                return {
                    "messages": [
                        response,
                        SystemMessage(content=repair_feedback),
                    ],
                    "plan_progress": plan_progress,
                    "pending_action": {},
                    "pending_recovery_action": {
                        "type": "ACTION_FORMAT_REPAIR",
                        "step_id": format_step_id,
                        "invalid_response_hash": invalid_hash,
                        "invalid_response_excerpt": str(content or "")[:700],
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "allowed_actions": renderer_protocol.get("allowed_actions") or [],
                        "repair_stage": repair_stage,
                        "previous_candidate": previous_candidate,
                        "protocol_error": protocol_error,
                        "schema_error": protocol_error,
                        "repair_instruction": self._corrective_action_repair_instruction(),
                    },
                    "action_format_repair": {
                        "step_id": format_step_id,
                        "invalid_response_hash": invalid_hash,
                        "attempt": format_count,
                        "feedback": repair_feedback,
                        "repair_stage": repair_stage,
                        "previous_candidate": previous_candidate,
                        "protocol_error": protocol_error,
                    },
                    "required_next_action": "ACTION_FORMAT_REPAIR",
                    "recovery_decision": format_decision.to_dict(),
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    "generate_result": "NEEDS_RECOVERY",
                    "generate_exit_reason": "unrecognized_action",
                    "next_step": "generate",
                }

            return {
                "messages": [response],
                "plan_progress": plan_progress,
                **step_skill_update,
                "next_step": next_step,
                "pending_action": structured_action if structured_action else {},
            }

        async def generate(state: AgentState):
            """Lifecycle-logged boundary around every Generate return path."""
            task_id = str(state.get("task_id") or "unknown")
            generate_call_audit[task_id] = False

            def logged_early_exit(result: Dict[str, Any], entry_record: Dict[str, Any]) -> Dict[str, Any]:
                exit_record = {
                    "event": "generate_exit",
                    "exit_reason": str(result.get("generate_exit_reason") or result.get("next_step") or "guarded_exit"),
                    "next_node": str(result.get("next_step") or ""),
                    "llm_invoked": False,
                    "state_changes": sorted(str(key) for key in result.keys()),
                    "result": str(result.get("generate_result") or "NEEDS_RECOVERY"),
                }
                logger.info("Generate lifecycle: task=%s %s", task_id, json.dumps(exit_record, ensure_ascii=False, sort_keys=True))
                result["generate_lifecycle"] = {"enter": entry_record, "exit": exit_record}
                return result

            plan_state = load_plan_state(self.data_path, task_id)
            _, current_step = current_plan_step_with_index(plan_state)
            current_step = current_step or {}
            current_step_id = str(current_step.get("step_id") or state.get("current_step_id") or "")
            recovery_action = str(
                (state.get("pending_recovery_action") or {}).get("type")
                or state.get("required_next_action")
                or ""
            )
            recovery_action_type = recovery_action.lower()
            durable_status = task_status(plan_state)
            if durable_status in TASK_TERMINAL_STATUSES or recovery_action_type == "blocked":
                reason = str((state.get("pending_recovery_action") or {}).get("reason") or f"task status is {durable_status}")
                early_entry = {
                    "event": "generate_enter",
                    "current_step_id": current_step_id,
                    "plan_version": str(plan_state.get("plan_version") or ""),
                    "recovery_action": recovery_action,
                    "remaining_budget": 0,
                }
                logger.info(
                    "Generate lifecycle: task=%s %s",
                    task_id,
                    json.dumps(early_entry, ensure_ascii=False, sort_keys=True),
                )
                return logged_early_exit({
                    "messages": [SystemMessage(content=f"Generate was not invoked because the task is terminal: {reason}")],
                    "pending_action": {},
                    "pending_recovery_action": {},
                    "next_step": "finish",
                    "generate_result": "BLOCKED" if durable_status != TASK_STATUS_COMPLETED else "FINISHED",
                    "generate_exit_reason": "terminal_state_before_generate",
                }, early_entry)
            if str(state.get("task_mode") or "managed").lower() == "managed" and not current_step_id:
                early_entry = {
                    "event": "generate_enter",
                    "current_step_id": "",
                    "plan_version": str(plan_state.get("plan_version") or ""),
                    "recovery_action": recovery_action,
                    "remaining_budget": 0,
                }
                logger.info("Generate lifecycle: task=%s %s", task_id, json.dumps(early_entry, ensure_ascii=False, sort_keys=True))
                return logged_early_exit({
                    "messages": [SystemMessage(content="Generate was not invoked because no executable current plan step exists.")],
                    "pending_action": {},
                    "required_next_action": "PLAN_PATCH",
                    "failure_owner": RecoveryFailureOwner.PLAN.value,
                    "recovery_scope": "PLAN",
                    "recovery_phase": "plan_repair",
                    "next_step": "planner",
                    "generate_result": "NEEDS_RECOVERY",
                    "generate_exit_reason": "current_step_missing",
                }, early_entry)
            task_budgets = dict((plan_state.get("task_state") or {}).get("budgets") or {})
            if recovery_action_type == "action_format_repair":
                repair_counts = dict(task_budgets.get("action_format_repair_by_step") or {})
                generate_remaining = max(0, 1 - int(repair_counts.get(current_step_id or "lightweight") or 0))
            else:
                action_counts = dict(task_budgets.get("generate_action_count_by_step") or {})
                generate_remaining = max(0, 8 - int(action_counts.get(current_step_id or "lightweight") or 0))
            entry = {
                "event": "generate_enter",
                "current_step_id": current_step_id,
                "plan_version": str(plan_state.get("plan_version") or state.get("plan_version") or ""),
                "validation_status": str((state.get("validation_evidence") or {}).get("status") or ""),
                "retry_count": int(state.get("retry_count") or 0),
                "recovery_action": recovery_action,
                "context_mode": str((state.get("context_budget_report") or {}).get("projection_mode") or "current_step"),
                "remaining_budget": generate_remaining,
            }
            consumed_identity = plan_identity(plan_state)
            approval_record = dict(plan_state.get("approval_record") or {})
            entry.update({
                "generate_call_id": "generate-" + hashlib.sha256(
                    (
                        f"{task_id}|{consumed_identity['plan_version']}|"
                        f"{consumed_identity['plan_semantic_hash']}|{current_step_id}"
                    ).encode("utf-8")
                ).hexdigest()[:20],
                "consumed_plan_id": consumed_identity["plan_id"],
                "consumed_plan_version": consumed_identity["plan_version"],
                "consumed_plan_semantic_hash": consumed_identity["plan_semantic_hash"],
                "approval_id": str(approval_record.get("approval_id") or "legacy-approval"),
                "approval_validation": "passed",
            })
            logger.info("Generate lifecycle: task=%s %s", task_id, json.dumps(entry, ensure_ascii=False, sort_keys=True))

            try:
                result = await _generate_impl(state)
            except Exception as exc:
                logger.exception("Generate failed before producing an explicit state transition: task=%s", task_id)
                result = {
                    "messages": [SystemMessage(content=f"Generate failed explicitly: {type(exc).__name__}: {exc}")],
                    "next_step": "supervisor",
                    "generate_result": "NEEDS_RECOVERY",
                    "generate_exit_reason": "generate_exception",
                }

            if not isinstance(result, dict):
                result = {
                    "messages": [SystemMessage(content="Generate returned no structured result; recovery is required.")],
                    "next_step": "supervisor",
                    "generate_result": "NEEDS_RECOVERY",
                    "generate_exit_reason": "invalid_generate_return",
                }

            if (
                recovery_action_type in {
                    "action_format_repair", "controller_audit_repair",
                    "script_patch", "runtime_recovery", "renderer_recovery",
                    "same_step_repair", "repair_previous_action",
                }
                and str(result.get("generate_exit_reason") or "") != "unrecognized_action"
                and not result.get("pending_recovery_action")
            ):
                result["pending_recovery_action"] = {}
                result["required_next_action"] = ""
                result["action_format_repair"] = {}
                if str(result.get("next_step") or "") == "execute":
                    # The committed repair decision has been consumed by this
                    # newly parsed and re-audited action. Leaving it in graph
                    # state would replay the repair instead of executing it.
                    result["recovery_decision"] = {}
                    result["recovery_application"] = {}
                    result["recovery_context"] = {}
                    result["recovery_context_digest"] = ""

            next_node = str(result.get("next_step") or "")
            outcome = str(result.get("generate_result") or "").upper()
            if outcome not in {
                "GENERATED_ACTION", "NEEDS_RECOVERY", "NEEDS_CONTEXT_COMPACTION",
                "SKILL_CONTINUATION", "SKILL_BINDING_PROPOSED",
                "SKILL_NO_PROGRESS", "STALE_NODE_RESULT", "BLOCKED", "FINISHED",
            }:
                if str(result.get("recovery_status") or "") == "PROMPT_ASSEMBLY_FAILURE":
                    outcome = "BLOCKED"
                elif next_node == "finish":
                    outcome = "FINISHED"
                elif next_node in {"supervisor", "planner"} or result.get("pending_recovery_action"):
                    outcome = "NEEDS_RECOVERY"
                else:
                    outcome = "GENERATED_ACTION"
            exit_reason = str(result.get("generate_exit_reason") or result.get("recovery_status") or next_node or outcome)
            exit_record = {
                "event": "generate_exit",
                "exit_reason": exit_reason,
                "next_node": next_node,
                "llm_invoked": bool(generate_call_audit.pop(task_id, False)),
                "state_changes": sorted(str(key) for key in result.keys()),
                "result": outcome,
            }
            logger.info("Generate lifecycle: task=%s %s", task_id, json.dumps(exit_record, ensure_ascii=False, sort_keys=True))
            result["generate_result"] = outcome
            result["generate_lifecycle"] = {"enter": entry, "exit": exit_record}
            if outcome == "BLOCKED" and str(result.get("recovery_status") or "") == "INTERNAL_PROTOCOL_ERROR":
                output.print_ai(
                    "Generate stopped with an explicit internal protocol failure because required current-step "
                    "context could not fit the prompt budget. The scientific plan step was not marked blocked."
                )
            return result

        # ════════════════════════════════════════════
        # Node 3: Execute
        # ════════════════════════════════════════════
        async def execute_logic(state: AgentState) -> AgentState:
            output.print_node_header("execute")
            task_id      = state.get("task_id", "default")

            def stale_pending_action_update(
                action: Mapping[str, Any],
                mismatches: Mapping[str, Any],
                *,
                phase: str,
            ) -> Dict[str, Any]:
                stale = {
                    "decision_result": "STALE_NODE_RESULT",
                    "status": "discarded",
                    "caller_node": "execute",
                    "action_id": str(action.get("action_id") or ""),
                    "step_id": str(action.get("step_id") or ""),
                    "changed_preconditions": sorted(mismatches),
                    "revision_comparison": deepcopy(dict(mismatches)),
                    "phase": str(phase),
                    "counts_as_failure": False,
                    "consumes_execution_retry": False,
                    "consumes_recovery_retry": False,
                    "execute": False,
                }
                action_id = str(action.get("action_id") or "")
                audit_persisted = False
                for _ in range(3):
                    current = load_plan_state(self.data_path, task_id)
                    current_task_state = dict(
                        current.get("task_state") or {}
                    )
                    durable_pending = dict(
                        current_task_state.get("pending_action") or {}
                    )
                    if (
                        action_id
                        and str(durable_pending.get("action_id") or "")
                        == action_id
                    ):
                        current_task_state["pending_action"] = {}
                    access = record_skill_access_event(
                        current_task_state.get("skill_access_state")
                        or current.get("skill_access_state"),
                        "stale_execution_result_discarded",
                        stale,
                    )
                    current_task_state["skill_access_state"] = access
                    current["task_state"] = current_task_state
                    current["skill_access_state"] = deepcopy(access)
                    try:
                        save_plan_state(self.data_path, task_id, current)
                        audit_persisted = True
                        break
                    except StateCASConflict:
                        continue
                stale["audit_persisted"] = audit_persisted
                changed = set(stale["changed_preconditions"])
                route = (
                    "consultant"
                    if changed
                    & {"task_revision", "authoritative_user_turn_revision"}
                    else "planner"
                )
                return {
                    "messages": [SystemMessage(content=json.dumps(
                        stale, ensure_ascii=False, sort_keys=True,
                    ))],
                    "stale_node_result": deepcopy(stale),
                    "execution_result": deepcopy(stale),
                    "next_step": route,
                }

            resumed_attempt = await self._resume_durable_attempt_update(task_id, state)
            if resumed_attempt is not None:
                return resumed_attempt

            captured_pending_action = dict(state.get("pending_action") or {})
            prestart_plan_state = load_plan_state(self.data_path, task_id)
            prestart_mismatches = self._pending_action_revision_mismatches(
                captured_pending_action,
                prestart_plan_state,
            ) if captured_pending_action else {}
            if prestart_mismatches:
                return stale_pending_action_update(
                    captured_pending_action,
                    prestart_mismatches,
                    phase="before_execute_preflight",
                )

            stale_reason = self._stale_plan_task_revision_reason(state, task_id)
            if stale_reason:
                return {
                    "messages": [SystemMessage(content=json.dumps({
                        "decision_result": "STALE_NODE_RESULT",
                        "caller_node": "execute",
                        "changed_preconditions": [
                            "generated_from_task_revision"
                        ],
                        "detail": stale_reason,
                        "counts_as_failure": False,
                        "consumes_execution_retry": False,
                    }, ensure_ascii=False, sort_keys=True))],
                    "stale_node_result": {
                        "decision_result": "STALE_NODE_RESULT",
                        "caller_node": "execute",
                        "changed_preconditions": [
                            "generated_from_task_revision"
                        ],
                    },
                    "next_step": "planner",
                }

            task_spec = self._task_spec_for_state(dict(state), state.get("messages", []))
            observed_conditions: Dict[str, Any] = {}
            for source in (state.get("runtime_status"), state.get("execution_evidence")):
                if not isinstance(source, dict):
                    continue
                observed_conditions.update(dict(source.get("conditions") or {}))
                for item in source.get("semantic_claims", []) or []:
                    if isinstance(item, dict) and item.get("semantic_key"):
                        observed_conditions[str(item.get("semantic_key"))] = item.get("value")
            failure_policy = evaluate_failure_policies(task_spec, observed_conditions)
            if failure_policy.get("blocked"):
                reason = str(failure_policy.get("reason") or "Typed failure policy blocked execution.")
                plan_progress = self._mark_plan_current_blocked(task_id, reason)
                return {
                    "messages": [SystemMessage(content=f"<observation>⛔ {reason}</observation>")],
                    "plan_progress": plan_progress,
                    "pending_action": {},
                    "contract_status": "blocked_by_failure_policy",
                    "task_status": TASK_STATUS_BLOCKED,
                    "next_step": "finish",
                }

            approved_plan = load_plan_state(self.data_path, task_id)
            current_registry = self._knowledge_claim_registry(
                task_id,
                {**dict(state), "task_spec": task_spec},
                approved_plan,
            )
            current_claim_hash = semantic_claim_set_hash(current_registry)
            current_constraint_hash = canonical_constraint_hash(task_spec)
            semantic_delta = approval_semantic_delta(
                approved_plan,
                current_constraint_hash=current_constraint_hash,
                current_claim_set_hash=current_claim_hash,
            )
            if plan_approval_is_current(approved_plan, task_spec_revision(task_spec)) and not semantic_delta["changed"]:
                preflight_conflicts = {
                    "knowledge_claims": [item.to_dict() for item in current_registry.all()],
                    "knowledge_conflicts": [],
                    "knowledge_claim_set_hash": current_claim_hash,
                    "canonical_constraint_hash": current_constraint_hash,
                    "knowledge_conflict_summary": {
                        "phase": "before_execute_approval_reused",
                        "unresolved_count": 0,
                        "blocking_conflicts": [],
                        "requires_probe": [],
                        "decisions": [],
                        "claim_set_hash": current_claim_hash,
                        "delta_validation": "unchanged",
                    },
                }
                logger.info(
                    "Execute semantic delta validation reused approval: task=%s constraint_hash=%s claim_set_hash=%s",
                    task_id,
                    current_constraint_hash[:16],
                    current_claim_hash[:16],
                )
            else:
                preflight_conflicts = self._knowledge_conflict_update(
                    task_id,
                    {**dict(state), "task_spec": task_spec},
                    phase="before_execute_delta",
                    plan_state=approved_plan,
                )
                summary = dict(preflight_conflicts.get("knowledge_conflict_summary") or {})
                summary["delta_validation"] = "changed"
                summary["delta_reasons"] = list(semantic_delta.get("reasons") or [])
                preflight_conflicts["knowledge_conflict_summary"] = summary
            guarded_state = {**dict(state), **preflight_conflicts}
            guard_action, guard_reason = self._knowledge_conflict_execution_guard(task_id, guarded_state)
            if guard_action == "ask_user":
                question = (
                    "A required user constraint conflicts with the current recovery/plan proposal. "
                    "Please decide whether to provide a compatible alternative or stop this stage.\n\n"
                    + guard_reason
                )
                return {
                    **preflight_conflicts,
                    "messages": [HumanMessage(content=f"<observation>⚠️ {guard_reason}</observation>")],
                    "pending_human_question": {
                        "type": "knowledge_conflict",
                        "stage": "execute",
                        "question": question,
                        "resume_step": "planner",
                    },
                    "next_step": "ask_user",
                    "pending_action": {},
                }
            if guard_action == "probe":
                return {
                    **preflight_conflicts,
                    "messages": [SystemMessage(content=(
                        "Execute stopped before running a command because typed post-approval facts require "
                        "revalidation or a compatible scoped plan repair. " + guard_reason
                    ))],
                    "pending_action": {},
                    "required_next_action": "PLAN_PATCH",
                    "failure_owner": RecoveryFailureOwner.PLAN.value,
                    "recovery_scope": "CURRENT_STEP",
                    "next_step": "planner",
                }
            pending_action = captured_pending_action
            managed_mode = str(state.get("task_mode") or "managed").lower() == "managed"
            if managed_mode:
                if self._pending_action_is(pending_action, "execute"):
                    try:
                        assert_current_action_runtime_scope(pending_action)
                    except ActionRuntimeContractError as exc:
                        diagnostic = exc.to_diagnostic()
                        return {
                            "messages": [SystemMessage(content=json.dumps(
                                diagnostic, ensure_ascii=False, sort_keys=True,
                            ))],
                            "pending_action": {},
                            "pending_recovery_action": {
                                "type": "legacy_runtime_scope_regeneration",
                                "reason": exc.code,
                                "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                                "violation": diagnostic,
                                "execution_started": False,
                            },
                            "required_next_action": (
                                "LEGACY_RUNTIME_SCOPE_REQUIRES_REGENERATION"
                            ),
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "generate_result": "NEEDS_RECOVERY",
                            "next_step": "generate",
                        }
                current_action_state = load_plan_state(
                    self.data_path, task_id
                )
                current_action_mismatches = (
                    self._pending_action_revision_mismatches(
                        pending_action,
                        current_action_state,
                    )
                    if pending_action else {}
                )
                if current_action_mismatches:
                    return stale_pending_action_update(
                        pending_action,
                        current_action_mismatches,
                        phase="before_action_contract_validation",
                    )
                contract_error = self._validate_pending_action_contract(
                    pending_action,
                    state,
                    task_id,
                )
                if contract_error:
                    plan_state = load_plan_state(self.data_path, task_id)
                    _, current_step = current_plan_step_with_index(plan_state)
                    step_id = str(current_step.get("step_id") or "task")
                    count, _ = self._increment_durable_budget(
                        task_id,
                        "empty_execute_by_step",
                        step_id,
                        limit=2,
                    )
                    if count >= 2:
                        progress = self._finalize_blocked_state(task_id, contract_error)
                        return {
                            "messages": [HumanMessage(content=f"<observation>❌ {contract_error}</observation>")],
                            "plan_progress": progress,
                            "pending_action": {},
                            "task_status": TASK_STATUS_BLOCKED,
                            "next_step": "finish",
                        }
                    plan_progress = self._record_plan_current_evidence(
                        task_id,
                        "execute_action_contract_failed",
                        contract_error,
                    )
                    return {
                        "messages": [SystemMessage(content=(
                            "Execute was not entered because its action contract is invalid: "
                            + contract_error
                            + " Generate must repair the action metadata for the unchanged current step."
                        ))],
                        "plan_progress": plan_progress,
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "ACTION_FORMAT_REPAIR",
                            "reason": contract_error,
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        },
                        "required_next_action": "ACTION_FORMAT_REPAIR",
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "recovery_scope": "CURRENT_STEP",
                        "recovery_phase": "diagnose",
                        "next_step": "generate",
                    }
            original_code = ""
            if self._pending_action_is(pending_action, "execute"):
                pending_action_reason = self._pending_action_stale_reason(pending_action, state, task_id)
                if pending_action_reason:
                    current_action_state = load_plan_state(
                        self.data_path, task_id
                    )
                    return stale_pending_action_update(
                        pending_action,
                        self._pending_action_revision_mismatches(
                            pending_action,
                            current_action_state,
                        ) or {"pending_action_binding": {
                            "expected": "current",
                            "observed": pending_action_reason,
                        }},
                        phase="before_script_materialization",
                    )
                generated_ref = dict(pending_action.get("generated_script") or {})
                generated_path = str(
                    generated_ref.get("path") or pending_action.get("generated_script_path") or ""
                )
                generated_hash = str(
                    generated_ref.get("sha256") or pending_action.get("generated_script_hash") or ""
                )
                if generated_path:
                    try:
                        generated_bytes = Path(generated_path).read_bytes()
                    except OSError as exc:
                        detail = f"Generated script source is unavailable: {generated_path}: {exc}"
                        return {
                            "messages": [SystemMessage(content=detail)],
                            "pending_action": {},
                            "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "next_step": "supervisor",
                        }
                    actual_hash = hashlib.sha256(generated_bytes).hexdigest()
                    if generated_hash and actual_hash != generated_hash:
                        detail = (
                            "Generated script hash drifted before approval: "
                            f"expected {generated_hash}, observed {actual_hash}."
                        )
                        return {
                            "messages": [SystemMessage(content=detail)],
                            "pending_action": {},
                            "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "next_step": "supervisor",
                        }
                    original_code = generated_bytes.decode("utf-8", errors="replace")
                else:
                    original_code = str(pending_action.get("code") or "")
            if not original_code.strip() and str(state.get("task_mode") or "managed").lower() in {"readonly", "simple_execute"}:
                original_code = self._recent_nonempty_execute_body(state.get("messages", []), window=6)
            if not original_code.strip():
                detail = "No current, revision-bound pending execute action was found."
                plan_progress = self._record_plan_current_evidence(task_id, "execute_missing_code", detail)
                return {"messages": [HumanMessage(content=f"<observation>❌ {detail}</observation>")],
                        "plan_progress": plan_progress,
                        "pending_action": {},
                        "next_step": "generate"}

            recovery_action_type = str(
                (state.get("pending_recovery_action") or {}).get("type")
                or state.get("required_next_action")
                or ""
            ).lower()
            declared_purpose = str(pending_action.get("purpose") or "analysis").strip().lower()
            command_role = str(pending_action.get("command_role") or "").strip().lower()
            if not command_role:
                if recovery_action_type in {"diagnostic_probe", "probe", "run_probe"} or declared_purpose == "probe":
                    command_role = "diagnostic"
                elif declared_purpose == "validation":
                    command_role = "required_validation"
                elif declared_purpose == "fallback" or recovery_action_type == "fallback":
                    command_role = "fallback"
                else:
                    command_role = "primary"

            action_plan_state = load_plan_state(self.data_path, task_id)
            _, action_step = current_plan_step_with_index(action_plan_state)
            action_step_purpose = str((action_step or {}).get("purpose") or "analysis").strip().lower()
            manifest_managed_action = str(pending_action.get("action_source") or "") == "manifest_runner"
            bypass_step_gate = (
                not manifest_managed_action
                and (
                    command_role in {"diagnostic", "optional_probe", "recovery"}
                    or (command_role == "required_validation" and action_step_purpose != "validation")
                )
            )

            if managed_mode and command_role not in {"diagnostic", "optional_probe", "recovery"}:
                dependency_evidence = CompletionGate.validate_dependencies(
                    action_plan_state,
                    str((action_step or {}).get("step_id") or pending_action.get("step_id") or ""),
                    str(pending_action.get("stage_id") or action_plan_state.get("current_stage_id") or ""),
                )
                if not dependency_evidence.satisfied:
                    decision = RecoveryPolicy().decide(
                        dependency_evidence=dependency_evidence.to_dict(),
                        budgets=dict((action_plan_state.get("task_state") or {}).get("budgets") or {}),
                        action_id=str(pending_action.get("action_id") or "dependency-gate"),
                        step_id=str((action_step or {}).get("step_id") or pending_action.get("step_id") or ""),
                        attempt_id=str(pending_action.get("attempt_id") or "dependency-gate"),
                    )
                    decision = contextualize_recovery_decision(decision, source_node="controller")
                    pending_type = {
                        RecoveryDecisionKind.PLAN_PATCH_REQUEST.value: "PLAN_PATCH",
                        RecoveryDecisionKind.ROLLBACK_UPSTREAM_STEP.value: "ROLLBACK_UPSTREAM_STEP",
                        RecoveryDecisionKind.REWIND_MANIFEST_STAGE.value: "REWIND_MANIFEST_STAGE",
                    }.get(decision.kind, decision.kind)
                    return {
                        "messages": [SystemMessage(content=(
                            "DependencyGate rejected the formal action before execution. "
                            f"RecoveryPolicy proposed {decision.kind}: {decision.reason}"
                        ))],
                        "dependency_evidence": dependency_evidence.to_dict(),
                        "recovery_decision": decision.to_dict(),
                        "recovery_application": {},
                        "recovery_status": decision.kind,
                        "pending_recovery_action": {
                            "type": pending_type,
                            "reason": decision.reason,
                            "step_id": dependency_evidence.step_id,
                        },
                        "required_next_action": pending_type,
                        "plan_progress": render_plan_progress(action_plan_state),
                        "pending_action": {},
                        "next_step": decision.next_route,
                    }

            if command_role in {"diagnostic", "optional_probe"}:
                diagnostic_envelope: Optional[RecoveryExecutionEnvelope] = None
                if pending_action.get("recovery_execution_envelope"):
                    try:
                        diagnostic_envelope = RecoveryExecutionEnvelope.from_mapping(
                            pending_action.get("recovery_execution_envelope")
                        )
                    except RecoveryExecutionContractError as exc:
                        probe_allowed, probe_error = False, (
                            f"{exc.code}: {exc.message}"
                        )
                    else:
                        probe_allowed, probe_error = validate_diagnostic_action(
                            {**pending_action, "code": original_code}
                        )
                else:
                    # Compatibility-only optional probes retain the legacy
                    # read-only policy; Recovery probes must carry authority.
                    if command_role == "diagnostic":
                        probe_allowed, probe_error = False, (
                            "RECOVERY_EXECUTION_ENVELOPE_MISSING: diagnostic "
                            "Recovery action cannot default to primary"
                        )
                    else:
                        probe_allowed, probe_error = (
                            validate_diagnostic_probe_code(original_code)
                        )
                if not probe_allowed:
                    if diagnostic_envelope is not None:
                        validation_fingerprint = hashlib.sha256(
                            probe_error.encode("utf-8", errors="replace")
                        ).hexdigest()[:24]
                        diagnostic_store = RecoveryStateStore(
                            self.data_path, task_id
                        )
                        diagnostic_store.save_probe_lifecycle(
                            ProbeLifecycleRecord(
                                recovery_decision_id=(
                                    diagnostic_envelope.recovery_decision_id
                                ),
                                probe_id=str(
                                    diagnostic_envelope.probe_id or ""
                                ),
                                status=(
                                    ProbeLifecycleStatus.NOT_EXECUTED.value
                                ),
                                action_id=diagnostic_envelope.action_id,
                                validation_fingerprint=validation_fingerprint,
                            )
                        )
                        diagnostic_store.append_trace(
                            "DIAGNOSTIC_ACTION_NOT_EXECUTED",
                            {
                                "probe_id": diagnostic_envelope.probe_id,
                                "action_id": diagnostic_envelope.action_id,
                                "reason": probe_error,
                                "validation_fingerprint": (
                                    validation_fingerprint
                                ),
                            },
                        )
                    plan_progress = self._record_plan_current_evidence(
                        task_id,
                        "diagnostic_probe_boundary_failed",
                        probe_error,
                    )
                    return {
                        "messages": [SystemMessage(content=(
                            "Diagnostic probe was rejected before execution: "
                            + probe_error
                            + ". Generate one bounded read-only probe for the current task root."
                        ))],
                        "plan_progress": plan_progress,
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "internal_protocol_error",
                            "reason": probe_error,
                            "failure_owner": (
                                RecoveryFailureOwner.INTERNAL_PROTOCOL.value
                            ),
                            "execution_started": False,
                        },
                        "required_next_action": "INTERNAL_PROTOCOL_ERROR",
                        "failure_owner": (
                            RecoveryFailureOwner.INTERNAL_PROTOCOL.value
                        ),
                        "next_step": "supervisor",
                    }
                if diagnostic_envelope is not None:
                    Path(
                        diagnostic_envelope.scratch_capability.scratch_root
                    ).mkdir(parents=True, exist_ok=True)

            if managed_mode:
                if command_role == "renderer_invocation":
                    execute_count, _ = self._increment_durable_budget(
                        task_id,
                        "renderer_invocations_by_step",
                        str(pending_action.get("step_id") or "task"),
                        limit=2,
                    )
                elif command_role in {"diagnostic", "optional_probe", "required_validation"}:
                    execute_count = len(RecoveryStateStore(self.data_path, task_id).load_execution_records()) + 1
                elif command_role == "recovery":
                    execute_count = len(RecoveryStateStore(self.data_path, task_id).load_execution_records()) + 1
                else:
                    execute_count, _ = self._increment_durable_budget(
                        task_id,
                        "execute_attempts_by_step",
                        str(pending_action.get("step_id") or "task"),
                        limit=3,
                    )
            else:
                execute_count = 1

            if guard_action == "probe":
                # A targeted read-only probe is allowed to resolve the
                # conflict; the old analysis command is not.
                if int(state.get("retry_count") or 0) >= 4:
                    question = (
                        "The same knowledge conflict has remained unresolved after four probe opportunities. "
                        "Please provide a decision or evidence before the analysis can continue.\n\n"
                        + guard_reason
                    )
                    return {
                        **preflight_conflicts,
                        "messages": [HumanMessage(content=f"<observation>⚠️ {guard_reason}</observation>")],
                        "pending_human_question": {
                            "type": "knowledge_conflict_probe_budget",
                            "stage": "execute",
                            "question": question,
                            "resume_step": "planner",
                        },
                        "next_step": "ask_user",
                        "pending_action": {},
                    }
                probe_code = str(original_code or "").lower()
                probe_markers = (
                    "--version", "-version", "--help", "command -v", "type -a", "which ",
                    "stat ", "file ", "sha256sum", "test -", "ls ", "head ", "tail ",
                    "grep ", "find ", "printf ", "echo ",
                )
                if not any(marker in probe_code for marker in probe_markers) or re.search(r"(?:^|\s)-o\s+\S+", probe_code):
                    plan_progress = self._record_plan_current_evidence(task_id, "knowledge_conflict_probe_required", guard_reason)
                    return {
                        **preflight_conflicts,
                        "messages": [HumanMessage(content=(
                            "<observation>⚠️ Execution held because the current plan is stale or has an unresolved "
                            f"knowledge conflict. {guard_reason} Generate a targeted read-only probe or revised plan; "
                            "do not repeat the old analysis command.</observation>"
                        ))],
                        "plan_progress": plan_progress,
                        "pending_action": {},
                        "next_step": "generate",
                    }

            declared_language = str(pending_action.get("language") or "").strip().lower()
            language = {
                "bash": "Bash", "shell": "Bash", "sh": "Bash",
                "python": "Python", "py": "Python",
                "r": "R", "rscript": "R",
            }.get(declared_language, detect_script_language(original_code))
            # Preserve the exact model-authored body. Controller environment
            # materialization stays out of this string and is passed directly
            # to the subprocess boundary below.
            generated_model_code = original_code
            runtime_bindings: Dict[str, str] = {}
            artifact_bindings: Dict[str, str] = {}
            effective_execution_env: Dict[str, str] = {}
            managed_runtime_env_names: set[str] = set()
            current_runtime_resolution: Dict[str, Any] = {}
            current_runtime_manifest: Dict[str, Any] = {}
            current_artifact_manifest: Dict[str, Any] = {}
            current_policy_manifest: Dict[str, Any] = {}
            current_approval_identity: Dict[str, Any] = {}
            controller_identity_env = {
                "BIOMIND_TASK_ID": task_id,
                "BIOMIND_ACTION_ID": str(pending_action.get("action_id") or ""),
                "BIOMIND_STEP_ID": str(pending_action.get("step_id") or ""),
            }
            if managed_mode:
                try:
                    for manifest_key in (
                        "runtime_binding_manifest",
                        "artifact_env_manifest",
                        "execution_policy_manifest",
                    ):
                        validate_manifest_hash(
                            dict(pending_action.get(manifest_key) or {})
                        )
                    capability_registry = (
                        self.skill_manager.get_execution_capability_registry(
                            list((action_step or {}).get("skill_ids") or [])
                        )
                        if self.skill_manager
                        else {}
                    )
                    runtime_binding_registry = build_runtime_binding_registry(state)
                    managed_runtime_env_names.update(
                        str(row.get("env_name") or "")
                        for row in runtime_binding_registry.values()
                        if isinstance(row, Mapping)
                    )
                    for runtime_audit in state.get("runtime_audit", []) or []:
                        if not isinstance(runtime_audit, Mapping):
                            continue
                        managed_runtime_env_names.update(
                            str(name or "").strip().upper()
                            for name in dict(
                                runtime_audit.get("resolved_runtime_paths") or {}
                            )
                        )
                    current_runtime_resolution = resolve_action_runtime_bindings(
                        selected_skill_id=str(
                            pending_action.get("selected_skill_id") or ""
                        ),
                        execution_capability_id=str(
                            pending_action.get("execution_capability_id") or ""
                        ),
                        approved_capability_contract_hash=str(
                            pending_action.get("capability_contract_hash") or ""
                        ),
                        capability_registry=capability_registry,
                        ready_runtime_binding_registry=runtime_binding_registry,
                        current_action_identity={
                            "action_id": str(pending_action.get("action_id") or ""),
                            "plan_id": str(pending_action.get("plan_id") or ""),
                            "step_id": str(pending_action.get("step_id") or ""),
                        },
                    )
                    current_runtime_manifest = dict(
                        current_runtime_resolution.get(
                            "runtime_binding_manifest"
                        ) or {}
                    )
                    if str(current_runtime_manifest.get("manifest_hash") or "") != str(
                        pending_action.get("runtime_binding_manifest_hash") or ""
                    ):
                        raise ActionRuntimeContractError(
                            "RUNTIME_BINDING_SNAPSHOT_DRIFT",
                            action_id=str(pending_action.get("action_id") or ""),
                            approved_manifest_hash=str(
                                pending_action.get("runtime_binding_manifest_hash") or ""
                            ),
                            observed_manifest_hash=str(
                                current_runtime_manifest.get("manifest_hash") or ""
                            ),
                        )
                    current_artifact_manifest = build_artifact_env_manifest(
                        list(
                            pending_action.get("controller_artifact_environment")
                            or []
                        ),
                        action_identity={
                            "action_id": str(pending_action.get("action_id") or ""),
                            "plan_id": str(pending_action.get("plan_id") or ""),
                            "step_id": str(pending_action.get("step_id") or ""),
                        },
                        selected_skill_id=str(
                            pending_action.get("selected_skill_id") or ""
                        ),
                        execution_capability_id=str(
                            pending_action.get("execution_capability_id") or ""
                        ),
                        capability_contract_hash_value=str(
                            pending_action.get("capability_contract_hash") or ""
                        ),
                    )
                    current_policy_manifest = build_execution_policy_manifest(
                        action_identity={
                            "action_id": str(pending_action.get("action_id") or ""),
                            "plan_id": str(pending_action.get("plan_id") or ""),
                            "step_id": str(pending_action.get("step_id") or ""),
                        },
                        working_directory=os.getcwd(),
                        language=language,
                    )
                    current_approval_identity = build_action_approval_identity(
                        generated_script_sha256=str(
                            pending_action.get("generated_script_hash")
                            or pending_action.get("generated_script_sha256")
                            or ""
                        ),
                        capability_contract_hash_value=str(
                            pending_action.get("capability_contract_hash") or ""
                        ),
                        runtime_env_manifest_hash=str(
                            current_runtime_manifest.get("manifest_hash") or ""
                        ),
                        artifact_env_manifest_hash=str(
                            current_artifact_manifest.get("manifest_hash") or ""
                        ),
                        execution_policy_manifest_hash=str(
                            current_policy_manifest.get("manifest_hash") or ""
                        ),
                        working_directory=os.getcwd(),
                    )
                    validate_action_approval_identity(
                        dict(pending_action.get("action_approval_identity") or {}),
                        current_approval_identity,
                    )
                    runtime_bindings = dict(
                        current_runtime_resolution.get(
                            "effective_runtime_bindings"
                        ) or {}
                    )
                    artifact_bindings = artifact_environment_values(
                        list(
                            pending_action.get("controller_artifact_environment")
                            or []
                        )
                    )
                    conflicts = sorted(set(runtime_bindings) & set(artifact_bindings))
                    if conflicts:
                        raise ActionRuntimeContractError(
                            "RUNTIME_BINDING_MANIFEST_INVALID",
                            action_id=str(pending_action.get("action_id") or ""),
                            conflicting_env_names=conflicts,
                        )
                except ActionRuntimeContractError as exc:
                    diagnostic = exc.to_diagnostic()
                    return {
                        "messages": [SystemMessage(content=json.dumps(
                            diagnostic, ensure_ascii=False, sort_keys=True,
                        ))],
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "runtime_binding_provenance_error",
                            "reason": exc.code,
                            "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                            "violation": diagnostic,
                            "failure_stage": "pre_action_contract",
                            "execution_started": False,
                        },
                        "required_next_action": exc.code,
                        "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                        "recovery_status": "INTERNAL_PROTOCOL_ERROR",
                        "generate_result": "BLOCKED",
                        "next_step": "generate",
                    }
            effective_execution_env = build_action_execution_environment(
                os.environ,
                runtime_bindings=runtime_bindings,
                artifact_bindings=artifact_bindings,
                controller_bindings=controller_identity_env,
                managed_runtime_env_names=managed_runtime_env_names,
            )
            code = normalize_script_code(original_code)
            forbidden_actions = [str(item).strip() for item in (state.get("forbidden_recovery_actions") or []) if str(item).strip()]
            if forbidden_actions:
                normalized_code = ActionSignature.normalize_command(code)
                readonly_forbidden = {"cat", "ls", "find", "head", "tail", "grep", "help"}
                repeated = any(
                    normalized_code == ActionSignature.normalize_command(item)
                    or (" " in item and ActionSignature.normalize_command(item) in normalized_code)
                    or (item.lower() in readonly_forbidden and re.search(rf"\b{re.escape(item)}\b", normalized_code, re.IGNORECASE))
                    for item in forbidden_actions
                )
                if repeated:
                    plan_progress = self._record_plan_current_evidence(
                        task_id,
                        "forbidden_recovery_action",
                        "Generate proposed an action forbidden by the persisted recovery progress: " + ", ".join(forbidden_actions[:5]),
                    )
                    return {
                        "messages": [HumanMessage(content=(
                            "<observation>❌ Recovery action blocked: the proposed command repeats an action "
                            "that produced no independent diagnostic progress. Choose a different probe/repair, "
                            "rollback, or write a truthful blocked artifact.</observation>"
                        ))],
                        "plan_progress": plan_progress,
                        "pending_action": {},
                        "next_step": "generate",
                    }
            task_boundary_context = "\n".join(
                str(getattr(message, "content", message))
                for message in state.get("messages", [])[:8]
            )
            boundary_gate = CompletionGate.validate_code_boundary(code, task_boundary_context)
            if not boundary_gate.passed:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "pre_execution_boundary_gate_failed",
                    boundary_gate.message,
                )
                obs = f"<observation>❌ Pre-execution boundary gate blocked execution.\n{boundary_gate.feedback}\n</observation>"
                return {
                    "messages": [HumanMessage(content=obs)],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id),
                    "next_step": "generate",
                }
            selected_skills_state = state.get("active_skills", []) or []
            future_skills_state = state.get("future_skills", []) or []
            runtime_skills_state = (
                [str(pending_action.get("selected_skill_id"))]
                if managed_mode and str(pending_action.get("selected_skill_id") or "")
                else self._infer_runtime_skills_from_code(code, selected_skills_state)
            )
            selected_skill_pool_state = state.get("selected_skills", []) or runtime_skills_state
            install_redirect = self._redirect_install_command(code, runtime_skills_state)
            if install_redirect:
                install_tool_name = self._install_tool_name(install_redirect)
                install_disallowed = self._runtime_install_disallowed_by_task_spec(
                    self._task_spec_for_state(dict(state), state.get("messages", [])),
                    install_tool_name,
                )
                if install_disallowed:
                    final_res = self._runtime_block_message(install_redirect, runtime_skills_state, code[:1000])
                    plan_progress = self._mark_plan_current_blocked(task_id, final_res)
                    return {
                        "messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                        "plan_progress": plan_progress,
                        "selected_skills": selected_skill_pool_state,
                        "active_skills": runtime_skills_state,
                        "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                        "next_step": self._next_step_after_runtime_block(task_id),
                    }
                plan_progress = self._record_plan_current_evidence(task_id, "redirect_to_install", install_redirect[:1000])
                return {
                    "messages": [AIMessage(content=install_redirect)],
                    "plan_progress": plan_progress,
                    "selected_skills": selected_skill_pool_state,
                    "active_skills": runtime_skills_state,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "install_subagent",
                }

            future_violation = self._workflow_future_skill_violation(code, selected_skills_state, future_skills_state)
            if future_violation:
                plan_progress = self._record_plan_current_evidence(task_id, "future_skill_guard", future_violation[:1000])
                obs = f"<observation>❌ Workflow skill guard blocked execution.\n{future_violation}\n</observation>"
                return {
                    "messages": [HumanMessage(content=obs)],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "generate",
                }

            runner_violation = self._selected_skill_env_runner_violation(code, runtime_skills_state)
            if runner_violation:
                plan_progress = self._record_plan_current_evidence(task_id, "skill_env_runner_guard", runner_violation[:1000])
                obs = f"<observation>❌ Skill runtime guard blocked execution.\n{runner_violation}\n</observation>"
                return {
                    "messages": [HumanMessage(content=obs)],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "generate",
                }

            runtime_ready, runtime_redirect = (
                (True, "")
                if managed_mode
                else self._ensure_skill_runtime_ready(
                    runtime_skills_state, task_id=task_id, code=code
                )
            )
            if not runtime_ready and runtime_redirect:
                if install_disallowed:
                    final_res = self._runtime_block_message(runtime_redirect, runtime_skills_state, runtime_redirect)
                    plan_progress = self._mark_plan_current_blocked(task_id, final_res)
                    return {
                        "messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                        "plan_progress": plan_progress,
                        "selected_skills": selected_skill_pool_state,
                        "active_skills": runtime_skills_state,
                        "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                        "next_step": self._next_step_after_runtime_block(task_id),
                    }
                plan_progress = self._record_plan_current_evidence(task_id, "runtime_not_ready", runtime_redirect[:1000])
                return {
                    "messages": [AIMessage(content=runtime_redirect)],
                    "plan_progress": plan_progress,
                    "selected_skills": selected_skill_pool_state,
                    "active_skills": runtime_skills_state,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "install_subagent",
                }

            # Review the four provenance owners without concatenating their
            # content into one executable string.
            code_review_provenance = build_code_review_provenance(
                code,
                generated_script_sha256=str(
                    pending_action.get("generated_script_hash")
                    or pending_action.get("generated_script_sha256")
                    or ""
                ),
                artifact_env_manifest=current_artifact_manifest,
                runtime_env_manifest=current_runtime_manifest,
                execution_policy_manifest=current_policy_manifest,
            )
            action, final_code = self.middleware.review_code(
                code,
                language,
                provenance=code_review_provenance,
            )
            if action == "reject":
                rejection_reason = str(final_code or "User rejected generated code.")
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "execute_rejected_by_user",
                    rejection_reason[:1000],
                )
                obs = (
                    "<observation>❌ Rejected by user.\n"
                    f"Reason/feedback: {rejection_reason}\n"
                    "</observation>"
                )
                return {"messages": [HumanMessage(content=obs)],
                        "plan_progress": plan_progress,
                        "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                        "next_step": "generate"}
            if action == "quit":
                await self._finalize_task_memory(
                    task_id,
                    "cancelled",
                    state.get("messages", []),
                    {"reason": "User terminated during code review."},
                )
                return {"messages": [HumanMessage(content="Task terminated.")], "next_step": "finish"}

            elif action == "edit":
                # 判断：是直接粘贴的代码，还是指导意见？
                # 简单策略：如果包含中文或明显的描述性词汇，视为反馈
                if re.search(r'[\u4e00-\u9fff]', final_code) or \
                    any(keyword in final_code.lower() for keyword in ['correct', '正确', 'should', '应该', 'use', '使用']):
                    # 这是指导意见，不是代码
                    feedback_msg = f"<observation>⚠️ User provided guidance:\n{final_code}\n\nPlease regenerate code based on this feedback.</observation>"
                    plan_progress = self._record_plan_current_evidence(task_id, "execute_user_guidance", final_code[:1000])
                    return {"messages": [HumanMessage(content=feedback_msg)], "plan_progress": plan_progress, "next_step": "generate"}
                else:   
                    # 这是修改后的代码，可以执行
                    code_to_run = normalize_script_code(final_code)
                    language = detect_script_language(code_to_run)
            else:
                code_to_run = normalize_script_code(final_code)  # approve 的情况  

            boundary_gate = CompletionGate.validate_code_boundary(code_to_run, task_boundary_context)
            if not boundary_gate.passed:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "pre_execution_boundary_gate_failed",
                    boundary_gate.message,
                )
                obs = f"<observation>❌ Pre-execution boundary gate blocked execution.\n{boundary_gate.feedback}\n</observation>"
                return {
                    "messages": [HumanMessage(content=obs)],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "generate",
                }

            # This is the exact approved source that the wrapper will run.
            # Keep it for direct executable-identity evidence after the process.
            approved_source_code = code_to_run
            if str(pending_action.get("script_adapter") or "") == "script_block_v1":
                audit_block = ExecutableScriptBlock(
                    language={"Bash": "bash", "Python": "python", "R": "r"}.get(
                        language, "bash"
                    ),
                    body=code_to_run,
                    tag={"Bash": "shell", "Python": "python", "R": "r"}.get(
                        language, "shell"
                    ),
                )
                execution_audit_findings = audit_generated_script(
                    audit_block,
                    runtime_snapshot={
                        "bindings": dict(runtime_bindings),
                        "runtime_snapshot_digest": str(
                            current_runtime_manifest.get("manifest_hash") or ""
                        ),
                    },
                    artifact_environment=list(
                        pending_action.get("controller_artifact_environment") or []
                    ),
                    evidence_refs=[
                        str(pending_action.get("generated_script_path") or "")
                    ],
                )
                if any(
                    str(item.get("severity") or "").upper() == "HIGH"
                    and bool(item.get("authoritative", True))
                    for item in execution_audit_findings
                ):
                    return {
                        "messages": [SystemMessage(content=(
                            "Controller pre-execution re-audit blocked the script without "
                            "modifying it. Corrective Generate must repair the authoritative findings."
                        ))],
                        "pending_action": {},
                        "pending_recovery_action": {
                            "type": "controller_audit_repair",
                            "reason": "pre_execution_reaudit_failed",
                            "failure_owner": RecoveryFailureOwner.GENERATED_ACTION.value,
                            "previous_script": code_to_run,
                            "previous_script_ref": dict(
                                pending_action.get("generated_script") or {}
                            ),
                            "machine_audit_findings": execution_audit_findings,
                            "repair_target": "previous_generated_script",
                            "repair_instruction": (
                                "Fix the deterministic findings only and preserve unrelated valid logic."
                            ),
                            "execution_started": False,
                        },
                        "controller_machine_audit_findings": execution_audit_findings,
                        "required_next_action": "CORRECTIVE_GENERATE",
                        "failure_owner": RecoveryFailureOwner.GENERATED_ACTION.value,
                        "next_step": "generate",
                    }

            runtime_skills_state = (
                [str(pending_action.get("selected_skill_id"))]
                if managed_mode and str(pending_action.get("selected_skill_id") or "")
                else self._infer_runtime_skills_from_code(
                    code_to_run, selected_skills_state
                )
            )
            selected_skill_pool_state = state.get("selected_skills", []) or runtime_skills_state
            install_redirect = self._redirect_install_command(code_to_run, runtime_skills_state)
            if install_redirect:
                if install_disallowed:
                    final_res = self._runtime_block_message(install_redirect, runtime_skills_state, code_to_run[:1000])
                    plan_progress = self._mark_plan_current_blocked(task_id, final_res)
                    return {
                        "messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                        "plan_progress": plan_progress,
                        "selected_skills": selected_skill_pool_state,
                        "active_skills": runtime_skills_state,
                        "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                        "next_step": self._next_step_after_runtime_block(task_id),
                    }
                plan_progress = self._record_plan_current_evidence(task_id, "redirect_to_install", install_redirect[:1000])
                return {
                    "messages": [AIMessage(content=install_redirect)],
                    "plan_progress": plan_progress,
                    "selected_skills": selected_skill_pool_state,
                    "active_skills": runtime_skills_state,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "install_subagent",
                }

            future_violation = self._workflow_future_skill_violation(code_to_run, selected_skills_state, future_skills_state)
            if future_violation:
                plan_progress = self._record_plan_current_evidence(task_id, "future_skill_guard", future_violation[:1000])
                obs = f"<observation>❌ Workflow skill guard blocked execution.\n{future_violation}\n</observation>"
                return {
                    "messages": [HumanMessage(content=obs)],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "generate",
                }

            runner_violation = self._selected_skill_env_runner_violation(code_to_run, runtime_skills_state)
            if runner_violation:
                plan_progress = self._record_plan_current_evidence(task_id, "skill_env_runner_guard", runner_violation[:1000])
                obs = f"<observation>❌ Skill runtime guard blocked execution.\n{runner_violation}\n</observation>"
                return {
                    "messages": [HumanMessage(content=obs)],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "generate",
                }

            runtime_ready, runtime_redirect = (
                (True, "")
                if managed_mode
                else self._ensure_skill_runtime_ready(
                    runtime_skills_state, task_id=task_id, code=code_to_run
                )
            )
            if not runtime_ready and runtime_redirect:
                if install_disallowed:
                    final_res = self._runtime_block_message(runtime_redirect, runtime_skills_state, runtime_redirect)
                    plan_progress = self._mark_plan_current_blocked(task_id, final_res)
                    return {
                        "messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                        "plan_progress": plan_progress,
                        "selected_skills": selected_skill_pool_state,
                        "active_skills": runtime_skills_state,
                        "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                        "next_step": self._next_step_after_runtime_block(task_id),
                    }
                plan_progress = self._record_plan_current_evidence(task_id, "runtime_not_ready", runtime_redirect[:1000])
                return {
                    "messages": [AIMessage(content=runtime_redirect)],
                    "plan_progress": plan_progress,
                    "selected_skills": selected_skill_pool_state,
                    "active_skills": runtime_skills_state,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "next_step": "install_subagent",
                }

            if managed_mode:
                current_policy_manifest = build_execution_policy_manifest(
                    action_identity={
                        "action_id": str(pending_action.get("action_id") or ""),
                        "plan_id": str(pending_action.get("plan_id") or ""),
                        "step_id": str(pending_action.get("step_id") or ""),
                    },
                    working_directory=os.getcwd(),
                    language=language,
                )
                current_approval_identity = build_action_approval_identity(
                    generated_script_sha256=str(
                        pending_action.get("generated_script_hash")
                        or pending_action.get("generated_script_sha256")
                        or ""
                    ),
                    capability_contract_hash_value=str(
                        pending_action.get("capability_contract_hash") or ""
                    ),
                    runtime_env_manifest_hash=str(
                        current_runtime_manifest.get("manifest_hash") or ""
                    ),
                    artifact_env_manifest_hash=str(
                        current_artifact_manifest.get("manifest_hash") or ""
                    ),
                    execution_policy_manifest_hash=str(
                        current_policy_manifest.get("manifest_hash") or ""
                    ),
                    working_directory=os.getcwd(),
                )

            # Allocate the attempt before materializing the approved/executed
            # versions. Every durable path is therefore namespaced by one attempt.
            step_index = len(state["messages"])
            shim_path  = self.pm.get_shim_dir_str()
            started_at = datetime.now().isoformat(timespec="seconds")
            attempt_plan_state = load_plan_state(self.data_path, task_id)
            managed_output_contracts = [
                dict(item)
                for item in pending_action.get("controller_output_bindings", []) or []
                if isinstance(item, Mapping)
            ]
            if str(pending_action.get("result_contract") or "").upper() in {
                RecoveryResultContract.DIAGNOSTIC_EVIDENCE.value,
                RecoveryResultContract.EXECUTION_BUNDLE.value,
            }:
                managed_output_contracts = []
            managed_output_snapshot_before = capture_managed_output_snapshot(
                managed_output_contracts
            )
            record_provenance_event(attempt_plan_state, "action_bound", {
                "task_id": task_id,
                "action": dict(pending_action),
                "raw_action": dict(pending_action),
            })
            generated_ref = dict(pending_action.get("generated_script") or {})
            attempt_record = record_provenance_event(attempt_plan_state, "attempt_created", {
                "action_id": str(pending_action.get("action_id") or ""),
                "step_id": str(pending_action.get("step_id") or ""),
                "stage_id": str(pending_action.get("stage_id") or ""),
                "generated_script": generated_ref,
                "managed_output_contracts": managed_output_contracts,
                "managed_output_snapshot_before": managed_output_snapshot_before,
            })
            attempt_id = str(attempt_record.get("attempt_id") or "")
            attempt_dir = (
                Path(self.data_path) / "task_outputs" / task_id / "attempts" / attempt_id
            )
            attempt_dir.mkdir(parents=True, exist_ok=True)
            manifest_refs: Dict[str, Dict[str, str]] = {}
            manifest_items = (
                (
                    ("runtime_env_manifest.json", current_runtime_manifest),
                    ("artifact_env_manifest.json", current_artifact_manifest),
                    ("execution_policy_manifest.json", current_policy_manifest),
                )
                if managed_mode else ()
            )
            for filename, manifest in manifest_items:
                manifest_path = attempt_dir / filename
                manifest_path.write_text(
                    json.dumps(
                        manifest,
                        ensure_ascii=False,
                        indent=2,
                        sort_keys=True,
                    ) + "\n",
                    encoding="utf-8",
                )
                manifest_refs[filename] = {
                    "path": str(manifest_path.resolve()),
                    "manifest_hash": str(manifest.get("manifest_hash") or ""),
                }
            stdout_path = attempt_dir / "stdout.log"
            stderr_path = attempt_dir / "stderr.log"
            exit_status_path = attempt_dir / "exit_status.json"
            # Every attempt has a minimal durable runner/return-code trace.
            # Shell policy is invocation metadata and never prepended to the
            # model or approved script bytes.
            trace_file = str(attempt_dir / "command_trace.log")
            stdout_path.touch(exist_ok=True)
            stderr_path.touch(exist_ok=True)
            Path(trace_file).touch(exist_ok=True)
            approved_content = code_to_run
            approved_ref = self._persist_script_version(
                task_id,
                attempt_plan_state,
                str(pending_action.get("step_id") or "step"),
                str(pending_action.get("action_id") or "action"),
                "approved",
                approved_content,
                extension={"Python": ".py", "R": ".R"}.get(language, ".sh"),
                parent_script_ref=generated_ref,
                mutation_reason="user_approval_or_edit",
                producer="hitl_approval",
                root=attempt_dir,
            )
            record_provenance_event(attempt_plan_state, "attempt_state_changed", {
                "attempt_id": attempt_id,
                "status": ATTEMPT_SCRIPT_READY,
                "generated_script": generated_ref,
                "approved_script": approved_ref,
                "stdout_path": str(stdout_path),
                "stderr_path": str(stderr_path),
                "exit_status_path": str(exit_status_path),
                "runtime_env_manifest": manifest_refs.get(
                    "runtime_env_manifest.json", {}
                ),
                "artifact_env_manifest": manifest_refs.get(
                    "artifact_env_manifest.json", {}
                ),
                "execution_policy_manifest": manifest_refs.get(
                    "execution_policy_manifest.json", {}
                ),
                "action_approval_identity": deepcopy(current_approval_identity),
            })
            record_provenance_event(attempt_plan_state, "attempt_state_changed", {
                "attempt_id": attempt_id,
                "status": ATTEMPT_APPROVED,
            })
            approved_runner = (
                runtime_bindings.get("BASH_BIN") or "bash"
                if language == "Bash"
                else runtime_bindings.get("PYTHON_BIN") or sys.executable
                if language == "Python"
                else runtime_bindings.get("RSCRIPT_BIN")
                or runtime_bindings.get("R_BIN")
                or str(shutil.which("Rscript") or "Rscript")
            )
            approved_runner_argv = [str(approved_runner)]
            if language == "Bash" and bool(
                (current_policy_manifest.get("policy") or {}).get(
                    "shell_pipefail", True
                )
            ):
                approved_runner_argv.extend(["-o", "pipefail"])
            approved_runner_argv.append(str(approved_ref["path"]))
            if shim_path:
                base_path = str(effective_execution_env.get("PATH") or "")
                effective_execution_env["PATH"] = (
                    base_path + (os.pathsep if base_path else "") + str(shim_path)
                )
            status_tmp = f"{exit_status_path}.tmp.$$"
            wrapper_parts = [
                "#!/bin/bash\n",
                "set +e\n",
                f": > {shlex.quote(str(stdout_path))}\n",
                f": > {shlex.quote(str(stderr_path))}\n",
            ]
            wrapper_parts.append(
                f"printf 'runner=%s script=%s\\n' {shlex.quote(shlex.join(approved_runner_argv[:-1]))} "
                f"{shlex.quote(approved_ref['path'])} > {shlex.quote(trace_file)}\n"
            )
            wrapper_parts.extend([
                f"{shlex.join(approved_runner_argv)} "
                f"> {shlex.quote(str(stdout_path))} 2> {shlex.quote(str(stderr_path))}\n",
                "rc=$?\n",
            ])
            wrapper_parts.append(
                f"printf 'returncode=%s\\n' \"$rc\" >> {shlex.quote(trace_file)}\n"
            )
            wrapper_parts.extend([
                "finished_at=$(date -Iseconds 2>/dev/null || date)\n",
                f"printf '{{\"attempt_id\":\"{attempt_id}\",\"returncode\":%s,\"finished_at\":\"%s\"}}\\n' "
                f"\"$rc\" \"$finished_at\" > {shlex.quote(status_tmp)}\n",
                f"mv {shlex.quote(status_tmp)} {shlex.quote(str(exit_status_path))}\n",
                f"cat {shlex.quote(str(stdout_path))}\n",
                f"cat {shlex.quote(str(stderr_path))} >&2\n",
                "exit \"$rc\"\n",
            ])
            wrapper = "".join(wrapper_parts)
            executed_ref = self._persist_script_version(
                task_id,
                attempt_plan_state,
                str(pending_action.get("step_id") or "step"),
                str(pending_action.get("action_id") or "action"),
                "executed",
                wrapper,
                extension=".sh",
                parent_script_ref=approved_ref,
                mutation_reason="durable_execution_wrapper",
                producer="executor_wrapper",
                root=attempt_dir,
            )
            script_file = executed_ref["path"]
            record_provenance_event(attempt_plan_state, "attempt_state_changed", {
                "attempt_id": attempt_id,
                "status": ATTEMPT_STARTING,
                "executed_script": executed_ref,
                "executed_script_path": script_file,
                "started_at": started_at,
            })
            save_plan_state(self.data_path, task_id, attempt_plan_state)
            output.print_once(f"script:{script_file}", f"💾 Script: {script_file}", Fore.GREEN)

            execution_argv = ["bash", script_file]
            execution_command = f"bash {shlex.quote(script_file)}"
            recovery_dir = str(attempt_dir / "recovery")
            os.makedirs(recovery_dir, exist_ok=True)
            log_metadata_before: Dict[str, Dict[str, int]] = {}
            if ENABLE_ROOT_CAUSE_ANALYZER:
                try:
                    log_metadata_before = RootCauseAnalyzer().capture_log_metadata(
                        command=execution_command,
                        cwd=os.getcwd(),
                        generated_script_path=script_file,
                    )
                except Exception as exc:
                    logger.debug("Could not capture pre-run log metadata: %s", exc)

            async def persist_attempt_lifecycle(event: str, payload: Dict[str, Any]) -> None:
                lifecycle_state = load_plan_state(self.data_path, task_id)
                durable_failure = (
                    dict(lifecycle_state.get("failure") or {})
                    if isinstance(lifecycle_state.get("failure"), Mapping)
                    else {}
                )
                if (
                    event in {"RUNNING", "PROCESS_STARTED"}
                    and str(
                        durable_failure.get("stage")
                        or durable_failure.get("failure_stage")
                        or ""
                    ) == "pre_action_contract"
                ):
                    # A repaired candidate has crossed the real process boundary.
                    # Preserve the original violation identity, but prevent the
                    # no-execution guard from treating the resolved repair as a
                    # terminal pre-action failure.
                    durable_failure["execution_started"] = True
                    durable_failure["resolved_at"] = timestamp_now()
                    lifecycle_state["failure"] = durable_failure
                lifecycle_payload = {
                    "attempt_id": attempt_id,
                    "status": ATTEMPT_PROCESS_EXITED if event == "PROCESS_EXITED" else ATTEMPT_RUNNING,
                    "pid": payload.get("pid"),
                    "pgid": payload.get("pgid"),
                    "heartbeat_at": payload.get("heartbeat_at"),
                    "started_at": payload.get("started_at") or started_at,
                    "finished_at": payload.get("finished_at") or "",
                    "returncode": payload.get("returncode"),
                    "stdout_path": str(stdout_path),
                    "stderr_path": str(stderr_path),
                    "exit_status_path": str(exit_status_path),
                }
                record_provenance_event(lifecycle_state, "attempt_state_changed", lifecycle_payload)
                save_plan_state(self.data_path, task_id, lifecycle_state)

            try:
                preexec_approval_identity = build_action_approval_identity(
                    generated_script_sha256=str(
                        pending_action.get("generated_script_hash")
                        or pending_action.get("generated_script_sha256")
                        or ""
                    ),
                    capability_contract_hash_value=str(
                        pending_action.get("capability_contract_hash") or ""
                    ),
                    runtime_env_manifest_hash=str(
                        current_runtime_manifest.get("manifest_hash") or ""
                    ),
                    artifact_env_manifest_hash=str(
                        current_artifact_manifest.get("manifest_hash") or ""
                    ),
                    execution_policy_manifest_hash=str(
                        current_policy_manifest.get("manifest_hash") or ""
                    ),
                    working_directory=os.getcwd(),
                )
                validate_action_approval_identity(
                    current_approval_identity,
                    preexec_approval_identity,
                )
            except ActionRuntimeContractError as exc:
                return {
                    "messages": [SystemMessage(content=json.dumps(
                        exc.to_diagnostic(), ensure_ascii=False, sort_keys=True,
                    ))],
                    "pending_action": {},
                    "required_next_action": exc.code,
                    "failure_owner": RecoveryFailureOwner.INTERNAL_PROTOCOL.value,
                    "execution_started": False,
                    "next_step": "generate",
                }

            diagnostic_dispatch_envelope: Optional[
                RecoveryExecutionEnvelope
            ] = None
            if (
                command_role == "diagnostic"
                and pending_action.get("recovery_execution_envelope")
            ):
                diagnostic_dispatch_envelope = (
                    RecoveryExecutionEnvelope.from_mapping(
                        pending_action.get("recovery_execution_envelope")
                    )
                )
                dispatch_store = RecoveryStateStore(
                    self.data_path, task_id
                )
                dispatch_store.save_probe_lifecycle(
                    ProbeLifecycleRecord(
                        recovery_decision_id=(
                            diagnostic_dispatch_envelope.recovery_decision_id
                        ),
                        probe_id=str(
                            diagnostic_dispatch_envelope.probe_id or ""
                        ),
                        status=ProbeLifecycleStatus.DISPATCHED.value,
                        action_id=diagnostic_dispatch_envelope.action_id,
                        result_reference=attempt_id,
                    )
                )
                dispatch_store.append_trace(
                    "DIAGNOSTIC_ACTION_DISPATCHED",
                    {
                        "probe_id": diagnostic_dispatch_envelope.probe_id,
                        "action_id": diagnostic_dispatch_envelope.action_id,
                        "execution_attempt_id": attempt_id,
                    },
                )
            start_time = time.time()
            diagnostic_timed_out = False
            try:
                execution_call = run_script_path(
                        script_file,
                        expected_sha256=executed_ref["sha256"],
                        interpreter="bash",
                        lifecycle_callback=persist_attempt_lifecycle,
                        env=effective_execution_env,
                    )
                if diagnostic_dispatch_envelope is not None:
                    stdout, stderr, returncode = await asyncio.wait_for(
                        execution_call,
                        timeout=float(
                            diagnostic_dispatch_envelope
                            .scratch_capability.max_wall_seconds
                        ),
                    )
                else:
                    stdout, stderr, returncode = await execution_call
            except asyncio.TimeoutError:
                diagnostic_timed_out = True
                stdout, stderr, returncode = (
                    "",
                    "Diagnostic execution exceeded its Controller wall-time capability.",
                    124,
                )
            except Exception as e:
                stdout, stderr, returncode = "", str(e), 1

            duration = time.time() - start_time
            finished_at = datetime.now().isoformat(timespec="seconds")
            # A process may finish after the user, Consultant, or Planner has
            # replaced the authority under which its action was generated.
            # Keep the immutable runner/log evidence, but do not validate,
            # reconcile outputs, advance the plan, or charge a failure budget
            # for a result that no longer belongs to the current revisions.
            post_run_state = load_plan_state(self.data_path, task_id)
            stale_execution_fields = self._pending_action_revision_mismatches(
                pending_action,
                post_run_state,
            )
            post_run_pending = dict(
                (post_run_state.get("task_state") or {}).get(
                    "pending_action"
                ) or {}
            )
            if (
                post_run_pending
                and str(post_run_pending.get("action_id") or "")
                != str(pending_action.get("action_id") or "")
            ):
                stale_execution_fields["pending_action_identity"] = {
                    "bound": str(pending_action.get("action_id") or ""),
                    "current": str(post_run_pending.get("action_id") or ""),
                }
            if stale_execution_fields:
                stale_record = {
                    "decision_result": "STALE_EXECUTION_RESULT",
                    "counts_as_failure": False,
                    "consumes_execution_retry": False,
                    "action_id": str(pending_action.get("action_id") or ""),
                    "attempt_id": str(attempt_id or ""),
                    "step_id": str(pending_action.get("step_id") or ""),
                    "changed_preconditions": sorted(stale_execution_fields),
                    "revision_comparison": deepcopy(stale_execution_fields),
                    "returncode": int(returncode),
                    "started_at": str(started_at),
                    "finished_at": str(finished_at),
                    "duration_seconds": round(duration, 3),
                    "script_ref": deepcopy(dict(executed_ref or {})),
                    "stdout_log": str(stdout_path),
                    "stderr_log": str(stderr_path),
                    "exit_status_path": str(exit_status_path),
                    "trace_file": str(trace_file or ""),
                }
                stale_audit_persisted = False
                for _ in range(3):
                    latest = load_plan_state(self.data_path, task_id)
                    latest_mismatches = self._pending_action_revision_mismatches(
                        pending_action,
                        latest,
                    )
                    if latest_mismatches:
                        stale_record["changed_preconditions"] = sorted(
                            latest_mismatches
                        )
                        stale_record["revision_comparison"] = deepcopy(
                            latest_mismatches
                        )
                    latest_task_state = dict(latest.get("task_state") or {})
                    stale_history = [
                        deepcopy(dict(item))
                        for item in latest_task_state.get(
                            "stale_execution_results", []
                        ) or []
                        if isinstance(item, Mapping)
                    ]
                    stale_history.append(deepcopy(stale_record))
                    latest_task_state["stale_execution_results"] = stale_history[-20:]
                    durable_pending = dict(
                        latest_task_state.get("pending_action") or {}
                    )
                    if str(durable_pending.get("action_id") or "") == str(
                        pending_action.get("action_id") or ""
                    ):
                        latest_task_state["pending_action"] = {}
                    access = record_skill_access_event(
                        latest_task_state.get("skill_access_state")
                        or latest.get("skill_access_state"),
                        "stale_execution_result_discarded",
                        stale_record,
                    )
                    latest_task_state["skill_access_state"] = access
                    latest["task_state"] = latest_task_state
                    latest["skill_access_state"] = deepcopy(access)
                    try:
                        save_plan_state(self.data_path, task_id, latest)
                        post_run_state = latest
                        stale_audit_persisted = True
                        break
                    except StateCASConflict:
                        continue
                stale_record["audit_persisted"] = stale_audit_persisted
                changed = set(stale_record["changed_preconditions"])
                resume_node = (
                    "consultant"
                    if changed
                    & {"task_revision", "authoritative_user_turn_revision"}
                    else "planner"
                )
                return {
                    "messages": [SystemMessage(content=json.dumps(
                        stale_record,
                        ensure_ascii=False,
                        sort_keys=True,
                    ))],
                    "execution_result": deepcopy(stale_record),
                    "stale_execution_result": deepcopy(stale_record),
                    "plan_progress": render_plan_progress(post_run_state),
                    "next_step": resume_node,
                }
            expected_runtime_contract = {
                "status": "passed",
                "bindings": dict(runtime_bindings),
                "executables": {},
                "versions": {},
                "runtime_snapshot_digest": str(
                    current_runtime_manifest.get("manifest_hash") or ""
                ),
            }
            actual_runtime_environment: Dict[str, Any] = {
                **{
                    key: value
                    for key, value in runtime_bindings.items()
                    if key in {
                        "CONDA_DEFAULT_ENV", "CONDA_EXE", "CONDA_PREFIX",
                        "ENV_PREFIX", "JAVA_HOME", "VIRTUAL_ENV",
                    }
                },
                "injected_bindings": dict(runtime_bindings),
                "resolved_executables": _observed_runtime_executables(
                    expected_runtime_contract,
                    runtime_bindings,
                    approved_source_code,
                    language,
                    str(approved_runner),
                    shim_path=str(shim_path or ""),
                ),
            }
            runtime_machine_comparison = compare_runtime_machine_evidence(
                expected_runtime_contract,
                actual_runtime_environment,
            )
            immediate_failure_evidence_path = ""

            def persist_immediate_failure_snapshot(
                diagnostic_code: str,
                diagnostic_summary: str,
            ) -> None:
                nonlocal immediate_failure_evidence_path
                if immediate_failure_evidence_path:
                    return
                snapshot = AttemptFailureEvidence.from_mapping({
                    "session_id": str(state.get("session_id") or task_id),
                    "task_id": task_id,
                    "plan_id": str(attempt_plan_state.get("plan_id") or ""),
                    "plan_version": str(
                        attempt_plan_state.get("plan_version") or "plan_v1"
                    ),
                    "step_id": str(pending_action.get("step_id") or ""),
                    "action_id": str(pending_action.get("action_id") or ""),
                    "attempt_id": attempt_id,
                    "failed_command": execution_command,
                    "returncode": returncode,
                    "stdout_log": str(stdout_path),
                    "stderr_log": str(stderr_path),
                    "trace_file": trace_file,
                    "stdout_summary": self._clip_observation_text(stdout, 8000),
                    "stderr_summary": self._clip_observation_text(stderr, 8000),
                    "expected_runtime_contract": expected_runtime_contract,
                    "actual_environment": actual_runtime_environment,
                    "machine_audit_findings": list(
                        runtime_machine_comparison.get("machine_audit_findings")
                        or []
                    ),
                    "diagnostic_code": diagnostic_code,
                    "diagnostic_summary": diagnostic_summary,
                })
                immediate_failure_evidence_path = str(
                    RecoveryStateStore(
                        self.data_path, task_id
                    ).save_attempt_failure_evidence(snapshot)
                )

            if returncode != 0:
                persist_immediate_failure_snapshot(
                    "PROCESS_EXIT_NONZERO",
                    f"The executed process exited with return code {returncode}.",
                )
            self.profiler.record_skill_usage(
                task_id,
                runtime_skills_state,
                usage_type="executed",
                node="execute",
                detail=script_file,
            )
            if diagnostic_dispatch_envelope is not None:
                validation_result = {
                    "passed": returncode == 0 and not diagnostic_timed_out,
                    "status": (
                        "timed_out"
                        if diagnostic_timed_out
                        else "succeeded"
                        if returncode == 0
                        else "failed"
                    ),
                    "result_contract": (
                        RecoveryResultContract.DIAGNOSTIC_EVIDENCE.value
                    ),
                    "completion_eligible": False,
                    "errors": (
                        []
                        if returncode == 0 and not diagnostic_timed_out
                        else [
                            "Diagnostic process did not complete successfully; "
                            "its typed evidence remains available to Recovery."
                        ]
                    ),
                }
                validation_block = (
                    '\n<validation_result level="diagnostic" '
                    f'status="{validation_result["status"]}">\n'
                    "Diagnostic evidence contract evaluated; formal output "
                    "coverage and CompletionGate are ineligible.\n"
                    "</validation_result>"
                )
                validation_level = "diagnostic_evidence"
            else:
                validation_result, validation_block, validation_level = self._validate_execution_result(
                    state,
                    code_to_run,
                    stdout,
                    stderr,
                    returncode,
                )
            managed_output_snapshot_after = capture_managed_output_snapshot(
                managed_output_contracts
            )
            observed_candidate_records = discover_current_attempt_outputs(
                managed_output_snapshot_before,
                managed_output_snapshot_after,
                attempt_id=attempt_id,
            )
            runtime_output_reconciliation = reconcile_runtime_outputs(
                managed_output_contracts,
                observed_candidate_records,
                attempt_id=attempt_id,
                exit_code=returncode,
            )
            if runtime_output_reconciliation.get("status") == "recovery":
                validation_result = dict(validation_result or {})
                validation_result["passed"] = False
                validation_result["output_reconciliation"] = runtime_output_reconciliation
                validation_result["errors"] = list(dict.fromkeys([
                    *list(validation_result.get("errors") or []),
                    *[
                        str(item.get("code") or "OUTPUT_RECONCILIATION_FAILED")
                        + ": "
                        + str(item.get("message") or "runtime output reconciliation failed")
                        for item in runtime_output_reconciliation.get("violations", []) or []
                        if isinstance(item, Mapping)
                    ],
                ]))
                validation_block += (
                    "\nRUNTIME_OUTPUT_RECONCILIATION:\n"
                    + json.dumps(
                        runtime_output_reconciliation,
                        ensure_ascii=False,
                        sort_keys=True,
                        default=str,
                    )[:6000]
                    + "\n"
                )
                validation_level = "runtime_output_reconciliation"
            validation_failed = bool(validation_result and not validation_result.get("passed", True))
            benign_nonzero_preview = bool(
                validation_result
                and validation_result.get("benign_nonzero_readonly_preview")
            )
            effective_success = returncode == 0 or benign_nonzero_preview
            runtime_install_redirect, runtime_skills_after_execute = self._runtime_install_redirect_from_execution(
                code_to_run,
                stdout,
                stderr,
                runtime_skills_state,
                task_id,
            )
            runtime_missing = bool(runtime_install_redirect)
            runtime_install_blocked = bool(runtime_missing and install_disallowed)
            task_mode = str(state.get("task_mode") or "").strip().lower()
            lightweight_mode = task_mode in {"readonly", "simple_execute"}
            if runtime_missing and lightweight_mode:
                runtime_install_blocked = True
            if (validation_failed or runtime_missing) and not immediate_failure_evidence_path:
                persist_immediate_failure_snapshot(
                    "RUNTIME_MISSING" if runtime_missing else "VALIDATION_FAILED",
                    (
                        "The process completed but the required runtime was unavailable."
                        if runtime_missing
                        else "The process completed but required validation failed."
                    ),
                )
            retry_plan = load_plan_state(self.data_path, task_id)
            retry_count = int(
                ((retry_plan.get("task_state") or {}).get("budgets") or {}).get("execution_retry_count")
                or 0
            )

            # 持久化
            if self.state_manager:
                self.state_manager.save_execution(task_id, step_index, code_to_run, language,
                                                  stdout, stderr, returncode, duration)
                if returncode == 0 and not validation_failed and not runtime_missing:
                    self._auto_save_results(task_id, step_index, code_to_run, stdout)
                    self._record_successful_skill_execution(
                        runtime_skills_state,
                        code_to_run,
                        stdout,
                    )

            runtime_status_block = self._format_runtime_status_for_observation(task_id, runtime_skills_state)
            stdout_obs = self._clip_observation_text(stdout, 2000)
            stderr_obs = self._clip_observation_text(stderr, 1000)
            if runtime_missing:
                obs = (f"<observation>\n[{language}] ❌ Runtime missing ({duration:.1f}s)\n"
                       f"STDOUT:\n{stdout_obs}\n"
                       f"STDERR:\n{stderr_obs}"
                       f"{validation_block}"
                       f"{runtime_status_block}\n</observation>")
            elif effective_success and not validation_failed:
                obs = (f"<observation>\n[{language}] ✅ Success ({duration:.1f}s)\n"
                       f"STDOUT:\n{stdout_obs}\n"
                       f"STDERR:\n{stderr_obs}"
                       f"{validation_block}"
                       f"{runtime_status_block}\n</observation>")
            elif effective_success and validation_failed:
                obs = (f"<observation>\n[{language}] ❌ Failed validation ({duration:.1f}s)\n"
                       f"STDOUT:\n{stdout_obs}\n"
                       f"STDERR:\n{stderr_obs}"
                       f"{validation_block}"
                       f"{runtime_status_block}\n</observation>")
            else:
                obs = (f"<observation>\n[{language}] ❌ Failed ({duration:.1f}s)\n"
                       f"STDOUT:\n{stdout_obs}\n"
                       f"STDERR:\n{stderr_obs}"
                       f"{validation_block}"
                       f"{runtime_status_block}\n</observation>")

            output.print_observation(obs)
            if runtime_install_blocked:
                final_res = self._runtime_block_message(
                    runtime_install_redirect,
                    runtime_skills_after_execute,
                    stderr or stdout or runtime_install_redirect,
                )
                if lightweight_mode:
                    plan_progress = self._record_plan_current_evidence(
                        task_id,
                        "lightweight_runtime_missing_no_install",
                        final_res[:1000],
                    )
                else:
                    plan_progress = self._mark_plan_current_blocked(task_id, final_res)
            elif runtime_missing:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "runtime_missing_after_execute",
                    f"{script_file}\n{runtime_install_redirect[:1000]}",
                )
            elif bypass_step_gate:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "diagnostic_observation" if command_role != "recovery" else "recovery_observation",
                    (
                        f"{script_file}\nreturncode={returncode}\n"
                        f"STDOUT:\n{self._clip_observation_text(stdout, 1000)}\n"
                        f"STDERR:\n{self._clip_observation_text(stderr, 1000)}"
                    ),
                )
            elif returncode == 0 and not validation_failed:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "execute_success",
                    (
                        f"{script_file}\n"
                        f"STDOUT:\n{self._clip_observation_text(stdout, 1000)}\n"
                        f"STDERR:\n{self._clip_observation_text(stderr, 1000)}"
                    ),
                )
            else:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "execute_failed",
                    f"{script_file}\nSTDOUT:\n{self._clip_observation_text(stdout, 1000)}\nSTDERR:\n{self._clip_observation_text(stderr, 1000)}",
                )
            await self._observe_session_memory(
                task_id,
                "execute",
                state.get("messages", []) + [HumanMessage(content=obs)],
                {
                    "script_file": script_file,
                    "language": language,
                    "returncode": returncode,
                    "duration_seconds": round(duration, 3),
                    "stdout": stdout[:3000],
                    "stderr": stderr[:1500],
                    "validation_level": validation_level,
                    "validation": validation_result,
                    "plan_progress": plan_progress,
                },
            )
            trace_text = ""
            if trace_file:
                try:
                    trace_text = Path(trace_file).read_text(encoding="utf-8", errors="replace")
                except OSError:
                    trace_text = ""
            pipeline_statuses = None
            status_match = re.search(r"PIPESTATUS=\(([^)]*)\)", trace_text)
            if status_match:
                try:
                    pipeline_statuses = [int(item) for item in re.findall(r"-?\d+", status_match.group(1))]
                except ValueError:
                    pipeline_statuses = None
            root_cause_analysis: Dict[str, Any] = {}
            command_chain: Dict[str, Any] = {}
            if ENABLE_ROOT_CAUSE_ANALYZER:
                try:
                    analysis = await asyncio.wait_for(
                        asyncio.to_thread(
                            RootCauseAnalyzer().analyze,
                            command=execution_command,
                            argv=execution_argv,
                            cwd=os.getcwd(),
                            environment_name=str((state.get("runtime_status") or {}).get("env") or "") or None,
                            exit_code=returncode,
                            signal=-returncode if returncode < 0 else None,
                            stdout=stdout,
                            stderr=stderr,
                            generated_script_path=script_file,
                            trace_text=trace_text,
                            pipeline_statuses=pipeline_statuses,
                            stage_status=state.get("plan_progress"),
                            log_metadata_before=log_metadata_before,
                        ),
                        timeout=ROOT_CAUSE_TIMEOUT_SECONDS,
                    )
                    root_cause_analysis = analysis.llm_view()
                    full_chain = analysis.command_chain.to_dict()
                    command_chain = {
                        "root_node_id": full_chain.get("root_node_id"),
                        "confirmed_failed_node_id": full_chain.get("confirmed_failed_node_id"),
                        "candidate_failed_node_ids": full_chain.get("candidate_failed_node_ids", [])[:12],
                        "chain_confidence": full_chain.get("chain_confidence"),
                        "extraction_warnings": full_chain.get("extraction_warnings", [])[:12],
                    }
                    RootCauseAnalyzer.persist(analysis, recovery_dir)
                except asyncio.TimeoutError:
                    root_cause_analysis = {
                        "status": "diagnostic_timeout",
                        "root_cause_summary": (
                            "Root-cause post-processing exceeded its bounded diagnostic timeout; "
                            "raw execution evidence remains authoritative."
                        ),
                        "root_cause_confidence": 0.0,
                        "evidence": [f"timeout_seconds={ROOT_CAUSE_TIMEOUT_SECONDS}"],
                    }
                    logger.warning(
                        "RootCauseAnalyzer timed out after %.1fs; continuing to Supervisor with raw evidence.",
                        ROOT_CAUSE_TIMEOUT_SECONDS,
                    )
                except Exception as exc:
                    logger.warning("RootCauseAnalyzer failed; keeping raw execution evidence: %s", exc)
            execution_plan_state = load_plan_state(self.data_path, task_id)
            execution_step = self._running_plan_step(execution_plan_state) or {}
            execution_contracts = managed_output_contracts or step_artifact_contracts(execution_step)
            declared_outputs = [
                str(item.get("expected_path") or item.get("path") or "")
                for item in execution_contracts
                if str(item.get("expected_path") or item.get("path") or "").strip()
            ]
            if not declared_outputs:
                declared_outputs = [
                    str(item) for item in execution_step.get("outputs", []) or [] if str(item).strip()
                ]
            observed_outputs = [
                str(item.get("path") or "")
                for item in observed_candidate_records
                if str(item.get("path") or "")
            ]
            reconciled_outputs = [
                dict(item)
                for item in runtime_output_reconciliation.get("bindings", []) or []
                if isinstance(item, Mapping)
            ]
            produced_artifacts = [
                str(item.get("observed_path") or "")
                for item in reconciled_outputs
                if str(item.get("observed_path") or "")
            ]
            execution_failure_fingerprint = str(
                (root_cause_analysis or {}).get("inner_fingerprint")
                or (root_cause_analysis or {}).get("failure_fingerprint")
                or ""
            )
            if not execution_failure_fingerprint and (returncode != 0 or validation_failed):
                fingerprint_text = json.dumps({
                    "command": execution_command,
                    "returncode": returncode,
                    "stderr": stderr[-4000:],
                    "stdout": stdout[-4000:],
                    "output_reconciliation": runtime_output_reconciliation.get("fingerprint") or "",
                    "observed_outputs": sorted(observed_outputs),
                }, ensure_ascii=False, sort_keys=True, default=str)
                execution_failure_fingerprint = hashlib.sha256(
                    fingerprint_text.encode("utf-8", errors="replace")
                ).hexdigest()[:20]
            execution_evidence = {
                "execution_id": f"exec-{str(attempt_record.get('attempt_id') or pending_action.get('action_id') or Path(script_file or 'execute').stem)}",
                "plan_id": str(execution_plan_state.get("plan_id") or ""),
                "action_id": str(pending_action.get("action_id") or ""),
                "execution_status": (
                    "succeeded" if effective_success and not runtime_missing else "failed"
                ),
                "process_status": "succeeded" if returncode == 0 else "failed",
                "purpose": declared_purpose,
                "result_contract": str(
                    pending_action.get("result_contract") or ""
                ),
                "execution_mode": str(
                    pending_action.get("execution_mode") or ""
                ),
                "recovery_decision_id": str(
                    pending_action.get("recovery_decision_id") or ""
                ),
                "recovery_context_id": str(
                    pending_action.get("recovery_context_id") or ""
                ),
                "probe_id": str(pending_action.get("probe_id") or ""),
                "recovery_execution_envelope": deepcopy(
                    pending_action.get("recovery_execution_envelope") or {}
                ),
                "attempt_id": str(attempt_record.get("attempt_id") or ""),
                "command_role": command_role,
                "action_kind": str(pending_action.get("action_kind") or pending_action.get("kind") or ""),
                "action_source": str(pending_action.get("action_source") or "generate"),
                "renderer_id": str(pending_action.get("renderer_id") or ""),
                "manifest_path": str(pending_action.get("manifest_path") or ""),
                "manifest_id": str(pending_action.get("manifest_id") or attempt_record.get("manifest_id") or ""),
                "stage_id": str(pending_action.get("stage_id") or attempt_record.get("stage_id") or ""),
                "manifest_fingerprint": str(pending_action.get("manifest_fingerprint") or ""),
                "manifest_action_id": str(pending_action.get("manifest_action_id") or ""),
                "manifest_script_hash": str(pending_action.get("manifest_script_hash") or ""),
                "success_checks": list(pending_action.get("success_checks") or []),
                "command": execution_command,
                "code": code_to_run,
                "generated_code": generated_model_code,
                "code_path": approved_ref["path"],
                "argv": execution_argv,
                "script_file": script_file,
                "generated_script_path": str(generated_ref.get("path") or ""),
                "generated_script": generated_ref,
                "approved_script": approved_ref,
                "executed_script": executed_ref,
                "cwd": os.getcwd(),
                "started_at": started_at,
                "finished_at": finished_at,
                "duration_seconds": round(duration, 3),
                "stdout": stdout,
                "stderr": stderr,
                "returncode": returncode,
                "signal": -returncode if returncode < 0 else None,
                "language": language,
                "validation": validation_result,
                "trace_file": trace_file or None,
                "trace_text": trace_text,
                "pipeline_statuses": pipeline_statuses,
                "log_metadata_before": log_metadata_before,
                "executor_metadata": get_last_execution_metadata(),
                "root_cause_analysis": root_cause_analysis,
                "command_chain": command_chain,
                "plan_version": str(execution_plan_state.get("plan_version") or "plan_v1"),
                "task_revision": self._task_revision_for_state(dict(state)),
                "step_id": str(execution_step.get("step_id") or ""),
                "attempt": len(state.get("recovery_attempts", []) or []) + 1,
                "declared_outputs": declared_outputs,
                "observed_outputs": observed_outputs,
                "produced_artifacts": produced_artifacts,
                "observed_output_records": observed_candidate_records,
                "runtime_output_reconciliation": runtime_output_reconciliation,
                "reconciled_outputs": reconciled_outputs,
                "output_reconciliation_status": str(
                    runtime_output_reconciliation.get("status") or "not_required"
                ),
                "failure_code": str(
                    ((runtime_output_reconciliation.get("violations") or [{}])[0]).get("code")
                    if runtime_output_reconciliation.get("violations")
                    else ""
                ),
                "fallback_used": command_role == "fallback" or bool(pending_action.get("fallback_used")),
                "retry_count_recorded": bool(
                    command_role == "primary"
                    and (not effective_success or validation_failed or runtime_missing)
                ),
                "failure_fingerprint": execution_failure_fingerprint,
                "stdout_log": str(stdout_path),
                "stderr_log": str(stderr_path),
                "exit_status_path": str(exit_status_path),
                "stdout_summary": self._clip_observation_text(stdout, 2000),
                "stderr_summary": self._clip_observation_text(stderr, 2000),
                "expected_runtime_contract": deepcopy(expected_runtime_contract),
                "actual_environment": deepcopy(actual_runtime_environment),
                "action_contract": {
                    key: value for key, value in pending_action.items()
                    if key not in {"code", "command", "messages"}
                },
            }
            if immediate_failure_evidence_path:
                execution_evidence["failure_evidence_path"] = (
                    immediate_failure_evidence_path
                )
            executor_metadata = dict(execution_evidence.get("executor_metadata") or {})
            if executor_metadata.get("stdout_log"):
                execution_evidence["executor_stdout_log"] = str(executor_metadata["stdout_log"])
            if executor_metadata.get("stderr_log"):
                execution_evidence["executor_stderr_log"] = str(executor_metadata["stderr_log"])
            recovery_store = RecoveryStateStore(self.data_path, task_id)
            try:
                prior_records = recovery_store.load_execution_records()
            except Exception as exc:
                logger.warning(
                    "Could not load prior execution records for %s: %s",
                    task_id,
                    exc,
                )
                prior_records = []
            execution_evidence["recent_attempts"] = [
                {
                    "execution_id": str(item.get("execution_id") or ""),
                    "step_id": str(item.get("step_id") or ""),
                    "action_id": str(item.get("action_id") or ""),
                    "action_kind": str(item.get("action_kind") or ""),
                    "command_role": str(item.get("command_role") or ""),
                    "exit_code": item.get("exit_code"),
                    "failure_fingerprint": str(item.get("failure_fingerprint") or ""),
                }
                for item in prior_records[-3:]
            ]
            execution_evidence = enrich_execution_evidence(
                {**dict(state), "pending_action": pending_action},
                execution_evidence,
            )
            pre_evidence_commit_state = load_plan_state(
                self.data_path, task_id
            )
            pre_evidence_mismatches = (
                self._pending_action_revision_mismatches(
                    pending_action,
                    pre_evidence_commit_state,
                )
            )
            durable_successor = dict(
                (pre_evidence_commit_state.get("task_state") or {}).get(
                    "pending_action"
                ) or {}
            )
            if (
                durable_successor
                and str(durable_successor.get("action_id") or "")
                != str(pending_action.get("action_id") or "")
            ):
                pre_evidence_mismatches["pending_action_identity"] = {
                    "bound": str(pending_action.get("action_id") or ""),
                    "current": str(
                        durable_successor.get("action_id") or ""
                    ),
                }
            if pre_evidence_mismatches:
                stale_update = stale_pending_action_update(
                    pending_action,
                    pre_evidence_mismatches,
                    phase="before_execution_evidence_commit",
                )
                stale_update["stale_execution_result"] = {
                    **deepcopy(dict(
                        stale_update.get("execution_result") or {}
                    )),
                    "returncode": int(returncode),
                    "stdout_log": str(stdout_path),
                    "stderr_log": str(stderr_path),
                    "exit_status_path": str(exit_status_path),
                    "finished_at": str(finished_at),
                }
                return stale_update
            if returncode != 0 or validation_failed or runtime_missing:
                failure_snapshot = AttemptFailureEvidence.from_mapping({
                    **execution_evidence,
                    "session_id": str(state.get("session_id") or task_id),
                    "task_id": task_id,
                    "machine_audit_findings": list(
                        (execution_evidence.get("runtime_drift") or {}).get(
                            "machine_audit_findings"
                        )
                        or []
                    ),
                    "diagnostic_code": str(
                        execution_evidence.get("failure_code")
                        or (root_cause_analysis or {}).get("status")
                        or "EXECUTION_FAILED"
                    ),
                    "diagnostic_summary": str(
                        (root_cause_analysis or {}).get("root_cause_summary")
                        or "Execution or validation failed; immutable evidence was captured."
                    ),
                })
                # Failure evidence is a mandatory precondition for Recovery.
                # Do not swallow an identity conflict or write failure and then
                # ask a model to diagnose from a lossy graph-state projection.
                failure_path = recovery_store.save_attempt_failure_evidence(
                    failure_snapshot
                )
                execution_evidence["failure_evidence_path"] = str(failure_path)
            try:
                record = ExecutionRecord.from_mapping(execution_evidence)
                execution_record_path = recovery_store.save_execution_record(record)
                execution_evidence["execution_record_path"] = str(
                    execution_record_path
                )
                provenance_plan = load_plan_state(self.data_path, task_id)
                provenance_mismatches = (
                    self._pending_action_revision_mismatches(
                        pending_action,
                        provenance_plan,
                    )
                )
                provenance_successor = dict(
                    (provenance_plan.get("task_state") or {}).get(
                        "pending_action"
                    ) or {}
                )
                if (
                    provenance_successor
                    and str(provenance_successor.get("action_id") or "")
                    != str(pending_action.get("action_id") or "")
                ):
                    provenance_mismatches["pending_action_identity"] = {
                        "bound": str(
                            pending_action.get("action_id") or ""
                        ),
                        "current": str(
                            provenance_successor.get("action_id") or ""
                        ),
                    }
                if provenance_mismatches:
                    stale_update = stale_pending_action_update(
                        pending_action,
                        provenance_mismatches,
                        phase="before_execution_provenance_commit",
                    )
                    stale_update["stale_execution_result"] = {
                        **deepcopy(dict(
                            stale_update.get("execution_result") or {}
                        )),
                        "returncode": int(returncode),
                        "stdout_log": str(stdout_path),
                        "stderr_log": str(stderr_path),
                        "exit_status_path": str(exit_status_path),
                        "execution_record_path": str(
                            execution_record_path
                        ),
                        "finished_at": str(finished_at),
                    }
                    return stale_update
                runtime_artifact_failure = record_runtime_output_failure(
                    provenance_plan,
                    runtime_output_reconciliation,
                    step_id=str(execution_step.get("step_id") or ""),
                    attempt_id=record.attempt_id,
                    command_role=command_role,
                )
                provenance_result = record_provenance_event(provenance_plan, "execution_finished", {
                    "attempt_id": record.attempt_id,
                    "execution_record": {**execution_evidence, **record.summary()},
                })
                record.produced_artifact_ids = list(provenance_result.get("produced_artifact_ids") or [])
                if runtime_artifact_failure:
                    execution_evidence["typed_failure"] = runtime_artifact_failure
                recovery_store.save_execution_record(record)
                provenance_task_state = dict(provenance_plan.get("task_state") or {})
                durable_pending = dict(
                    provenance_task_state.get("pending_action") or {}
                )
                if str(durable_pending.get("action_id") or "") == str(
                    pending_action.get("action_id") or ""
                ):
                    provenance_task_state["pending_action"] = {}
                provenance_plan["task_state"] = provenance_task_state
                save_plan_state(self.data_path, task_id, provenance_plan)
                logger.info(
                    "Execution provenance: task=%s plan=%s step=%s stage=%s action=%s attempt=%s role=%s artifacts=%s source=%s",
                    task_id,
                    record.plan_id,
                    record.step_id,
                    record.stage_id,
                    record.action_id,
                    record.attempt_id,
                    record.command_role,
                    ",".join(record.produced_artifact_ids) or "none",
                    str(pending_action.get("action_source") or "unknown"),
                )
                execution_evidence.update(record.summary())
                # Keep executor-facing aliases while the graph state migrates.
                execution_evidence["returncode"] = record.exit_code
                execution_evidence["script_file"] = record.script_path
                execution_evidence["cwd"] = record.working_directory
            except Exception as exc:
                logger.warning("Could not persist execution record for %s: %s", task_id, exc)
            execution_evidence["failure_log_projection"] = failure_log_projection(
                "\n".join([stderr, stdout]),
                log_path=str(execution_evidence.get("stderr_log") or execution_evidence.get("stdout_log") or ""),
            )
            execution_evidence["generated_code"] = self._clip_observation_text(
                generated_model_code,
                4000,
            )
            diagnostic_evidence_record: Dict[str, Any] = {}
            if diagnostic_dispatch_envelope is not None:
                scratch_metadata = collect_diagnostic_scratch_metadata(
                    diagnostic_dispatch_envelope.scratch_capability
                )
                typed_diagnostic = DiagnosticEvidenceRecord.from_execution(
                    execution_evidence,
                    diagnostic_dispatch_envelope,
                    timed_out=diagnostic_timed_out,
                    scratch_artifact_metadata=scratch_metadata,
                )
                diagnostic_store = RecoveryStateStore(
                    self.data_path, task_id
                )
                persisted_diagnostic = (
                    diagnostic_store.save_diagnostic_evidence(
                        typed_diagnostic
                    )
                )
                diagnostic_evidence_record = dict(
                    persisted_diagnostic.get("record") or {}
                )
                lifecycle_status = (
                    ProbeLifecycleStatus.SUCCEEDED.value
                    if typed_diagnostic.status
                    == DiagnosticEvidenceStatus.SUCCEEDED.value
                    else ProbeLifecycleStatus.FAILED.value
                )
                diagnostic_store.save_probe_lifecycle(
                    ProbeLifecycleRecord(
                        recovery_decision_id=(
                            diagnostic_dispatch_envelope.recovery_decision_id
                        ),
                        probe_id=str(
                            diagnostic_dispatch_envelope.probe_id or ""
                        ),
                        status=lifecycle_status,
                        action_id=diagnostic_dispatch_envelope.action_id,
                        evidence_fingerprint=(
                            typed_diagnostic.evidence_fingerprint
                        ),
                        result_reference=str(
                            persisted_diagnostic.get("path") or ""
                        ),
                    )
                )
                diagnostic_store.append_trace(
                    "DIAGNOSTIC_EVIDENCE_RECORDED",
                    {
                        **diagnostic_evidence_record,
                        "deduplicated": not bool(
                            persisted_diagnostic.get("created")
                        ),
                    },
                )
                execution_evidence["diagnostic_evidence"] = (
                    diagnostic_evidence_record
                )
            # Raw streams are durable files. Keep only a bounded current-step
            # projection in graph state so one failed build cannot inflate all
            # downstream prompts and checkpoints.
            execution_evidence.pop("stdout", None)
            execution_evidence.pop("stderr", None)
            execution_evidence.pop("trace_text", None)
            execution_evidence.pop("code", None)
            conflict_update = self._knowledge_conflict_update(
                task_id,
                {
                    **dict(state),
                    "execution_evidence": execution_evidence,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                },
                phase="after_execute",
            )
            if bypass_step_gate:
                return {
                    **conflict_update,
                    "messages": [HumanMessage(content=obs)],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                    "execution_evidence": execution_evidence,
                    "diagnostic_evidence": diagnostic_evidence_record,
                    "root_cause_analysis": execution_evidence.get("root_cause_analysis", {}),
                    "command_chain": execution_evidence.get("command_chain", {}),
                    "pending_action": {},
                    "pending_recovery_action": {},
                    "required_next_action": (
                        "RECOVERY_REASSESS_DIAGNOSTIC_EVIDENCE"
                        if command_role in {"diagnostic", "optional_probe"}
                        else "SAME_STEP_GENERATE"
                    ),
                    "failure_owner": (
                        RecoveryFailureOwner.SCRIPT.value
                        if command_role == "recovery"
                        else RecoveryFailureOwner.DIAGNOSTIC.value
                    ),
                    "recovery_scope": "CURRENT_STEP",
                    "recovery_phase": "diagnose",
                    "supervisor_verdict": "",
                    "completion_gate_result": {},
                    "retry_count": retry_count,
                    "next_step": (
                        "supervisor"
                        if command_role in {"diagnostic", "optional_probe"}
                        else "generate"
                    ),
                }
            if runtime_install_blocked:
                if lightweight_mode:
                    await self._finalize_task_memory(
                        task_id,
                        "failed",
                        state.get("messages", []) + [HumanMessage(content=obs), AIMessage(content=f"<observation>{final_res}</observation>")],
                        {
                            "task_mode": task_mode,
                            "reason": final_res[:2000],
                            "plan_progress": plan_progress,
                        },
                    )
                return {
                    **conflict_update,
                    "messages": [HumanMessage(content=obs), AIMessage(content=f"<observation>{final_res}</observation>")],
                    "plan_progress": plan_progress,
                    "selected_skills": state.get("selected_skills", []) or runtime_skills_after_execute,
                    "active_skills": runtime_skills_after_execute,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_after_execute),
                    "execution_evidence": execution_evidence,
                    "root_cause_analysis": execution_evidence.get("root_cause_analysis", {}),
                    "command_chain": execution_evidence.get("command_chain", {}),
                    "retry_count": retry_count,
                    "failure_owner": RecoveryFailureOwner.DEPENDENCY.value,
                    "next_step": "finish" if lightweight_mode else self._next_step_after_runtime_block(task_id),
                }
            if runtime_missing:
                return {
                    **conflict_update,
                    "messages": [HumanMessage(content=obs), AIMessage(content=runtime_install_redirect)],
                    "plan_progress": plan_progress,
                    "selected_skills": state.get("selected_skills", []) or runtime_skills_after_execute,
                    "active_skills": runtime_skills_after_execute,
                    "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_after_execute),
                    "execution_evidence": execution_evidence,
                    "root_cause_analysis": execution_evidence.get("root_cause_analysis", {}),
                    "command_chain": execution_evidence.get("command_chain", {}),
                    "retry_count": retry_count,
                    "failure_owner": RecoveryFailureOwner.DEPENDENCY.value,
                    "next_step": "install_subagent",
                }
            if task_mode in {"readonly", "simple_execute"}:
                await self._finalize_task_memory(
                    task_id,
                    "completed" if returncode == 0 and not validation_failed else "failed",
                    state.get("messages", []) + [HumanMessage(content=obs)],
                    {
                        "task_mode": task_mode,
                        "script_file": script_file,
                        "returncode": returncode,
                        "validation_level": validation_level,
                        "validation": validation_result,
                    },
                )
            return {
                **conflict_update,
                "messages": [HumanMessage(content=obs)],
                "plan_progress": plan_progress,
                "runtime_status": self._runtime_status_for_task(task_id, runtime_skills_state),
                "execution_evidence": execution_evidence,
                "root_cause_analysis": execution_evidence.get("root_cause_analysis", {}),
                "command_chain": execution_evidence.get("command_chain", {}),
                "pending_recovery_action": {},
                "required_next_action": "",
                "recovery_scope": "",
                "recovery_phase": "",
                "supervisor_verdict": "",
                "retry_count": retry_count,
                "next_step": "finish" if task_mode in {"readonly", "simple_execute"} else "supervisor",
            }

        execute_node = error_recovery_middleware(
            self.recovery_llm,
            self.retriever,
            skill_manager=self.skill_manager,
            data_path=self.data_path,
            recovery_llm_policy=self.recovery_llm_policy,
        )(execute_logic)

        # ════════════════════════════════════════════
        # Node 4: Supervisor（新节点）
        # ════════════════════════════════════════════
        async def supervisor(state: AgentState):
            """Controller adapter for fact-only Supervisor validation."""
            output.print_node_header("supervisor")
            task_id = state.get("task_id", "default")
            durable_plan = load_plan_state(self.data_path, task_id)
            durable_failure = (
                dict(durable_plan.get("failure") or {})
                if isinstance(durable_plan.get("failure"), Mapping)
                else {}
            )
            durable_failure_stage = str(
                durable_failure.get("stage")
                or durable_failure.get("failure_stage")
                or ""
            )
            if (
                durable_failure_stage == "pre_action_contract"
                and durable_failure.get("execution_started") is False
            ):
                guarded_update = await self.supervisor_node.run({
                    **dict(state),
                    "failure": durable_failure,
                    "primary_failure": durable_failure,
                    "termination_reason": str(
                        durable_failure.get("termination_reason")
                        or state.get("termination_reason")
                        or ""
                    ),
                    "execution_started": False,
                })
                guarded_update["plan_progress"] = render_plan_progress(durable_plan)
                await self._observe_session_memory(
                    task_id,
                    "supervisor",
                    state.get("messages", []) + list(guarded_update.get("messages") or []),
                    {
                        "pre_action_terminal": True,
                        "error_code": str(durable_failure.get("error_code") or ""),
                        "termination_reason": str(durable_failure.get("termination_reason") or ""),
                        "execution_started": False,
                    },
                )
                return guarded_update
            conflict_update = self._knowledge_conflict_update(
                task_id,
                dict(state),
                phase="before_supervisor",
            )
            supervisor_state = {**dict(state), **conflict_update}
            durable_failure_projection: Dict[str, Any] = {}
            if durable_failure:
                supervisor_state["failure"] = durable_failure
                supervisor_state["primary_failure"] = durable_failure
                supervisor_state["execution_started"] = durable_failure.get("execution_started")
                durable_failure_projection = {
                    "failure": durable_failure,
                    "primary_failure": durable_failure,
                    "execution_started": durable_failure.get("execution_started"),
                }
            raw_update = await self.supervisor_node.run(supervisor_state)
            update = {
                **conflict_update,
                **durable_failure_projection,
                **(raw_update if isinstance(raw_update, dict) else {}),
            }
            execution = dict(state.get("execution_evidence") or {})
            validation = ValidationEvidence.from_mapping(update.get("validation_evidence") or {})
            plan_state = load_plan_state(self.data_path, task_id)
            _, current_step = current_plan_step_with_index(plan_state)
            current_step = current_step or {}
            current_step_id = str(current_step.get("step_id") or validation.step_id or "")
            command_role = str(validation.command_role or execution.get("command_role") or "analysis_execution").lower()
            execution_purpose = str(execution.get("purpose") or "analysis").strip().lower()

            def replace_validation(**changes: Any) -> None:
                nonlocal validation
                value = validation.to_dict()
                for key, item in changes.items():
                    if key in {"errors", "warnings", "info", "recoverability_hints"}:
                        value[key] = list(dict.fromkeys([*list(value.get(key) or []), *list(item or [])]))
                    else:
                        value[key] = item
                validation = ValidationEvidence.from_mapping(value)
                update["validation_evidence"] = validation.to_dict()
                update["supervisor_verdict"] = self.supervisor_node._legacy_compat_status(validation.status)

            execution_contract_errors: List[str] = []
            if not str(execution.get("execution_id") or execution.get("attempt_id") or ""):
                execution_contract_errors.append("No persisted ExecutionRecord identifies the current attempt.")
            if current_step_id and str(execution.get("step_id") or "") not in {"", current_step_id}:
                execution_contract_errors.append(
                    f"ExecutionRecord belongs to step {execution.get('step_id')}, not {current_step_id}."
                )
            if str(execution.get("execution_status") or "").lower() == "failed" and validation.status == ValidationStatus.VALID.value:
                execution_contract_errors.append("ExecutionRecord status is failed despite a valid return-code projection.")
            if execution_contract_errors:
                replace_validation(
                    status=ValidationStatus.INVALID.value,
                    errors=execution_contract_errors,
                    recoverability_hints=["execution_contract"],
                )

            conflict_summary = conflict_update.get("knowledge_conflict_summary") or {}
            blocking_conflicts = list(conflict_summary.get("blocking_conflicts") or []) if isinstance(conflict_summary, dict) else []
            conflict_decisions = list(conflict_summary.get("decisions") or []) if isinstance(conflict_summary, dict) else []
            plan_conflict = any(
                isinstance(item, dict)
                and bool(item.get("requires_plan_revision"))
                and str(item.get("decision") or "") in {
                    "local_replan", "stage_replan", "downstream_replan", "global_replan",
                }
                for item in conflict_decisions
            )
            if blocking_conflicts:
                replace_validation(
                    status=ValidationStatus.INVALID.value,
                    errors=["Unresolved knowledge conflicts: " + ", ".join(map(str, blocking_conflicts[:8]))],
                    recoverability_hints=["knowledge_conflict"],
                )
            validation_payload = validation.to_dict()
            if plan_conflict:
                validation_payload["failure_owner"] = RecoveryFailureOwner.PLAN.value
                validation_payload["contract_violations"] = [
                    "Knowledge conflict resolution explicitly requires a plan revision."
                ]

            current_task_state = dict(plan_state.get("task_state") or {})
            legacy_renderer_mode = bool(
                current_task_state.get("legacy_renderer_mode") is True
                or str(current_task_state.get("execution_contract") or "")
                == "legacy_renderer_v1"
            )
            # In V2 the Supervisor's deterministic ValidationEvidence closes
            # the exact Generate -> Execute artifact versions before the
            # Completion Gate reads them.  Delaying this write until a later
            # legacy adapter leaves valid outputs in `materialized/unknown`
            # state and causes a false Generate retry loop.
            if not legacy_renderer_mode and str(execution.get("attempt_id") or ""):
                try:
                    provenance_plan = load_plan_state(self.data_path, task_id)
                    record_provenance_event(provenance_plan, "validation_recorded", {
                        "attempt_id": str(execution.get("attempt_id") or ""),
                        "validation": validation.to_dict(),
                    })
                    save_plan_state(self.data_path, task_id, provenance_plan)
                    plan_state = provenance_plan
                    update["provenance_summary"] = provenance_debug_dump(provenance_plan)["summary"]
                    update["provenance_state_path"] = str(plan_state_path(self.data_path, task_id))
                except ValueError as exc:
                    logger.warning("Could not associate V2 validation provenance for %s: %s", task_id, exc)

            def commit_policy(
                *,
                evidence: Optional[Dict[str, Any]] = None,
                completion: Optional[Dict[str, Any]] = None,
            ) -> RecoveryDecision:
                current = load_plan_state(self.data_path, task_id)
                decision = RecoveryPolicy().decide(
                    execution_evidence=execution,
                    validation_evidence=evidence if evidence is not None else validation_payload,
                    progress_snapshot=dict(state.get("recovery_progress") or {}),
                    completion_evidence=completion,
                    budgets=dict((current.get("task_state") or {}).get("budgets") or {}),
                    action_id=str(execution.get("action_id") or execution.get("execution_id") or "supervisor"),
                    step_id=current_step_id,
                    attempt_id=str(execution.get("attempt_id") or execution.get("execution_id") or validation.validation_id),
                )
                decision = contextualize_recovery_decision(decision, source_node="supervisor")
                update["recovery_decision"] = decision.to_dict()
                update["recovery_application"] = {}
                update["recovery_status"] = decision.kind
                update["plan_progress"] = render_plan_progress(current)
                update["pending_action"] = {}
                return decision

            if validation.status not in {
                ValidationStatus.VALID.value,
                ValidationStatus.VALID_WITH_WARNINGS.value,
            }:
                decision = commit_policy()
                update.setdefault("messages", []).append(SystemMessage(content=(
                    f"RecoveryPolicy interpreted ValidationEvidence {validation.validation_id} as "
                    f"{decision.kind}; Supervisor supplied facts only."
                )))
            elif command_role in {"probe", "diagnostic", "optional_probe", "capability_probe"}:
                decision = commit_policy()
                update["completion_gate_result"] = {
                    "passed": False,
                    "classification": "probe_evidence_recorded",
                    "formal_artifact_gate_skipped": True,
                    "completion_eligible": False,
                    "step_completed": False,
                }
                update["diagnostic_evidence"] = dict(
                    execution.get("diagnostic_evidence") or {}
                )
                update.setdefault("messages", []).append(SystemMessage(content=(
                    "The bounded probe was recorded as capability evidence. No formal artifact or step completion gate ran."
                )))
            else:
                renderer_controlled = bool(
                    legacy_renderer_mode
                    and (
                        command_role == "renderer_invocation"
                        or str(execution.get("action_source") or "") == "manifest_runner"
                    )
                )
                renderer_incomplete = False
                if renderer_controlled:
                    try:
                        manifest_path = str(execution.get("manifest_path") or "")
                        raw_manifest = json.loads(Path(manifest_path).read_text(encoding="utf-8"))
                        renderer_plan = load_plan_state(self.data_path, task_id)
                        _, renderer_step = current_plan_step_with_index(renderer_plan)
                        renderer_step = renderer_step or {}
                        if command_role == "renderer_invocation":
                            manifest = register_renderer_manifest(
                                renderer_plan,
                                str(renderer_step.get("step_id") or current_step_id),
                                raw_manifest,
                                manifest_path=manifest_path,
                                task_id=str(task_id),
                                producer_action_id=str(execution.get("action_id") or ""),
                            )
                            renderer_incomplete = True
                        else:
                            manifest = normalize_renderer_manifest(raw_manifest, manifest_path)
                            action_id = str(execution.get("manifest_action_id") or "")
                            action = next(
                                item for item in manifest.get("actions", [])
                                if str(item.get("id") or "") == action_id
                            )
                            action_validation = validate_renderer_action_artifacts(manifest, action)
                            if not action_validation["passed"]:
                                raise ValueError(json.dumps(action_validation, ensure_ascii=False, sort_keys=True))
                            mark_renderer_action_completed(
                                renderer_plan,
                                str(renderer_step.get("step_id") or current_step_id),
                                action_id,
                                {
                                    "execution_id": str(execution.get("execution_id") or ""),
                                    "action_id": str(execution.get("action_id") or ""),
                                    "manifest_fingerprint": str(execution.get("manifest_fingerprint") or ""),
                                    "manifest_script_hash": str(execution.get("manifest_script_hash") or ""),
                                    "artifact_validation": action_validation,
                                },
                            )
                            renderer_execution = dict(renderer_step.get("renderer_execution") or {})
                            renderer_incomplete = not renderer_manifest_complete(manifest, renderer_execution)
                        save_plan_state(self.data_path, task_id, renderer_plan)
                    except (OSError, json.JSONDecodeError, StopIteration, ValueError) as exc:
                        replace_validation(
                            status=ValidationStatus.INVALID.value,
                            errors=[f"Renderer manifest/action contract failed: {exc}"],
                            recoverability_hints=["artifact_contract"],
                        )
                        validation_payload = validation.to_dict()
                        decision = commit_policy(evidence=validation_payload)
                        update.setdefault("messages", []).append(SystemMessage(content=(
                            f"Renderer contract validation failed; RecoveryPolicy selected {decision.kind}."
                        )))
                        renderer_incomplete = True

                if "recovery_decision" not in update and renderer_incomplete:
                    decision = commit_policy()
                    update["completion_gate_result"] = {
                        "passed": True,
                        "classification": (
                            "renderer_manifest_registered"
                            if command_role == "renderer_invocation"
                            else "manifest_action_completed"
                        ),
                    }
                elif "recovery_decision" not in update and not self._execution_purpose_completes_step(
                    current_step,
                    execution_purpose,
                ):
                    decision = commit_policy()
                    update.setdefault("messages", []).append(SystemMessage(content=(
                        "The execution produced validation evidence but did not satisfy the business purpose of the current step."
                    )))
                elif "recovery_decision" not in update:
                    gate_state = load_plan_state(self.data_path, task_id)
                    step_gate = CompletionGate.validate_current_step(self.data_path, task_id, gate_state)
                    if (
                        not step_gate.passed
                        and step_gate.classification == "contract_reconciliation_required"
                        and isinstance(step_gate.reconciliation, dict)
                    ):
                        reconciliation = step_gate.reconciliation
                        events = apply_artifact_reconciliation(
                            gate_state,
                            str(reconciliation.get("step_id") or current_step_id),
                            reconciliation.get("manifest") or {},
                            manifest_path=str(reconciliation.get("manifest_path") or ""),
                        )
                        if events:
                            save_plan_state(self.data_path, task_id, gate_state)
                            gate_state = load_plan_state(self.data_path, task_id)
                            step_gate = CompletionGate.validate_current_step(self.data_path, task_id, gate_state)
                    update["completion_gate_result"] = step_gate.to_dict()
                    if step_gate.passed:
                        decision = commit_policy(
                            completion={
                                "completion_satisfied": True,
                                "task_complete": False,
                                "evidence": [validation.validation_id, "current_step_completion_gate_passed"],
                            }
                        )
                        if self._plan_tracker_is_complete(task_id):
                            next_batch = self._activate_next_workflow_batch_after_plan_completion(state, task_id)
                            if next_batch:
                                update.update(next_batch)
                    else:
                        failed_validation = validation.to_dict()
                        failed_validation["status"] = ValidationStatus.INVALID.value
                        failed_validation["errors"] = list(dict.fromkeys([
                            *validation.errors,
                            str(step_gate.message or step_gate.feedback or "Current step contract failed."),
                        ]))
                        decision = commit_policy(evidence=failed_validation)

            update["validation_evidence"] = validation.to_dict()
            update["last_supervisor_feedback"] = {
                "validation_id": validation.validation_id,
                "status": validation.status,
                "legacy_compat_only": True,
                "step_id": current_step_id,
                "execution_id": str(execution.get("execution_id") or execution.get("action_id") or ""),
            }
            await self._observe_session_memory(
                task_id,
                "supervisor",
                state.get("messages", []) + list(update.get("messages") or []),
                {
                    "validation_status": validation.status,
                    "validation_id": validation.validation_id,
                    "recovery_decision": str((update.get("recovery_decision") or {}).get("kind") or ""),
                },
            )
            return update

        async def _legacy_supervisor_controller(state: AgentState):
            """Deprecated compatibility node; not registered in the active graph."""
            output.print_node_header("supervisor")
            task_id = state.get("task_id", "default")
            conflict_update = self._knowledge_conflict_update(
                task_id,
                dict(state),
                phase="before_supervisor",
            )
            supervisor_state = {**dict(state), **conflict_update}
            if state.get("final_audit_requested"):
                update = await self.supervisor_node.final_audit(supervisor_state)
            else:
                update = await self.supervisor_node.run(supervisor_state)
            update = {**conflict_update, **(update if isinstance(update, dict) else {})}
            execution = state.get("execution_evidence") or {}
            current_plan_state = load_plan_state(self.data_path, task_id)
            _, current_plan_step = current_plan_step_with_index(current_plan_state)
            current_step_id = str(current_plan_step.get("step_id") or "")
            execution_step_id = str(execution.get("step_id") or "") if isinstance(execution, dict) else ""
            execution_purpose = str(execution.get("purpose") or "analysis").strip().lower() if isinstance(execution, dict) else ""
            renderer_controlled = bool(
                isinstance(execution, dict)
                and (
                    str(execution.get("command_role") or "") == "renderer_invocation"
                    or str(execution.get("action_source") or "") == "manifest_runner"
                )
            )
            renderer_probe = bool(
                isinstance(execution, dict)
                and bool(current_plan_step.get("renderer_composite"))
                and str(execution.get("command_role") or "").lower() in {"diagnostic", "optional_probe"}
                and execution_purpose in {"probe", "validation"}
            )
            provisional_verdict = str(update.get("supervisor_verdict") or "").upper()
            if not state.get("final_audit_requested") and provisional_verdict in {"PASS", "WARN"}:
                execution_contract_error = ""
                if not isinstance(execution, dict) or not str(execution.get("execution_id") or ""):
                    execution_contract_error = "Supervisor has no persisted ExecutionRecord for the current step."
                elif current_step_id and execution_step_id != current_step_id:
                    execution_contract_error = (
                        f"ExecutionRecord belongs to step {execution_step_id or '<missing>'}, not current step {current_step_id}."
                    )
                elif str(execution.get("execution_status") or "").lower() != "succeeded":
                    execution_contract_error = "The current ExecutionRecord is not successful."
                if execution_contract_error:
                    update["supervisor_verdict"] = "RETRY"
                    update["next_step"] = "generate"
                    failed_execution = (
                        isinstance(execution, dict)
                        and bool(str(execution.get("execution_id") or ""))
                        and str(execution.get("execution_status") or "").lower() != "succeeded"
                    )
                    update["required_next_action"] = "SCRIPT_PATCH" if failed_execution else "PROBE"
                    update["failure_owner"] = (
                        RecoveryFailureOwner.SCRIPT.value
                        if failed_execution
                        else RecoveryFailureOwner.VERIFICATION.value
                    )
                    update["recovery_scope"] = "CURRENT_STEP"
                    update["recovery_phase"] = "apply_repair" if failed_execution else "probe"
                    update["pending_recovery_action"] = {
                        "type": "script_patch" if failed_execution else "diagnostic_probe",
                        "reason": execution_contract_error,
                        "failure_owner": update["failure_owner"],
                    }
                    update.setdefault("messages", []).append(SystemMessage(content=execution_contract_error))
                elif renderer_probe:
                    update.update({
                        "next_step": "generate",
                        "pending_action": {},
                        "pending_recovery_action": {},
                        "required_next_action": "",
                        "failure_owner": "",
                        "recovery_scope": "",
                        "recovery_phase": "",
                        "action_status": "completed",
                        "step_status": "in_progress",
                        "completion_gate_result": {
                            "passed": True,
                            "classification": "renderer_probe_recorded",
                            "formal_artifact_gate_skipped": True,
                        },
                    })
                    update.setdefault("messages", []).append(SystemMessage(content=(
                        "The bounded Renderer capability probe completed and was recorded as diagnostic evidence. "
                        "It did not invoke the Renderer, consume Renderer invocation budget, run the formal Renderer "
                        "artifact gate, or complete the composite step."
                    )))
                elif not renderer_controlled and not self._execution_purpose_completes_step(
                    current_plan_step,
                    execution_purpose,
                ):
                    update["supervisor_verdict"] = "RETRY"
                    update["next_step"] = "generate"
                    update.setdefault("messages", []).append(SystemMessage(content=(
                        "The command produced diagnostic/validation evidence only. The current business analysis step "
                        "declares a different purpose and remains incomplete; use the evidence for a concrete repair "
                        "or analysis action."
                    )))
            if renderer_probe and str(update.get("supervisor_verdict") or "").upper() in {"PASS", "WARN"}:
                update["last_supervisor_feedback"] = self._supervisor_feedback_snapshot(
                    update,
                    state,
                    task_id,
                )
                await self._observe_session_memory(
                    task_id,
                    "supervisor",
                    state.get("messages", []) + list(update.get("messages") or []),
                    {
                        "next_step": "generate",
                        "supervisor_verdict": update.get("supervisor_verdict"),
                        "renderer_probe": True,
                    },
                )
                return update
            effective_renderer_verdict = str(update.get("supervisor_verdict") or "").upper()
            if renderer_controlled and effective_renderer_verdict in {"PASS", "WARN"}:
                renderer_result: Dict[str, Any] = {}
                renderer_plan = load_plan_state(self.data_path, task_id)
                _, renderer_step = current_plan_step_with_index(renderer_plan)
                renderer_step = renderer_step or {}
                role = str(execution.get("command_role") or "")
                manifest_path = str(execution.get("manifest_path") or "")
                try:
                    raw_manifest = json.loads(Path(manifest_path).read_text(encoding="utf-8"))
                    if role == "renderer_invocation":
                        manifest = register_renderer_manifest(
                            renderer_plan,
                            str(renderer_step.get("step_id") or ""),
                            raw_manifest,
                            manifest_path=manifest_path,
                            task_id=str(task_id),
                            producer_action_id=str(execution.get("action_id") or ""),
                        )
                    else:
                        manifest = normalize_renderer_manifest(raw_manifest, manifest_path)
                    requirement_result = evaluate_requirements(manifest.get("requirements", []) or [])
                    if requirement_result["blocked"]:
                        raise ValueError(
                            "Missing required renderer requirements: "
                            + ", ".join(requirement_result["missing_required"] + requirement_result["missing_conditional"])
                        )
                    if requirement_result["needs_reconciliation"]:
                        raise ValueError(
                            "Renderer requirements need contract reconciliation: "
                            + ", ".join(requirement_result["unknown"])
                        )
                    update["missing_required_inputs"] = []
                    update["skipped_optional_checks"] = list(requirement_result["skipped_optional"])
                    update["proposed_requirements"] = []
                    update["contract_status"] = "valid"
                    update["action_status"] = "completed"
                    update["step_status"] = "in_progress"
                    if role == "renderer_invocation":
                        save_plan_state(self.data_path, task_id, renderer_plan)
                        renderer_result = {
                            "messages": list(update.get("messages") or []) + [SystemMessage(content=(
                                "Renderer manifest registered. Subsequent professional actions are controller-selected "
                                "from the manifest; this invocation does not complete the composite plan step."
                            ))],
                            "supervisor_verdict": effective_renderer_verdict,
                            "next_step": "generate",
                            "pending_action": {},
                            "pending_recovery_action": {},
                            "required_next_action": "",
                            "failure_owner": "",
                            "recovery_scope": "",
                            "recovery_phase": "",
                            "action_status": "completed",
                            "step_status": "in_progress",
                            "contract_status": "valid",
                            "missing_required_inputs": [],
                            "skipped_optional_checks": list(requirement_result["skipped_optional"]),
                            "proposed_requirements": [],
                            "completion_gate_result": {
                                "passed": True,
                                "classification": "renderer_manifest_registered",
                            },
                        }
                    else:
                        action_id = str(execution.get("manifest_action_id") or "")
                        action = next(
                            item for item in manifest.get("actions", [])
                            if str(item.get("id") or "") == action_id
                        )
                        action_validation = validate_renderer_action_artifacts(manifest, action)
                        if not action_validation["passed"]:
                            raise ValueError(
                                "Renderer action artifact validation failed: "
                                + json.dumps(action_validation, ensure_ascii=False, sort_keys=True)
                            )
                        mark_renderer_action_completed(
                            renderer_plan,
                            str(renderer_step.get("step_id") or ""),
                            action_id,
                            {
                                "execution_id": str(execution.get("execution_id") or ""),
                                "action_id": str(execution.get("action_id") or ""),
                                "manifest_fingerprint": str(execution.get("manifest_fingerprint") or ""),
                                "manifest_script_hash": str(execution.get("manifest_script_hash") or ""),
                                "artifact_validation": action_validation,
                            },
                        )
                        save_plan_state(self.data_path, task_id, renderer_plan)
                        renderer_execution = dict(renderer_step.get("renderer_execution") or {})
                        if not renderer_manifest_complete(manifest, renderer_execution):
                            renderer_result = {
                                "messages": list(update.get("messages") or []) + [SystemMessage(content=(
                                    f"Renderer action {action_id} passed its declared contract. "
                                    "The composite step remains in progress; scheduling the next manifest action."
                                ))],
                                "supervisor_verdict": effective_renderer_verdict,
                                "next_step": "generate",
                                "pending_action": {},
                                "pending_recovery_action": {},
                                "required_next_action": "",
                                "failure_owner": "",
                                "recovery_scope": "",
                                "recovery_phase": "",
                                "action_status": "completed",
                                "step_status": "in_progress",
                                "contract_status": "valid",
                                "missing_required_inputs": [],
                                "skipped_optional_checks": list(requirement_result["skipped_optional"]),
                                "proposed_requirements": [],
                                "completion_gate_result": {
                                    "passed": True,
                                    "classification": "manifest_action_completed",
                                    "action_id": action_id,
                                },
                            }
                except (OSError, json.JSONDecodeError, StopIteration, ValueError) as exc:
                    update.update({
                        "supervisor_verdict": "RETRY",
                        "next_step": "generate",
                        "required_next_action": "RECONCILE_ARTIFACTS",
                        "failure_owner": RecoveryFailureOwner.ARTIFACT_CONTRACT.value,
                        "recovery_scope": "CURRENT_STEP",
                        "recovery_phase": "reconcile",
                        "action_status": "failed",
                        "step_status": "in_progress",
                        "contract_status": "conflict",
                        "pending_recovery_action": {
                            "type": "reconcile_artifacts",
                            "reason": str(exc),
                            "failure_owner": RecoveryFailureOwner.ARTIFACT_CONTRACT.value,
                        },
                    })
                    update.setdefault("messages", []).append(SystemMessage(content=str(exc)))
                if renderer_result:
                    renderer_result["last_supervisor_feedback"] = self._supervisor_feedback_snapshot(
                        renderer_result,
                        state,
                        task_id,
                    )
                    await self._observe_session_memory(
                        task_id,
                        "supervisor",
                        state.get("messages", []) + list(renderer_result.get("messages") or []),
                        {
                            "next_step": "generate",
                            "supervisor_verdict": effective_renderer_verdict,
                            "renderer_action": str(execution.get("manifest_action_id") or role),
                        },
                    )
                    return renderer_result
            conflict_summary = conflict_update.get("knowledge_conflict_summary", {})
            blocking_conflicts = conflict_summary.get("blocking_conflicts", []) if isinstance(conflict_summary, dict) else []
            if blocking_conflicts and str(update.get("supervisor_verdict") or "") in {"PASS", "WARN"}:
                update["supervisor_verdict"] = "RETRY"
                update["next_step"] = "generate"
                update.setdefault("messages", []).append(
                    SystemMessage(
                        content=(
                            "Knowledge conflict audit blocked Supervisor completion. Unresolved blocking conflicts: "
                            + ", ".join(str(item) for item in blocking_conflicts[:8])
                            + ". Resolve or revalidate them before PASS."
                        )
                    )
                )
            decisions = conflict_summary.get("decisions", []) if isinstance(conflict_summary, dict) else []
            if any(
                isinstance(item, dict)
                and item.get("requires_plan_revision")
                and item.get("decision") in {"local_replan", "stage_replan", "downstream_replan", "global_replan"}
                for item in decisions
            ):
                update.setdefault("messages", []).append(
                    SystemMessage(content="Knowledge conflict requires an auditable plan revision before the next execution step.")
                )
                update["next_step"] = "planner"
                update["required_next_action"] = "PLAN_PATCH"
                update["failure_owner"] = RecoveryFailureOwner.PLAN.value
                update["recovery_scope"] = "CURRENT_STEP"
                update["recovery_phase"] = "plan_repair"
            update_messages = update.get("messages", []) if isinstance(update, dict) else []
            await self._observe_session_memory(
                task_id,
                "supervisor",
                state.get("messages", []) + update_messages,
                {
                    "next_step": update.get("next_step") if isinstance(update, dict) else "",
                    "retry_count": update.get("retry_count") if isinstance(update, dict) else "",
                    "supervisor_verdict": update.get("supervisor_verdict") if isinstance(update, dict) else "",
                },
            )
            if isinstance(update, dict):
                verdict = str(update.get("supervisor_verdict") or "")
                warn_requires_followup = verdict == "WARN" and self._supervisor_warn_requires_followup(update_messages)
                if warn_requires_followup:
                    warn_step_gate_state = load_plan_state(self.data_path, task_id)
                    warn_step_gate = CompletionGate.validate_current_step(
                        self.data_path,
                        task_id,
                        warn_step_gate_state,
                    )
                    if self._supervisor_warn_is_acceptably_artifact_bounded(
                        update_messages,
                        warn_step_gate_state,
                        warn_step_gate,
                    ):
                        update.setdefault("messages", []).append(
                            SystemMessage(
                                content=(
                                    "Supervisor WARN requested an additional artifact inspection, but the deterministic "
                                    "step completion gate already verified the final/status artifacts for this output step. "
                                    "Treating the WARN as advisory and allowing normal completion checks to proceed."
                                )
                            )
                        )
                        warn_requires_followup = False
                if warn_requires_followup:
                    followup_text = "\n".join(
                        str(getattr(msg, "content", msg) or "") for msg in update_messages
                    )[:1200]
                    plan_progress = self._record_plan_current_evidence(
                        task_id,
                        "warn_followup_required",
                        followup_text,
                    )
                    update.setdefault("messages", []).append(
                        SystemMessage(
                            content=(
                                "Supervisor WARN contains a required follow-up action, so this step is not complete yet. "
                                "Continue with Generate and perform the concrete action from the supervisor feedback before "
                                "advancing or finishing."
                            )
                        )
                    )
                    update["supervisor_verdict"] = "RETRY"
                    update["next_step"] = "generate"
                    update["plan_progress"] = plan_progress
                elif verdict in {"PASS", "WARN"}:
                    step_gate_state = load_plan_state(self.data_path, task_id)
                    step_gate = CompletionGate.validate_current_step(
                        self.data_path,
                        task_id,
                        step_gate_state,
                    )
                    update["completion_gate_result"] = step_gate.to_dict()
                    if (
                        not step_gate.passed
                        and step_gate.classification == "contract_reconciliation_required"
                        and isinstance(step_gate.reconciliation, dict)
                    ):
                        reconciliation = step_gate.reconciliation
                        events = apply_artifact_reconciliation(
                            step_gate_state,
                            str(reconciliation.get("step_id") or current_step_id),
                            reconciliation.get("manifest") or {},
                            manifest_path=str(reconciliation.get("manifest_path") or ""),
                        )
                        if events:
                            save_plan_state(self.data_path, task_id, step_gate_state)
                            step_gate_state = load_plan_state(self.data_path, task_id)
                            step_gate = CompletionGate.validate_current_step(
                                self.data_path,
                                task_id,
                                step_gate_state,
                            )
                            update["completion_gate_result"] = step_gate.to_dict()
                            update.setdefault("messages", []).append(SystemMessage(content=(
                                "Renderer artifact manifest reconciled the current plan contract without rerunning "
                                "the successful command. Completion Gate was re-evaluated against canonical paths."
                            )))
                    structured_recovery_action = ""
                    if not step_gate.passed:
                        update = await self._adjudicate_post_review_recovery(state, update, task_id)
                        structured_recovery_action = str(
                            (update.get("recovery_decision") or {}).get("recommended_action") or ""
                        )
                    if structured_recovery_action:
                        plan_progress = self._record_plan_current_evidence(
                            task_id,
                            "structured_recovery_decision",
                            json.dumps(update.get("recovery_decision") or {}, ensure_ascii=False)[:3000],
                        )
                        update["plan_progress"] = plan_progress
                        if structured_recovery_action == RecoveryAction.RECONCILE_AND_CONTINUE.value:
                            # Reconciliation was already attempted above. A still-failing
                            # gate means the canonical producer/output still needs a
                            # current-step repair; it is not evidence that the Plan is wrong.
                            update["next_step"] = "generate"
                            update["required_next_action"] = "SCRIPT_PATCH"
                            update["failure_owner"] = RecoveryFailureOwner.GENERATED_ACTION.value
                            update["recovery_scope"] = "CURRENT_STEP"
                    elif not step_gate.passed and step_gate.classification == "diagnostic_probe_required":
                        plan_progress = self._record_plan_current_evidence(
                            task_id,
                            "artifact_contract_diagnostic_required",
                            step_gate.feedback,
                        )
                        update.setdefault("messages", []).append(SystemMessage(content=(
                            "Completion Gate found bounded artifact candidates but no authoritative manifest mapping. "
                            "This is a control-plane contract ambiguity, not an execution retry. Planner must perform "
                            "a local contract repair or preserve a bounded read-only diagnostic step; do not rerun the "
                            "successful producer command.\n\n" + step_gate.feedback
                        )))
                        update["supervisor_verdict"] = "WARN"
                        update["next_step"] = "generate"
                        update["required_next_action"] = "DIAGNOSTIC_PROBE"
                        update["plan_progress"] = plan_progress
                    elif not step_gate.passed:
                        plan_progress = self._record_plan_current_evidence(
                            task_id,
                            "step_completion_gate_failed",
                            step_gate.message,
                        )
                        gate_message = (
                            "Step completion validation failed.\n\n"
                            f"{step_gate.feedback}\n\n"
                            "Do not advance to the next plan step yet. Continue or repair the current step, "
                            "then run a concrete verification command."
                        )
                        update.setdefault("messages", []).append(SystemMessage(content=gate_message))
                        update["supervisor_verdict"] = "RETRY"
                        update["next_step"] = "generate"
                        update["plan_progress"] = plan_progress
                    else:
                        plan_progress = self._mark_plan_current_done(
                            task_id,
                            f"supervisor_verdict: {verdict}",
                            source_node="supervisor",
                        )
                        converged_steps, converged_progress = self._advance_satisfied_validation_steps(
                            task_id,
                            execution if isinstance(execution, dict) else {},
                            source_node="supervisor",
                        )
                        if converged_steps:
                            plan_progress = converged_progress
                            update.setdefault("messages", []).append(SystemMessage(content=(
                                f"Controller linked the successful ExecutionEvidence to {converged_steps} consecutive "
                                "validation step(s), verified each step's success criteria through CompletionGate, "
                                "and advanced without repeating the same check."
                            )))
                        update["plan_progress"] = plan_progress
                        committed_plan = load_plan_state(self.data_path, task_id)
                        committed_recovery = dict(
                            ((committed_plan.get("task_state") or {}).get("recovery_state") or {})
                        )
                        committed_decision = dict(committed_recovery.get("last_recovery_decision") or {})
                        update["pending_recovery_action"] = {}
                        update["recovery_phase"] = "committed"
                        update["recovery_status"] = str(committed_decision.get("kind") or "COMPLETE_STEP")
                        update["retry_count"] = int(
                            (((committed_plan.get("task_state") or {}).get("budgets") or {}).get("execution_retry_count"))
                            or 0
                        )
                        update["recovery_decision"] = committed_decision
                        update["next_step"] = str(committed_decision.get("next_route") or "generate")
                        update["verification_checks"] = []
                        update["forbidden_recovery_actions"] = []
                        for field in SUPERVISOR_RETRY_FIELDS:
                            update[field] = ""
                        if self._plan_tracker_is_complete(task_id):
                            final_gate_state = load_plan_state(self.data_path, task_id)
                            final_gate = CompletionGate.validate_final(
                                self.data_path,
                                task_id,
                                final_gate_state,
                                state.get("current_plan", ""),
                                require_execution_evidence=True,
                                require_supervisor_evidence=True,
                            )
                            update["completion_gate_result"] = final_gate.to_dict()
                            if final_gate.passed:
                                next_batch_update = self._activate_next_workflow_batch_after_plan_completion(
                                    state,
                                    task_id,
                                )
                                if next_batch_update:
                                    update.update(next_batch_update)
                                    update["supervisor_verdict"] = "PASS"
                                    update["plan_progress"] = ""
                                else:
                                    completed_state = load_plan_state(self.data_path, task_id)
                                    set_task_status(completed_state, TASK_STATUS_COMPLETED, "final completion gate passed")
                                    save_plan_state(self.data_path, task_id, completed_state)
                                    update["next_step"] = "finish"
                            else:
                                reopened_state = load_plan_state(self.data_path, task_id)
                                reopen_last_done_step(
                                    reopened_state,
                                    f"final_completion_gate_failed: {final_gate.message}",
                                )
                                plan_progress = self._persist_plan_tracker(task_id, reopened_state)
                                gate_message = (
                                    "Final completion validation failed.\n\n"
                                    f"{final_gate.feedback}\n\n"
                                    "The plan was marked complete, but the task is not ready to finish. "
                                    "Repair the reopened final/output step and verify the artifacts."
                                )
                                update.setdefault("messages", []).append(SystemMessage(content=gate_message))
                                update["supervisor_verdict"] = "RETRY"
                                update["next_step"] = "generate"
                                update["plan_progress"] = plan_progress
                                update = await self._adjudicate_post_review_recovery(state, update, task_id)
                elif verdict == "RETRY":
                    update = await self._adjudicate_post_review_recovery(state, update, task_id)
                    plan_progress = self._record_plan_current_evidence(
                        task_id,
                        "structured_recovery_decision",
                        json.dumps(update.get("recovery_decision") or {}, ensure_ascii=False)[:3000],
                    )
                    update["plan_progress"] = plan_progress
                elif verdict == "ESCALATE":
                    if (
                        str(state.get("task_mode") or "managed").lower() == "managed"
                        and not bool(state.get("non_interactive"))
                    ):
                        plan_progress = self._record_plan_current_evidence(
                            task_id,
                            "supervisor_escalation_waiting_user",
                            "Automatic retries were exhausted without a verified completion.",
                        )
                        failed_checks = (update.get("supervisor_feedback") or {}).get("failed_checks", [])
                        reason = "; ".join(
                            str(item.get("message") or "") for item in failed_checks[:3] if isinstance(item, dict)
                        ) or "Supervisor exhausted automatic retries for the current step."
                        question = (
                            f"Automatic recovery could not verify the current step: {reason} "
                            "Please provide a different recovery direction, or confirm that this stage should be recorded as blocked."
                        )
                        update.update({
                            "plan_progress": plan_progress,
                            "next_step": "ask_user",
                            "pending_human_question": {
                                "type": "supervisor_escalation",
                                "stage": "supervisor",
                                "question": question,
                                "resume_step": "generate",
                            },
                            "task_status": TASK_STATUS_WAITING_USER,
                        })
                    else:
                        plan_progress = self._mark_plan_current_blocked(task_id, "supervisor_verdict: ESCALATE")
                        update["plan_progress"] = plan_progress
                        update["next_step"] = self._next_step_after_runtime_block(task_id)
            if isinstance(update, dict) and str(update.get("supervisor_verdict") or "").upper() == "RETRY":
                if missing_supervisor_retry_fields(update):
                    retry_text = "\n".join(
                        str(getattr(message, "content", message) or "")
                        for message in list(update.get("messages", []) or [])[-4:]
                    )
                    retry_state = {**dict(state), **update}
                    contract = self.supervisor_node._retry_contract(
                        retry_state,
                        [],
                        fallback_reason=self._clip_observation_text(retry_text, 3000) or "Supervisor requested retry.",
                    )
                    if update.get("next_step") == "planner":
                        contract.update({
                            "required_next_action": "PLAN_PATCH",
                            "failure_owner": RecoveryFailureOwner.PLAN.value,
                            "recovery_scope": "PLAN",
                            "recovery_phase": "plan_repair",
                        })
                    update.update(contract)
            update = self._commit_legacy_recovery_projection(
                state,
                update,
                task_id,
                source_node="supervisor",
            )
            effective_verdict = str(update.get("supervisor_verdict") or "").upper() if isinstance(update, dict) else ""
            if provisional_verdict and effective_verdict and effective_verdict != provisional_verdict:
                logger.warning(
                    "Controller adjusted Supervisor verdict: task=%s step=%s %s->%s",
                    task_id,
                    current_step_id or "-",
                    provisional_verdict,
                    effective_verdict,
                )
                output.print_once(
                    f"supervisor_effective_verdict:{task_id}:{current_step_id}:{effective_verdict}",
                    (
                        f"Controller effective verdict: {effective_verdict} "
                        f"(Supervisor initially reported {provisional_verdict}; controller contract checks adjusted it)."
                    ),
                    Fore.YELLOW,
                )
            if isinstance(update, dict) and update.get("next_step") == "finish":
                verdict = str(update.get("supervisor_verdict") or "")
                final_status = "completed" if verdict in {"PASS", "WARN"} else "failed"
                if not update.get("plan_progress"):
                    if final_status == "failed":
                        update["plan_progress"] = self._mark_plan_current_blocked(
                            task_id,
                            f"supervisor_finished: {str(update.get('supervisor_verdict') or 'finish')}",
                        )
                    else:
                        update["plan_progress"] = render_plan_progress(load_plan_state(self.data_path, task_id))
                await self._finalize_task_memory(
                    task_id,
                    final_status,
                    state.get("messages", []) + update_messages,
                    {"reason": f"Supervisor ended the task with verdict {verdict or 'finish'}."},
                )
            update["last_supervisor_feedback"] = self._supervisor_feedback_snapshot(
                update,
                state,
                task_id,
            )
            final_validation = dict(update.get("validation_evidence") or {})
            attempt_id = str(execution.get("attempt_id") or "")
            if attempt_id:
                try:
                    provenance_plan = load_plan_state(self.data_path, task_id)
                    record_provenance_event(provenance_plan, "validation_recorded", {
                        "attempt_id": attempt_id,
                        "validation": final_validation,
                    })
                    save_plan_state(self.data_path, task_id, provenance_plan)
                    update["provenance_summary"] = provenance_debug_dump(provenance_plan)["summary"]
                    update["provenance_state_path"] = str(plan_state_path(self.data_path, task_id))
                except ValueError as exc:
                    logger.warning("Could not associate validation provenance for %s: %s", task_id, exc)
            return update

        async def supervisor_final_audit(state: AgentState):
            """Controller-owned final gate following fact-only validation."""
            output.print_node_header("supervisor_final_audit")
            task_id = state.get("task_id", "default")
            synced_from_status, reconciled_progress = self._reconcile_completion_candidate_plan(
                task_id,
                dict(state),
            )
            audit_state = dict(state)
            if synced_from_status:
                audit_state["plan_progress"] = reconciled_progress
            conflict_update = self._knowledge_conflict_update(task_id, audit_state, phase="final_audit")
            raw_update = await self.supervisor_node.final_audit({**audit_state, **conflict_update})
            update = {**conflict_update, **(raw_update if isinstance(raw_update, dict) else {})}
            validation = ValidationEvidence.from_mapping(update.get("validation_evidence") or {})
            blocking_conflicts = list(
                ((conflict_update.get("knowledge_conflict_summary") or {}).get("blocking_conflicts") or [])
            )
            validation_payload = validation.to_dict()
            if blocking_conflicts:
                validation_payload["status"] = ValidationStatus.INVALID.value
                validation_payload["errors"] = list(dict.fromkeys([
                    *validation.errors,
                    "Unresolved final-audit knowledge conflicts: " + ", ".join(map(str, blocking_conflicts[:8])),
                ]))
                validation = ValidationEvidence.from_mapping(validation_payload)
                update["validation_evidence"] = validation.to_dict()
                update["supervisor_verdict"] = self.supervisor_node._legacy_compat_status(validation.status)

            plan_state = load_plan_state(self.data_path, task_id)
            execution = dict(state.get("execution_evidence") or {})
            final_gate = CompletionGate.validate_final(
                self.data_path,
                task_id,
                plan_state,
                state.get("current_plan", ""),
                require_execution_evidence=True,
                require_supervisor_evidence=False,
            )
            update["completion_gate_result"] = final_gate.to_dict()
            completion: Dict[str, Any] = {}
            if validation.status in {
                ValidationStatus.VALID.value,
                ValidationStatus.VALID_WITH_WARNINGS.value,
            } and final_gate.passed:
                completion = {
                    "completion_satisfied": True,
                    "task_complete": True,
                    "evidence": [validation.validation_id, "final_completion_gate_passed"],
                }
            elif not final_gate.passed:
                validation_payload = validation.to_dict()
                validation_payload["status"] = ValidationStatus.INVALID.value
                validation_payload["errors"] = list(dict.fromkeys([
                    *validation.errors,
                    str(final_gate.message or final_gate.feedback or "Final completion contract failed."),
                ]))
                validation = ValidationEvidence.from_mapping(validation_payload)
                update["validation_evidence"] = validation.to_dict()
                update["supervisor_verdict"] = self.supervisor_node._legacy_compat_status(validation.status)

            decision = RecoveryPolicy().decide(
                execution_evidence=execution,
                validation_evidence=validation.to_dict(),
                completion_evidence=completion,
                progress_snapshot=dict(state.get("recovery_progress") or {}),
                budgets=dict((plan_state.get("task_state") or {}).get("budgets") or {}),
                action_id=str(execution.get("action_id") or execution.get("execution_id") or "final-audit"),
                step_id=str(state.get("current_step_id") or ""),
                attempt_id=f"final-audit:{task_id}:{validation.validation_id}",
            )
            decision = contextualize_recovery_decision(decision, source_node="supervisor")
            update["recovery_decision"] = decision.to_dict()
            update["recovery_application"] = {}
            update["recovery_status"] = decision.kind
            update["plan_progress"] = render_plan_progress(plan_state)
            update["final_audit_requested"] = False
            if decision.kind == RecoveryDecisionKind.COMPLETE_TASK.value:
                update["completion_candidate"] = {}
                await self._finalize_task_memory(
                    task_id,
                    "completed",
                    state.get("messages", []) + list(update.get("messages") or []),
                    {"reason": "ValidationEvidence and final CompletionGate passed."},
                )
            return update

        async def _legacy_supervisor_final_audit(state: AgentState):
            """Deprecated compatibility node; active final audit uses supervisor_final_audit."""
            """Run the objective final audit requested by the main router."""
            output.print_node_header("supervisor_final_audit")
            task_id = state.get("task_id", "default")
            synced_from_status, reconciled_progress = self._reconcile_completion_candidate_plan(
                task_id,
                dict(state),
            )
            audit_state = dict(state)
            if synced_from_status:
                audit_state["plan_progress"] = reconciled_progress
            conflict_update = self._knowledge_conflict_update(
                task_id,
                audit_state,
                phase="final_audit",
            )
            update = await self.supervisor_node.final_audit({**audit_state, **conflict_update})
            update = {**conflict_update, **(update if isinstance(update, dict) else {})}
            if synced_from_status:
                update.setdefault("messages", []).append(SystemMessage(content=(
                    "Controller synchronized the approved checklist from the terminal stage_status.tsv before final audit. "
                    "This is evidence reconciliation, not an LLM checklist mutation."
                )))
                update["plan_progress"] = audit_state.get("plan_progress", "")
            blocking_conflicts = (conflict_update.get("knowledge_conflict_summary") or {}).get("blocking_conflicts", [])
            if blocking_conflicts and str(update.get("supervisor_verdict") or "") in {"PASS", "WARN"}:
                update["supervisor_verdict"] = "RETRY"
                update["next_step"] = "generate"
                update.setdefault("messages", []).append(
                    SystemMessage(
                        content=(
                            "Final audit blocked by unresolved knowledge conflicts: "
                            + ", ".join(str(item) for item in blocking_conflicts[:8])
                        )
                    )
                )
            final_decisions = (conflict_update.get("knowledge_conflict_summary") or {}).get("decisions", [])
            if any(
                isinstance(item, dict)
                and item.get("requires_plan_revision")
                and item.get("decision") in {"local_replan", "stage_replan", "downstream_replan", "global_replan"}
                for item in final_decisions
            ):
                update.setdefault("messages", []).append(
                    SystemMessage(content="Final audit requires an auditable plan revision before execution can resume.")
                )
                update["next_step"] = "planner"
                update["required_next_action"] = "PLAN_PATCH"
                update["failure_owner"] = RecoveryFailureOwner.PLAN.value
                update["recovery_scope"] = "PLAN"
                update["recovery_phase"] = "plan_repair"
            update_messages = update.get("messages", []) if isinstance(update, dict) else []
            await self._observe_session_memory(
                task_id,
                "supervisor_final_audit",
                state.get("messages", []) + update_messages,
                {
                    "next_step": update.get("next_step") if isinstance(update, dict) else "",
                    "supervisor_verdict": update.get("supervisor_verdict") if isinstance(update, dict) else "",
                    "final_audit": True,
                },
            )
            if isinstance(update, dict) and update.get("next_step") == "finish":
                final_state = load_plan_state(self.data_path, task_id)
                final_gate = CompletionGate.validate_final(
                    self.data_path,
                    task_id,
                    final_state,
                    state.get("current_plan", ""),
                    require_execution_evidence=True,
                    require_supervisor_evidence=False,
                )
                update["completion_gate_result"] = final_gate.to_dict()
                if not final_gate.passed:
                    update.setdefault("messages", []).append(
                        SystemMessage(
                            content=(
                                "Final audit reached a finish recommendation, but the deterministic completion gate "
                                "rejected it.\n\n" + final_gate.feedback
                            )
                        )
                    )
                    update["next_step"] = "generate"
                    update["supervisor_verdict"] = "RETRY"
                    update = await self._adjudicate_post_review_recovery(state, update, task_id)
                else:
                    completed_state = load_plan_state(self.data_path, task_id)
                    completion_decision = RecoveryPolicy().decide(
                        completion_evidence={
                            "completion_satisfied": True,
                            "task_complete": True,
                            "evidence": ["supervisor_final_audit", "completion_gate_passed"],
                        },
                        action_id=str((state.get("execution_evidence") or {}).get("action_id") or "final-audit"),
                        step_id=str(state.get("current_step_id") or ""),
                        attempt_id=f"final-audit:{task_id}",
                        budgets=dict((completed_state.get("task_state") or {}).get("budgets") or {}),
                    )
                    completion_decision = contextualize_recovery_decision(
                        completion_decision,
                        source_node="supervisor",
                    )
                    update["recovery_decision"] = completion_decision.to_dict()
                    update["recovery_application"] = {}
                    update["next_step"] = completion_decision.next_route
                    update["final_audit_requested"] = False
                    update["completion_candidate"] = {}
            if isinstance(update, dict):
                update = self._commit_legacy_recovery_projection(
                    state,
                    update,
                    task_id,
                    source_node="supervisor",
                )
                update["last_supervisor_feedback"] = self._supervisor_feedback_snapshot(
                    update,
                    state,
                    task_id,
                )
            return update

        # ════════════════════════════════════════════
        # Node 5: Install Sub-Agent
        # ════════════════════════════════════════════
        async def install_subagent(state: AgentState):
            output.print_node_header("install_subagent")
            last_msg = state["messages"][-1].content
            task_id  = state.get("task_id", "default")
            pending_action = state.get("pending_action") or {}
            context_summary = self._clip_prompt_text(
                state.get("requirements_summary", "No context."),
                LLM_STEP_PLAN_CHARS,
            )
            current_plan_for_install = self._current_step_prompt_context(
                task_id,
                current_plan=str(state.get("current_plan", "") or ""),
                plan_progress=str(state.get("plan_progress", "") or ""),
                state=state,
            )
            selected_for_install = state.get("active_skills", []) or []
            narrowed_for_step = self._narrow_skills_to_current_plan_step(selected_for_install, task_id)
            if narrowed_for_step != self._selected_skill_ids(selected_for_install):
                previous_skills = ", ".join(self._selected_skill_ids(selected_for_install)) or "None"
                selected_for_install = narrowed_for_step
                if narrowed_for_step:
                    context_summary += (
                        "\n\n[INSTALL TARGET STEP GUARD]\n"
                        f"- Previous active skills: {previous_skills}\n"
                        f"- Current plan step declared skill(s): {', '.join(narrowed_for_step)}\n"
                        "- Installation is restricted to the current plan step.\n"
                    )
            if not selected_for_install:
                plan_progress = self._record_plan_current_evidence(
                    task_id,
                    "install_without_step_skill",
                    "Installer refused to fall back from current-step ACTIVE_SKILLS to task-wide SELECTED_SKILLS.",
                )
                return {
                    "messages": [
                        SystemMessage(
                            content=(
                                "Installer has no skill assigned by the current plan step. "
                                "Return to Planner and add the intended canonical skill to this step's `Skills:` field; "
                                "do not install from the task-wide selected pool."
                            )
                        )
                    ],
                    "plan_progress": plan_progress,
                    "next_step": "generate",
                }
            if current_plan_for_install:
                context_summary += f"\n\nCurrent approved step:\n{current_plan_for_install}"
            runtime_defaults = self._skill_runtime_defaults(selected_for_install)
            if self.skill_manager and selected_for_install:
                skill_ctx = self.skill_manager.load_skills_for_prompt(selected_for_install)
                cards = self._skill_execution_context(selected_for_install)
                if skill_ctx or cards:
                    context_summary += (
                        "\n\nSelected skill runtime context:\n"
                        f"{self._clip_prompt_text(cards, 5000)}\n"
                        f"{self._clip_prompt_text(skill_ctx, 4000)}"
                    )

            match = re.search(r"<install_tool(?:\s+env=[\"'](.*?)[\"'])?>(.*?)</install_tool>", last_msg, re.DOTALL)
            if self._pending_action_is(pending_action, "install_tool"):
                specified_env = str(pending_action.get("env") or "").strip() or None
                raw_tool_name = str(pending_action.get("tool") or "").strip() or runtime_defaults.get("tool_name", "skill_runtime")
            else:
                specified_env = match.group(1) if match else None
                raw_tool_name = match.group(2).strip() if match else runtime_defaults.get("tool_name", "skill_runtime")
            tool_name, inner_env = self._install_tool_parts(raw_tool_name, specified_env or runtime_defaults.get("env", ""))
            if inner_env and not specified_env:
                specified_env = inner_env
            if not tool_name or tool_name == "unknown":
                tool_name = runtime_defaults.get("tool_name", "skill_runtime")
            install_context_text = self._clip_prompt_text(
                "\n".join(part for part in [last_msg, context_summary] if part),
                LLM_STEP_CONTEXT_CHARS,
            )
            inferred_for_install = self._executable_runtime_skills(
                self._infer_runtime_skills_from_code(install_context_text, selected_for_install)
            )
            if inferred_for_install and inferred_for_install != self._selected_skill_ids(selected_for_install):
                previous_skills = ", ".join(self._selected_skill_ids(selected_for_install)) or "None"
                selected_for_install = inferred_for_install
                runtime_defaults = self._skill_runtime_defaults(selected_for_install)
                context_summary += (
                    "\n\n[INSTALL TARGET RESOLUTION]\n"
                    f"- Previous active/selected skills: {previous_skills}\n"
                    f"- Resolved executable runtime skill(s) from failed tool/context: {', '.join(inferred_for_install)}\n"
                    "- Workflow/router skills are not installable runtimes; repair the concrete executable skill runtime.\n"
                )
                if self.skill_manager:
                    resolved_cards = self._skill_execution_context(selected_for_install)
                    resolved_docs = self.skill_manager.load_skills_for_prompt(selected_for_install)
                    context_summary += (
                        "\n\nResolved executable skill runtime context:\n"
                        f"{self._clip_prompt_text(resolved_cards, 5000)}\n"
                        f"{self._clip_prompt_text(resolved_docs, 4000)}"
                    )
            owner_skill = self._runtime_owner_skill_for_install(tool_name, selected_for_install)
            if owner_skill:
                runtime_defaults = self._skill_runtime_defaults([owner_skill])
            selected_skills = runtime_defaults.get("selected", []) or []
            tool_name, correction_note = self._sanitize_install_tool_for_selected_runtime(
                tool_name,
                selected_skills,
                runtime_defaults,
                specified_env or runtime_defaults.get("env", ""),
            )
            if correction_note:
                context_summary += "\n\n" + correction_note
                last_msg = re.sub(r"\bcalder_r_runtime\b", tool_name, last_msg)
            explicit_runtime_repair = self._explicit_runtime_repair_kind(tool_name, last_msg)
            choice_key = self._install_choice_key(task_id, tool_name)
            static_skill_env = self._skill_static_default_env(selected_skills[0]) if selected_skills else ""

            if static_skill_env:
                default_env = static_skill_env
                if specified_env and specified_env not in {static_skill_env, "default"}:
                    context_summary += (
                        f"\n\n[INSTALL ENV OVERRIDE NOTICE]\n"
                        f"- Selected skill default_env: {static_skill_env}\n"
                        f"- Generated install tag requested env: {specified_env}\n"
                        f"- Prefer the selected skill default_env unless the user explicitly overrides it.\n"
                    )
            else:
                default_env = specified_env if specified_env and specified_env != "default" else (
                    runtime_defaults.get("env") or f"bio_{tool_name}"
                )

            registered_reuse = {}
            if not explicit_runtime_repair:
                registered_reuse = self._reuse_registered_runtime_for_install(
                    selected_skills or selected_for_install,
                    specified_env,
                    task_id,
                )
            if registered_reuse.get("ok"):
                final_res = registered_reuse["message"]
                self.profiler.record_skill_usage(
                    task_id,
                    selected_skills or selected_for_install,
                    usage_type="installed_runtime",
                    node="install_subagent",
                    detail=registered_reuse.get("env", ""),
                )
                plan_progress = self._mark_plan_current_done(task_id, final_res)
                self._record_installed_skill_environment(selected_skills or selected_for_install, registered_reuse["env"], final_res)
                await self._observe_session_memory(
                    task_id,
                    "install_subagent",
                    state.get("messages", []) + [AIMessage(content=f"<observation>{final_res}</observation>")],
                    {
                        "tool_name": tool_name,
                        "target_env": registered_reuse["env"],
                        "result": final_res,
                        "plan_progress": plan_progress,
                        "runtime_status": self._runtime_status_for_task(task_id),
                    },
                )
                return {
                    "messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id),
                    "next_step": self._next_step_after_install_result(task_id),
                }
            if registered_reuse and registered_reuse.get("env"):
                default_env = registered_reuse["env"]
                context_summary += (
                    f"\n\n[REGISTERED RUNTIME CHECK]\n"
                    f"- Registered environment: {registered_reuse['env']}\n"
                    f"- Healthcheck failed: {registered_reuse.get('detail', 'unknown')}\n"
                    f"- Repair or reinstall this same environment. Do not create a duplicate environment unless the user explicitly overrides the env name.\n"
                )
            reuse_match = None
            if self.pm and not explicit_runtime_repair and any([
                runtime_defaults.get("packages"),
                runtime_defaults.get("capabilities"),
                runtime_defaults.get("language"),
            ]):
                reuse_match = self.pm.find_matching_environment({
                    "language": runtime_defaults.get("language", ""),
                    "packages": runtime_defaults.get("packages", []),
                    "capabilities": runtime_defaults.get("capabilities", []),
                })
                if reuse_match and reuse_match.get("match_type") == "exact":
                    ok, detail = self.pm.verify_environment(
                        env_name=reuse_match["env"],
                        language=runtime_defaults.get("language", ""),
                        healthcheck=runtime_defaults.get("healthcheck", ""),
                    )
                    if ok:
                        final_res = (
                            f"✅ Reusing existing environment '{reuse_match['env']}' for "
                            f"{', '.join(runtime_defaults.get('selected', []) or [tool_name])}."
                        )
                        self.profiler.record_skill_usage(
                            task_id,
                            selected_skills or selected_for_install,
                            usage_type="installed_runtime",
                            node="install_subagent",
                            detail=reuse_match.get("env", ""),
                        )
                        plan_progress = self._mark_plan_current_done(task_id, final_res)
                        self._record_installed_skill_environment(selected_skills or selected_for_install, reuse_match["env"], final_res)
                        await self._observe_session_memory(
                            task_id,
                            "install_subagent",
                            state.get("messages", []) + [AIMessage(content=f"<observation>{final_res}</observation>")],
                            {
                                "tool_name": tool_name,
                                "target_env": reuse_match["env"],
                                "result": final_res,
                                "plan_progress": plan_progress,
                                "runtime_status": self._runtime_status_for_task(task_id),
                            },
                        )
                        return {
                            "messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                            "plan_progress": plan_progress,
                            "runtime_status": self._runtime_status_for_task(task_id),
                            "next_step": "generate",
                        }
                    context_summary += (
                        f"\n\n[ENVIRONMENT CHECK]\n"
                        f"- Existing matching environment: {reuse_match['env']}\n"
                        f"- Healthcheck failed: {detail}\n"
                        f"- Please repair or reinstall this environment instead of creating a duplicate.\n"
                    )
                    default_env = reuse_match["env"]
                elif reuse_match and reuse_match.get("match_type") == "partial":
                    missing_packages = ", ".join(reuse_match.get("missing_packages", [])) or "none"
                    missing_caps = ", ".join(reuse_match.get("missing_capabilities", [])) or "none"
                    context_summary += (
                        f"\n\n[ENVIRONMENT REUSE CANDIDATE]\n"
                        f"- Reuse and extend environment: {reuse_match['env']}\n"
                        f"- Missing packages: {missing_packages}\n"
                        f"- Missing capabilities: {missing_caps}\n"
                        f"- Prefer extending this environment instead of creating a new one.\n"
                    )
                    default_env = reuse_match["env"]
            cached_env = self._install_env_choices.get(choice_key)
            if cached_env:
                target_env = cached_env
            elif specified_env and (not runtime_defaults.get("env") or specified_env == runtime_defaults.get("env")):
                target_env = specified_env
            else:
                print(f"\n{Fore.CYAN}❓ Confirm environment for {tool_name}?{Style.RESET_ALL}")
                user_choice = interrupt({
                    "type": "env_selection",
                    "tool_name": tool_name,
                    "default_env": default_env,
                    "reason": "Confirm or override the environment before installation.",
                })
                target_env = user_choice.strip() if isinstance(user_choice, str) and user_choice.strip() else default_env
            self._install_env_choices[choice_key] = target_env
            attempt_key = f"{choice_key}::{target_env}"
            sub_config = {"configurable": {"thread_id": f"{task_id}_installer_{tool_name}"}}
            installer_snapshot = self.installer_app.get_state(sub_config)
            installer_has_pending_interrupt = bool(
                installer_snapshot.tasks and installer_snapshot.tasks[0].interrupts
            )
            if not installer_has_pending_interrupt:
                self._install_attempt_counts[attempt_key] = self._install_attempt_counts.get(attempt_key, 0) + 1
            scope_key = ""
            if explicit_runtime_repair:
                skill_scope = ",".join(selected_skills or selected_for_install or [tool_name])
                scope_key = f"{task_id}::runtime_repair::{explicit_runtime_repair}::{target_env}::{skill_scope}"
                if not installer_has_pending_interrupt:
                    self._install_scope_attempt_counts[scope_key] = self._install_scope_attempt_counts.get(scope_key, 0) + 1
                if self._install_scope_attempt_counts.get(scope_key, 0) > 2:
                    final_res = (
                        f"blocked: repeated runtime repair loop detected for `{explicit_runtime_repair}` in "
                        f"`{target_env}` after {self._install_scope_attempt_counts[scope_key]} attempts. "
                        "The root cause is still unresolved; do not switch to another conda environment or rerun "
                        "availability checks as a substitute for installation. Repair the selected runtime or ask "
                        "the user to install/register it explicitly."
                    )
                    plan_progress = self._mark_plan_current_blocked(task_id, final_res)
                    self._install_env_choices.pop(choice_key, None)
                    await self._observe_session_memory(
                        task_id,
                        "install_subagent",
                        state.get("messages", []) + [AIMessage(content=f"<observation>{final_res}</observation>")],
                        {
                            "tool_name": tool_name,
                            "target_env": target_env,
                            "result": final_res,
                            "plan_progress": plan_progress,
                            "runtime_status": self._runtime_status_for_task(task_id),
                        },
                    )
                    return {
                        "messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                        "plan_progress": plan_progress,
                        "runtime_status": self._runtime_status_for_task(task_id),
                        "next_step": self._next_step_after_install_result(task_id),
                    }
            if self._install_attempt_counts.get(attempt_key, 0) > 2:
                final_res = (
                    f"blocked: repeated installation loop detected for `{tool_name}` in environment "
                    f"`{target_env}` after {self._install_attempt_counts[attempt_key]} attempts. "
                    "Run the skill runtime healthcheck directly and continue execution if it passes; "
                    "do not re-enter INSTALL_SUBAGENT for the same target."
                )
                plan_progress = self._mark_plan_current_blocked(task_id, final_res)
                self._install_env_choices.pop(choice_key, None)
                await self._observe_session_memory(
                    task_id,
                    "install_subagent",
                    state.get("messages", []) + [AIMessage(content=f"<observation>{final_res}</observation>")],
                    {
                        "tool_name": tool_name,
                        "target_env": target_env,
                        "result": final_res,
                        "plan_progress": plan_progress,
                        "runtime_status": self._runtime_status_for_task(task_id),
                    },
                )
                return {
                    "messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id),
                    "next_step": self._next_step_after_install_result(task_id),
                }

            if explicit_runtime_repair:
                context_summary += self._runtime_repair_context(explicit_runtime_repair, target_env)

            install_command_context = self._selected_skill_install_command_context(runtime_defaults, target_env)
            if install_command_context:
                context_summary += install_command_context

            packages = [] if explicit_runtime_repair else runtime_defaults.get("packages", [])
            if packages:
                context_summary += (
                    f"\n\n[INSTALL TARGET OVERRIDE]\n"
                    f"- target_env: {target_env}\n"
                    f"- language: {runtime_defaults.get('language', 'python') or 'python'}\n"
                    f"- requested packages: {', '.join(packages)}\n"
                    f"- requested capabilities: {', '.join(runtime_defaults.get('capabilities', []) or []) or 'none'}\n"
                    f"- The target_env above overrides any default_env written in the skill docs for this installation.\n"
                    f"- Create/use `{target_env}`, install the packages there, and register the environment before any tool registration.\n"
                )

            print(f"\n{Fore.CYAN}🔧 INSTALLER: {tool_name} → {target_env}{Style.RESET_ALL}")

            initial_msg = INSTALLER_HANDOVER_TEMPLATE.format(
                user_context=context_summary, rag_context="",
                tool_name=tool_name, target_env=target_env,
                env_instruction=f"Target environment: {target_env}",
            )

            final_res    = "Installation Failed"
            snapshot     = installer_snapshot
            current_payload = None if installer_has_pending_interrupt \
                else {
                    "tool_name": tool_name,
                    "task_id": task_id,
                    "selected_skills": selected_skills or selected_for_install,
                    "messages": [HumanMessage(content=initial_msg)],
                }

            while True:
                if current_payload:
                    async for event in self.installer_app.astream(current_payload, config=sub_config):
                        for node_name, update in event.items():
                            if "messages" in update:
                                last_m = update["messages"][-1]
                                if isinstance(last_m, AIMessage):
                                    output.print_once(f"inst:{last_m.content[:40]}",
                                                      f"[Installer] {last_m.content[:200]}", Fore.MAGENTA)
                            if "final_result" in update:
                                final_res = update["final_result"]

                snapshot = self.installer_app.get_state(sub_config)
                if not snapshot.next and (not snapshot.tasks or not snapshot.tasks[0].interrupts):
                    break
                if snapshot.tasks and snapshot.tasks[0].interrupts:
                    sub_iv = snapshot.tasks[0].interrupts[0].value
                    user_resp = interrupt(sub_iv)
                    current_payload = Command(resume=user_resp)
                    continue
                break

            self.profiler.record_skill_usage(
                task_id,
                selected_skills or selected_for_install,
                usage_type="installed_runtime",
                node="install_subagent",
                detail=target_env,
            )
            final_res_lower = str(final_res).lower()
            install_success = not any(
                marker in final_res_lower
                for marker in ("failed", "❌", "blocked", "loop detected", "exceeded")
            )
            if selected_skills or selected_for_install:
                recheck_failures = []
                recheck_successes = []
                for sid in self._selected_skill_ids(selected_skills or selected_for_install):
                    ok, detail, verified_env = self._verify_skill_runtime(
                        sid,
                        task_id=task_id,
                        use_cache=False,
                    )
                    if not ok:
                        recheck_failures.append(
                            f"{sid} in `{verified_env or target_env}` failed healthcheck: {detail or 'Healthcheck failed.'}"
                        )
                    else:
                        recheck_successes.append(
                            f"{sid} in `{verified_env or target_env}` passed healthcheck: {detail or 'Healthcheck passed.'}"
                        )
                if recheck_successes and not recheck_failures:
                    install_success = True
                    if any(marker in final_res_lower for marker in ("failed", "❌", "blocked", "loop detected", "exceeded")):
                        final_res = (
                            "✅ Installation/runtime is usable after direct skill healthcheck.\n"
                            + "\n".join(f"- {item}" for item in recheck_successes)
                            + "\n\nOriginal installer final message was overridden because the verified runtime healthcheck passed:\n"
                            + str(final_res)[:1500]
                        )
                elif recheck_failures:
                    install_success = False
                    final_res = (
                        f"{final_res}\n\n"
                        "Post-install skill runtime healthcheck failed:\n"
                        + "\n".join(f"- {item}" for item in recheck_failures)
                    )
            if install_success:
                self._install_env_choices.pop(choice_key, None)
                self._install_attempt_counts.pop(attempt_key, None)
                if scope_key:
                    self._install_scope_attempt_counts.pop(scope_key, None)
            if install_success:
                self._record_installed_skill_environment(selected_skills or selected_for_install, target_env, final_res)
                plan_progress = self._mark_plan_current_done(task_id, str(final_res)[:1000])
            else:
                install_command = runtime_defaults.get("install_command", "")
                blocked_note = (
                    f"{final_res}\n\n"
                    "blocked: required runtime installation did not complete. "
                    "Do not retry the same healthcheck or fabricate outputs."
                )
                if install_command:
                    blocked_note += f"\nSuggested install command: {install_command}"
                final_res = blocked_note
                plan_progress = self._mark_plan_current_blocked(task_id, f"install_failed: {str(final_res)[:1000]}")
            await self._observe_session_memory(
                task_id,
                "install_subagent",
                state.get("messages", []) + [AIMessage(content=f"<observation>{final_res}</observation>")],
                {
                    "tool_name": tool_name,
                    "target_env": target_env,
                    "result": final_res[:3000],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id),
                },
            )
            output.print_observation(f"<observation>{final_res}</observation>")

            return {"messages": [AIMessage(content=f"<observation>{final_res}</observation>")],
                    "plan_progress": plan_progress,
                    "runtime_status": self._runtime_status_for_task(task_id),
                    "next_step": self._next_step_after_install_result(task_id)}

        # ════════════════════════════════════════════
        # 节点注册 & 连线
        # ════════════════════════════════════════════
        profiled_nodes = {
            "triage": self._profile_node("triage", triage),
            "direct_chat": self._profile_node("direct_chat", direct_chat),
            "consultant": self._profile_node("consultant", consultant),
            "ask_user": self._profile_node("ask_user", ask_user),
            "planner": self._profile_node("planner", planner),
            "plan_review": self._profile_node("plan_review", plan_review),
            "generate": self._profile_node("generate", generate),
            "execute": self._profile_node("execute", execute_node),
            "supervisor": self._profile_node("supervisor", supervisor),
            "supervisor_final_audit": self._profile_node(
                "supervisor_final_audit", supervisor_final_audit
            ),
            "install_subagent": self._profile_node("install_subagent", install_subagent),
        }
        # Expose the exact registered wrappers to integration tests.  Tests do
        # not receive a parallel implementation of routing or persistence.
        self._graph_node_handlers = profiled_nodes
        for node_name, handler in profiled_nodes.items():
            workflow.add_node(node_name, handler)

        workflow.add_edge(START, "triage")

        def triage_router(state):
            step = state.get("next_step")
            if step == "direct_chat": return "direct_chat"
            if step == "generate":    return "generate"
            if step == "execute":     return "execute"
            if step == "planner":     return "planner"
            if step == "plan_review": return "plan_review"
            if step == "ask_user":    return "ask_user"
            if step == "waiting_user": return END
            if step == "finish":      return END
            if step == "supervisor_final_audit": return "supervisor_final_audit"
            return "consultant"

        workflow.add_conditional_edges("triage", triage_router,
                                       ["direct_chat", "generate", "execute", "planner", "plan_review", "ask_user", "consultant", "supervisor_final_audit", END])
        workflow.add_edge("direct_chat", END)

        def consultant_router(state):
            step = state.get("next_step")
            if step == "planner":     return "planner"
            if step == "generate":    return "generate"
            if step == "ask_user":    return "ask_user"
            if step == "human_input": return END
            if step == "finish":      return END
            return "consultant"

        workflow.add_conditional_edges("consultant", consultant_router,
                                       ["planner", "generate", "ask_user", "consultant", END])

        def ask_user_router(state):
            step = state.get("next_step")
            if step == "generate": return "generate"
            if step == "planner": return "planner"
            return "consultant"

        workflow.add_conditional_edges("ask_user", ask_user_router,
                                       ["generate", "planner", "consultant"])

        def planner_router(state):
            step = state.get("next_step")
            if step == "consultant": return "consultant"
            if step == "planner": return "planner"
            if step == "generate": return "generate"
            if step == "finish": return END
            return "plan_review"

        workflow.add_conditional_edges("planner", planner_router,
                                       ["consultant", "planner", "generate", "plan_review", END])

        def install_subagent_router(state):
            step = state.get("next_step", "generate")
            if step == "finish": return END
            if step == "human_input": return END
            return "generate"

        workflow.add_conditional_edges("install_subagent", install_subagent_router,
                                       ["generate", END])

        def plan_review_router(state):
            step = state.get("next_step")
            if step == "consultant": return "consultant"
            if step == "planner": return "planner"
            if step == "ask_user": return "ask_user"
            if step == "finish":  return END
            if step == "human_input": return END
            return "generate"

        workflow.add_conditional_edges("plan_review", plan_review_router,
                                       ["generate", "consultant", "planner", "ask_user", END])

        runtime_destinations = [
            "consultant", "planner", "ask_user", "execute", "install_subagent",
            "supervisor", "supervisor_final_audit", "generate", END,
        ]

        def dispatch_runtime_route(state, source_node):
            route = self._dispatch_effective_route(state, source_node)
            if route == "finish":
                return END
            if route in {
                "consultant", "planner", "ask_user", "execute", "install_subagent",
                "supervisor", "supervisor_final_audit", "generate",
            }:
                return route
            logger.error(
                "RUNTIME_DISPATCH_TARGET_INVALID source=%s route=%s",
                source_node,
                route,
            )
            return END

        def generate_router(state):
            return dispatch_runtime_route(state, "generate")

        workflow.add_conditional_edges("generate", generate_router,
                                       runtime_destinations)

        # execute → supervisor → generate（managed 核心链路）；轻量任务直接结束。
        def execute_router(state):
            return dispatch_runtime_route(state, "execute")

        workflow.add_conditional_edges("execute", execute_router,
                                       runtime_destinations)

        def supervisor_router(state):
            durable_failure = (
                dict(state.get("failure") or {})
                if isinstance(state.get("failure"), Mapping)
                else {}
            )
            if (
                str(
                    durable_failure.get("stage")
                    or durable_failure.get("failure_stage")
                    or ""
                ) == "pre_action_contract"
                and durable_failure.get("execution_started") is False
            ):
                return END
            return dispatch_runtime_route(state, "supervisor")

        workflow.add_conditional_edges("supervisor", supervisor_router,
                                       runtime_destinations)

        def final_audit_router(state):
            return dispatch_runtime_route(state, "supervisor_final_audit")

        workflow.add_conditional_edges("supervisor_final_audit", final_audit_router,
                                       runtime_destinations)

        return workflow.compile(checkpointer=self.checkpointer)

    # ────────────────────────────────────────────────────────────
    #  主运行入口
    # ────────────────────────────────────────────────────────────

    def _messages_for_memory_status(self, task_id: str, config: Dict[str, Any], runner_input: Any) -> List[BaseMessage]:
        """Return the best available message list for the memory pressure display."""
        try:
            snapshot = self.app.get_state(config)
            values = snapshot.values if snapshot and snapshot.values else {}
            messages = values.get("messages", []) if isinstance(values, dict) else []
            if messages:
                return list(messages)
        except Exception:
            pass
        if isinstance(runner_input, dict):
            return list(runner_input.get("messages", []) or [])
        return []

    @staticmethod
    def _snapshot_values(snapshot: Any) -> Dict[str, Any]:
        values = getattr(snapshot, "values", None)
        return values if isinstance(values, dict) else {}

    @staticmethod
    def _snapshot_next_step(snapshot: Any) -> str:
        return str(BioAnalystAgent._snapshot_values(snapshot).get("next_step") or "").strip()

    @staticmethod
    def _messages_terminal_text(messages: Any) -> str:
        parts: List[str] = []
        for message in list(messages or [])[-3:]:
            content = str(getattr(message, "content", message) or "").strip()
            if content:
                parts.append(content)
        return "\n".join(parts)

    @staticmethod
    def _terminal_status_from_text(text: str) -> str:
        normalized = str(text or "").strip()
        plain = re.sub(r"</?[^>]+>", "", normalized).strip()
        lowered = plain.lower()
        if not lowered:
            return ""
        if lowered in {"cancelled.", "cancelled", "task terminated."}:
            return "cancelled"
        if (
            lowered.startswith("blocked:")
            or "\nblocked:" in lowered
            or "required runtime installation did not complete" in lowered
            or "loop detected" in lowered
        ):
            return "blocked"
        if (
            "❌" in plain
            or "task stopped before the next generated action" in lowered
            or "llm request_failed" in lowered
            or "llm input_rejected" in lowered
            or "the llm call failed" in lowered
            or lowered.startswith(("failed", "error:"))
            or "\nfailed" in lowered
            or "\nerror:" in lowered
        ):
            return "failed"
        return ""

    def _terminal_status_from_plan(self, task_id: str, values: Optional[Dict[str, Any]] = None) -> str:
        try:
            state = load_plan_state(self.data_path, task_id)
        except Exception:
            state = {}
        durable_status = task_status(state)
        if durable_status in TASK_TERMINAL_STATUSES:
            return durable_status
        steps = [step for step in state.get("steps", []) or [] if isinstance(step, dict)]
        if steps:
            statuses = {str(step.get("status") or "").strip().lower() for step in steps}
            if statuses & {"blocked", "failed", "skipped_upstream_blocked"}:
                return "blocked"
            if statuses <= {"done", "passed", "skipped", "cancelled"}:
                return "completed"
            return "blocked"

        plan_progress = str((values or {}).get("plan_progress") or "")
        if "- [!]" in plan_progress or "Next step: BLOCKED:" in plan_progress:
            return "blocked"
        return ""

    def _terminal_status_from_snapshot(self, task_id: str, snapshot: Any) -> str:
        values = self._snapshot_values(snapshot)
        if str(values.get("recovery_status") or "") == "paused_retryable":
            return "paused_retryable"
        if self._snapshot_next_step(snapshot) == "human_input" or self._business_waiting_state(load_waiting_state(self.data_path, task_id)):
            return "waiting_user"
        try:
            durable_plan = load_plan_state(self.data_path, task_id)
        except Exception:
            durable_plan = {}
        durable_consultation = dict(
            (durable_plan.get("task_state") or {}).get("consultation_state")
            or {}
        )
        consultation_state = (
            values.get("consultation_state") or durable_consultation or {}
        )
        if isinstance(consultation_state, Mapping):
            finalize_protocol = consultation_state.get("finalize_protocol") or {}
            finalize_status = (
                str(
                    finalize_protocol.get("finalize_status")
                    or finalize_protocol.get("status")
                    or ""
                ).strip().lower()
                if isinstance(finalize_protocol, Mapping)
                else ""
            )
            if (
                str(consultation_state.get("phase") or "").strip().lower() == "blocked"
                or str(consultation_state.get("consultation_status") or "").strip().lower()
                == "blocked"
                or str(consultation_state.get("completion_decision") or "").strip().lower()
                == "blocked"
                or finalize_status
                in {"blocked", "blocked_internal_contract", "blocked_internal_provider"}
            ):
                return "blocked"
            if isinstance(finalize_protocol, Mapping):
                schema = int(finalize_protocol.get("schema_version") or 0)
                compile_outcome = dict(
                    finalize_protocol.get("compile_outcome") or {}
                )
                compiled = bool(
                    (
                        schema == 4
                        and finalize_status == "compiled"
                        and str(compile_outcome.get("status") or "")
                        == "compiled"
                    )
                    or (
                        schema in {2, 3}
                        and finalize_status == "compiled"
                    )
                )
                owner_present = bool(
                    finalize_protocol
                    or str(consultation_state.get("phase") or "")
                    .strip().lower() == "finalize"
                )
                if owner_present and not compiled:
                    # Graph END while FINALIZE still owns the task is a typed
                    # incomplete terminal projection, never completion.
                    return "blocked"
        snapshot_task_status = str(values.get("task_status") or "").strip().lower()
        if snapshot_task_status in TASK_TERMINAL_STATUSES:
            return snapshot_task_status

        plan_status = self._terminal_status_from_plan(task_id, values)
        if plan_status:
            return plan_status

        text_status = self._terminal_status_from_text(
            self._messages_terminal_text(values.get("messages", []))
        )
        if text_status:
            return text_status
        # Graph END is not proof of business completion.  Missing terminal
        # evidence must fail closed so resume/Wiki cannot inherit an optimistic
        # state-manager projection.
        return "blocked"

    @staticmethod
    def _first_structured_text(
        records: Sequence[Mapping[str, Any]],
        keys: Sequence[str],
    ) -> str:
        for record in records:
            for key in keys:
                value = record.get(key)
                if isinstance(value, (str, int, float)) and str(value).strip():
                    return str(value).strip()
        return ""

    def _interactive_run_result(
        self,
        task_id: str,
        status: str,
        snapshot: Any = None,
        *,
        exception: Optional[BaseException] = None,
    ) -> InteractiveRunResult:
        """Project terminal details only from structured state and artifacts."""
        values = self._snapshot_values(snapshot)
        try:
            durable_plan = load_plan_state(self.data_path, task_id)
        except Exception:
            durable_plan = {}
        task_state = dict(durable_plan.get("task_state") or {})
        task_root = Path(self.data_path) / "task_outputs" / str(task_id)
        metrics_path = task_root / "run_metrics.json"
        trace_path = task_root / "context_trace" / "events.jsonl"
        try:
            metrics = json.loads(metrics_path.read_text(encoding="utf-8"))
            if not isinstance(metrics, dict):
                metrics = {}
        except (OSError, TypeError, json.JSONDecodeError):
            metrics = {}

        records: List[Mapping[str, Any]] = []

        def add_record(value: Any) -> None:
            if isinstance(value, Mapping) and value:
                records.append(value)

        for key in ("terminal_diagnostic", "completion_gate_result"):
            add_record(values.get(key))
        final_result = dict(metrics.get("final_result") or {})
        add_record(final_result.get("terminal_diagnostic"))
        add_record(final_result)
        add_record(metrics.get("terminal_diagnostic"))
        if status in {"failed", "blocked"} or exception is not None:
            for key in (
                "failure",
                "skill_decision_result",
                "canonical_commit",
            ):
                add_record(values.get(key))
            add_record(task_state.get("failure"))
            planning_failure = dict(task_state.get("planning_failure") or {})
            add_record(planning_failure.get("terminal_diagnostic"))
            add_record(planning_failure)
            add_record(task_state.get("consultant_commit_rejection"))
            pending_transition = dict(
                task_state.get("consultant_pending_transition") or {}
            )
            if pending_transition.get("terminal") is True:
                add_record(pending_transition)
            add_record(final_result.get("failure"))
            add_record(metrics.get("failure"))

        transition = dict(task_state.get("last_transition") or {})
        add_record(transition)
        stage = self._first_structured_text(
            records,
            ("stage", "failure_stage", "source_node", "from_node", "owner"),
        )
        failure_code = (
            self._first_structured_text(
                records,
                ("failure_code", "error_code", "code", "reason_code"),
            )
            if status in {"failed", "blocked"} or exception is not None
            else ""
        )
        reason = self._first_structured_text(
            records,
            ("reason", "message", "error", "summary", "detail"),
        )
        result_path = self._first_structured_text(
            records,
            (
                "result_path",
                "output_path",
                "artifact_path",
                "report_path",
                "plan_path",
            ),
        )
        if exception is not None:
            failure_code = failure_code or type(exception).__name__
            reason = reason or str(exception)
            stage = stage or "runtime"
        if status in {"failed", "blocked"} and not failure_code:
            failure_code = "TERMINAL_EVIDENCE_MISSING"
        if status == "completed":
            stage = stage or "finalize"
            reason = reason or "Task completed."
        elif status == "waiting_user":
            waiting = load_waiting_state(self.data_path, task_id) or {}
            stage = stage or str(waiting.get("stage") or "human_input")
            reason = reason or str(waiting.get("prompt") or "Waiting for user input.")
        elif status == "cancelled":
            reason = reason or "Task cancelled by user."
        elif status == "interrupted":
            reason = reason or "Interactive execution interrupted."

        if not result_path and metrics_path.exists():
            result_path = str(metrics_path)
        return InteractiveRunResult(
            task_id=str(task_id),
            status=str(status or "blocked"),
            stage=stage,
            failure_code=failure_code,
            reason=reason,
            result_path=result_path,
            trace_path=str(trace_path) if trace_path.exists() else "",
        )

    async def go(
        self,
        input_data: Any,
        task_id: Optional[str] = None,
        resume: bool = False,
        structured_source: Optional[Dict[str, Any]] = None,
    ):
        if not task_id:
            task_id = self._auto_task_id_for_prompt(input_data) or f"task_{int(time.time())}"
        output.reset_for_task()
        if not isinstance(input_data, Command) and not resume:
            output.print_once(
                f"task_accepted:{task_id}",
                f"● Task accepted: {task_id}",
                Fore.GREEN,
            )
        config = {"configurable": {"thread_id": task_id}}
        self.profiler.start_task(task_id)
        self._record_initial_profiler_metadata(task_id, input_data)
        self._sync_runtime_registries_at_startup()

        if isinstance(input_data, Command):
            runner_input = input_data
            print(f"\n🔄 Resuming: {task_id}")
        else:
            prompt = input_data
            project_id = self.default_project_id
            if resume:
                try:
                    checkpoint = self.app.get_state(config)
                    checkpoint_values = self._snapshot_values(checkpoint)
                except Exception:
                    checkpoint_values = {}
                runner_input = self._build_resume_runner_state(task_id, prompt, checkpoint_values)
                print(f"\n🔄 Resuming: {task_id}")
            else:
                stable_record = self._get_or_create_stable_prompt(task_id, project_id)
                durable_start, is_continuation, _ = self._persist_user_submission(
                    task_id,
                    prompt,
                    structured_source=structured_source,
                )
                if not is_continuation:
                    self.task_summary_renderer.initialize_task(
                        task_id,
                        str(prompt),
                        status="running",
                        authoritative_new_task=True,
                    )
                    if self.state_manager:
                        self.state_manager.create_task(task_id, prompt)
                conversation_evidence = dict(
                    durable_start.get("conversation_evidence") or {}
                )
                durable_task_spec = canonical_task_spec_for_state(durable_start)
                durable_task_state = dict(durable_start.get("task_state") or {})
                runner_input = {
                    "messages": [HumanMessage(
                        content=prompt,
                        additional_kwargs={
                            "message_origin": "user",
                            "structured_source": dict(structured_source or {}),
                        },
                    )],
                    "task_id": task_id,
                    "session_id": task_id,
                    "project_id": project_id,
                    "stable_system_prompt": stable_record["prompt"],
                    "core_memory_loaded_at": stable_record["core_memory_loaded_at"],
                    "runtime_status": self._runtime_status_for_task(task_id),
                    "conversation_evidence": conversation_evidence,
                    "task_spec": deepcopy(durable_task_spec),
                    "task_revision": task_spec_revision(durable_task_spec),
                    "selected_skills": list(
                        durable_task_state.get("selected_skills") or []
                    ),
                    "resolved_bindings": deepcopy(dict(
                        durable_task_state.get("resolved_bindings") or {}
                    )),
                    "consultation_state": deepcopy(dict(
                        durable_task_state.get("consultation_state") or {}
                    )),
                    "planner_feedback": deepcopy(dict(
                        durable_task_state.get("planner_feedback") or {}
                    )),
                }
                if is_continuation:
                    print(f"\n↪ Continuing: {task_id}")

        # 内存状态展示
        self.memory_manager.print_status(
            self._messages_for_memory_status(task_id, config, runner_input)
        )

        with self.profiler.task_context(task_id):
            try:
                async for event in self.app.astream(runner_input, config=config):
                    self.profiler.heartbeat(task_id)
            except asyncio.CancelledError:
                self.profiler.finish_for_exception(task_id, asyncio.CancelledError())
                raise
            except TimeoutError as exc:
                self.profiler.finish_for_exception(task_id, exc)
                raise
            except KeyboardInterrupt as exc:
                self.profiler.finish_for_exception(task_id, exc)
                raise
            except BaseException as exc:
                self.profiler.finish_for_exception(task_id, exc)
                raise
            finally:
                self.profiler.flush(task_id)

    async def _run_agent_interrupt_loop(
        self,
        initial_input: Any,
        task_id: str,
        *,
        resume_initial: bool = False,
    ) -> InteractiveRunResult:
        """Run a fresh or resumed task until terminal state or saved user wait."""
        next_input = initial_input
        while True:
            try:
                await self.go(
                    next_input,
                    task_id=task_id,
                    resume=resume_initial or isinstance(next_input, Command),
                )
            except (KeyboardInterrupt, asyncio.CancelledError):
                raise
            except BaseException as exc:
                try:
                    failed_snapshot = self.app.get_state(
                        {"configurable": {"thread_id": task_id}}
                    )
                except Exception:
                    failed_snapshot = None
                self.profiler.finish_task(task_id, "failed")
                return self._interactive_run_result(
                    task_id,
                    "failed",
                    failed_snapshot,
                    exception=exc,
                )
            resume_initial = False
            config = {"configurable": {"thread_id": task_id}}
            snapshot = self.app.get_state(config)

            if not (snapshot.tasks and snapshot.tasks[0].interrupts):
                terminal_status = self._terminal_status_from_snapshot(task_id, snapshot)
                if terminal_status == "waiting_user":
                    if self.state_manager:
                        self.state_manager.update_task_status(task_id, "waiting_user")
                    self.profiler.finish_task(task_id, "waiting_user")
                    return self._interactive_run_result(
                        task_id,
                        terminal_status,
                        snapshot,
                    )
                if self.state_manager:
                    try:
                        self.state_manager.update_task_status(task_id, terminal_status)
                    except Exception:
                        pass
                self.profiler.finish_task(task_id, terminal_status)
                if terminal_status == "completed":
                    await self._maybe_auto_wiki_ingest_after_finalize(
                        task_id,
                        terminal_status,
                    )
                    await self._maybe_offer_wiki_ingest(task_id, self.default_project_id)
                return self._interactive_run_result(
                    task_id,
                    terminal_status,
                    snapshot,
                )

            payload = snapshot.tasks[0].interrupts[0].value
            user_response = ""

            if isinstance(payload, dict) and payload.get("type") == "code_review":
                risk_info = payload.get("risk", {})
                risk = risk_info.get("level") or risk_info.get("risk_level") or "MEDIUM"
                print(f"\n{Fore.YELLOW}⚠️  CODE REVIEW  |  Risk: {risk}{Style.RESET_ALL}")
                wait_started = time.perf_counter()
                wait_started_at = timestamp_now()
                output.page_text("Code Review", payload.get("content", ""), Fore.CYAN)
                try:
                    user_response = await self._aprompt_user(
                        task_id,
                        "code_review",
                        f"{Fore.YELLOW}[y/Enter=run, n=reject, q=quit, e:<code>=edit, text=feedback] > {Style.RESET_ALL}",
                        payload=payload,
                        started_at=wait_started_at,
                    )
                except HumanInputUnavailable as exc:
                    self._record_human_wait(
                        task_id,
                        "code_review",
                        wait_started,
                        f"<waiting_user:{type(exc).__name__}>",
                        payload,
                        started_at=wait_started_at,
                    )
                    return self._interactive_run_result(
                        task_id,
                        "waiting_user",
                        snapshot,
                    )
                self._record_human_wait(
                    task_id,
                    "code_review",
                    wait_started,
                    user_response,
                    payload,
                    started_at=wait_started_at,
                )

            elif isinstance(payload, dict) and payload.get("type") == "env_selection":
                tool = payload.get("tool_name")
                dflt = payload.get("default_env")
                reason = payload.get("reason", "")
                print(f"\n{Fore.CYAN}🔧 Install '{tool}' → env [{dflt}]?{Style.RESET_ALL}")
                if reason:
                    print(f"{Fore.CYAN}{reason}{Style.RESET_ALL}")
                wait_started = time.perf_counter()
                wait_started_at = timestamp_now()
                try:
                    user_response = await self._aprompt_user(
                        task_id,
                        "env_selection",
                        f"Target env (Enter={dflt}) > ",
                        payload=payload,
                        started_at=wait_started_at,
                    )
                except HumanInputUnavailable as exc:
                    self._record_human_wait(
                        task_id,
                        "env_selection",
                        wait_started,
                        f"<waiting_user:{type(exc).__name__}>",
                        payload,
                        started_at=wait_started_at,
                    )
                    return self._interactive_run_result(
                        task_id,
                        "waiting_user",
                        snapshot,
                    )
                raw_response = user_response
                if not user_response.strip():
                    user_response = dflt
                self._record_human_wait(
                    task_id,
                    "env_selection",
                    wait_started,
                    raw_response,
                    payload,
                    started_at=wait_started_at,
                )

            elif isinstance(payload, dict) and payload.get("type") in {"consultant_question", "generate_question"}:
                wait_started = time.perf_counter()
                wait_started_at = timestamp_now()
                prompt_type = payload.get("type", "human_question")
                try:
                    user_response = await self._aprompt_user(
                        task_id,
                        prompt_type,
                        f"{Fore.YELLOW}Response (q=quit) > {Style.RESET_ALL}",
                        payload=payload,
                        started_at=wait_started_at,
                    )
                except HumanInputUnavailable as exc:
                    self._record_human_wait(
                        task_id,
                        prompt_type,
                        wait_started,
                        f"<waiting_user:{type(exc).__name__}>",
                        payload,
                        started_at=wait_started_at,
                    )
                    return self._interactive_run_result(
                        task_id,
                        "waiting_user",
                        snapshot,
                    )
                self._record_human_wait(
                    task_id,
                    prompt_type,
                    wait_started,
                    user_response,
                    payload,
                    started_at=wait_started_at,
                )

            else:
                wait_started = time.perf_counter()
                wait_started_at = timestamp_now()
                generic_payload = payload if isinstance(payload, dict) else {"content": payload}
                try:
                    user_response = await self._aprompt_user(
                        task_id,
                        "interrupt",
                        f"{Fore.YELLOW}Response (q=quit) > {Style.RESET_ALL}",
                        payload=generic_payload,
                        started_at=wait_started_at,
                    )
                except HumanInputUnavailable as exc:
                    self._record_human_wait(
                        task_id,
                        "interrupt",
                        wait_started,
                        f"<waiting_user:{type(exc).__name__}>",
                        generic_payload,
                        started_at=wait_started_at,
                    )
                    return self._interactive_run_result(
                        task_id,
                        "waiting_user",
                        snapshot,
                    )
                self._record_human_wait(
                    task_id,
                    "interrupt",
                    wait_started,
                    user_response,
                    generic_payload,
                    started_at=wait_started_at,
                )

            if user_response.strip().lower() in ["q", "quit", "exit"]:
                self.profiler.finish_task(task_id, "cancelled")
                return self._interactive_run_result(
                    task_id,
                    "cancelled",
                    snapshot,
                )
            next_input = Command(resume=user_response)

    # ────────────────────────────────────────────────────────────
    #  交互模式
    # ────────────────────────────────────────────────────────────

    async def interactive_mode(self):
        print(f"""
{Fore.CYAN}╔══════════════════════════════════════════════════╗
║  🧬  BioAnalyst V4  |  Interactive Mode          ║
╚══════════════════════════════════════════════════╝{Style.RESET_ALL}
Commands:
  /tasks              List recent tasks
  /new [name]         New session
  /resume <id>        Resume task
  /memory             Show memory status
  /memory search <q>  Search SessionArchive events
  /memory lint        Check Core memory and optional curated-claim conflicts
  /memory promote     Promote safe wiki index refs into Core project memory
  /wiki               Show wiki disabled/enabled status
  /wiki search <q>    Search wiki memory when BIOMIND_WIKI_ENABLED=true
  /wiki ingest        Curate events only when BIOMIND_WIKI_ENABLED=true
  /wiki ingest task   Curate current task only when BIOMIND_WIKI_ENABLED=true
  /wiki compile       Rebuild wiki digest only when BIOMIND_WIKI_ENABLED=true
  /wiki lint          Check wiki links only when BIOMIND_WIKI_ENABLED=true
  /wiki page <id>     Show a wiki page only when BIOMIND_WIKI_ENABLED=true
  /wiki review        Show pending wiki review items only when enabled
  /task summarize [id] Render a task summary report from archive evidence
  /paste              Enter multiline task input; finish with /end
  /cot <id>           Open CoT log for task
  /stop               Cancel current task
  /debug              Inspect graph state
  /exit               Quit
  ![cmd]              Run shell command directly
""")
        current_session_id = f"session_{int(time.time())}"
        current_session_is_new = True
        print(f"{Fore.GREEN}● Session: {current_session_id}{Style.RESET_ALL}")

        DIRECT_CMDS = ['ls', 'll', 'la', 'pwd', 'whoami', 'date', 'head', 'tail',
                       'cat', 'mkdir', 'touch', 'which', 'df', 'free']

        while True:
            try:
                cwd_name  = os.path.basename(os.getcwd()) or "/"
                try:
                    user_input = await self._aprompt_user(
                        current_session_id,
                        "interactive_prompt",
                        f"\n{Fore.CYAN}[{current_session_id[:20]}]{Fore.WHITE} {cwd_name}> {Style.RESET_ALL}",
                        payload={"cwd": os.getcwd()},
                    )
                except HumanInputUnavailable:
                    continue
                user_input = user_input.strip()
                if not user_input:
                    continue

                if user_input.lower() in {"继续", "继续执行", "continue", "resume"}:
                    control = self._continue_control_state(current_session_id)
                    if control.get("action") != "new_task":
                        if control.get("action") == "waiting_user":
                            waiting = control.get("waiting") or {}
                            output.page_text(
                                f"Waiting State | {current_session_id}",
                                (
                                    "任务仍在等待具体输入；“继续”不能替代该回答。\n\n"
                                    f"Stage: {waiting.get('stage', '')}\n"
                                    f"Prompt: {waiting.get('prompt', '')}\n"
                                    f"Payload: {json.dumps(waiting.get('payload') or {}, ensure_ascii=False)}"
                                ),
                                Fore.YELLOW,
                            )
                            continue
                        if control.get("action") == "completed":
                            print(f"{Fore.GREEN}✓ Task {current_session_id} is already complete; nothing was rerun.{Style.RESET_ALL}")
                            continue
                        logger.info(
                            "Plain continue resolved as control event: %s",
                            json.dumps(control.get("resume_audit") or {}, ensure_ascii=False, sort_keys=True),
                        )
                        run_result = await self._run_agent_interrupt_loop(
                            "",
                            current_session_id,
                            resume_initial=True,
                        )
                        output.render_terminal_result(run_result)
                        current_session_is_new = False
                        continue

                # ── 系统命令 ─────────────────────────────────
                if user_input.strip().lower() in {"/exit", "/quit", "q", "quit", "exit"}:
                    break

                if user_input == "/paste":
                    try:
                        user_input = await self._aprompt_user(
                            current_session_id,
                            "interactive_prompt",
                            f"{Fore.CYAN}Paste task content. Finish with /end on its own line.{Style.RESET_ALL}\n... ",
                            payload={"cwd": os.getcwd(), "mode": "multiline"},
                            multiline=True,
                        )
                    except HumanInputUnavailable:
                        continue
                    user_input = user_input.strip()
                    if not user_input:
                        continue

                if user_input.startswith("/memory search "):
                    query = user_input.split(" ", 2)[2].strip()
                    result = await self.task_summary_renderer.asearch(query, task_id=current_session_id)
                    output.page_text(f"Session Archive Search | {query}", result, Fore.CYAN)
                    continue

                if user_input == "/memory":
                    config = {"configurable": {"thread_id": current_session_id}}
                    snap   = self.app.get_state(config)
                    msgs   = snap.values.get("messages", []) if snap.values else []
                    self.memory_manager.print_status(msgs)
                    print(self.core_memory_store.status_text(self.default_project_id))
                    print(self.task_summary_renderer.status_text(current_session_id))
                    output.page_text(
                        "Task Summary",
                        self.task_summary_renderer.read_task_summary(current_session_id),
                        Fore.CYAN,
                    )
                    continue

                if user_input == "/memory lint":
                    wiki_lint = (
                        self.wiki_memory_manager.lint(project_id=self.default_project_id)
                        if self.wiki_enabled
                        else self._wiki_disabled_message()
                    )
                    wiki_claims = (
                        self.wiki_memory_manager.read_claims_index(self.default_project_id)
                        if self.wiki_enabled
                        else []
                    )
                    core_lint = self.core_memory_store.lint_project_memory(
                        self.default_project_id,
                        wiki_claims=wiki_claims,
                    )
                    output.page_text(
                        "Memory Lint",
                        f"{core_lint}\n\n{wiki_lint}",
                        Fore.CYAN,
                    )
                    continue

                if user_input == "/memory promote":
                    if not self.wiki_enabled:
                        output.page_text("Memory Promote", self._wiki_disabled_message(), Fore.CYAN)
                        continue
                    result = self.wiki_memory_manager.sync_project_index_fields(project_id=self.default_project_id)
                    output.page_text("Memory Promote", result, Fore.CYAN)
                    continue

                if user_input == "/wiki" or user_input.startswith("/wiki "):
                    if not self.wiki_enabled:
                        output.page_text("Wiki Disabled", self._wiki_disabled_message(), Fore.CYAN)
                        continue

                if user_input.startswith("/wiki search "):
                    query = user_input.split(" ", 2)[2].strip()
                    hits = self.wiki_memory_manager.search(
                        query,
                        project_id=self.default_project_id,
                    )
                    result = self.wiki_memory_manager.format_hits(hits, title=f"Wiki Search | {query}")
                    output.page_text(f"Wiki Search | {query}", result, Fore.CYAN)
                    continue

                if user_input in {"/wiki ingest", "/wiki ingest task"}:
                    if not current_session_id:
                        output.page_text(
                            "Wiki Ingest",
                            "Wiki ingest denied: no snapshot-bound current task.",
                            Fore.YELLOW,
                        )
                        continue
                    if user_input == "/wiki ingest":
                        output.page_text(
                            "Wiki Ingest",
                            "Project-wide blind ingestion is disabled. Use /wiki ingest task so every event is bound to one completed task snapshot.",
                            Fore.YELLOW,
                        )
                        continue
                    try:
                        succeeded, result = await self._ingest_wiki_task_with_gate(
                            current_session_id,
                            project_id=self.default_project_id,
                        )
                    except Exception as exc:
                        succeeded, result = False, (
                            f"Wiki ingest failed after durable dispatch: {type(exc).__name__}: {exc}"
                        )
                    output.page_text(
                        "Wiki Ingest",
                        result,
                        Fore.CYAN if succeeded else Fore.YELLOW,
                    )
                    continue

                if user_input == "/wiki compile":
                    result = self.wiki_memory_manager.compile_digest(project_id=self.default_project_id)
                    output.page_text("Wiki Compile", result, Fore.CYAN)
                    continue

                if user_input == "/wiki lint":
                    result = self.wiki_memory_manager.lint(project_id=self.default_project_id)
                    output.page_text("Wiki Lint", result, Fore.CYAN)
                    continue

                if user_input.startswith("/wiki page "):
                    identifier = user_input.split(" ", 2)[2].strip()
                    result = self.wiki_memory_manager.read_page(identifier)
                    output.page_text(f"Wiki Page | {identifier}", result, Fore.CYAN)
                    continue

                if user_input == "/wiki review":
                    result = self.wiki_memory_manager.read_review_queue()
                    output.page_text("Wiki Review Queue", result, Fore.CYAN)
                    continue

                if user_input == "/wiki":
                    print(self.wiki_memory_manager.status_text(self.default_project_id))
                    output.page_text(
                        "Wiki Overview",
                        self.wiki_memory_manager.overview_file.read_text(encoding="utf-8"),
                        Fore.CYAN,
                    )
                    continue

                if user_input == "/task summarize" or user_input.startswith("/task summarize "):
                    parts = user_input.split(" ", 2)
                    target_task_id = parts[2].strip() if len(parts) > 2 and parts[2].strip() else current_session_id
                    path = self.task_summary_renderer.write_task_summary(target_task_id)
                    output.page_text(
                        f"Task Summary | {target_task_id}",
                        path.read_text(encoding="utf-8"),
                        Fore.CYAN,
                    )
                    continue

                if user_input.startswith("/cot "):
                    tid  = user_input.split(" ", 1)[1].strip()
                    path = Path(self.data_path) / "task_outputs" / tid / f"cot_{tid}.md"
                    if path.exists():
                        import subprocess
                        subprocess.run(["less", str(path)])
                    else:
                        print(f"{Fore.RED}CoT log not found: {path}{Style.RESET_ALL}")
                    continue

                if user_input.startswith("/new"):
                    if self.state_manager:
                        self.state_manager.update_task_status(current_session_id, "suspended")
                    self.profiler.finish_task(current_session_id, "suspended")
                    await self._finalize_task_memory(
                        current_session_id,
                        "interrupted",
                        payload={"reason": "User started a new session."},
                    )
                    parts = user_input.split(" ", 1)
                    name  = re.sub(r"[^a-zA-Z0-9_-]", "", parts[1]) if len(parts) > 1 else ""
                    current_session_id = f"{name}_{int(time.time())}" if name else f"session_{int(time.time())}"
                    current_session_is_new = True
                    output.reset_for_task()
                    print(f"{Fore.GREEN}● New session: {current_session_id}{Style.RESET_ALL}")
                    continue

                if user_input == "/stop":
                    if self.state_manager:
                        self.state_manager.update_task_status(current_session_id, "cancelled")
                    self.profiler.finish_task(current_session_id, "cancelled")
                    await self._finalize_task_memory(
                        current_session_id,
                        "cancelled",
                        payload={"reason": "User stopped the current task."},
                    )
                    try:
                        stop_snapshot = self.app.get_state(
                            {"configurable": {"thread_id": current_session_id}}
                        )
                    except Exception:
                        stop_snapshot = None
                    output.render_terminal_result(
                        self._interactive_run_result(
                            current_session_id,
                            "cancelled",
                            stop_snapshot,
                        )
                    )
                    current_session_id = f"session_{int(time.time())}"
                    current_session_is_new = True
                    output.reset_for_task()
                    print(f"{Fore.GREEN}● New session: {current_session_id}{Style.RESET_ALL}")
                    continue

                if user_input == "/tasks":
                    if self.state_manager:
                        tasks = self.state_manager.list_tasks(limit=15)
                        print(f"\n{'Task ID':<32} | {'Status':<10} | {'Updated'}")
                        print("─" * 68)
                        for t in tasks:
                            print(f"{t['task_id']:<32} | {t['status']:<10} | {t['updated_at']}")
                    continue

                if user_input.startswith("/resume "):
                    tid = user_input.split(" ", 1)[1].strip()
                    current_session_id = tid
                    current_session_is_new = False
                    waiting = load_waiting_state(self.data_path, tid)
                    if waiting:
                        output.page_text(
                            f"Waiting State | {tid}",
                            json.dumps(waiting, ensure_ascii=False, indent=2),
                            Fore.CYAN,
                        )
                    config = {"configurable": {"thread_id": tid}}
                    snapshot = self.app.get_state(config)
                    if snapshot.tasks and snapshot.tasks[0].interrupts:
                        payload = snapshot.tasks[0].interrupts[0].value
                        output.page_text(
                            f"Pending Interrupt | {tid}",
                            json.dumps(payload, ensure_ascii=False, indent=2)
                            if isinstance(payload, dict)
                            else str(payload),
                            Fore.CYAN,
                        )
                        wait_started = time.perf_counter()
                        wait_started_at = timestamp_now()
                        try:
                            user_response = await self._aprompt_user(
                                tid,
                                "resume_interrupt",
                                f"{Fore.YELLOW}Resume response (q=quit) > {Style.RESET_ALL}",
                                payload=payload if isinstance(payload, dict) else {"content": payload},
                                started_at=wait_started_at,
                            )
                        except HumanInputUnavailable:
                            continue
                        self._record_human_wait(
                            tid,
                            "resume_interrupt",
                            wait_started,
                            user_response,
                            payload if isinstance(payload, dict) else {"content": payload},
                            started_at=wait_started_at,
                        )
                        if user_response.strip().lower() in ["q", "quit", "exit"]:
                            self.profiler.finish_task(tid, "cancelled")
                            continue
                        run_result = await self._run_agent_interrupt_loop(
                            Command(resume=user_response),
                            tid,
                        )
                    else:
                        run_result = await self._run_agent_interrupt_loop(
                            "",
                            tid,
                            resume_initial=True,
                        )
                    output.render_terminal_result(run_result)
                    continue

                if user_input == "/debug":
                    config   = {"configurable": {"thread_id": current_session_id}}
                    snapshot = self.app.get_state(config)
                    print(f"Next nodes: {snapshot.next}")
                    if snapshot.tasks and snapshot.tasks[0].interrupts:
                        print(f"Interrupt payload: {snapshot.tasks[0].interrupts[0].value}")
                    continue

                # ── Shell 直通 ────────────────────────────────
                if user_input.startswith("cd "):
                    try:
                        os.chdir(user_input[3:].strip())
                        if self.pm: self.pm.work_dir = Path(os.getcwd())
                        print(f"📂 {os.getcwd()}")
                    except Exception as e:
                        print(f"❌ {e}")
                    continue

                cmd_parts = user_input.split()
                base_cmd  = cmd_parts[0] if cmd_parts else ""
                is_direct = (user_input.startswith("!") or
                             (base_cmd in DIRECT_CMDS and len(user_input) < 60))

                if is_direct:
                    real_cmd = user_input[1:] if user_input.startswith("!") else user_input
                    if base_cmd == "ll":
                        real_cmd = "ls -lh " + " ".join(cmd_parts[1:])
                    import subprocess
                    subprocess.run(real_cmd, shell=True, executable="/bin/bash")
                    continue

                # ── Agent 处理（含中断循环）────────────────────
                next_input = user_input
                if self._should_auto_rename_session(
                    current_session_id,
                    authoritative_new_task=current_session_is_new,
                ):
                    suggested_session_id = self._auto_task_id_for_prompt(next_input, fallback_prefix="session")
                    if suggested_session_id:
                        current_session_id = suggested_session_id
                        print(f"{Fore.GREEN}● Task title: {current_session_id}{Style.RESET_ALL}")
                run_result = await self._run_agent_interrupt_loop(
                    next_input,
                    current_session_id,
                )
                output.render_terminal_result(run_result)
                current_session_is_new = False

            except KeyboardInterrupt:
                restore_terminal_state()
                if self.state_manager:
                    self.state_manager.update_task_status(current_session_id, "interrupted")
                self.profiler.finish_task(current_session_id, "interrupted")
                try:
                    interrupted_snapshot = self.app.get_state(
                        {"configurable": {"thread_id": current_session_id}}
                    )
                except Exception:
                    interrupted_snapshot = None
                output.render_terminal_result(
                    self._interactive_run_result(
                        current_session_id,
                        "interrupted",
                        interrupted_snapshot,
                    )
                )
                break
            except Exception:
                import traceback
                traceback.print_exc()


# ════════════════════════════════════════════════════════════════
#  启动入口
# ════════════════════════════════════════════════════════════════

def restore_terminal():
    try:
        restore_terminal_state()
    except Exception:
        pass
    print("\n👋 Terminal restored.")


def _handle_suspend(signum, frame):
    """Suspend promptly; restore the TTY after the process is foregrounded again."""
    signal.signal(signal.SIGTSTP, signal.SIG_DFL)
    os.kill(os.getpid(), signal.SIGTSTP)
    signal.signal(signal.SIGTSTP, _handle_suspend)
    restore_terminal_state()


def _handle_interrupt(signum, frame):
    """Make Ctrl-C cancel executor-owned child process groups before exit."""
    terminate_active_processes()
    raise KeyboardInterrupt


async def main():
    command   = sys.argv[1] if len(sys.argv) > 1 else "interactive"
    data_path = str(PathManager.WORK_DIR)

    print(f"""
{Fore.CYAN}╔═══════════════════════════════════════════════════════╗
║    🧬  BioAnalyst Agent V4  –  Production System    ║
╚═══════════════════════════════════════════════════════╝{Style.RESET_ALL}
""")

    agent = BioAnalystAgent(
        data_path=data_path,
        llm_model=LLM_DEFAULT_MODEL,
        model_provider="openai",
        max_memory_tokens=200_000,
        use_llm_supervisor=True,
    )

    try:
        if command == "interactive":
            if hasattr(agent, "interactive_mode"):
                await agent.interactive_mode()
        elif command == "demo":
            await agent.go("Explore the data in ./sample_data")
        else:
            print(f"Unknown command: {command}")
    finally:
        await agent.aclose()


if __name__ == "__main__":
    atexit.register(restore_terminal)
    try:
        signal.signal(signal.SIGINT, _handle_interrupt)
    except Exception:
        pass
    if hasattr(signal, "SIGTSTP"):
        try:
            signal.signal(signal.SIGTSTP, _handle_suspend)
        except Exception:
            pass
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("\n👋 Bye")
    except Exception:
        import traceback
        traceback.print_exc()
